#!/bin/bash
# coding-harness install.sh 테스트 스위트
# 각 케이스를 독립 임시 디렉토리에서 실행한다. 진입부에서 HOME 자체를 전역 샌드박스로
# 미리 치환해 실제 ~/.claude 를 보호하고, 실제 HOME 이 필요한 --scope user 호출만 개별
# HOME= 으로 다시 지정한다(§전역 HOME 샌드박스 참고).

set -euo pipefail

# 레포 루트 (이 스크립트의 부모 디렉토리)
REPO_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
INSTALL_SCRIPT="$REPO_ROOT/install.sh"

# 전역 HOME 샌드박스(결함 HIGH-3, 2회차 검수). --scope project 호출 다수는 대상이 $PWD 라
# 원래 HOME= 치환이 필요 없지만, install.sh 가 그 전제(resolve_target_paths 의 조건부
# 대입 한 줄)를 잃으면 그 다수가 그대로 실제 $HOME 을 향한다 — 직전 검수에서 실제로 그렇게
# 됐다. 호출부 39곳을 개별로 고치는 대신 진입부에서 HOME 을 격리해, 그 한 줄이 무너져도
# 실제 $HOME 은 애초에 후보에 들지 않게 만든다(fail-safe). --scope user 호출은 이미 전부
# 자기 몫의 HOME= 을 지정하므로(예: `HOME="$sandbox" "$INSTALL_SCRIPT" --scope user`) 이
# 전역값을 그 호출 하나에 한해 덮어쓸 뿐 그대로 안전하다 — bash 의 `VAR=v cmd` 형태는 그
# 명령 실행 동안만 값을 바꾸고 이후 복귀한다. CODING_HARNESS_TEST_HOME 은 검증 전용 주입구다
# (REMOVALS_FILE 의 CODING_HARNESS_REMOVALS_FILE 과 같은 성격) — 일반 실행은 매번 새
# mktemp 디렉토리를 쓴다. 실제 HOME 이 필요한 테스트는 없다(실측 확인 — 전역 치환만으로
# 충분하다).
# 정리 대상 소유권 구분(G-1, 2회차 검수 Critical). CODING_HARNESS_TEST_HOME 을 호출자가
# 지정했으면 그 경로는 호출자 소유이므로 스위트가 만들지도, 끝에 지우지도 않는다 —
# 절대 경로·존재 여부 같은 검증 목록이 아니라 "누가 만들었는가"로 rm -rf 범위를 좁힌다.
# 우리가 mktemp -d 로 새로 만든 경우에만 SANDBOX_IS_OURS=1 을 세워 정리 대상임을 표시한다.
if [[ -n "${CODING_HARNESS_TEST_HOME:-}" ]]; then
  GLOBAL_HOME_SANDBOX="$CODING_HARNESS_TEST_HOME"
  SANDBOX_IS_OURS=0
else
  GLOBAL_HOME_SANDBOX="$(mktemp -d)"
  SANDBOX_IS_OURS=1
fi
export HOME="$GLOBAL_HOME_SANDBOX"

# cleanup_registered_paths 가 삭제 직전에 대피할 중립 디렉토리(정리가 자기 작업
# 디렉토리를 지우던 결함의 수정).
# CLEANUP_PATHS 에는 여러 그룹이 등록한 경로가 함께 쌓이고 삭제도 배열 전체 단위라(그
# 경위는 cleanup_registered_paths·finish_group 주석 참고), 프로세스가 지금 그중 하나
# 안에 서 있는 채로 그 배열이 지워지면 자기 cwd 를 스스로 지우는 꼴이 된다. 이 전용
# 디렉토리로 대피하는 이유: (i) register_cleanup_path 호출 대상이 아니라 CLEANUP_PATHS
# 에 섞일 수 없고, (ii) 스위트 시작(여기)부터 끝(아래 suite_exit_guard)까지 존재가
# 보장되며, (iii) 아무 테스트도 안에 쓰지 않는 빈 디렉토리라 상대 경로 단언이 우연히
# 성립해 테스트를 오염시키지 않는다. 레포 루트로 대피하지 않는 이유는
# cleanup_registered_paths 주석에 적는다.
CLEANUP_NEUTRAL_CWD="$(mktemp -d)"

# 파싱 완주 센티널(§18 이관 2 의 근본 수정). bash 는 스크립트를 증분 파싱하므로 아래
# 트랩 설치가 끝난 뒤에 나오는 문법 오류는 "트랩이 걸린 채로" 스크립트를 죽인다 — 그때
# 트랩이 보는 $? 는 0 이고 TEST_EXECUTION_STARTED 도 0 이라 요약 미출력 분기가 발화하지
# 않아, `bash -n tests/run.sh` 가 exit 2 를 내는 파일이 `bash tests/run.sh --only T29` 로는
# exit 0 이 됐다(HEAD 1d9472a 사본에서 `s/^SUMMARY_PRINTED=0/fi/` 로 재현). 이 플래그를 0
# 으로 두고 파일 마지막 `main "$@"` 직전에 1 로 세우면, 그 사이 어디서 파싱이 끊겨도 트랩이
# "완주하지 못했다"를 보고 비0 으로 강제한다.
#
# 두 형제 플래그(TEST_EXECUTION_STARTED·SUMMARY_PRINTED)와 달리 아래 "통계" 절이 아니라
# 여기서 선언하는 이유가 둘 있다:
#  (i) 상속된 환경변수로 가드가 잠드는 것을 막는다 — 이 `=0` 대입이 상속값을 덮는다.
#      선언이 없으면 바깥에서 SCRIPT_FULLY_PARSED=1 을 export 한 실행이 이 검출을 통째로
#      잃는다(문법 오류를 심은 사본에 export 해 재현 확인). 트랩이 ${SCRIPT_FULLY_PARSED:-0}
#      으로 참조하는 것은 두 형제와의 대칭일 뿐 이 플래그에는 하중이 없다 — 형제들은 트랩
#      설치보다 뒤(아래 "통계" 절)에서 선언돼 :-0 이 없으면 set -u 에 걸리지만, 이 선언은
#      트랩 설치(아래 `trap suite_exit_guard EXIT`)보다 **앞**이고 bash 는 스크립트를 위에서
#      아래로 증분 파싱하므로, 트랩이 미선언 상태를 보는 경로가 없다. 줄 번호를 적지 않는
#      이유: 이 절을 고치는 수정이 그 번호를 함께 밀어 인용이 곧 낡는다(실제로 겪었다).
#  (ii) 이 자리가 T36-3·T36-4·T36-10 의 조각 추출 범위 **안**이라 조각도 0 으로 초기화된다.
#      조각은 파일의 일부만 떼어 돌리므로 구조적으로 센티널이 설 수 없어 명시적 옵트인
#      (조각 끝에 SCRIPT_FULLY_PARSED=1 을 덧붙이는 줄)이 필요하고, 그 옵트인이 실제로
#      load-bearing 이려면 조각 안의 초기값이 0 이어야 한다. 옵트인을 빠뜨린 조각 프로브는
#      T36-12 가 잡는다.
# 이 줄을 suite_exit_guard 정의 바로 위가 아니라 그 doc-comment 블록 위에 두는 이유:
# T37-13 의 한계 표기 검사는 `함수명() {` 줄 **직전**의 연속 주석 줄만 doc 블록으로 모으므로
# (extract_preceding_comment_block), 정의와 주석 사이에 코드 한 줄이 끼면 그 블록이 빈 값이
# 되어 이 트랩을 앵커로 쓰는 원장 행이 앵커 실패로 보고된다(실측).
SCRIPT_FULLY_PARSED=0

# 요약 미출력 검출(tests-hardening PRP §4.2 항목4, A8·K1). TEST_EXECUTION_STARTED 가
# 서고(그룹 실행 시작) SUMMARY_PRINTED 가 서지 않은 채(print_test_summary 미도달) 스크립트가
# 끝나면 "[ERROR] 스위트가 요약 전에 종료됨" 을 찍는다. 그 시점의 $?(exit_code)가 아래 quirk
# 로 0 이어도 이 분기 안에서 exit_code=1 로 다시 세워 항상 비0으로 종료한다(G-2, 2회차 검수
# Major — 검출하고도 exit 0 을 내보내던 결함의 수정). 두 플래그는 아래 "통계" 절에서
# 선언하지만 이 트랩은 그보다 먼저 설치되므로 ${VAR:-0} 기본값으로 참조한다 — bash 3.2 의
# set -u 는 스칼라 ${VAR:-기본값} 은 안전하게 통과시키지만 배열은 선언 후 비어 있어도
# ${arr[@]} 참조 자체가 unbound 오류다(실측 확인, 아래 register_and_run_tests·
# print_test_summary 에서 배열을 다룰 때도 이 제약을 따른다). 이 함수를 트랩 설치보다 먼저
# 정의하는 이유: 트랩은 발화 시점에 함수 이름을 찾으므로, 스크립트가 이 지점 이전에 죽으면
# 아직 정의되지 않은 이름을 부르게 된다 — 그래서 log_error 등 뒤에 정의되는 헬퍼에 의존하지
# 않고 이 함수를 완전히 자기완결로 둔다.
#
# 이 트랩의 발화는 한때 실행 모드에 따라 갈렸다 — bash 는 같은 시그널(EXIT)에 트랩을 여러
# 번 걸면 마지막 설치만 발화시키는데, 예전에는 이 파일 안 테스트 함수 다수가 각자 자기
# 샌드박스를 지우는 EXIT 트랩을 새로 걸어, 그중 스위트 실행 순서상 가장 나중에 설치된
# 그룹의 트랩만 실제로 남고 이 전역 트랩은(그리고 그 전에 설치된 다른 그룹들의 트랩도) 덮여
# 사라졌다. S2(tests-hardening PRP §4.3)가 그 함수별 trap EXIT 설치를 전부
# register_cleanup_path 로 교체해 이 전제 자체가 사라졌다 — 통상적인 방식으로 trap 을
# 다시 거는 코드가 이 파일 안에 없는 한, 실행 모드(전체 실행·--only·--list·인자 오류로
# 인한 조기 exit)와 무관하게 이 트랩만 발화한다. "통상적인 방식"의 경계와 우회 가능한
# 형태는 아래 verify_trap_hygiene 주석에 적는다 — 여기서 되풀이하지 않는다.
#
# 이 결함(요약 전 종료가 exit 0 으로 새는 것)은 --only T28 로 T28 함수 본문에 unbound
# 변수를 주입해 직접 재현했다: 위 로그 문구가 찍히고, 수정 전에는 종료 코드가 0 으로
# 샜지만 수정 후에는 exit_code=1 로 종료한다(아래 T36-4·T36-5 가 이 경로를 고정한다).
#
# 이 파일 자신의 trap 설치 개수(EXIT 1곳·RETURN 0곳이어야 한다)는 K3 검사
# (verify_trap_hygiene, main 참고)가 실행마다 강제한다 — 그 검사의 방식과 한계는 그
# 함수 자신의 주석에 적는다.
#
# 부수 한계: 위 exit_code 강제는 뒤이은 rm -rf 가 성공할 때만 최종 종료 코드에 반영된다 —
# rm 이 실패하면(비망라 예시: 읽기전용 잔여물, 읽기전용 마운트) set -e 가 이 함수를 그
# 자리에서 끊어 exit "$exit_code" 에 도달하지 못하고 최종 종료 코드가 rm 의 실패 코드로
# 바뀐다. 이 트랩 자체는 그 경로를 막지 않는다.
suite_exit_guard() {
  local exit_code=$?
  # 파싱 완주 검사(위 SCRIPT_FULLY_PARSED 문단). 이 분기를 요약 미출력 분기보다 먼저 두는
  # 이유: 파싱이 끊겼다는 사실이 더 상류의 원인이고, 그 상태에서는 두 형제 플래그가 애초에
  # 선언되지 않았을 수도 있어 진단이 그쪽으로 새면 오히려 원인을 감춘다.
  if [[ "${SCRIPT_FULLY_PARSED:-0}" -ne 1 ]]; then
    echo "[ERROR] 스크립트 파싱이 완주하지 못함(원래 종료 코드 $exit_code → 이 트랩이 exit 1 로 강제) — 원인 후보 셋: (1) 문법 오류(bash -n tests/run.sh 로 위치 확인), (2) 최상위 코드가 set -e 로 중간에 끊김(이때 bash -n 은 통과하므로 마지막 로그 줄을 보라), (3) 조각 프로브에서 SCRIPT_FULLY_PARSED=1 옵트인이 빠졌다"
    exit_code=1
  fi
  if [[ "${TEST_EXECUTION_STARTED:-0}" -eq 1 && "${SUMMARY_PRINTED:-0}" -ne 1 ]]; then
    echo "[ERROR] 스위트가 요약 전에 종료됨(원래 종료 코드 $exit_code → 이 트랩이 exit 1 로 강제) — 마지막으로 실행된 그룹의 로그를 확인하라"
    exit_code=1
  fi
  if ((SANDBOX_IS_OURS)); then
    rm -rf -- "$GLOBAL_HOME_SANDBOX"
  fi
  # 그룹이 finish_group 을 거치지 못하고 조기 return 한 경우를 위한 fail-safe(S2). 이
  # 시점에 CLEANUP_PATHS 에 아직 남아 있는 경로가 있다면(등록은 됐지만 명시 호출로
  # 정리되지 못했거나, rm -rf 가 실패해 다시 등록된 채로 남은 것) 여기서 마저 정리한다 —
  # cleanup_registered_paths 는 빈 배열이면 곧바로 반환하므로 정상 종료 경로에서는 대개
  # 지울 것이 없다. declare -F 로 먼저 존재를 확인하는 이유(재현된 실측): 이 함수는
  # register_cleanup_path·CLEANUP_PATHS 와 함께 트랩 설치보다 뒤에 정의된다(위 "이
  # 함수를 트랩 설치보다 먼저 정의하는 이유" 문단이 이미 self-contained 원칙을 적어
  # 뒀다) — T36-3·T36-4 가 "set -euo pipefail 줄부터 trap suite_exit_guard EXIT 줄까지"만
  # 그대로 추출해 별도 프로세스로 돌리는 조각에는 그 뒤에 있는 이 정의가 없어, 그 조각
  # 안에서 suite_exit_guard 가 발화하면 "cleanup_registered_paths: command not found"로
  # 죽는다 — set -e 가 걸린 채로(이 트랩은 || true 로 감싸인 호출 트리 밖에서 발화하므로
  # 진짜로 걸려 있다) 그 실패가 이 함수를 그 자리에서 끊어 뒤따르는 CLEANUP_NEUTRAL_CWD
  # 정리(아래)까지 못 미치고, 그 조각이 자기 몫으로 만든 CLEANUP_NEUTRAL_CWD 가 새 채로
  # 남는다(재현 확인). declare -F 가드는 실제 전체 실행에서도 유효하다 — 위의
  # SANDBOX_IS_OURS 분기가 log_error 대신 echo 를 쓰는 것과 같은 이유로, 스크립트가
  # 이 함수 정의 이전에 죽는 경우 전반에 대한 방어다.
  #
  # 정직하게 남긴다 — 이 가드 자체를 전용으로 시험하는 안전망은 없다. cleanup_registered_paths
  # 정의를 통째로 지우면 전체 실행은 exit 1 로 걸리지만(재현 확인), 잡아내는 것은 이
  # 가드가 아니라 T36-6 이 그 함수를 별도 목적(K4b 절반 검증)으로 직접 호출하는 부수
  # 효과다 — --only 로 T36 을 뺀 부분집합(예: --only T1,T2)에서는 이 결함이 exit 0·
  # 에러 0건으로 완전히 새어나간다(재현 확인). 지금 수용 가능한 이유: project CLAUDE.md
  # §4 의 정본 검증 명령은 인자 없는 전체 실행이라 T36 이 항상 포함되므로, 공식 커밋
  # 게이트는 이 시나리오를 놓치지 않는다.
  #
  # 위 「지우면 exit 1」청구는 cleanup_registered_paths **함수 자체**가 없어지는 경우
  # (함수 소실)를 뜻한다(PRP §17 이관 6). 실제로 재발했던 형태는 이와 달랐다 — 함수는
  # 남기고 이 트랩 안의 fail-close 검사 한 줄만 무력화하는 **가드 누락**이었다("정리
  # 실패가 종료 코드에 반영되지 않던 결함" 문단이 그 원래 형태다). 「정리하지 못한 경로가
  # 남으면 exit 1」검사에 한해서는 그 가드 누락 형태를 지금은 T36-10 이 전용으로 잡는다
  # (S3b 가 추가) — 나머지 두 fail-close 분기(파싱 완주·요약 미출력)에서 같은 형태의
  # 가드 누락이 잡히는지는 이 절이 확인하지 않는다.
  declare -F cleanup_registered_paths > /dev/null 2>&1 && cleanup_registered_paths
  # 정리 실패가 종료 코드에 반영되지 않던 결함(재현됨) — cleanup_registered_paths 는
  # rm -rf 가 실패하면 CLEANUP_PATHS 를 비우지 않고 log_error 만 남기는데(위 그 함수의
  # 주석 참고), suite_exit_guard 는 그 로그를 무시하고 그대로 exit 0 을 낼 수 있었다 —
  # 요약 미출력 검출(위 TEST_EXECUTION_STARTED 분기)과 같은 계열의 "검출은 됐는데 exit
  # 0" 구조라 같은 관용구로 닫는다: 정리 후에도 CLEANUP_PATHS 가 비지 않았으면 비0으로
  # 강제한다. 삭제 실패마다 나는 개별 [ERROR](chmod·rm -rf 실패 로그, 위 함수 참고)는
  # 억제하지 않는다 — 그중 어떤 경로가 실패했는지는 그 줄들에만 남으므로, 억제하면 원인
  # 추적이 어려워진다. declare -p 로 먼저 선언 여부를 보는 이유(재현된 실측 — 위
  # declare -F 항목과 같은 함정): CLEANUP_PATHS 도 트랩 설치보다 뒤(아래 "통계" 절)에서
  # 선언되므로, T36-3·T36-4 의 추출 조각처럼 그 지점 이전만 떼어 실행하는 문맥에서는
  # 아예 선언되지 않은 채로 여기 도달한다 — 그 상태로 ${#CLEANUP_PATHS[@]} 를 바로
  # 참조하면 "CLEANUP_PATHS: unbound variable" 로 죽어 뒤따르는 CLEANUP_NEUTRAL_CWD
  # 정리를 못 미친다(재현 확인). declare -p 실패는 && 왼쪽이라 set -e 를 트리거하지
  # 않는다(위 declare -F 항목과 동일한 성질, 실측).
  if declare -p CLEANUP_PATHS > /dev/null 2>&1 && ((${#CLEANUP_PATHS[@]} > 0)); then
    # 이 수는 "실패한 경로 수"가 아니라 그 시점의 배열 길이다(PRP §17 이관 5) — rm -rf 가
    # 실패하면 cleanup_registered_paths 가 배열 전체를 유지하므로(위 그 함수의 주석), 그중
    # 다수는 이번 rm -rf 로 이미 실제로 삭제됐을 수 있다. 어떤 경로가 실제로 실패했는지는
    # 이 숫자가 아니라 위 개별 [ERROR](chmod·rm -rf 실패 로그)에만 남는다.
    echo "[ERROR] 정리 시도 후에도 CLEANUP_PATHS 에 ${#CLEANUP_PATHS[@]}개 항목이 남음(rm -rf 실패 시 배열이 비워지지 않아 이 수는 배열 길이이지 실패한 경로 수가 아니다 — 개별 실패는 위 cleanup_registered_paths 의 rm -rf 로그를 보라) → 이 트랩이 exit 1 로 강제"
    exit_code=1
  fi
  # CLEANUP_NEUTRAL_CWD 는 CODING_HARNESS_TEST_HOME 지정 여부와 무관하게 이 스위트가 항상
  # 직접 mktemp 로 만든 것이라(호출자 소유가 아니다) SANDBOX_IS_OURS 게이트 없이 지운다.
  # cleanup_registered_paths 뒤에 지우는 이유: 그 함수가 삭제 직전 대피 지점으로 이
  # 디렉토리를 쓸 수 있으므로, 그 호출이 끝난 뒤에 지워야 대피가 항상 유효한 경로를
  # 가리킨다.
  rm -rf -- "$CLEANUP_NEUTRAL_CWD"
  exit "$exit_code"
}
trap suite_exit_guard EXIT

