# ID 접두 부재 래칫(tests-hardening PRP §4.4, K5 의 짝, T37-12 가 실행마다 검사). 아래
# collect_guard_ids 는 note_failure/record_failure 호출 중 줄 시작이 호출인 것만(주석
# 줄 제외) 보고, 그 중 여는 따옴표 바로 뒤에 "T[0-9]+-[0-9a-z]+ 가 있는 것만 ID 있음으로
# 센다(한 줄에 여러 개면 첫 것만). 이 상수는 그 규칙으로 ID 가 없다고 판정된 호출 수의
# 상한이다. 실측 분해(그룹별로 직접 센 값 — 착지 시점 호출 줄 총 958 중 111): T1~T20 계열
# 91 · T21 6 · T34 8 · T22 2 · T24 1 · T25 1 · T33 1 · T35 1. 섞여 있는 형태는 네 가지다:
#   (a) record_failure "$test_name" "<산문>" 으로 ID 를 아예 붙이지 않는 옛 관용구(대다수),
#   (b) T33·T34 의 "G1:"/"G2: 다른 접두 규약(9건 = T33 1 + T34 8),
#   (c) record_failure "$test_name" "$reason" 형태의 간접 래퍼(T35 1건),
#   (d) 여는 따옴표가 작은따옴표인 호출(T25 1건 — note_failure 'T25-37: …'). ID 가 있는데도
#       추출 규칙이 못 보는 형태라 이 분모가 대신 잡는다(collect_guard_ids 의 한계 절 참고).
# 내리는 것은 자유, 올리려면 이 줄을 고치는 커밋에 이유가 필요하다(T26 과 동형).
#
# 111 → 110 으로 내린 이유(S4-3 B4): 위 실측 분해는 **착지 시점의 핀된 기록**이고 그
# 시점 값은 111 이다. 이 회차가 기존 ID 없는 호출 하나(T3 의 멱등 위반 보고)에 T3-1
# 접두를 붙여 원장 앵커로 승격시켜 실측이 110 이 됐다 — 그 여유 1칸을 남겨 두면 다음
# 회차의 ID 없는 신규 호출 하나가 조용히 통과한다. 이 회차가 만든 여유이므로 회수한다.
#
# 106 → 103 으로 내린 이유(docs/prps/dashboard-into-hub.md M1 검수 1회차 F14, 2회차 N6 이
# 수치 정정): 이 fix round 착수 시점의 실측은 106 이다(위 (b) 의 "T34 8"·"111 → 110" 은
# 더 이른 체크포인트를 서술한 역사 기록이라 그대로 둔다 — dashboard-native-data-source
# PRP 의 T34 재작성이 그 이후 "G2:" 접두를 8건에서 4건으로 이미 줄여 놓았고, 그 4건이
# 이 fix round 착수 시점의 실측 106 에 반영돼 있다). 이번 회차가 그 G2 접두 4건을
# T34-3~T34-6 네 개의 원장 앵커 있는 ID 로 승격시켜 4건 모두 사라졌다(-4). 같은 작업
# 중 T22(위 "T22 2")가 3으로 +1 됐다(hub_dashboard_log.py/hub_dashboard_render.py 사전조건
# 분기가 파일 3종에서 나뉘며 ID 없는 산문 경고가 하나 늘었다 — 기존 관용구 (a)와 같은 형태,
# 이 fix round 이전부터 있던 값이라 그대로 둔다). 순증감: 106 − 4(T34) + 1(T22) = 103.
readonly NOTE_FAILURE_ID_LESS_RATCHET=103

# 실패 보고 호출 줄의 판정 정규식(설계 ledger-anchor-column §5-3 이 정의한 분모).
# 원장 5열 expect_token 의 판별자 자격 계수(count_token_hits_in_report_lines)와 8열
# anchor_function 의 교차검증(guard_token_is_inside_anchor)이 같은 분모를 써야 하므로
# 한 자리에 둔다 — 검수 2회차 MEDIUM(두 렌즈 공통): 두 함수가 이 리터럴을 각자 들고
# 있어, 다섯 번째 보고 함수를 더하는 수정이 한쪽만 고치면 두 검사가 서로 다른 분모를
# 보게 됐다. 그 형태는 검수 1회차 Major A(문면이 약속한 검사가 코드에 없었다)와 같은
# 계열이라 리터럴을 하나로 모았다.
#
# 함께 고쳐야 하는 자리 — tests/mutations.tsv 헤더 5열 항목이 같은 네 이름을 산문으로
# 열거한다. 기계가 그 일치를 대조하지 않으므로(assert_ledger_header_citation 은 숫자
# 인용만 본다) 이 상수를 고치는 커밋이 그 산문도 함께 고친다.
#
# 한계(비망라) — 줄 시작 앵커와 네 명령 이름에 결합돼 있다: 줄 중간에서 보고하는 호출,
# printf 로 보고하는 자리, 변수에 담아 뒤에서 찍는 형태는 이 분모에 들지 않는다(실재
# 예가 이 파일에 있고 지금은 등록된 변조행과 무관하다 — 검수 2회차 접지 렌즈 실측).
# 전수 증명이 아니다.
readonly FAILURE_REPORT_LINE_PATTERN='^[[:space:]]*(note_failure|record_failure|log_error|echo)[[:space:]]'

# 원장 전용 예약 그룹 번호(규약 전문은 tests/mutations.tsv 헤더). 특정 그룹 밖에 있는
# 가드(main 의 사전 점검 verify_trap_hygiene·verify_group_registry_parity ·
# print_test_summary 의 총합 계약)는 서브체크
# ID 가 없어 원장에서만 쓰는 식별자를 붙인다. 실재 그룹 번호를 빌려 쓰면 그 그룹이 나중에
# 같은 번호의 서브체크를 실제로 추가하는 순간 완비 검사(K5, 소스 − 원장 방향)가 그 새
# 서브체크를 "이미 등록됨"으로 오인하므로, 레지스트리에 없는 번호를 예약해 쓴다. 예약이
# 깨졌는지(이 번호가 실제 그룹이 됐는지)는 T37-11 이 실행마다 확인한다.
readonly RESERVED_LEDGER_ONLY_GROUP="T99"

# 이 하네스 자신의 그룹 번호. 판정 로직 세 곳(원장 파서의 자기 참조 거부 · 미러 실행의
# 방어적 재확인 · 서브체크 수 기대값 산출)이 같은 번호를 봐야 하는데, 구현 중 T36→T37 로
# 한 번 표류했다 — RESERVED_LEDGER_ONLY_GROUP 과 같은 이유로 상수로 묶는다.
# test_mutation_ledger_harness 의 `local test_name="T37"` 은 예외로 리터럴을 유지한다:
# verify_group_registry_parity 가 `declare -f` 텍스트에서 test_name="…" 값을 정규식으로
# 뽑아 그룹 ID 와 비교하므로, 변수로 바꾸면 뽑히는 값이 "$MUTATION_HARNESS_GROUP" 이라는
# 문자열이 되어 파리티가 항상 깨진다(실측 확인).
readonly MUTATION_HARNESS_GROUP="T37"

# 원장 변조행 수의 하한(T37-14 가 실행마다 검사). 원장에서 파생되지 않은 독립 상수여야
# 하는 이유: T37-13 과 전체 모드의 T37-15 가 하는 "검사 건수 == 변조행 수" 단언은 분모가 같은
# 원장에서 파생되므로(증분 모드의 T37-15 분모는 선택 행 수다), 변조행이 0행이 되면 `0 != 0` 으로
# 침묵한다(K6 층 전체가 공허해지는 자리).
# 이 상수가 그 분모의 바닥을 원장 밖에 못박는다. 올리는 것은 자유, 내리려면 이 줄을
# 고치는 커밋에 이유가 필요하다(T26 과 반대 방향의 같은 관용구).
#
# 4 → 8 로 올린 이유(S3b): 이 회차가 가드 4종에 K6 커버리지를 추가했다 — T28-4(중첩 한도
# 계약) · T31-6(인용 계약) · T36-8(조각 자식 종료 코드) · T36-10(정리 실패 시 종료 코드
