# 8 → 10 으로 올린 이유(S3b 검수 2회차): 면제 래칫 기제가 처음으로 발동한 자리다 — T36-0
# 의 분모가 6→7 로 개정되면서 면제 사유(「S3 이전에 존재한 가드 — 개정·수정 시 변조행으로
