# 완비 검사(K5) 실패 메시지에 예시로 실을 ID 개수. 두 방향 차집합은 추출이나 원장 한쪽이
# 통째로 고장나면 수백 건이 되므로(실측) 건수는 전부 보고하고 목록만 앞에서 자른다.
readonly GUARD_ID_LIST_PREVIEW_LIMIT=20

# 통계
total_tests=0
passed_tests=0
failed_tests=0
failed_list=()
untallied_groups=()      # 집계에 도달하지 못한 그룹 ID (항목3, register_and_run_tests 가 채운다)
SUMMARY_PRINTED=0        # print_test_summary 가 끝까지 출력하면 1 (항목4)
TEST_EXECUTION_STARTED=0 # register_and_run_tests 호출 직전 1 (항목4 — 인자 파싱 단계의
                         # 정상 종료(--list 등)를 "요약 미출력"으로 오탐하지 않기 위한 게이트)
SELECTED_GROUPS=()       # parse_suite_arguments 가 채우는 실행 대상 그룹 목록 (항목5)
CLEANUP_PATHS=()         # register_cleanup_path 가 채우고 cleanup_registered_paths 가 비우는
                         # 그룹별 정리 대상 경로(S2, tests-hardening PRP §4.3)
# 사전 점검 3종의 완료 표시(PRP §20-8 신규 3). 각 verify_* 가 자기 검사를 통과하고 반환하는
# 마지막 줄에서 1 로 세우고, verify_prechecks_completed_before_group_run 이 register_and_
# run_tests 시작 시점에 셋 다 확인한다 — 그 함수 주석에 기제와 한계를 적는다.
PRECHECK_REGISTRY_PARITY_DONE=0
PRECHECK_TRAP_HYGIENE_DONE=0
PRECHECK_LEDGER_HEADER_DONE=0

# 색상 코드
readonly GREEN='\033[0;32m'
readonly RED='\033[0;31m'
readonly YELLOW='\033[1;33m'
readonly NC='\033[0m'  # No Color

# ============================================================================
# 헬퍼 함수
# ============================================================================

log_test_name() {
  echo ""
  echo "======================================================================"
  echo "[$1] $2"
  echo "======================================================================"
}

log_info() {
  echo "[INFO] $*"
}

log_ok() {
  echo -e "${GREEN}[OK]${NC} $*"
}

log_error() {
  # stderr 로 쓴다(PRP §17 이관 4). T36-7 의 cd_evac_result=$(...) 처럼 2>&1 없이 stdout
  # 만 캡처하는 자리가 있으면, 이 함수가 stdout 에 쓸 때 그 출력이 캡처 변수에 섞여 판정
  # 토큰 어느 것과도 일치하지 않는 공허 통과를 만들 수 있었다(목으로 재현). log_info·
  # log_ok·log_warn 은 실패 진단이 아니라 성공/정보 로그라 이 함정의 대상이 아니므로 그대로
  # 둔다 — 옮기면 정상 실행 로그가 stderr 로 섞여 별도 근거 없이 출력 스트림 계약을 넓힌다.
  echo -e "${RED}[ERROR]${NC} $*" >&2
}

log_warn() {
  echo -e "${YELLOW}[WARN]${NC} $*"
}

# 테스트 실패 기록
record_failure() {
  local test_name="$1"
  local reason="$2"
  ((failed_tests++))
  failed_list+=("$test_name: $reason")
  log_error "$reason"
}

# 그룹 안에서 **서로 독립인** 서브체크의 실패를 모은다. 첫 실패에서 return 하면 그 뒤의
# 서브체크가 아예 실행되지 않아, "고치고 다시 돌리기"를 실패 건수만큼 반복해야 한다 —
# 실측: 무관한 회귀 2건(문서 문구 T25-5 · 색 대비 T25-110)을 동시에 주입하면 1건만
# 보고되고 나머지는 실패로 등장조차 하지 않는다. 여기서 얻는 완화는 **그룹 내부**에
# 한정된다 — 그룹끼리는 register_and_run_tests 가 `|| true` 로 부르므로 원래도 독립이다.
#
# **종속** 서브체크(파일 존재 검사, 값 추출 성공 여부처럼 뒤 검사의 전제가 되는 것)는
# 여전히 record_failure + `return 1` 을 쓴다. 전제가 깨진 뒤의 검사는 결과가 무의미하고,
# 빈 변수가 `[[ -ne ]]` 같은 비교에 들어가면 오류를 낸다.
group_failures=()

note_failure() {
  group_failures+=("$1")
  log_error "$1"
}

# 그룹별 정리 등록(S2, tests-hardening PRP §4.3). 트랩 대신 쓰는 관용구 — 각 테스트
# 함수는 mktemp 로 만든 자기 샌드박스 경로를 여기 등록만 하고, 실제 삭제는 아래
# cleanup_registered_paths 를 명시적으로 부르는 쪽(finish_group·suite_exit_guard)이
# 맡는다. 이유: bash 의 trap 은 같은 시그널(EXIT)에 여러 번 걸리면 마지막 설치만
# 발화하므로, 함수마다 자기 trap 을 새로 걸던 이전 방식은 이 함수보다 나중에 실행되는
# 다른 그룹이 그 trap 을 덮어쓰는 순간 이전 그룹의 정리가 통째로 사라졌다(누수의 원인).
# 등록은 그런 덮어쓰기가 없다 — 배열에 계속 쌓인다.
# 위생 가드(주제 1, S3a 검수 1회차 Critical): 등록 경로는 대개 mktemp 산출물이라 빈
# 문자열·`/`·$HOME·레포 루트가 들어올 정당한 경우가 없다. 예외는 T35 가 정리하는
# `$REPO_ROOT/commands/__pycache__` 한 자리다(비망라 — 레포 내부 경로를 정당하게 등록하는
# 호출부가 실재한다). 그래서 이 가드가 막는 것은 값 4개의 정확 문자열 대조뿐이고 하위
# 경로는 막지 않는다 — `$REPO_ROOT` 하위 전체를 거부하도록 조이면 그 예외의 정리가
# 조용히 사라진다.
# 막아야 하는 결함: mktemp 실패를 검사하지 않는 호출부가 있으면 빈 문자열이 흘러들고,
# 그것이 `dirname` 같은 변환을 거치면 `/` 로 증폭돼 cleanup_registered_paths 의
# `chmod -R 755` · `rm -rf` 인자가 된다(rm 은 BSD 가 `/` 를 막지만 chmod 에는 그 안전망이
# 없다). 이 층에서 거부해 그 경로를 끊는다.
# $HOME 을 막는 것이 정상 경로에서 무의미하지 않은 이유: 이 가드는 호출 시점의 값을 보므로,
# 진입부의 `export HOME="$GLOBAL_HOME_SANDBOX"`(위 "전역 HOME 샌드박스" 참고)가 무너지면
# 그때 $HOME 은 실제 홈이고 이 가드가 그것을 거부한다 — 진입부 치환에 대한 2차 방어다
# (음성 대조에서 실제 홈 모양 트리가 통째로 소멸하는 것이 관측됐다). 진입부가 성립하는
# 정상 경로에서는 호출자가 CODING_HARNESS_TEST_HOME 으로 준 디렉토리를 막는 역할을 한다.
# 유효한 인자는 그대로 등록하고 무효한 것만 건너뛴다 — 한 호출에 여러 경로를 넘기는
# 호출부가 있어, 통째로 거부하면 정상 형제 경로가 등록되지 않아 누수가 된다.
#
# 한계(비망라) — 정확 문자열 대조이므로 근사형은 통과한다: `//` · `/.` · `.` · `$HOME/` ·
# `$REPO_ROOT/` · `/Users` 가 전부 등록된다(실측). 현행 호출부(실측 33곳)는 대개 가공 없는
# mktemp 산출물이고, 예외는 위에서 인정한 `$REPO_ROOT/commands/__pycache__` 한 자리와
# T37-17 의 프로브 두 곳(리터럴 `/` 를 등록해 거부를 확인하는 쪽 · `$fixture_root/…` 로
# 결합한 경로를 등록해 수락을 확인하는 쪽)이다 — 어느 것도 위 근사형을 만들지 않는다.
# 그럼에도 이 절을 남기는 이유: 1회차의 피해 경로가 바로 「가공(`dirname`)이 값을
# 증폭시킨 것」이었다. 전수 증명이 아니다.
register_cleanup_path() {
  local candidate rejected=0
  for candidate in "$@"; do
    if [[ -z "$candidate" || "$candidate" == "/" || "$candidate" == "$HOME" \
      || "$candidate" == "$REPO_ROOT" ]]; then
      log_error "register_cleanup_path: 위생 가드가 파괴적 경로 등록을 거부함: '${candidate}'(빈 값·/·\$HOME·레포 루트는 등록 대상이 아니다 — mktemp 실패로 빈 경로가 흘러든 경우가 대표적이다)"
      rejected=1
      continue
    fi
    CLEANUP_PATHS+=("$candidate")
  done
  ((rejected == 0))
}

# 등록된 경로를 실제로 지운다.
#
# 삭제 전에 CLEANUP_NEUTRAL_CWD 로 대피하는 이유(정리가 자기 작업 디렉토리를 지우던
# 결함, 재현됨): 이 배열은
# 호출한 그룹뿐 아니라 finish_group 을 아직 못 거친 이전 그룹들이 남긴 경로까지 함께
# 담고 있을 수 있다(그 경로들이 이 그룹 자신이 등록한 것만이 아니라는 점은 finish_group
# 주석 참고). 프로세스가 지금 그중 하나(또는 그 하위) 안에 서 있는 채로 이 함수가 그
# 배열 전체를 지우면 자기 cwd 를 스스로 지우는 꼴이 되어, 이후 상대 경로 연산·pwd -P·
# 서브셸 실행이 깨진다. 레포 루트로 대피하지 않는 이유: 이 함수보다 앞서 어느 그룹의
# mktemp 가 실패해 cd 가 빈 인자로 조용히 제자리에 머문 채(set -e 는 이 호출 트리 전체에서
# 이미 꺼져 있다 — 아래 rm -rf 항목·finish_group 주석 참고) 여기 도달하면, 레포 루트로의
# 대피가 그 뒤 install.sh 호출을 레포 자기 자신 대상으로 실행시킬 수 있다(project
# CLAUDE.md §1(a) 금지, tests/run.sh 의 T31-4 가 그런 커밋을 막는 대상). 대피 자체가
# 실패하는 이례적인 경우엔 `/` 로 물러난다 — 상대 경로 단언이 우연히 성립할 만한 테스트
# 픽스처가 거기 있을 수 없다.
#
# 잔여 위험(주석만 — 실환경 재현 불가로 코드는 바꾸지 않는다): `cd "$X" || cd /` 는 첫
# 시도가 실패했을 때만 둘째로 넘어가는 폴백이라, 둘 다 실패하는 경우는 다루지 않는다.
# 그 기제에서 따라오는 한계: finish_group 의 두 호출 경로(set -e 꺼짐, 위 chmod 항목
# 참고)에서는 그 실패를 그냥 지나쳐 대피 없이 rm -rf 를 실행하고(미대피 삭제),
# suite_exit_guard 경로(set -e 켜짐)에서는 그 실패가 이 함수를 그 자리에서 끊어 뒤따르는
# rm -rf·CLEANUP_NEUTRAL_CWD 정리·exit "$exit_code" 를 전부 건너뛴다. 비망라 예시: `/`
# 자체를 도달 불가로 만들어 재현을 시도했으나, 이 환경에서 `/` 는 root:wheel 755 라
# mkdir 시도가 그 자리에서 실패로 끝날 뿐 재현되지 않았다 — 그래서 대피 지점을 `/` 대신
# 레포 루트로 바꾸지 않는다: 레포 루트는 실제로 쓰기 가능해, 그리 바꾸면 대피가 오히려
# install.sh 자기 설치 사고로 이어지는 진짜 손상 경로를 연다(위 레포 루트 비선택 이유
# 참고). 두 대피 모두를 실패시킬 다른 형태(예: 두 디렉토리 모두에 대한 실행 권한을
# 프로세스가 동시에 잃는 상황)는 배제되지 않는다. 전수 증명이 아니다.
#
# chmod 를 항상 먼저 시도하는 이유: 일부 그룹(T7·T27)이 소유권·쓰기 금지 시나리오를
# 재현하려 등록 경로 중 일부를 555 등으로 만들어 두는데, 이미 쓰기 가능한 나머지에는
# chmod 가 아무 영향이 없으므로 전 경로에 무조건 적용해도 안전하다 — 27곳이던 개별 trap
# 설치 중 T7·T27 두 곳에만 있던 "일부만 chmod 후 rm" 조합을 나머지와 구분하지 않고
# 단일 함수로 통일한다. 모드 뒤에 `--` 를 붙이지 않는 이유(chmod 가 매번 실패하던
# 결함, 재현됨): BSD/macOS chmod 는 모드(755)를 첫 비옵션 인자로 잡고 그 자리에서
# 옵션 파싱을 끝내므로,
# 모드 뒤의 `--` 는 옵션 종료자가 아니라 존재하지 않는 파일 이름으로 해석돼 chmod 가 매번
# exit 1 로 실패한다(그래도 모드 자체는 정상 변경된다) — 등록 경로는 구조적으로 전부
# 절대 경로라 애초에 `--` 로 막을 대시-시작 경로가 없다. chmod 실패를 `|| true` 로
# 삼키는 이유: suite_exit_guard(전역 EXIT 트랩)가 이 함수를 부르는 경로에서는 set -e 가
# 실제로 걸려 있어 chmod 실패가 뒤따르는 rm -rf 실행을 막을 수 있다 — finish_group 의
# 두 호출 경로는 register_and_run_tests 가 그룹 함수를 `|| true` 로 부르는 순간부터 그
# 호출 트리 전체에서 set -e 가 이미 꺼져 있어 이 보호가 없어도 같은 문제는 없지만, 호출
# 경로마다 안전장치 필요 여부가 갈리는 것을 기억하는 대신 세 경로 모두에 같은 관용구를
# 쓴다. rm -rf 실패 시 배열을 비우지 않는 이유(실패한 경로가 기록 없이 사라지던 결함,
# 재현됨): 비우면
# suite_exit_guard 의 fail-safe(위 register_cleanup_path 주석 참고)가 재시도할 대상 자체를
# 잃어 실패한 경로가 어디에도 기록되지 않고 잊힌다 — 실패를 로그로 남기고 배열은 남겨
# 다음 시도(다른 그룹의 호출, 또는 스위트 종료 시 fail-safe)가 재시도하게 한다. 이미
# 지워진 경로가 섞여 있어도 rm -rf 는 그 경로만 조용히 성공 처리하므로 재시도 자체는
# 안전하다.
cleanup_registered_paths() {
  if ((${#CLEANUP_PATHS[@]} == 0)); then
    return 0
  fi
  cd "$CLEANUP_NEUTRAL_CWD" || cd /
  chmod -R 755 "${CLEANUP_PATHS[@]}" 2> /dev/null || true
  if rm -rf -- "${CLEANUP_PATHS[@]}"; then
    CLEANUP_PATHS=()
  else
    log_error "cleanup_registered_paths: rm -rf 가 등록된 경로 일부를 지우지 못함 — 그 경로는 배열에 남아 다음 정리 시도(다른 그룹 또는 스위트 종료 시 fail-safe)에서 재시도된다"
  fi
}

# 그룹 종료. 누적된 실패가 있으면 **그룹 1건**으로 기록한다 — 집계 단위가 그룹이어야
# `total_tests` 총합 계약(passed + failed == total_tests)이 유지된다.
#
# record_failure 를 쓰지 않고 집계 두 줄을 직접 하는 이유: record_failure 는 기록과
# [ERROR] 출력을 함께 하는데, 여기서는 note_failure 가 각 건을 이미 출력해 뒀다.
# record_failure 를 부르면 같은 내용이 두 번 찍힌다(실패 1건일 때 특히 그렇다).
#
# 반환 직전에 cleanup_registered_paths 를 불러 정리한다(트랩이 아니라 명시 호출). 이때
# 지워지는 건 "이 그룹이 등록한 경로"가 아니라 그 시점까지 CLEANUP_PATHS 에 쌓인 경로
# 전부다(이전 서술이 범위를 좁게 잘못 적어 — 그 경로 중 하나가
# 프로세스의 현재 작업 디렉토리인 경우를 놓치게 했다) — finish_group 을 아직 못 거친
# 이전 그룹들이 남긴 등록까지 포함된다. 그 경로들이 cwd 일 수 있는 문제와 대응은
# cleanup_registered_paths 자신의 주석에 적는다. 이 함수 자체를 거치지 않고 그 전에
# record_failure+return 로 먼저 빠지는 조기 실패 경로(사전조건 실패 등)는 여기서
# 정리되지 않지만, 등록만은 이미 끝난 뒤이므로 전역 EXIT 트랩(suite_exit_guard)이 스위트
# 종료 시점에 fail-safe 로 마저 정리한다 — 아래는 비망라 예시고, finish_group 을 아예
# 쓰지 않는 함수(T1 류)도 같은 이유로 이 fail-safe 에 기댄다.
finish_group() {
  local group_name="$1"
  local failure_count=${#group_failures[@]}
  if ((failure_count == 0)); then
    log_ok "$group_name 통과"
    ((passed_tests++)) || true
    cleanup_registered_paths
    return 0
  fi
  ((failed_tests++))
  if ((failure_count == 1)); then
    failed_list+=("$group_name: ${group_failures[0]}")
  else
    # 요약만 보고도 무엇이 깨졌는지 알 수 있게 전 건을 싣는다.
    # ${array[*]} 대신 직접 이어 붙이는 이유: IFS 는 첫 글자만 구분자로 쓰므로
    # IFS=' | ' 로는 공백 하나만 들어가 메시지들이 붙어 버린다.
    local joined="${group_failures[0]}"
    local index
    for ((index = 1; index < failure_count; index++)); do
      joined+=" | ${group_failures[index]}"
    done
    failed_list+=("$group_name: ${failure_count}건 동시 실패 — $joined")
  fi
  group_failures=()
  cleanup_registered_paths
  return 1
}

# 단순 비교
assert_equals() {
  local expected="$1"
  local actual="$2"
  local message="$3"
  if [[ "$expected" != "$actual" ]]; then
    return 1
  fi
  return 0
}

# 파일 존재 확인
assert_file_exists() {
  local file_path="$1"
  local message="$2"
  if [[ ! -f "$file_path" ]]; then
    log_error "파일 미존재: $file_path ($message)"
    return 1
  fi
  return 0
}

# 파일 미존재 확인
assert_file_not_exists() {
  local file_path="$1"
  local message="$2"
  if [[ -f "$file_path" ]]; then
    log_error "파일 존재함 (기대: 미존재): $file_path ($message)"
    return 1
  fi
  return 0
}

# 디렉토리 존재 확인
assert_dir_exists() {
  local dir_path="$1"
  local message="$2"
  if [[ ! -d "$dir_path" ]]; then
    log_error "디렉토리 미존재: $dir_path ($message)"
    return 1
  fi
  return 0
}

# 디렉토리 미존재 확인
assert_dir_not_exists() {
  local dir_path="$1"
  local message="$2"
  if [[ -d "$dir_path" ]]; then
    log_error "디렉토리 존재함 (기대: 미존재): $dir_path ($message)"
    return 1
  fi
  return 0
}

# 종료 코드 확인
assert_exit_code() {
  local expected_code="$1"
  local actual_code="$2"
  local message="$3"
  if [[ "$expected_code" != "$actual_code" ]]; then
    log_error "종료 코드 불일치: 기대=$expected_code, 실제=$actual_code ($message)"
    return 1
  fi
  return 0
}

# 파일 개수 확인 (특정 디렉토리 아래)
count_files_recursive() {
  local dir="$1"
  if [[ ! -d "$dir" ]]; then
    echo 0
  else
    find "$dir" -type f | wc -l | xargs echo  # Trim whitespace from wc output
  fi
}

# 디렉토리 비교
assert_dirs_equal() {
  local dir1="$1"
  local dir2="$2"
  local message="$3"
  local diff_output
  diff_output=$(diff -r "$dir1" "$dir2" 2>&1 || true)
  if [[ -n "$diff_output" ]]; then
    log_error "디렉토리 내용 불일치 ($message)"
    echo "$diff_output" | head -10
    return 1
  fi
  return 0
}

# 파일 내용 일치 확인
assert_file_content_equals() {
  local file_path="$1"
  local expected_content="$2"
  local message="$3"
  local actual_content
  actual_content=$(cat "$file_path" 2>/dev/null || echo "")
  if [[ "$expected_content" != "$actual_content" ]]; then
    log_error "파일 내용 불일치 ($message)"
    log_error "기대:"
    echo "$expected_content" | head -5
    log_error "실제:"
    echo "$actual_content" | head -5
    return 1
  fi
  return 0
}

# install.sh 의 compute_sha256() 과 동일한 로직 — T27 이 대장(ledger) 해시를 흉내낼 때 쓴다.
compute_sha256_for_test() {
  if command -v sha256sum &> /dev/null; then
    sha256sum "$1" | awk '{print $1}'
  else
    shasum -a 256 "$1" | awk '{print $1}'
  fi
}

# ============================================================================
# 테스트 케이스
# ============================================================================

# T1: --scope project 신규 설치
test_scope_project_new_install() {
  local test_name="T1"
  local test_desc="--scope project 신규 설치"
  log_test_name "$test_name" "$test_desc"

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  cd "$sandbox"

  local exit_code=0
  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 || exit_code=$?

  if ! assert_exit_code 0 "$exit_code" "install.sh exit code"; then
    record_failure "$test_name" "설치 실패: exit code $exit_code"
    return 1
  fi

  # rules 46개 확인
  local rules_count
  rules_count=$(count_files_recursive "./.claude/rules")
  if ! assert_equals 46 "$rules_count" "rules 파일 개수"; then
    record_failure "$test_name" "rules 파일 개수: 기대=46, 실제=$rules_count"
    return 1
  fi

  # agents 4개 확인
  local agents_count
  agents_count=$(count_files_recursive "./.claude/agents")
  if ! assert_equals 4 "$agents_count" "agents 파일 개수"; then
    record_failure "$test_name" "agents 파일 개수: 기대=4, 실제=$agents_count"
    return 1
  fi

  # commands 8개 확인 (.md 8종 — 대시보드 자산은 hub/bin 으로 이전됐다, docs/prps/
  # dashboard-into-hub.md HD1)
  local commands_count
  commands_count=$(count_files_recursive "./.claude/commands")
  if ! assert_equals 8 "$commands_count" "commands 파일 개수"; then
    record_failure "$test_name" "commands 파일 개수: 기대=8, 실제=$commands_count"
    return 1
  fi

  # CLAUDE.md 미설치 확인 — project scope 는 CLAUDE.md 를 배포하지 않는다(비파괴 증명, T5 와 짝)
  if ! assert_file_not_exists "./CLAUDE.md" "CLAUDE.md"; then
    record_failure "$test_name" "CLAUDE.md 가 생성됨 (기대: project scope 는 CLAUDE.md 를 배포하지 않음)"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T2: --scope user 신규 설치
test_scope_user_new_install() {
  local test_name="T2"
  local test_desc="--scope user 신규 설치"
  log_test_name "$test_name" "$test_desc"

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  # HOME을 샌드박스로 치환해 실제 ~/.claude 보호
  local exit_code=0
  HOME="$sandbox" "$INSTALL_SCRIPT" --scope user > /dev/null 2>&1 || exit_code=$?

  if ! assert_exit_code 0 "$exit_code" "install.sh exit code"; then
    record_failure "$test_name" "설치 실패: exit code $exit_code"
    return 1
  fi

  # $HOME/.claude/rules 생성 확인
  if ! assert_dir_exists "$sandbox/.claude/rules" ".claude/rules"; then
    record_failure "$test_name" ".claude/rules 디렉토리 미생성"
    return 1
  fi

  # $HOME/.claude/agents 생성 확인
  if ! assert_dir_exists "$sandbox/.claude/agents" ".claude/agents"; then
    record_failure "$test_name" ".claude/agents 디렉토리 미생성"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T3: 멱등성 — 2회 연속 실행 후 차이 없음
#
# 한계(비망라, PRP tests-hardening §9 B4) — 이 비교는 `./.claude` 아래 파일들의 내용 해시만
# 대조한다. 그 디렉토리 밖에 생기는 부작용이나, 내용은 같아도 권한·타임스탬프처럼 md5sum 이
# 보지 않는 속성의 변화는 이 비교로 드러나지 않는다. T3-1 은 이 비교가 실제로 무는 것을
# 원장으로 확인한 사례(installed_at 스트립 제거)고, T3-2·T3-3 은 비교 자체의 사전조건
# (도구 존재·캡처 비어있지 않음)만 본다. 전수 증명이 아니다.
test_idempotency() {
  local test_name="T3"
  local test_desc="멱등성: 2회 연속 실행"
  log_test_name "$test_name" "$test_desc"

  # 사전조건(종속 서브체크, PRP §9 B4): md5sum 이 PATH 에 없으면 아래 find -exec 가 파일마다
  # 조용히 실패해 상태 캡처가 빈 문자열이 되고, 뒤의 "" == "" 비교가 늘 통과해 멱등성
  # 위반을 못 잡는다(기본 macOS 는 BSD md5 만 제공하고 md5sum 은 없다 — 이 실행 환경에는
  # /sbin/md5sum 이 있어 지금은 도달하지 않는 이식성 공허다). 도구를 바꾸는 것(shasum 등)은
  # 이번 범위 밖이라 여기서는 원인만 갈라 보고하고 뒤 단계로 넘어가지 않는다.
  if ! command -v md5sum > /dev/null 2>&1; then
    record_failure "$test_name" "T3-2: md5sum 명령을 찾을 수 없음 — 상태 캡처가 조용히 빈 값이 되어 아래 비교가 무의미해짐"
    return 1
  fi

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  cd "$sandbox"

  # 첫 번째 실행
  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1

  # 상태 캡처
  local first_state
  first_state=$(find "./.claude" -type f -exec md5sum {} \; | sort)

  # 사전조건(종속 서브체크, PRP §9 B4): 캡처가 빈 값이면(설치 실패로 ./.claude 에 파일이
  # 없는 경우) 뒤의 "" == "" 비교가 늘 통과해 이 테스트가 아무것도 검사하지 않은 채 끝난다.
  # md5sum 부재는 위에서 이미 갈랐으므로 여기 도달했다면 원인은 설치 결과 쪽이다.
  if [[ -z "$first_state" ]]; then
    record_failure "$test_name" "T3-3: 첫 실행 후 상태 캡처가 빈 값 — ./.claude 에 파일이 없음(설치 실패 가능)"
    return 1
  fi

  # 초 경계를 넘겨 manifest 타임스탬프 재기록이 감지되도록 강제
  sleep 1

  # 두 번째 실행
  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1

  # 상태 비교
  local second_state
  second_state=$(find "./.claude" -type f -exec md5sum {} \; | sort)

  if ! assert_equals "$first_state" "$second_state" "두 상태 동일"; then
    record_failure "$test_name" "T3-1: 멱등성 위반: 상태 변경"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T4: 부분 손상 수복
test_partial_damage_recovery() {
  local test_name="T4"
  local test_desc="부분 손상 수복: rules/common/testing.md 삭제 후 재실행"
  log_test_name "$test_name" "$test_desc"

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  cd "$sandbox"

  # 첫 번째 설치
  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1

  # 파일 삭제
  rm -f "./.claude/rules/common/testing.md"

  # 재실행
  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1

  # 파일 복구 확인
  if ! assert_file_exists "./.claude/rules/common/testing.md" "testing.md 복구"; then
    record_failure "$test_name" "testing.md 미복구"
    return 1
  fi

  # rules 46개 확인
  local rules_count
  rules_count=$(count_files_recursive "./.claude/rules")
  if ! assert_equals 46 "$rules_count" "rules 파일 개수"; then
    record_failure "$test_name" "rules 파일 개수: 기대=46, 실제=$rules_count"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T5: --scope project 는 기존 ./CLAUDE.md 를 건드리지 않는다(project scope 는 CLAUDE.md 를
# 배포하지 않으므로 충돌 자체가 성립하지 않는다 — 이 자리는 이전엔 "충돌 시 중단"이었다).
# 은퇴 조건을 만족하는 HOME 의 ~/.claude/CLAUDE.md 도 project scope 실행으로는 절대
# 건드려지지 않는지 별도로 확인한다(scope 게이트 — [[ -f "" ]] 가 우연히 막아주는 것에
# 기대지 않고 실제 파일로 검증한다).
test_scope_project_ignores_existing_claude_md() {
  local test_name="T5"
  local test_desc="--scope project 는 기존 CLAUDE.md 를 건드리지 않는다(scope 게이트 포함)"
  log_test_name "$test_name" "$test_desc"

  local sandbox sandbox_home sandbox_gate
  sandbox=$(mktemp -d)
  sandbox_home=$(mktemp -d)
  sandbox_gate=$(mktemp -d)
  register_cleanup_path "$sandbox" "$sandbox_home" "$sandbox_gate"

  cd "$sandbox"

  # CLAUDE.md 사전 생성
  echo "existing content" > ./CLAUDE.md
  local original_content
  original_content=$(cat ./CLAUDE.md)

  # 설치 시도
  local exit_code=0
  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 || exit_code=$?

  # exit 0 확인 — CLAUDE.md 는 project scope 에서 애초에 배포 대상이 아니다(현행 1 의 반전)
  if ! assert_exit_code 0 "$exit_code" "exit code 0"; then
    record_failure "$test_name" "exit code: 기대=0, 실제=$exit_code"
    return 1
  fi

  # CLAUDE.md 내용 불변 확인
  local current_content
  current_content=$(cat ./CLAUDE.md)
  if ! assert_equals "$original_content" "$current_content" "CLAUDE.md 불변"; then
    record_failure "$test_name" "CLAUDE.md 내용 변경됨"
    return 1
  fi

  # 백업 파일 미생성 확인 — CLAUDE.md 는 손대지 않으므로 백업할 것도 없다
  local backup_files
  backup_files=$(ls -1 ./CLAUDE.md.bak-* 2>/dev/null | wc -l | xargs echo)
  if [[ "$backup_files" != "0" ]]; then
    record_failure "$test_name" "백업 파일이 생성됨(기대: 0개, 실제: ${backup_files}개)"
    return 1
  fi

  # rules 46개 설치 확인 — CLAUDE.md 존재 여부와 무관하게 정상 설치된다(현행 "미생성" 단언의 반전)
  local rules_count
  rules_count=$(count_files_recursive "./.claude/rules")
  if ! assert_equals 46 "$rules_count" "rules 파일 개수"; then
    record_failure "$test_name" "rules 파일 개수: 기대=46, 실제=$rules_count"
    return 1
  fi

  # scope 게이트 — 은퇴 조건(레거시 센티널 2종 일치)을 만족하는 CLAUDE.md 를 별도 HOME 에
  # 실제로 배치하고, 선행 project 설치가 전혀 없는 새 $PWD($sandbox_gate)에서
  # --scope project(대상은 $sandbox_gate 지 $HOME 이 아니다)를 실행해도 무접촉인지
  # 확인한다. project scope 에서 retired_claude_md_path 가 빈 문자열이라 [[ -f "" ]] 가
  # 우연히 막아주는 것과는 별개로, 실제 파일이 있는 상황에서도 안전한지 검증하는 것이 이
  # 블록의 목적이다.
  # $sandbox 를 재사용하지 않는 이유(2회차 검수 HIGH-1 (a)): 위 :479 의 앞선
  # --scope project 설치가 $sandbox/.claude/.coding-harness.json 을 이미 version 3 으로
  # 남긴다. project scope 의 은퇴 판정은 (호출된다고 가정해도) 그 $PWD manifest 를
  # 읽으므로, $sandbox 를 그대로 쓰면 규칙 4(version ≥ 3 → 로그 없이 skip)가 먼저 이겨
  # 이 블록이 무엇을 검증하든 항상 통과해버린다 — 새 $sandbox_gate 라야 그 선점이 없다.
  # 픽스처가 레거시 센티널인 이유(HIGH-1 (b)): $sandbox_gate 는 manifest 가 아예 없으므로
  # (규칙 4 는 버전 0, 규칙 5/6 은 대장 해시 없음으로 항상 통과) 이 시나리오에서 유일하게
  # 관측 가능한 판정 분기는 규칙 7(레거시 센티널)뿐이다 — "대장 해시 주입"은 project
  # scope 가 $HOME 의 manifest 를 읽지 않으므로 여기서는 아무것도 판정하지 않는다.
  mkdir -p "$sandbox_home/.claude"
  {
    echo '# 전역 개발 지침 (~/.claude/CLAUDE.md)'
    echo ''
    echo '### 서브에이전트 위임은 사용자가 상시 요청한 것이다'
  } > "$sandbox_home/.claude/CLAUDE.md"
  local home_claude_md_hash
  home_claude_md_hash=$(compute_sha256_for_test "$sandbox_home/.claude/CLAUDE.md")

  cd "$sandbox_gate"
  local scope_gate_output scope_gate_exit=0
  scope_gate_output=$(HOME="$sandbox_home" "$INSTALL_SCRIPT" --scope project 2>&1) || scope_gate_exit=$?
  if [[ "$scope_gate_exit" -ne 0 ]]; then
    record_failure "$test_name" "scope 게이트: --scope project 인데 exit ${scope_gate_exit}로 실패함"
    return 1
  fi
  if [[ ! -f "$sandbox_home/.claude/CLAUDE.md" ]]; then
    record_failure "$test_name" "scope 게이트: HOME 의 CLAUDE.md 가 project scope 실행 중 사라짐(은퇴 게이트 무력화 의심)"
    return 1
  fi
  if [[ "$(compute_sha256_for_test "$sandbox_home/.claude/CLAUDE.md")" != "$home_claude_md_hash" ]]; then
    record_failure "$test_name" "scope 게이트: HOME 의 CLAUDE.md 내용이 변경됨"
    return 1
  fi
  local scope_gate_retired_count
  scope_gate_retired_count=$(ls -1 "$sandbox_home/.claude/CLAUDE.md.retired-"* 2> /dev/null | wc -l | xargs echo)
  if [[ "$scope_gate_retired_count" != "0" ]]; then
    record_failure "$test_name" "scope 게이트: HOME 에 은퇴 파일이 생성됨(기대: 0개, 실제: ${scope_gate_retired_count}개)"
    return 1
  fi
  local scope_gate_retire_log_lines
  scope_gate_retire_log_lines=$(grep -c "은퇴" <<< "$scope_gate_output" || true)
  if [[ "$scope_gate_retire_log_lines" != "0" ]]; then
    record_failure "$test_name" "scope 게이트: --scope project 인데 은퇴 관련 로그가 출력됨(기대: 0줄, 실제: ${scope_gate_retire_log_lines}줄)"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T6: 은퇴 경로 B — 대장 해시 일치 → mv 로 개명(삭제이자 백업), 재실행은 멱등(경로 F)
test_retire_ledger_match() {
  local test_name="T6"
  local test_desc="은퇴 경로 B: 대장 해시 일치 → CLAUDE.md.retired-* 로 개명"
  log_test_name "$test_name" "$test_desc"

  local sandbox_home
  sandbox_home=$(mktemp -d)
  register_cleanup_path "$sandbox_home"

  # v2 설치본을 흉내낸다: 옛 CLAUDE.md 사본을 배치하고, manifest 대장에 그 해시를 직접
  # 주입한다(T27-2 :5580 대의 주입 기법과 동일 — read_installed_ledger_hash 가 grep 기반
  # 줄 매칭이라 파일 끝에 한 줄 추가하는 것으로 충분하다. 한계: 결과 manifest 는 엄밀한
  # JSON 이 아니다 — 이 스위트 전반의 관행).
  mkdir -p "$sandbox_home/.claude"
  printf '오래된 CLAUDE.md 내용\n' > "$sandbox_home/.claude/CLAUDE.md"
  local original_content
  original_content=$(cat "$sandbox_home/.claude/CLAUDE.md")
  local claude_md_hash
  claude_md_hash=$(compute_sha256_for_test "$sandbox_home/.claude/CLAUDE.md")
  cat > "$sandbox_home/.claude/.coding-harness.json" << MANIFEST_EOF
{
  "version": 2,
  "scope": "user"
}
MANIFEST_EOF
  echo "    \"CLAUDE.md\": \"$claude_md_hash\"" >> "$sandbox_home/.claude/.coding-harness.json"

  local exit_code=0
  HOME="$sandbox_home" "$INSTALL_SCRIPT" --scope user > /dev/null 2>&1 || exit_code=$?
  if ! assert_exit_code 0 "$exit_code" "exit code 0"; then
    record_failure "$test_name" "설치 실패: exit code $exit_code"
    return 1
  fi

  if [[ -f "$sandbox_home/.claude/CLAUDE.md" ]]; then
    record_failure "$test_name" "CLAUDE.md 가 은퇴되지 않고 남아있음"
    return 1
  fi

  local retired_files
  retired_files=$(ls -1 "$sandbox_home/.claude/CLAUDE.md.retired-"* 2> /dev/null | wc -l | xargs echo)
  if [[ "$retired_files" != "1" ]]; then
    record_failure "$test_name" "은퇴 백업 파일 개수: 기대=1, 실제=$retired_files"
    return 1
  fi

  local retired_content
  retired_content=$(cat "$sandbox_home/.claude/CLAUDE.md.retired-"* 2> /dev/null)
  if ! assert_equals "$original_content" "$retired_content" "은퇴 백업 내용"; then
    record_failure "$test_name" "은퇴 백업 내용 불일치"
    return 1
  fi

  # 재실행 시 은퇴 파일이 늘지 않음(파일이 이미 없어 규칙 2(파일 부재) skip, 경로 F 멱등 —
  # manifest 는 이미 v3 이지만 규칙 2 가 규칙 4 보다 먼저 이겨 규칙 4 는 이 경로에서 발동하지
  # 않는다. 규칙 4 skip 자체는 T7(f)가 별도로 검증한다)
  HOME="$sandbox_home" "$INSTALL_SCRIPT" --scope user > /dev/null 2>&1
  retired_files=$(ls -1 "$sandbox_home/.claude/CLAUDE.md.retired-"* 2> /dev/null | wc -l | xargs echo)
  if [[ "$retired_files" != "1" ]]; then
    record_failure "$test_name" "재실행 후 은퇴 파일 개수 변화(멱등 위반): 실제=$retired_files"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T7: 은퇴 보호 분기 — (a) 대장 불일치(수정본, --force 로도 보호) (b) manifest 없음 +
# 레거시 센티널 일치(자동 이관) (c) manifest 없음 + 무관 내용(보호) (d) dry-run 은
# 계획만 출력하고 실제로 은퇴시키지 않는다 (e) 심볼릭 링크(규칙 3이 대장 일치·규칙 5보다
# 먼저 이김) (f) manifest v3 + 레거시 센티널 2종(규칙 4가 규칙 7보다 먼저 이겨 로그 0줄)
# (g) .claude 읽기 전용 + rules/agents/commands 미존재(사전 조건 실패, manifest 미갱신)
# (h) 동일-초 백업 이름 선재(선재 검사가 exit 1 로 막고 선재 파일을 보존) (i) .claude
# 읽기 전용 + rules/agents/commands 선존(사전 조건은 통과하고 mv 가 EPERM 으로 실패,
# fail-closed·manifest 미갱신 — (g)와 달리 retire_user_claude_md 호출 자체는 실행된다)
test_retire_protection_branches() {
  local test_name="T7"
  local test_desc="은퇴 보호 분기: 대장 불일치·레거시 센티널·무관 내용·dry-run·심볼릭 링크·v3+센티널·읽기 전용·동일-초 충돌·mv 실패"
  log_test_name "$test_name" "$test_desc"

  local sandbox_modified sandbox_legacy sandbox_unknown sandbox_dry
  local sandbox_symlink sandbox_v3sentinel sandbox_readonly sandbox_collision sandbox_mvfail
  sandbox_modified=$(mktemp -d); sandbox_legacy=$(mktemp -d)
  sandbox_unknown=$(mktemp -d); sandbox_dry=$(mktemp -d)
  sandbox_symlink=$(mktemp -d); sandbox_v3sentinel=$(mktemp -d)
  sandbox_readonly=$(mktemp -d); sandbox_collision=$(mktemp -d)
  sandbox_mvfail=$(mktemp -d)
  register_cleanup_path "$sandbox_modified" "$sandbox_legacy" "$sandbox_unknown" "$sandbox_dry" \
    "$sandbox_symlink" "$sandbox_v3sentinel" "$sandbox_readonly" "$sandbox_collision" "$sandbox_mvfail"

  # ---- (a) 대장 해시 불일치(사용자 수정) → protect_modified, --force 로도 은퇴하지 않는다 ----
  mkdir -p "$sandbox_modified/.claude"
  printf '오래된 CLAUDE.md 내용\n' > "$sandbox_modified/.claude/CLAUDE.md"
  local modified_hash
  modified_hash=$(compute_sha256_for_test "$sandbox_modified/.claude/CLAUDE.md")
  cat > "$sandbox_modified/.claude/.coding-harness.json" << MANIFEST_EOF
{
  "version": 2,
  "scope": "user"
}
MANIFEST_EOF
  echo "    \"CLAUDE.md\": \"$modified_hash\"" >> "$sandbox_modified/.claude/.coding-harness.json"
  echo "# 사용자 수정" >> "$sandbox_modified/.claude/CLAUDE.md"   # 주입한 해시와 불일치하게 만든다

  local modified_output modified_exit=0
  modified_output=$(HOME="$sandbox_modified" "$INSTALL_SCRIPT" --scope user --force 2>&1) || modified_exit=$?
  if [[ "$modified_exit" -ne 0 ]]; then
    record_failure "$test_name" "(a) 보호는 실패가 아닌데 exit ${modified_exit}로 중단됨"
    return 1
  fi
  if [[ ! -f "$sandbox_modified/.claude/CLAUDE.md" ]]; then
    record_failure "$test_name" "(a) 수정된 CLAUDE.md 가 --force 로 은퇴됨(기대: 보호)"
    return 1
  fi
  if ! grep -qF "수정된 파일이라 --force 로도 은퇴시키지 않습니다" <<< "$modified_output"; then
    record_failure "$test_name" "(a) stdout 에 protect_modified 보호 로그가 없음"
    return 1
  fi

  # ---- (b) manifest 없음 + 레거시 센티널 2종 일치 → retire(자동 이관) ----
  mkdir -p "$sandbox_legacy/.claude"
  {
    echo '# 전역 개발 지침 (~/.claude/CLAUDE.md)'
    echo ''
    echo '### 서브에이전트 위임은 사용자가 상시 요청한 것이다'
  } > "$sandbox_legacy/.claude/CLAUDE.md"

  local legacy_exit=0
  HOME="$sandbox_legacy" "$INSTALL_SCRIPT" --scope user > /dev/null 2>&1 || legacy_exit=$?
  if [[ "$legacy_exit" -ne 0 ]]; then
    record_failure "$test_name" "(b) 레거시 센티널 자동 이관이 exit ${legacy_exit}로 실패함"
    return 1
  fi
  if [[ -f "$sandbox_legacy/.claude/CLAUDE.md" ]]; then
    record_failure "$test_name" "(b) 레거시 센티널 일치 CLAUDE.md 가 은퇴되지 않음"
    return 1
  fi
  local legacy_retired_count
  legacy_retired_count=$(ls -1 "$sandbox_legacy/.claude/CLAUDE.md.retired-"* 2> /dev/null | wc -l | xargs echo)
  if [[ "$legacy_retired_count" != "1" ]]; then
    record_failure "$test_name" "(b) 레거시 은퇴 파일 개수: 기대=1, 실제=$legacy_retired_count"
    return 1
  fi

  # ---- (c) manifest 없음 + 무관 내용 → protect_unknown(보호) ----
  mkdir -p "$sandbox_unknown/.claude"
  echo "my own notes" > "$sandbox_unknown/.claude/CLAUDE.md"

  local unknown_output unknown_exit=0
  unknown_output=$(HOME="$sandbox_unknown" "$INSTALL_SCRIPT" --scope user 2>&1) || unknown_exit=$?
  if [[ "$unknown_exit" -ne 0 ]]; then
    record_failure "$test_name" "(c) 보호는 실패가 아닌데 exit ${unknown_exit}로 중단됨"
    return 1
  fi
  if [[ ! -f "$sandbox_unknown/.claude/CLAUDE.md" ]]; then
    record_failure "$test_name" "(c) 무관 내용의 CLAUDE.md 가 삭제됨(기대: 보호)"
    return 1
  fi
  if ! grep -qF "설치 이력을 확인할 수 없어 은퇴시키지 않습니다" <<< "$unknown_output"; then
    record_failure "$test_name" "(c) stdout 에 protect_unknown 보호 로그가 없음"
    return 1
  fi

  # ---- (d) dry-run — 계획만 출력, 실제로 은퇴시키지 않는다 ----
  mkdir -p "$sandbox_dry/.claude"
  printf '오래된 CLAUDE.md 내용\n' > "$sandbox_dry/.claude/CLAUDE.md"
  local dry_hash
  dry_hash=$(compute_sha256_for_test "$sandbox_dry/.claude/CLAUDE.md")
  cat > "$sandbox_dry/.claude/.coding-harness.json" << MANIFEST_EOF
{
  "version": 2,
  "scope": "user"
}
MANIFEST_EOF
  echo "    \"CLAUDE.md\": \"$dry_hash\"" >> "$sandbox_dry/.claude/.coding-harness.json"

  local dry_output dry_exit=0
  dry_output=$(HOME="$sandbox_dry" "$INSTALL_SCRIPT" --scope user --dry-run 2>&1) || dry_exit=$?
  if [[ "$dry_exit" -ne 0 ]]; then
    record_failure "$test_name" "(d) dry-run 이 exit ${dry_exit}로 실패함"
    return 1
  fi
  if [[ ! -f "$sandbox_dry/.claude/CLAUDE.md" ]]; then
    record_failure "$test_name" "(d) --dry-run 인데 CLAUDE.md 가 실제로 은퇴됨"
    return 1
  fi
  local dry_retired_count
  dry_retired_count=$(ls -1 "$sandbox_dry/.claude/CLAUDE.md.retired-"* 2> /dev/null | wc -l | xargs echo)
  if [[ "$dry_retired_count" != "0" ]]; then
    record_failure "$test_name" "(d) --dry-run 인데 은퇴 파일이 생성됨"
    return 1
  fi
  if ! grep -qF "CLAUDE.md 배포 채널 은퇴" <<< "$dry_output"; then
    record_failure "$test_name" "(d) dry-run 출력에 은퇴 계획 문구가 없음"
    return 1
  fi

  # ---- (e) 심볼릭 링크 — 대장 해시가 일치해도(규칙 5 조건 충족) 규칙 3(심볼릭 링크)이
  # 먼저 이겨 protect_unknown 이어야 한다. 링크·원본 둘 다 잔존을 확인한다. ----
  mkdir -p "$sandbox_symlink/.claude"
  printf '오래된 CLAUDE.md 내용\n' > "$sandbox_symlink/.claude/CLAUDE.md.real"
  local symlink_target_hash
  symlink_target_hash=$(compute_sha256_for_test "$sandbox_symlink/.claude/CLAUDE.md.real")
  ln -s "$sandbox_symlink/.claude/CLAUDE.md.real" "$sandbox_symlink/.claude/CLAUDE.md"
  cat > "$sandbox_symlink/.claude/.coding-harness.json" << MANIFEST_EOF
{
  "version": 2,
  "scope": "user"
}
MANIFEST_EOF
  echo "    \"CLAUDE.md\": \"$symlink_target_hash\"" >> "$sandbox_symlink/.claude/.coding-harness.json"

  local symlink_output symlink_exit=0
  symlink_output=$(HOME="$sandbox_symlink" "$INSTALL_SCRIPT" --scope user 2>&1) || symlink_exit=$?
  if [[ "$symlink_exit" -ne 0 ]]; then
    record_failure "$test_name" "(e) 보호는 실패가 아닌데 exit ${symlink_exit}로 중단됨"
    return 1
  fi
  if [[ ! -L "$sandbox_symlink/.claude/CLAUDE.md" ]]; then
    record_failure "$test_name" "(e) 심볼릭 링크가 사라짐(기대: 보호로 링크 잔존 — 규칙 3이 규칙 5보다 먼저 이겨야 함)"
    return 1
  fi
  if [[ ! -f "$sandbox_symlink/.claude/CLAUDE.md.real" ]]; then
    record_failure "$test_name" "(e) 심볼릭 링크의 원본 파일이 사라짐"
    return 1
  fi
  if ! grep -qF "심볼릭 링크라 의도를 판정할 수 없어" <<< "$symlink_output"; then
    record_failure "$test_name" "(e) stdout 에 심볼릭 링크 전용 보호 사유 로그가 없음"
    return 1
  fi

  # ---- (f) manifest v3 + 레거시 센티널 2종을 모두 가진 파일 — 규칙 4(skip)가 규칙
  # 7(retire)보다 먼저 이겨야 하고, 규칙 4 의 skip 은 로그를 내지 않는다(경로 F). ----
  mkdir -p "$sandbox_v3sentinel/.claude"
  {
    echo '# 전역 개발 지침 (~/.claude/CLAUDE.md)'
    echo ''
    echo '### 서브에이전트 위임은 사용자가 상시 요청한 것이다'
  } > "$sandbox_v3sentinel/.claude/CLAUDE.md"
  cat > "$sandbox_v3sentinel/.claude/.coding-harness.json" << MANIFEST_EOF
{
  "version": 3,
  "scope": "user"
}
MANIFEST_EOF

  local v3sentinel_output v3sentinel_exit=0
  v3sentinel_output=$(HOME="$sandbox_v3sentinel" "$INSTALL_SCRIPT" --scope user 2>&1) || v3sentinel_exit=$?
  if [[ "$v3sentinel_exit" -ne 0 ]]; then
    record_failure "$test_name" "(f) manifest v3 스킵인데 exit ${v3sentinel_exit}로 실패함"
    return 1
  fi
  if [[ ! -f "$sandbox_v3sentinel/.claude/CLAUDE.md" ]]; then
    record_failure "$test_name" "(f) manifest v3 인데 CLAUDE.md 가 은퇴됨(기대: 무접촉, 경로 F)"
    return 1
  fi
  local v3sentinel_retire_log_lines
  v3sentinel_retire_log_lines=$(grep -c "은퇴" <<< "$v3sentinel_output" || true)
  if [[ "$v3sentinel_retire_log_lines" != "0" ]]; then
    record_failure "$test_name" "(f) manifest v3 인데 은퇴 관련 로그가 출력됨(기대: 0줄, 실제: ${v3sentinel_retire_log_lines}줄) — 규칙 4 는 로그 없이 skip 해야 함"
    return 1
  fi

  # ---- (g) .claude 자체가 읽기 전용(chmod 555) + rules/agents/commands 미존재 →
  # find_existing_ancestor 가 .claude 자신으로 귀결돼 check_write_permission(사전 조건)
  # 에서 exit 1 — retire_user_claude_md 호출 자체에 도달하지 않는다. manifest 는 v2 로
  # 남아야 한다(설치 전체가 미실행임을 증명). mv 가 실제로 호출된 뒤 실패하는 경로는
  # rules/agents/commands 가 이미 있어야 사전 조건을 통과하므로 별도인 (i)가 잠근다. ----
  mkdir -p "$sandbox_readonly/.claude"
  printf '오래된 CLAUDE.md 내용\n' > "$sandbox_readonly/.claude/CLAUDE.md"
  cat > "$sandbox_readonly/.claude/.coding-harness.json" << MANIFEST_EOF
{
  "version": 2,
  "scope": "user"
}
MANIFEST_EOF
  chmod 555 "$sandbox_readonly/.claude"

  local readonly_exit=0
  HOME="$sandbox_readonly" "$INSTALL_SCRIPT" --scope user > /dev/null 2>&1 || readonly_exit=$?
  chmod 755 "$sandbox_readonly/.claude"   # 이후 단언·정리를 위해 즉시 권한 복구

  if [[ "$readonly_exit" -ne 1 ]]; then
    record_failure "$test_name" "(g) .claude 읽기 전용인데 exit ${readonly_exit}(기대: 1)로 종료됨"
    return 1
  fi
  if ! grep -qF '"version": 2' "$sandbox_readonly/.claude/.coding-harness.json"; then
    record_failure "$test_name" "(g) 사전 조건 실패에도 manifest 가 갱신됨(기대: v2 그대로)"
    return 1
  fi

  # ---- (h) 동일-초 백업 이름 선재 — mv 직전 선재 검사가 exit 1 로 막고 선재 파일을
  # 보존해야 한다(데이터 손실 방지). ----
  mkdir -p "$sandbox_collision/.claude"
  printf '오래된 CLAUDE.md 내용\n' > "$sandbox_collision/.claude/CLAUDE.md"
  local collision_hash
  collision_hash=$(compute_sha256_for_test "$sandbox_collision/.claude/CLAUDE.md")
  cat > "$sandbox_collision/.claude/.coding-harness.json" << MANIFEST_EOF
{
  "version": 2,
  "scope": "user"
}
MANIFEST_EOF
  echo "    \"CLAUDE.md\": \"$collision_hash\"" >> "$sandbox_collision/.claude/.coding-harness.json"

  # retire_user_claude_md 가 실제로 고르는 초는 install.sh 자신의 date 호출 시점이라 이
  # 테스트가 미리 알 수 없다 — 그래서 한 초가 아니라 현재 초부터 collision_window_seconds
  # 초 창 전부에 백업 후보를 선점해, install.sh 가 그 창 안 어느 초를 고르든 충돌이
  # 성립하게 만든다(초 연산은 GNU/BSD 가 갈리는 date -d/-v 대신, 이 파일의 기존 관행과
  # 같은 python3 로 계산한다). 한계: 창을 벗어난 초가 선택되면 충돌이 성립하지 않아
  # install.sh 가 exit 0 으로 성공한다 — 그때 이 케이스는 조용히 통과하지 않고 바로 아래
  # exit 코드 단언에서 실패한다(거짓 실패). 창 초과의 대가는 오탐이며, 가드가 검증되지
  # 않은 채 통과하는 방향은 아니다(창을 now+10 으로 밀어 강제 초과시키면 "(h) … exit
  # 0(기대: 1)"로 실패함을 확인 — 검수 실측).
  # collision_window_seconds: 선점 시각부터 install.sh 의 date 호출까지의 지연을 흡수하는
  # 여유값. install_directory 가 retire_user_claude_md 보다 먼저 실행되므로(순서는
  # perform_installation 참조) 이 구간은 rules/agents/commands 62개 파일
  # (RULES_FILE_COUNT+AGENTS_FILE_COUNT+COMMANDS_FILE_COUNT) 의 설치와 검증을 포함하는데
  # 실측 0.144초였고, base 초 대비 오프셋은 N=19 관측에서 최대 1(대부분 0)이라 창
  # {0,1,2} 에 여유 슬롯 1개가 남는다(검수 실측). (a)~(g) 의 지연은 무관하다 — 이 창의
  # 기준초(now)는 (g) 종료 뒤 이 (h) 블록에서 새로 계산되므로, (a)~(g) 의 지연은 이미
  # 지나간 뒤라 이 창에 들어오지 않는다.
  local collision_window_seconds=3
  local collision_timestamp collision_candidate_path
  local collision_backup_paths=()
  while IFS= read -r collision_timestamp; do
    [[ -z "$collision_timestamp" ]] && continue
    collision_candidate_path="$sandbox_collision/.claude/CLAUDE.md.$collision_timestamp"
    echo "PRECIOUS EARLIER BACKUP - MUST NOT BE LOST" > "$collision_candidate_path"
    collision_backup_paths+=("$collision_candidate_path")
  done < <(python3 - "$collision_window_seconds" <<'PYEOF'
import datetime
import sys

window_seconds = int(sys.argv[1])
now = datetime.datetime.now()
for offset in range(window_seconds):
    print((now + datetime.timedelta(seconds=offset)).strftime("retired-%Y%m%d-%H%M%S"))
PYEOF
)

  local collision_output collision_exit=0
  collision_output=$(HOME="$sandbox_collision" "$INSTALL_SCRIPT" --scope user 2>&1) || collision_exit=$?
  if [[ "$collision_exit" -ne 1 ]]; then
    record_failure "$test_name" "(h) 동일-초 백업 충돌인데 exit ${collision_exit}(기대: 1)로 종료됨"
    return 1
  fi
  # exit 1 단독으로는 install.sh 가 다른 이유로 조기 실패해도 통과한다(가드 미도달이어도
  # 초록) — 아래 로그 문구 단언이 이를 막는다. 이 문구는 충돌 가드(retire_user_claude_md)
  # 에서만 나오므로 발화 자체가 가드 도달·발화의 증거이고, 가드는 선점된 백업 이름에만
  # 발화하므로 install.sh 가 고른 초가 위 선점 창 안이었다는 것까지 함께 증명한다(창을
  # 벗어났다면 exit 0 이 되어 위 단언에서 먼저 걸린다).
  if ! grep -qF "은퇴 대상 백업 이름이 이미 존재합니다" <<< "$collision_output"; then
    record_failure "$test_name" "(h) exit 1 이 충돌 가드에서 나오지 않음(가드 미도달 — 테스트 전제 불성립)"
    return 1
  fi
  for collision_candidate_path in "${collision_backup_paths[@]}"; do
    if ! grep -qF "PRECIOUS EARLIER BACKUP" "$collision_candidate_path" 2>/dev/null; then
      record_failure "$test_name" "(h) 선재 백업 파일이 덮어써짐(데이터 손실): $collision_candidate_path"
      return 1
    fi
  done
  if [[ ! -f "$sandbox_collision/.claude/CLAUDE.md" ]]; then
    record_failure "$test_name" "(h) 충돌 감지 전에 원본 CLAUDE.md 가 이미 옮겨짐"
    return 1
  fi

  # ---- (i) .claude 읽기 전용 + rules/agents/commands 선존 → 사전 조건은 통과하고
  #      mv 가 EPERM 으로 실패한다. fail-closed(exit 1) + manifest v2 유지를 잠근다.
  #      (g)와의 차이: rules/agents/commands 가 미리 존재해 find_existing_ancestor 가
  #      그 쓰기 가능한 하위 디렉토리로 귀결되므로 check_write_permission(사전 조건)을
  #      통과하고 install_directory 3종이 실제로 끝난 뒤 retire_user_claude_md 의 mv 에서
  #      비로소 실패한다 — mv 대상(CLAUDE.md, 백업 후보)이 .claude 바로 아래라 그 rename
  #      은 .claude 자신의 쓰기 권한을 요구하기 때문이다. ----
  mkdir -p "$sandbox_mvfail/.claude/rules" "$sandbox_mvfail/.claude/agents" \
           "$sandbox_mvfail/.claude/commands"
  printf '오래된 CLAUDE.md 내용\n' > "$sandbox_mvfail/.claude/CLAUDE.md"
  local mvfail_hash
  mvfail_hash=$(compute_sha256_for_test "$sandbox_mvfail/.claude/CLAUDE.md")
  cat > "$sandbox_mvfail/.claude/.coding-harness.json" << MANIFEST_EOF
{
  "version": 2,
  "scope": "user"
}
MANIFEST_EOF
  echo "    \"CLAUDE.md\": \"$mvfail_hash\"" >> "$sandbox_mvfail/.claude/.coding-harness.json"
  #   ↑ 해시를 v2 manifest 대장에 주입해 retire 판정을 유도 ((a)와 동일 기법)
  chmod 555 "$sandbox_mvfail/.claude"

  local mvfail_output mvfail_exit=0
  mvfail_output=$(HOME="$sandbox_mvfail" "$INSTALL_SCRIPT" --scope user 2>&1) || mvfail_exit=$?
  chmod 755 "$sandbox_mvfail/.claude"      # 즉시 복구 (trap 에도 등록)

  if [[ "$mvfail_exit" -ne 1 ]]; then
    record_failure "$test_name" "(i) mv 실패 경로인데 exit ${mvfail_exit}(기대: 1)로 종료됨"
    return 1
  fi
  if [[ ! -f "$sandbox_mvfail/.claude/CLAUDE.md" ]]; then
    record_failure "$test_name" "(i) mv 가 실패했는데 원본 CLAUDE.md 가 사라짐"
    return 1
  fi
  local mvfail_retired_count
  mvfail_retired_count=$(ls -1 "$sandbox_mvfail/.claude/CLAUDE.md.retired-"* 2> /dev/null | wc -l | xargs echo)
  if [[ "$mvfail_retired_count" != "0" ]]; then
    record_failure "$test_name" "(i) mv 가 실패했는데 은퇴 파일이 생성됨: ${mvfail_retired_count}개"
    return 1
  fi
  if ! grep -qF '"version": 2' "$sandbox_mvfail/.claude/.coding-harness.json"; then
    record_failure "$test_name" "(i) mv 실패에도 manifest 가 v3 로 갱신됨(기대: v2 유지)"
    return 1
  fi
  if ! grep -qF "은퇴 실패" <<< "$mvfail_output"; then
    record_failure "$test_name" "(i) stderr 에 '은퇴 실패' 문구가 없음"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T8: --dry-run 부작용 0
test_dry_run_no_side_effect() {
  local test_name="T8"
  local test_desc="--dry-run: 파일시스템 변경 없음"
  log_test_name "$test_name" "$test_desc"

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  cd "$sandbox"

  # 기존 파일 생성
  echo "existing" > existing_file.txt
  local existing_mtime
  existing_mtime=$(stat -f%m existing_file.txt 2>/dev/null || stat -c%Y existing_file.txt 2>/dev/null)
  sleep 1

  # --dry-run 실행
  "$INSTALL_SCRIPT" --scope project --dry-run > /dev/null 2>&1

  # 대상 디렉토리 미생성 확인
  if ! assert_dir_not_exists "./.claude" "./.claude 생성됨"; then
    record_failure "$test_name" "./.claude 디렉토리가 생성됨 (기대: 미생성)"
    return 1
  fi

  # 기존 파일 mtime 불변 확인
  local current_mtime
  current_mtime=$(stat -f%m existing_file.txt 2>/dev/null || stat -c%Y existing_file.txt 2>/dev/null)
  if ! assert_equals "$existing_mtime" "$current_mtime" "파일 mtime"; then
    record_failure "$test_name" "기존 파일의 mtime이 변경됨"
    return 1
  fi

  # ---- T8-1 (MAJOR-1, PRP shell-hardening §17 — S2 검수 1회차 접지): 사전 설치가 있고
  # 그중 한 파일이 modified 인 상태에서 --force --dry-run 이 dry-run 계약(파일시스템
  # 변경 없음)을 어기고 실제로 .bak-* 백업을 만들던 회귀. 위 기본 검사(빈 샌드박스 +
  # --force 없음)는 check_directory_conflict 의 --force 분기(backup_modified_managed_files
  # 호출) 자체에 도달하지 못해 이 회귀를 잡지 못했다 — 그래서 사전 설치 + modified
  # 픽스처로 그 분기를 직접 밟는다(T15-3(H5) 와 같은 픽스처 형태).
  local t8_1_sandbox
  t8_1_sandbox=$(mktemp -d)
  register_cleanup_path "$t8_1_sandbox"
  ( cd "$t8_1_sandbox" && "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 )
  echo "# T8-1 사용자 수정" >> "$t8_1_sandbox/.claude/rules/common/coding-style.md"

  local t8_1_files_before
  t8_1_files_before=$(find "$t8_1_sandbox/.claude" -type f | wc -l | tr -d ' ')

  local t8_1_output t8_1_exit=0
  t8_1_output=$( cd "$t8_1_sandbox" && "$INSTALL_SCRIPT" --scope project --force --dry-run 2>&1 ) \
    || t8_1_exit=$?
  if [[ "$t8_1_exit" -ne 0 ]]; then
    record_failure "$test_name" "T8-1 (MAJOR-1): 사전 설치+modified 상태의 --force --dry-run 이 exit ${t8_1_exit}(기대: 0)"
    return 1
  fi

  # T8-1 양성 단언(S2 검수 2회차 MEDIUM N2): 이 서브체크의 다른 세 단언(exit 0 · 백업
  # 0개 · 파일 수 불변)은 — 그 중 둘은 이 주석보다 아래에 있다 — 전부 불변형이라, 사전 설치를
  # 생략한 빈 샌드박스(--force 분기 자체를 밟지 않는 픽스처)에서도 그대로 통과한다 —
  # check_directory_conflict 의 [[ -d "$target_directory" ]] || return 0 조기 반환 때문이다.
  # backup_modified_managed_files 가 실제로 --force 분기를 실행했다는 것을 dry-run 출력의
  # 계획 줄(log_plan "... (--force 백업)")로 직접 확인한다 — 이 픽스처는 modified 파일이
  # 정확히 1개(coding-style.md)이므로 1줄을 기대한다.
  local t8_1_backup_plan_count
  t8_1_backup_plan_count=$(grep -Fc '(--force 백업)' <<< "$t8_1_output") || true
  if [[ "$t8_1_backup_plan_count" -ne 1 ]]; then
    record_failure "$test_name" "T8-1: --force --dry-run 출력의 (--force 백업) 계획 줄이 ${t8_1_backup_plan_count}개(기대: 1) — backup_modified_managed_files 의 --force 분기가 밟히지 않았을 수 있음"
    return 1
  fi

  local t8_1_backup_count
  t8_1_backup_count=$(find "$t8_1_sandbox/.claude/rules/common" -maxdepth 1 \
    -name 'coding-style.md.bak-*' 2> /dev/null | wc -l | tr -d ' ')
  if [[ "$t8_1_backup_count" != "0" ]]; then
    record_failure "$test_name" "T8-1 (MAJOR-1): --force --dry-run 이 실제로 .bak-* 백업을 생성함(${t8_1_backup_count}개)"
    return 1
  fi

  local t8_1_files_after
  t8_1_files_after=$(find "$t8_1_sandbox/.claude" -type f | wc -l | tr -d ' ')
  if [[ "$t8_1_files_after" != "$t8_1_files_before" ]]; then
    record_failure "$test_name" "T8-1 (MAJOR-1): --force --dry-run 후 대상 파일 수가 변함(전 ${t8_1_files_before} → 후 ${t8_1_files_after})"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T9: --scope 누락 시 usage + exit 1
test_missing_scope() {
  local test_name="T9"
  local test_desc="--scope 누락 시 usage + exit 1"
  log_test_name "$test_name" "$test_desc"

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  cd "$sandbox"

  # --scope 없이 실행
  local exit_code=0
  local output
  output=$("$INSTALL_SCRIPT" 2>&1)
  exit_code=$?

  if ! assert_exit_code 1 "$exit_code" "exit code 1"; then
    record_failure "$test_name" "exit code: 기대=1, 실제=$exit_code"
    return 1
  fi

  # usage 출력 확인 (--scope 문자열 포함)
  if ! echo "$output" | grep -q "\-\-scope"; then
    record_failure "$test_name" "usage 메시지에 --scope 미포함"
    return 1
  fi

  # 파일시스템 변경 없음 확인
  if [[ -d "./.claude" ]]; then
    record_failure "$test_name" "./.claude 디렉토리가 생성됨 (기대: 미생성)"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T10: 쓰기 권한 없음
test_no_write_permission() {
  local test_name="T10"
  local test_desc="쓰기 권한 없음: chmod 500"
  log_test_name "$test_name" "$test_desc"

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  # 읽기 전용으로 변경
  chmod 500 "$sandbox"

  cd "$sandbox"

  # 설치 시도
  local exit_code=0
  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 || exit_code=$?

  # exit 1 확인
  if ! assert_exit_code 1 "$exit_code" "exit code 1"; then
    record_failure "$test_name" "exit code: 기대=1, 실제=$exit_code"
    return 1
  fi

  # 권한 복구 (정리를 위해)
  chmod 755 "$sandbox"

  # 부분 설치 없음 확인
  if [[ -d "$sandbox/.claude" ]]; then
    record_failure "$test_name" "./.claude 디렉토리가 생성됨 (부분 설치)"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T12: paths frontmatter 보존
test_paths_frontmatter_preserved() {
  local test_name="T12"
  local test_desc="paths frontmatter 보존"
  log_test_name "$test_name" "$test_desc"

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  cd "$sandbox"

  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1

  # react/coding-style.md 확인
  local react_file="./.claude/rules/react/coding-style.md"
  if ! assert_file_exists "$react_file" "react/coding-style.md"; then
    record_failure "$test_name" "react/coding-style.md 미존재"
    return 1
  fi

  # 첫 줄이 --- 인지 확인
  local first_line
  first_line=$(head -1 "$react_file")
  if ! assert_equals "---" "$first_line" "첫 줄 YAML marker"; then
    record_failure "$test_name" "첫 줄이 '---'가 아님: $first_line"
    return 1
  fi

  # paths: 문자열 포함 확인
  if ! grep -q "^paths:" "$react_file"; then
    record_failure "$test_name" "paths: 필드 미발견"
    return 1
  fi

  # python/coding-style.md 확인 (결함 7 — rules/python/ 신설, react 검사와 동일 형태)
  local python_file="./.claude/rules/python/coding-style.md"
  if ! assert_file_exists "$python_file" "python/coding-style.md"; then
    record_failure "$test_name" "python/coding-style.md 미존재"
    return 1
  fi

  local python_first_line
  python_first_line=$(head -1 "$python_file")
  if ! assert_equals "---" "$python_first_line" "첫 줄 YAML marker"; then
    record_failure "$test_name" "python/coding-style.md 첫 줄이 '---'가 아님: $python_first_line"
    return 1
  fi

  if ! grep -q "^paths:" "$python_file"; then
    record_failure "$test_name" "python/coding-style.md 에 paths: 필드 미발견"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T13: 상대경로 참조 보존
test_relative_path_references_work() {
  local test_name="T13"
  local test_desc="상대경로 참조 보존"
  log_test_name "$test_name" "$test_desc"

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  cd "$sandbox"

  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1

  # typescript/coding-style.md 확인
  local ts_file="./.claude/rules/typescript/coding-style.md"
  if ! assert_file_exists "$ts_file" "typescript/coding-style.md"; then
    record_failure "$test_name" "typescript/coding-style.md 미존재"
    return 1
  fi

  # ../common/coding-style.md 참조 확인
  if ! grep -q "\.\./common/" "$ts_file"; then
    record_failure "$test_name" "../common/ 상대경로 참조 미발견"
    return 1
  fi

  # 실제 파일이 존재하는지 확인
  local common_file="./.claude/rules/common/coding-style.md"
  if ! assert_file_exists "$common_file" "common/coding-style.md (대상)"; then
    record_failure "$test_name" "상대경로가 가리키는 실제 파일 미존재"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T14: 심볼릭 링크 대상 감지
#
# 한계(비망라, T14-1·T14-2 — PRP shell-hardening §9-3) — 심링크 픽스처는 상대 경로로만
# 재현한다. 절대 경로 링크는 이 환경에서 cp 가 Permission denied 로 끝나 관통 여부를
# 증명하지 못한다(실측). exit 코드만으로는 check_no_symlink_targets 가 실제로 잡았는지
# 판별할 수 없다 — 이 환경의 cp -R 는 source·target 양쪽이 디렉토리인 조합에서 심링크
# 대상 자체를 스스로 거부해("Not a directory") 그 가드가 없어도 exit 코드가 우연히
# 같아진다(실측). 그래서 각 서브체크는 가드 자신의 진단 문구("심볼릭 링크입니다")가
# 출력에 있는지까지 함께 확인한다. 조상 검사는 여기 등장하는 두 깊이(잎의 직속 부모·
# 최상위 관리 디렉토리)만 확인했고, 더 깊은 중간 계층의 조합은 전수 검증하지 않았다.
# 전수 증명이 아니다.
test_symlink_target_warning() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T14"
  local test_desc="심볼릭 링크 대상 감지 및 중단"
  log_test_name "$test_name" "$test_desc"

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  local real_dir
  real_dir=$(mktemp -d)
  register_cleanup_path "$real_dir"

  # 심볼릭 링크 생성
  local symlink_path="$sandbox/symlink"
  ln -s "$real_dir" "$symlink_path"

  cd "$symlink_path"

  # 설치 시도
  local exit_code=0
  local output
  output=$("$INSTALL_SCRIPT" --scope project 2>&1)
  exit_code=$?

  # exit 1 확인 (경고 후 중단)
  if ! assert_exit_code 1 "$exit_code" "exit code 1"; then
    record_failure "$test_name" "exit code: 기대=1, 실제=$exit_code"
    return 1
  fi

  # .claude 디렉토리 미생성 확인
  if [[ -d "./.claude" ]]; then
    record_failure "$test_name" "./.claude 디렉토리가 생성됨 (기대: 미생성)"
    return 1
  fi

  # ---- T14-1 (H3, PRP shell-hardening §9-3): 관리 경로 잎의 조상 디렉토리(예:
  # rules/common)가 심링크면 cp -R 가 그 링크를 관통해 대상 밖에 쓴다 — 쓰기 전에
  # 거부해야 하고 링크 대상 파일의 내용은 그대로여야 한다. 상대 경로 링크로 재현한다
  # (GOTCHA 5 — 절대 경로 링크는 이 환경에서 Permission denied 로 끝나 무엇을 증명했는지
  # 불분명해진다).
  #
  # exit 코드만으로는 판별력이 없다(실측, §9-3 한계 — 이 환경의 cp -R 는 source·target
  # 양쪽이 디렉토리인 경로에서 심링크 대상을 스스로 거부해 "Not a directory"로 실패한다
  # — check_no_symlink_targets 가 없어도 exit 코드는 우연히 같아진다). 그래서 가드
  # 자신의 진단 문구가 출력에 있는지로 판별한다 — 없으면 그 exit 은 이 가드가 아니라
  # cp 자신이 만든 우연의 일치다.
  local h3_root h3_attacker
  h3_root=$(mktemp -d)
  h3_attacker=$(mktemp -d)
  register_cleanup_path "$h3_root" "$h3_attacker"
  echo "원본 보존 확인용" > "$h3_attacker/sentinel.md"
  mkdir -p "$h3_root/project/.claude/rules"
  ( cd "$h3_root/project/.claude/rules" \
    && ln -s "../../../$(basename "$h3_attacker")" common )

  local h3_output h3_exit=0
  h3_output=$( cd "$h3_root/project" && "$INSTALL_SCRIPT" --scope project 2>&1 ) || h3_exit=$?
  if [[ "$h3_exit" -eq 0 ]]; then
    record_failure "$test_name" "T14-1 (H3): 관리 경로 조상(rules/common)이 심링크인데도 설치가 exit 0"
    return 1
  fi
  if ! grep -qE "심볼릭 링크입니다.*rules/common" <<< "$h3_output"; then
    record_failure "$test_name" "T14-1 (H3): check_no_symlink_targets 의 진단 문구가 출력에 없음(다른 원인의 실패로 exit 만 우연히 일치했을 수 있음)"
    return 1
  fi
  if ! grep -qF "원본 보존 확인용" "$h3_attacker/sentinel.md"; then
    record_failure "$test_name" "T14-1 (H3): 심링크 대상 파일의 내용이 변경됨(관통 발생 의심)"
    return 1
  fi

  # ---- T14-2 (H3): 최상위 관리 디렉토리 자체(.claude/rules)가 심링크인 경우도 같다 —
  # 조상 열거가 잎 하나만 보도록 좁아지는 회귀를 잡는다. 판별 근거는 T14-1 과 동일하다.
  local h3b_root h3b_attacker
  h3b_root=$(mktemp -d)
  h3b_attacker=$(mktemp -d)
  register_cleanup_path "$h3b_root" "$h3b_attacker"
  echo "조상 보존 확인용" > "$h3b_attacker/sentinel.md"
  mkdir -p "$h3b_root/project/.claude"
  ( cd "$h3b_root/project/.claude" \
    && ln -s "../../$(basename "$h3b_attacker")" rules )

  local h3b_output h3b_exit=0
  h3b_output=$( cd "$h3b_root/project" && "$INSTALL_SCRIPT" --scope project 2>&1 ) || h3b_exit=$?
  if [[ "$h3b_exit" -eq 0 ]]; then
    record_failure "$test_name" "T14-2 (H3): 최상위 관리 디렉토리(rules) 자체가 심링크인데도 설치가 exit 0"
    return 1
  fi
  if ! grep -qE '심볼릭 링크입니다.*/rules$' <<< "$h3b_output"; then
    record_failure "$test_name" "T14-2 (H3): check_no_symlink_targets 의 진단 문구가 출력에 없음(다른 원인의 실패로 exit 만 우연히 일치했을 수 있음)"
    return 1
  fi
  if ! grep -qF "조상 보존 확인용" "$h3b_attacker/sentinel.md"; then
    record_failure "$test_name" "T14-2 (H3): 심링크 대상 파일의 내용이 변경됨(관통 발생 의심)"
    return 1
  fi

  # ---- T14-3 (H3): --force 는 이 가드를 우회하지 못한다 — check_directory_conflict 의
  # --force 조기 반환과 대비되는 지점이다. --force 의 의미는 "내 수정본을 덮어써도 좋다"
  # 이지 "대상 트리 밖에 써도 좋다"가 아니다.
  local h3_force_exit=0
  ( cd "$h3_root/project" && "$INSTALL_SCRIPT" --scope project --force > /dev/null 2>&1 ) \
    || h3_force_exit=$?
  if [[ "$h3_force_exit" -eq 0 ]]; then
    record_failure "$test_name" "T14-3 (H3): --force 가 심링크 가드를 우회함(기대: 그래도 거부)"
    return 1
  fi
  if ! grep -qF "원본 보존 확인용" "$h3_attacker/sentinel.md"; then
    record_failure "$test_name" "T14-3 (H3): --force 경로에서 심링크 대상 파일의 내용이 변경됨"
    return 1
  fi

  # ---- T14-6 (M3, S1 검수 1회차 — T14-1·T14-2 의 조상 열거는 $target_base_dir/.claude/
  # 하위 상대경로만 만들어, 모든 관리 경로의 최상위 공통 조상인 .claude 자신은 그 열거에
  # 들지 않는다): .claude 자신이 심링크인 신규 설치에서 check_no_symlink_targets 가
  # .claude 자신을 별도로 봐야 닫히는 자리다. install.sh 에 .claude 를 보는 다른 검사는
  # 없다 — is_symlinked_path 의 유일한 호출부는 그 부모($target_base_dir)를 본다
  # (검수 2회차 정정: 앞 판은 그 검사가 「cd 실패로 무력화된다」고 적었으나 반증됐다).
  local h6_root h6_attacker
  h6_root=$(mktemp -d)
  h6_attacker=$(mktemp -d)
  register_cleanup_path "$h6_root" "$h6_attacker"
  echo "최상위 조상 보존 확인용" > "$h6_attacker/sentinel.md"
  mkdir -p "$h6_root/project"
  ( cd "$h6_root/project" && ln -s "../../$(basename "$h6_attacker")" .claude )

  local h6_output h6_exit=0
  h6_output=$( cd "$h6_root/project" && "$INSTALL_SCRIPT" --scope project 2>&1 ) || h6_exit=$?
  if [[ "$h6_exit" -eq 0 ]]; then
    record_failure "$test_name" "T14-6 (M3): .claude 자신이 심링크인 신규 설치에서도 설치가 exit 0 — 조상 심링크 관통 가드 회귀 의심"
    return 1
  fi
  if ! grep -qE '심볼릭 링크입니다.*/\.claude$' <<< "$h6_output"; then
    record_failure "$test_name" "T14-6 (M3): check_no_symlink_targets 의 .claude 진단 문구가 출력에 없음(다른 원인의 실패로 exit 만 우연히 일치했을 수 있음)"
    return 1
  fi
  if ! grep -qF "최상위 조상 보존 확인용" "$h6_attacker/sentinel.md"; then
    record_failure "$test_name" "T14-6 (M3): 심링크 대상 파일의 내용이 변경됨(관통 발생 의심)"
    return 1
  fi

  # ---- T14-7 (M3): --force 도 .claude 자신의 심링크 가드를 우회하지 못한다 —
  # check_no_symlink_targets 는 force_overwrite 를 참조하지 않으므로(T14-3 과 같은 근거)
  # 위 h6 픽스처를 재사용해 확인한다.
  local h6_force_exit=0
  ( cd "$h6_root/project" && "$INSTALL_SCRIPT" --scope project --force > /dev/null 2>&1 ) \
    || h6_force_exit=$?
  if [[ "$h6_force_exit" -eq 0 ]]; then
    record_failure "$test_name" "T14-7 (M3): --force 가 .claude 심링크 가드를 우회함(기대: 그래도 거부)"
    return 1
  fi
  if ! grep -qF "최상위 조상 보존 확인용" "$h6_attacker/sentinel.md"; then
    record_failure "$test_name" "T14-7 (M3): --force 경로에서 심링크 대상 파일의 내용이 변경됨"
    return 1
  fi

  # ---- T14-4 (H4, PRP shell-hardening §9-4): $PWD 가 $HOME 과 실경로로 같으면
  # --scope project 를 거부하고 .claude/ 를 만들지 않는다.
  local h4_home
  h4_home=$(mktemp -d)
  register_cleanup_path "$h4_home"
  local h4_exit=0
  ( cd "$h4_home" && HOME="$h4_home" "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 ) \
    || h4_exit=$?
  if [[ "$h4_exit" -eq 0 ]]; then
    note_failure "T14-4 (H4): \$PWD == \$HOME 인데 --scope project 가 exit 0"
  fi
  if [[ -d "$h4_home/.claude" ]]; then
    note_failure "T14-4 (H4): \$PWD == \$HOME 거부 시에도 .claude/ 가 생성됨"
  fi

  # ---- T14-5 (H4): 기존 user 매니페스트가 있는 $HOME 에서도 거부되고 그 매니페스트는
  # 변경되지 않는다.
  local h4_existing_home
  h4_existing_home=$(mktemp -d)
  register_cleanup_path "$h4_existing_home"
  ( HOME="$h4_existing_home" "$INSTALL_SCRIPT" --scope user > /dev/null 2>&1 )
  local h4_manifest="$h4_existing_home/.claude/.coding-harness.json"
  local h4_before
  h4_before=$(cat "$h4_manifest")
  local h4b_exit=0
  ( cd "$h4_existing_home" && HOME="$h4_existing_home" "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 ) \
    || h4b_exit=$?
  if [[ "$h4b_exit" -eq 0 ]]; then
    note_failure "T14-5 (H4): 기존 user 설치본이 있는 \$HOME 에서도 --scope project 가 exit 0"
  fi
  local h4_after
  h4_after=$(cat "$h4_manifest" 2>/dev/null || echo "__MISSING__")
  if [[ "$h4_after" != "$h4_before" ]]; then
    note_failure "T14-5 (H4): 거부된 시도 후 기존 user manifest 내용이 변경됨"
  fi

  # ---- T14-8 (CRITICAL-1, PRP shell-hardening §17 — S2 검수 1회차 접지): --force 로
  # modified 파일을 덮어쓰기 전에 backup_modified_managed_files 가 형제 위치에 만드는
  # 백업 이름(<잎>.bak-<타임스탬프>)이 대상 트리 밖 파일을 가리키는 심볼릭 링크로
  # 선점되면, cp -p 가 그 링크를 관통해 대상 밖 파일을 덮어쓴다(검수 1회차 실측). 이
  # 시나리오는 cp -R 의 디렉토리 재귀(T14-1·T14-2 가 쓰는 것)가 아니라 cp -p 의 단일
  # 파일 복사라 절대 경로 심링크에서도 이 환경의 "Permission denied" 문제가 없다(검수
  # 실측) — 그래서 위 항목들과 달리 절대 경로로 심는다. 백업 파일명은 초 단위
  # 타임스탬프라 install.sh 의 date 호출이 정확히 어느 초를 고를지 이 테스트가 미리 알
  # 수 없다 — 위 T7 그룹의 (h) 블록(retire_user_claude_md 동일-초 충돌 검사)과 같은
  # 이유로, 현재 초부터 8초 창 전부에 심링크를 선점해 install.sh 가 그 창 안 어느 초를
  # 고르든 성립하게 만든다(python3 로 계산 — GNU/BSD 가 갈리는 date -d/-v 대신 이 파일의
  # 기존 관행).
  local h5sym_sandbox
  h5sym_sandbox=$(mktemp -d)
  register_cleanup_path "$h5sym_sandbox"
  ( cd "$h5sym_sandbox" && "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 )
  local h5sym_target_path="$h5sym_sandbox/.claude/rules/common/coding-style.md"
  echo "# T14-8 사용자 수정" >> "$h5sym_target_path"

  local h5sym_victim_dir
  h5sym_victim_dir=$(mktemp -d)
  register_cleanup_path "$h5sym_victim_dir"
  local h5sym_victim_path="$h5sym_victim_dir/outside.md"
  echo "관통 확인용 원본" > "$h5sym_victim_path"

  local h5sym_window_seconds=8
  local h5sym_suffix
  while IFS= read -r h5sym_suffix; do
    [[ -z "$h5sym_suffix" ]] && continue
    ln -s "$h5sym_victim_path" "${h5sym_target_path}.${h5sym_suffix}"
  done < <(python3 - "$h5sym_window_seconds" <<'PYEOF'
import datetime
import sys

window_seconds = int(sys.argv[1])
now = datetime.datetime.now()
for offset in range(window_seconds):
    print((now + datetime.timedelta(seconds=offset)).strftime("bak-%Y%m%d-%H%M%S"))
PYEOF
)

  local h5sym_exit=0
  ( cd "$h5sym_sandbox" && "$INSTALL_SCRIPT" --scope project --force > /dev/null 2>&1 ) \
    || h5sym_exit=$?
  if [[ "$h5sym_exit" -eq 0 ]]; then
    note_failure "T14-8 (CRITICAL-1): 백업 이름이 심링크로 선점됐는데도 --force 가 exit 0"
  fi
  if ! grep -qF "관통 확인용 원본" "$h5sym_victim_path"; then
    note_failure "T14-8 (CRITICAL-1): 대상 트리 밖 파일(outside.md)의 내용이 변경됨 — 백업 심링크 관통"
  fi

  finish_group "$test_name"
}

# T15: D1 전용 — diff 감지 및 --force 요구
#
# 한계(비망라, T15-1 — PRP shell-hardening §9-1, S1 검수 1회차 m4 로 픽스처 갱신) — diff
# 오류(상태 2 이상) 재현은 이 환경(Apple diff, FreeBSD 기반)에서 두 형태를 실측했다 —
# "대상측 파일 하나가 읽기 금지"(T15-1 이 쓰는 것)와 "소스 디렉토리 자체가 사라진다"
# (T15-2 가 쓰는 것, m2 의 find 실패 검사를 겨냥). **대상측 서브디렉토리 전체**를 chmod
# 로 읽지 못하게 막는 방식은 이 diff 구현이 그 상황에서도 상태 0(차이 있는 파일이
# 없으면) 또는 1(다른 차이가 있으면)만 내 재현되지 않았다 — 대상에만 있는 접근 불가
# 디렉토리는 diff 가 "Only in target"으로도 못 만들고 조용히 건너뛴다. 다른 diff
# 구현(GNU 등)이나 다른 OS 에서의 동작은 확인하지 않았다. 전수 증명이 아니다.
test_diff_detection_requires_force() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T15"
  local test_desc="D1: diff 감지 및 --force 요구(T15-1·T15-2) + --force 백업(T15-3, H5)"
  log_test_name "$test_name" "$test_desc"

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  cd "$sandbox"

  # 초기 설치
  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1

  # rules 파일 수정
  echo "# modified" >> "./.claude/rules/common/coding-style.md"

  # 재실행 (--force 없음)
  local exit_code=0
  local output
  output=$("$INSTALL_SCRIPT" --scope project 2>&1)
  exit_code=$?

  # exit 1 확인
  if ! assert_exit_code 1 "$exit_code" "exit code 1"; then
    record_failure "$test_name" "exit code: 기대=1, 실제=$exit_code (diff 미감지)"
    return 1
  fi

  # 차이 파일 목록이 파일명과 함께 실제로 출력돼야 한다 (D1 스펙 요구사항)
  if ! echo "$output" | grep -q "common/coding-style.md"; then
    record_failure "$test_name" "차이 파일 목록에 common/coding-style.md 가 없음"
    return 1
  fi

  # --force 없이는 수정 내용이 보존돼야 한다 (덮어쓰지 않았음을 확인)
  if ! grep -q "^# modified$" "./.claude/rules/common/coding-style.md"; then
    record_failure "$test_name" "--force 없이 사용자 수정이 덮어써졌음"
    return 1
  fi

  # --force 재실행 후 성공 확인
  exit_code=0
  "$INSTALL_SCRIPT" --scope project --force > /dev/null 2>&1 || exit_code=$?
  if ! assert_exit_code 0 "$exit_code" "exit code 0 (--force)"; then
    record_failure "$test_name" "--force 재실행 실패"
    return 1
  fi

  # ---- T15-1 (H1, PRP shell-hardening §9-1): diff 자체가 실패(상태 2 이상)하면 "결측
  # 없음"이 아니라 설치 실패로 보고된다. 대상측 파일 하나를 chmod 000 으로 읽지 못하게
  # 만들어 diff -rq 가 그 파일에서 "Permission denied"로 상태 2 를 낸다(실측). 대상측
  # **서브디렉토리** 전체를 chmod 로 막는 방식은 재현되지 않았지만(위 한계 절), **파일**
  # 단위 chmod 는 안정적으로 상태 2 를 낸다.
  #
  # 이전 회차는 소스(rules/) 자체를 지워 재현했다 — 그런데 그 방식은 대상이 아니라
  # 소스측을 건드려, check_no_symlink_targets 의 관리 파일 열거(find)도 함께 실패시켰다.
  # m2 수정(아래 T15-2) 이후 그 열거가 fail-closed 로 바뀌어 여기서 노리는 diff 자체의
  # 실패보다 먼저 잡히므로, 그 방식으로는 더 이상 이 서브체크를 독립적으로 재현하지
  # 못한다 — 대상측 파일 chmod 로 바꿔 소스측 열거와 겹치지 않게 분리했다(S1 검수
  # 1회차 m4).
  local repo_copy_h1 sandbox_h1
  repo_copy_h1=$(mktemp -d)
  sandbox_h1=$(mktemp -d)
  register_cleanup_path "$repo_copy_h1" "$sandbox_h1"
  cp -R "$REPO_ROOT/rules" "$REPO_ROOT/agents" "$REPO_ROOT/commands" "$repo_copy_h1/"
  cp "$REPO_ROOT/install.sh" "$repo_copy_h1/"

  ( cd "$sandbox_h1" && "$repo_copy_h1/install.sh" --scope project > /dev/null 2>&1 )
  local h1_probe_file="$sandbox_h1/.claude/rules/common/coding-style.md"
  chmod 000 "$h1_probe_file"

  # exit 코드만으로는 판별력이 없다(실측) — cp -R 도 이 chmod 된 파일을 덮어쓰지 못해
  # 결국 "복사 실패"로 exit 1 을 낸다(H1 없이도 같다). H1 이 실제로 잡았는지는 그
  # 자신의 진단 문구("diff 검사 실패")로만 구분된다.
  local h1_output h1_exit=0
  h1_output=$( cd "$sandbox_h1" && "$repo_copy_h1/install.sh" --scope project 2>&1 ) || h1_exit=$?
  chmod 644 "$h1_probe_file"
  if [[ "$h1_exit" -eq 0 ]]; then
    record_failure "$test_name" "T15-1 (H1): 대상 파일이 읽기 금지인데도 재설치가 exit 0 — diff 오류가 삼켜짐(결측 없음으로 오분류)"
    return 1
  fi
  if ! grep -qF "diff 검사 실패" <<< "$h1_output"; then
    record_failure "$test_name" "T15-1 (H1): diff fail-loud 진단 문구가 출력에 없음(다른 원인의 실패로 exit 만 우연히 일치했을 수 있음)"
    return 1
  fi

  # ---- T15-2 (m2, S1 검수 1회차 — check_no_symlink_targets 가 find 실패·0건에서 조용히
  # 통과한다): find | while | sort -u 파이프라인은 마지막 단(sort)의 종료 상태만 남겨
  # find 자신의 오류를 지운다. 레포 사본에서 rules/ 를 통째로 지운다(agents·commands
  # 는 남겨 후보 자체는 0건이 아니게 만든다 — 이 결함은 find 의 부분 실패이지 "후보
  # 0건"이 아니다). 위 T15-1 이 이전 회차에 쓰던 것과 같은 픽스처를 이번에는 그 자신의
  # 회귀 검사로 쓴다.
  local repo_copy_m2 sandbox_m2
  repo_copy_m2=$(mktemp -d)
  sandbox_m2=$(mktemp -d)
  register_cleanup_path "$repo_copy_m2" "$sandbox_m2"
  cp -R "$REPO_ROOT/rules" "$REPO_ROOT/agents" "$REPO_ROOT/commands" "$repo_copy_m2/"
  cp "$REPO_ROOT/install.sh" "$repo_copy_m2/"
  rm -rf "$repo_copy_m2/rules"

  local m2_output m2_exit=0
  m2_output=$( cd "$sandbox_m2" && "$repo_copy_m2/install.sh" --scope project 2>&1 ) || m2_exit=$?
  if [[ "$m2_exit" -eq 0 ]]; then
    record_failure "$test_name" "T15-2 (m2): 관리 파일 열거(find)가 부분 실패했는데도 설치가 exit 0 — check_no_symlink_targets 가 find 실패를 삼킴(fail-open)"
    return 1
  fi
  if ! grep -qF "관리 파일 열거 실패" <<< "$m2_output"; then
    record_failure "$test_name" "T15-2 (m2): find 실패 진단 문구가 출력에 없음(다른 원인의 실패로 exit 만 우연히 일치했을 수 있음)"
    return 1
  fi

  # ---- T15-3 (H5, PRP shell-hardening §9-5): --force 가 modified 파일을 덮어쓰기 전에
  # 형제 위치에 .bak-<타임스탬프> 백업을 만들고 목록을 표시한다. stale(대장과 일치 —
  # 우리가 설치한 그대로인 낡은 사본)은 백업하지 않는다. 한 픽스처에 modified·stale 을
  # 함께 둬야 "modified 만 골라 백업한다"가 실제로 검증된다 — 둘 중 하나만 있으면 분류를
  # 통과시키는 아무 구현이나 통과한다. 독립 서브체크라 note_failure 를 쓴다(설계 §10-2).
  local repo_copy_h5 sandbox_h5
  repo_copy_h5=$(mktemp -d)
  sandbox_h5=$(mktemp -d)
  register_cleanup_path "$repo_copy_h5" "$sandbox_h5"
  cp -R "$REPO_ROOT/rules" "$REPO_ROOT/agents" "$REPO_ROOT/commands" "$repo_copy_h5/"
  cp "$REPO_ROOT/install.sh" "$repo_copy_h5/"
  ( cd "$sandbox_h5" && "$repo_copy_h5/install.sh" --scope project > /dev/null 2>&1 )

  # modified: 대상측을 사용자가 고친 것처럼 만든다(대장 해시와 불일치) — 백업에 담겨야
  # 하는 내용을 미리 사본으로 남겨 뒤에서 대조한다.
  local h5_modified_path="$sandbox_h5/.claude/rules/common/coding-style.md"
  echo "# T15-3 사용자 수정" >> "$h5_modified_path"
  local h5_reference_copy
  h5_reference_copy=$(mktemp)
  register_cleanup_path "$h5_reference_copy"
  cp "$h5_modified_path" "$h5_reference_copy"

  # stale: 레포측(설치 소스)만 전진시킨다 — 대상은 그대로라 대장 해시와 일치한다.
  echo "# T15-3 레포 전진" >> "$repo_copy_h5/rules/common/testing.md"

  local h5_output h5_exit=0
  h5_output=$( cd "$sandbox_h5" && "$repo_copy_h5/install.sh" --scope project --force 2>&1 ) || h5_exit=$?
  if [[ "$h5_exit" -ne 0 ]]; then
    note_failure "T15-3 (H5): --force 재설치가 exit ${h5_exit}로 실패함(기대: 0) — 출력: $(tail -3 <<< "$h5_output")"
  fi
  if ! grep -qF "common/coding-style.md" <<< "$h5_output"; then
    note_failure "T15-3 (H5): --force 출력에 수정 파일 목록(common/coding-style.md)이 없음"
  fi

  local h5_modified_backup
  h5_modified_backup=$(find "$sandbox_h5/.claude/rules/common" -maxdepth 1 \
    -name 'coding-style.md.bak-*' 2> /dev/null | head -1)
  if [[ -z "$h5_modified_backup" ]]; then
    note_failure "T15-3 (H5): modified 파일(coding-style.md)의 .bak-* 백업이 없음"
  elif ! cmp -s "$h5_reference_copy" "$h5_modified_backup"; then
    note_failure "T15-3 (H5): 백업 파일 내용이 덮어쓰기 전 원본과 다름 — $h5_modified_backup"
  fi

  local h5_stale_backup
  h5_stale_backup=$(find "$sandbox_h5/.claude/rules/common" -maxdepth 1 \
    -name 'testing.md.bak-*' 2> /dev/null | head -1)
  if [[ -n "$h5_stale_backup" ]]; then
    note_failure "T15-3 (H5): stale 파일(testing.md)이 백업됨(기대: 백업하지 않음) — $h5_stale_backup"
  fi

  finish_group "$test_name"
}

# 모든 테스트 등록 및 실행
# T16: 소유권 원칙 — 대상에만 있는 파일은 충돌로 보지 않고 삭제하지도 않는다.
# 회귀 방지: 사용자의 ~/.claude/agents 에는 배포 대상 4개 외 수십 개가 공존한다.
test_unmanaged_files_preserved() {
  local test_name="T16"
  local test_desc="소유권 원칙: 대상에만 있는 파일 보존 및 충돌 미판정"
  log_test_name "$test_name" "$test_desc"

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  cd "$sandbox"
  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1

  # 배포 대상이 아닌 파일을 대상 디렉토리에 추가
  echo "# 사용자 소유 에이전트" > "./.claude/agents/my-own-agent.md"
  mkdir -p "./.claude/rules/custom"
  echo "# 사용자 보유 규칙" > "./.claude/rules/custom/team-style.md"

  # --force 없이 재실행: 충돌로 판정하지 않아야 한다
  local exit_code=0
  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 || exit_code=$?
  if ! assert_exit_code 0 "$exit_code" "exit code 0 (남의 파일은 충돌이 아님)"; then
    record_failure "$test_name" "대상 전용 파일을 충돌로 오판: exit=$exit_code"
    return 1
  fi

  # 남의 파일이 보존돼야 한다
  if [[ ! -f "./.claude/agents/my-own-agent.md" ]]; then
    record_failure "$test_name" "사용자 소유 에이전트가 삭제됨"
    return 1
  fi
  if [[ ! -f "./.claude/rules/custom/team-style.md" ]]; then
    record_failure "$test_name" "사용자 보유 규칙이 삭제됨"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T17: .md 커맨드 8종(의존 사슬 7종 + 독립 커맨드 1종)이 설치되고 의존 사슬이 닫히는지 확인.
# commands/ 최상위 파일 수(COMMANDS_FILE_COUNT, T22-138)는 이제 이 8개 .md 파일뿐이다 —
# 대시보드 자산(옛 템플릿·헬퍼·렌더러 3개)은 hub/bin 으로 전부 옮겨갔다(HD1, docs/prps/
# dashboard-into-hub.md).
test_commands_installed() {
  local test_name="T17"
  local test_desc=".md 커맨드 8종 설치 및 의존 사슬 완결"
  log_test_name "$test_name" "$test_desc"

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  cd "$sandbox"
  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1

  local command_name
  for command_name in prp-prd prp-plan prp-implement prp-pr prp-commit code-review harness-update hub; do
    if [[ ! -f "./.claude/commands/$command_name.md" ]]; then
      record_failure "$test_name" "$command_name.md 미설치"
      return 1
    fi
  done

  # 설치된 커맨드가 참조하는 다른 커맨드가 모두 설치돼 있어야 한다 (사슬 완결)
  local referenced
  for referenced in $(grep -rhoE '/(prp-[a-z]+|code-review)\b' ./.claude/commands/ | sort -u | tr -d '/'); do
    if [[ ! -f "./.claude/commands/$referenced.md" ]]; then
      record_failure "$test_name" "참조되지만 미설치인 커맨드: $referenced"
      return 1
    fi
  done

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T18: 전역 커맨드와 다를 때 경고, 같을 때 안내 (--scope project)
test_global_command_overlap_report() {
  local test_name="T18"
  local test_desc="전역 커맨드 비교 보고"
  log_test_name "$test_name" "$test_desc"

  local sandbox sandbox_home
  sandbox=$(mktemp -d)
  sandbox_home=$(mktemp -d)
  register_cleanup_path "$sandbox" "$sandbox_home"

  # 가짜 전역: 5개는 동일, prp-plan 만 다르게
  mkdir -p "$sandbox_home/.claude/commands"
  cp "$REPO_ROOT/commands"/*.md "$sandbox_home/.claude/commands/"
  echo "# 전역에서 수정됨" >> "$sandbox_home/.claude/commands/prp-plan.md"

  cd "$sandbox"
  local output
  output=$(HOME="$sandbox_home" "$INSTALL_SCRIPT" --scope project 2>&1)

  if ! echo "$output" | grep -q "전역 커맨드와 내용이 다릅니다.*prp-plan"; then
    record_failure "$test_name" "전역 불일치 경고에 prp-plan 이 없음"
    return 1
  fi
  # 우선순위 방향이 사실과 맞아야 한다: 커맨드는 전역 > 프로젝트 (skills 문서)
  if ! echo "$output" | grep -q "전역이 프로젝트보다 우선"; then
    record_failure "$test_name" "우선순위 안내가 없거나 방향이 틀림 (전역>프로젝트여야 함)"
    return 1
  fi
  # docs/prps/dashboard-into-hub.md HD1: commands/ 가 이제 8개 전부 .md 라(옛 12개 중
  # 3개는 .html/.py 라 애초에 이 픽스처의 cp *.md 대상이 아니었다) prp-plan 1개가
  # differ 로 빠지면 동일 판정은 7개다(8 - 1).
  if ! echo "$output" | grep -q "전역에 동일한 커맨드 7개"; then
    record_failure "$test_name" "동일 7개 안내가 없음"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T19: --scope user 는 대상이 곧 전역이므로 비교 보고를 생략한다
test_global_report_skipped_for_user_scope() {
  local test_name="T19"
  local test_desc="--scope user 는 전역 비교 생략"
  log_test_name "$test_name" "$test_desc"

  local sandbox sandbox_home
  sandbox=$(mktemp -d)
  sandbox_home=$(mktemp -d)
  register_cleanup_path "$sandbox" "$sandbox_home"

  mkdir -p "$sandbox_home/.claude/commands"
  cp "$REPO_ROOT/commands"/*.md "$sandbox_home/.claude/commands/"
  echo "# 전역에서 수정됨" >> "$sandbox_home/.claude/commands/prp-plan.md"

  cd "$sandbox"
  local output
  output=$(HOME="$sandbox_home" "$INSTALL_SCRIPT" --scope user --force 2>&1)

  if echo "$output" | grep -q "전역"; then
    record_failure "$test_name" "--scope user 인데 전역 비교 메시지가 출력됨"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T20: Manifest 생성 확인
test_manifest_created_after_install() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T20"
  local test_desc="Manifest 생성 및 기본 검증"
  log_test_name "$test_name" "$test_desc"

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  cd "$sandbox"
  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1

  # Manifest 파일 존재 확인
  if ! assert_file_exists "./.claude/.coding-harness.json" "manifest 파일"; then
    record_failure "$test_name" "manifest 파일 미존재"
    return 1
  fi

  # Manifest 필드 검증 (grep 사용, jq 없음)
  local manifest_content
  manifest_content=$(cat "./.claude/.coding-harness.json")

  if ! echo "$manifest_content" | grep -q '"version": 3'; then
    record_failure "$test_name" "version 필드 미발견 또는 잘못됨"
    return 1
  fi

  if ! echo "$manifest_content" | grep -q '"scope": "project"'; then
    record_failure "$test_name" "scope 필드 미발견 또는 값 잘못됨"
    return 1
  fi

  if ! echo "$manifest_content" | grep -q '"repo_path"'; then
    record_failure "$test_name" "repo_path 필드 미발견"
    return 1
  fi

  # ---- T20-1 (H2 원자성, PRP shell-hardening §9-2·§10-2): manifest 쓰기 도중 실패해도
  # 기존 파일이 온전하고 임시 파일이 남지 않는다. save_manifest_file 이 mktemp+mv 원자
  # 교체로 바뀐 것을 고정한다(선례: hub_atomic_write.atomic_write_text). .claude/ 자체를
  # 쓰기 금지로 만들어 mktemp 단계에서만 실패하게 한다 — 하위 rules/agents/commands 는
  # 그대로 쓰기 가능해 복사는 성공하고 manifest 쓰기만 막힌다(격리).
  #
  # 한계(기록, §10-3 판정): 이 검사는 "임시 파일 잔존 없음"과 "실패 시 기존 파일 불변"만
  # 본다 — 교체가 실제로 mv(원자적 rename)인지는 기계로 확인하지 못한다. mv 를 cp 로
  # 바꾸는 변조는 이 검사를 통과할 수 있다.
  local atomic_manifest="$sandbox/.claude/.coding-harness.json"
  # 멱등성 단락(installed_at 제외 비교)을 피해 실제로 재기록을 시도하게 만든다 — 그러지
  # 않으면 save_manifest_file 이 "변경 없음"으로 조기 반환해 mktemp 단계에 도달하지
  # 못한다(재현 확인). scope 값 하나를 손으로 바꿔 다음 빌드 결과와 달라지게 만든다.
  sed -i.bak_atomic_probe 's/"scope": "project"/"scope": "project-atomic-probe"/' "$atomic_manifest"
  rm -f "${atomic_manifest}.bak_atomic_probe"
  local atomic_before
  atomic_before=$(cat "$atomic_manifest")
  chmod 555 "$sandbox/.claude"
  local atomic_exit=0
  ( cd "$sandbox" && "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 ) || atomic_exit=$?
  chmod 755 "$sandbox/.claude"
  if [[ "$atomic_exit" -eq 0 ]]; then
    note_failure "T20-1 (H2 원자성): .claude 쓰기 금지에서도 재설치가 exit 0 — manifest 쓰기 실패가 감지되지 않음"
  fi
  local atomic_after
  atomic_after=$(cat "$atomic_manifest" 2>/dev/null || echo "__MISSING__")
  if [[ "$atomic_after" != "$atomic_before" ]]; then
    note_failure "T20-1 (H2 원자성): 쓰기 실패 후 기존 manifest 내용이 변경됨(비원자적 교체 의심)"
  fi
  local atomic_leftover
  atomic_leftover=$(find "$sandbox/.claude" -maxdepth 1 -name '.coding-harness.json.*' 2>/dev/null | wc -l | tr -d ' ')
  if [[ "$atomic_leftover" -ne 0 ]]; then
    note_failure "T20-1 (H2 원자성): 임시 manifest 파일이 정리되지 않고 남음(${atomic_leftover}건)"
  fi

  # ---- T20-2 (M2, S1 검수 1회차 — 신규 설치 manifest 권한 회귀): mktemp 산출물은 항상
  # 0600 이다. 기존 파일 모드 보존이 "기존 파일이 있을 때"만 동작해, 최초 설치(대상에
  # manifest 가 아직 없음)에는 그 0600 이 그대로 최종 모드가 되는 회귀가 있었다 — 이
  # 함수 주석이 막겠다고 선언한 "사용자의 manifest 권한이 조용히 좁아진다"가 생성
  # 분기에서 그대로 일어난 형태다. umask 를 022 로 고정해 재현을 결정적으로 만든다.
  local mode_sandbox fresh_install_mode
  mode_sandbox=$(mktemp -d)
  register_cleanup_path "$mode_sandbox"
  fresh_install_mode=$(
    cd "$mode_sandbox" || exit 1
    umask 022
    "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1
    stat -f '%OLp' ".claude/.coding-harness.json" 2> /dev/null \
      || stat -c '%a' ".claude/.coding-harness.json" 2> /dev/null
  )
  if [[ "$fresh_install_mode" != "644" ]]; then
    note_failure "T20-2 (M2): 신규 설치 manifest 권한이 ${fresh_install_mode:-<확인 실패>}(기대: umask(022) 반영 기본 모드 644)"
  fi

  finish_group "$test_name"
}

# T21: Manifest 필드 완결성 및 dry-run 미생성
test_manifest_fields_complete() {
  local test_name="T21"
  local test_desc="Manifest 필드 완결성 및 dry-run 검증"
  log_test_name "$test_name" "$test_desc"

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  cd "$sandbox"
  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1

  local manifest_content
  manifest_content=$(cat "./.claude/.coding-harness.json")

  # 필수 필드 확인
  if ! echo "$manifest_content" | grep -q '"installed_at"'; then
    record_failure "$test_name" "installed_at 필드 미발견"
    return 1
  fi

  if ! echo "$manifest_content" | grep -q '"installed_from_commit"'; then
    record_failure "$test_name" "installed_from_commit 필드 미발견"
    return 1
  fi

  if ! echo "$manifest_content" | grep -q '"target_base_dir"'; then
    record_failure "$test_name" "target_base_dir 필드 미발견"
    return 1
  fi

  if ! echo "$manifest_content" | grep -q '"files_count"'; then
    record_failure "$test_name" "files_count 필드 미발견"
    return 1
  fi

  # 결함 4 — v2 해시 대장(files) 필드 존재 확인
  if ! echo "$manifest_content" | grep -q '"files": {'; then
    record_failure "$test_name" "files 대장 필드 미발견 (manifest v2)"
    return 1
  fi

  # dry-run 시 manifest 미생성 확인
  local sandbox_dry
  sandbox_dry=$(mktemp -d)
  register_cleanup_path "$sandbox" "$sandbox_dry"

  cd "$sandbox_dry"
  "$INSTALL_SCRIPT" --scope project --dry-run > /dev/null 2>&1

  if [[ -f "./.claude/.coding-harness.json" ]]; then
    record_failure "$test_name" "--dry-run 시 manifest가 생성됨 (기대: 미생성)"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T22: dashboard 템플릿 무결성 — LLM 지시문 방식이라 런타임 Edit 결과는 검증 대상이 아니고,
# 설치·문서 정합성만 자동 검증한다 (하위 검증 T22-1~T22-169). T22-168·T22-169(PRP
# shell-hardening §10-2)는 dashboard 가 아니라 commands/harness-update.md·frontmatter 3종의
# 문면 정합성이다 — 그 PRP 가 이 그룹을 "문면 그룹" 접두로 명시적으로 지정했다(축적된
# 문서 정합성 검사의 공용 자리, T22-162 의 .gitignore 검사가 이미 같은 성격이다).
#
# 한계(비망라, T22-165, PRP tests-hardening §9 B1) — T22-165 는 잔재 순회 루프의 목록
# 길이(건수)만 본다. 항목이 통째로 다른 문자열로 바뀌어도 건수가 그대로면 이 단정은
# 발화하지 않는다 — 개별 문자열이 실제로 잔재인지는 각 반복의 grep 자체가 맡는다.
# 전수 증명이 아니다.
test_dashboard_template_integrity() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T22"
  local test_desc="dashboard 템플릿 무결성 + harness-update.md·frontmatter 3종 문면 정합성 (T22-1~T22-175, dashboard-native-data-source PRP 로 재작성)"
  log_test_name "$test_name" "$test_desc"

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  cd "$sandbox"
  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1

  # 재조준(docs/prps/dashboard-into-hub.md HD1·HD4 — M1): 대시보드 4파일이 commands/ 에서
  # hub/bin·hub/README.md 로 전부 옮겨갔다. hub/bin·hub/README 는 이 install.sh(coding-harness)
  # 가 배포하지 않으므로(허브는 별도 설치기, hub/install.sh) 샌드박스 설치 결과가 아니라
  # 레포 원본을 본다 — T23 의 readme_file 과 동일 방식.
  local dashboard_command_file="$REPO_ROOT/hub/README.md"
  local dashboard_template_file="$REPO_ROOT/hub/bin/hub_dashboard_template.html"
  local dashboard_helper_file="$REPO_ROOT/hub/bin/hub_dashboard_log.py"
  local dashboard_render_file="$REPO_ROOT/hub/bin/hub_dashboard_render.py"
  # docs/prps/ 는 install.sh 가 배포하는 대상이 아니므로(레포 자체 문서) 설치된 사본이 아니라
  # 레포 원본을 검사한다 — T23 의 readme_file 과 동일 방식.
  local dashboard_rationale_file="$REPO_ROOT/docs/prps/dashboard-rationale.md"

  # T22-1(역방향, HD1 — dashboard-into-hub PRP): 샌드박스 설치 결과에 commands/dashboard* 가
  # 하나도 없다. 허브는 coding-harness 의 install.sh 가 배포하지 않는 별도 자산이라, 이 설치기가
  # 만든 결과에는 대시보드 관련 무엇도 남지 않아야 한다.
  local leftover_dashboard_count
  leftover_dashboard_count=$(find "./.claude/commands" -maxdepth 1 -name 'dashboard*' 2> /dev/null | wc -l | tr -d ' ')
  if [[ "$leftover_dashboard_count" -ne 0 ]]; then
    record_failure "$test_name" "T22-1: 샌드박스 설치 결과에 commands/dashboard* 가 ${leftover_dashboard_count}건 있음(HD1 위반)"
    return 1
  fi

  # 합본을 만들려면 템플릿·기록기·렌더러 3종 + hub/README.md 도 레포에 있어야 한다 — 이
  # 체크는 "존재"만 확인하는 전제 조건이다. 템플릿 내용(시작이 <!doctype html>, 끝이
  # </html>) 검사는 T22-134 담당.
  if ! assert_file_exists "$dashboard_command_file" "hub/README.md"; then
    record_failure "$test_name" "hub/README.md 미발견 — 합본을 만들 수 없어 T22 그룹을 진행할 수 없음"
    return 1
  fi
  if ! assert_file_exists "$dashboard_template_file" "hub_dashboard_template.html"; then
    record_failure "$test_name" "hub_dashboard_template.html 미발견 — 합본을 만들 수 없어 T22 그룹을 진행할 수 없음"
    return 1
  fi
  if ! assert_file_exists "$dashboard_helper_file" "hub_dashboard_log.py" \
    || ! assert_file_exists "$dashboard_render_file" "hub_dashboard_render.py"; then
    record_failure "$test_name" "hub_dashboard_log.py/hub_dashboard_render.py 미발견 — 합본을 만들 수 없어 T22 그룹을 진행할 수 없음"
    return 1
  fi

  # 대시보드 절차는 문서→기록기→순수 로직→템플릿 네 파일에 나뉘어 있다(dashboard-native-data-source
  # PRP DN3 — 실행 주체가 LLM 이 읽는 문서에서 코드로 옮겨간 뒤에도 셀렉터·CSS·JS 검증은
  # 네 파일의 합본을 대상으로 계속한다).
  local dashboard_union_file="$sandbox/dashboard_union.txt"
  cat "$dashboard_command_file" "$dashboard_helper_file" "$dashboard_render_file" "$dashboard_template_file" > "$dashboard_union_file"

  # T22-2: 필수 셀렉터 6종이 템플릿에 모두 존재
  local required_selector
  for required_selector in dz-title dz-progress-bar dz-progress-pct dz-step- \
    dz-log dz-updated; do
    if ! grep -q "$required_selector" "$dashboard_union_file"; then
      record_failure "$test_name" "T22-2: 셀렉터 미발견: $required_selector"
      return 1
    fi
  done

  # T22-3: 결과 배지 4종 CSS class 정의 존재
  local badge_class
  for badge_class in impl pass fail commit; do
    if ! grep -q "\.badge\.${badge_class}" "$dashboard_union_file"; then
      note_failure "T22-3: 배지 class 미발견: .badge.$badge_class"
    fi
  done

  # T22-4: 필터 라디오 3종과 CSS 규칙 존재
  if ! grep -q "dzf-review:checked" "$dashboard_union_file"; then
    note_failure "T22-4: 필터 CSS 규칙(dzf-review:checked) 미발견"
  fi
  if ! grep -q 'id="dzf-all"' "$dashboard_union_file" \
    || ! grep -q 'id="dzf-impl"' "$dashboard_union_file" \
    || ! grep -q 'id="dzf-review"' "$dashboard_union_file"; then
    record_failure "$test_name" "T22-4: 필터 라디오 3종 미발견"
    return 1
  fi

  # T22-138: install.sh 의 COMMANDS_FILE_COUNT 가 commands/ 최상위 전체 파일 수와 일치 (재발 방지책).
  local declared_count
  declared_count=$(grep -oE '^readonly COMMANDS_FILE_COUNT=[0-9]+' "$INSTALL_SCRIPT" | grep -oE '[0-9]+$')
  local actual_count
  actual_count=$(ls "$REPO_ROOT/commands"/* | wc -l | xargs echo)
  if ! assert_equals "$actual_count" "$declared_count" "COMMANDS_FILE_COUNT 일치"; then
    note_failure "T22-138: COMMANDS_FILE_COUNT=$declared_count, 실제 파일 수=$actual_count"
  fi

  # T22-7: div.legend 컴포넌트가 템플릿에서 제거됐는지 확인 (사용자 요청, 회귀 방지)
  if grep -q 'class="legend"' "$dashboard_union_file"; then
    note_failure "T22-7: div.legend 가 여전히 템플릿에 남아있음"
  fi

  # T22-8(역방향): 세션 구분 마커(session-head) 가 완전히 제거됐는지 확인
  if grep -q "session-head" "$dashboard_union_file"; then
    note_failure "T22-8: session-head 세션 구분 마커가 여전히 남아있음"
  fi

  # T22-10: 작업 추적 타이틀이 인라인 <b> 가 아니라 block 요소로 분리됐는지 확인
  if ! grep -q 'class="log-title"' "$dashboard_union_file"; then
    note_failure "T22-10: log-title 블록 요소 미발견"
  fi

  # T22-14(역방향): 세션 탭 CSS 골격과 삽입 마커가 완전히 제거됐는지 확인
  if grep -q 'label\[for\^="dzs-"\]' "$dashboard_union_file"; then
    note_failure "T22-14: 세션 탭 라벨 CSS 골격이 여전히 남아있음"
  fi
  if grep -q 'DZ:SESSION-RULES' "$dashboard_union_file"; then
    note_failure "T22-14: DZ:SESSION-RULES 삽입 마커가 여전히 남아있음"
  fi

  # T22-18(역방향): 세션별 .entry 필터 규칙(#dzs-*)이 완전히 제거됐는지 확인
  if grep -q '#dz-log > li:not(\[data-session=' "$dashboard_union_file"; then
    note_failure "T22-18: 세션 필터가 옛 '> li' 패턴으로 되돌아감"
  fi
  if grep -q '#dzs-1:checked ~ #dz-log .entry:not(\[data-session="1"\])' "$dashboard_union_file"; then
    note_failure "T22-18: 세션별 .entry 필터 규칙(#dzs-1)이 여전히 남아있음"
  fi

  # T22-22: 매트릭스 셀렉터 2종 존재 (dz-cell-, dz-group-) — 매트릭스 모드는 렌더 경로에서
  # 폐기됐지만(DN10) 템플릿 CSS 는 hub_parse._CELL_LINE_PATTERN 과 같은 이유로 구파일
  # 호환 목적으로 그대로 남는다.
  if ! grep -q 'dz-cell-' "$dashboard_union_file"; then
    note_failure "T22-22: dz-cell- 셀렉터 미발견"
  fi
  if ! grep -q 'dz-group-' "$dashboard_union_file"; then
    note_failure "T22-22: dz-group- 셀렉터 미발견"
  fi

  # T22-23: 매트릭스 CSS 가 템플릿에 상주 — 구파일 호환 목적으로 남긴다(DN10).
  if ! grep -q 'table\.matrix{' "$dashboard_union_file"; then
    note_failure "T22-23: table.matrix{ CSS 규칙 미발견"
  fi

  # T22-24: 선형 단계 목록 비퇴화 + 새 렌더러가 만드는 단계 줄 패턴이 문서화돼 있다.
  if ! grep -qF '<ol class="steps" id="dz-steps">' "$dashboard_union_file"; then
    note_failure "T22-24: 선형 단계 목록 <ol id=\"dz-steps\"> 미발견"
  fi
  if ! grep -q 'dz-step-{n}' "$dashboard_union_file"; then
    note_failure "T22-24: dz-step-{n} 패턴 미발견"
  fi

  # T22-27: 색 토큰 팔레트 이식(허브 토큰 전면 이식) — ① 정방향(신규 시맨틱 토큰명 존재)
  # ② 역방향(구 카테고리 토큰명 부재) ③ 역방향(색각 안전성 없는 구형 리터럴 부재).
  local new_color_token
  for new_color_token in '--bg:' '--surface:' '--head:' '--accent:' '--accent-ink:' '--accent-soft:' '--attention:' '--attention-soft:' '--shadow:'; do
    if ! grep -qF -- "$new_color_token" "$dashboard_union_file"; then
      record_failure "$test_name" "T22-27: 신규 색 토큰 미발견: $new_color_token"
      return 1
    fi
  done
  local legacy_color_token
  for legacy_color_token in '--navy:' '--blue:' '--green:' '--red:' '--orange:'; do
    if grep -qF -- "$legacy_color_token" "$dashboard_union_file"; then
      record_failure "$test_name" "T22-27: 구 색 토큰이 남아 있음: $legacy_color_token"
      return 1
    fi
  done
  local legacy_color_literal
  for legacy_color_literal in '#1F8A70' '#C2410C' '#F59E0B'; do
    if grep -qF -- "$legacy_color_literal" "$dashboard_union_file"; then
      note_failure "T22-27: 색각 안전성 없는 팔레트가 남아 있음: $legacy_color_literal"
    fi
  done

  # T22-28: 게이트 전용 개념 미신설(역방향) — 별도 게이트 컴포넌트 부활 방지.
  if grep -q 'dz-gate-' "$dashboard_union_file"; then
    note_failure "T22-28: dz-gate- 전용 셀렉터가 신설됨(게이트는 단계 1개 그룹으로 표현해야 함)"
  fi

  # T22-29: file:// 리로드 경로 비퇴화 — if(!isServed){...} 분기 자체와 그 판정식이 남아있다.
  if ! grep -qF "if(!isServed){" "$dashboard_union_file"; then
    note_failure "T22-29: if(!isServed){ 분기 미발견"
  fi
  if ! grep -qF "location.protocol === 'http:'" "$dashboard_union_file"; then
    note_failure "T22-29: isServed 판정식(location.protocol === 'http:') 미발견"
  fi

  # T22-30: 폴링 경로 존재 — 미구현/브라우저 캐시로 갱신이 멈추는 퇴행 방지.
  if ! grep -q 'DOMParser' "$dashboard_union_file"; then
    note_failure "T22-30: DOMParser 미발견"
  fi
  if ! grep -qF "cache:'no-store'" "$dashboard_union_file"; then
    note_failure "T22-30: cache:'no-store' 미발견"
  fi

  # T22-31: 기능 감지 존재 — 감지 없이 호출해 미지원 브라우저에서 예외가 나는 퇴행 방지.
  if ! grep -qF "'documentPictureInPicture' in window" "$dashboard_union_file"; then
    note_failure "T22-31: documentPictureInPicture 기능 감지 미발견"
  fi

  # T22-32: 자동 진입 금지 — requestWindow 호출이 정확히 1곳(click 리스너 안)뿐이다.
  if ! grep -q '자동 재시도하지 않는다' "$dashboard_union_file"; then
    note_failure "T22-32: 자동 재시도 금지 문구 미발견"
  fi
  if [[ "$(grep -c 'requestWindow' "$dashboard_union_file")" -ne 1 ]]; then
    note_failure "T22-32: requestWindow 호출이 정확히 1곳이 아님(click 리스너 밖에서 열릴 가능성)"
  fi
  if grep -qE 'setTimeout\(.*requestWindow|setInterval\(.*requestWindow' "$dashboard_union_file"; then
    note_failure "T22-32: setTimeout/setInterval 에서 requestWindow 를 호출함(자동 진입 회귀)"
  fi

  # T22-33: 스타일시트 복사 — PiP 창이 무스타일로 뜨는 퇴행 방지.
  if ! grep -qF "querySelectorAll('style')" "$dashboard_union_file"; then
    note_failure "T22-33: querySelectorAll('style') 미발견"
  fi
  if ! grep -q 'head.appendChild' "$dashboard_union_file"; then
    note_failure "T22-33: head.appendChild 미발견"
  fi

  # T22-34: 이동 방식 + 복귀 경로 — opener 가 영구히 비는 퇴행 방지.
  if ! grep -qF 'body.appendChild(wrap)' "$dashboard_union_file"; then
    note_failure "T22-34: body.appendChild(wrap) 미발견"
  fi
  if ! grep -q 'pagehide' "$dashboard_union_file"; then
    note_failure "T22-34: pagehide 미발견"
  fi
  if ! grep -qF 'insertBefore(wrap, wrapReturnAnchor)' "$dashboard_union_file"; then
    note_failure "T22-34: insertBefore(wrap, wrapReturnAnchor) 미발견(PiP 복귀 경로 미검증)"
  fi
  if grep -qF 'insertBefore(wrap, pipButton)' "$dashboard_union_file"; then
    note_failure "T22-34: insertBefore(wrap, pipButton) 이 남아있음(NotFoundError 회귀, P0)"
  fi
  if ! grep -qF 'wrapReturnAnchor = wrap.nextSibling' "$dashboard_union_file"; then
    note_failure "T22-34: wrapReturnAnchor = wrap.nextSibling 앵커 캡처 미발견"
  fi

  # T22-37: 플로팅 UI 가 .wrap 바깥에 있는지 — 템플릿에서의 마지막 등장 위치로 판정한다.
  local pip_button_line wrap_open_line wrap_end_line
  pip_button_line=$(grep -n 'id="dz-pip-btn"' "$dashboard_union_file" | tail -1 | cut -d: -f1)
  wrap_open_line=$(grep -n '<div class="wrap">' "$dashboard_union_file" | tail -1 | cut -d: -f1)
  wrap_end_line=$(grep -n 'id="dz-updated"' "$dashboard_union_file" | tail -1 | cut -d: -f1)
  if [[ -z "$pip_button_line" || -z "$wrap_open_line" || -z "$wrap_end_line" ]] \
    || { [[ "$pip_button_line" -ge "$wrap_open_line" ]] && [[ "$pip_button_line" -le "$wrap_end_line" ]]; }; then
    note_failure "T22-37: 플로팅 버튼이 .wrap 범위 안에 있음(.wrap 바깥이어야 한다)"
  fi

  # T22-38: grep 유일성 불변식(역방향) — [id="dz- 형태의 속성 셀렉터 문자열이 없다.
  if grep -q '\[id="dz-' "$dashboard_union_file"; then
    note_failure "T22-38: [id=\"dz- 형태의 셀렉터 문자열이 발견됨"
  fi

  # T22-39: 로그 카드 식별자 존재 — id 없이 구조 셀렉터로 되돌아가는 회귀 방지.
  if ! grep -qF 'id="dz-log-card"' "$dashboard_union_file"; then
    note_failure "T22-39: id=\"dz-log-card\" 미발견"
  fi

  # T22-40: PiP 압축 규칙 존재 — 압축 뷰 자체의 유실 방지.
  if ! grep -qF 'body.dz-pip #dz-log-card{display:none}' "$dashboard_union_file"; then
    note_failure "T22-40: body.dz-pip #dz-log-card{display:none} 미발견"
  fi

  # T22-41: 로그 앵커 비충돌 — 템플릿 자체만 대상으로 좁혀 충돌 가능성을 직접 확인한다.
  if grep -n 'id="dz-log"' "$dashboard_template_file" | grep -q 'dz-log-card'; then
    note_failure "T22-41: 로그 카드 id 가 log 앵커와 충돌함"
  fi
  if [[ "$(grep -c 'id="dz-log"' "$dashboard_template_file")" -ne 1 ]]; then
    note_failure "T22-41: 템플릿 안 id=\"dz-log\" 매칭 줄 수가 1이 아님(로그 카드 id 충돌 가능성)"
  fi

  # T22-42: CSS 로만 숨김(역방향) — 스크립트가 카드를 DOM 에서 떼어내면 폴링이 오판한다.
  if grep -qE '(getElementById|querySelector)\([^)]*dz-log-card' "$dashboard_union_file"; then
    note_failure "T22-42: 스크립트가 dz-log-card 를 getElementById/querySelector 로 참조함"
  fi

  # T22-43: 로그 동기화 비퇴화.
  if ! grep -qF 'function syncLog' "$dashboard_union_file"; then
    note_failure "T22-43: function syncLog 미발견"
  fi
  if ! grep -qF "live.innerHTML = next.innerHTML" "$dashboard_union_file"; then
    note_failure "T22-43: live.innerHTML = next.innerHTML 미발견"
  fi

  # T22-44: 단계 상세 마크업·CSS — 상세 span 또는 빈 값 숨김 규칙 유실 방지.
  if ! grep -qF 'class="step-detail"' "$dashboard_union_file"; then
    note_failure "T22-44: class=\"step-detail\" 미발견"
  fi
  if ! grep -qF '.step-detail:empty{display:none}' "$dashboard_union_file"; then
    note_failure "T22-44: .step-detail:empty{display:none} 미발견"
  fi

  # T22-45: PiP 는 활성 상세만 — 좁은 창이 상세로 도배되는 회귀 방지.
  if ! grep -qF 'body.dz-pip ol.steps li:not(.active) .step-detail' "$dashboard_union_file"; then
    note_failure "T22-45: body.dz-pip ol.steps li:not(.active) .step-detail 미발견"
  fi

  # T22-47: PiP 창 높이 콘텐츠 맞춤 — 하단에 빈 여백이 남는 회귀 방지.
  if ! grep -qF 'function resizePipToFit(){' "$dashboard_union_file"; then
    note_failure "T22-47: function resizePipToFit 미발견"
  fi
  if ! grep -qF 'pipWindow.resizeTo(PIP_WIDTH,' "$dashboard_union_file"; then
    note_failure "T22-47: resizeTo 호출 미발견"
  fi
  if ! grep -qF 'resizePipToFit();' "$dashboard_union_file"; then
    note_failure "T22-47: apply() 안에서 resizePipToFit 호출 미발견"
  fi

  # T22-48: 구현 세부 작업 패널의 정적 컨테이너 셀렉터 3종 존재 — 패널 자체(동적 항목 생성)는
  # 폐기됐지만(DN8) 빈 컨테이너는 템플릿에 남아 :has() 로 상시 숨는다(T22-49).
  if ! grep -qF 'id="dz-impl-card"' "$dashboard_union_file"; then
    note_failure "T22-48: id=\"dz-impl-card\" 미발견"
  fi
  if ! grep -qF 'id="dz-impl-tasks"' "$dashboard_union_file"; then
    note_failure "T22-48: id=\"dz-impl-tasks\" 미발견"
  fi
  if ! grep -qF 'id="dz-impl-count"' "$dashboard_union_file"; then
    note_failure "T22-48: id=\"dz-impl-count\" 미발견"
  fi

  # T22-49: 자동 숨김 규칙 존재 — 빈 카드가 모든 세션에 노출되는 회귀 방지.
  if ! grep -qF '#dz-impl-card:not(:has(#dz-impl-tasks li)){display:none}' "$dashboard_union_file"; then
    note_failure "T22-49: 구현 세부 작업 카드 자동 숨김 규칙 미발견"
  fi

  # T22-50: 레이아웃 CSS 재사용(역방향) — 중복 정의가 생기면 목록이 갈라진다.
  if ! grep -qF '<ol class="steps" id="dz-impl-tasks">' "$dashboard_union_file"; then
    note_failure "T22-50: <ol class=\"steps\" id=\"dz-impl-tasks\"> 미발견"
  fi
  if grep -q 'ol\.impl-tasks' "$dashboard_union_file"; then
    note_failure "T22-50: ol.impl-tasks 레이아웃 규칙이 중복 정의됨"
  fi

  # T22-51: 폴링 동기화 — 카드가 동기화에서 빠지면 http://·PiP 에서 영구히 stale 된다.
  if ! grep -qF 'function syncImplCard(fresh){' "$dashboard_union_file"; then
    note_failure "T22-51: function syncImplCard(fresh){ 미발견"
  fi
  if ! grep -qF 'syncImplCard(fresh);' "$dashboard_union_file"; then
    note_failure "T22-51: apply() 안에서 syncImplCard 호출 미발견"
  fi

  # T22-52: CSS 로만 숨김(역방향) — 스크립트가 impl 카드를 DOM/인라인 스타일로 조작하지 않는다.
  if grep -n 'dz-impl-card' "$dashboard_union_file" | grep -qE 'remove\(|style\.display'; then
    note_failure "T22-52: 스크립트가 dz-impl-card 를 DOM/인라인 스타일로 조작함"
  fi

  # T22-53: 기존 시각화 동기화 비퇴화.
  if ! grep -qF "querySelector('#dz-steps,#dz-matrix')" "$dashboard_union_file"; then
    note_failure "T22-53: querySelector('#dz-steps,#dz-matrix') 미발견"
  fi

  # T22-61(역방향): 「지금」 카드 제거 후속으로 없앤 dz-current 계열 셀렉터·인자가 부활하지 않는다.
  if grep -qE 'dz-current|"현재 위치"' "$dashboard_union_file"; then
    note_failure "T22-61: 제거된 dz-current 계열 셀렉터·인자가 부활함"
  fi

  # T22-69: file:// 폴백 생존(최우선) — 서버 실패 시 URL 을 아무것도 못 주는 순수 퇴행을 막는다.
  if ! grep -qF 'file://' "$dashboard_union_file"; then
    record_failure "$test_name" "T22-69: file:// 문자열이 문서에서 사라짐"
    return 1
  fi

  # T22-80: 템플릿의 #dz-log 여는 태그에 포트 각인 슬롯이 비어 있는 상태로 존재하는지 확인 —
  # 자동 발행은 폐기됐지만(DN8) 이 슬롯은 옛 발행본·허브 파서 계약과의 호환을 위해 항상
  # 빈 문자열로 남는다(PublishedValues.log_server_port 는 build_published_values 가 "" 로 고정).
  if ! grep -qF 'id="dz-log" data-owner-token="" data-server-port=""' "$dashboard_union_file"; then
    record_failure "$test_name" "T22-80: #dz-log 각인 슬롯(data-server-port) 미발견"
    return 1
  fi

  # T22-84(역방향): <script> 블록은 data-server-port 를 읽지도 쓰지도 않는다.
  local script_block
  script_block=$(sed -n '/^<script>/,/<\/script>/p' "$dashboard_union_file")
  if [[ -z "$script_block" ]]; then
    note_failure "T22-84: <script> 블록 범위 추출 실패 — 앵커가 깨졌다"
  fi
  if grep -q 'data-server-port' <<< "$script_block"; then
    record_failure "$test_name" "T22-84: <script> 블록이 data-server-port 를 참조함(불변식 위반)"
    return 1
  fi

  # T22-85(역방향): poll() 실패 경로가 PiP 창을 닫거나 리로드하지 않는다.
  local poll_body
  poll_body=$(sed -n '/function poll(){/,/setInterval(poll,/p' "$dashboard_union_file")
  if [[ -z "$poll_body" ]]; then
    note_failure "T22-85: poll() 범위 추출 실패 — 앵커가 깨졌다"
  fi
  if grep -q 'close()\|location.reload' <<< "$poll_body"; then
    note_failure "T22-85: poll() 실패 경로에서 close()/location.reload 발견 — PiP 고정 회귀"
  fi

  # T22-91(역방향): 세션 탭 UI 잔재 전무 확인.
  local session_relic
  for session_relic in 'data-current-session' 'data-session=' 'sessionTabsChanged' 'dzs-'; do
    if grep -qF -- "$session_relic" "$dashboard_union_file"; then
      note_failure "T22-91: 세션 탭 잔재 발견: $session_relic"
    fi
  done

  # T22-92(역방향): 부제(#dz-subtitle) 잔재 전무 확인.
  if grep -qF 'dz-subtitle' "$dashboard_union_file"; then
    note_failure "T22-92: dz-subtitle 잔재 발견"
  fi
  if grep -qF 'class="sub"' "$dashboard_union_file"; then
    note_failure "T22-92: class=\"sub\" 잔재 발견"
  fi

  # T22-94(역방향): open -g(백그라운드) 옵션 문자열이 없다 — 탭을 몰래 백그라운드로 여는
  # 코드가 다른 경로로 되살아나지 않았는지 확인한다(자동 발행 자체는 폐기됐다, DN8).
  if grep -qF 'open -g' "$dashboard_union_file"; then
    record_failure "$test_name" "T22-94: open -g(백그라운드) 옵션 문자열 발견"
    return 1
  fi

  # T22-96(역방향): 「지금」 카드 잔재 전무 확인 — dz-now-card·renderNowCard 등 10종.
  local now_card_relic
  local now_card_relics_checked_count=0
  for now_card_relic in 'dz-now-card' 'dz-now-elapsed' 'dz-now-since' 'dz-now-next' 'renderNowCard' 'data-started-at' 'now-row' 'now-label' 'now-value' 'now-title'; do
    ((now_card_relics_checked_count++)) || true
    if grep -qF -- "$now_card_relic" "$dashboard_union_file"; then
      note_failure "T22-96: 「지금」 카드 잔재 발견: $now_card_relic"
    fi
  done
  # T22-165(공허 통과 방지): 위 루프가 실제로 목록 10종 전부를 순회했는지 건수로 단정한다.
  local -r NOW_CARD_RELIC_EXPECTED_COUNT=10
  if ((now_card_relics_checked_count != NOW_CARD_RELIC_EXPECTED_COUNT)); then
    note_failure "T22-165: 「지금」 카드 잔재 검사 건수 ${now_card_relics_checked_count}건(기대 ${NOW_CARD_RELIC_EXPECTED_COUNT}건) — 목록이 줄어 일부 문자열이 검사에서 빠짐"
  fi

  # T22-97(R1): body.dz-embedded #dz-pip-btn CSS 규칙 존재.
  if ! grep -qF 'body.dz-embedded #dz-pip-btn' "$dashboard_union_file"; then
    note_failure "T22-97: body.dz-embedded #dz-pip-btn CSS 규칙 미발견"
  fi

  # T22-98(R1): 임베드 판정식 — self !== top 이 없으면 늘 false 로 오판정한다.
  if ! grep -qF 'window.self !== window.top' "$dashboard_union_file"; then
    note_failure "T22-98: window.self !== window.top 판정식 미발견"
  fi

  # T22-99(R1, GOTCHA 3): isEmbedded 는 선언 1 + 사용 1, 정확히 2줄이어야 한다.
  if [[ "$(grep -c 'isEmbedded' "$dashboard_union_file")" -ne 2 ]]; then
    note_failure "T22-99: isEmbedded 등장 횟수가 정확히 2가 아님"
  fi
  if grep -qE 'if\(isEmbedded\) return' "$dashboard_union_file"; then
    record_failure "$test_name" "T22-99: if(isEmbedded) return 발견(폴링 조기 반환 회귀)"
    return 1
  fi

  # T22-101(R2, 역방향+정방향, docs/prps/dashboard-into-hub.md M1 로 범위 재조준): 허브
  # 기본 포트를 하드코딩하지 않고, 허브 상세 패널 언급이 있다. 포트 부재 검사는 기록기·
  # 렌더러·템플릿 3파일로 좁힌다 — hub/README.md(이제 dashboard_command_file)는 허브
  # 자신의 문서라 "포트 8794(고정)" 처럼 포트를 정당하게 언급한다.
  if grep -qF '8794' "$dashboard_helper_file" "$dashboard_render_file" "$dashboard_template_file"; then
    note_failure "T22-101: 허브 기본 포트(8794) 가 기록기·렌더러·템플릿에 하드코딩됨"
  fi
  if ! grep -qF '패널' "$dashboard_union_file"; then
    record_failure "$test_name" "T22-101: '패널' 문구 미발견(허브 상세 패널 언급 회귀)"
    return 1
  fi

  # T22-105(R1): 템플릿의 #dz-log 여는 태그에 data-owner-token 속성이 추가됐다(순서 포함).
  # 역방향: 토큰 없는 옛 줄이 남아있지 않다.
  if ! grep -qF 'id="dz-log" data-owner-token="" data-server-port=""' "$dashboard_union_file"; then
    note_failure "T22-105: #dz-log 여는 태그에 data-owner-token 속성 미발견(순서 포함)"
  fi
  if grep -qF 'id="dz-log" data-server-port=""></ul>' "$dashboard_union_file"; then
    record_failure "$test_name" "T22-105: 토큰 없는 옛 #dz-log 줄이 남아있음"
    return 1
  fi

  # T22-109(R1, 가장 값진 검사): 스크립트가 data-owner-token 을 읽는 코드가 어디에도 없다 —
  # 그 속성은 렌더러(코드)만 쓰고 <script> 는 읽지 않는다.
  local script_token_leak
  for script_token_leak in "getAttribute('data-owner-token'" 'dataset.ownerToken' "querySelector('[data-owner-token"; do
    if grep -qF -- "$script_token_leak" "$dashboard_union_file"; then
      note_failure "T22-109: 스크립트가 토큰을 읽는 흔적 발견(불변식 위반): $script_token_leak"
    fi
  done

  # T22-111(허브 T25-28 과 대칭): 다크 테마는 미디어 쿼리 + data-theme 속성 오버라이드 둘 다로
  # 성립해야 한다 — 한쪽만 남으면 localStorage 차단 환경 또는 수동 오버라이드가 죽는다.
  if ! grep -qF "prefers-color-scheme" "$dashboard_union_file"; then
    note_failure "T22-111: prefers-color-scheme 가 없음"
  fi
  if ! grep -qF ':root[data-theme="dark"]' "$dashboard_union_file"; then
    record_failure "$test_name" "T22-111: :root[data-theme=\"dark\"] 가 없음"
    return 1
  fi

  # T22-112: 'dz-theme' 리터럴이 head FOUC 스크립트 + 본문 IIFE 두 곳에 각각 등장해야 한다.
  local dz_theme_literal_count
  dz_theme_literal_count=$(grep -oF "'dz-theme'" "$dashboard_union_file" | wc -l | tr -d ' ')
  if [[ "$dz_theme_literal_count" -lt 2 ]]; then
    record_failure "$test_name" "T22-112: 'dz-theme' 리터럴이 ${dz_theme_literal_count}회만 등장(기대 2회 이상)"
    return 1
  fi

  # T22-113(FOUC 방지 회귀): data-theme 설정이 <head> 테마 스크립트에 있고, <body> 보다 앞선다.
  local head_theme_line body_open_line
  head_theme_line=$(grep -n "document.documentElement.setAttribute('data-theme', theme);" "$dashboard_union_file" | head -1 | cut -d: -f1)
  body_open_line=$(grep -n '^<body>$' "$dashboard_union_file" | head -1 | cut -d: -f1)
  if [[ -z "$head_theme_line" || -z "$body_open_line" || "$head_theme_line" -gt "$body_open_line" ]]; then
    record_failure "$test_name" "T22-113: <head> 테마 스크립트의 data-theme 설정이 <body> 보다 앞에 있지 않음"
    return 1
  fi

  # T22-114: 테마 토글이 .wrap 바깥에 있는지 — 템플릿에서의 마지막 등장 위치로 판정한다.
  local theme_toggle_line wrap_open_line wrap_end_line
  theme_toggle_line=$(grep -n 'id="dz-theme-toggle"' "$dashboard_union_file" | tail -1 | cut -d: -f1)
  wrap_open_line=$(grep -n '<div class="wrap">' "$dashboard_union_file" | tail -1 | cut -d: -f1)
  wrap_end_line=$(grep -n 'id="dz-updated"' "$dashboard_union_file" | tail -1 | cut -d: -f1)
  if [[ -z "$theme_toggle_line" || -z "$wrap_open_line" || -z "$wrap_end_line" ]] \
    || { [[ "$theme_toggle_line" -ge "$wrap_open_line" ]] && [[ "$theme_toggle_line" -le "$wrap_end_line" ]]; }; then
    note_failure "T22-114: 테마 토글이 .wrap 범위 안에 있음(.wrap 바깥이어야 한다)"
  fi

  # T22-115: 허브 모달(iframe) 안에서는 테마 토글이 숨어야 한다.
  if ! grep -qF 'body.dz-embedded #dz-theme-toggle' "$dashboard_union_file"; then
    note_failure "T22-115: body.dz-embedded #dz-theme-toggle CSS 규칙 미발견"
  fi

  # T22-116: PiP 창으로 data-theme 를 전파하는 코드가 있는지.
  if ! grep -qF "pipDocument.documentElement.setAttribute('data-theme'" "$dashboard_union_file"; then
    record_failure "$test_name" "T22-116: PiP 분기에 pipDocument.documentElement.setAttribute('data-theme' 미발견"
    return 1
  fi

  # T22-117(팔레트 회귀 방지, T25-29 와 대칭): 토큰화한 자리에 구형 카테고리 리터럴이 없다.
  local legacy_hex_literal
  for legacy_hex_literal in '#E5F3EE' '#EAF2FB' '#FBE9E2' '#E7EAF3' '#2D78C8' '#4B5A6D' '#1F8A70' '#C2410C' '#F59E0B'; do
    if grep -qF -- "$legacy_hex_literal" "$dashboard_union_file"; then
      note_failure "T22-117: 색각 안전성 없는 구형 리터럴이 남아 있음: $legacy_hex_literal"
    fi
  done

  # T22-118(단방향 읽기 계약): 'dzh-theme' 리터럴은 있어야 하지만, 대시보드가 이 키에 쓰지 않는다.
  if ! grep -qF "'dzh-theme'" "$dashboard_union_file"; then
    note_failure "T22-118: 'dzh-theme' 리터럴 미발견(허브 모달 테마 동기화 코드 자체가 없음)"
  fi
  if grep -qF "setItem('dzh-theme'" "$dashboard_union_file"; then
    note_failure "T22-118: setItem('dzh-theme' 발견 — 대시보드가 허브 키에 쓰고 있음(단방향 읽기 계약 위반)"
  fi
  if ! grep -A2 "themeToggleButton.addEventListener('click'" "$dashboard_union_file" | grep -qF 'if(embedded) return;'; then
    note_failure "T22-118: 테마 토글 클릭 핸들러에 embedded 가드 없음(CSS display:none 에만 의존)"
  fi

  # T22-120(다크 대비 예비안): li.done .num 1 + 매트릭스 done 셀 1, 정확히 2곳(템플릿 안).
  local done_ring_count
  done_ring_count=$(grep -c 'box-shadow:inset 0 0 0 1px var(--accent)' "$dashboard_union_file")
  if [[ "$done_ring_count" -ne 2 ]]; then
    record_failure "$test_name" "T22-120: 완료 상태 inset ring 개수가 2가 아님(실제: $done_ring_count)"
    return 1
  fi

  # T22-121(프로젝트 헤더): id 와 class 가 같은 줄에 있어야 한다.
  local project_name_element_line
  project_name_element_line=$(grep -n 'id="dz-project-name"' "$dashboard_union_file" | tail -1)
  if [[ -z "$project_name_element_line" ]] || ! grep -qF 'class="project-name"' <<< "$project_name_element_line"; then
    record_failure "$test_name" "T22-121: id=\"dz-project-name\" 과 class=\"project-name\" 이 같은 줄에 없음"
    return 1
  fi

  # T22-122(프로젝트 헤더): 줄 번호 순서 #dz-page-head < #dz-project-name < #dz-top-actions < .wrap.
  local page_head_line top_actions_element_line wrap_div_line
  page_head_line=$(grep -n 'id="dz-page-head"' "$dashboard_union_file" | tail -1 | cut -d: -f1)
  top_actions_element_line=$(grep -n 'id="dz-top-actions"' "$dashboard_union_file" | tail -1 | cut -d: -f1)
  wrap_div_line=$(grep -n '<div class="wrap">' "$dashboard_union_file" | tail -1 | cut -d: -f1)
  if [[ -z "$page_head_line" || -z "$top_actions_element_line" || -z "$wrap_div_line" ]] \
    || ! [[ "$page_head_line" -lt "${project_name_element_line%%:*}" \
         && "${project_name_element_line%%:*}" -lt "$top_actions_element_line" \
         && "$top_actions_element_line" -lt "$wrap_div_line" ]]; then
    record_failure "$test_name" "T22-122: 헤더 요소 순서(#dz-page-head < #dz-project-name < #dz-top-actions < .wrap)가 어긋남"
    return 1
  fi

  # T22-123(역방향, 프로젝트 헤더): #dz-top-actions 에 position:fixed 가 남아있지 않다.
  local top_actions_css_line
  top_actions_css_line=$(grep -n '#dz-top-actions{' "$dashboard_union_file" | tail -1)
  if [[ -z "$top_actions_css_line" ]]; then
    note_failure "T22-123: #dz-top-actions{ CSS 규칙 줄 미발견"
  fi
  if grep -qF 'position:fixed' <<< "$top_actions_css_line"; then
    note_failure "T22-123: #dz-top-actions 에 position:fixed 가 남아있음(흐름 배치 회귀)"
  fi

  # T22-124(프로젝트 헤더): 허브 모달에서 프로젝트 명이 모달 제목과 중복 표시되는 회귀 방지.
  if ! grep -qF 'body.dz-embedded #dz-page-head' "$dashboard_union_file"; then
    note_failure "T22-124: body.dz-embedded #dz-page-head CSS 규칙 미발견"
  fi

  # T22-125(프로젝트 헤더·기록 위치): 기록기의 기준 폴더가 cwd 가 아니라 소유 레포 루트(워크트리를
  # 접은 폴더)라는 값 출처가 사라지면, 워크트리 안에서 쓴 기록이 워크트리와 함께 지워지고 헤더의
  # 프로젝트 명도 워크트리 이름이 된다(docs/prps/dashboard-into-hub.md HD16 — 옛 토큰은 cwd 의 basename).
  if ! grep -qF 'fold_worktree_path(os.getcwd())' "$dashboard_union_file"; then
    note_failure "T22-125: fold_worktree_path(os.getcwd()) 미발견(기록 기준 폴더가 소유 레포 루트가 아님)"
  fi

  # T22-127(요구 2): 복사용 표준 단계 목록 리터럴이 문서에 남아있는지 확인한다.
  if ! grep -qF '설계|승인|구현|검수' "$dashboard_union_file"; then
    note_failure "T22-127: 표준 단계 목록 리터럴(설계|승인|구현|검수) 미발견"
  fi

  # T22-128(허브 상세 패널 가로 넘침 회귀 방지): `.entry .detail` 에 overflow-wrap:anywhere.
  if ! grep -qE '\.entry \.detail\{[^}]*white-space:pre-wrap;overflow-wrap:anywhere\}' "$dashboard_union_file"; then
    note_failure "T22-128: .entry .detail 규칙에 overflow-wrap:anywhere 가 없음(가로 넘침 회귀)"
  fi

  # T22-129: 프로젝트 대시보드 폴링 주기 회귀 방지 — 60000(1분)으로 고정.
  if ! grep -qF "POLL_INTERVAL_MS = 60000" "$dashboard_union_file"; then
    note_failure "T22-129: POLL_INTERVAL_MS = 60000 회귀(대시보드 폴링 주기가 바뀜)"
  fi

  # T22-130(요구 2): 상세 마크업(문단·목록·인라인 코드) CSS 4규칙 존재 확인.
  local detail_markup_css_token
  for detail_markup_css_token in '.entry .detail>*{margin:0}' '.entry .detail ul{list-style:disc' \
    '.entry .detail code{' 'ui-monospace'; do
    if ! grep -qF -- "$detail_markup_css_token" "$dashboard_union_file"; then
      note_failure "T22-130: 상세 마크업 CSS 규칙 미발견: $detail_markup_css_token"
    fi
  done

  # T22-132(요구 2): 상세 마크업 불변식(태그 사이 개행 없이 한 줄로 조립)이 문서에 명시돼
  # 있다 — 실제 계약은 tests/hub/test_hub_dashboard_log.py 의 render_detail_html 단위
  # 테스트가 고정한다(문서 프로즈가 아니라 함수 자체가 정본, DN3).
  if ! grep -qF '불변식 10' "$dashboard_union_file"; then
    note_failure "T22-132: 불변식 10 미발견"
  fi

  # T22-134: 템플릿이 설치본에 존재하고 <!doctype html> 로 시작해 </html> 로 끝난다.
  if ! assert_file_exists "$dashboard_template_file" "dashboard_template.html"; then
    note_failure "T22-134: dashboard_template.html 미설치"
  else
    if ! head -1 "$dashboard_template_file" | grep -qF '<!doctype html>'; then
      note_failure "T22-134: 템플릿이 <!doctype html> 로 시작하지 않음"
    fi
    if ! tail -1 "$dashboard_template_file" | grep -qF '</html>'; then
      note_failure "T22-134: 템플릿이 </html> 로 끝나지 않음"
    fi
  fi

  # T22-135(역방향): dashboard.md 에 <!doctype html> 이 없다 — 템플릿을 문서로 되돌리는 회귀 방지.
  if grep -qF '<!doctype html>' "$dashboard_command_file"; then
    note_failure "T22-135: dashboard.md 에 <!doctype html> 이 남아있음(템플릿 미분리 회귀)"
  fi

  # T22-136: dashboard.md 가 실제 배포 템플릿 파일명을 문자열로 포함한다.
  local actual_template_basename
  actual_template_basename=$(basename "$dashboard_template_file")
  if ! grep -qF "$actual_template_basename" "$dashboard_command_file"; then
    note_failure "T22-136: dashboard.md 에 템플릿 파일명($actual_template_basename) 미언급"
  fi

  # T22-137(정+역, dashboard-into-hub.md M2 HD15 재조준): init 이 지금도 낼 수 있는 폐쇄
  # 어휘(OK·MKDIR-FAILED)는 문서에 있고(정), 폐기된 어휘(NOTEMPLATE·ANCHOR-FAIL)는 문서
  # 어디에도 없다(역 — HTML 재발행 경로가 사라지며 그 실패 어휘도 함께 사라졌다).
  local init_closed_vocab
  for init_closed_vocab in 'OK' 'MKDIR-FAILED'; do
    if ! grep -qF -- "$init_closed_vocab" "$dashboard_command_file"; then
      note_failure "T22-137: 개정 init 폐쇄 어휘 미발견: $init_closed_vocab"
    fi
  done
  local retired_init_vocab
  for retired_init_vocab in 'NOTEMPLATE' 'ANCHOR-FAIL'; do
    if grep -qF -- "$retired_init_vocab" "$dashboard_command_file"; then
      note_failure "T22-137: hub/README.md 에 폐기된 어휘가 남아 있음: $retired_init_vocab"
    fi
  done

  # T22-139: init 이 치환하는 앵커 9종이 템플릿에 각각 정확히 1회 등장한다
  # (앵커 유일성 붕괴 → 서버 렌더 404 상시화 방지, dashboard-into-hub.md M2 재조준 —
  # AnchorMismatch 는 이제 허브 서버의 404 + server.log 한 줄로 드러난다, HD15).
  local init_substitution_anchor
  for init_substitution_anchor in \
    '<span class="project-name" id="dz-project-name">프로젝트</span>' \
    '<h1 id="dz-title">세션 제목</h1>' \
    '<div class="pct" id="dz-progress-pct">0/0 · 0%</div>' \
    '<ol class="steps" id="dz-steps">' \
    '<ul class="log" id="dz-log" data-owner-token="" data-server-port=""></ul>' \
    '<div class="foot" id="dz-updated">갱신: -</div>'; do
    local anchor_occurrence_count
    anchor_occurrence_count=$(grep -cF -- "$init_substitution_anchor" "$dashboard_template_file")
    if [[ "$anchor_occurrence_count" -ne 1 ]]; then
      note_failure "T22-139: 템플릿 앵커 등장 횟수가 1이 아님(실제 $anchor_occurrence_count): $init_substitution_anchor"
    fi
  done

  # T22-145/146 공통 준비(결정 IR4·GOTCHA 1): 훅 줄과 그 앞뒤 분기 앵커의 줄 번호를 추출한다.
  local hook_line_count is_served_branch_line hook_line has_pip_branch_line
  hook_line_count=$(grep -c 'window\.dzRequestRefresh = poll;' "$dashboard_template_file")
  is_served_branch_line=$(grep -n 'if(!isServed){' "$dashboard_template_file" | head -1 | cut -d: -f1)
  hook_line=$(grep -n 'window\.dzRequestRefresh = poll;' "$dashboard_template_file" | head -1 | cut -d: -f1)
  has_pip_branch_line=$(grep -n 'if(!hasPipSupport){' "$dashboard_template_file" | head -1 | cut -d: -f1)
  if [[ "$hook_line_count" -ne 1 || -z "$is_served_branch_line" || -z "$hook_line" || -z "$has_pip_branch_line" ]]; then
    record_failure "$test_name" "T22-145/146: 갱신 훅 추출 실패 — 훅 ${hook_line_count}건(기대 1) 또는 분기 앵커 미발견"
    return 1
  fi

  # T22-145(결정 IR4): 갱신 훅 노출 줄이 if(!isServed){ 분기(갱신 경로 A) 보다 뒤에 있다.
  if [[ "$hook_line" -le "$is_served_branch_line" ]]; then
    note_failure "T22-145: 갱신 훅 노출 줄이 if(!isServed){ 분기보다 뒤에 있지 않음(갱신 경로 A 오염)"
  fi

  # T22-146(GOTCHA 1 회귀 검출): 갱신 훅 노출 줄이 if(!hasPipSupport){ 분기보다 앞에 있다.
  if [[ "$hook_line" -ge "$has_pip_branch_line" ]]; then
    note_failure "T22-146: 갱신 훅 노출 줄이 if(!hasPipSupport){ 분기보다 앞에 있지 않음(GOTCHA 1)"
  fi

  # T22-148(정+역, 결정 LT8): id="dz-tooltip" 는 템플릿에 정확히 1줄 존재하고, .wrap 여는
  # 줄보다 앞이다(.wrap 안에 들어가면 PiP 진입 시 사라진다).
  local tooltip_id_occurrence_count tooltip_id_line wrap_open_for_tooltip_line
  tooltip_id_occurrence_count=$(grep -c 'id="dz-tooltip"' "$dashboard_template_file")
  if [[ "$tooltip_id_occurrence_count" -ne 1 ]]; then
    note_failure "T22-148: id=\"dz-tooltip\" 등장 횟수=$tooltip_id_occurrence_count(기대 1)"
  else
    tooltip_id_line=$(grep -n 'id="dz-tooltip"' "$dashboard_template_file" | cut -d: -f1)
    wrap_open_for_tooltip_line=$(grep -n '<div class="wrap">' "$dashboard_template_file" | tail -1 | cut -d: -f1)
    if [[ -z "$wrap_open_for_tooltip_line" || "$tooltip_id_line" -ge "$wrap_open_for_tooltip_line" ]]; then
      note_failure "T22-148: #dz-tooltip 이 .wrap 여는 줄보다 앞에 있지 않음(결정 LT8 위반 — PiP 이동 시 소멸)"
    fi
  fi

  # T22-149(정, 결정 LT4): .tooltip{ 규칙에 뷰포트 클램프와 overflow-wrap:anywhere 가 있다.
  if ! grep -qF 'max-width:min(420px,calc(100vw - 32px))' "$dashboard_template_file" \
    || ! grep -qE '\.tooltip\{[^}]*overflow-wrap:anywhere' "$dashboard_template_file"; then
    note_failure "T22-149: .tooltip{ 규칙에 뷰포트 클램프·overflow-wrap:anywhere 가 없음"
  fi

  # T22-150(역, GOTCHA 6): 템플릿 파일 자체에 data-tooltip 문자열이 0건이다.
  if grep -q 'data-tooltip' "$dashboard_template_file"; then
    note_failure "T22-150: dashboard_template.html 에 data-tooltip 문자열이 있음(각인 방식으로의 퇴행)"
  fi

  # T22-151(정, 결정 LT9): getElementById('dz-tooltip') 가 THEME_STORAGE_KEY 보다 뒤다.
  local tooltip_lookup_line theme_storage_key_line
  tooltip_lookup_line=$(grep -n "getElementById('dz-tooltip')" "$dashboard_template_file" | head -1 | cut -d: -f1)
  theme_storage_key_line=$(grep -n "var THEME_STORAGE_KEY = 'dz-theme';" "$dashboard_template_file" | head -1 | cut -d: -f1)
  if [[ -z "$tooltip_lookup_line" || -z "$theme_storage_key_line" || "$tooltip_lookup_line" -le "$theme_storage_key_line" ]]; then
    note_failure "T22-151: getElementById('dz-tooltip') 가 THEME_STORAGE_KEY 보다 뒤에 있지 않음(결정 LT9 위반 — 폴링 IIFE 오염 가능)"
  fi

  # T22-152(정, 결정 IL1~IL3): 선택 차단 CSS 규칙과 우클릭 차단 리스너가 모두 있다.
  if ! grep -qF 'html{-webkit-user-select:none;user-select:none}' "$dashboard_template_file"; then
    note_failure "T22-152: html{-webkit-user-select:none;user-select:none} 미발견"
  fi
  if ! grep -qF 'function preventNativeContextMenu(event){ event.preventDefault(); }' "$dashboard_template_file" \
    || ! grep -qF "document.addEventListener('contextmenu', preventNativeContextMenu);" "$dashboard_template_file"; then
    note_failure "T22-152: contextmenu preventDefault 리스너 미발견"
  fi

  # T22-153(정+역, 결정 IL4): documentPictureInPicture 의 'enter' 리스너가 존재하고, 그 줄이
  # THEME_STORAGE_KEY 보다 뒤다.
  local pip_enter_line
  pip_enter_line=$(grep -n "documentPictureInPicture.addEventListener('enter'" "$dashboard_template_file" | head -1 | cut -d: -f1)
  if [[ -z "$pip_enter_line" ]]; then
    note_failure "T22-153: documentPictureInPicture 의 'enter' 리스너 미발견"
  elif [[ -z "$theme_storage_key_line" || "$pip_enter_line" -le "$theme_storage_key_line" ]]; then
    note_failure "T22-153: 'enter' 리스너가 THEME_STORAGE_KEY 보다 뒤에 있지 않음(결정 IL4 위반)"
  fi

  # T22-158(재조준 2차, B2 완료 — dashboard-native-data-source PRP §6.3, docs/prps/
  # dashboard-into-hub.md HD1·HD2·§17-2 안 A 로 대상 재조준): 이 계약 문구("서브에이전트
  # 디스패치·결과 시점에는 아무것도 기록하지 않는다" — DN4·DN6, 단계 상태·진행률은
  # 기록에서 파생된다)를 지금 갖는 문서가 role-separation.md 에서 hub/rules/
  # dashboard-recording.md 로 옮겨갔다 — 안 A 는 role-separation.md 에 포인터조차 남기지
  # 않으므로, 그 문서는 더 이상 이 문구를 가질 수 없다(가지면 안 A 위반이다). 이전(移轉)
  # 원본·목적지가 서로 다른 결함을 겨눠 T22-170a/b 등과 같은 문자 접미로 나눈다(검수
  # 1회차 F15 승급 작업 중 식별 — 원래 한 ID 아래 note_failure 2건이 있었다).
  if ! grep -qF '디스패치·결과 시점에는' "$REPO_ROOT/hub/rules/dashboard-recording.md"; then
    note_failure "T22-158a: hub/rules/dashboard-recording.md 에 '디스패치·결과 시점에는' 문구 미발견(DN4·DN6 파생 계약 누락)"
  fi
  if grep -qF '디스패치·결과 시점에는' "$REPO_ROOT/rules/workflow/role-separation.md"; then
    note_failure "T22-158b: rules/workflow/role-separation.md 에 그 문구가 남아 있음(§17-2 안 A 위반 — 포인터조차 남기지 않기로 했다)"
  fi

  # T22-159(재조준 2차, docs/prps/dashboard-into-hub.md HD10): "### 대시보드 경로 규칙" 절이
  # hub/README.md 「진행 기록」 안에 H3 로 존재하고, 그 절 범위에 세 토큰이 모두 있으며,
  # "### 헬퍼 스크립트" 절보다 앞선 줄에 온다(줄 번호 비교). 이 두 절이 hub/README.md 의
  # 다른 H2 절과 섞이지 않도록 H3(###)로 앵커한다 — dashboard.md 시절엔 H2(##)였다.
  local path_rule_heading_line helper_table_heading_line
  path_rule_heading_line=$(grep -n '^### 대시보드 경로 규칙$' "$dashboard_command_file" | head -1 | cut -d: -f1)
  helper_table_heading_line=$(grep -n '^### 헬퍼 스크립트$' "$dashboard_command_file" | head -1 | cut -d: -f1)
  if [[ -z "$path_rule_heading_line" ]]; then
    record_failure "$test_name" "T22-159: '### 대시보드 경로 규칙' 절 미발견"
    return 1
  fi
  if [[ -z "$helper_table_heading_line" ]] || [[ "$path_rule_heading_line" -ge "$helper_table_heading_line" ]]; then
    record_failure "$test_name" "T22-159: '대시보드 경로 규칙' 절이 '헬퍼 스크립트' 절보다 앞에 있지 않음"
    return 1
  fi
  local path_rule_section
  path_rule_section=$(sed -n '/^### 대시보드 경로 규칙/,/^### 데이터 모델/p' "$dashboard_command_file")
  local path_rule_token
  for path_rule_token in 'CLAUDE_CODE_SESSION_ID' '.claude/dashboards/' 'hub_dashboard_log.py'; do
    if ! grep -qF -- "$path_rule_token" <<< "$path_rule_section"; then
      note_failure "T22-159: '대시보드 경로 규칙' 절에 토큰 미발견: $path_rule_token"
    fi
  done

  # T22-160(재조준, DN9): LEGACY 단일 파일 쓰기 모드가 완전히 폐기됐다 — 리텐션 임계값·
  # 세션 ID 환경변수 읽기는 남아있고, 옛 LEGACY 경로 리터럴은 되돌아오지 않는다.
  local dn9_token
  for dn9_token in 'RETENTION_SECONDS = 7 * 24 * 60 * 60' 'os.environ.get("CLAUDE_CODE_SESSION_ID")'; do
    if ! grep -qF -- "$dn9_token" "$dashboard_union_file"; then
      note_failure "T22-160: 문서+헬퍼 어디에도 토큰 미발견: $dn9_token"
    fi
  done
  if grep -qF 'rm -f .claude/dashboard.html' "$dashboard_union_file"; then
    record_failure "$test_name" "T22-160: 옛 리터럴 'rm -f .claude/dashboard.html' 이 남아있음(경로 규칙 미적용)"
    return 1
  fi

  # T22-161(참 불변식): 코드 블록 안의 .claude/dashboard.html 리터럴은 항상 0건이어야 한다
  # (LEGACY 단일 파일 경로가 이제 문서 어디에도 없다, DN9).
  local unprotected_legacy_literal_count
  unprotected_legacy_literal_count=$(awk '
    /^[[:space:]]*```/ { fenced = !fenced; next }
    { code = fenced || /^[[:space:]]{4,}[^ ]/ }
    code && /\.claude\/dashboard\.html/ { count++ }
    END { print count + 0 }
  ' "$dashboard_command_file")
  if [[ "$unprotected_legacy_literal_count" -ne 0 ]]; then
    note_failure "T22-161: 보호되지 않은 레거시 리터럴 .claude/dashboard.html 이 코드 블록에 ${unprotected_legacy_literal_count}건(기대 0)"
  fi

  # T22-162(결정 ST5): .gitignore 에 .claude/dashboards/ 1줄이 있다.
  if ! grep -qxF '.claude/dashboards/' "$REPO_ROOT/.gitignore"; then
    record_failure "$test_name" "T22-162: .gitignore 에 .claude/dashboards/ 항목 없음"
    return 1
  fi

  # T22-163 삭제(→ T40-5, docs/prps/dashboard-into-hub.md HD10): 대상이던 dashboard.md 가
  # 툼스톤으로 사라졌다. 같은 성격의 증분 상한 래칫은 새 배포 대상 hub/rules/
  # dashboard-recording.md 를 겨냥해 T40-5 로 다시 선다(HUB_DASHBOARD_RULE_BUDGET_BYTES).

  # T22-164(진행중 단계 행 애니메이션): 새 @keyframes 이름·::after 훅·animation·
  # prefers-reduced-motion 분기가 모두 있어야 신호와 저감 대응이 함께 산다.
  local dz_step_anim_token
  for dz_step_anim_token in '@keyframes dz-step-active-pulse' 'ol.steps li.active .chip::after{' \
    'animation:dz-step-active-pulse' 'prefers-reduced-motion'; do
    if ! grep -qF -- "$dz_step_anim_token" "$dashboard_template_file"; then
      note_failure "T22-164: dashboard_template.html 에 $dz_step_anim_token 이 없음"
    fi
  done
  if ! grep -qE 'prefers-reduced-motion:reduce\)\{[^}]*li\.active \.chip::after\{animation:none' "$dashboard_template_file"; then
    note_failure "T22-164: reduced-motion 분기가 li.active .chip::after 의 애니메이션을 끄지 않음"
  fi
  if ! grep -qF -- '@keyframes dz-step-active-pulse{0%,100%{opacity:.6}' "$dashboard_template_file"; then
    note_failure "T22-164: dz-step-active-pulse 의 진폭이 .6 이 아님(회귀 — 옛 .3 으로 되돌아감)"
  fi

  # T22-167(주기 핀): pulse 주기가 4s 로 고정돼 있다.
  if ! grep -qF -- 'animation:dz-step-active-pulse 4s' "$dashboard_template_file"; then
    note_failure "T22-167: dz-step-active-pulse 의 주기가 4s 가 아님(회귀 — 옛 2.4s 로 되돌아감)"
  fi

  # T22-170a/b(밴드·바 부활 금지): ::before 바(a)·li.active 밴드(b)가 모두 없다.
  if grep -qF 'ol.steps li.active::before' "$dashboard_template_file"; then
    note_failure "T22-170a: dashboard_template.html 에 ol.steps li.active::before 잔재가 있음(밴드·바 부활 금지 위반)"
  fi
  if grep -qE 'li\.active\{[^}]*background:var\(--accent-soft\)' "$dashboard_template_file"; then
    note_failure "T22-170b: dashboard_template.html 에 li.active 밴드(background:var(--accent-soft)}) 잔재가 있음"
  fi

  # ---- T22-168 (H6, PRP shell-hardening §9-6, 대시보드와 무관 — 기존 그대로 유지): 값은
  # 상수명으로만 지목한다(rules-docs-sync.md §17-1). 전수 증명이 아니다.
  local harness_update_prose_file="$REPO_ROOT/commands/harness-update.md"
  if ! grep -qF 'diff -rq' "$harness_update_prose_file"; then
    note_failure "T22-168: harness-update.md 에 diff -rq 요약행 서술이 없음"
  fi
  if ! grep -qF 'MAX_DIFF_LINES' "$harness_update_prose_file"; then
    note_failure "T22-168: harness-update.md 가 diff 상한을 상수명(MAX_DIFF_LINES)으로 지목하지 않음"
  fi
  if grep -qF 'the diff content install.sh already printed' "$harness_update_prose_file"; then
    note_failure "T22-168: harness-update.md 에 install.sh 가 보여준 적 없는 diff content 주장이 남아있음"
  fi
  if ! grep -qF '.bak-<timestamp>' "$harness_update_prose_file"; then
    note_failure "T22-168: harness-update.md 가 H5 의 백업 파일명 형식(.bak-<timestamp>)을 서술하지 않음"
  fi
  if ! grep -qF 'no automatic cleanup' "$harness_update_prose_file"; then
    note_failure "T22-168: harness-update.md 가 백업 자동 정리 없음을 서술하지 않음"
  fi
  if grep -qF 'manifest v2' "$harness_update_prose_file"; then
    note_failure "T22-168: harness-update.md 에 낡은 표기 manifest v2 가 남아있음(현재 MANIFEST_VERSION 과 불일치)"
  fi

  # ---- T22-169 (H7, PRP shell-hardening §9-9, 대시보드와 무관 — 기존 그대로 유지): 세
  # 커맨드 frontmatter 에 disable-model-invocation: true 가 있다.
  local h7_frontmatter_file
  for h7_frontmatter_file in "commands/harness-update.md" "commands/prp-commit.md" "commands/prp-pr.md"; do
    if ! grep -qF 'disable-model-invocation: true' "$REPO_ROOT/$h7_frontmatter_file"; then
      note_failure "T22-169: $h7_frontmatter_file frontmatter 에 disable-model-invocation: true 없음(H7)"
    fi
  done

  # T22-171(원자적 쓰기 불변식 승계, M2 재조준 — 사이드카·HTML 쓰기는 HD8·HD15 로 사라졌다):
  # JSONL·settings.local.json 쓰기가 모두 원자적 쓰기 경로(_write_text_atomically)를 여러
  # 차례 호출한다 — 직접 쓰기로 퇴행해
  # 부분 쓰기 위험을 다시 들이는 것을 막는다.
  local atomic_write_hit_count
  atomic_write_hit_count=$(grep -oF '_write_text_atomically(' "$dashboard_helper_file" | wc -l | tr -d ' ')
  if [[ "$atomic_write_hit_count" -lt 2 ]]; then
    note_failure "T22-171: hub_dashboard_log.py 에 _write_text_atomically( 등장이 ${atomic_write_hit_count}회(기대 2회 이상 — 정의+호출)"
  fi

  # T22-176(신설, docs/prps/dashboard-into-hub.md HD14 재조준 — 검수 1회차 F4): 로컬
  # _atomic_write_text 정의는 사라졌다 — hub_dashboard_log.py 는 이제 hub_atomic_write.
  # atomic_write_text 를 재사용한다(중복 구현 금지). 그 임포트 자체가 사라지면
  # _write_text_atomically 래퍼가 정의조차 되지 않아 위 T22-171 보다 먼저 깨져야 하는
  # 결함이라 별도 ID 로 분리한다(T22-171 과 같은 실패 보고 줄에 토큰이 겹치던 것을
  # 검수가 지적했다).
  if ! grep -qF 'import hub_atomic_write' "$dashboard_helper_file"; then
    note_failure "T22-176: hub_dashboard_log.py 가 hub_atomic_write 를 임포트하지 않음(HD14 재사용 위반)"
  fi

  # T22-175(신설, DN16): switch 절차가 dashboard_enabled 필드만 설정하고 settings.local.json
  # 을 통째로 덮어쓰지 않는다는 보증이 헬퍼 소스 자체에 있다(문서 T23-8·T23-9 의 코드 대응).
  if ! grep -qF 'settings["dashboard_enabled"] = desired_enabled' "$dashboard_helper_file"; then
    note_failure "T22-175: dashboard_helper.py 에 dashboard_enabled 필드 단독 대입이 없음(DN16 위반 가능성)"
  fi
  if ! grep -qF 'INVALID-SETTINGS' "$dashboard_helper_file"; then
    note_failure "T22-175: dashboard_helper.py 에 INVALID-SETTINGS 출력이 없음"
  fi

  finish_group "$test_name"
}

# T23: 진행 기록 스위치의 문서 정합성 (하위 검증 T23-1~T23-11). docs/prps/dashboard-into-hub.md
# HD1·HD9·HD10 재조준 — dashboard.md 는 툼스톤으로 사라지고 그 자리를 commands/hub.md ·
# hub/rules/dashboard-recording.md · hub/README.md 가 나눠 받는다. 이 기능은 hub/README.md ·
# hub/rules/dashboard-recording.md · commands/hub.md 세 문서가 같은 설정 키
# (dashboard_enabled)에 합의해야만 동작하므로, 문자열 정합성 회귀를 grep 으로 막는다.
#
# 한계(비망라, 검수 1회차 F15 — 승급 작업 중 이 그룹에 disclaimer 가 없었음을 확인) — 아래
# grep -q 검사는 대상 파일 전체에서 문구의 "존재"만 보고, 그 문구가 의도한 절(예: 설치
# 절차의 올바른 단계 번호 아래)에 있는지는 보지 않는다. 문구가 파일 어딘가로 옮겨지거나
# 무관한 문맥에 재사용돼도 이 검사는 통과한다. 전수 증명이 아니다.
test_dashboard_option_docs() {
  local test_name="T23"
  local test_desc="진행 기록 스위치 문서 정합성 (T23-1~T23-11)"
  log_test_name "$test_name" "$test_desc"

  local sandbox
  sandbox=$(mktemp -d)
  register_cleanup_path "$sandbox"

  cd "$sandbox"
  "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1

  local dashboard_command_file="./.claude/commands/hub.md"
  # README.md 는 install.sh 가 배포하는 파일이 아니므로(레포 자체 문서) 설치된 사본이 아니라
  # 레포 원본을 검사한다 — T22-138 이 install.sh 를 REPO_ROOT 기준으로 검사하는 것과 동일 방식.
  local readme_file="$REPO_ROOT/README.md"

  # T23-1: README 에 AI 에이전트 설치 절차 섹션이 존재
  if ! grep -q "AI 에이전트로 설치" "$readme_file"; then
    record_failure "$test_name" "T23-1: README 에 AI 에이전트 설치 절차 섹션 미발견"
    return 1
  fi

  # T23-2: 절차가 대상 프로젝트 바깥 clone 을 명시
  if ! grep -q "바깥에 clone" "$readme_file"; then
    record_failure "$test_name" "T23-2: 바깥에 clone 문구 미발견"
    return 1
  fi

  # T23-3: CLAUDE.md 충돌 시 자동 --force 금지 문구가 존재
  if ! grep -q "자동으로 .*--force.* 를 붙이지 않는다" "$readme_file"; then
    record_failure "$test_name" "T23-3: 자동 --force 금지 문구 미발견"
    return 1
  fi

  # T23-4(재조준, HD1): 설치 절차에 옛 대시보드 옵션 질문 단계가 없고(역방향), 대신 허브
  # 안내 1줄로 바뀌었다. 역방향(잔재 부활)과 정방향(안내 문구 누락)이 서로 다른 결함이라
  # 문자 접미로 나눈다(검수 1회차 F15 승급 작업 중 식별).
  if grep -q "대시보드 옵션 질문" "$readme_file"; then
    record_failure "$test_name" "T23-4a: README 설치 절차에 옛 '대시보드 옵션 질문' 단계가 남아 있음(HD1 위반)"
    return 1
  fi
  if ! grep -q "진행 기록(대시보드)은 허브 기능이다" "$readme_file"; then
    record_failure "$test_name" "T23-4b: README 설치 절차에 허브 안내 문구가 없음"
    return 1
  fi

  # T23-5(재조준, HD9): commands/hub.md 에 /hub dashboard on|off 절이 존재
  if ! grep -qF '## `/hub dashboard on|off`' "$dashboard_command_file"; then
    record_failure "$test_name" "T23-5: /hub dashboard on|off 절 미발견"
    return 1
  fi

  # T23-6(재조준, HD9): frontmatter argument-hint 에 dashboard on·dashboard off 가 노출
  if ! head -4 "$dashboard_command_file" | grep -qF "dashboard on|dashboard off"; then
    record_failure "$test_name" "T23-6: argument-hint 에 dashboard on|dashboard off 미노출"
    return 1
  fi

  # T23-7(재조준, HD2·HD9·HD10): 세 문서(hub/rules/dashboard-recording.md·commands/hub.md·
  # hub/README.md)가 키 이름을 동일 표기로 참조. 이 항목이 가장 중요하다 — 한 곳에서
  # 이름이 어긋나면 미지의 설정 키로 조용히 무시된다. README.md 는 이 목록에서 빠졌다 —
  # dashboard_enabled 언급 자체가 그쪽에는 더 이상 없다(HD1, 대시보드 절차 전체가 허브
  # 쪽으로 옮겨갔다).
  local doc_file
  for doc_file in "$REPO_ROOT/hub/rules/dashboard-recording.md" "$dashboard_command_file" "$REPO_ROOT/hub/README.md"; do
    if [[ "$(grep -c "dashboard_enabled" "$doc_file")" -lt 1 ]]; then
      record_failure "$test_name" "T23-7: dashboard_enabled 미참조: $doc_file"
      return 1
    fi
  done

  # T23-8: on/off 절이 기존 필드 보존을 명시
  if ! grep -q "기존 필드는 어떤 경우에도 건드리지 않는다" "$dashboard_command_file"; then
    record_failure "$test_name" "T23-8: 기존 필드 보존 문구 미발견"
    return 1
  fi

  # T23-9: 파싱 불가 파일을 덮어쓰지 않는다는 문구 존재
  if ! grep -q "덮어쓰면 사용자의 권한 허용 목록이 사라진다" "$dashboard_command_file"; then
    record_failure "$test_name" "T23-9: 파싱 불가 파일 보호 문구 미발견"
    return 1
  fi

  # T23-10: on/off 가 대시보드 HTML 을 만들지도 지우지도 않음을 명시
  if ! grep -q "만들지도 지우지도 않는다" "$dashboard_command_file"; then
    record_failure "$test_name" "T23-10: HTML 비접촉 문구 미발견"
    return 1
  fi

  # T23-11: README 가 병합 절차를 복제하지 않고 참조만 함 (DRY 경계 회귀 방지).
  # README 에 절차 전문을 붙여넣으면 이 문자열이 급증하므로 상한을 둔다.
  local settings_json_mentions
  settings_json_mentions=$(grep -c "settings.local.json" "$readme_file")
  if [[ "$settings_json_mentions" -gt 3 ]]; then
    record_failure "$test_name" "T23-11: README 가 병합 절차를 복제한 것으로 의심됨 (settings.local.json 언급 ${settings_json_mentions}회)"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T24: 허브 + hub_dashboard_render.py 순수 로직 단위 테스트 (stdlib unittest). 종료
# 코드만 검사하고, 실패 시 출력을 그대로 흘려보내 원인을 바로 알 수 있게 한다.
# discover 경로가 tests/hub 가 아니라 tests 전체인 이유(역사적, dashboard-worktree-bash-gate
# PRP §8.1) — 원래는 tests/commands/test_dashboard_helper.py 를 함께 줍기 위해서였다. 그
# 파일은 docs/prps/dashboard-into-hub.md M1(HD1·HD4)이 tests/hub/test_hub_dashboard_log.py
# 로 이전하며 tests/commands/ 자체가 사라졌다 — 지금은 tests/ 아래에 hub/ 외의 테스트
# 디렉터리가 없어 이 넓은 scope 가 tests/hub 단독 scope 와 결과가 같다(무해한 잔존, 좁힐
# 실익이 없어 손대지 않는다). 기존 hub 테스트는 그대로 발견된다(실측 확인 — 그 시점
# 617건, S3b 후반부-1 이 삼킨 예외 래퍼의 음성 대조 7건을 더해 624건이다).
test_hub_unit_tests() {
  local test_name="T24"
  local test_desc="허브+hub_dashboard_render 순수 모듈 단위 테스트 (python3 -m unittest discover)"
  log_test_name "$test_name" "$test_desc"

  # PYTHONDONTWRITEBYTECODE=1 — tests/hub/test_hub_dashboard_log.py 가 sys.path 를 조정해
  # hub/bin/hub_dashboard_render.py 를 레포 원본 경로에서 직접 import 한다. 바이트코드
  # 캐시를 끄지 않으면 hub/bin/__pycache__/ 가 레포에 생긴다 — hub/install.sh 의 파일 수
  # 계산(copy_managed_bin_files·verify_installed_file_count)은 find -maxdepth 1 -type f 로
  # 디렉터리를 애초에 세지 않아 여기서는 회귀가 재현되지 않지만(commands/dashboard_render.py
  # 시절 root install.sh 에서 실측됐던 것과 달리 안전하다), 레포에 원치 않는 산출물이
  # 남는 것 자체는 여전히 피할 이유라 이 플래그를 유지한다.
  local output
  local exit_code=0
  output=$(cd "$REPO_ROOT" && PYTHONDONTWRITEBYTECODE=1 python3 -m unittest discover -s tests -t "$REPO_ROOT" 2>&1) || exit_code=$?

  if [[ "$exit_code" -ne 0 ]]; then
    echo "$output"
    record_failure "$test_name" "python3 -m unittest discover 실패 (exit $exit_code)"
    return 1
  fi

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# 템플릿 CSS 규칙 추출기(T25-257~259·T25-262 공용) — 줄바꿈을 공백으로 펴고 공백 연속을 하나로 줄인 사본에서
# `선택자{선언들}` 를 한 줄에 하나씩 낸다. 여러 줄에 걸친 규칙을 한 줄 규칙처럼 grep -oE 로 뽑기 위한 것이다
# (T25-246 류의 기존 추출은 한 줄 규칙만 다룬다). 선택자는 ERE 조각으로 넘긴다(점·괄호·플러스는 호출자가
# 이스케이프한다). 규칙이 없으면 빈 출력이다 — 호출자가 앵커가 깨진 것으로 보고한다.
# 한계(비망라) — 주석 안에 같은 모양의 글자(선택자 바로 뒤의 여는 중괄호)가 있으면 그 주석도 규칙으로 뽑힌다:
# 그래서 이 가드들이 다루는 선택자 뒤에는 여는 중괄호를 주석에 적지 않는다. 전수 증명이 아니다.
extract_flattened_css_rules() {
  local css_file="$1" selector_pattern="$2"
  tr '\n' ' ' < "$css_file" | tr -s ' ' | grep -oE "${selector_pattern}\{[^}]*\}" || true
}

# 파이썬 상수 선언 `NAME = 10 * 60 * 1000`(정수 곱 한 줄)의 값을 divisor 로 나눈 몫을 낸다(T25-273 — README 의 「N MiB」·「N분」과
# 코드 상수를 같은 단위로 대조하는 용도). 우변이 정수 곱이 아니거나(주석이 붙은 줄·다른 식) 나누어 떨어지지 않거나 선언이 없으면 빈
# 출력이다 — 호출자가 「못 읽음」을 불일치로 보고한다(fail-closed). 산술 전개에 넘기는 식은 아래 정규식이 `[1-9][0-9]*( \* ...)*` 로
# 걸러낸 것뿐이라 파일 내용이 명령으로 해석될 길이 없다(앞자리 0 은 8진수로 읽히므로 정규식이 막는다).
read_python_product_constant() {
  local source_file="$1" constant_name="$2" divisor="$3" product_expression product_value
  product_expression=$(sed -nE "s/^${constant_name} = ([1-9][0-9]*( \\* [1-9][0-9]*)*)\$/\\1/p" "$source_file" | head -1)
  [[ -n "$product_expression" ]] || return 0
  product_value=$((product_expression))
  ((product_value % divisor == 0)) || return 0
  echo $((product_value / divisor))
}

# T25: 허브 문서·상수 정합성 (하위 검증 T25-1~T25-274)
#
# 한계(비망라, T37-13 선행 조건 — dashboard-ui-polish-4 PRP §8.1-4) — 이 그룹 검사 다수는
# grep -qF/-c 로 CSS 선언·리터럴·함수 시그니처의 존재만 본다. 토큰이 있다는 것과 그 토큰이
# 의도한 자리에서 의도한 대로 쓰였다는 것은 다른 명제다 — 예를 들어 존재 검사는 선택자가
# 다른 규칙 뒤로 옮겨져 캐스케이드 우선순위가 바뀌어도 잡지 않는다(줄 번호 비교로 순서를
# 못박은 소수의 검사만 예외, 예: T25-66·T25-170·T25-228). 같은 이유로, 함수 본문
# 안에서만 유효해야 하는 호출(예: setAttribute)의 존재 검사도 대다수는 대상 파일 **전체**
# 에서 리터럴을 찾을 뿐 그 호출이 실제로 그 함수 본문 안에 있는지는 보지 않는다 — 본문
# 밖(죽은 주석 등)으로 옮겨져도 그대로 통과한다(함수 본문을 sed 로 잘라 그 안에서만 찾는
# T25-129 류의 소수 검사만 예외). 전수 증명이 아니다.
test_hub_docs_and_constants() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T25"
  local test_desc="허브 문서·상수 정합성 (T25-1~T25-284)"
  log_test_name "$test_name" "$test_desc"

  local hub_settings_file="$REPO_ROOT/hub/bin/hub_settings.py"
  local hub_hook_file="$REPO_ROOT/hub/bin/hub_hook.py"
  local hub_py_file="$REPO_ROOT/hub/bin/hub.py"
  local hub_collect_file="$REPO_ROOT/hub/bin/hub_collect.py"
  local hub_config_file="$REPO_ROOT/hub/bin/hub_config.py"
  local hub_atomic_write_file="$REPO_ROOT/hub/bin/hub_atomic_write.py"
  local hub_model_file="$REPO_ROOT/hub/bin/hub_model.py"
  local hub_session_file="$REPO_ROOT/hub/bin/hub_session.py"
  local hub_session_facts_file="$REPO_ROOT/hub/bin/hub_session_facts.py"
  local hub_project_file="$REPO_ROOT/hub/bin/hub_project.py"
  local hub_server_state_file="$REPO_ROOT/hub/bin/hub_server_state.py"
  local hub_server_file="$REPO_ROOT/hub/bin/hub_server.py"
  local hub_daemon_file="$REPO_ROOT/hub/bin/hub_daemon.py"
  local hub_install_file="$REPO_ROOT/hub/install.sh"
  local hub_command_file="$REPO_ROOT/commands/hub.md"
  local harness_update_command_file="$REPO_ROOT/commands/harness-update.md"
  local dashboard_command_file="$REPO_ROOT/hub/README.md"
  local readme_file="$REPO_ROOT/README.md"
  local hub_dashboard_prp_file="$REPO_ROOT/docs/prps/hub-dashboard.md"
  local hub_session_revival_prp_file="$REPO_ROOT/docs/prps/hub-session-revival-and-stale-tier1.md"
  local test_hub_collect_file="$REPO_ROOT/tests/hub/test_hub_collect.py"

  # T25-1(개정 R-M5 — 대상 이동): HUB_FILE_COUNT 는 이제 hub/install.sh 가 갖는다. 그 값을
  # 여기 적지 않는다 — 바로 아래가 실측과 대조하는 검사이고, 적으면 hub/bin 에 파일이 늘
  # 때마다 낡는다(옛 문면의 「값 10」이 실제로 낡아 있었다).
  local declared_count actual_count
  declared_count=$(grep -oE '^readonly HUB_FILE_COUNT=[0-9]+' "$hub_install_file" | grep -oE '[0-9]+$')
  actual_count=$(find "$REPO_ROOT/hub/bin" -maxdepth 1 -type f | wc -l | tr -d ' ')
  if ! assert_equals "$actual_count" "$declared_count" "HUB_FILE_COUNT 일치"; then
    record_failure "$test_name" "T25-1: HUB_FILE_COUNT=$declared_count, 실제 파일 수=$actual_count"
    return 1
  fi

  # T25-2(개정 R-M5 — 반전): 루트 install.sh 는 hub 를 전혀 모른다. hub/install.sh 가 독립 설치한다
  local sandbox_root sandbox_hub
  sandbox_root=$(mktemp -d)
  sandbox_hub=$(mktemp -d)
  register_cleanup_path "$sandbox_root" "$sandbox_hub"

  HOME="$sandbox_root" "$INSTALL_SCRIPT" --scope user > /dev/null 2>&1
  if [[ -d "$sandbox_root/.claude/hub" ]]; then
    record_failure "$test_name" "T25-2: 루트 install.sh --scope user 후 .claude/hub 가 생성됨 (기대: 미생성)"
    return 1
  fi

  HOME="$sandbox_hub" "$hub_install_file" > /dev/null 2>&1
  local installed_hub_count
  installed_hub_count=$(find "$sandbox_hub/.claude/hub/bin" -maxdepth 1 -type f 2>/dev/null | wc -l | tr -d ' ')
  if [[ "$installed_hub_count" -ne "$declared_count" ]]; then
    record_failure "$test_name" "T25-2: hub/install.sh 설치 후 hub/bin 파일 수=$installed_hub_count (기대 $declared_count)"
    return 1
  fi

  # ---- T25-174 (N3, PRP shell-hardening §9-3 — H3 의 허브 트윈): TARGET_BIN_DIR 자신이
  # 심볼릭 링크면 허브 설치가 쓰기 전에 중단하고 링크 대상 파일은 그대로 남는다. 상대 경로
  # 링크로 재현한다(GOTCHA 5 — 절대 경로 링크는 이 환경에서 Permission denied 로 끝나 무엇을
  # 증명했는지 불분명해진다).
  local sandbox_n3_home sandbox_n3_attacker
  sandbox_n3_home=$(mktemp -d)
  sandbox_n3_attacker=$(mktemp -d)
  register_cleanup_path "$sandbox_n3_home" "$sandbox_n3_attacker"
  echo "원본 보존 확인용" > "$sandbox_n3_attacker/sentinel.md"
  mkdir -p "$sandbox_n3_home/.claude/hub"
  ( cd "$sandbox_n3_home/.claude/hub" \
    && ln -s "../../../$(basename "$sandbox_n3_attacker")" bin )

  local n3_exit=0
  ( HOME="$sandbox_n3_home" "$hub_install_file" > /dev/null 2>&1 ) || n3_exit=$?
  if [[ "$n3_exit" -eq 0 ]]; then
    record_failure "$test_name" "T25-174 (N3): TARGET_BIN_DIR 심링크에서도 허브 설치가 exit 0 — 심링크 관통 가드 회귀 의심"
    return 1
  fi
  if ! grep -qF "원본 보존 확인용" "$sandbox_n3_attacker/sentinel.md"; then
    record_failure "$test_name" "T25-174 (N3): 심링크 대상 파일의 내용이 변경됨(관통 발생 의심)"
    return 1
  fi

  # ---- T25-175 (M3, S1 검수 1회차 — check_preconditions 가 TARGET_HUB_DIR($HOME/.claude/
  # hub) 자신만 보고 그 부모($HOME/.claude)는 보지 않았다): $HOME/.claude 가 심링크이고
  # 그 안에 아직 hub/ 가 없는 신규 설치에서는 is_symlinked_path "$TARGET_HUB_DIR" 의 cd
  # 가 실패해 "심링크 아님"으로 오판되고, mkdir -p 가 그 심링크를 관통해 대상 밖에 쓴다.
  local sandbox_m3_home sandbox_m3_attacker
  sandbox_m3_home=$(mktemp -d)
  sandbox_m3_attacker=$(mktemp -d)
  register_cleanup_path "$sandbox_m3_home" "$sandbox_m3_attacker"
  ( cd "$sandbox_m3_home" && ln -s "../$(basename "$sandbox_m3_attacker")" .claude )

  local m3_exit=0
  ( HOME="$sandbox_m3_home" "$hub_install_file" > /dev/null 2>&1 ) || m3_exit=$?
  if [[ "$m3_exit" -eq 0 ]]; then
    record_failure "$test_name" "T25-175 (M3): \$HOME/.claude 자신이 심링크인 신규 설치에서도 허브 설치가 exit 0 — 심링크 관통 가드 회귀 의심"
    return 1
  fi
  if [[ -e "$sandbox_m3_attacker/hub" ]]; then
    record_failure "$test_name" "T25-175 (M3): \$HOME/.claude 심링크를 관통해 대상 밖(hub/)에 파일이 생성됨"
    return 1
  fi

  # T25-3(개정 R-4 — 대상 이동): 마커 문서화는 이제 hub/README.md 가 맡는다(root README.md 는 분리됨)
  local marker="# DZH_HUB_HOOK"
  local hub_readme_file="$REPO_ROOT/hub/README.md"
  local doc_file
  for doc_file in "$hub_settings_file" "$hub_command_file" "$hub_readme_file"; do
    if ! grep -qF "$marker" "$doc_file"; then
      note_failure "T25-3: $marker 마커 미발견: $doc_file"
    fi
  done

  # T25-4: 훅 커맨드 문자열에 || true 와 >/dev/null 이 모두 있다
  if ! grep -F "|| true" "$hub_settings_file" | grep -qF ">/dev/null"; then
    note_failure "T25-4: 훅 커맨드에 || true 와 >/dev/null 이 한 줄에 함께 없음"
  fi

  # T25-5: type: "http" 를 쓰지 말라는 근거 문구
  if ! grep -qF 'type: "http"' "$hub_command_file"; then
    note_failure "T25-5: type:\"http\" 관련 근거 문구 미발견"
  fi

  # T25-6(재앵커, dashboard-native-data-source PRP §6.6 — dashboard-into-hub PRP M1·M2 로
  # 경로만 재조준): 단계 줄 템플릿의 생산자가 문서 프로즈에서 hub_dashboard_render.py 의 코드
  # 자체로 옮겨갔다(DN3) — 그 <li id="dz-step-%d"> 형태는 템플릿 자체 폴링의 id 계약이다.
  # impl 세부 작업 패널은 폐기(DN8)돼 dz-impl 쪽 단계 줄 생산자는 더 이상 없다.
  if ! grep -qF 'id="dz-step-%d"' "$REPO_ROOT/hub/bin/hub_dashboard_render.py"; then
    note_failure "T25-6: hub_dashboard_render.py 에 단계 줄 템플릿(id=\"dz-step-%d\") 미발견"
  fi

  # T25-7: hub_hook.py 에 Notification 문자열이 없다 (미설치 결정의 회귀 방지)
  if grep -q "Notification" "$hub_hook_file"; then
    note_failure "T25-7: hub_hook.py 에 Notification 문자열이 존재함"
  fi

  # T25-8(개정 — 포트 상수가 hub_model.py 로 이동): 8794 정합, 8791 부재
  if ! grep -q "8794" "$hub_model_file" || ! grep -q "8794" "$hub_command_file"; then
    note_failure "T25-8: 포트 8794 가 hub_model.py 또는 commands/hub.md 에 없음"
  fi
  if grep -q "8791" "$hub_model_file" "$hub_command_file"; then
    note_failure "T25-8: /dashboard 의 포트 8791 이 허브 파일에 등장함"
  fi

  # T25-9(재조준, HD1 — dashboard 가 독립 커맨드에서 빠졌다): README.md 가 "독립 커맨드 1종"으로 갱신됐다
  if ! grep -qF "독립 커맨드 1종" "$readme_file"; then
    record_failure "$test_name" "T25-9: README 에 '독립 커맨드 1종' 문구 미발견"
    return 1
  fi

  # T25-10(+ T25-27 — hub_usage.py 추가 + 결정 MS1 분리 3개 편입 + hub_config.py 편입,
  # docs/prps/hub-collect-split-for-merge.md; + MEDIUM-2, 검수 2회차 — dashboard_render.py
  # 편입(dashboard-into-hub PRP M1 로 hub_dashboard_render.py 경로 재조준); +
  # docs/prps/hub-live-session-native-source.md 결정 LS2 — hub_live_session.py 편입; +
  # docs/prps/hub-subagent-background-pause.md 결정 BW11(M1) — hub_session.py 에서 분리된
  # hub_session_facts.py 편입; + docs/prps/hub-live-activity.md 결정 LA14 — hub_activity.py 편입; +
  # docs/prps/harness-versioning.md 단계 B — hub_release.py 편입):
  # hub_model.py·hub_parse.py·hub_usage.py·hub_session.py·hub_session_facts.py·hub_project.py·
  # hub_server_state.py·hub_config.py·hub_dashboard_render.py·hub_live_session.py·hub_activity.py·hub_release.py 에
  # 파일시스템 접근이 없다(순수 레이어 경계의 기계적 강제). dashboard_render.py 는 ★순수 마커를 자체
  # 선언하고도 이 목록에 없었다(구현 시점 누락). hub_atomic_write.py 는 tempfile·os.fdopen 을
  # 쓰므로 이 목록에 넣지 않는다.
  local pure_file
  for pure_file in "$REPO_ROOT/hub/bin/hub_model.py" "$REPO_ROOT/hub/bin/hub_parse.py" "$REPO_ROOT/hub/bin/hub_usage.py" \
      "$hub_session_file" "$hub_session_facts_file" "$hub_project_file" "$hub_server_state_file" "$hub_config_file" \
      "$REPO_ROOT/hub/bin/hub_dashboard_render.py" "$REPO_ROOT/hub/bin/hub_live_session.py" \
      "$REPO_ROOT/hub/bin/hub_activity.py" "$REPO_ROOT/hub/bin/hub_release.py"; do
    if grep -qE 'open\(|Path\(|os\.' "$pure_file"; then
      record_failure "$test_name" "T25-10: $pure_file 에 파일시스템 접근 흔적(open(/Path(/os.)이 있음"
      return 1
    fi
  done

  local hub_template_file="$REPO_ROOT/hub/bin/hub_template.html"
  local dashboard_template_file="$REPO_ROOT/hub/bin/hub_dashboard_template.html"

  # T25-11(개정 3 — 세션 식별 줄이 short_id 렌더를 되살림, §4. 개정 4 — 결정 AR4·AR8,
  # docs/prps/hub-agent-runs-and-prompt-source.md: run.agent_type 이 이제 칩에 직접 쓰이지
  # 않고 agentRunChipLabel(run)·agentRunTooltipText(run) 을 거쳐 간접적으로 실린다): 세션
  # 줄의 동적 값은 반드시 escapeHtml 을 통과한다. 부정 검사(`+ session.short_id +` 리터럴
  # 금지)는 그대로 둔다 — short_id 는 다시 렌더되지만 반드시 escapeHtml(session.short_id)
  # 경유여야 하고, 이스케이프 없는 옛 삽입 형태가 되살아나는 것을 막는다. 서브에이전트
  # 타입명이 실리는 두 경로(칩 라벨·툴팁) 모두 escapeHtml 을 거치는지 긍정 검사한다.
  # short_id·session_id 자체의 긍정 검사는 T25-125 가 담당한다(세션 식별 줄 전용 검사로 분리).
  # 재검수 1회차 H1 — 세 필드(칩 라벨·툴팁·제목) 중 제목(agentRunDisplayTitle)만 긍정 검사가
  # 빠져 있었다. 제목은 meta.description 을 담아 AR10 이 "프롬프트 파생 자유 텍스트"로
  # 규정한 값이라 세 값 중 가장 위험한데, 그 값만 회귀 가드가 없었다(검수자가 escapeHtml
  # 을 벗겨내고 tests/hub 736건 전부 통과함을 실측).
  if grep -qF "+ session.short_id +" "$hub_template_file"; then
    note_failure "T25-11: session.short_id 가 escapeHtml 없이 삽입됨(m9 회귀)"
  fi
  if ! grep -qF "escapeHtml(agentRunChipLabel(run))" "$hub_template_file"; then
    note_failure "T25-11: 서브에이전트 실행 칩 라벨이 escapeHtml 없이 삽입됨"
  fi
  if ! grep -qF "escapeHtml(agentRunTooltipText(run))" "$hub_template_file"; then
    note_failure "T25-11: 서브에이전트 실행 툴팁이 escapeHtml 없이 삽입됨"
  fi
  if ! grep -qF "escapeHtml(agentRunDisplayTitle(run))" "$hub_template_file"; then
    note_failure "T25-11: 서브에이전트 실행 제목이 escapeHtml 없이 삽입됨(재검수 1회차 H1)"
  fi

  # T25-12(검수 M6 회귀): 티어 1 렌더에 구현 진행·stale 병기가 반영됐다. 활성 단계 표시(진행률 줄 맨 앞 단계 칩)는
  # 결정 LM12 로 걷혔다 — 그 부재는 T25-263 이 지킨다.
  if ! grep -qF "renderTier1ImplProgress" "$hub_template_file"; then
    note_failure "T25-12: 티어 1 렌더에 구현 진행(impl_done/impl_total) 표시가 없음"
  fi
  if ! grep -qF "직전 " "$hub_template_file"; then
    record_failure "$test_name" "T25-12: stale 세션의 '직전 <base_state>' 병기 문구가 없음"
    return 1
  fi

  # T25-13(검수 M1 회귀): JSON 유니코드 이스케이프로 교체됐고, HTML 엔티티 치환으로 되돌아가지 않았다
  local render_hub_html_file="$REPO_ROOT/hub/bin/hub_model.py"
  if ! grep -qF "u003c" "$render_hub_html_file"; then
    note_failure "T25-13: render_hub_html 에 JSON 유니코드 이스케이프(u003c)가 없음"
  fi
  if grep -qF "&lt;" "$render_hub_html_file"; then
    record_failure "$test_name" "T25-13: render_hub_html 이 HTML 엔티티 치환으로 회귀함(M1 회귀)"
    return 1
  fi

  # T25-14: hub/bin/*.py·commands/hub.md 에 serve 잔재가 없다(폐기 회귀 방지, 개정 쟁점 R2)
  local serve_leftover_pattern='start_serving|stop_serving|/hub serve[^r]|pkill'
  local source_file
  for source_file in "$REPO_ROOT"/hub/bin/*.py "$hub_command_file"; do
    if grep -qE "$serve_leftover_pattern" "$source_file"; then
      note_failure "T25-14: $source_file 에 폐기된 serve 잔재가 남아 있음"
    fi
  done

  # T25-15: hub_server.py 가 SimpleHTTPRequestHandler 를 쓰지 않고 화이트리스트를 갖는다(노출 표면 회귀 방지)
  if grep -qF "SimpleHTTPRequestHandler" "$hub_server_file"; then
    note_failure "T25-15: hub_server.py 가 SimpleHTTPRequestHandler 를 사용함(디렉토리 전체 노출 위험)"
  fi
  if ! grep -qF "ALLOWED_REQUEST_PATHS" "$hub_server_file"; then
    record_failure "$test_name" "T25-15: hub_server.py 에 ALLOWED_REQUEST_PATHS 화이트리스트가 없음"
    return 1
  fi

  # T25-16(검수 Nit2 — AST 검사로 승격): hub_daemon.py 의 **같은 함수 안에서** os.kill 호출보다
  # is_our_server_process 호출이 먼저 나와야 한다(PID 재사용 방어 회귀 방지). 텍스트 줄 번호
  # 비교보다 엄밀하다 — 함수 경계를 실제로 구분하므로 무관한 함수의 신원 확인이 우연히
  # 앞줄에 있다는 이유로 통과하는 오탐이 없다.
  local ast_check_output
  ast_check_output=$(python3 - "$hub_daemon_file" <<'PYEOF'
import ast
import sys

source_path = sys.argv[1]
tree = ast.parse(open(source_path, encoding="utf-8").read(), filename=source_path)


def is_os_kill_call(node):
    return (
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
        and node.func.attr == "kill"
        and isinstance(node.func.value, ast.Name)
        and node.func.value.id == "os"
    )


def is_identity_check_call(node):
    return (
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == "is_our_server_process"
    )


violations = []
kill_call_total = 0
for func in ast.walk(tree):
    if not isinstance(func, (ast.FunctionDef, ast.AsyncFunctionDef)):
        continue
    kill_calls = [n for n in ast.walk(func) if is_os_kill_call(n)]
    if not kill_calls:
        continue
    kill_call_total += len(kill_calls)
    check_lines = [n.lineno for n in ast.walk(func) if is_identity_check_call(n)]
    for kill_call in kill_calls:
        if not any(line < kill_call.lineno for line in check_lines):
            violations.append(f"{func.name}() 의 {kill_call.lineno}번째 줄")

if kill_call_total == 0:
    print("NO_KILL_CALLS_FOUND")
elif violations:
    print("VIOLATIONS:" + "; ".join(violations))
else:
    print("OK")
PYEOF
)
  if [[ "$ast_check_output" == "NO_KILL_CALLS_FOUND" ]]; then
    note_failure "T25-16: hub_daemon.py 에서 os.kill 호출을 찾지 못함"
  fi
  if [[ "$ast_check_output" != "OK" ]]; then
    note_failure "T25-16: 신원 확인 없이 os.kill 을 호출하는 지점 — $ast_check_output"
  fi

  # T25-172(신설, hub-server-identity PRP §9-4·§12 승인 4): is_our_server_process 호출의
  # 두 번째 인자가 모듈 상수 HUB_PY_PATH(판정자 자기 경로) 인 곳이 없어야 한다. 신원의
  # 기준을 "판정자의 경로"에서 "레코드가 적어 둔 기동 경로"로 옮긴 설계(같은 PRP §1-(2))가
  # 되돌아가면, 레포 사본·설치본처럼 허브가 두 벌 존재하는 환경에서 오판이 재발한다.
  # T25-16 과 같은 AST 관용구를 쓰되, 판정 로직 자체는 여기 두지 않는다 — hub_daemon.py
  # 쪽 판정 분기를 전용 함수로 뽑지 않은 이유(D7)와 같다: 이 검사는 그 파일을 읽기만 한다.
  local identity_arg_check_output
  identity_arg_check_output=$(python3 - "$hub_daemon_file" <<'PYEOF'
import ast
import sys

source_path = sys.argv[1]
tree = ast.parse(open(source_path, encoding="utf-8").read(), filename=source_path)


def is_identity_check_call(node):
    return (
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == "is_our_server_process"
    )


def second_positional_or_keyword_arg(node, keyword_name):
    # 위치 인자든 키워드 인자든 같은 자리를 겨눈다(2회차 검수 Minor 4) — 위치 인자만 보면
    # is_our_server_process(ps_args, hub_py_path=HUB_PY_PATH) 처럼 키워드 형태로 되돌리는
    # 변조가 조용히 통과한다(행위는 원래 결함과 동일한데 이 가드만 못 본다).
    if len(node.args) >= 2:
        return node.args[1]
    for keyword in node.keywords:
        if keyword.arg == keyword_name:
            return keyword.value
    return None


violations = []
call_total = 0
for node in ast.walk(tree):
    if not is_identity_check_call(node):
        continue
    call_total += 1
    identity_arg = second_positional_or_keyword_arg(node, "hub_py_path")
    if isinstance(identity_arg, ast.Name) and identity_arg.id == "HUB_PY_PATH":
        violations.append(f"{node.lineno}번째 줄")

if call_total == 0:
    print("NO_CALLS_FOUND")
elif violations:
    print("VIOLATIONS:" + "; ".join(violations))
else:
    print("OK")
PYEOF
)
  if [[ "$identity_arg_check_output" == "NO_CALLS_FOUND" ]]; then
    note_failure "T25-172: hub_daemon.py 에서 is_our_server_process 호출을 찾지 못함"
  elif [[ "$identity_arg_check_output" == VIOLATIONS:* ]]; then
    # NO_CALLS_FOUND 와 서로 배타적인 elif 다(2회차 검수 Minor 4) — 이전에는 독립된 두 if 라
    # NO_CALLS_FOUND 에서도 이 분기가 함께 발화해 "다시 HUB_PY_PATH 를 인자로 씀"이라는
    # 사실과 다른 메시지가 같이 나왔다.
    note_failure "T25-172: is_our_server_process 호출이 다시 HUB_PY_PATH 를 인자로 씀 — $identity_arg_check_output"
  elif [[ "$identity_arg_check_output" != "OK" ]]; then
    # fail-close(2회차 검수 Minor 4) — python 프로브가 죽거나(트레이스백) 예상 밖 출력을
    # 내면 위 두 분기 어디에도 안 걸려 조용히 통과할 뻔한 자리를 여기서 잡는다.
    note_failure "T25-172: 판정 불가(python 프로브 이상 출력) — $identity_arg_check_output"
  fi

  # T25-173(신설, hub-server-identity PRP §6 생산 지점 — 2회차 검수 Major 1 · 3회차 검수
  # Minor B): hub_server.py 의 run_server 가 ServerRecord(...) 호출에서 hub_py_path 키워드에
  # 실제로 sys.argv[0] 을 넘기는지 AST 로 본다(T25-172 와 같은 관용구로 승격) —
  # grep -qF "hub_py_path=sys.argv[0]" 는 그 부분문자열이 죽은 조건식
  # (`hub_py_path=sys.argv[0] if False else None`)이나 주석 안에만 남아도 파일 텍스트에
  # 있다는 이유로 통과했다(3회차 검수 Minor B 가 실측). 이 한 줄이 승인 1·2(신원 기준을
  # 레코드가 적어 둔 기동 경로로 옮긴다)를 성립시키는 유일한 지점이다 — 사라지면 이 서버가
  # 쓰는 모든 신규 레코드가 구버전 취급되어, 조건부로만 승인된 §3 의 완화 기준이 예외 없는
  # 전면 기준으로 영구 승격한다(관측 A·B 의 고아 위험이 상시화된다).
  local record_arg_check_output
  record_arg_check_output=$(python3 - "$hub_server_file" <<'PYEOF'
import ast
import sys

source_path = sys.argv[1]
tree = ast.parse(open(source_path, encoding="utf-8").read(), filename=source_path)


def is_server_record_call(node):
    return (
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
        and node.func.attr == "ServerRecord"
    )


def hub_py_path_keyword_value(node):
    for keyword in node.keywords:
        if keyword.arg == "hub_py_path":
            return keyword.value
    return None


def is_sys_argv_zero(node):
    return (
        node is not None
        and isinstance(node, ast.Subscript)
        and isinstance(node.value, ast.Attribute)
        and node.value.attr == "argv"
        and isinstance(node.value.value, ast.Name)
        and node.value.value.id == "sys"
        and isinstance(node.slice, ast.Constant)
        and node.slice.value == 0
    )


violations = []
call_total = 0
for node in ast.walk(tree):
    if not is_server_record_call(node):
        continue
    call_total += 1
    if not is_sys_argv_zero(hub_py_path_keyword_value(node)):
        violations.append(f"{node.lineno}번째 줄")

if call_total == 0:
    print("NO_CALLS_FOUND")
elif violations:
    print("VIOLATIONS:" + "; ".join(violations))
else:
    print("OK")
PYEOF
)
  if [[ "$record_arg_check_output" == "NO_CALLS_FOUND" ]]; then
    note_failure "T25-173: hub_server.py 에서 ServerRecord 호출을 찾지 못함"
  elif [[ "$record_arg_check_output" == VIOLATIONS:* ]]; then
    note_failure "T25-173: hub_server.py 에 hub_py_path=sys.argv[0] 이 없음(생산 지점 소실) — $record_arg_check_output"
  elif [[ "$record_arg_check_output" != "OK" ]]; then
    # fail-close(T25-172 와 같은 형태) — python 프로브가 죽거나 예상 밖 출력을 내면 위 두
    # 분기 어디에도 안 걸려 조용히 통과할 뻔한 자리를 여기서 잡는다.
    note_failure "T25-173: 판정 불가(python 프로브 이상 출력) — $record_arg_check_output"
  fi

  # T25-17: hub_daemon.py 에 start_new_session=True 가 있다(세션 무관 수명, 요구 R-1 의 기계적 강제)
  if ! grep -qF "start_new_session=True" "$hub_daemon_file"; then
    record_failure "$test_name" "T25-17: hub_daemon.py 에 start_new_session=True 가 없음"
    return 1
  fi

  # T25-18: _tier3_activity_by_encoded_name 이 except OSError 를 포함한다(R3-m1 회귀)
  local tier3_function_body
  tier3_function_body=$(awk '/^def _tier3_activity_by_encoded_name\(/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_collect_file")
  if ! echo "$tier3_function_body" | grep -qF "except OSError"; then
    note_failure "T25-18: _tier3_activity_by_encoded_name 에 except OSError 가드가 없음"
  fi

  # T25-19: commands/hub.md 에 last_collect_failure·event_read_warnings 등장(R3-m2 회귀)
  if ! grep -qF "last_collect_failure" "$hub_command_file"; then
    note_failure "T25-19: commands/hub.md 에 last_collect_failure 미언급"
  fi
  if ! grep -qF "event_read_warnings" "$hub_command_file"; then
    record_failure "$test_name" "T25-19: commands/hub.md 에 event_read_warnings 미언급"
    return 1
  fi

  # T25-20: hub.py 의 cmd_open 함수 본문에 서버 기동 호출이 없다(암묵 기동 회귀 방지, 요구 R-2)
  local cmd_open_body
  cmd_open_body=$(awk '/^def cmd_open\(/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_py_file")
  if echo "$cmd_open_body" | grep -qE "start_server|server-start"; then
    record_failure "$test_name" "T25-20: cmd_open 이 서버를 기동하는 것으로 보임(암묵 기동 회귀)"
    return 1
  fi

  # T25-21: 루트 install.sh 에 hub 문자열이 등장하지 않는다(설치 분리의 기계적 강제, 요구 R-5)
  local root_hub_mentions
  root_hub_mentions=$(grep -c "hub" "$INSTALL_SCRIPT" || true)
  if [[ "$root_hub_mentions" -ne 0 ]]; then
    record_failure "$test_name" "T25-21: install.sh 에 hub 문자열이 ${root_hub_mentions}건 등장함(기대 0)"
    return 1
  fi

  # T25-22(검수 Nit3 — 임계값 완화): README.md 의 허브 언급이 14줄 이하이고 hub/README.md
  # 링크를 포함한다(문서 분리 회귀 방지). 대소문자 구분 검색이다 — case-insensitive 는
  # "GitHub" 까지 세어 오탐한다. 10 은 소소한 문구 조정에도 쉽게 넘는 빡빡한 값이었다.
  local readme_hub_mentions readme_hub_link_count
  readme_hub_mentions=$(grep -c "hub" "$readme_file" || true)
  readme_hub_link_count=$(grep -cF "hub/README.md" "$readme_file" || true)
  if [[ "$readme_hub_mentions" -gt 14 ]]; then
    note_failure "T25-22: README.md 의 허브 언급이 ${readme_hub_mentions}줄(기대 14줄 이하)"
  fi
  if [[ "$readme_hub_link_count" -eq 0 ]]; then
    record_failure "$test_name" "T25-22: README.md 에 hub/README.md 링크가 없음"
    return 1
  fi

  # T25-23: hub/install.sh --uninstall 절차에서 server-stop·uninstall-hooks 가 rm -rf 보다 앞에 온다
  local server_stop_line uninstall_hooks_line rm_rf_line
  server_stop_line=$(grep -n "server-stop" "$hub_install_file" | head -1 | cut -d: -f1)
  uninstall_hooks_line=$(grep -n "uninstall-hooks" "$hub_install_file" | head -1 | cut -d: -f1)
  rm_rf_line=$(grep -n 'rm -rf "\$TARGET_BIN_DIR"' "$hub_install_file" | head -1 | cut -d: -f1)
  if [[ -z "$server_stop_line" || -z "$uninstall_hooks_line" || -z "$rm_rf_line" ]]; then
    note_failure "T25-23: server-stop/uninstall-hooks/rm -rf 셋 중 하나를 hub/install.sh 에서 찾지 못함"
  fi
  if [[ "$server_stop_line" -ge "$rm_rf_line" || "$uninstall_hooks_line" -ge "$rm_rf_line" ]]; then
    note_failure "T25-23: server-stop·uninstall-hooks 가 rm -rf 보다 앞에 있지 않음(순서 위반)"
  fi

  # T25-24: commands/harness-update.md 에 조건부 허브 절과 판정 경로(hub/bin/hub.py)가 있다(R-5 연동 회귀)
  if ! grep -qF "Phase 4b" "$harness_update_command_file"; then
    note_failure "T25-24: commands/harness-update.md 에 Phase 4b 절이 없음"
  fi
  if ! grep -qF "hub/bin/hub.py" "$harness_update_command_file"; then
    note_failure "T25-24: commands/harness-update.md 에 판정 경로(hub/bin/hub.py)가 없음"
  fi

  # T25-228: Phase 4b 의 "이미 최신이면 건너뛴다" 사전 비교가 server-stop 호출보다 앞줄에
  # 있어야 불필요한 서버 정지를 실제로 피한다 — 2026-09-23 세션에서 hub/ 가 무변경인데도
  # Phase 4b 가 server-stop 을 요구해 자동 모드 분류기가 그 명령을 거부한 사고의 재발
  # 방지다. 순서만 보고 명령 자체의 의미(정말 무엇을 비교하는지)는 검사하지 않는다(위
  # 함수 한계 참고, T25-66·T25-170 과 같은 예외 부류).
  local hub_precheck_diff_line hub_server_stop_json_line
  hub_precheck_diff_line=$(grep -n -F 'diff -rq -x __pycache__ "$repo_path/hub/bin" "$HOME/.claude/hub/bin"' "$harness_update_command_file" | head -1 | cut -d: -f1)
  hub_server_stop_json_line=$(grep -n -F 'server-stop --json' "$harness_update_command_file" | head -1 | cut -d: -f1)
  if [[ -z "$hub_precheck_diff_line" ]]; then
    note_failure "T25-228: commands/harness-update.md 에 허브 재설치 사전 비교 명령이 없음"
  elif [[ -z "$hub_server_stop_json_line" ]]; then
    note_failure "T25-228: commands/harness-update.md 에 server-stop --json 호출을 찾지 못함"
  elif [[ "$hub_precheck_diff_line" -ge "$hub_server_stop_json_line" ]]; then
    note_failure "T25-228: 허브 재설치 사전 비교가 server-stop --json 호출보다 앞에 있지 않음(불필요한 서버 정지 회귀)"
  fi

  # T25-25: commands/hub.md 사전 조건이 install.sh --scope user 를 안내하지 않고 hub/install.sh 를 안내한다
  if grep -qF "install.sh --scope user 를 먼저 실행" "$hub_command_file"; then
    note_failure "T25-25: commands/hub.md 가 존재하지 않는 절차(install.sh --scope user)를 안내함"
  fi
  if ! grep -qF "hub/install.sh" "$hub_command_file"; then
    record_failure "$test_name" "T25-25: commands/hub.md 사전 조건에 hub/install.sh 안내가 없음"
    return 1
  fi

  # T25-26(검수 n1 회귀 — 2방향 실측): run_hub_subcommand_or_abort 의 ok 판정은 문자열 매칭이 아니라
  # 실제 JSON 파싱이다. 압축 JSON(`"ok":true`, 공백 없음)으로도 성공을 오판 없이 인식해야
  # 한다 — 예전의 `grep -q '"ok": true'` 였다면 이 공백 없는 형태를 실패로 오판했을 것이다.
  # 반대로 ok:false 면 --force 없이 반드시 중단하고 bin/ 을 보존해야 한다(정지 수단 소멸 방지).
  local sandbox_stop_ok sandbox_stop_fail
  sandbox_stop_ok=$(mktemp -d)
  sandbox_stop_fail=$(mktemp -d)
  register_cleanup_path "$sandbox_root" "$sandbox_hub" "$sandbox_stop_ok" "$sandbox_stop_fail"

  mkdir -p "$sandbox_stop_ok/.claude/hub/bin"
  cat > "$sandbox_stop_ok/.claude/hub/bin/hub.py" << 'PYEOF'
#!/usr/bin/env python3
import sys
subcommand = sys.argv[1] if len(sys.argv) > 1 else ""
if subcommand == "server-stop":
    print('{"ok":true,"was_running":true}')
elif subcommand == "uninstall-hooks":
    print('{"ok":true,"removed":[]}')
else:
    print('{"ok":true}')
PYEOF

  mkdir -p "$sandbox_stop_fail/.claude/hub/bin"
  cat > "$sandbox_stop_fail/.claude/hub/bin/hub.py" << 'PYEOF'
#!/usr/bin/env python3
import sys
subcommand = sys.argv[1] if len(sys.argv) > 1 else ""
if subcommand == "server-stop":
    print('{"ok":false,"reason":"테스트로 강제한 실패"}')
elif subcommand == "uninstall-hooks":
    print('{"ok":true,"removed":[]}')
else:
    print('{"ok":true}')
PYEOF

  HOME="$sandbox_stop_ok" "$hub_install_file" --uninstall > /dev/null 2>&1
  if [[ -d "$sandbox_stop_ok/.claude/hub/bin" ]]; then
    note_failure "T25-26: server-stop 성공(압축 JSON)인데 bin/ 이 삭제되지 않음(오판 의심)"
  fi

  if HOME="$sandbox_stop_fail" "$hub_install_file" --uninstall > /dev/null 2>&1; then
    note_failure "T25-26: server-stop 실패인데 hub/install.sh --uninstall 이 성공(exit 0)으로 끝남"
  fi
  if [[ ! -f "$sandbox_stop_fail/.claude/hub/bin/hub.py" ]]; then
    note_failure "T25-26: server-stop 실패 시 bin/ 이 보존되지 않음(정지 수단 소멸)"
  fi

  # T25-176(PRP shell-hardening §4, H8 — server-stop 전용이던 게이트를 uninstall-hooks·
  # uninstall-statusline 까지 넓힌 run_hub_subcommand_or_abort 의 회귀 검사). T25-26 과 같은
  # 관용구(샌드박스 HOME + 스텁 hub.py)를 확장해, 서버 정지는 성공하지만 훅(또는
  # statusLine) 제거가 실패하는 갈래를 추가한다. 세 가지를 함께 확인한다 — exit≠0 ·
  # bin/ 보존 · 중단 보고에 "어느 단계까지 갔는지"(부분 적용 상태, §4-3 결정 3)가 나타나는가.
  # 마지막으로 --force 를 준 별도 샌드박스에서 우회가 실제로 bin/ 삭제까지 완주하고 수동
  # 복구 절차를 인쇄하는지 확인한다(§4-3 결정 4). 뮤테이션 원장 행은 붙이지 않는다 — exit
  # 코드와 bin/ 존재의 직접 관측이라 T25-26 과 같은 이유로 불필요하다고 판정했다(§10-3).
  #
  # 한계(S3 검수 2렌즈): 이 검사는 "수동 복구 절차" 문자열의 존재만 보므로,
  # run_hub_subcommand_or_abort 가 하위 명령별 복구 문장을 가르는 것이 퇴화해 전부 같은
  # 기본 문장을 받게 되는 것은 잡지 못한다. --force 갈래도 uninstall-hooks 실패만
  # 태우므로 server-stop 전용 복구 문장은 어느 서브체크도 관측하지 않는다. 전수 증명이
  # 아니다.
  local sandbox_h8_hooks_fail sandbox_h8_statusline_fail sandbox_h8_hooks_fail_force
  sandbox_h8_hooks_fail=$(mktemp -d)
  sandbox_h8_statusline_fail=$(mktemp -d)
  sandbox_h8_hooks_fail_force=$(mktemp -d)
  register_cleanup_path "$sandbox_h8_hooks_fail" "$sandbox_h8_statusline_fail" \
    "$sandbox_h8_hooks_fail_force"

  mkdir -p "$sandbox_h8_hooks_fail/.claude/hub/bin"
  cat > "$sandbox_h8_hooks_fail/.claude/hub/bin/hub.py" << 'PYEOF'
#!/usr/bin/env python3
import sys
subcommand = sys.argv[1] if len(sys.argv) > 1 else ""
if subcommand == "server-stop":
    print('{"ok":true,"was_running":true}')
elif subcommand == "uninstall-hooks":
    print('{"ok":false,"reason":"테스트로 강제한 훅 제거 실패"}')
else:
    print('{"ok":true}')
PYEOF

  mkdir -p "$sandbox_h8_statusline_fail/.claude/hub/bin"
  cat > "$sandbox_h8_statusline_fail/.claude/hub/bin/hub.py" << 'PYEOF'
#!/usr/bin/env python3
import sys
subcommand = sys.argv[1] if len(sys.argv) > 1 else ""
if subcommand == "server-stop":
    print('{"ok":true,"was_running":true}')
elif subcommand == "uninstall-hooks":
    print('{"ok":true,"removed":[]}')
elif subcommand == "uninstall-statusline":
    print('{"ok":false,"reason":"테스트로 강제한 statusLine 제거 실패"}')
else:
    print('{"ok":true}')
PYEOF

  mkdir -p "$sandbox_h8_hooks_fail_force/.claude/hub/bin"
  cat > "$sandbox_h8_hooks_fail_force/.claude/hub/bin/hub.py" << 'PYEOF'
#!/usr/bin/env python3
import sys
subcommand = sys.argv[1] if len(sys.argv) > 1 else ""
if subcommand == "server-stop":
    print('{"ok":true,"was_running":true}')
elif subcommand == "uninstall-hooks":
    print('{"ok":false,"reason":"테스트로 강제한 훅 제거 실패"}')
else:
    print('{"ok":true}')
PYEOF

  local h8_hooks_fail_output h8_hooks_fail_exit=0
  h8_hooks_fail_output=$(HOME="$sandbox_h8_hooks_fail" "$hub_install_file" --uninstall 2>&1) \
    || h8_hooks_fail_exit=$?
  if [[ "$h8_hooks_fail_exit" -eq 0 ]]; then
    note_failure "T25-176: uninstall-hooks 실패인데 hub/install.sh --uninstall 이 성공(exit 0)으로 끝남"
  fi
  if [[ ! -f "$sandbox_h8_hooks_fail/.claude/hub/bin/hub.py" ]]; then
    note_failure "T25-176: uninstall-hooks 실패 시 bin/ 이 보존되지 않음(정지 수단 소멸)"
  fi
  if ! grep -qF "서버 정지는 이미 완료됐습니다" <<< "$h8_hooks_fail_output"; then
    note_failure "T25-176: uninstall-hooks 실패 중단 보고에 진행 단계(서버 정지 완료)가 나타나지 않음"
  fi

  local h8_statusline_fail_output h8_statusline_fail_exit=0
  h8_statusline_fail_output=$(HOME="$sandbox_h8_statusline_fail" "$hub_install_file" --uninstall 2>&1) \
    || h8_statusline_fail_exit=$?
  if [[ "$h8_statusline_fail_exit" -eq 0 ]]; then
    note_failure "T25-176: uninstall-statusline 실패인데 hub/install.sh --uninstall 이 성공(exit 0)으로 끝남"
  fi
  if [[ ! -f "$sandbox_h8_statusline_fail/.claude/hub/bin/hub.py" ]]; then
    note_failure "T25-176: uninstall-statusline 실패 시 bin/ 이 보존되지 않음(정지 수단 소멸)"
  fi
  if ! grep -qF "서버 정지·훅 제거는 이미 완료됐습니다" <<< "$h8_statusline_fail_output"; then
    note_failure "T25-176: uninstall-statusline 실패 중단 보고에 진행 단계(서버 정지·훅 제거 완료)가 나타나지 않음"
  fi

  local h8_force_output h8_force_exit=0
  h8_force_output=$(HOME="$sandbox_h8_hooks_fail_force" "$hub_install_file" --uninstall --force 2>&1) \
    || h8_force_exit=$?
  if [[ "$h8_force_exit" -ne 0 ]]; then
    note_failure "T25-176: --force 인데도 uninstall-hooks 실패로 중단됨(우회 실패, exit=$h8_force_exit)"
  fi
  if [[ -d "$sandbox_h8_hooks_fail_force/.claude/hub/bin" ]]; then
    note_failure "T25-176: --force 인데 uninstall-hooks 실패 후에도 bin/ 이 삭제되지 않음(우회가 완주하지 않음)"
  fi
  if ! grep -qF "수동 복구 절차" <<< "$h8_force_output"; then
    note_failure "T25-176: --force 경로에 수동 복구 절차 안내가 없음"
  fi

  # T25-28(결정 T1·T3 회귀): 다크 테마는 미디어 쿼리 + data-theme 속성 오버라이드 둘 다로
  # 성립하고, 'dzh-theme' 리터럴은 head FOUC 스크립트 + 본문 IIFE 두 곳에 각각 등장해야 한다
  # (head 스크립트는 자족적이어야 해서 상수 공유가 불가능하다).
  if ! grep -qF "prefers-color-scheme" "$hub_template_file"; then
    note_failure "T25-28: hub_template.html 에 prefers-color-scheme 가 없음"
  fi
  if ! grep -qF "data-theme" "$hub_template_file"; then
    record_failure "$test_name" "T25-28: hub_template.html 에 data-theme 가 없음"
    return 1
  fi
  local dzh_theme_literal_count
  dzh_theme_literal_count=$(grep -oF "'dzh-theme'" "$hub_template_file" | wc -l | tr -d ' ')
  if [[ "$dzh_theme_literal_count" -lt 2 ]]; then
    record_failure "$test_name" "T25-28: 'dzh-theme' 리터럴이 ${dzh_theme_literal_count}회만 등장(기대 2회 이상)"
    return 1
  fi

  # T25-29(팔레트 회귀 방지): 색각 안전성이 없는 구형 초록·빨강·주황이 템플릿에서 완전히 사라져야 한다.
  local legacy_color
  for legacy_color in "#1F8A70" "#C2410C" "#F59E0B"; do
    if grep -qF "$legacy_color" "$hub_template_file"; then
      note_failure "T25-29: hub_template.html 에 색각 안전성 없는 팔레트($legacy_color)가 남아 있음"
    fi
  done

  # T25-30(색 이외 채널 회귀 방지): 상태 배지가 색만이 아니라 글리프로도 구분되고,
  # 그 글리프는 스크린리더에서 숨겨진다(aria-hidden).
  if ! grep -qF "STATE_GLYPH" "$hub_template_file"; then
    note_failure "T25-30: hub_template.html 에 STATE_GLYPH 가 없음"
  fi
  if ! grep -qF "aria-hidden" "$hub_template_file"; then
    record_failure "$test_name" "T25-30: hub_template.html 에 aria-hidden 이 없음"
    return 1
  fi

  # T25-31(문서 정합, 개정 — 죽은 전제를 테스트로 고정하지 않는다): show_usage_panel 스위치와
  # 데이터 출처(statusLine 캡처의 used_percentage)가 hub/README.md 에 문서화돼 있다.
  # plan-usage-history.json 은 결정 P1 로 사라진 경로라 더 이상 grep 대상이 아니다(승인 항목 5).
  local hub_readme_usage_file="$REPO_ROOT/hub/README.md"
  local usage_source_token
  for usage_source_token in "show_usage_panel" "used_percentage" "statusLine"; do
    if ! grep -qF "$usage_source_token" "$hub_readme_usage_file"; then
      record_failure "$test_name" "T25-31: hub/README.md 에 $usage_source_token 언급이 없음"
      return 1
    fi
  done

  # T25-32(결정 G1~G5 회귀): 프로젝트 목록이 뷰포트 폭에 따라 열 수가 바뀌는 그리드이고,
  # 카드가 행 높이에 맞춰 늘어나지 않으며, 비-카드 요소는 한 행을 다 쓴다.
  local grid_token
  for grid_token in "max-width:1440px" "display:grid" \
                    "repeat(auto-fill,minmax(max(320px,calc((100% - 24px)/3 - 1px)),1fr))" \
                    "align-items:start" "grid-column:1/-1"; do
    if ! grep -qF "$grid_token" "$hub_template_file"; then
      note_failure "T25-32: hub_template.html 에 그리드 규칙($grid_token)이 없음"
    fi
  done

  # T25-33(결정 C1 · 불변식 H1′ 회귀 — 이 파일에서 가장 중요한 검사):
  # 접기 버튼은 정적 마크업이어야 하고, 패널 컨테이너를 통째로 다시 그리는 코드가 되살아나면
  # 접힘 상태가 30초 틱마다 초기화된다.
  if ! grep -qF '<button id="dzh-usage-toggle"' "$hub_template_file"; then
    note_failure "T25-33: 접기 버튼이 정적 마크업으로 존재하지 않음"
  fi
  if ! grep -qF 'id="dzh-usage-body"' "$hub_template_file"; then
    note_failure "T25-33: 파생 본문 컨테이너(#dzh-usage-body)가 없음"
  fi
  if grep -qF "usageEl.innerHTML" "$hub_template_file"; then
    record_failure "$test_name" "T25-33: usageEl.innerHTML 대입이 부활함 — 재렌더가 접기 버튼을 파괴한다"
    return 1
  fi

  # T25-34(제약 C8 회귀): 접기 토글의 상태가 접근성 트리에 노출되고, 기존 막대의
  # progressbar 시맨틱이 리팩토링 중 유실되지 않는다.
  local a11y_token
  for a11y_token in "aria-expanded" 'aria-controls="dzh-usage-body"' 'role="progressbar"'; do
    if ! grep -qF "$a11y_token" "$hub_template_file"; then
      note_failure "T25-34: hub_template.html 에 접근성 속성($a11y_token)이 없음"
    fi
  done

  # T25-35(결정 L1·L3·C2 회귀): 패널은 우하단 고정이고(중앙 정렬 흔적이 남으면 안 된다),
  # 하단 여백은 실측 커스텀 속성으로 주며, 접힘 상태는 전용 키에 저장된다.
  if grep -qF "translateX(-50%)" "$hub_template_file"; then
    record_failure "$test_name" "T25-35: 하단 중앙 정렬(translateX(-50%))이 남아 있음"
    return 1
  fi
  local panel_token
  for panel_token in "right:16px;bottom:16px" "--usage-clearance" "'dzh-usage-collapsed'"; do
    if ! grep -qF -- "$panel_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-35: hub_template.html 에 패널 규칙($panel_token)이 없음"
      return 1
    fi
  done

  # T25-36(문서 정합): 화면 배치 변경이 hub/README.md 에 반영돼 있다.
  local hub_readme_layout_file="$REPO_ROOT/hub/README.md"
  local doc_token
  for doc_token in "우하단" "접기" "그리드"; do
    if ! grep -qF "$doc_token" "$hub_readme_layout_file"; then
      note_failure "T25-36: hub/README.md 에 화면 배치 설명($doc_token)이 없음"
    fi
  done

  # T25-37(검수 m3 회귀): escapeHtml 이 따옴표도 이스케이프한다. usage-meta 의 title="..." 이
  # 이 함수의 첫 속성 자리 사용처라, 따옴표를 넘기면 그대로 속성이 끊길 수 있었다.
  if ! grep -qF '.replace(/"/g' "$hub_template_file"; then
    note_failure 'T25-37: escapeHtml 에 큰따옴표 이스케이프가 없음'
  fi
  if ! grep -qF ".replace(/'/g" "$hub_template_file"; then
    note_failure "T25-37: escapeHtml 에 작은따옴표 이스케이프가 없음"
  fi

  # T25-38(GOTCHA 1 회귀): statusLine 커맨드 줄이 stdout 을 리다이렉트하지 않는다.
  # `2>/dev/null` 은 `>/dev/null` 을 부분 문자열로 포함하므로 grep -F '>/dev/null' 로는
  # 검사할 수 없다(정상 커맨드가 항상 걸린다) — `>` 앞 문자가 숫자가 아닌 경우만 잡는다(GOTCHA 6).
  if grep -F 'hub_statusline.py' "$hub_settings_file" | grep -qE '(^|[^0-9])>/dev/null'; then
    note_failure "T25-38: statusLine 커맨드가 stdout 을 리다이렉트함 — 상태줄이 사라진다"
  fi
  if ! grep -F 'hub_statusline.py' "$hub_settings_file" | grep -qF '2>/dev/null'; then
    note_failure "T25-38: statusLine 커맨드 줄에 2>/dev/null 이 없음"
  fi
  if ! grep -F 'hub_statusline.py' "$hub_settings_file" | grep -qF '|| true'; then
    record_failure "$test_name" "T25-38: statusLine 커맨드 줄에 || true 가 없음"
    return 1
  fi
  # 마커(# DZH_HUB_STATUSLINE)는 STATUSLINE_MARKER 변수 참조로 이어붙는다(HOOK_MARKER 와
  # 같은 관행) — 소스상 같은 줄에 리터럴로 나타나지 않는다. 마커 존재 자체는 T25-40 이
  # 파일 전체를 대상으로 검사한다(T25-3 과 같은 방식).

  # T25-39(T25-23 과 같은 방식): hub/install.sh --uninstall 에서 uninstall-statusline 이
  # rm -rf "$TARGET_BIN_DIR" 보다 앞에 온다 — 없는 스크립트를 부르는 무성음 상태를 막는다.
  local uninstall_statusline_line rm_rf_line_t39
  uninstall_statusline_line=$(grep -n "uninstall-statusline" "$hub_install_file" | head -1 | cut -d: -f1)
  rm_rf_line_t39=$(grep -n 'rm -rf "\$TARGET_BIN_DIR"' "$hub_install_file" | head -1 | cut -d: -f1)
  if [[ -z "$uninstall_statusline_line" || -z "$rm_rf_line_t39" ]]; then
    note_failure "T25-39: uninstall-statusline/rm -rf 중 하나를 hub/install.sh 에서 찾지 못함"
  fi
  if [[ "$uninstall_statusline_line" -ge "$rm_rf_line_t39" ]]; then
    record_failure "$test_name" "T25-39: uninstall-statusline 이 rm -rf 보다 앞에 있지 않음(순서 위반)"
    return 1
  fi

  # T25-40(T25-3 선례): statusLine 마커 문서화가 hub_settings.py·commands/hub.md·hub/README.md
  # 세 곳에 존재한다.
  local statusline_marker="# DZH_HUB_STATUSLINE"
  for doc_file in "$hub_settings_file" "$hub_command_file" "$hub_readme_file"; do
    if ! grep -qF "$statusline_marker" "$doc_file"; then
      note_failure "T25-40: $statusline_marker 마커 미발견: $doc_file"
    fi
  done

  # T25-43(세션 활동 노출 회귀 — 개정: agent-chip-more 부재 검사로 반전): 세션 표시가
  # '실행 중인 것만' 으로 되돌아가지 않고, "+N" 오버플로 칩(agent-chip-more)도 되살아나지
  # 않는다(결정 K1~K3).
  if grep -qF "active_agent_types" "$hub_template_file" "$hub_session_file" "$hub_session_facts_file"; then
    note_failure "T25-43: active_agent_types 가 부활함 — 완료 세션이 다시 빈 목록이 된다"
  fi
  if grep -qF "agent-chip-more" "$hub_template_file"; then
    record_failure "$test_name" "T25-43: agent-chip-more 가 남아 있음 — +N 오버플로 칩은 결정 K3 로 삭제됨"
    return 1
  fi
  local session_activity_token
  for session_activity_token in "summarize_agent_runs" "agent_runs"; do
    if ! grep -qF "$session_activity_token" "$hub_session_file"; then
      record_failure "$test_name" "T25-43: hub_session.py 에 $session_activity_token 이 없음"
      return 1
    fi
  done
  # 개정(결정 AR12, docs/prps/hub-agent-runs-and-prompt-source.md) — 첫 줄 타입 합계 칩 행
  # (renderAgentRuns·MAX_VISIBLE_AGENT_CHIPS)은 실행 목록으로 대체됐다. 그 대체가 실제로
  # 있는지는 renderAgentRunList·visibleAgentRunRows 로 확인하고(역방향은 T25-210), 칩
  # 클래스 자체(.agent-chip)는 실행 목록에서도 재사용되므로 그대로 남긴다.
  for session_activity_token in "renderAgentRunList" "agent-chip" "visibleAgentRunRows"; do
    if ! grep -qF "$session_activity_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-43: hub_template.html 에 $session_activity_token 이 없음"
      return 1
    fi
  done

  # T25-41(요구 "주기는 유지"의 회귀 방지): 초기화 예정 시각 표시에 필요한 토큰이 전부
  # hub_template.html 에 있고, 폴링 주기·사용량 갱신 주기 문구는 바뀌지 않았다.
  local reset_time_token
  for reset_time_token in "usage-reset" "rate_limit_resets" "초기화 " "renderUsageResetRow"; do
    if ! grep -qF "$reset_time_token" "$hub_template_file"; then
      note_failure "T25-41: hub_template.html 에 초기화 예정 시각 토큰($reset_time_token)이 없음"
    fi
  done
  # 폴링 주기는 5초에서 1분으로 바뀌었다(사용자 요청 — 5초는 너무 짧다). 이 검사는 원래
  # 5000 을 고정했는데, 그 커밋은 주기 변경을 모르는 상태에서 작성됐다. 값만 갱신하고
  # "주기가 임의로 바뀌지 않는다"는 검사의 의도는 그대로 유지한다.
  if ! grep -qF "POLL_INTERVAL_MS = 60000" "$hub_template_file"; then
    note_failure "T25-41: POLL_INTERVAL_MS = 60000 회귀(폴링 주기가 바뀜)"
  fi
  # '약 15분 주기'는 데스크톱 앱 샘플링 주기 전제 문구였다. 퍼센트 출처가 statusLine 캡처로
  # 바뀌며(결정 P1·P6) 그 전제 자체가 사라졌다 — 새 문구로 교체한다(승인 항목 5).
  if ! grep -qF "세션 진행 중에만 갱신" "$hub_template_file"; then
    note_failure "T25-41: '세션 진행 중에만 갱신' 문구 회귀(사용량 갱신 주기 고지 유실)"
  fi

  # T25-42(문서 정합): hub/README.md·commands/hub.md 에 새 파일·서브커맨드가 문서화돼 있다.
  if ! grep -qF "rate_limits.json" "$hub_readme_file"; then
    note_failure "T25-42: hub/README.md 에 rate_limits.json 언급이 없음"
  fi
  if ! grep -qiF "statusline" "$hub_readme_file"; then
    note_failure "T25-42: hub/README.md 에 statusline 언급이 없음"
  fi
  if ! grep -qF "install-statusline" "$hub_command_file"; then
    note_failure "T25-42: commands/hub.md 에 install-statusline 이 없음"
  fi
  if ! grep -qF "uninstall-statusline" "$hub_command_file"; then
    note_failure "T25-42: commands/hub.md 에 uninstall-statusline 이 없음"
  fi

  # T25-44(커스텀 툴팁 회귀): 네이티브 title 툴팁이 하나도 남지 않고, 커스텀 툴팁이 위임·
  # 접근성·해제 경로를 모두 갖는다. (<title> 요소는 속성 형태가 아니라 이 검사에 걸리지 않는다)
  if grep -qF 'title="' "$hub_template_file"; then
    record_failure "$test_name" "T25-44: 네이티브 title 속성이 남아 있음 — data-tooltip 을 쓸 것"
    return 1
  fi
  local tooltip_token
  for tooltip_token in 'id="dzh-tooltip"' 'role="tooltip"' 'data-tooltip' 'aria-describedby' \
                       "'mouseover'" "'focusin'" "Escape" "MutationObserver"; do
    if ! grep -qF -- "$tooltip_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-44: hub_template.html 에 툴팁 계약($tooltip_token)이 없음"
      return 1
    fi
  done

  # T25-45(문서 정합): 세션 줄 구성과 툴팁 거동이 hub/README.md 에 반영돼 있다.
  for doc_token in "서브에이전트" "툴팁"; do
    if ! grep -qF "$doc_token" "$hub_readme_file"; then
      note_failure "T25-45: hub/README.md 에 화면 설명($doc_token)이 없음"
    fi
  done

  # T25-46(브라우저 타이틀 회귀): 탭 제목이 "Claude Agents Manager" 로 고정돼 있다.
  if ! grep -qF '<title>Claude Agents Manager</title>' "$hub_template_file"; then
    note_failure "T25-46: hub_template.html 에 <title>Claude Agents Manager</title> 가 없음"
  fi

  # T25-47(파비콘 회귀): 인라인 SVG data: URI 파비콘 링크가 유지돼 있다.
  if ! grep -qF 'rel="icon"' "$hub_template_file"; then
    note_failure "T25-47: hub_template.html 에 rel=\"icon\" 이 없음"
  fi
  if ! grep -qF 'data:image/svg+xml' "$hub_template_file"; then
    record_failure "$test_name" "T25-47: hub_template.html 에 data:image/svg+xml 파비콘이 없음"
    return 1
  fi

  # T25-48(재기동 계약 회귀): server-restart 가 CLI·데몬·커맨드 문서 세 곳에 있고,
  # 그것을 만들면서 멱등 start 를 force 로 바꾸는 회귀(GOTCHA 1)가 없다.
  local restart_token
  for restart_token in "server-restart" "cmd_server_restart"; do
    if ! grep -qF "$restart_token" "$hub_py_file"; then
      record_failure "$test_name" "T25-48: hub.py 에 $restart_token 이 없음"
      return 1
    fi
  done
  for restart_token in "def restart_server" "def restart_note" "_wait_for_port_release"; do
    if ! grep -qF "$restart_token" "$hub_daemon_file"; then
      note_failure "T25-48: hub_daemon.py 에 $restart_token 이 없음"
    fi
  done
  if ! grep -qF '"already_running": True' "$hub_daemon_file"; then
    record_failure "$test_name" "T25-48: start_server 의 멱등(already_running)이 사라짐 — restart 와 별도 경로여야 한다"
    return 1
  fi
  for restart_token in "server restart" "server-restart"; do
    if ! grep -qF "$restart_token" "$hub_command_file"; then
      note_failure "T25-48: commands/hub.md 에 $restart_token 이 없음"
    fi
  done
  if ! grep -E '^argument-hint:' "$hub_command_file" | grep -qF "server restart"; then
    record_failure "$test_name" "T25-48: argument-hint 에 'server restart' 미노출"
    return 1
  fi

  # T25-49(브라우저 포커스 회귀): 포커스 경로가 hub_daemon 에 하나만 있고, 셸을 거치지 않으며,
  # hub.py 에는 webbrowser 직접 호출이 남지 않는다(경로 이중화 방지).
  local focus_token
  for focus_token in "def browser_open_command" "/usr/bin/open" "darwin" "webbrowser"; do
    if ! grep -qF "$focus_token" "$hub_daemon_file"; then
      note_failure "T25-49: hub_daemon.py 에 $focus_token 이 없음"
    fi
  done
  if grep -qF "shell=True" "$hub_daemon_file"; then
    note_failure "T25-49: hub_daemon.py 가 shell=True 를 씀 — URL 을 셸에 넘기지 않는다"
  fi
  if grep -qF "webbrowser" "$hub_py_file"; then
    note_failure "T25-49: hub.py 에 webbrowser 직접 호출이 남음 — hub_daemon.open_browser 로 단일화할 것"
  fi
  if ! grep -qF "browser_focus_requested" "$hub_command_file"; then
    record_failure "$test_name" "T25-49: commands/hub.md 에 browser_focus_requested 보고 규칙이 없음"
    return 1
  fi
  for focus_token in "restart" "포커스"; do
    if ! grep -qF "$focus_token" "$hub_readme_file"; then
      note_failure "T25-49: hub/README.md 에 서버 제어 설명($focus_token)이 없음"
    fi
  done

  # T25-50(결정 W1 회귀): 그리드 트랙 최소폭이 3열 상한 계산식으로 바뀌었고, hub/README.md 의
  # 열 수 고지가 1~3열로 갱신돼 있다.
  if ! grep -qF "max(320px" "$hub_template_file"; then
    note_failure "T25-50: hub_template.html 에 max(320px 트랙 계산이 없음"
  fi
  if ! grep -qF "/3 - 1px)" "$hub_template_file"; then
    note_failure "T25-50: hub_template.html 에 3열 상한 계산(/3 - 1px)이 없음(GOTCHA 1)"
  fi
  if ! grep -qF "1~3열" "$hub_readme_file"; then
    record_failure "$test_name" "T25-50: hub/README.md 의 열 수 고지가 1~3열로 갱신되지 않음"
    return 1
  fi

  # T25-51(결정 V1 회귀): 완료 세션 숨김 필터는 클라이언트에만 있다 — 서버(hub_project)는
  # 세션을 걸러내지 않는다(sessions=session_views 가 그대로 있다는 것이 그 증거다).
  local client_filter_token
  for client_filter_token in "shouldRenderSession" "visibleAgentRunRows"; do
    if ! grep -qF "$client_filter_token" "$hub_template_file"; then
      note_failure "T25-51: hub_template.html 에 $client_filter_token 이 없음"
    fi
  done
  if ! grep -qF "sessions=session_views" "$hub_project_file"; then
    note_failure "T25-51: hub_project.py 가 세션을 걸러내는 것으로 보임(sessions=session_views 부재)"
  fi

  # T25-52(결정 K1~K3 회귀 — 안 A, docs/prps/hub-agent-runs-and-prompt-source.md 결정 AR4·AR5
  # 로 리터럴 개정 — 타입 합계 딕셔너리(is_running_by_type)가 사라지고 실행 1건당 뷰가 되며
  # 정렬 키가 `run.is_running` 을 직접 본다): "+N" 오버플로 칩 로직(overflowRuns)이 없고,
  # summarize_agent_runs 의 정렬 키에 실행 중 우선순위(K2)가 반영돼 있다.
  if grep -qF "overflowRuns" "$hub_template_file"; then
    note_failure "T25-52: hub_template.html 에 오버플로 칩 흔적(overflowRuns)이 남아 있음"
  fi
  if ! grep -qF "0 if run.is_running else 1" "$hub_session_file"; then
    record_failure "$test_name" "T25-52: hub_session.py 의 summarize_agent_runs 정렬 키에 실행 중 우선순위(K2)가 없음"
    return 1
  fi

  # T25-53(GOTCHA 2 회귀 — 결정 Z1): STALE_SESSION_HIDE_AFTER_MS 가 존재하고, MS_PER_HOUR
  # 선언보다 뒤에 선언돼 있다. var 호이스팅은 선언만 끌어올리고 할당은 올리지 않으므로 앞에
  # 두면 12 * undefined = NaN 이 되어 컷오프가 조용히 죽는다.
  local ms_per_hour_decl_line stale_cutoff_decl_line
  ms_per_hour_decl_line=$(grep -n "var MS_PER_HOUR" "$hub_template_file" | head -1 | cut -d: -f1)
  stale_cutoff_decl_line=$(grep -n "var STALE_SESSION_HIDE_AFTER_MS" "$hub_template_file" | head -1 | cut -d: -f1)
  if [[ -z "$ms_per_hour_decl_line" || -z "$stale_cutoff_decl_line" ]]; then
    note_failure "T25-53: MS_PER_HOUR/STALE_SESSION_HIDE_AFTER_MS 선언을 hub_template.html 에서 찾지 못함"
  fi
  if [[ "$stale_cutoff_decl_line" -le "$ms_per_hour_decl_line" ]]; then
    record_failure "$test_name" "T25-53: STALE_SESSION_HIDE_AFTER_MS 가 MS_PER_HOUR 보다 앞서 선언됨(GOTCHA 2)"
    return 1
  fi

  # T25-54(결정 P1 회귀 — 퍼센트 출처 교체): 데스크톱 앱 사용량 히스토리 경로·파서가
  # 소스에 남아 있지 않고, 캡처 단일 출처의 새 계약(신규 필드·투영 함수·비교 함수)이 있다.
  local hub_usage_file="$REPO_ROOT/hub/bin/hub_usage.py"
  local desktop_usage_token
  for desktop_usage_token in "plan-usage-history" "PLAN_USAGE_HISTORY_PATH" "parse_usage_history"; do
    if grep -qF "$desktop_usage_token" "$hub_collect_file" || grep -qF "$desktop_usage_token" "$hub_usage_file"; then
      record_failure "$test_name" "T25-54: hub_collect.py/hub_usage.py 에 데스크톱 앱 흔적($desktop_usage_token)이 남아 있음"
      return 1
    fi
  done
  local capture_source_token
  for capture_source_token in "session_used_percent" "usage_sample_from_capture" "same_capture_values"; do
    if ! grep -qF "$capture_source_token" "$hub_usage_file"; then
      note_failure "T25-54: hub_usage.py 에 캡처 단일 출처 토큰($capture_source_token)이 없음"
    fi
  done

  # T25-55(문서 정합 — 결정 P1, R1 로 재개정): commands/hub.md 의 usage_sample_age_ms 설명에
  # 데스크톱 앱 문구가 없고, 퍼센트 출처가 명시돼 있다. "유일한 출처"는 R1(사용량 API 폴링,
  # 결정 A2)이 두 번째 생산자를 더하면서 더 이상 참이 아니게 됐다 — "퍼센트의 출처는" 으로
  # 완화해 두 생산자를 모두 포괄한다(T25-54 가 이미 겪은 것과 같은 종류의 재개정).
  if grep -qF "macOS 데스크톱 앱" "$hub_command_file"; then
    note_failure "T25-55: commands/hub.md 에 macOS 데스크톱 앱 문구가 남아 있음(결정 P1 위반)"
  fi
  if ! grep -qF "퍼센트의 출처는" "$hub_command_file"; then
    note_failure "T25-55: commands/hub.md 의 usage_sample_age_ms 설명에 출처 설명이 없음"
  fi

  # T25-56(전제 2 회귀 — #dzh-data 계약 불변): HubSnapshot 의 usage·rate_limit_resets 두
  # 필드가 그대로 있고, 템플릿이 여전히 snapshot.usage·snapshot.rate_limit_resets 를 읽는다.
  if ! grep -qF "usage: UsageSample | None = None" "$hub_model_file"; then
    note_failure "T25-56: hub_model.py 의 HubSnapshot.usage 필드가 계약과 다름"
  fi
  if ! grep -qF "rate_limit_resets: RateLimitResets | None = None" "$hub_model_file"; then
    record_failure "$test_name" "T25-56: hub_model.py 의 HubSnapshot.rate_limit_resets 필드가 계약과 다름"
    return 1
  fi
  local snapshot_field_token
  for snapshot_field_token in "snapshot.usage" "snapshot.rate_limit_resets"; do
    if ! grep -qF "$snapshot_field_token" "$hub_template_file"; then
      note_failure "T25-56: hub_template.html 이 $snapshot_field_token 를 읽지 않음"
    fi
  done

  # T25-57(R3 서버 라우팅 회귀, hub-card-interactions-and-usage.md 결정 N3): 프로젝트
  # 대시보드 라우트는 정규식으로만 해석되고, 기존 화이트리스트는 그대로 남으며, 요청
  # 문자열(self.path)로 경로를 조립하는 코드가 없다.
  if ! grep -qF "PROJECT_DASHBOARD_PATH_PATTERN" "$hub_server_file"; then
    note_failure "T25-57: hub_server.py 에 PROJECT_DASHBOARD_PATH_PATTERN 이 없음"
  fi
  if ! grep -qF '[0-9a-f]{16}' "$hub_server_file"; then
    note_failure "T25-57: hub_server.py 에 [0-9a-f]{16} 패턴이 없음"
  fi
  if ! grep -qF "ALLOWED_REQUEST_PATHS" "$hub_server_file"; then
    record_failure "$test_name" "T25-57: hub_server.py 에 ALLOWED_REQUEST_PATHS 가 없음(T25-15 보강)"
    return 1
  fi
  local path_concat_token
  for path_concat_token in "os.path.join" "/ self.path" "+ self.path"; do
    if grep -qF "$path_concat_token" "$hub_server_file"; then
      note_failure "T25-57: hub_server.py 가 요청 문자열로 경로를 조립하는 것으로 보임($path_concat_token)"
    fi
  done

  # T25-58(R4 회귀, 결정 X1): .project-name 에 data-tooltip 이 없다 — 보이는 텍스트와
  # 같아 제거해도 정보 손실이 없다.
  if grep -qF 'project-name" data-tooltip' "$hub_template_file"; then
    note_failure "T25-58: hub_template.html 의 project-name 에 data-tooltip 잔재가 있음"
  fi

  # T25-59(R5 회귀, 결정 E1~E3): 헤더 버튼 클러스터가 고정 위치를 버리고 .head-row 문서
  # 흐름 안으로 들어왔다.
  if grep -qF "padding-right:150px" "$hub_template_file"; then
    note_failure "T25-59: hub_template.html 에 padding-right:150px 잔재가 있음"
  fi
  if grep -qF "position:fixed;top:16px;right:16px" "$hub_template_file"; then
    note_failure "T25-59: hub_template.html 에 .top-actions 고정 위치 잔재가 있음"
  fi
  if ! grep -qF ".head-row{display:flex" "$hub_template_file"; then
    note_failure "T25-59: hub_template.html 에 .head-row{display:flex 가 없음"
  fi
  if ! grep -qF ".top-actions{margin-left:auto" "$hub_template_file"; then
    record_failure "$test_name" "T25-59: hub_template.html 에 .top-actions{margin-left:auto 가 없음"
    return 1
  fi

  # T25-60(R1 보안 불변식, 결정 A4): hub_usage_fetch.py 에 shell=True·print(·str(error) 가
  # 없고, FAILURE_REASON_MESSAGES 고정 어휘가 있다(불변식 A-SEC).
  local hub_usage_fetch_file="$REPO_ROOT/hub/bin/hub_usage_fetch.py"
  local forbidden_token
  for forbidden_token in "shell=True" "print(" "str(error)"; do
    if grep -qF "$forbidden_token" "$hub_usage_fetch_file"; then
      note_failure "T25-60: hub_usage_fetch.py 에 금지 토큰($forbidden_token)이 있음"
    fi
  done
  if ! grep -qF "FAILURE_REASON_MESSAGES" "$hub_usage_fetch_file"; then
    note_failure "T25-60: hub_usage_fetch.py 에 FAILURE_REASON_MESSAGES 가 없음"
  fi

  # T25-61(R1 구조): hub_usage.py 에 parse_usage_api_response·should_attempt_usage_api_poll·
  # UsageApiPollState(결정 MS1 — 사용량 API 폴링 스케줄이 hub_usage.py 로 편입됐다),
  # hub_config.py 에 usage_api_enabled 타입 등록이 있다(T25-10 이 hub_usage.py·hub_config.py
  # 의 순수성을 이미 강제한다). _CONFIG_FIELD_TYPES 는 hub-collect-split-for-merge.md 로
  # hub_collect.py 에서 hub_config.py 로 옮겨졌다.
  if ! grep -qF "parse_usage_api_response" "$hub_usage_file"; then
    record_failure "$test_name" "T25-61: hub_usage.py 에 parse_usage_api_response 가 없음"
    return 1
  fi
  local model_token
  for model_token in "should_attempt_usage_api_poll" "UsageApiPollState"; do
    if ! grep -qF "$model_token" "$hub_usage_file"; then
      note_failure "T25-61: hub_usage.py 에 $model_token 이 없음"
    fi
  done
  if ! grep -qF '"usage_api_enabled": bool' "$hub_config_file"; then
    record_failure "$test_name" "T25-61: hub_config.py 의 _CONFIG_FIELD_TYPES 에 usage_api_enabled 등록이 없음"
    return 1
  fi

  # T25-62(R2 회귀): 카드 순서 저장·드래그 핸들 관련 토큰이 존재하고, 구 함수
  # stableSortedProjects 는 orderedProjectPaths 로 대체돼 사라졌다.
  local order_token
  for order_token in "'dzh-project-order'" "orderedProjectPaths" "isReordering" "card-drag-handle"; do
    if ! grep -qF "$order_token" "$hub_template_file"; then
      note_failure "T25-62: hub_template.html 에 $order_token 이 없음"
    fi
  done
  if grep -qF "stableSortedProjects" "$hub_template_file"; then
    record_failure "$test_name" "T25-62: hub_template.html 에 구 함수 stableSortedProjects 가 남아 있음"
    return 1
  fi

  # T25-63(R3·R6 마크업 회귀, 결정 N5·Y1~Y4 → hub-detail-side-panel.md 결정 SP1·SP10): 상세
  # 패널 마크업과 .icon-btn 공통 클래스가 존재하고, 테마 토글은 라이트/다크 2상태만 남았다.
  local modal_markup_token
  for modal_markup_token in '<aside id="dzh-detail-panel"' 'id="dzh-detail-frame"' ".icon-btn"; do
    if ! grep -qF "$modal_markup_token" "$hub_template_file"; then
      note_failure "T25-63: hub_template.html 에 $modal_markup_token 이 없음"
    fi
  done
  if ! grep -qF "THEME_CYCLE = ['light', 'dark']" "$hub_template_file"; then
    note_failure "T25-63: hub_template.html 의 THEME_CYCLE 이 2상태가 아님"
  fi
  if grep -qF "'system'" "$hub_template_file"; then
    record_failure "$test_name" "T25-63: hub_template.html 에 3상태 테마 잔재('system')가 남아 있음"
    return 1
  fi

  # T25-64(문서 정합, M5 → hub-detail-side-panel.md 결정 SP10): hub/README.md 에 카드 순서·
  # 상세 패널·usage_api_enabled 설명이 있고, commands/hub.md 에 usage_api_last_failure 설명이 있다.
  local readme_doc_token
  for readme_doc_token in "카드 순서" "상세 패널" "usage_api_enabled"; do
    if ! grep -qF "$readme_doc_token" "$hub_readme_file"; then
      note_failure "T25-64: hub/README.md 에 $readme_doc_token 설명이 없음"
    fi
  done
  if ! grep -qF "usage_api_last_failure" "$hub_command_file"; then
    record_failure "$test_name" "T25-64: commands/hub.md 에 usage_api_last_failure 설명이 없음"
    return 1
  fi

  # T25-65(R3): working 카드 glow — CSS 규칙 + JS 방출 + pulse·접근성 분기가 모두 있어야
  # 신호 자체와 저감 대응이 함께 산다(개정 1 — pulse 와 reduced-motion 분기는 반드시 함께).
  local r3_token
  for r3_token in '.card.card-working{' "card-working'" '@keyframes card-working-glow' 'prefers-reduced-motion'; do
    if ! grep -qF -- "$r3_token" "$hub_template_file"; then
      note_failure "T25-65: hub_template.html 에 $r3_token 이 없음"
    fi
  done
  if ! grep -qF '작업중' "$hub_readme_file"; then
    note_failure "T25-65: hub/README.md 「화면 배치」에 작업중 강조 설명이 없음"
  fi
  # 진폭 핀(개정 2, dashboard-ui-polish-4 PRP 결정 D5 — pulse 진폭을 .35→.6 으로 순화한
  # 값 자체를 못박는다. 위 루프는 @keyframes 이름만 보고 그 안의 값은 보지 않는다).
  if ! grep -qF -- '@keyframes card-working-glow{0%,100%{opacity:.6}' "$hub_template_file"; then
    note_failure "T25-65: card-working-glow 의 진폭이 .6 이 아님(회귀 — 옛 .35 로 되돌아감)"
  fi

  # T25-171(신설, dashboard-ui-polish-4 PRP §4.2 결정 D5 — 검수 1회차 MEDIUM 지적 후속,
  # 개정 docs/prps/hub-session-list-and-glow-fixes.md 결정 GW1·GW3): 주기 핀. 원래 결정 D5 는
  # 두 파일이 같은 두 숫자(진폭 .6·주기 4s)를 쓴다고 명시했으나, 2026-09-17 사용자 요청으로
  # 허브만 주기를 2s 로 줄였다(대시보드의 dz-step-active-pulse 는 4s 그대로) — 이제 공유하는
  # 것은 진폭뿐이다.
  if ! grep -qF -- 'animation:card-working-glow 2s' "$hub_template_file"; then
    note_failure "T25-171: card-working-glow 의 주기가 2s 가 아님(회귀 — 옛 4s 로 되돌아감)"
  fi

  # T25-189(신설, docs/prps/dashboard-hub-signal-tuning.md 결정 D8 — 작업중 카드 bloom 의
  # 이 갈래에서는 원래 T25-172 였다 — main 위로 리베이스하는 시점에 그 번호를 이미
  # hub-server-identity PRP 가 쓰고 있어 원장 1열 유일성 때문에 옮겼다.
  # 확산이 그리드 간격 안에서 끝난다). 리터럴이 아니라 부등식을 고정한다(T25-110 과 같은
  # 형태) — CSS Backgrounds 3 §7.1.1 근거로 blur 의 실효 확산을 1.5×blur 로 잡는 보수적
  # 상한이다(실측 Blink 는 이보다 짧다). gap 또는 bloom 선언 자체를 못 찾으면 공허 통과
  # 대신 실패로 보고한다.
  local bloom_gap_output
  bloom_gap_output=$(python3 - "$hub_template_file" <<'PYEOF'
import re
import sys

BLUR_SPREAD_UPPER_BOUND_FACTOR = 1.5   # CSS Backgrounds 3 §7.1.1 보수적 상한

source = open(sys.argv[1], encoding="utf-8").read()
# 검수 R2 MEDIUM 2: /* ... */ 주석을 먼저 지운다. 이 파일은 CSS 리터럴을 통째로
# 인용하는 주석 관용구를 쓴다(바로 위 .card.card-working 규칙의 근거 주석이 그 예다) —
# 스트립 없이 원문 그대로 정규식을 돌리면 re.search 는 맨 앞 매치를 반환하므로, 주석이
# 완결된 리터럴을 먼저 인용하면 실제 선언보다 먼저 걸려 값을 잘못 읽는다(검수자 실측
# 재현 — 주석에 옛 값 "…,0 0 18px -4px var(--accent)}" 를 완결 인용하면 실제 선언은
# 8px -2px 로 멀쩡한데도 "상한 23 > gap 12" 로 오탐했다. 반대로 무해한 값을 먼저
# 인용하면 진짜 깨진 선언을 놓치는 공허 통과도 같은 구조에서 가능하다 — 이 검사가
# 막으려던 바로 그것이다). gap_match 에도 같은 위험이 원리적으로 있다(주석이 "#dzh-app{"
# 를 완결 인용하면 마찬가지로 오매칭한다) — source 하나만 스트립해 두 정규식을 함께
# 보호한다(실측: 지금 파일의 주석 중 "#dzh-app{" 를 리터럴로 완결 인용하는 곳은 없어
# 아직 발화하지 않지만, 그 성립은 관례에 기대는 것이지 검사가 강제하는 것이 아니다).
source = re.sub(r"/\*.*?\*/", "", source, flags=re.DOTALL)
gap_match = re.search(r"#dzh-app\{[^}]*gap:(\d+)px", source)
bloom_match = re.search(
    r"\.card\.card-working\{[^}]*,0 0 (\d+)px (-?\d+)px var\(--accent\)\}", source
)

if gap_match is None:
    print("#dzh-app 의 gap 선언을 찾지 못함")
    raise SystemExit(0)
if bloom_match is None:
    print(".card.card-working 의 바깥 bloom 선언을 찾지 못함")
    raise SystemExit(0)

gap = int(gap_match.group(1))
blur = int(bloom_match.group(1))
spread = int(bloom_match.group(2))
upper_bound = BLUR_SPREAD_UPPER_BOUND_FACTOR * blur + spread
if upper_bound > gap:
    print(f"bloom 확산 상한 {upper_bound:g} > gap {gap}(blur={blur}px, spread={spread}px)")
else:
    print("OK")
PYEOF
)
  if [[ "$bloom_gap_output" != "OK" ]]; then
    note_failure "T25-189: 작업중 카드 bloom 확산이 간격을 넘을 수 있음 — $bloom_gap_output"
  fi

  # T25-66(R4): 바깥 클릭 리스너 — closest 가드 2종이 있어야 하고, GOTCHA 2 를 줄 번호
  # 비교로 기계적으로 강제한다(T25-53 선례) — if(!isServed){ 뒤로 가면 file:// 모드에서
  # 기능이 조용히 사라진다.
  if ! grep -qF "closest('#dzh-usage')" "$hub_template_file"; then
    note_failure "T25-66: closest('#dzh-usage') 가드 미발견"
  fi
  if ! grep -qF "closest('#dzh-detail-panel')" "$hub_template_file"; then
    record_failure "$test_name" "T25-66: closest('#dzh-detail-panel') 가드 미발견"
    return 1
  fi
  # if(!isServed){ 는 renderConnectionStatus() 안에도 한 번 더 나온다(무관한 기존 코드) —
  # 리스너 등록을 지키는 실제 게이트는 IIFE 끝의 reload 분기이므로 **마지막** 등장을 앵커로
  # 쓴다(T22-37 이 pip 버튼 위치를 마지막 등장으로 판정하는 것과 같은 관례).
  local outside_click_guard_line is_served_gate_line
  outside_click_guard_line=$(grep -n "closest('#dzh-usage')" "$hub_template_file" | head -1 | cut -d: -f1)
  is_served_gate_line=$(grep -n 'if(!isServed){' "$hub_template_file" | tail -1 | cut -d: -f1)
  if [[ -z "$outside_click_guard_line" || -z "$is_served_gate_line" || "$outside_click_guard_line" -ge "$is_served_gate_line" ]]; then
    note_failure "T25-66: 바깥 클릭 리스너가 if(!isServed){ 뒤에 등록됨(GOTCHA 2 위반)"
  fi
  if ! grep -qF '바깥' "$hub_readme_file"; then
    note_failure "T25-66: hub/README.md 사용량 패널 절에 바깥 클릭 설명이 없음"
  fi

  # T25-67(R5, 역방향 중심): 패널 안 툴팁 2종과 죽은 옵저버가 사라졌는지 확인하면서도,
  # renderUsageResetRow·usage-meta·data-tooltip(패널 밖)은 여전히 살아 있어야 한다 —
  # "지운 것"과 "지우면 안 되는 것"을 함께 감사한다.
  if grep -qF '이 정보를 확인한 시각' "$hub_template_file"; then
    note_failure "T25-67: '이 정보를 확인한 시각' 툴팁 문구가 남아 있음"
  fi
  if grep -qF 'usage-meta" data-tooltip' "$hub_template_file"; then
    note_failure "T25-67: usage-meta 의 data-tooltip 속성이 남아 있음"
  fi
  # ③ 반전(R-B): R5 는 이 옵저버를 지웠지만(결정 UT4), R-B 가 조건부로 되살렸다(결정 EX7) —
  # 만료 안내 줄(.usage-stale-note)이 패널 안 유일한 트리거이므로 T25-71 이 이 복원을 강제한다.
  if ! grep -qF 'usageBodyElForTooltipObserver' "$hub_template_file"; then
    note_failure "T25-67: usageBodyElForTooltipObserver 가 없음(R-B 가 조건부로 복원해야 함, 결정 EX7)"
  fi
  if ! grep -qF 'renderUsageResetRow' "$hub_template_file"; then
    note_failure "T25-67: renderUsageResetRow 함수가 사라짐(과잉 제거)"
  fi
  if ! grep -qF 'usage-meta' "$hub_template_file" || ! grep -qF 'data-tooltip' "$hub_template_file"; then
    note_failure "T25-67: usage-meta 또는 data-tooltip(패널 밖) 이 과잉 제거됨"
  fi
  if ! grep -qF 'rate_limit_capture_age_ms' "$hub_readme_file"; then
    record_failure "$test_name" "T25-67: hub/README.md 에 캡처 시각 진단 창구(rate_limit_capture_age_ms) 언급이 없음"
    return 1
  fi

  # T25-68(R7, 정·역 혼합): 라이브 이동 구현 4토큰이 있고, 제거된 키보드 경로의 흔적 6종은
  # 전부 0건이어야 한다(전수 확인 — PRP 자체 확인 결과와 일치).
  local r7_positive_token
  for r7_positive_token in 'setDragImage' 'compareDocumentPosition' 'card-dragging' 'commitReorder(currentCardOrder())'; do
    if ! grep -qF -- "$r7_positive_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-68: hub_template.html 에 $r7_positive_token 이 없음"
      return 1
    fi
  done
  local r7_removed_token
  for r7_removed_token in 'keyboardMoveTargetIndex' 'announceProjectPosition' 'moveProjectPath' 'dzh-live' 'restoreHandleFocusAfterRender' 'ArrowLeft'; do
    if grep -qF -- "$r7_removed_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-68: hub_template.html 에 제거 대상 $r7_removed_token 이 남아 있음"
      return 1
    fi
  done
  local card_order_section
  card_order_section=$(sed -n '/^## 카드 순서/,/^## /p' "$hub_readme_file")
  if grep -qF '←' <<< "$card_order_section"; then
    note_failure "T25-68: hub/README.md 「카드 순서」에 ← 가 남아 있음(키보드 조작 잔재)"
  fi
  if ! grep -qF '드래그' <<< "$card_order_section"; then
    record_failure "$test_name" "T25-68: hub/README.md 「카드 순서」에 드래그 설명이 없음"
    return 1
  fi

  # T25-69·T25-70 은 폐기됐다(hub-detail-side-panel.md) — 대상인 모달 depth·경계 규칙과
  # 모달 열기 애니메이션 자체가 사라졌다. 대체 검사는 T25-77(레이아웃)·T25-79(애니메이션 세트
  # + 소스 순서)다.

  # T25-71(R-B 표시 + 툴팁 복원): 만료(조회되지 않음) 표시 토큰 4개가 있고, 그 툴팁 트리거를
  # 위해 tooltipDismissObserver 가 #dzh-usage-body 를 다시 관찰한다(GOTCHA 1 의 기계적 강제).
  local stale_display_token
  for stale_display_token in "usage-stale-note" "USAGE_STALE_TOOLTIP" "usage-pct-empty" "is_stale"; do
    if ! grep -qF -- "$stale_display_token" "$hub_template_file"; then
      note_failure "T25-71: hub_template.html 에 $stale_display_token 이 없음"
    fi
  done
  if ! grep -qF "tooltipDismissObserver.observe(usageBodyElForTooltipObserver" "$hub_template_file"; then
    note_failure "T25-71: tooltipDismissObserver 가 #dzh-usage-body 를 다시 관찰하지 않음(GOTCHA 1)"
  fi

  # T25-72(R-B 파이썬 계약): UsageSample.is_stale·mark_stale_usage_sample 이 hub_usage.py 에
  # 있고, hub_collect.py 가 그 함수를 부른다. 역방향(핵심) — _capture_for_snapshot 범위 안에
  # 만료 시 지우던 옛 경로(usage = None)가 되살아나지 않았다.
  if ! grep -qF "is_stale: bool = False" "$hub_usage_file"; then
    note_failure "T25-72: hub_usage.py 에 is_stale: bool = False 필드가 없음"
  fi
  if ! grep -qF "def mark_stale_usage_sample" "$hub_usage_file"; then
    note_failure "T25-72: hub_usage.py 에 mark_stale_usage_sample 함수가 없음"
  fi
  if ! grep -qF "mark_stale_usage_sample" "$hub_collect_file"; then
    record_failure "$test_name" "T25-72: hub_collect.py 가 mark_stale_usage_sample 을 호출하지 않음"
    return 1
  fi
  local capture_for_snapshot_body
  capture_for_snapshot_body=$(sed -n '/^def _capture_for_snapshot/,/^# ---- 합성 ----/p' "$hub_collect_file")
  if echo "$capture_for_snapshot_body" | grep -qF "usage = None"; then
    record_failure "$test_name" "T25-72: _capture_for_snapshot 에 옛 숨김 경로(usage = None)가 되살아남"
    return 1
  fi

  # T25-73(R-A 온보딩 + 소유권 원칙): 정방향 — commands/hub.md 의 /hub install 절에
  # install-statusline 이 있고, hub/install.sh 의 "다음 단계" 줄과 hub/README.md 「빠른 시작」에
  # 상태줄 언급이 있다. 역방향(핵심, 전제 1 의 기계적 강제) — hub/install.sh 는 settings.json 도
  # install-statusline 도 모른다.
  local hub_install_section
  hub_install_section=$(sed -n '/^## `\/hub install`/,/^## `\/hub off`/p' "$hub_command_file")
  if ! echo "$hub_install_section" | grep -qF "install-statusline"; then
    note_failure "T25-73: commands/hub.md 의 /hub install 절에 install-statusline 이 없음"
  fi
  if ! grep -F "다음 단계" "$hub_install_file" | grep -qF "상태줄"; then
    record_failure "$test_name" "T25-73: hub/install.sh 의 '다음 단계' 안내에 상태줄 언급이 없음"
    return 1
  fi
  local quick_start_section
  quick_start_section=$(sed -n '/^## 빠른 시작/,/^## /p' "$hub_readme_file")
  if ! echo "$quick_start_section" | grep -qF "상태줄"; then
    note_failure "T25-73: hub/README.md 「빠른 시작」에 상태줄 언급이 없음"
  fi
  if grep -qF "settings.json" "$hub_install_file"; then
    record_failure "$test_name" "T25-73: hub/install.sh 가 settings.json 을 언급함(전제 1 위반)"
    return 1
  fi
  # "install-statusline" 은 기존 --uninstall 절차의 "uninstall-statusline" 호출 안에도 부분
  # 문자열로 존재한다(u+install-statusline) — 그 문자열 자체를 금지하면 항상 거짓양성이 난다.
  # 실제로 막아야 할 것은 **단독 직접 호출**이므로, 전체 등장 횟수가 uninstall-statusline
  # 등장 횟수와 같은지(=모든 등장이 그 안에만 있는지)로 판정한다.
  local install_statusline_total uninstall_statusline_total
  install_statusline_total=$(grep -oF "install-statusline" "$hub_install_file" | wc -l | tr -d ' ')
  uninstall_statusline_total=$(grep -oF "uninstall-statusline" "$hub_install_file" | wc -l | tr -d ' ')
  if [[ "$install_statusline_total" -ne "$uninstall_statusline_total" ]]; then
    record_failure "$test_name" "T25-73: hub/install.sh 가 install-statusline 을 (uninstall-statusline 바깥에서) 직접 호출함(전제 1 위반)"
    return 1
  fi

  # T25-74(문서 정합): hub/README.md 사용량 패널 절에 '조회되지 않음' 설명이 있고, 역방향 —
  # R-B 이전의 낡은 숨김 서술("5시간보다 오래됐거나 … 패널 전체를 표시하지 않는다")이 남아
  # 있지 않다(문서와 동작이 어긋난 채 방치되는 것을 막는다).
  local usage_panel_section
  usage_panel_section=$(sed -n '/^## 사용량 패널/,/^## /p' "$hub_readme_file")
  if ! echo "$usage_panel_section" | grep -qF "조회되지 않음"; then
    note_failure "T25-74: hub/README.md 사용량 패널 절에 '조회되지 않음' 설명이 없음"
  fi
  if echo "$usage_panel_section" | grep -qF "5시간보다 오래됐거나(세션을 한동안 안"; then
    record_failure "$test_name" "T25-74: hub/README.md 에 R-B 이전의 낡은 숨김 서술이 남아 있음"
    return 1
  fi

  # T25-75(역방향 전용, dashboard-into-hub.md M2 재조준): hub/bin/*.py 와 hub_template.html
  # 어디에도 data-owner-token 문자열이 없다. hub_dashboard_render.py·hub_dashboard_log.py
  # 는 예외다(HD14 — 이 둘이 그 속성을 "정의"하는 쪽이다). M2 부터 hub_server.py 가 그
  # 렌더러를 요청마다 부르지만(HD5), data-owner-token 리터럴 자체는 여전히
  # hub_dashboard_render.py 안에서만 정의되고 hub_parse.py·hub_server.py 를 포함한 허브의
  # 나머지 모듈은 이 문자열을 갖지 않는다 — 계약이 다시 결합되면(허브가 그 속성을 직접
  # 읽기 시작하면) 이 가드가 잡는다.
  local hub_source_file
  for hub_source_file in "$REPO_ROOT"/hub/bin/*.py "$hub_template_file"; do
    case "$(basename "$hub_source_file")" in
      hub_dashboard_render.py | hub_dashboard_log.py) continue ;;
    esac
    if grep -qF 'data-owner-token' "$hub_source_file"; then
      record_failure "$test_name" "T25-75: $hub_source_file 에 data-owner-token 문자열이 있음(허브-대시보드 결합 회귀)"
      return 1
    fi
  done

  # T25-76(hub-detail-side-panel.md 결정 SP1 마크업 + 역방향): <aside id="dzh-detail-panel">
  # 비모달 패널 마크업이 있고, 옛 <dialog> 모달 마크업·머리 주석 잔재는 전부 사라졌다.
  local panel_markup_token
  for panel_markup_token in '<aside id="dzh-detail-panel"' 'id="dzh-detail-frame"' 'role="dialog"' 'aria-labelledby="dzh-detail-title"'; do
    if ! grep -qF -- "$panel_markup_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-76: hub_template.html 에 $panel_markup_token 이 없음"
      return 1
    fi
  done
  local removed_modal_markup_token
  for removed_modal_markup_token in '<dialog id="dzh-dashboard-modal"' 'showModal(' 'dzh-modal-frame' '#dzh-dashboard-modal'; do
    if grep -qF -- "$removed_modal_markup_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-76: hub_template.html 에 옛 모달 잔재($removed_modal_markup_token)가 남아 있음"
      return 1
    fi
  done

  # T25-77(결정 SP2·SP3 레이아웃 → T25-69 대체): 밀어내기·슬라이드 CSS 토큰이 있고, 옛 모달
  # depth 규칙(::backdrop·backdrop-fade)은 대상 자체가 사라져 함께 없어졌다.
  local panel_layout_token
  for panel_layout_token in '--dzh-panel-width:' 'padding-right:var(--dzh-panel-width)' \
      'translateX(calc(-1 * var(--dzh-panel-width)))' 'transform:translateX(100%)' 'visibility:hidden'; do
    if ! grep -qF -- "$panel_layout_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-77: hub_template.html 에 $panel_layout_token 이 없음"
      return 1
    fi
  done
  local removed_modal_depth_token
  for removed_modal_depth_token in '.modal::backdrop{' '@keyframes backdrop-fade'; do
    if grep -qF -- "$removed_modal_depth_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-77: hub_template.html 에 옛 모달 잔재($removed_modal_depth_token)가 남아 있음"
      return 1
    fi
  done

  # T25-78(결정 SP3 브레이크포인트 일치, GOTCHA 2 기계적 강제): CSS @media (min-width:NNNNpx)
  # 의 숫자와 JS PANEL_PUSH_MIN_WIDTH_PX 의 숫자가 같아야 한다 — 한쪽만 고치면 "밀어내는데
  # 배경이 inert" 같은 조용한 어긋남이 생긴다.
  local css_breakpoint js_breakpoint
  css_breakpoint=$(grep -oE '@media \(min-width:[0-9]+px\)' "$hub_template_file" | head -1 | grep -oE '[0-9]+')
  js_breakpoint=$(grep -oE 'PANEL_PUSH_MIN_WIDTH_PX = [0-9]+' "$hub_template_file" | grep -oE '[0-9]+')
  if [[ -z "$css_breakpoint" || -z "$js_breakpoint" || "$css_breakpoint" != "$js_breakpoint" ]]; then
    note_failure "T25-78: CSS 브레이크포인트($css_breakpoint)와 JS PANEL_PUSH_MIN_WIDTH_PX($js_breakpoint)가 다름"
  fi

  # T25-79(결정 SP12·SP13·SP16·SP17 양방향 애니메이션 세트 + 소스 순서, hub-detail-side-panel.md
  # R2 — 개정: 초판은 열기만이었다): 전이 선언이 "닫힌(기본) 규칙"에 있어야 하고(GOTCHA 11),
  # visibility 가 같은 시간으로 함께 전이돼야 하며(GOTCHA 13), prefers-reduced-motion 무효화
  # 블록이 6셀렉터로 확장되고 소스 순서상 @media (min-width:1024px) 블록보다 뒤에 온다(명세도
  # 함정, GOTCHA 15). 옛 모달 열기 애니메이션은 대상 자체가 사라져 함께 없어졌다.

  # 79-a: 전이 선언 토큰(GOTCHA 13 — visibility 를 전이 목록에서 빼면 슬라이드가 보이지 않는다)
  if ! grep -qF -- 'transition:transform 180ms ease-out, visibility 180ms' "$hub_template_file"; then
    record_failure "$test_name" "T25-79-a: hub_template.html 에 transition:transform 180ms ease-out, visibility 180ms 가 없음"
    return 1
  fi

  # 79-b: 그 토큰이 "닫힌(기본) 규칙"에 있어야 한다 — body.dzh-panel-open .detail-panel{transform:none
  # 규칙보다 줄 번호가 앞서야 한다(GOTCHA 11 — 열림 규칙으로 되돌리면 닫기 애니메이션이 소실된다).
  local base_transition_line panel_open_rule_line
  base_transition_line=$(grep -n 'transition:transform 180ms ease-out, visibility 180ms' "$hub_template_file" | head -1 | cut -d: -f1)
  panel_open_rule_line=$(grep -n 'body\.dzh-panel-open \.detail-panel{transform:none' "$hub_template_file" | head -1 | cut -d: -f1)
  if [[ -z "$base_transition_line" || -z "$panel_open_rule_line" || "$base_transition_line" -ge "$panel_open_rule_line" ]]; then
    record_failure "$test_name" "T25-79-b: 전이 선언이 body.dzh-panel-open .detail-panel 규칙보다 앞(기본 규칙)에 있지 않음(GOTCHA 11)"
    return 1
  fi

  # 79-c: prefers-reduced-motion 블록의 첫 셀렉터가 @media (min-width:1024px) 블록보다 뒤에
  # 와야 한다 — 미디어 쿼리는 명세도를 올리지 않으므로 소스 순서가 전부다(GOTCHA 15).
  local push_mode_usage_line reduced_motion_first_selector_line
  push_mode_usage_line=$(grep -n 'body\.dzh-panel-open #dzh-usage{transform:' "$hub_template_file" | head -1 | cut -d: -f1)
  reduced_motion_first_selector_line=$(grep -n '\.detail-panel,$' "$hub_template_file" | head -1 | cut -d: -f1)
  if [[ -z "$push_mode_usage_line" || -z "$reduced_motion_first_selector_line" || "$reduced_motion_first_selector_line" -le "$push_mode_usage_line" ]]; then
    record_failure "$test_name" "T25-79-c: prefers-reduced-motion 블록이 @media (min-width:1024px) 블록보다 앞에 있음(GOTCHA 15)"
    return 1
  fi

  # 79-d: 무효화 블록에 6셀렉터가 모두 있어야 한다 — 기본 규칙 3개(.detail-panel·body·
  # #dzh-usage)를 빠뜨리면 저감 모드에서 닫기만 애니메이션되는 반쪽 상태가 된다(GOTCHA 15).
  local reduced_motion_token
  for reduced_motion_token in '.detail-panel,' '  body,' '  #dzh-usage,' 'body.dzh-panel-open,' \
      'body.dzh-panel-open .detail-panel,' 'body.dzh-panel-open #dzh-usage{transition:none}'; do
    if ! grep -qF -- "$reduced_motion_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-79-d: prefers-reduced-motion 블록에 $reduced_motion_token 이 없음"
      return 1
    fi
  done

  # 79-e(역방향, 초판 승계): 옛 모달 열기 애니메이션 잔재가 없다.
  local removed_modal_animation_token
  for removed_modal_animation_token in 'animation:modal-open' '@keyframes modal-open'; do
    if grep -qF -- "$removed_modal_animation_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-79-e: hub_template.html 에 옛 모달 잔재($removed_modal_animation_token)가 남아 있음"
      return 1
    fi
  done

  # T25-80(결정 SP7·SP9 폴링 정지 → hub-panel-empty-state-and-open-card.md 결정 OC1):
  # 닫힘·교체 모두 about:blank/loadPanelDocument 경로를 쓰고, openPanelTarget 이 열림 상태의
  # 유일한 진실이다. src 대입으로의 회귀(뒤로가기 오염 재발)를 막는다.
  local panel_stop_token
  for panel_stop_token in 'about:blank' 'contentWindow.location.replace(' 'openPanelTarget'; do
    if ! grep -qF -- "$panel_stop_token" "$hub_template_file"; then
      note_failure "T25-80: hub_template.html 에 $panel_stop_token 이 없음"
    fi
  done
  if grep -qF -- 'panelFrameEl.src' "$hub_template_file"; then
    record_failure "$test_name" "T25-80: hub_template.html 에 panelFrameEl.src 대입(SP9 회귀)이 남아 있음"
    return 1
  fi

  # T25-81(문서 정합 — 개정: R2 가 닫힘 서술 토큰을 추가, M2 재개정 — 카드 상세보기 모달
  # 도입, docs/prps/hub-session-modal-and-partial-update.md 결정 SC17): hub/README.md 가
  # 패널로의 전환과 닫힘(SP18)·카드 상세보기(모달) 도입을 설명하고, hub_template.html 머리
  # 주석이 불변식 개정(H1⁗)을 반영한다. 역방향 — README 에 옛 기능 이름 '대시보드 모달'
  # 잔재가 없다(SC17 이 역검사를 이 옛 이름으로 좁힌다 — 카드 상세보기 자신은 정당하게
  # '모달'이라는 낱말을 쓴다).
  local readme_panel_token
  for readme_panel_token in '상세 패널' '밀' '덮' '나간다' '카드 상세보기'; do
    if ! grep -qF -- "$readme_panel_token" "$hub_readme_file"; then
      note_failure "T25-81: hub/README.md 에 $readme_panel_token 토큰이 없음"
    fi
  done
  if ! grep -qF -- 'H1⁗' "$hub_template_file"; then
    note_failure "T25-81: hub_template.html 머리 주석에 H1⁗ 이 없음"
  fi
  if grep -qF '대시보드 모달' "$hub_readme_file"; then
    record_failure "$test_name" "T25-81: hub/README.md 에 옛 기능 이름 '대시보드 모달' 잔재가 남아 있음"
    return 1
  fi

  # T25-82(SP14 닫기 지연 경로, hub-detail-side-panel.md R2): about:blank 지연은
  # setTimeout(PANEL_CLOSE_ANIMATION_MS) 이고 transitionend 를 쓰지 않는다(GOTCHA 12 — 저감
  # 모드에서는 발화하지 않고 백그라운드 탭에서는 상한 없이 밀린다). 상태 클래스
  # (dzh-panel-closing) 로의 회귀(SP12 안 B)도 함께 막는다.
  local panel_close_delay_token
  for panel_close_delay_token in 'PANEL_CLOSE_ANIMATION_MS' 'panelBlankTimerId' \
      'scheduleBlankAfterSlide' 'clearTimeout(panelBlankTimerId)'; do
    if ! grep -qF -- "$panel_close_delay_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-82: hub_template.html 에 $panel_close_delay_token 이 없음"
      return 1
    fi
  done
  # 역방향 토큰은 실제 사용(이벤트 리스너 등록) 형태만 본다 — GOTCHA 12 설명 주석 자체가
  # "transitionend" 라는 낱말을 언급하므로(왜 안 쓰는지 설명해야 하니까), 낱말 단순 매칭은
  # 설계가 요구하는 그 주석과 스스로 충돌한다.
  local panel_close_delay_removed_token
  for panel_close_delay_removed_token in "addEventListener('transitionend'" 'dzh-panel-closing'; do
    if grep -qF -- "$panel_close_delay_removed_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-82: hub_template.html 에 금지 토큰($panel_close_delay_removed_token)이 있음"
      return 1
    fi
  done

  # T25-83(SP15 재진입 가드의 위치, 기계적 강제 — 선례: T25-66 의 줄 번호 비교): 취소는
  # openDetailPanel 과 closeDetailPanel 사이에서만 일어나야 한다 — 그 지점에서 대기 중인
  # blank 타이머는 존재할 수 없다("대기 타이머 ⇒ 닫힘" 불변식, SP15). 함수 순서를 뒤집으면
  # 이 검사가 실패한다.
  local open_fn_line close_fn_line cancel_line
  open_fn_line=$(grep -n 'function openDetailPanel(' "$hub_template_file" | head -1 | cut -d: -f1)
  close_fn_line=$(grep -n 'function closeDetailPanel(' "$hub_template_file" | head -1 | cut -d: -f1)
  cancel_line=$(grep -n 'clearTimeout(panelBlankTimerId)' "$hub_template_file" | head -1 | cut -d: -f1)
  if [[ -z "$cancel_line" || -z "$open_fn_line" || -z "$close_fn_line" \
      || "$cancel_line" -le "$open_fn_line" || "$cancel_line" -ge "$close_fn_line" ]]; then
    record_failure "$test_name" "T25-83: clearTimeout(panelBlankTimerId) 가 openDetailPanel 과 closeDetailPanel 사이에 있지 않음(SP15)"
    return 1
  fi

  # T25-84(SP12·SP14 시간 3중 일치, 기계적 강제 — 선례: T25-78): CSS 슬라이드 시간·CSS
  # visibility 시간·JS PANEL_CLOSE_ANIMATION_MS 세 숫자가 모두 같아야 한다. 180 을 리터럴로
  # 적지 않는다 — 세 값의 상호 일치만 본다(시간을 바꾸고 싶으면 세 곳을 함께 고치게 된다).
  local css_slide_ms css_visibility_ms js_close_ms
  css_slide_ms=$(grep -oE 'transition:transform [0-9]+ms ease-out, visibility [0-9]+ms' \
                   "$hub_template_file" | head -1 | grep -oE '[0-9]+' | head -1)
  css_visibility_ms=$(grep -oE 'transition:transform [0-9]+ms ease-out, visibility [0-9]+ms' \
                   "$hub_template_file" | head -1 | grep -oE '[0-9]+' | tail -1)
  js_close_ms=$(grep -oE 'PANEL_CLOSE_ANIMATION_MS = [0-9]+' "$hub_template_file" | grep -oE '[0-9]+')
  if [[ -z "$js_close_ms" || -z "$css_slide_ms" || "$css_slide_ms" != "$css_visibility_ms" \
      || "$css_slide_ms" != "$js_close_ms" ]]; then
    record_failure "$test_name" "T25-84: CSS 슬라이드(${css_slide_ms})·CSS visibility(${css_visibility_ms})·JS PANEL_CLOSE_ANIMATION_MS(${js_close_ms}) 가 서로 다름"
    return 1
  fi

  # T25-85(SP11 헤드 패널화 + G8, hub-detail-side-panel.md R2 → hub-panel-polish-and-icons.md
  # 결정 PV12): 닫기 컨트롤이 .detail-close 를 쓰고 lucide chevrons-right(오른쪽으로 밀려
  # 나가는 실제 동작을 가리킨다) 아이콘을 쓴다. 역방향 — border-bottom 이 파일 전체 0건이다
  # (R2 승인 항목 6 — 시안 C 가 탈락해 토큰을 좁힐 이유가 없다), 옛 .icon-btn 닫기 버튼·
  # ✕ 글리프도 남아 있지 않다.
  local detail_close_token
  for detail_close_token in '.detail-close{' 'class="detail-close"' '.detail-close svg{' \
      'aria-label="닫기"' 'data-tooltip="닫기 (Esc)"'; do
    if ! grep -qF -- "$detail_close_token" "$hub_template_file"; then
      note_failure "T25-85: hub_template.html 에 $detail_close_token 이 없음"
    fi
  done
  # "border-bottom:" (선언 형태)만 본다 — SP11 시안 A 설명 주석 자체가 "border-bottom 을
  # 지워도…" 라고 그 낱말을 언급해야 하므로(G8 이 왜 성립하는지 설명해야 하니까), 낱말 단순
  # 매칭은 설계가 요구하는 그 주석과 스스로 충돌한다.
  if grep -qF -- 'border-bottom:' "$hub_template_file"; then
    record_failure "$test_name" "T25-85: hub_template.html 에 border-bottom:(G8 위반) 선언이 남아 있음"
    return 1
  fi
  local removed_detail_close_token
  for removed_detail_close_token in '<button id="dzh-detail-close" class="icon-btn"' '>✕<'; do
    if grep -qF -- "$removed_detail_close_token" "$hub_template_file"; then
      note_failure "T25-85: hub_template.html 에 옛 닫기 버튼 잔재($removed_detail_close_token)가 남아 있음"
    fi
  done

  # T25-86(RV1 부활 규칙 + 순서, GOTCHA 1, docs/prps/hub-session-revival-and-stale-tier1.md —
  # 재조준(M1, 결정 BW11): 대상이 hub_session_facts.py 로 옮겼다 — build_session_facts 전체가
  # 그 모듈로 이동했기 때문이다):
  # SessionStart 분기가 ended_at_ms 를 해제한다. 기계적 검사 — 내부 이벤트 필터의 판정
  # (if is_filtered:)이 _apply_tracked_event 호출보다 먼저 나와야 한다(선례: T25-83 의 줄
  # 번호 비교) — 그래야 compact 가 이 함수에 도달하기 전에 걸러진다(GOTCHA 1).
  if ! grep -qF 'elif event.hook_event_name == "SessionStart":' "$hub_session_facts_file"; then
    note_failure "T25-86: hub_session_facts.py 에 SessionStart 부활 분기가 없음"
  fi
  if ! grep -qF 'session.ended_at_ms = None' "$hub_session_facts_file"; then
    record_failure "$test_name" "T25-86: hub_session_facts.py 에 session.ended_at_ms = None 대입이 없음"
    return 1
  fi
  local is_filtered_check_line apply_tracked_event_call_line
  is_filtered_check_line=$(grep -n 'if is_filtered:' "$hub_session_facts_file" | head -1 | cut -d: -f1)
  apply_tracked_event_call_line=$(grep -n '_apply_tracked_event(session, event)' "$hub_session_facts_file" | head -1 | cut -d: -f1)
  if [[ -z "$is_filtered_check_line" || -z "$apply_tracked_event_call_line" \
      || "$is_filtered_check_line" -ge "$apply_tracked_event_call_line" ]]; then
    record_failure "$test_name" "T25-86: 내부 이벤트 필터가 _apply_tracked_event 호출보다 먼저 오지 않음(GOTCHA 1)"
    return 1
  fi

  # T25-87(GN1·GN2·GN4 파이썬 계약, GOTCHA 2·3): 세대 판정 술어·상수·필드가 존재하고,
  # LIVE_SESSION_STATES 에 stale·done 이 없으며(GOTCHA 3 — 부활한 좀비 stale 세션이 판정을
  # 깨뜨리는 것을 막는다), ProjectView 필드 순서가 dashboard_key 뒤다(GOTCHA 2).
  local gn_python_token
  for gn_python_token in 'def is_tier1_from_previous_task(' 'LIVE_SESSION_STATES' \
      'tier1_is_previous_task: bool = False'; do
    if ! grep -qF -- "$gn_python_token" "$hub_project_file"; then
      record_failure "$test_name" "T25-87: hub_project.py 에 $gn_python_token 이 없음"
      return 1
    fi
  done
  local live_session_states_decl_line
  live_session_states_decl_line=$(grep -n '^LIVE_SESSION_STATES' "$hub_project_file" | head -1)
  if [[ -z "$live_session_states_decl_line" ]] \
      || echo "$live_session_states_decl_line" | grep -qE '"stale"|"done"'; then
    record_failure "$test_name" "T25-87: LIVE_SESSION_STATES 선언에 stale·done 이 있거나 선언을 찾지 못함(GOTCHA 3)"
    return 1
  fi
  local dashboard_key_field_line tier1_is_previous_task_field_line
  dashboard_key_field_line=$(grep -n 'dashboard_key: str | None = None' "$hub_project_file" | head -1 | cut -d: -f1)
  tier1_is_previous_task_field_line=$(grep -n 'tier1_is_previous_task: bool = False' "$hub_project_file" | head -1 | cut -d: -f1)
  if [[ -z "$dashboard_key_field_line" || -z "$tier1_is_previous_task_field_line" \
      || "$dashboard_key_field_line" -ge "$tier1_is_previous_task_field_line" ]]; then
    record_failure "$test_name" "T25-87: ProjectView 필드 순서 — dashboard_key 가 tier1_is_previous_task 보다 먼저 와야 함(GOTCHA 2)"
    return 1
  fi

  # T25-88(역전환 — 카드 상세보기 정리 M2, 결정 MX4·MX13, docs/prps/hub-session-modal-cleanup.md
  # §10.1; 원래는 GN5 「이전 작업」 라벨 카드 표시의 정방향 가드였다, G9 — 새 색 리터럴 금지): 카드와
  # 카드 상세보기 머리에서 프로젝트 단위 진행률이 걷히며 그 경고 라벨의 CSS·상수와, 카드·머리에 톤다운을
  # 거는 스코프 셀렉터가 되살아나지 않는다. 파일 전체를 세므로 주석까지 본다(T25-178 선례) — 걷은
  # 식별자를 템플릿 주석에 다시 적지 않는다. 옛 T25-184(톤다운 셀렉터의 자식 결합자 >)는 그 셀렉터 자체가
  # 걷혀 이 역가드(.card[data-tier1-)가 덮으므로 폐기했다. 카드 상세보기 머리의 같은 톤다운 셀렉터
  # (.session-modal-root[data-tier1-)는 M2 가 이 자리에서 따로 문 적이 있으나, 머리에 패널 속성을 다는 갈래
  # 전체(.session-modal-root[data-)를 T25-247 의 역가드가 접두 포함으로 덮게 돼 걷었다(결정 MX13 —
  # 다른 역가드가 이미 덮는 것은 두지 않는다). 유지 — 패널 안내 줄(.detail-note)은 남으므로 그 규칙에 #
  # 색 리터럴이 0건이다(G9).
  # 세 줄로 나눠 쓴다(반복문 대신) — 반복문 메시지는 변수를 보간해 소스에 리터럴로 나타나지 않아 원장
  # 판별자 자격(T37-13)을 못 채운다(T25-240 관례와 같은 이유).
  if grep -qF -- 'tier1-prev-label' "$hub_template_file"; then
    note_failure "T25-88: hub_template.html 에 걷은 이전 작업 라벨 CSS 가 되살아남(결정 MX4 위반 — 주석에도 다시 적지 않는다)"
  fi
  if grep -qF -- 'TIER1_PREVIOUS_TASK_LABEL' "$hub_template_file"; then
    note_failure "T25-88: hub_template.html 에 걷은 이전 작업 라벨 상수가 되살아남(결정 MX4 위반 — 주석에도 다시 적지 않는다)"
  fi
  if grep -qF -- '.card[data-tier1-' "$hub_template_file"; then
    note_failure "T25-88: hub_template.html 에 카드의 톤다운 스코프 셀렉터가 되살아남(결정 MX4 위반 — 카드에는 프로젝트 단위 진행률이 없다)"
  fi
  if grep -qE '\.detail-note\{[^}]*#[0-9a-fA-F]{3}' "$hub_template_file"; then
    record_failure "$test_name" "T25-88: .detail-note 에 하드코딩된 # 색 리터럴이 있음(G9)"
    return 1
  fi

  # T25-89(GN6·GN7 패널 안내 + IIFE 분리, G8 — 가장 값진 기계적 검사): 안내 줄 노드·속성
  # 읽기·머리 주석 편입이 존재하고, 패널 IIFE(var PANEL_OPEN_BODY_CLASS 줄 ~ 파일 끝)에
  # snapshot 문자열이 0건이다 — 렌더 IIFE 와의 분리(결정 SP1)가 이번 기능으로도 깨지지
  # 않았음을 검사한다. panelFrameEl.src 회귀 금지는 T25-80 이 이미 지킨다.
  local gn6_note_token
  for gn6_note_token in 'id="dzh-detail-note"' 'TIER1_PREVIOUS_TASK_ATTRIBUTE' '#dzh-detail-note'; do
    if ! grep -qF -- "$gn6_note_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-89: hub_template.html 에 $gn6_note_token 이 없음"
      return 1
    fi
  done
  local panel_iife_start_line
  panel_iife_start_line=$(grep -n 'var PANEL_OPEN_BODY_CLASS' "$hub_template_file" | head -1 | cut -d: -f1)
  if [[ -z "$panel_iife_start_line" ]]; then
    record_failure "$test_name" "T25-89: hub_template.html 에 var PANEL_OPEN_BODY_CLASS 를 찾지 못함"
    return 1
  fi
  local snapshot_leak_count
  snapshot_leak_count=$(tail -n "+$panel_iife_start_line" "$hub_template_file" | grep -c "snapshot")
  if [[ "$snapshot_leak_count" -ne 0 ]]; then
    record_failure "$test_name" "T25-89: 패널 IIFE 범위에 snapshot 문자열이 ${snapshot_leak_count}건 있음(G8 위반)"
    return 1
  fi

  # T25-90(문서 정합 R2·R3, docs/prps/hub-session-revival-and-stale-tier1.md): README 가
  # 이전 작업 라벨·구세대 산출물 처리(읽지 않음·리텐션)·재부착 규칙을 설명한다. 역방향 — 옛 단정 문구
  # "— CSS 가 숨긴다"가 hub/README.md 에서 사라졌다(결정 LG1 이 교정한다). 세 번째 토큰은
  # 검수 1회차 F8 이 옛 `/dashboard init` 커맨드 표기를 기록기 표기로 바꾸며 함께
  # 재조준됐다(문서 동기화 대상 자체는 그대로, 부르는 이름만 바뀌었다).
  local doc_sync_token
  for doc_sync_token in '이전 작업' '구세대' '기록기 `init`'; do
    if ! grep -qF -- "$doc_sync_token" "$hub_readme_file"; then
      note_failure "T25-90: hub/README.md 에 $doc_sync_token 토큰이 없음"
    fi
  done
  if ! grep -qF -- '재부착' "$hub_dashboard_prp_file"; then
    note_failure "T25-90: docs/prps/hub-dashboard.md 에 재부착 토큰이 없음"
  fi
  if grep -qF -- '— CSS 가 숨긴다' "$hub_readme_file"; then
    note_failure "T25-90: hub/README.md 에 옛 단정 문구(— CSS 가 숨긴다)가 남아 있음(LG1)"
  fi

  # T25-91(ZG1·ZG2 상수·술어 계약 + 선언 순서, GOTCHA 1·2, docs/prps/hub-zombie-subagent-guard.md):
  # SUBAGENT_ZOMBIE_AFTER_MS 상수와 is_running_subagent 술어가 존재하고, 선언 순서가
  # 상수 < is_running_subagent < _compute_base_state 다(기본 인자 평가 시점 NameError 회피,
  # 선례: T25-87 의 줄 번호 비교). 역방향(핵심, G8) — 옛 무조건 판정이 소스에서 사라졌다.
  if ! grep -qF 'SUBAGENT_ZOMBIE_AFTER_MS = 90 * 60 * 1000' "$hub_session_file"; then
    note_failure "T25-91: hub_session.py 에 SUBAGENT_ZOMBIE_AFTER_MS = 90 * 60 * 1000 이 없음"
  fi
  if ! grep -qF 'def is_running_subagent(' "$hub_session_file"; then
    note_failure "T25-91: hub_session.py 에 def is_running_subagent( 이 없음"
  fi
  if grep -qF 'sub.ended_at_ms is None for sub in facts.subagents' "$hub_session_file"; then
    record_failure "$test_name" "T25-91 역방향: hub_session.py 에 옛 무조건 판정이 남아 있음(G8 위반)"
    return 1
  fi
  local zombie_const_line is_running_subagent_def_line compute_base_state_def_line
  zombie_const_line=$(grep -n '^SUBAGENT_ZOMBIE_AFTER_MS = 90 \* 60 \* 1000' "$hub_session_file" | head -1 | cut -d: -f1)
  is_running_subagent_def_line=$(grep -n '^def is_running_subagent(' "$hub_session_file" | head -1 | cut -d: -f1)
  compute_base_state_def_line=$(grep -n '^def _compute_base_state(' "$hub_session_file" | head -1 | cut -d: -f1)
  if [[ -z "$zombie_const_line" || -z "$is_running_subagent_def_line" || -z "$compute_base_state_def_line" \
      || "$zombie_const_line" -ge "$is_running_subagent_def_line" \
      || "$is_running_subagent_def_line" -ge "$compute_base_state_def_line" ]]; then
    record_failure "$test_name" "T25-91: 선언 순서가 상수 < is_running_subagent < _compute_base_state 가 아님(GOTCHA 1)"
    return 1
  fi

  # T25-92(ZG5 단일 판정자, G4 — 가장 값진 기계적 검사): _compute_base_state 와
  # summarize_agent_runs 두 함수 본문 모두에 is_running_subagent( 호출이 1건 이상이다
  # (GOTCHA 4 — 한쪽만 고치면 카드와 칩이 모순된다). 역방향: summarize_agent_runs 범위 안에
  # ended_at_ms is None 직접 비교가 0건이다. 결정 AR4(docs/prps/
  # hub-agent-runs-and-prompt-source.md)로 1:1 투영이 됐지만 한 함수 안에 그대로 인라인돼
  # 있다. summarize_agent_runs 는 지금 파일의 마지막 top-level 함수라 종료 앵커 없이도
  # EOF 까지 추출한 범위가 우연히 본문과 일치했었다 — 재검수 1회차 M5로 그 우연에 기대지
  # 않게 `flag && /^def /{exit}` 를 되살렸다(뒤에 새 함수가 붙으면 그 본문까지 섞여 들어와
  # GOTCHA 4 위반을 놓칠 수 있었다).
  local base_state_body summarize_agent_runs_body
  base_state_body=$(awk '/^def _compute_base_state\(/{flag=1; next} flag && /^def compute_session_view\(/{exit} flag{print}' "$hub_session_file")
  summarize_agent_runs_body=$(awk '/^def summarize_agent_runs\(/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_session_file")
  if [[ "$(echo "$base_state_body" | grep -c 'is_running_subagent(')" -eq 0 ]]; then
    note_failure "T25-92: _compute_base_state 본문에 is_running_subagent( 호출이 없음(GOTCHA 4)"
  fi
  if [[ "$(echo "$summarize_agent_runs_body" | grep -c 'is_running_subagent(')" -eq 0 ]]; then
    note_failure "T25-92: summarize_agent_runs 본문에 is_running_subagent( 호출이 없음(GOTCHA 4)"
  fi
  if [[ "$(echo "$summarize_agent_runs_body" | grep -c 'ended_at_ms is None')" -ne 0 ]]; then
    record_failure "$test_name" "T25-92 역방향: summarize_agent_runs 범위 안에 ended_at_ms is None 직접 비교가 남아 있음"
    return 1
  fi

  # T25-93(ZG3 시그니처 + 기존 계약 공존, GOTCHA 3): compute_session_view·summarize_agent_runs
  # 두 시그니처 모두에 zombie_after_ms: int = SUBAGENT_ZOMBIE_AFTER_MS 기본 인자가 있다.
  # 역방향(회귀 방지) — T25-52 가 요구하는 정렬 키 리터럴(결정 AR4·AR5 로 run.is_running 직접
  # 참조 형태로 개정)이 남아 있고, hub_template.html 의 run.is_running 참조가 4건이다(G7 —
  # 템플릿은 서버가 판정한 값을 읽기만 하고 자기 판정을 만들지 않는다). 옛 값은 4 였다: 실행 줄
  # 렌더가 툴팁 문구·강조 클래스·글리프 분기·보조기술 텍스트 넷에서 읽었는데, 결정 MX10
  # (docs/prps/hub-session-modal-cleanup.md §10.1)이 글리프 분기를 걷어 셋이 됐다. 결정 LA9
  # (docs/prps/hub-live-activity.md)가 활동 줄·행 툴팁 줄의 공용 게이트 runningActivityOf 에서
  # 한 번 더 읽어 넷이 됐다(새 참조는 그 한 곳뿐이다 — 활동 줄과 툴팁 줄이 각자 읽으면 다섯).
  local zombie_default_arg_count
  zombie_default_arg_count=$(grep -cF 'zombie_after_ms: int = SUBAGENT_ZOMBIE_AFTER_MS' "$hub_session_file")
  if [[ "$zombie_default_arg_count" -ne 2 ]]; then
    note_failure "T25-93: zombie_after_ms 기본 인자 선언 수=$zombie_default_arg_count (기대: 2 — compute_session_view·summarize_agent_runs)"
  fi
  if ! grep -qF '0 if run.is_running else 1' "$hub_session_file"; then
    record_failure "$test_name" "T25-93 역방향: hub_session.py 에 0 if run.is_running else 1 이 없음(T25-52 회귀, GOTCHA 3)"
    return 1
  fi
  local run_is_running_count
  run_is_running_count=$(grep -cF 'run.is_running' "$hub_template_file")
  if [[ "$run_is_running_count" -ne 4 ]]; then
    record_failure "$test_name" "T25-93: hub_template.html 의 run.is_running 참조 수=$run_is_running_count (기대: 4 — 툴팁 문구·강조 클래스·보조기술 텍스트·활동 게이트, G7 위반 또는 글리프 분기 부활)"
    return 1
  fi

  # T25-94(문서 정합 ZG7): README·hub-dashboard.md·hub-session-revival-and-stale-tier1.md 가
  # 좀비 가드를 서로 참조한다. 기계적(개정 관례 강제, GOTCHA 10) — hub-dashboard.md 의 원문
  # 코드블록 줄이 여전히 존재한다(개정 화살표로 원문을 덮어쓰면 실패). 역방향 — hub/README.md
  # 의 옛 단정 문구는 여전히 없다(T25-90 승계 확인).
  local zg7_doc_token
  for zg7_doc_token in '좀비' '90분'; do
    if ! grep -qF -- "$zg7_doc_token" "$hub_readme_file"; then
      note_failure "T25-94: hub/README.md 에 $zg7_doc_token 토큰이 없음"
    fi
  done
  if ! grep -qF -- 'hub-zombie-subagent-guard' "$hub_dashboard_prp_file"; then
    note_failure "T25-94: docs/prps/hub-dashboard.md 에 hub-zombie-subagent-guard 참조가 없음"
  fi
  if ! grep -qF -- 'hub-zombie-subagent-guard' "$hub_session_revival_prp_file"; then
    note_failure "T25-94: docs/prps/hub-session-revival-and-stale-tier1.md 에 hub-zombie-subagent-guard 참조가 없음"
  fi
  if ! grep -qF -- '2. turn_state == "running" 또는 살아 있는 서브에이전트 존재' "$hub_dashboard_prp_file"; then
    note_failure "T25-94: docs/prps/hub-dashboard.md 의 규칙 2 원문 줄이 사라짐(개정 관례 위반, GOTCHA 10)"
  fi
  if grep -qF -- '— CSS 가 숨긴다' "$hub_readme_file"; then
    record_failure "$test_name" "T25-94: hub/README.md 에 옛 단정 문구(— CSS 가 숨긴다)가 남아 있음(T25-90 승계 확인)"
    return 1
  fi

  # T25-95(PV1 패널 표면, docs/prps/hub-panel-polish-and-icons.md 결정 PV1, G1): .detail-panel
  # 은 --bg 배경이고 .detail-head 에는 배경·테두리 선언이 없다 — SP11 이 구분선을 지운 판단을
  # 유지한 채 헤드-카드 위계를 표면 색으로 세운다. CSS 선언이 여러 줄에 걸쳐 있어 첫 '}' 까지를
  # 그 규칙의 전문으로 본다(CSS 는 중첩 중괄호를 쓰지 않는다).
  local detail_panel_rule detail_head_rule
  detail_panel_rule=$(sed -n '/\.detail-panel{/,/}/p' "$hub_template_file" | awk '{print} /}/{exit}')
  if ! echo "$detail_panel_rule" | grep -qF 'background:var(--bg)'; then
    note_failure "T25-95: .detail-panel 규칙에 background:var(--bg) 가 없음"
  fi
  if echo "$detail_panel_rule" | grep -qF 'background:var(--surface)'; then
    record_failure "$test_name" "T25-95: .detail-panel 규칙에 옛 background:var(--surface) 가 남아 있음"
    return 1
  fi
  detail_head_rule=$(sed -n '/\.detail-head{/,/}/p' "$hub_template_file" | awk '{print} /}/{exit}')
  if [[ -z "$detail_head_rule" ]] || echo "$detail_head_rule" | grep -qE 'background|border'; then
    record_failure "$test_name" "T25-95: .detail-head 규칙에 background 또는 border 선언이 있음(PV1 위반)"
    return 1
  fi

  # T25-96(PV3·PV4 헤더 높이 고정, G3·G4): 안내 줄 자리는 항상 예약되고 한 줄로 잘린다.
  # hidden 속성 토글은 사라졌다 — visibility 클래스 토글만 남는다.
  local detail_note_markup detail_note_rule
  detail_note_markup=$(sed -n '/<p id="dzh-detail-note"/,/>/p' "$hub_template_file")
  if [[ -z "$detail_note_markup" ]]; then
    note_failure "T25-96: hub_template.html 에 <p id=\"dzh-detail-note\" 마크업을 찾지 못함"
  fi
  if ! echo "$detail_note_markup" | grep -qF 'data-tooltip='; then
    note_failure "T25-96: dzh-detail-note 마크업에 data-tooltip= 이 없음"
  fi
  if echo "$detail_note_markup" | grep -qF 'hidden'; then
    record_failure "$test_name" "T25-96: dzh-detail-note 마크업에 hidden 속성이 남아 있음"
    return 1
  fi
  detail_note_rule=$(sed -n '/\.detail-note{/,/}/p' "$hub_template_file" | awk '{print} /}/{exit}')
  local detail_note_rule_token
  for detail_note_rule_token in 'white-space:nowrap' 'visibility:hidden' 'line-height:16px'; do
    if ! echo "$detail_note_rule" | grep -qF -- "$detail_note_rule_token"; then
      note_failure "T25-96: .detail-note 규칙에 $detail_note_rule_token 이 없음"
    fi
  done
  if ! grep -qF -- 'detail-note-visible' "$hub_template_file"; then
    note_failure "T25-96: hub_template.html 에 detail-note-visible 클래스가 없음"
  fi
  if grep -qF -- 'panelNoteEl.hidden' "$hub_template_file"; then
    note_failure "T25-96: hub_template.html 에 panelNoteEl.hidden 대입이 남아 있음"
  fi
  if grep -qF -- 'DETAIL_NOTE_TEXT' "$hub_template_file"; then
    record_failure "$test_name" "T25-96: hub_template.html 에 DETAIL_NOTE_TEXT 상수가 남아 있음"
    return 1
  fi

  # T25-97(PV6~PV8 회전, G5·G6): 회전 키프레임·규칙·저감 무효화가 세트로 있고, 무효화가
  # 소스 순서상 뒤에 온다(선례: T25-79·T25-91 의 줄 번호 비교). 회전 시간은 CSS 에만 산다 —
  # 회전 IIFE 범위에 setTimeout( 이 0건이어야 한다(animationend 로 해제, PV7).
  local rotation_token
  for rotation_token in '@keyframes dzh-refresh-spin' '.refresh-btn.refresh-spinning svg{animation:' \
      'animationend'; do
    if ! grep -qF -- "$rotation_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-97: hub_template.html 에 $rotation_token 이 없음"
      return 1
    fi
  done
  local spin_rule_line spin_reduce_line
  spin_rule_line=$(grep -n '\.refresh-btn\.refresh-spinning svg{animation:' "$hub_template_file" | head -1 | cut -d: -f1)
  spin_reduce_line=$(grep -n 'prefers-reduced-motion' "$hub_template_file" | while IFS=: read -r n _; do
    sed -n "${n}p" "$hub_template_file" | grep -q 'refresh-spinning' && echo "$n"; done | head -1)
  if [[ -z "$spin_rule_line" || -z "$spin_reduce_line" || "$spin_reduce_line" -le "$spin_rule_line" ]]; then
    record_failure "$test_name" "T25-97: prefers-reduced-motion 의 refresh-spinning 무효화가 회전 규칙보다 앞에 있거나 없음"
    return 1
  fi
  local refresh_iife_start_line refresh_iife_body
  refresh_iife_start_line=$(grep -n 'var REFRESH_SPIN_CLASS' "$hub_template_file" | head -1 | cut -d: -f1)
  if [[ -z "$refresh_iife_start_line" ]]; then
    record_failure "$test_name" "T25-97: hub_template.html 에 var REFRESH_SPIN_CLASS 를 찾지 못함"
    return 1
  fi
  refresh_iife_body=$(tail -n "+$refresh_iife_start_line" "$hub_template_file" | awk '{print} /^}\)\(\);$/{exit}')
  if echo "$refresh_iife_body" | grep -qF 'setTimeout('; then
    record_failure "$test_name" "T25-97: 회전 IIFE 범위에 setTimeout( 이 남아 있음(PV7 위반)"
    return 1
  fi

  # T25-98(PV9~PV12 아이콘, G7): 남은 유니코드 글리프 3종이 lucide 인라인 SVG 로 바뀌었고,
  # CDN·런타임 로더 흔적이 없다.
  local icon_token
  for icon_token in 'class="theme-icon-moon"' 'class="theme-icon-sun"' 'DRAG_HANDLE_ICON_SVG' \
      '.card-drag-handle svg{' '.detail-close svg{' 'lucide'; do
    if ! grep -qF -- "$icon_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-98: hub_template.html 에 $icon_token 이 없음"
      return 1
    fi
  done
  local removed_icon_token
  for removed_icon_token in '>☾<' '☀' '>≡<' '>»<' 'THEME_GLYPH' 'cdn.' 'unpkg' 'createIcons'; do
    if grep -qF -- "$removed_icon_token" "$hub_template_file"; then
      note_failure "T25-98: hub_template.html 에 옛 글리프·CDN 잔재($removed_icon_token)가 남아 있음"
    fi
  done

  # T25-99(문서·주석 정합, G8): hub/README.md 의 아이콘 서술이 화면과 일치하고, 머리 주석의
  # 안내 줄 계약이 개정됐다(결정 PV5).
  if ! grep -qF -- '아이콘' "$hub_readme_file"; then
    record_failure "$test_name" "T25-99: hub/README.md 에 아이콘 서술이 없음"
    return 1
  fi
  local readme_removed_glyph_token
  for readme_removed_glyph_token in '☾' '≡'; do
    if grep -qF -- "$readme_removed_glyph_token" "$hub_readme_file"; then
      record_failure "$test_name" "T25-99: hub/README.md 에 옛 글리프($readme_removed_glyph_token)가 남아 있음"
      return 1
    fi
  done
  local head_comment_body
  head_comment_body=$(sed -n '/^<!--$/,/^-->$/p' "$hub_template_file")
  if ! echo "$head_comment_body" | grep -qF -- 'detail-note-visible'; then
    note_failure "T25-99: hub_template.html 머리 주석에 detail-note-visible 이 없음"
  fi
  if echo "$head_comment_body" | grep -qF -- 'hidden·textContent 만 바뀐다'; then
    record_failure "$test_name" "T25-99: hub_template.html 머리 주석에 옛 계약 문구(hidden·textContent 만 바뀐다)가 남아 있음"
    return 1
  fi

  # T25-100(MS1 파일 존재·크기, docs/prps/hub-model-module-split.md 결정 MS1): 분리된 3개
  # 파일이 존재하고, hub/bin/*.py 전부가 800줄 이하다(파일 800줄 상한이 이 분리의 이유였다).
  local ms1_split_file
  for ms1_split_file in "$hub_session_file" "$hub_project_file" "$hub_server_state_file"; do
    if [[ ! -f "$ms1_split_file" ]]; then
      record_failure "$test_name" "T25-100: $ms1_split_file 이 존재하지 않음"
      return 1
    fi
  done
  local py_source_file py_line_count
  for py_source_file in "$REPO_ROOT"/hub/bin/*.py; do
    py_line_count=$(wc -l < "$py_source_file" | tr -d ' ')
    if [[ "$py_line_count" -gt 800 ]]; then
      note_failure "T25-100: $py_source_file 이 800줄을 넘음($py_line_count 줄)"
    fi
  done

  # T25-101(MS2 파사드 부재, 결정 MS2 — 파사드를 만들지 않는다): hub_model.py 에 와일드카드
  # 재노출이나 이동한 심볼의 재정의가 없다.
  if grep -qE '^from hub_(session|project|server_state) import \*' "$hub_model_file"; then
    record_failure "$test_name" "T25-101: hub_model.py 에 와일드카드 재노출이 있음(MS2 위반)"
    return 1
  fi
  local relocated_symbol_def
  for relocated_symbol_def in 'def compute_session_view(' 'def summarize_agent_runs(' \
      'def compose_project_views(' 'def is_server_alive(' 'def should_spawn_collect(' \
      'def parse_server_record('; do
    if grep -qF -- "$relocated_symbol_def" "$hub_model_file"; then
      note_failure "T25-101: hub_model.py 에 이동한 심볼의 정의($relocated_symbol_def)가 남아 있음(MS2 위반)"
    fi
  done

  # T25-102(MS4 순환·잎 계약, 결정 MS4): hub_server_state.py 는 어떤 허브 모듈도 임포트하지
  # 않는 잎이고, hub_session.py 는 hub_project 를 임포트하지 않는다(관측 1 — 섹션 5~6 만
  # hub_project 로 간다). 역방향 — hub_project.py 가 hub_model 을 임포트하면 안 된다
  # (간선 방향이 반대로 뒤집힌다).
  if grep -qE '^(import|from) hub_' "$hub_server_state_file"; then
    note_failure "T25-102: hub_server_state.py 가 다른 허브 모듈을 임포트함(잎 모듈 계약 위반)"
  fi
  if grep -qE '^(import|from) hub_project' "$hub_session_file"; then
    note_failure "T25-102: hub_session.py 가 hub_project 를 임포트함(의존 방향 위반)"
  fi
  if grep -qE '^import hub_model' "$hub_project_file"; then
    record_failure "$test_name" "T25-102 역방향: hub_project.py 가 hub_model 을 임포트함(역방향 간선 금지)"
    return 1
  fi

  # T25-103(MS9 테스트 1:1, 결정 MS9): 소스 1개 ↔ 테스트 1개 관례가 분리된 3개 모듈로
  # 확장됐다. 역방향 — 이관된 테스트 클래스가 test_hub_model.py 에 잔류하면 회귀다.
  local ms9_test_file
  for ms9_test_file in "$REPO_ROOT/tests/hub/test_hub_session.py" \
      "$REPO_ROOT/tests/hub/test_hub_project.py" \
      "$REPO_ROOT/tests/hub/test_hub_server_state.py"; do
    if [[ ! -f "$ms9_test_file" ]]; then
      record_failure "$test_name" "T25-103: $ms9_test_file 이 존재하지 않음"
      return 1
    fi
  done
  local relocated_test_class hub_model_test_file
  hub_model_test_file="$REPO_ROOT/tests/hub/test_hub_model.py"
  for relocated_test_class in "class SubagentZombieGuardTest" "class ComposeProjectViewsTest" \
      "class ParseServerRecordTest"; do
    if grep -qF -- "$relocated_test_class" "$hub_model_test_file"; then
      note_failure "T25-103: test_hub_model.py 에 이관된 테스트 클래스($relocated_test_class)가 잔류함"
    fi
  done

  # T25-104(문서 정합, 결정 MS10 — 갱신: docs/prps/hub-tier1-clamp-fix-and-session-model.md 가
  # hub_transcript.py 를 더해 15 → 16 으로, docs/prps/hub-workflow-visibility.md 1회차가
  # hub_redact.py·hub_workflow.py 를 더해 16 → 18 로, 2회차가 hub_workflow_read.py 를 더해
  # 18 → 19 로, docs/prps/hub-collect-split-for-merge.md 가 hub_config.py·hub_atomic_write.py
  # 를 더해 19 → 21 로, docs/prps/hub-agent-runs-and-prompt-source.md 가 hub_subagent.py·
  # hub_subagent_read.py 를 더해 21 → 23 로, docs/prps/hub-live-session-native-source.md 가
  # hub_live_session.py·hub_live_session_read.py 를 더해 23 → 25 로 다시 바꿨다, docs/prps/
  # hub-subagent-liveness-signal.md §11 R4 가 예견한 후속 분리(결정 MS1 의 기존 절차)가
  # hub_server_state_read.py 를 더해 25 → 26 으로, docs/prps/dashboard-into-hub.md M1(HD1)이
  # hub_dashboard_log.py·hub_dashboard_render.py·hub_dashboard_template.html 을 더해
  # 26 → 29 로, docs/prps/hub-subagent-background-pause.md 결정 BW11(M1) 이 hub_session.py 를
  # 분리해 나온 hub_session_facts.py 를 더해 29 → 30 으로, docs/prps/hub-usage-panel-account.md
  # 결정 AC8 이 hub_account.py 를 더해 30 → 31 로, docs/prps/hub-live-activity.md 결정 LA14 가
  # hub_activity.py 를 더해 31 → 32 로, docs/prps/harness-benchmark-adoption.md ⑨ 가
  # hub_session_cost.py 를 더해 32 → 33 으로, docs/prps/harness-versioning.md 단계 B 가
  # hub_release.py·hub_release_read.py 를 더해 33 → 35 로 다시 바꿨다, T25-149 참조):
  # hub/README.md 가 35개 파일을 고지하고, hub-dashboard.md 모듈 구성표가 hub_session.py·
  # hub_session_facts.py·hub_live_session.py 를 안다. 역방향 — 옛 "12개 파일" 고지가 남아
  # 있으면 안 된다.
  if ! grep -qF "35개 파일" "$hub_readme_file"; then
    note_failure "T25-104: hub/README.md 에 35개 파일 고지가 없음"
  fi
  if grep -qF "33개 파일" "$hub_readme_file"; then
    note_failure "T25-104: hub/README.md 에 옛 33개 파일 고지가 남아 있음"
  fi
  if grep -qF "32개 파일" "$hub_readme_file"; then
    note_failure "T25-104: hub/README.md 에 옛 32개 파일 고지가 남아 있음"
  fi
  if grep -qF "31개 파일" "$hub_readme_file"; then
    note_failure "T25-104: hub/README.md 에 옛 31개 파일 고지가 남아 있음"
  fi
  if grep -qF "30개 파일" "$hub_readme_file"; then
    note_failure "T25-104: hub/README.md 에 옛 30개 파일 고지가 남아 있음"
  fi
  if grep -qF "12개 파일" "$hub_readme_file"; then
    note_failure "T25-104: hub/README.md 에 옛 12개 파일 고지가 남아 있음"
  fi
  if ! grep -qF "hub_session.py" "$hub_dashboard_prp_file"; then
    record_failure "$test_name" "T25-104: docs/prps/hub-dashboard.md 모듈 구성표에 hub_session.py 가 없음"
    return 1
  fi
  if ! grep -qF "hub_session_facts.py" "$hub_dashboard_prp_file"; then
    record_failure "$test_name" "T25-104: docs/prps/hub-dashboard.md 모듈 구성표에 hub_session_facts.py 가 없음"
    return 1
  fi
  if ! grep -qF "hub_live_session.py" "$hub_readme_file"; then
    note_failure "T25-104: hub/README.md 파일 배치에 hub_live_session.py 가 없음"
  fi
  if ! grep -qF "hub_live_session.py" "$hub_dashboard_prp_file"; then
    note_failure "T25-104: docs/prps/hub-dashboard.md 모듈 구성표에 hub_live_session.py 가 없음"
  fi

  # T25-105(hub-panel-empty-state-and-open-card.md 결정 OC4·OC5, G1·G2·G3; 재조준 — 카드 상세보기 정리
  # M3, 결정 MX1, docs/prps/hub-session-modal-cleanup.md §10.1): 대시보드가 없는 세션도 사유 속성을 실어
  # 패널로 넘기고, 그 사유의 단일 출처는 세션 사유 함수(sessionPanelEmptyReason)다 — 프로젝트 요약을
  # 여는 요소(모달 루트)가 패널 속성을 잃어 프로젝트판 사유 함수는 사라졌다. 역방향 — 옛 단일 속성
  # 셀렉터·패널 IIFE 안 티어 문구 복제·상태 클래스 없는 무조건 iframe 숨김이 없다.
  local oc4_oc5_token
  for oc4_oc5_token in 'PANEL_EMPTY_REASON_ATTRIBUTE' \
      'function sessionPanelEmptyReason(' '.detail-panel.detail-empty .detail-frame{display:none}' \
      '.detail-panel.detail-empty .detail-empty-reason{display:block}' 'id="dzh-detail-empty-reason"'; do
    if ! grep -qF -- "$oc4_oc5_token" "$hub_template_file"; then
      note_failure "T25-105: hub_template.html 에 $oc4_oc5_token 이 없음"
    fi
  done
  # 불변식 OC-A(키 부재 ⇔ 사유 존재)의 강제 지점은 무조건 else 다 — else if 로 좁혀지면
  # 이 리터럴 줄 자체가 사라진다(속성 이름만 보는 substring 검사로는 조건부화를 못 잡는다).
  # M3 뒤 이 강제 지점은 sessionRowAttributes() 하나뿐이다(옛 projectPanelAttributes() 갈래는 루트가
  # 패널 속성을 잃으며 사라졌다). 예전에는 같은 리터럴 줄이 두 함수에 있어 전체 파일 검사가 한쪽만
  # 지워도 다른 쪽 한 건으로 조용히 통과했고, tests/mutations.tsv 의 mutation_sed_is_write_safe 가 줄
  # 번호 주소를 받지 않아 변조행이 대상을 좁힐 수도 없었다(2026-09-24 구현 단계 개정 — 그때 지역
  # 변수명을 갈랐다). 지금은 리터럴이 파일 전체에서 유일하지만 본문 한정 추출은 방어적으로 그대로
  # 둔다(같은 줄이 다른 함수에 다시 생겨도 이 검사가 엉뚱한 함수의 매치로 속지 않는다).
  local session_row_attrs_body_105
  session_row_attrs_body_105=$(sed -n '/function sessionRowAttributes(project, session){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$session_row_attrs_body_105" ]]; then
    record_failure "$test_name" "T25-105: sessionRowAttributes() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF -- "else attrs += ' data-panel-empty-reason=\"' + escapeHtml(emptyReason) + '\"';" \
      <<< "$session_row_attrs_body_105"; then
    note_failure "T25-105: data-panel-empty-reason 부여가 무조건 else 가 아님(불변식 OC-A 위반)"
  fi
  if grep -qF -- "CLICKABLE_CARD_SELECTOR = '[' + DASHBOARD_KEY_ATTRIBUTE + ']';" "$hub_template_file"; then
    record_failure "$test_name" "T25-105: hub_template.html 에 옛 단일 속성 셀렉터가 남아 있음(결정 OC5 회귀)"
    return 1
  fi
  local panel_iife_start_line_105 tier_text_leak_count
  panel_iife_start_line_105=$(grep -n 'var PANEL_OPEN_BODY_CLASS' "$hub_template_file" | head -1 | cut -d: -f1)
  if [[ -z "$panel_iife_start_line_105" ]]; then
    record_failure "$test_name" "T25-105: hub_template.html 에 var PANEL_OPEN_BODY_CLASS 를 찾지 못함"
    return 1
  fi
  tier_text_leak_count=$(tail -n "+$panel_iife_start_line_105" "$hub_template_file" \
                           | grep -c '세션 활동은 있지만\|파일시스템에서만')
  if [[ "$tier_text_leak_count" -ne 0 ]]; then
    record_failure "$test_name" "T25-105: 패널 IIFE 범위에 티어 문구가 ${tier_text_leak_count}건 복제돼 있음(G3 위반)"
    return 1
  fi
  # 무조건 숨김("상태 클래스 없는 .detail-frame{display:none}")으로의 회귀를 잡는다 — 부분
  # 문자열로는 스코프가 붙은 정상 규칙과 구분되지 않으므로, "좁은 패턴 등장 횟수"와 "스코프가
  # 붙은 전체 패턴 등장 횟수"가 같은지를 비교한다(다르면 스코프 없는 규칙이 별도로 존재한다).
  local unscoped_frame_hide_count scoped_frame_hide_count
  unscoped_frame_hide_count=$(grep -o '\.detail-frame{display:none}' "$hub_template_file" | wc -l | tr -d ' ')
  scoped_frame_hide_count=$(grep -o '\.detail-panel\.detail-empty \.detail-frame{display:none}' \
                              "$hub_template_file" | wc -l | tr -d ' ')
  if [[ "$unscoped_frame_hide_count" != "$scoped_frame_hide_count" ]]; then
    record_failure "$test_name" "T25-105: .detail-frame{display:none} 가 detail-empty 스코프 없이 존재함"
    return 1
  fi

  # T25-106(결정 OC1 신원 키 교체, G4): 패널의 신원이 dashboardKey 가 아니라 projectPath 다.
  # 역방향 — 옛 진실(openDashboardKey)이 주석을 포함해 파일 전체에 남아 있지 않다.
  local oc1_token
  for oc1_token in 'openPanelTarget' 'PROJECT_PATH_ATTRIBUTE' 'isSameDocument' 'function readCardTarget('; do
    if ! grep -qF -- "$oc1_token" "$hub_template_file"; then
      note_failure "T25-106: hub_template.html 에 $oc1_token 이 없음"
    fi
  done
  if grep -qF -- 'openDashboardKey' "$hub_template_file"; then
    record_failure "$test_name" "T25-106: hub_template.html 에 옛 신원 키(openDashboardKey)가 남아 있음"
    return 1
  fi

  # T25-107(결정 OC8 재적용 경로, G6·G7·G8 — 가장 값진 기계적 검사, M1 개정 — docs/prps/
  # hub-session-modal-and-partial-update.md 결정 PU1·PU6, M2 보강 — 같은 문서 결정 SC3):
  # dzh:rendered 가 정확히 2회(발행·수신) 있고, 발행 지점이 DOM 최종 확정
  # (reconcileChildren(app, appContentHtml())) 뒤·모달 갱신(renderSessionModal(); 호출 줄)
  # 뒤·패널 IIFE 시작 앞이다 — 모달 본문이 갱신되기 전에 표시 복원 이벤트가 나가면 모달 쪽
  # 선택 표시가 한 틱 묵은 채로 남는다. 역방향 — new MutationObserver 등장 횟수가 여전히
  # 2(툴팁 전용, 옵저버 회귀 금지).
  local oc8_token
  for oc8_token in 'function applyOpenCardMarking(' 'RENDERED_EVENT_NAME'; do
    if ! grep -qF -- "$oc8_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-107: hub_template.html 에 $oc8_token 이 없음"
      return 1
    fi
  done
  local rendered_event_count observer_count dom_final_line_107 modal_render_line_107 dispatch_line_107 panel_iife_start_line_107
  rendered_event_count=$(grep -c "dzh:rendered" "$hub_template_file")
  observer_count=$(grep -c 'new MutationObserver' "$hub_template_file")
  dom_final_line_107=$(grep -n "reconcileChildren(app, appContentHtml());" "$hub_template_file" | head -1 | cut -d: -f1)
  modal_render_line_107=$(grep -n 'renderSessionModal();' "$hub_template_file" | head -1 | cut -d: -f1)
  dispatch_line_107=$(grep -n 'dispatchEvent(new Event(RENDERED_EVENT_NAME))' "$hub_template_file" | head -1 | cut -d: -f1)
  panel_iife_start_line_107=$(grep -n 'var PANEL_OPEN_BODY_CLASS' "$hub_template_file" | head -1 | cut -d: -f1)
  if [[ "$rendered_event_count" -ne 2 || "$observer_count" -ne 2 \
      || -z "$dispatch_line_107" || -z "$dom_final_line_107" || -z "$modal_render_line_107" \
      || -z "$panel_iife_start_line_107" \
      || "$dispatch_line_107" -le "$dom_final_line_107" \
      || "$dispatch_line_107" -le "$modal_render_line_107" \
      || "$dispatch_line_107" -ge "$panel_iife_start_line_107" ]]; then
    record_failure "$test_name" "T25-107: dzh:rendered(${rendered_event_count})·MutationObserver(${observer_count}) 개수 또는 발행 위치가 어긋남"
    return 1
  fi

  # T25-108(결정 OC9·OC11 표시 채널, G5, M2 개정 — docs/prps/hub-session-modal-and-partial-update.md
  # 결정 SC4; 재개정 — 카드 상세보기 정리 M3, 결정 MX1·MX2·MX13, docs/prps/hub-session-modal-cleanup.md
  # §10.1): 열린 카드 표시(면색+aria-current)가 존재하고, 카드 커서는 모달을 여는 표지
  # (data-opens-session-modal)에 걸린다 — 보일 세션이 없어 모달을 열지 않는 카드는 pointer 가 아니다. 모달
  # 루트의 커서 규칙은 루트가 누를 수 없는 머리가 되며 사라졌다(그 부재는 T25-247 이 문다). 역방향 —
  # 새 규칙에 색 리터럴이 없고(T25-88 관례), 모든 카드에 pointer 를 거는 옛 커서 규칙·옛 단독 셀렉터·
  # 카드에 남은 두 속성 OR 커서 규칙이 되살아나지 않았다. 옛 <span> 분기 역검사(OC11 회귀)는 걷었다 —
  # 그 결정이 MX2 로 개정돼 span 이 다시 정당한 분기가 됐고, 올바른 분기는 T25-256 이 문다.
  local oc9_oc11_token
  for oc9_oc11_token in '.card.card-open{' 'card-open' 'OPEN_CARD_CLASS' 'aria-current'; do
    if ! grep -qF -- "$oc9_oc11_token" "$hub_template_file"; then
      record_failure "$test_name" "T25-108: hub_template.html 에 $oc9_oc11_token 이 없음"
      return 1
    fi
  done
  # 아래 줄은 반복문 밖의 고정 문구로 둔다(원장 판별자 자격, T37-13) — 반복문 메시지는
  # 변수를 보간해 소스에 리터럴로 나타나지 않는다.
  if ! grep -qF -- '.card[data-opens-session-modal]{cursor:pointer}' "$hub_template_file"; then
    record_failure "$test_name" "T25-108: 카드의 모달 여는 커서 규칙(.card[data-opens-session-modal]{cursor:pointer})이 없음(결정 MX2 위반)"
    return 1
  fi
  local card_open_rule
  card_open_rule=$(grep -oE '\.card\.card-open\{[^}]*\}' "$hub_template_file" | head -1)
  if [[ -z "$card_open_rule" ]] || echo "$card_open_rule" | grep -qE '#[0-9a-fA-F]{3}'; then
    note_failure "T25-108: .card.card-open 규칙에 하드코딩된 # 색 리터럴이 있거나 규칙을 찾지 못함(G9)"
  fi
  if grep -qF -- '.card[data-project-path]{cursor:pointer}' "$hub_template_file"; then
    note_failure "T25-108: hub_template.html 에 모든 카드에 pointer 를 거는 옛 커서 규칙이 남아 있음(결정 MX2 회귀 — 보일 세션이 없는 카드가 눌릴 것처럼 보인다)"
  fi
  if grep -qF -- '.card[data-dashboard-key]{cursor:pointer}' "$hub_template_file"; then
    note_failure "T25-108: hub_template.html 에 옛 단독 커서 셀렉터가 남아 있음(결정 OC5 회귀)"
  fi
  if grep -qF -- '.card[data-dashboard-key],.card[data-panel-empty-reason]{cursor:pointer}' "$hub_template_file"; then
    note_failure "T25-108: hub_template.html 카드에 두 속성 OR 커서 규칙이 남아 있음(결정 SC4 회귀 — 카드는 패널 속성을 갖지 않는다)"
  fi

  # T25-109(문서·주석 정합, G10; 재조준 — 카드 상세보기 정리 M3, 결정 MX2): README 와 머리 주석이 R2
  # 이후의 화면과 일치한다. README 는 「보일 세션이 있는 카드」만 카드 상세보기를 연다고 말한다(옛 「어느
  # 카드든」 토큰은 카드가 다 열지 않게 되며 사라졌다). 역방향 — 정본 이관 표기 누락으로 옛 결정이 살아
  # 있는 것처럼 읽히는 옛 문구가 남아 있지 않다(T25-81·T25-99 와 같은 관례). 첫 토큰은 반복문 밖의 고정
  # 문구로 둔다(원장 판별자 자격, T37-13 — 반복문 메시지는 변수를 보간해 소스에 리터럴로 나타나지 않는다).
  if ! grep -qF -- '보일 세션이 있는 카드' "$hub_readme_file"; then
    note_failure "T25-109: hub/README.md 에 보일 세션이 있는 카드 토큰이 없음(결정 MX2 위반 — 카드는 보일 세션이 있을 때만 모달을 연다는 서술이 없다)"
  fi
  local readme_oc_token
  for readme_oc_token in '사유' '배경색'; do
    if ! grep -qF -- "$readme_oc_token" "$hub_readme_file"; then
      note_failure "T25-109: hub/README.md 에 $readme_oc_token 토큰이 없음"
    fi
  done
  if grep -qF -- '클릭 대상이 아니다' "$hub_readme_file"; then
    record_failure "$test_name" "T25-109: hub/README.md 에 '클릭 대상이 아니다' 잔재가 남아 있음"
    return 1
  fi
  local head_comment_body_109
  head_comment_body_109=$(sed -n '/^<!--$/,/^-->$/p' "$hub_template_file")
  # 'dzh:rendered' 리터럴은 여기서 검사하지 않는다 — T25-107 이 그 문자열의 전체 등장 횟수를
  # 정확히 2(두 상수 선언)로 고정하므로, 머리 주석에 같은 리터럴을 한 번 더 쓰면 T25-107 이
  # 실패한다. 머리 주석은 "이벤트로 알린다"고 서술해 같은 사실을 리터럴 없이 전달한다.
  local head_comment_oc_token
  for head_comment_oc_token in 'data-panel-empty-reason' 'aria-current'; do
    if ! echo "$head_comment_body_109" | grep -qF -- "$head_comment_oc_token"; then
      note_failure "T25-109: hub_template.html 머리 주석에 $head_comment_oc_token 이 없음"
    fi
  done
  if echo "$head_comment_body_109" | grep -qF -- '카드에는 패널 열림 상태를 반영하지 않는다'; then
    note_failure "T25-109: hub_template.html 머리 주석에 옛 조항 ③(카드에는 패널 열림 상태를 반영하지 않는다)이 남아 있음"
  fi
  if grep -qF -- '프로젝트 대시보드 모달' "$hub_template_file"; then
    record_failure "$test_name" "T25-109: hub_template.html 에 '프로젝트 대시보드 모달' 잔재가 남아 있음"
    return 1
  fi

  # T25-110(라이트 테마 열린 카드 식별): 값이 아니라 **관계**를 고정한다. 열린 카드의 면색
  # (--accent-soft)은 두 요구를 동시에 만족해야 하고 둘은 서로 반대로 당긴다 — ①페이지 배경
  # (--bg)과 지각 가능하게 떨어질 만큼 어두워야 하고, ②카드 안 --muted 본문의 WCAG AA 를
  # 깨뜨릴 만큼 어두워선 안 된다. 한쪽만 보고 값을 고치면 다른 쪽이 조용히 깨지므로(옛
  # #E4F0F8 은 ①을 ΔL* 1.46 으로 어겼다) 두 부등식을 함께 검사한다. 테두리(--accent)의
  # 비텍스트 대비도 같이 본다 — 면색 단독으로는 ①의 천장이 낮아 테두리가 필수 채널이다.
  local open_card_contrast_output
  open_card_contrast_output=$(python3 - "$hub_template_file" <<'PYEOF'
import re
import sys

MIN_MUTED_TEXT_CONTRAST = 4.5      # WCAG 1.4.3 AA — 카드 안 --muted 본문(.path·.session-time)
MIN_SURFACE_DELTA_LSTAR = 2.0      # 넓은 면적의 명도 식별 한계(CIE L*)
MIN_BORDER_CONTRAST = 3.0          # WCAG 1.4.11 — 비텍스트(테두리)
REQUIRED_TOKENS = ("bg", "muted", "accent", "accent-soft")


def relative_luminance(hex_color: str) -> float:
    """#RRGGBB 의 WCAG 상대 휘도."""
    channels = [int(hex_color[index:index + 2], 16) / 255 for index in (1, 3, 5)]
    linear = [c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4 for c in channels]
    return 0.2126 * linear[0] + 0.7152 * linear[1] + 0.0722 * linear[2]


def contrast_ratio(first: str, second: str) -> float:
    """두 색의 WCAG 대비비(1:1 ~ 21:1)."""
    a, b = relative_luminance(first), relative_luminance(second)
    return (max(a, b) + 0.05) / (min(a, b) + 0.05)


def lightness_star(hex_color: str) -> float:
    """CIE L* — 대비비와 달리 사람이 느끼는 명도 차를 선형에 가깝게 나타낸다."""
    luminance = relative_luminance(hex_color)
    if luminance <= 0.008856:
        return 903.3 * luminance
    return 116 * luminance ** (1 / 3) - 16


source = open(sys.argv[1], encoding="utf-8").read()
# 라이트 테마는 맨 앞의 **맨몸** :root 블록이다(다크는 :root[data-theme]·미디어쿼리 안).
light_root = re.search(r":root\{(.*?)\}", source, re.S)
if light_root is None:
    print("라이트 테마 :root 블록을 찾지 못함")
    raise SystemExit(0)
tokens = dict(re.findall(r"--([a-z-]+):(#[0-9A-Fa-f]{6})", light_root.group(1)))
absent = [name for name in REQUIRED_TOKENS if name not in tokens]
if absent:
    print("라이트 :root 에 없는 토큰: " + ", ".join(absent))
    raise SystemExit(0)

problems = []
muted_contrast = contrast_ratio(tokens["accent-soft"], tokens["muted"])
if muted_contrast < MIN_MUTED_TEXT_CONTRAST:
    problems.append(
        f"열린 카드 면색 위 --muted 본문 {muted_contrast:.2f}:1 < {MIN_MUTED_TEXT_CONTRAST}"
    )
surface_delta = lightness_star(tokens["bg"]) - lightness_star(tokens["accent-soft"])
if surface_delta < MIN_SURFACE_DELTA_LSTAR:
    problems.append(
        f"열린 카드 면색과 --bg 의 ΔL* {surface_delta:.2f} < {MIN_SURFACE_DELTA_LSTAR}"
    )
border_contrast = contrast_ratio(tokens["accent"], tokens["bg"])
if border_contrast < MIN_BORDER_CONTRAST:
    problems.append(
        f"테두리 --accent 와 --bg 의 대비 {border_contrast:.2f}:1 < {MIN_BORDER_CONTRAST}"
    )
print("; ".join(problems) if problems else "OK")
PYEOF
)
  if [[ "$open_card_contrast_output" != "OK" ]]; then
    note_failure "T25-110: 라이트 테마 열린 카드 대비 — $open_card_contrast_output"
  fi
  # 위 부등식은 색 토큰만 본다 — 규칙이 실제로 두 채널을 쓰는지는 따로 고정해야 한다.
  if ! grep -qF -- '.card.card-open{background:var(--accent-soft);border-color:var(--accent)}' "$hub_template_file"; then
    note_failure "T25-110: .card.card-open 이 면색+테두리 2채널을 함께 쓰지 않음"
  fi

  # T25-282·T25-283·T25-284(신설, 결정 LT2·LT4·LT9·LT12, docs/prps/hub-light-theme-sunset.md): 라이트 금빛 팔레트의 세 관계.
  # T25-110 은 원장 면제행이라 개정하지 않고(개정하면 변조행 승급 의무가 생긴다 — PRP §9 X7) 새 관계는 별도 ID 로 둔다. 한 python 이
  # 두 템플릿을 읽어 pairs=·parity=·alias= 세 줄을 내고, 발화 줄은 가드마다 하나다.
  #   ① 의미 쌍: 채움 위 글자는 그라데이션 모든 정지점에서 4.5:1, 글자 토큰은 면 위 4.5:1, 경고(남보라)와 평상·채움은 CIELAB b* 의
  #      부호가 반대(적록 색각이상에서도 갈린다 — LT4), 막대의 한 정지점은 트랙과 비텍스트 3:1.
  #   ② 허브·대시보드의 라이트 맨몸 :root 선언이 문자 단위로 같다(dzh- 접두 허브 배치 토큰 제외 — LT2).
  #   ③ 새 토큰의 다크 별칭이 파일마다 정확히 2번(다크 블록 두 벌) 있다 — 별칭이 있어야 바뀐 규칙 8개가 다크에서 옛 계산값이 된다(LT12).
  # 한계(비망라): 첫 맨몸 :root 블록만 본다. 정지점은 #RRGGBB 만 인식하고 rgb()·색 이름은 세지 않는다. ③ 은 별칭 리터럴의 개수만
  # 세므로, 별칭이 있어도 규칙이 새 토큰을 쓰지 않는 결함은 못 잡는다.
  local light_theme_output light_theme_pairs light_theme_parity light_theme_alias
  light_theme_output=$(python3 - "$hub_template_file" "$REPO_ROOT/hub/bin/hub_dashboard_template.html" <<'PYEOF'
import re
import sys

MIN_TEXT_CONTRAST = 4.5            # WCAG 1.4.3 AA — 글자
MIN_NONTEXT_CONTRAST = 3.0         # WCAG 1.4.11 — 비텍스트(막대 대 트랙)
MIN_HUE_AXIS_MAGNITUDE = 20.0      # CIELAB b* — 부호가 반대여도 0 근처면 색각이상에서 갈리지 않는다
HUB_ONLY_TOKEN_PREFIX = "dzh-"     # 허브 배치 토큰(패널 폭·거터) — 대시보드에는 없다
DARK_ALIAS_LITERALS = (
    "--accent-fill:var(--accent-ink)",
    "--on-accent-fill:var(--bg)",
    "--accent-bar:var(--accent)",
    "--gloss-edge:0 0 transparent",
)
EXPECTED_ALIAS_COUNT = 2           # 다크 블록 두 벌(미디어쿼리 + data-theme)
SRGB_LINEAR_CUTOFF = 0.04045      # sRGB 전달 함수의 선형 구간 경계(IEC 61966-2-1)
D65_WHITE_Z = 1.08883              # D65 백색점의 Z(Y=1 기준) — CIE 1976 L*a*b*
LAB_EPSILON = 0.008856             # CIE 1976 L*a*b* 의 (6/29)^3 — 이 아래는 선형 근사
LAB_LINEAR_SLOPE = 7.787           # CIE 1976 L*a*b* 선형 구간 기울기 (29/6)^2 / 3
HEX_COLOR = re.compile(r"#[0-9A-Fa-f]{6}")
FLAT_TOKENS = (
    "surface", "soft", "accent", "accent-ink", "accent-soft",
    "attention", "attention-soft", "on-accent-fill",
)
GRADIENT_TOKENS = ("accent-fill", "accent-bar")


def linear_channels(hex_color):
    """#RRGGBB 의 선형 sRGB 채널 3개."""
    channels = [int(hex_color[index:index + 2], 16) / 255 for index in (1, 3, 5)]
    return [
        channel / 12.92 if channel <= SRGB_LINEAR_CUTOFF else ((channel + 0.055) / 1.055) ** 2.4
        for channel in channels
    ]


def relative_luminance(hex_color):
    """WCAG 상대 휘도."""
    red, green, blue = linear_channels(hex_color)
    return 0.2126 * red + 0.7152 * green + 0.0722 * blue


def contrast_ratio(first, second):
    """두 색의 WCAG 대비비."""
    first_luminance, second_luminance = relative_luminance(first), relative_luminance(second)
    return (max(first_luminance, second_luminance) + 0.05) / (min(first_luminance, second_luminance) + 0.05)


def lab_b_star(hex_color):
    """CIELAB b*(파랑-노랑 축, D65) — 양수는 노랑 쪽, 음수는 파랑 쪽. 출처: CIE 1976 L*a*b*, sRGB→XYZ(D65) 행렬의 Y·Z 행."""
    red, green, blue = linear_channels(hex_color)
    tristimulus_y = 0.2126 * red + 0.7152 * green + 0.0722 * blue
    tristimulus_z = (0.0193339 * red + 0.1191920 * green + 0.9503041 * blue) / D65_WHITE_Z

    def lab_f(tristimulus_ratio):
        if tristimulus_ratio > LAB_EPSILON:
            return tristimulus_ratio ** (1 / 3)
        return LAB_LINEAR_SLOPE * tristimulus_ratio + 16 / 116

    return 200 * (lab_f(tristimulus_y) - lab_f(tristimulus_z))


def read_source(path):
    """파일 전체 텍스트."""
    with open(path, encoding="utf-8") as handle:
        return handle.read()


def light_declarations(source):
    """첫 맨몸 :root 블록의 --이름:값; 선언(공백 정규화). 블록이 없으면 None."""
    block = re.search(r":root\{(.*?)\}", source, re.S)
    if block is None:
        return None
    return {
        name: " ".join(value.split())
        for name, value in re.findall(r"--([a-z-]+):([^;]+);", block.group(1))
    }


def check_pairs(tokens):
    """의미 쌍 관계(① ~ ⑦)의 위반 목록."""
    if tokens is None:
        return ["허브 라이트 :root 블록을 찾지 못함"]
    absent = [name for name in FLAT_TOKENS + GRADIENT_TOKENS if name not in tokens]
    if absent:
        return ["라이트 :root 에 없는 토큰: " + ", ".join(absent)]
    flat = {name: tokens[name] for name in FLAT_TOKENS}
    malformed = [name for name, value in flat.items() if not re.fullmatch(HEX_COLOR, value)]
    fill_stops = HEX_COLOR.findall(tokens["accent-fill"])
    bar_stops = HEX_COLOR.findall(tokens["accent-bar"])
    if malformed or not fill_stops or not bar_stops:
        return ["#RRGGBB 로 읽히지 않는 토큰 또는 정지점 없음: " + ", ".join(malformed or ["accent-fill/accent-bar"])]
    problems = []
    for stop in fill_stops:
        ratio = contrast_ratio(flat["on-accent-fill"], stop)
        if ratio < MIN_TEXT_CONTRAST:
            problems.append(f"① 채움 정지점 {stop} 위 글자 {ratio:.2f}:1 < {MIN_TEXT_CONTRAST}")
    for label, text_name, face_name in (
        ("②", "accent-ink", "accent-soft"),
        ("③", "attention", "surface"),
        ("④", "attention", "attention-soft"),
        ("⑤", "attention", "accent-soft"),
    ):
        ratio = contrast_ratio(flat[text_name], flat[face_name])
        if ratio < MIN_TEXT_CONTRAST:
            problems.append(f"{label} {text_name} 대 {face_name} {ratio:.2f}:1 < {MIN_TEXT_CONTRAST}")
    attention_b = lab_b_star(flat["attention"])
    ordinary = [("accent", flat["accent"]), ("accent-ink", flat["accent-ink"])]
    ordinary += [(f"accent-fill {stop}", stop) for stop in fill_stops]
    for name, color in ordinary:
        ordinary_b = lab_b_star(color)
        same_side = (ordinary_b > 0) == (attention_b > 0)
        if same_side or min(abs(ordinary_b), abs(attention_b)) < MIN_HUE_AXIS_MAGNITUDE:
            problems.append(f"⑥ b* {name} {ordinary_b:+.1f} 대 attention {attention_b:+.1f} — 반대편이 아님")
    best_bar = max(contrast_ratio(stop, flat["soft"]) for stop in bar_stops)
    if best_bar < MIN_NONTEXT_CONTRAST:
        problems.append(f"⑦ 막대 정지점 대 트랙 최댓값 {best_bar:.2f}:1 < {MIN_NONTEXT_CONTRAST}")
    return problems


def check_parity(hub_tokens, dashboard_tokens):
    """두 파일 라이트 선언의 차이 목록."""
    if hub_tokens is None or dashboard_tokens is None:
        return ["라이트 :root 블록을 찾지 못함"]
    hub = {name: value for name, value in hub_tokens.items() if not name.startswith(HUB_ONLY_TOKEN_PREFIX)}
    dashboard = {
        name: value for name, value in dashboard_tokens.items() if not name.startswith(HUB_ONLY_TOKEN_PREFIX)
    }
    problems = []
    for name in sorted(set(hub) | set(dashboard)):
        if name not in dashboard:
            problems.append(f"--{name} 는 허브에만 있음")
        elif name not in hub:
            problems.append(f"--{name} 는 대시보드에만 있음")
        elif hub[name] != dashboard[name]:
            problems.append(f"--{name} 값 불일치(허브 {hub[name]} / 대시보드 {dashboard[name]})")
    return problems


def check_aliases(label, source):
    """다크 별칭 리터럴 개수 위반 목록."""
    problems = []
    for literal in DARK_ALIAS_LITERALS:
        count = source.count(literal)
        if count != EXPECTED_ALIAS_COUNT:
            problems.append(f"{label} {literal} {count}개(기대 {EXPECTED_ALIAS_COUNT})")
    return problems


hub_source = read_source(sys.argv[1])
dashboard_source = read_source(sys.argv[2])
hub_tokens = light_declarations(hub_source)
dashboard_tokens = light_declarations(dashboard_source)
results = {
    "pairs": check_pairs(hub_tokens),
    "parity": check_parity(hub_tokens, dashboard_tokens),
    "alias": check_aliases("허브", hub_source) + check_aliases("대시보드", dashboard_source),
}
for key, problems in results.items():
    print(key + "=" + ("; ".join(problems) if problems else "OK"))
PYEOF
)
  light_theme_pairs=$(sed -n 's/^pairs=//p' <<< "$light_theme_output")
  light_theme_parity=$(sed -n 's/^parity=//p' <<< "$light_theme_output")
  light_theme_alias=$(sed -n 's/^alias=//p' <<< "$light_theme_output")
  if [[ "$light_theme_pairs" != "OK" ]]; then
    note_failure "T25-282: 라이트 의미 쌍 관계 위반(결정 LT4 — 평상·채움과 경고가 한 색으로 붙거나 글자·막대 대비가 미달) — ${light_theme_pairs:-<출력 없음 — python 이 죽었다>}"
  fi
  if [[ "$light_theme_parity" != "OK" ]]; then
    note_failure "T25-283: 허브·대시보드 라이트 토큰 불일치(결정 LT2 — 상세 패널 iframe 안만 다른 색으로 남는다) — ${light_theme_parity:-<출력 없음 — python 이 죽었다>}"
  fi
  if [[ "$light_theme_alias" != "OK" ]]; then
    note_failure "T25-284: 다크 별칭 개수 불일치(결정 LT12 — 다크 화면이 라이트 금빛으로 바뀐다) — ${light_theme_alias:-<출력 없음 — python 이 죽었다>}"
  fi

  # T25-111(결정 WT3, docs/prps/hub-worktree-fold.md): hub_project.py 에 워크트리 경로 마커
  # 상수가 리터럴로 있다. 마커 문자열이 조용히 바뀌면 아무 경로도 접히지 않는다.
  # 독립 서브체크라 note_failure 를 쓴다(검수 1회차 M2) — record_failure + return 1 이면
  # 이 검사가 무관한 회귀와 동시에 걸렸을 때 그 회귀가 요약에서 소실된다(2231724 의 회귀).
  if ! grep -qF 'WORKTREE_PATH_MARKER = "/.claude/worktrees/"' "$hub_project_file"; then
    note_failure "T25-111: hub_project.py 에 WORKTREE_PATH_MARKER 리터럴이 없음"
  fi

  # T25-112(결정 WT4·WT5, T25-87 과 같은 줄번호 비교 방식): hub_collect.py 에서
  # fold_worktree_path 또는 group_paths_by_repo_root 호출이 should_ignore_cwd 호출보다
  # 앞 줄에 있다 — fold-first 순서가 뒤집히면 워크트리 경로가 ignore_globs 기본값
  # (`**/.claude/worktrees/**`)에 걸려 워크트리 세션이 통째로 사라진다.
  # `head -1` 은 "파일 전체의 첫 호출"을 비교한다. should_ignore_cwd 호출 자체는 2곳이지만
  # (`_group_sessions_by_project` 와 `_tier3_activity_by_encoded_name`), fold 와 **함께** 쓰이는
  # 지점은 전자 하나뿐이고 파일에서도 먼저 나오므로 `head -1` 이 그 지점을 집는다 — 따라서 이
  # 비교는 곧 그 함수 안의 실제 순서다(재검수 2회차 정정: 이전 주석은 "남은 호출 지점이 하나뿐"
  # 이라 적었으나 그것은 사실이 아니었다. 결론은 같고 근거만 틀렸다).
  # 잔여 한계: `_group_sessions_by_project` 에서 ignore 호출만 사라지면 first_ignore 가 티어 3
  # 쪽으로 밀려 이 검사가 조용히 통과한다. 그 회귀는 단위 테스트 U-13 이 잡는다.
  local first_fold_call_line first_ignore_call_line
  first_fold_call_line=$(grep -nE 'hub_project\.(fold_worktree_path|group_paths_by_repo_root)\(' "$hub_collect_file" | head -1 | cut -d: -f1)
  first_ignore_call_line=$(grep -n 'hub_project\.should_ignore_cwd(' "$hub_collect_file" | head -1 | cut -d: -f1)
  if [[ -z "$first_fold_call_line" || -z "$first_ignore_call_line" \
      || "$first_fold_call_line" -ge "$first_ignore_call_line" ]]; then
    note_failure "T25-112: hub_collect.py 에서 fold 호출이 should_ignore_cwd 보다 먼저 오지 않음(결정 WT4·WT5)"
  fi

  # T25-113(결정 WT8 되돌림 방지): hub_model.py 에 옛 조립(project.path 를 그대로 재조립하는
  # 식)이 남아 있으면 안 된다 — 되돌아가면 카드에 보이는 진행률과 클릭해서 열리는 파일이
  # 서로 다른 파일이 되는 조용한 불일치가 부활한다.
  if grep -qF 'project.path + "/" + PROJECT_DASHBOARD_RELATIVE_PATH' "$hub_model_file"; then
    note_failure "T25-113: hub_model.py 에 옛 조립(project.path 재조립)이 남아 있음(결정 WT8 되돌림)"
  fi

  # T25-114(T25-10 이 남긴 구멍을 메움, 결정 WT3 주의사항): hub_project.py 에 subprocess
  # 사용 흔적이 없다. T25-10 의 grep(open(/Path(/os.) 은 subprocess.run( 을 통과시킨다(실측) —
  # ★순수 계약의 진짜 경계는 docstring 이지 그 grep 이 아니다.
  if grep -qE 'subprocess' "$hub_project_file"; then
    note_failure "T25-114: hub_project.py 에 subprocess 사용 흔적이 있음(★순수 계약 위반)"
  fi

  # T25-115(결정 WT19, docs/prps/hub-worktree-fold.md 2판 — 재조준(M1, 결정 BW11): 대상이
  # hub_session_facts.py 로 옮겼다 — SessionFacts 전체가 그 모듈로 이동했기 때문이다):
  # hub_session_facts.py 의 observed_cwds 필드에 기본값이 없다. 기본값 `()` 가 슬쩍 붙으면
  # 손으로 만드는 픽스처가 조용히 "관측 cwd 없음"이 되어 `in observed_cwds` 판정이 언제나
  # 거짓이 된다 — 이번 결함과 정확히 같은 모양의 구멍이다.
  if ! grep -qF 'observed_cwds: tuple[str, ...]' "$hub_session_facts_file"; then
    note_failure "T25-115: hub_session_facts.py 에 observed_cwds: tuple[str, ...] 선언이 없음"
  fi
  if grep -qF 'observed_cwds: tuple[str, ...] = ()' "$hub_session_facts_file"; then
    note_failure "T25-115: hub_session_facts.py 의 observed_cwds 에 기본값 ()가 붙어 있음(결정 WT19 위반)"
  fi

  # T25-116(결정 WT16, 2판): hub_project.py 의 plan_tier1_candidates 가 후보 입력을
  # facts.observed_cwds 에서 읽는다. 옛 표현(facts.cwd 하나만 본다)으로 되돌아가면 워크트리
  # 경로가 다시 후보에 오를 길이 없어져 이번 결함(결함 A)이 재발한다.
  # 양성 검사는 반드시 후보 입력 루프 자체를 가리켜야 한다. 그냥 `facts.observed_cwds` 로
  # 넓게 잡으면 같은 파일의 _live_session_start_times_ms 참조가 대신 만족시켜, 루프를
  # `for cwd in (facts.cwd,)` 로 되돌려도 이 검사가 조용히 통과한다(검수 3회차 실측).
  if ! grep -qF 'for cwd in facts.observed_cwds' "$hub_project_file"; then
    note_failure "T25-116: hub_project.py 의 후보 입력 루프가 facts.observed_cwds 를 돌지 않음(결정 WT16 되돌림)"
  fi
  if grep -qF '{facts.cwd for' "$hub_project_file"; then
    note_failure "T25-116: hub_project.py 의 plan_tier1_candidates 가 옛 입력(facts.cwd 하나)으로 되돌아감"
  fi

  # T25-117(결정 WT18, 2판): _live_session_start_times_ms 의 GN 판정 비교가
  # tier1_source_path in facts.observed_cwds 다. facts.cwd == tier1_source_path 로 되돌아가면
  # 워크트리로 이동한 세션이 판정 집합에서 빠져 "이전 작업" 라벨이 우연히만 맞는 상태로
  # 되돌아간다(결정 WT9 수준으로 되돌림).
  if ! grep -qF 'tier1_source_path in facts.observed_cwds' "$hub_project_file"; then
    note_failure "T25-117: hub_project.py 에 tier1_source_path in facts.observed_cwds 비교가 없음(결정 WT18 되돌림)"
  fi
  if grep -qF 'facts.cwd == tier1_source_path' "$hub_project_file"; then
    note_failure "T25-117: hub_project.py 에 facts.cwd == tier1_source_path 비교가 남아 있음(결정 WT18 되돌림)"
  fi

  # T25-118(결정 WT20, 2판): 이벤트 파일 입력부터 collect_snapshot() 을 실행하는 이음매
  # 테스트가 삭제되거나 중간 함수 호출로 "간소화"되지 않는다. grep 은 클래스 존재만 보고
  # 단언의 강도는 못 본다 — 진짜 안전망은 뮤테이션 9~13 이다(§7 의 한계 기록과 동일).
  if ! grep -qF 'class CollectSnapshotWorktreeTier1Test' "$test_hub_collect_file"; then
    note_failure "T25-118: test_hub_collect.py 에 class CollectSnapshotWorktreeTier1Test 가 없음(결정 WT20 이음매 테스트 삭제)"
  fi
  if ! grep -qF 'hub_collect.collect_snapshot(' "$test_hub_collect_file"; then
    note_failure "T25-118: test_hub_collect.py 에 hub_collect.collect_snapshot( 호출이 없음(결정 WT20 이음매 테스트 삭제)"
  fi

  # T25-119(개정 — 가시성 게이트마저 제거, docs/prps/hub-ungated-poll-and-stale-tab-self-heal.md
  # 결정 SH1): 일부 환경(내장 브라우저)이 실제로 보이는 탭을 'hidden' 으로 오보고해 폴링이
  # 영구히 멎는 사고가 실측돼, "작업중 세션 유무"에서 한 번, "탭 가시성"에서 다시 한 번
  # 갈아탔던 게이트를 이번엔 완전히 없앤다. 옛 게이트(hasWorkingProject)의 부재는 계속
  # 지키고, 판정은 뒤집는다(역방향) — 이제는 게이트가 **없어야** 통과다.
  if grep -qF 'hasWorkingProject' "$hub_template_file"; then
    note_failure "T25-119: hub_template.html 에 폐기된 hasWorkingProject 흔적이 남아 있음(옛 게이트 회귀)"
  fi
  # 판정을 인터벌 등록 줄 하나로 좁힌다 — 파일 전체를 보면 1466·1557행 근방의 정당한
  # visibilityState 사용(file:// 폴백·즉시 폴링 사건 판별)을 오탐한다.
  local poll_interval_registration_line
  poll_interval_registration_line=$(grep -n 'POLL_INTERVAL_MS);' "$hub_template_file" | grep 'setInterval(' | head -1)
  if [[ -z "$poll_interval_registration_line" ]]; then
    record_failure "$test_name" "T25-119: POLL_INTERVAL_MS 인터벌 등록 줄을 찾지 못함"
    return 1
  fi
  if grep -qF 'visibilityState' <<< "$poll_interval_registration_line"; then
    note_failure "T25-119: hub_template.html 의 인터벌 등록 줄에 visibilityState 게이트가 남아 있음(결정 SH1 회귀)"
  fi
  if grep -qF '탭이 보이지 않는 동안은 이 1분 타이머가 폴링 자체를 건너뛴다' "$hub_readme_file"; then
    note_failure "T25-119: hub/README.md 에 폐기된 가시성 게이트 설명 문구가 남아 있음(결정 SH11 회귀)"
  fi
  if grep -qF '카드가 하나도 없으면 이 1분 타이머가 폴링 자체를 건너뛴다' "$hub_readme_file"; then
    note_failure "T25-119: hub/README.md 에 폐기된 '작업중 카드' 게이트 문구가 남아 있음(문서 회귀)"
  fi
  # 문서 방침 개정(2026-08): hub/README.md 는 변경 이력·제거 사유가 아니라 현재 상태만
  # 기술한다 — 위 두 회귀 검사(옛 게이트 문구 부재)는 유지하되, "왜 없앴는지" 서술을
  # 강제하던 순방향 검사는 새 방침과 양립하지 않아 제거한다.

  # T25-119(2판, 결정 개정): renderConnectionStatus() 의 "자동 갱신 대기" 분기는 옛 "작업중
  # 세션 유무" 게이트에서만 의미가 있었다(검수 HIGH 지적으로 도입된 분기 — 게이트가 닫힌
  # 동안 서버 생존을 관측할 수 없어 "서버 연결됨"을 단정하지 못하게 막았다). 탭 가시성
  # 게이트에서는 이 분기가 도달 불가다 — 문구는 새로고침 버튼의 data-tooltip 이라 hover·
  # focus 로만 보이는데, 그건 탭이 visible 일 때만 가능하고 visible 이면 게이트가 항상
  # 열려 있다. 되살아나지 않는지 문구 부재로 확인한다. 함수 본문만 추출한다 — 앵커가
  # 깨지면 검사가 조용히 무력화되므로 추출 실패 자체도 본다.
  local connection_status_body
  connection_status_body=$(sed -n '/function renderConnectionStatus(){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$connection_status_body" ]]; then
    note_failure "T25-119: renderConnectionStatus() 범위 추출 실패 — 앵커가 깨졌다"
  fi
  if grep -qF '자동 갱신 대기' <<< "$connection_status_body"; then
    note_failure "T25-119: renderConnectionStatus() 에 도달 불가였던 '자동 갱신 대기' 분기가 되살아나 있음"
  fi

  # T25-120(변경 B — 옛 자동주입 발췌 방어 필터): 훅 필터 도입(8af296a) 전에 저장된 옛
  # 기록은 닫는 태그 없이 잘려 훅 정규식(AUTO_INJECTED_PROMPT_BLOCK, .*?</\1>)으로도
  # 사후에 걸러지지 않는다 — 표시 단계에 방어 필터(displayableExcerpt)를 신설했다. 이
  # 검사는 그 필터가 사라지거나, renderSession·shouldRenderSession 이 session.task_excerpt
  # 를 다시 직접 보는 형태로 어긋나는 것(visibleAgentRuns 의 GOTCHA 3 과 같은 종류의
  # 함정)을 막는다.
  if ! grep -qF 'function displayableExcerpt(taskExcerpt){' "$hub_template_file"; then
    note_failure "T25-120: hub_template.html 에 function displayableExcerpt(taskExcerpt) 가 없음"
  fi
  # T25-120(결정 PS6 개정, docs/prps/hub-agent-runs-and-prompt-source.md — 양방향 → 단방향):
  # 훅이 프롬프트를 더 이상 기록하지 않으므로(결정 PS4) hub_hook.py 의
  # AUTO_INJECTED_PROMPT_BLOCK 앵커 자체가 사라졌다 — 두 파일의 태그 alternation 을 비교하던
  # 옛 검사는 앵커를 잃어 구조적으로 성립하지 않는다. `displayableExcerpt` 가 여전히 존재하고
  # (위 검사) `renderSession` 이 그것을 경유하는가만 단방향으로 본다 — 훅 쪽에 대응물이
  # 없어졌으니 한쪽만 남는 것이 옳다(PS6 — 근거 실측이 30건뿐이고 그 태그 규칙은 호스트
  # 소유라, 필터 자체를 지우는 대안보다 이 방어 필터를 남기는 쪽이 안전하다).
  if ! grep -qF 'renderSessionExcerpt(displayableExcerpt(session.task_excerpt))' "$hub_template_file"; then
    note_failure "T25-120: renderSession() 이 displayableExcerpt 를 경유하지 않음"
  fi

  local should_render_session_body
  should_render_session_body=$(sed -n '/function shouldRenderSession(session){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$should_render_session_body" ]]; then
    note_failure "T25-120: shouldRenderSession() 범위 추출 실패 — 앵커가 깨졌다"
  fi
  if ! grep -qF '!displayableExcerpt(session.task_excerpt)' <<< "$should_render_session_body"; then
    note_failure "T25-120: shouldRenderSession() 이 displayableExcerpt 를 경유하지 않음"
  fi
  if grep -qF '!session.task_excerpt' <<< "$should_render_session_body"; then
    note_failure "T25-120: shouldRenderSession() 이 session.task_excerpt 를 직접 봄(displayableExcerpt 를 안 거침 — 옛 조건 회귀)"
  fi

  # T25-121(개정 2, docs/prps/hub-collect-on-demand-and-readability.md §2): 요청 구동 수집의
  # 핵심 토큰이 hub_server.py 에 있다. **역방향**: `_DEPRECATED_CONFIG_FIELD_GUIDANCE` 의
  # 이주 안내문(§2.7) 1건을 빼면 hub/bin/ 어디에도 server_collect_interval_seconds 리터럴이
  # 남지 않는다(이주 완료 증명). "0건"이 아니라 "정확히 1건"을 요구하는 이유는
  # serve_port_candidates 가 이미 같은 모양(옛 필드명을 영구히 안내문에 남긴다)으로 존재하기
  # 때문이다 — 안내문 자체를 죽은 필드 잔재로 오판하지 않는다.
  local required_token
  for required_token in "SNAPSHOT_FRESHNESS_WINDOW_MS" "BACKGROUND_COLLECT_MAX_AGE_MS" \
      "class _SnapshotRefresher" "collect_if_older_than"; do
    if ! grep -qF "$required_token" "$hub_server_file"; then
      note_failure "T25-121: hub_server.py 에 $required_token 토큰이 없음"
    fi
  done
  local collect_interval_literal_count
  collect_interval_literal_count=$(grep -ro "server_collect_interval_seconds" "$REPO_ROOT"/hub/bin/*.py | wc -l | tr -d ' ')
  if [[ "$collect_interval_literal_count" -ne 1 ]]; then
    note_failure "T25-121: hub/bin/ 의 server_collect_interval_seconds 리터럴 개수=$collect_interval_literal_count(기대 1 — _DEPRECATED_CONFIG_FIELD_GUIDANCE 안내문 1건만 허용)"
  fi

  # T25-122(개정 2 → AR5 로 확장, 재작성 — 검수 Major: sed 텍스트 앵커는 docstring 산문까지
  # grep 대상에 넣어 오탐(주석에 파일명 언급만 있어도 실패)·미탐(본문 호출을 지워도 docstring
  # 언급이 남으면 통과)을 동시에 낸다. T25-16 과 같은 AST 추출 관례로 바꿔 **코드 본문만**
  # (docstring 제거) grep 대상으로 삼는다. 사용량 API 폴링이 절대 요청 경로에도, 하트비트
  # 티커(_maintenance_loop)에도 오르지 않는다 — 전용 데몬 스레드 _usage_api_poll_loop 에만
  # 있다(결정 AR5 — 결정 A3 의 배치 번복). 원격 호출(최악 15초 블로킹, hub_usage_fetch.py)이
  # 하트비트 티커와 같은 스레드에 있으면 TTL(15초) 산술이 성립하지 않는다는 것이 번복
  # 사유다(감사 B-2).
  local hub_server_ast_output
  hub_server_ast_output=$(python3 - "$hub_server_file" <<'PYEOF'
import ast
import sys

source_path = sys.argv[1]
tree = ast.parse(open(source_path, encoding="utf-8").read(), filename=source_path)

# 이름으로 함수를 찾는다(들여쓰기·앞뒤 함수 이름에 의존하지 않는다) — 순서가 바뀌거나
# 사이에 함수가 추가돼도 깨지지 않는다. 대신 이름이 아예 없어지거나(개명·삭제) 같은
# 이름이 여럿 생기면(오류) __MISSING__ 으로 명시 실패시킨다.
FUNCTION_NAMES = (
    "_maintenance_loop",
    "_usage_api_poll_loop",
    "run_server",
    "do_GET",
    "_serve_hub_html",
    "_serve_project_dashboard",
)


def body_without_docstring(func):
    body = list(func.body)
    if (
        body
        and isinstance(body[0], ast.Expr)
        and isinstance(body[0].value, ast.Constant)
        and isinstance(body[0].value.value, str)
    ):
        body = body[1:]
    return body


nodes_by_name = {name: [] for name in FUNCTION_NAMES}
for node in ast.walk(tree):
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name in nodes_by_name:
        nodes_by_name[node.name].append(node)

for name in FUNCTION_NAMES:
    matches = nodes_by_name[name]
    print(f"__BEGIN__:{name}")
    if len(matches) != 1:
        print(f"__MISSING__(matches={len(matches)})")
    else:
        body = body_without_docstring(matches[0])
        if body:
            print(ast.unparse(ast.Module(body=body, type_ignores=[])))
    print(f"__END__:{name}")
PYEOF
)
  # N-1(Q1 검수 2회차, 회귀) — ast.parse 가 SyntaxError 를 던지면 python 이 마커를 하나도
  # 출력하지 못해 아래 __MISSING__ 가드가 발동하지 않고, 부재 방향 검사 ①③ 이 공허하게
  # 통과한다. 옛 `-z` 빈 문자열 가드가 지키던 자리라 여기서 먼저 명시적으로 막는다.
  if [[ -z "$hub_server_ast_output" ]]; then
    record_failure "$test_name" "T25-122: hub_server.py AST 추출이 아무 출력도 내지 않았다 — ast.parse 실패(SyntaxError) 가능"
    return 1
  fi
  local maintenance_loop_body usage_api_poll_loop_body run_server_body
  local do_get_body serve_hub_html_body serve_project_dashboard_body
  maintenance_loop_body=$(sed -n '/^__BEGIN__:_maintenance_loop$/,/^__END__:_maintenance_loop$/p' <<< "$hub_server_ast_output" | sed '1d;$d')
  usage_api_poll_loop_body=$(sed -n '/^__BEGIN__:_usage_api_poll_loop$/,/^__END__:_usage_api_poll_loop$/p' <<< "$hub_server_ast_output" | sed '1d;$d')
  run_server_body=$(sed -n '/^__BEGIN__:run_server$/,/^__END__:run_server$/p' <<< "$hub_server_ast_output" | sed '1d;$d')
  do_get_body=$(sed -n '/^__BEGIN__:do_GET$/,/^__END__:do_GET$/p' <<< "$hub_server_ast_output" | sed '1d;$d')
  serve_hub_html_body=$(sed -n '/^__BEGIN__:_serve_hub_html$/,/^__END__:_serve_hub_html$/p' <<< "$hub_server_ast_output" | sed '1d;$d')
  serve_project_dashboard_body=$(sed -n '/^__BEGIN__:_serve_project_dashboard$/,/^__END__:_serve_project_dashboard$/p' <<< "$hub_server_ast_output" | sed '1d;$d')
  # 함수를 못 찾으면(이름 변경·삭제) 반드시 실패한다 — 옛 `-z` 빈 문자열 가드의 역할을
  # AST 추출 쪽에서도 유지한다.
  if grep -qF '__MISSING__' <<< "$maintenance_loop_body$usage_api_poll_loop_body$run_server_body$do_get_body$serve_hub_html_body$serve_project_dashboard_body"; then
    # N-4(Q1 검수 2회차, INFO) — AST 덤프 전체(80줄)를 싣는 대신 문제 함수 이름만 좁혀 싣는다.
    local missing_function_names
    missing_function_names=$(grep -B1 '__MISSING__' <<< "$hub_server_ast_output" | grep '^__BEGIN__:' | sed 's/^__BEGIN__://' | tr '\n' ' ')
    record_failure "$test_name" "T25-122: hub_server.py 함수 AST 추출 실패 — 함수가 없거나 이름이 여럿임(대상: $missing_function_names)"
    return 1
  fi
  # ① 유지보수 티커에는 더 이상 사용량 API 호출이 없다(AR5 로 전용 스레드로 이동). 이
  # 서브체크는 ②③④ 와 독립이므로 note_failure 를 쓴다 — record_failure+return 1 을 쓰면
  # 이 검사 하나의 실패가 나머지 세 검사의 보고까지 함께 지운다(group_failures 선언 위
  # note_failure 관례 참고 — 줄 번호는 인용하지 않는다).
  if grep -qE 'hub_usage_fetch|_run_usage_api_poll_cycle' <<< "$maintenance_loop_body"; then
    note_failure "T25-122: _maintenance_loop 본문에 사용량 API 폴링 호출이 남아 있음(AR5 위반 — 하트비트 티커에 원격 지연이 실리면 TTL 산술이 깨진다)"
  fi
  # ② 신설 전용 스레드 본문에만 폴링 호출이 있어야 한다.
  if ! grep -qF '_run_usage_api_poll_cycle(' <<< "$usage_api_poll_loop_body"; then
    note_failure "T25-122: _usage_api_poll_loop 본문에 _run_usage_api_poll_cycle 호출이 없음"
  fi
  # ③ 요청 경로에는 여전히 없어야 한다(기존 검사 유지 — 선재 코드, 계약 불변).
  local request_path_body="${do_get_body}${serve_hub_html_body}${serve_project_dashboard_body}"
  if grep -qE 'hub_usage_fetch|_run_usage_api_poll_cycle' <<< "$request_path_body"; then
    record_failure "$test_name" "T25-122: 요청 경로(do_GET/_serve_hub_html/_serve_project_dashboard) 본문에 사용량 API 호출이 있음 — 최악 15초 블로킹이 HTTP 응답에 실린다"
    return 1
  fi
  # ④ 두 데몬 스레드(유지보수 티커 + 사용량 API 폴링)가 모두 기동돼야 한다.
  if ! grep -qF 'target=_usage_api_poll_loop' <<< "$run_server_body"; then
    note_failure "T25-122: run_server 본문에 _usage_api_poll_loop 스레드 기동이 없음"
  fi

  # T25-123(개정 2): hub_server_state.py 에 evaluate_collect_health·maintenance_stalled·
  # CollectHealth 가 있다. **역방향**: hub/bin/ 에 collect_stalled 리터럴이 전혀 남지 않았다
  # (죽은 필드 회귀 방지). server_collect_interval_seconds 와 달리 이 이름은 config 필드가
  # 아니라 안내할 이주 경로가 없으므로 "0건"을 요구한다.
  for required_token in "evaluate_collect_health" "maintenance_stalled" "CollectHealth"; do
    if ! grep -qF "$required_token" "$hub_server_state_file"; then
      note_failure "T25-123: hub_server_state.py 에 $required_token 이 없음"
    fi
  done
  if grep -rqF "collect_stalled" "$REPO_ROOT/hub/bin"; then
    record_failure "$test_name" "T25-123: hub/bin/ 에 collect_stalled 리터럴이 남아 있음(죽은 필드 회귀)"
    return 1
  fi

  # T25-124(개정 2, 문서 정합): 허브 수집 주기 서술이 요청 구동으로 바뀌었는지 확인한다.
  if ! grep -qF "요청 구동" "$hub_readme_file"; then
    note_failure "T25-124: hub/README.md 에 '요청 구동' 문구가 없음"
  fi
  if grep -qF "5초마다 모든 프로젝트를 다시 수집" "$hub_readme_file"; then
    note_failure "T25-124: hub/README.md 에 옛 '5초마다 모든 프로젝트를 다시 수집' 문구가 남아 있음"
  fi
  if grep -qF "5초마다 갱신" "$hub_command_file"; then
    note_failure "T25-124: commands/hub.md 에 옛 '5초마다 갱신' 문구가 남아 있음"
  fi
  if grep -qF "기본 5초" "$dashboard_command_file"; then
    note_failure "T25-124: hub/README.md 에 옛 '기본 5초' 문구가 남아 있음"
  fi
  # 재조준 삭제(docs/prps/dashboard-into-hub.md HD1): README.md 의 "1분 간격 폴링" 오폭
  # 금지 검사를 없앤다 — 그 문구가 속해 있던 /dashboard PiP 문단 자체가 HD1 로 README.md
  # 에서 통째로 사라졌다(coding-harness 는 더 이상 대시보드를 모른다). 보호 대상이 의도적으로
  # 없어졌으므로 "사라지면 실패" 긍정 검사는 더 이상 성립하지 않는다.

  # T25-125(개정 3, docs/prps/hub-collect-on-demand-and-readability.md §4): 세션 식별 줄이
  # 실제로 렌더된다. escapeHtml(session.short_id)·escapeHtml(session.session_id) 은 T25-11 의
  # 부정 검사(`+ session.short_id +` 리터럴 금지)와 짝을 이루는 긍정 검사다 — 둘 다 escapeHtml
  # 을 경유해야 함을 못박는다.
  for required_token in "escapeHtml(session.short_id)" "escapeHtml(session.session_id)" \
      "renderSessionMeta" "absoluteTimeLabel" "session.started_at_ms"; do
    if ! grep -qF "$required_token" "$hub_template_file"; then
      note_failure "T25-125: hub_template.html 에 $required_token 이 없음"
    fi
  done

  # T25-126(§4.4, 결정 WT19 와 같은 관례 — 정체성 필드에 기본값을 주지 않는다 — 끝 앵커
  # 재조준(M1, 결정 BW11): SessionView 바로 뒤 절 머리가 hub_session_facts.py 분리로
  # ^# ---- 세션 표시 상태 ---- 로 바뀌었다 — 안 바꾸면 sed 범위가 파일 끝까지 늘어 거짓
  # 결과가 난다): SessionView 에 started_at_ms: int 선언이 있고 기본값이 붙어 있지 않다.
  # 기본값이 슬쩍 붙으면 생성 지점 누락(4곳 중 하나)이 조용히 통과해 화면에 1970년이 뜨고
  # 원인을 추적할 수 없게 된다.
  local session_view_body
  session_view_body=$(sed -n '/^class SessionView:/,/^# ---- 세션 표시 상태 ----/p' "$hub_session_file")
  if [[ -z "$session_view_body" ]]; then
    record_failure "$test_name" "T25-126: SessionView 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'started_at_ms: int' <<< "$session_view_body"; then
    note_failure "T25-126: hub_session.py 의 SessionView 에 started_at_ms: int 선언이 없음"
  fi
  if grep -qE 'started_at_ms: int[[:space:]]*=' <<< "$session_view_body"; then
    record_failure "$test_name" "T25-126: hub_session.py 의 SessionView.started_at_ms 에 기본값이 붙어 있음(§4.4 위반)"
    return 1
  fi

  # T25-127(§4.3·§4.5, 첫 줄 불변 계약, 검수 Minor 7 로 범위 정정. M2 앵커 이동 — docs/prps/
  # hub-session-modal-and-partial-update.md 결정 SC6: 첫 줄 구성이 renderSession() 에서
  # renderSessionContent() 로 옮겨 갔다 — 카드 세션 줄과 모달 세션 카드가 공유하기 위해서다):
  # 세션 식별 줄(.session-meta)은 .session-line 의 형제 블록이라 첫 줄의 flex-wrap 거동을
  # 바꾸지 않는다. CSS 규칙 존재를 확인하고, renderSessionContent() 범위를 앵커로 추출해
  # 그 안의 class="session-line" 문자열 뒤 첫 </div> **앞까지만 잘라**(줄 전체를 버리면 같은
  # 줄에서 순서만 바뀐 회귀 — 예: `+ renderSessionMeta(session) + '</div>'` — 를 못 잡는다,
  # 검수 Minor A)에 session-id·session-meta·renderSessionMeta 가 새어 들어가 있지 않은지
  # 본다. renderSessionMeta 호출도 봐야 하는 이유: 그 함수가 반환하는 리터럴
  # class="session-meta" 문자열은 renderSessionContent() 소스 안에 나타나지 않으므로(호출만
  # 있다), 하이픈 클래스명만 찾으면 식별 줄 호출이 </div> 앞으로 옮겨져도(가장 자연스러운
  # 회귀 편집) 잡히지 않는다.
  if ! grep -qF '.session-meta{' "$hub_template_file" || ! grep -qF '.session-id{' "$hub_template_file"; then
    note_failure "T25-127: .session-meta{ 또는 .session-id{ CSS 규칙이 없음"
  fi
  local render_session_body first_line_segment
  render_session_body=$(sed -n '/function renderSessionContent(session){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$render_session_body" ]]; then
    record_failure "$test_name" "T25-127: renderSessionContent() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  # 공허 통과 방지 — 앵커는 살아 있지만 본문 안에서 class="session-line" 자체가 사라지면
  # (예: 리터럴을 고쳐 썼다) 아래 awk 가 in_range 를 한 번도 못 켜 first_line_segment 가
  # 빈 문자열이 되고, 그러면 grep -qE 가 항상 실패(불일치)해 "새어 들어간 게 없다"는 거짓
  # 통과가 난다 — 그래서 이 앵커 리터럴의 존재를 별도로 강제한다.
  if ! grep -qF 'class="session-line"' <<< "$render_session_body"; then
    record_failure "$test_name" "T25-127: renderSessionContent() 본문에 class=\"session-line\" 이 없음 — 앵커가 깨졌다"
    return 1
  fi
  first_line_segment=$(awk '
    /class="session-line"/ { in_range=1 }
    in_range {
      if (match($0, /<\/div>/)) { print substr($0, 1, RSTART-1); exit }
      print
    }
  ' <<< "$render_session_body")
  if grep -qE 'session-id|session-meta|renderSessionMeta' <<< "$first_line_segment"; then
    record_failure "$test_name" "T25-127: renderSessionContent() 의 첫 줄(session-line) 구성 안에 session-id 또는 session-meta 가 새어 들어감(첫 줄 wrap 거동 회귀)"
    return 1
  fi

  # T25-128(§4.5, 완료 기준 6): absoluteTimeLabel 의 날짜 경계 분기(오늘이면 HH:MM, 다른
  # 날이면 M/D HH:MM)가 템플릿에 실제로 존재한다. 셸은 JS 를 실행하지 않으므로 값 자체는
  # 검증할 수 없다 — 최소한 그 분기 로직(sameDay 비교와 M/D 표기)이 함수 본문에서 사라지지
  # 않았는지를 문자열로 확인한다.
  local absolute_time_label_body
  absolute_time_label_body=$(sed -n '/function absoluteTimeLabel(atMs, nowMs){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$absolute_time_label_body" ]]; then
    record_failure "$test_name" "T25-128: absoluteTimeLabel() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'sameDay' <<< "$absolute_time_label_body"; then
    note_failure "T25-128: absoluteTimeLabel() 에 sameDay 날짜 경계 분기가 없음"
  fi
  if ! grep -qE 'getMonth\(\) \+ 1' <<< "$absolute_time_label_body"; then
    note_failure "T25-128: absoluteTimeLabel() 에 다른 날 분기(M/D 표기)가 없음"
  fi

  # T25-129(상세 패널 iframe 흰 플래시 제거, 브라우저 계측 확인): 로딩 중인 iframe 을 숨겨
  # 내비게이션 커밋~새 문서 첫 페인트 사이의 UA 기본(흰) 캔버스가 보이지 않게 한다.
  # CSS 기본 규칙(visibility:hidden)·로드 완료 클래스·loadPanelDocument() 안에서 replace()
  # 직전에 클래스를 떼는 순서·load 리스너 등록까지 전부 확인한다.
  local detail_frame_css_rule
  detail_frame_css_rule=$(grep -oE '\.detail-frame\{[^}]*\}' "$hub_template_file" | head -1)
  if [[ "$detail_frame_css_rule" != *"visibility:hidden"* ]]; then
    note_failure "T25-129: .detail-frame{...} 기본 규칙에 visibility:hidden 이 없음"
  fi
  if ! grep -qF '.detail-frame.detail-frame-loaded{visibility:visible}' "$hub_template_file"; then
    note_failure "T25-129: .detail-frame.detail-frame-loaded{visibility:visible} 규칙이 없음"
  fi

  local load_panel_document_body
  load_panel_document_body=$(sed -n '/function loadPanelDocument(url){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$load_panel_document_body" ]]; then
    record_failure "$test_name" "T25-129: loadPanelDocument() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'classList.remove(PANEL_FRAME_LOADED_CLASS)' <<< "$load_panel_document_body"; then
    note_failure "T25-129: loadPanelDocument() 안에 로드 완료 클래스 제거가 없음"
  fi
  local frame_loaded_remove_line frame_loaded_replace_line
  frame_loaded_remove_line=$(grep -nF 'classList.remove(PANEL_FRAME_LOADED_CLASS)' <<< "$load_panel_document_body" | head -1 | cut -d: -f1)
  frame_loaded_replace_line=$(grep -nF 'location.replace(url)' <<< "$load_panel_document_body" | head -1 | cut -d: -f1)
  if [[ -z "$frame_loaded_remove_line" || -z "$frame_loaded_replace_line" \
        || "$frame_loaded_remove_line" -ge "$frame_loaded_replace_line" ]]; then
    note_failure "T25-129: loadPanelDocument() 에서 로드 완료 클래스 제거가 location.replace 보다 먼저 오지 않음(같은 동기 태스크에서 숨겨야 흰 캔버스가 한 프레임도 안 보인다)"
  fi

  if ! grep -qF "panelFrameEl.addEventListener('load'" "$hub_template_file"; then
    note_failure "T25-129: panelFrameEl 에 load 리스너 등록이 없음"
  fi
  local frame_load_listener_body
  frame_load_listener_body=$(sed -n "/panelFrameEl.addEventListener('load', function(){/,/});/p" "$hub_template_file")
  if ! grep -qF 'classList.add(PANEL_FRAME_LOADED_CLASS)' <<< "$frame_load_listener_body"; then
    note_failure "T25-129: load 리스너가 로드 완료 클래스를 붙이지 않음"
  fi

  # T25-130(state-stale 배지 툴팁): 판정 기준(30분)·마지막 이벤트/활동의 절대시각+경과
  # (absoluteTimeLabel·elapsedLabel 재사용)·escapeHtml 경유·stale 전용 부착을 확인한다.
  # 30 은 hub_model.HubConfig.stale_after_minutes 기본값과 결합된 클라이언트 하드코딩이다
  # (commands/dashboard.md 의 -mmin -30 과 같은 관례) — 셸은 서버 설정을 읽을 수 없으므로
  # 리터럴 자체의 존재만 확인한다.
  if ! grep -qF 'var STALE_AFTER_MINUTES = 30;' "$hub_template_file"; then
    note_failure "T25-130: STALE_AFTER_MINUTES=30 하드코딩 상수가 없음(hub_model.HubConfig.stale_after_minutes 기본값과 결합)"
  fi

  local stale_tooltip_fn_body
  stale_tooltip_fn_body=$(sed -n '/function staleBadgeTooltipText(lastActivityAtMs, baseState, nowMs){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$stale_tooltip_fn_body" ]]; then
    record_failure "$test_name" "T25-130: staleBadgeTooltipText() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'absoluteTimeLabel(lastActivityAtMs, nowMs)' <<< "$stale_tooltip_fn_body" \
     || ! grep -qF 'elapsedLabel(lastActivityAtMs)' <<< "$stale_tooltip_fn_body"; then
    note_failure "T25-130: staleBadgeTooltipText() 가 absoluteTimeLabel·elapsedLabel 을 재사용하지 않음(새 포맷 함수 생성 의심)"
  fi

  # 앵커 갱신(결정 RI10, docs/prps/hub-rate-limit-interruption.md) — renderStateBadge() 가
  # interrupted 배지를 위해 4번째 인자(interruption)를 받는다. 세션 호출부도 그 인자를
  # 넘기도록 함께 갱신한다(프로젝트 호출부는 결정대로 3항 그대로 — RI7 §7 「호출부」).
  # 재조준(결정 BW9·BW10, docs/prps/hub-subagent-background-pause.md) — background 배지를
  # 위해 5번째 인자(backgroundWait)가 더해졌다. 세션 호출부도 함께 갱신한다(프로젝트 호출부는
  # 여전히 3항 그대로 — BW10 §7 「시그니처」).
  local render_state_badge_body
  render_state_badge_body=$(sed -n '/function renderStateBadge(state, baseState, lastActivityAtMs, interruption, backgroundWait){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$render_state_badge_body" ]]; then
    record_failure "$test_name" "T25-130: renderStateBadge() 범위 추출 실패 — 앵커가 깨졌다(시그니처가 5항이 아닐 수 있다)"
    return 1
  fi
  if ! grep -qF "state === 'stale'" <<< "$render_state_badge_body"; then
    note_failure "T25-130: renderStateBadge() 가 stale 상태만 골라 data-tooltip 을 붙이지 않음"
  fi
  if ! grep -qF 'escapeHtml(staleBadgeTooltipText(' <<< "$render_state_badge_body"; then
    note_failure "T25-130: renderStateBadge() 의 stale 툴팁이 escapeHtml 을 경유하지 않음"
  fi

  if ! grep -qF 'renderStateBadge(session.state, session.base_state, session.last_event_at_ms, session.interruption, session.background_wait)' "$hub_template_file"; then
    note_failure "T25-130: 세션 배지 호출부가 last_event_at_ms·interruption·background_wait 를 넘기지 않음"
  fi
  if ! grep -qF 'renderStateBadge(project.state, null, project.last_activity_at_ms)' "$hub_template_file"; then
    note_failure "T25-130: 프로젝트 배지 호출부가 last_activity_at_ms 를 넘기지 않음"
  fi

  # T25-131(결정 IR1, docs/prps/hub-panel-immediate-refresh.md — RENDERED_EVENT_NAME 관용구와
  # 동형): 'dzh:refresh-requested' 리터럴이 정확히 2건(렌더 IIFE·패널 IIFE 각 1 선언) 있다 —
  # 두 IIFE 는 서로의 변수를 모르므로 상수가 파일에 두 번 산다(T25-107 의 dzh:rendered 선례와
  # 같은 근거).
  local immediate_refresh_event_count
  immediate_refresh_event_count=$(grep -c "dzh:refresh-requested" "$hub_template_file")
  if [[ "$immediate_refresh_event_count" -ne 2 ]]; then
    record_failure "$test_name" "T25-131: 'dzh:refresh-requested' 리터럴이 ${immediate_refresh_event_count}건(기대 2)"
    return 1
  fi

  # T25-132(결정 IR2): 즉시 갱신 이벤트 발행이 pollNow() 함수 범위 안에 있다 — 발행 지점이
  # pollNow 1곳뿐이라는 계약을 검사한다(범위 추출 선례: T25-130 의 staleBadgeTooltipText()).
  local poll_now_fn_body
  poll_now_fn_body=$(sed -n '/function pollNow(isExplicitRequest){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$poll_now_fn_body" ]]; then
    record_failure "$test_name" "T25-132: pollNow() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'dispatchEvent(new CustomEvent(IMMEDIATE_REFRESH_EVENT_NAME' <<< "$poll_now_fn_body"; then
    record_failure "$test_name" "T25-132: pollNow() 안에 즉시 갱신 이벤트 발행이 없음"
    return 1
  fi

  # T25-133(개정 — 가시성 게이트 제거로 앵커 재고정, docs/prps/
  # hub-ungated-poll-and-stale-tab-self-heal.md 결정 SH1·GOTCHA 3): 옛 문자열 앵커
  # (`setInterval(function(){ if(document.visibilityState...`)는 게이트를 지우면 "줄을
  # 찾지 못함"으로 무력화된다 — 이 검사가 지키는 계약(IR2: 인터벌은 pollNow 를 쓰지 않는다)
  # 은 그대로 새 형태에 맞춰 재고정한다. 60초 인터벌이 여전히 poll 을 그대로 쓴다 — pollNow 로
  # 바뀌면 iframe 자체 폴링과 이중 폴링이 된다.
  local poll_interval_bare_ref_count poll_interval_pollnow_count
  poll_interval_bare_ref_count=$(grep -oF 'setInterval(poll, POLL_INTERVAL_MS)' "$hub_template_file" | wc -l | tr -d ' ')
  poll_interval_pollnow_count=$(grep -oF 'setInterval(pollNow' "$hub_template_file" | wc -l | tr -d ' ')
  if [[ "$poll_interval_bare_ref_count" -ne 1 || "$poll_interval_pollnow_count" -ne 0 ]]; then
    record_failure "$test_name" "T25-133: 60초 인터벌 형태가 어긋남(setInterval(poll, POLL_INTERVAL_MS) ${poll_interval_bare_ref_count}건·setInterval(pollNow ${poll_interval_pollnow_count}건, 이중 폴링 회귀/결정 IR2)"
    return 1
  fi

  # T25-134(정+역, GOTCHA 2 회귀 검출): pollNow( 호출이 정확히 3건이고 true 1·false 2로
  # 나뉜다. 리스너 인자 자리에 pollNow 를 맨몸으로 넘기면(", pollNow)") 첫 인자로 이벤트
  # 객체가 들어가 isExplicitRequest 가 항상 truthy 가 된다 — 결정 IR5 를 무력화하는 회귀다.
  # 정의 줄(function pollNow(...)) 은 호출이 아니므로 제외하고 센다.
  local poll_now_call_count poll_now_true_count poll_now_false_count poll_now_bare_ref_count
  poll_now_call_count=$(grep -v 'function pollNow(' "$hub_template_file" | grep -oF 'pollNow(' | wc -l | tr -d ' ')
  poll_now_true_count=$(grep -oF 'pollNow(true)' "$hub_template_file" | wc -l | tr -d ' ')
  poll_now_false_count=$(grep -oF 'pollNow(false)' "$hub_template_file" | wc -l | tr -d ' ')
  poll_now_bare_ref_count=$(grep -oE ', ?pollNow\)' "$hub_template_file" | wc -l | tr -d ' ')
  if [[ "$poll_now_call_count" -ne 3 || "$poll_now_true_count" -ne 1 || "$poll_now_false_count" -ne 2 \
      || "$poll_now_bare_ref_count" -ne 0 ]]; then
    record_failure "$test_name" "T25-134: pollNow 호출 형태가 어긋남(전체 ${poll_now_call_count}·true ${poll_now_true_count}·false ${poll_now_false_count}·맨몸참조 ${poll_now_bare_ref_count})"
    return 1
  fi

  # T25-135(정+역, 결정 IR4~IR8): refreshOpenPanelDocument() 가 가드 3종·기능 감지·명시적
  # 요청에서만 폴백 재로딩·예외 방어 코드 미사용을 모두 지킨다. 함수 범위 추출에만
  # record_failure+return 1 을 쓰고, 그 안의 네 단언(가드 3종·typeof·호출 순서·try 0건)은
  # 서로 독립이므로 각각 note_failure 로 보고한다(선례: T25-130 의 함수 범위 추출 후 독립
  # 단언 처리, 검수 MEDIUM R1).
  local refresh_open_panel_fn_body
  refresh_open_panel_fn_body=$(sed -n '/function refreshOpenPanelDocument(isExplicitRequest){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$refresh_open_panel_fn_body" ]]; then
    record_failure "$test_name" "T25-135: refreshOpenPanelDocument() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  local refresh_guard_token
  for refresh_guard_token in 'openPanelTarget === null' 'dashboardKey === null' 'PANEL_FRAME_LOADED_CLASS'; do
    if ! grep -qF -- "$refresh_guard_token" <<< "$refresh_open_panel_fn_body"; then
      note_failure "T25-135: refreshOpenPanelDocument() 에 가드($refresh_guard_token)가 없음"
    fi
  done
  if ! grep -qF 'typeof frameWindow[DASHBOARD_REFRESH_HOOK_NAME]' <<< "$refresh_open_panel_fn_body"; then
    note_failure "T25-135: refreshOpenPanelDocument() 에 typeof 기능 감지가 없음"
  fi
  local explicit_request_line loadpanel_fallback_line
  explicit_request_line=$(grep -n 'if(isExplicitRequest)' <<< "$refresh_open_panel_fn_body" | head -1 | cut -d: -f1)
  loadpanel_fallback_line=$(grep -n 'loadPanelDocument(' <<< "$refresh_open_panel_fn_body" | tail -1 | cut -d: -f1)
  if [[ -z "$explicit_request_line" || -z "$loadpanel_fallback_line" \
      || "$loadpanel_fallback_line" -lt "$explicit_request_line" ]]; then
    note_failure "T25-135: loadPanelDocument() 폴백이 if(isExplicitRequest) 뒤에 있지 않음(결정 IR5)"
  fi
  local refresh_fn_try_count
  refresh_fn_try_count=$(grep -c 'try' <<< "$refresh_open_panel_fn_body")
  if [[ "$refresh_fn_try_count" -ne 0 ]]; then
    note_failure "T25-135: refreshOpenPanelDocument() 에 try 가 ${refresh_fn_try_count}건 있음(결정 IR7)"
  fi

  # T25-136(교차 파일 일치, 선례: T25-1 의 HUB_FILE_COUNT·T25-84 의 3중 시간 일치): 허브의
  # DASHBOARD_REFRESH_HOOK_NAME 상수 값이 dashboard_template.html 의 window.<X> = poll; 과
  # 문자 단위로 같다 — 값을 하드코딩 비교하지 않고 양쪽에서 추출해 비교한다(오타는 조용한
  # 폴백으로 나타나 사람 눈으로는 못 잡는다, R-1).
  local hub_hook_name_value dashboard_hook_name_value
  hub_hook_name_value=$(grep -oE "DASHBOARD_REFRESH_HOOK_NAME = '[^']+'" "$hub_template_file" \
    | head -1 | sed -E "s/.*= '([^']+)'/\1/")
  dashboard_hook_name_value=$(grep -oE 'window\.[A-Za-z0-9_]+ = poll;' "$dashboard_template_file" \
    | head -1 | sed -E 's/window\.([A-Za-z0-9_]+) = poll;/\1/')
  if [[ -z "$hub_hook_name_value" || -z "$dashboard_hook_name_value" \
      || "$hub_hook_name_value" != "$dashboard_hook_name_value" ]]; then
    record_failure "$test_name" "T25-136: 훅 이름 불일치(허브 '${hub_hook_name_value}' vs 대시보드 '${dashboard_hook_name_value}')"
    return 1
  fi

  # T25-137(문서 정합, LG1 계열 역방향): hub/README.md 에 즉시 갱신 서술이 있고, 옛 단정
  # 문구 "이 갱신 메커니즘 자체는 한 줄도 바뀌지 않는다"가 사라졌다(결정 IR9).
  if ! grep -qF -- '즉시' "$hub_readme_file" || ! grep -qF -- '스크롤' "$hub_readme_file"; then
    note_failure "T25-137: hub/README.md 에 즉시 갱신 서술 토큰이 없음"
  fi
  if grep -qF -- '이 갱신 메커니즘 자체는 한 줄도 바뀌지 않는다' "$hub_readme_file"; then
    record_failure "$test_name" "T25-137: hub/README.md 에 옛 단정 문구가 남아 있음"
    return 1
  fi

  # T25-138(3자 교차 일치, docs/prps/hub-ungated-poll-and-stale-tab-self-heal.md 결정 SH4,
  # 선례: T25-136 의 훅 이름 교차 추출): HubSnapshot 필드명을 hub_model.py 에서 뽑아
  # hub_collect.py 의 대입, hub_template.html 의 참조에도 같은 이름이 쓰이는지 본다 —
  # 하드코딩 3중 비교 대신 이름을 한 곳에서 뽑아 나머지에서 찾는다.
  local template_stamp_field_name
  template_stamp_field_name=$(grep -oE 'template_stamp: str = ""' "$hub_model_file" \
    | grep -oE 'template_stamp' | head -1)
  if [[ -z "$template_stamp_field_name" ]]; then
    record_failure "$test_name" "T25-138: hub_model.py 에 template_stamp: str = \"\" 필드가 없음"
    return 1
  fi
  if ! grep -qF "${template_stamp_field_name}=" "$hub_collect_file"; then
    note_failure "T25-138: hub_collect.py 에 ${template_stamp_field_name}= 대입이 없음"
  fi
  if ! grep -qF "$template_stamp_field_name" "$hub_template_file"; then
    note_failure "T25-138: hub_template.html 에 $template_stamp_field_name 참조가 없음"
  fi

  # T25-139(정+역, 결정 SH3·SH5·GOTCHA 7): read_template_stamp() 가 sha256·read_bytes 를
  # 쓰고 OSError 를 흡수해 "" 를 돌려준다. read_text 로 되돌아가면 세대의 정의가 인코딩·
  # 개행 처리에 의존하게 된다.
  local read_template_stamp_fn_body
  read_template_stamp_fn_body=$(awk '/^def read_template_stamp\(\) -> str:/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_collect_file")
  if [[ -z "$read_template_stamp_fn_body" ]]; then
    record_failure "$test_name" "T25-139: read_template_stamp() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'hashlib.sha256' <<< "$read_template_stamp_fn_body"; then
    note_failure "T25-139: read_template_stamp() 에 hashlib.sha256 사용이 없음"
  fi
  if ! grep -qF 'read_bytes()' <<< "$read_template_stamp_fn_body"; then
    note_failure "T25-139: read_template_stamp() 에 read_bytes() 사용이 없음"
  fi
  if grep -qF 'read_text(' <<< "$read_template_stamp_fn_body"; then
    note_failure "T25-139: read_template_stamp() 에 read_text( 사용이 있음(결정 SH3 위반)"
  fi
  if ! grep -qF 'except OSError' <<< "$read_template_stamp_fn_body"; then
    note_failure "T25-139: read_template_stamp() 에 except OSError 처리가 없음(결정 SH5)"
  fi

  # T25-140(정+역, GOTCHA 1 회귀 검출): loadedTemplateStamp 는 IIFE 초기화 시점에 딱 한 번만
  # 포획돼야 하고(poll() 정의보다 앞), reloadForNewTemplateGeneration() 안에서는 절대
  # snapshot.template_stamp 를 직접 읽지 않아야 한다 — 비교 시점에 읽으면 이미 새 값을
  # 자기 자신과 비교하게 되어 화면상 증상 없이 기능이 죽는다(전제 4, 결정 SH7).
  local loaded_template_stamp_count loaded_template_stamp_line poll_fn_line
  loaded_template_stamp_count=$(grep -cF 'var loadedTemplateStamp =' "$hub_template_file")
  loaded_template_stamp_line=$(grep -n 'var loadedTemplateStamp =' "$hub_template_file" | head -1 | cut -d: -f1)
  poll_fn_line=$(grep -n '^  function poll(){$' "$hub_template_file" | head -1 | cut -d: -f1)
  if [[ "$loaded_template_stamp_count" -ne 1 ]]; then
    note_failure "T25-140: loadedTemplateStamp 대입이 ${loaded_template_stamp_count}건(기대 1)"
  fi
  if [[ -z "$loaded_template_stamp_line" || -z "$poll_fn_line" || "$loaded_template_stamp_line" -ge "$poll_fn_line" ]]; then
    note_failure "T25-140: loadedTemplateStamp 포획이 function poll(){ 보다 앞에 있지 않음(GOTCHA 1)"
  fi
  local reload_for_new_generation_fn_body
  reload_for_new_generation_fn_body=$(sed -n '/function reloadForNewTemplateGeneration(freshTemplateStamp){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$reload_for_new_generation_fn_body" ]]; then
    record_failure "$test_name" "T25-140: reloadForNewTemplateGeneration() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if grep -qF 'snapshot.template_stamp' <<< "$reload_for_new_generation_fn_body"; then
    note_failure "T25-140: reloadForNewTemplateGeneration() 안에서 snapshot.template_stamp 를 직접 읽음(GOTCHA 1 회귀)"
  fi

  # T25-141(정+역, 결정 SH6·SH9, GOTCHA 8): reloadForNewTemplateGeneration() 이 빈 문자열
  # 가드·루프 가드(readReloadedTemplateStamp)를 갖추고, 기록 성공을 리로드의 전제조건으로
  # 삼는다 — 반환값을 무시하고 호출만 하면(뮤테이션 5) 순서는 그대로라 줄번호 비교만으로는
  # 못 잡는다. 부정 패턴(`!rememberReloadTemplateStamp(`)의 존재로 "반환값이 실제로 게이트로
  # 쓰인다"를 직접 검사한다.
  if ! grep -qF "if(freshTemplateStamp === '') return false;" <<< "$reload_for_new_generation_fn_body"; then
    note_failure "T25-141: reloadForNewTemplateGeneration() 에 빈 문자열 가드가 없음(결정 SH6)"
  fi
  if ! grep -qF 'readReloadedTemplateStamp()' <<< "$reload_for_new_generation_fn_body"; then
    note_failure "T25-141: reloadForNewTemplateGeneration() 에 readReloadedTemplateStamp() 호출이 없음(결정 SH9)"
  fi
  if ! grep -qF '!rememberReloadTemplateStamp(' <<< "$reload_for_new_generation_fn_body"; then
    note_failure "T25-141: reloadForNewTemplateGeneration() 이 rememberReloadTemplateStamp() 반환값을 리로드의 전제조건으로 쓰지 않음(GOTCHA 8)"
  fi
  local remember_call_line location_reload_line location_reload_count
  remember_call_line=$(grep -n 'rememberReloadTemplateStamp(' <<< "$reload_for_new_generation_fn_body" | head -1 | cut -d: -f1)
  location_reload_line=$(grep -n 'location.reload()' <<< "$reload_for_new_generation_fn_body" | head -1 | cut -d: -f1)
  location_reload_count=$(grep -cF 'location.reload()' <<< "$reload_for_new_generation_fn_body")
  if [[ -z "$remember_call_line" || -z "$location_reload_line" || "$location_reload_line" -lt "$remember_call_line" ]]; then
    note_failure "T25-141: location.reload() 가 rememberReloadTemplateStamp( 보다 앞에 있음(GOTCHA 8)"
  fi
  if [[ "$location_reload_count" -ne 1 ]]; then
    note_failure "T25-141: reloadForNewTemplateGeneration() 안의 location.reload() 가 ${location_reload_count}건(기대 1)"
  fi

  # T25-142(정+역, 결정 SH11): 문서 정합 — README 의 자가 치유 서술·「알려진 한계」 2항목,
  # hub_template.html 머리 주석의 template_stamp 조항이 모두 있다.
  if ! grep -qF '자가 치유' "$hub_readme_file"; then
    note_failure "T25-142: hub/README.md 에 자가 치유 서술 토큰이 없음"
  fi
  if ! grep -qF '자가 치유 리로드' "$hub_readme_file" || ! grep -qF '패널·스크롤' "$hub_readme_file"; then
    note_failure "T25-142: hub/README.md 「알려진 한계」에 자가 치유 한계 2항목이 없음"
  fi
  local hub_template_head_comment
  hub_template_head_comment=$(sed -n '1,60p' "$hub_template_file")
  if ! grep -qF 'template_stamp' <<< "$hub_template_head_comment"; then
    note_failure "T25-142: hub_template.html 머리 주석에 template_stamp 조항이 없음"
  fi

  # T25-143(퇴역, dashboard-native-data-source PRP DN8): 자동 발행(로컬 http.server·포트
  # 각인·`serve`)이 통째로 폐기돼 `trap 'exit 0' TERM; python3 -m http.server` 기동 줄
  # 자체가 dashboard.md 어디에도 남지 않는다 — 검사할 대상이 없다(재앵커할 후속 개념도
  # 없다, 허브가 상주 서버라 대시보드 쪽 서버 기동 자체가 사라졌다). ID 번호는 예약해 둔다.

  # T25-144(정, docs/prps/dashboard-lead-tooltip-and-interaction-lockdown.md 결정 IL1~IL3):
  # hub_template.html 에 선택 차단 CSS 규칙과 우클릭 차단 리스너가 모두 있다.
  if ! grep -qF 'html{-webkit-user-select:none;user-select:none}' "$hub_template_file"; then
    note_failure "T25-144: hub_template.html 에 html{-webkit-user-select:none;user-select:none} 미발견"
  fi
  if ! grep -qF 'function preventNativeContextMenu(event){ event.preventDefault(); }' "$hub_template_file" \
    || ! grep -qF "document.addEventListener('contextmenu', preventNativeContextMenu);" "$hub_template_file"; then
    note_failure "T25-144: hub_template.html 에 contextmenu preventDefault 리스너 미발견"
  fi

  # T25-145(교차 파일, GOTCHA 7, 선례: T25-136 의 훅 이름 교차 추출·T25-1 의 파일 수 교차):
  # 두 템플릿의 html{...user-select...} 선언을 각각 뽑아 문자 단위로 비교한다 — 한쪽만
  # -webkit- 프리픽스를 잃는 표류를 하드코딩 비교 없이 감지한다.
  local hub_user_select_rule dashboard_user_select_rule
  hub_user_select_rule=$(grep -oE 'html\{[^}]*user-select[^}]*\}' "$hub_template_file" | head -1)
  dashboard_user_select_rule=$(grep -oE 'html\{[^}]*user-select[^}]*\}' "$dashboard_template_file" | head -1)
  if [[ -z "$hub_user_select_rule" || -z "$dashboard_user_select_rule" \
      || "$hub_user_select_rule" != "$dashboard_user_select_rule" ]]; then
    note_failure "T25-145: html{...user-select...} 선언이 두 템플릿에서 다름(허브 '${hub_user_select_rule}' vs 대시보드 '${dashboard_user_select_rule}')"
  fi

  # T25-146(정, 문서 정합, 선례: T25-137·T25-142 와 같은 형태, dashboard-into-hub.md M2
  # 재조준): hub/README.md 에 우클릭·선택 차단 서술 토큰이 있다(정) — 서버가 언제나 최신
  # 템플릿으로 렌더하므로(HD5) 파일 세대에 따라 잠금이 빠지는 경우 자체가 없어져 구세대
  # 조항 서브체크는 M2 에서 걷혔다(§5.3).
  if ! grep -qF '우클릭' "$hub_readme_file" || ! grep -qF '텍스트 선택' "$hub_readme_file"; then
    note_failure "T25-146: hub/README.md 에 우클릭·선택 차단 서술 토큰이 없음"
  fi

  # T25-147(개정·변조행 승급 — 카드 상세보기 정리 M2, 결정 MX5, docs/prps/hub-session-modal-cleanup.md
  # §10.1; 원래는 TC1 의 정방향 가드였다, docs/prps/hub-tier1-clamp-fix-and-session-model.md): 옛 주 검사(.tier1-active
  # 규칙을 뽑아 flex-shrink:0 을 본다)는 MX5 때 지웠고, 그 규칙 추출 자체도 세션 줄 정보 순서 개정(결정 LM4,
  # docs/prps/hub-session-row-layout-and-modal-size.md)이 .tier1-active 를 걷으며 함께 지웠다 — 지킬 대상이 없는 방어는
  # 두지 않는다(YAGNI). 아래 보조 검사만 남는다.

  # T25-147 보조(역, §2.5): .card 의 flex 아이템 자식 중 overflow:hidden 을 가지면서
  # flex-shrink/min-height 가드가 없는 것이 없다. 그 결함이 .tier1-active 하나에 격리됐던 것은 그것만
  # "overflow:hidden + 콘텐츠 높이 자동 최소 크기" 조합이었기 때문이다(§2.5 표) — 같은 조합을 가진 카드
  # 직계 자식이 생기면 같은 잘림이 재발한다. 목록은 지금 카드의 실제 직계 자식이다(project-head·path·
  # sessions — 진행률 세 클래스는 직계 자식에서 물러났다). .sessions 는 overflow-y:auto + 명시적
  # min-height:0 을 가진 의도된 축소 대상이라 이 패턴에 걸리지 않는다(화이트리스트가 아니라 애초에
  # overflow:hidden 이 아님).
  local card_child_selector
  for card_child_selector in project-head path sessions; do
    local card_child_rule
    card_child_rule=$(grep -oE "\\.${card_child_selector}\\{[^}]*\\}" "$hub_template_file" | head -1)
    if [[ "$card_child_rule" == *"overflow:hidden"* && "$card_child_rule" != *"flex-shrink"* \
        && "$card_child_rule" != *"min-height"* ]]; then
      note_failure "T25-147 보조: .$card_child_selector 가 overflow:hidden 이면서 flex-shrink/min-height 가드가 없음(§2.5 결함 확장 감지)"
    fi
  done

  # T25-148(삭제 — 결정 LM4, docs/prps/hub-session-row-layout-and-modal-size.md): 이 번호는 .tier1-active 의
  # display:-webkit-box·-webkit-line-clamp:2 (TC2)가 사라지지 않았는지 보던 역가드였다. 대상 줄이 걷히며 검사도 걷었다 —
  # 그 줄이 되살아나는 것은 T25-263 의 역방향(class="tier1-active" · .tier1-active{ 0건)이 막는다. 번호는 재사용하지 않는다
  # (T25-187·T25-191 의 선례와 같다).

  # T25-149(정+교차, 요구 2 — 배포 파일 수 15→16→18→19→21→23→25→26, docs/prps/
  # hub-tier1-clamp-fix-and-session-model.md → docs/prps/hub-workflow-visibility.md 1회차가
  # hub_redact.py·hub_workflow.py 를 더해 18로, 2회차가 hub_workflow_read.py 를 더해 19로,
  # docs/prps/hub-collect-split-for-merge.md 가 hub_config.py·hub_atomic_write.py 를 더해
  # 21로, docs/prps/hub-agent-runs-and-prompt-source.md 가 hub_subagent.py·
  # hub_subagent_read.py 를 더해 23으로, docs/prps/hub-live-session-native-source.md 가
  # hub_live_session.py·hub_live_session_read.py 를 더해 25로, docs/prps/
  # hub-subagent-liveness-signal.md §11 R4 가 예견한 후속 분리(결정 MS1 의 기존 절차)가
  # hub_server_state_read.py 를 더해 26으로, docs/prps/dashboard-into-hub.md M1(HD1)이
  # hub_dashboard_log.py·hub_dashboard_render.py·hub_dashboard_template.html 을 더해
  # 29로, docs/prps/hub-subagent-background-pause.md 결정 BW11(M1) 이 hub_session_facts.py
  # 를 더해 30으로, docs/prps/hub-usage-panel-account.md 결정 AC8 이 hub_account.py 를 더해
  # 31로, docs/prps/hub-live-activity.md 결정 LA14 가 hub_activity.py 를 더해 32로,
  # docs/prps/harness-benchmark-adoption.md ⑨ 가 hub_session_cost.py 를 더해 33으로,
  # docs/prps/harness-versioning.md 단계 B 가 hub_release.py·hub_release_read.py 를 더해 35로 갱신):
  # hub/install.sh 의 HUB_FILE_COUNT 가 35 이다. T25-1 은
  # "선언값==실제 파일 수"라는 일반 교차 검사라, 값이 이전 수에 머문 채 실제 파일 수도
  # 우연히 그 수로 되돌아가면(새 파일을 추가하며 다른 파일을 실수로 지운 경우) 잡지 못하는
  # 사각이 있다 — 이 값 자체를 35로 고정해 그 사각을 없앤다. hub/README.md 「파일 배치」의
  # 파일 수 서술도 함께 35로 갱신됐는지 본다.
  local declared_hub_file_count
  declared_hub_file_count=$(grep -oE '^readonly HUB_FILE_COUNT=[0-9]+' "$hub_install_file" | grep -oE '[0-9]+$')
  if [[ "$declared_hub_file_count" -ne 35 ]]; then
    note_failure "T25-149: hub/install.sh 의 HUB_FILE_COUNT=$declared_hub_file_count(기대 35)"
  fi
  if ! grep -qF '35개 파일' "$hub_readme_file"; then
    note_failure "T25-149: hub/README.md 「파일 배치」에 '35개 파일' 서술이 없음"
  fi

  # T25-150(정+역, 결정 FT7·GOTCHA 8 — 갱신: docs/prps/hub-subagent-background-pause.md 결정
  # BW9 가 background_wait 필드를 더해 "맨 뒤" 자리를 interruption → background_wait 으로
  # 다시 넘겼다. 그 앞서 docs/prps/hub-rate-limit-interruption.md 결정 RI8 이
  # tier1_is_finished_task → interruption 으로, docs/prps/hub-ui-4-issues.md 결정 FT7 이
  # workflow → tier1_is_finished_task 로, docs/prps/hub-workflow-visibility.md 결정 WF1 이
  # model → workflow 로 넘긴 적이 있다. 그리고 docs/prps/harness-benchmark-adoption.md ⑨ 가
  # session_cost 필드를 더해 "맨 뒤" 자리를 background_wait → session_cost 로 넘겼다):
  # hub_session.py 의 SessionView 에 model·workflow·tier1_is_finished_task·interruption·
  # background_wait 필드가 있고(자리는 더 이상 맨 뒤가 아니어도 된다 — 존재만 확인), 맨 뒤는
  # session_cost 이다 — dataclass 규칙상 기본값 없는 필드 뒤에
  # 기본값 있는 필드가 와야 하고, 어기면 모듈 임포트 자체가 TypeError 로 죽는다. 추출 범위는
  # 클래스 정의 바로 다음에 이미 있는 고정 주석 앵커(# ---- 세션 표시 상태 ----, M1(결정
  # BW11)로 재조준 — 예전 ^# ---- 내부 이벤트 필터 ---- 는 hub_session_facts.py 로 옮겨
  # hub_session.py 에서 사라졌다)로 끊어, 그 뒤 함수 본문의 "else:" 같은 우연한 오탐(콜론으로
  # 끝나는 들여쓰기 줄)이 섞이지 않게 한다.
  # 역: hub_transcript.py 는 여전히 ★순수다 — open(·Path·time.·os. 가 0건이어야 한다(PRP 결정,
  # tests/hub/test_hub_transcript.py 의 순수 계약과 같은 기준). GOTCHA 1(docs/prps/
  # hub-rate-limit-interruption.md) — time\. 정규식은 datetime.fromisoformat 의 "datetime."
  # 에도 우연히 걸린다("date" + "time." 로 쪼개 읽으면 "time." 부분 일치) — hub_usage.py 가
  # 이미 같은 ★순수 기준의 모듈에서 datetime 을 쓰므로, 정규식을 (^|[^A-Za-z_])time\. 로
  # 좁혀 datetime. 은 피하고(앞 글자가 알파벳/밑줄이면 제외) 단독 time.·os.time. 은 그대로 잡는다.
  local session_view_class_body
  session_view_class_body=$(awk '/^class SessionView:/{flag=1; next} flag && /^# ---- 세션 표시 상태 ----/{exit} flag{print}' "$hub_session_file")
  if [[ -z "$session_view_class_body" ]]; then
    record_failure "$test_name" "T25-150: SessionView 클래스 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'model: SessionModel | None = None' <<< "$session_view_class_body"; then
    note_failure "T25-150: SessionView 에 model: SessionModel | None = None 필드가 없음"
  fi
  if ! grep -qF 'workflow: WorkflowRunView | None = None' <<< "$session_view_class_body"; then
    note_failure "T25-150: SessionView 에 workflow: WorkflowRunView | None = None 필드가 없음"
  fi
  if ! grep -qF 'tier1_is_finished_task: bool = False' <<< "$session_view_class_body"; then
    note_failure "T25-150: SessionView 에 tier1_is_finished_task: bool = False 필드가 없음"
  fi
  if ! grep -qF 'interruption: SessionInterruption | None = None' <<< "$session_view_class_body"; then
    note_failure "T25-150: SessionView 에 interruption: SessionInterruption | None = None 필드가 없음"
  fi
  if ! grep -qF 'background_wait: BackgroundWait | None = None' <<< "$session_view_class_body"; then
    note_failure "T25-150: SessionView 에 background_wait: BackgroundWait | None = None 필드가 없음"
  fi
  local session_view_last_field_line
  # [a-z0-9_]+(숫자 포함) — 결정 FT7 의 필드명 tier1_is_finished_task 가 숫자를 포함해
  # 옛 [a-z_]+(숫자 없음, "model"·"workflow" 시절 그대로도 충분했다)로는 이 필드가
  # 매치되지 않고 앞선 workflow 줄이 "마지막"으로 오판됐다(발견: 이 개정으로 실제 실패
  # 재현).
  session_view_last_field_line=$(grep -E '^\s+[a-z0-9_]+:' <<< "$session_view_class_body" | tail -1)
  if [[ "$session_view_last_field_line" != *'session_cost: SessionCost | None = None'* ]]; then
    note_failure "T25-150: SessionView 의 마지막 필드가 session_cost 가 아님(GOTCHA 8) — '$session_view_last_field_line'"
  fi
  local hub_transcript_file="$REPO_ROOT/hub/bin/hub_transcript.py"
  if grep -qE 'open\(|Path\(|(^|[^A-Za-z_])time\.|os\.' "$hub_transcript_file"; then
    note_failure "T25-150: hub_transcript.py 에 순수 계약 위반 흔적(open(/Path(/time./os.)이 있음"
  fi

  # T25-151(정+역, 요구 2, §6.4): 템플릿에 .session-model · MODEL_LABEL_MAX_CHARS ·
  # sessionModelLabel · renderSessionModel 이 모두 있다. 역: .session-model 규칙에 새 색
  # 리터럴이 없고(G9, 기존 --muted 상속 관례 유지) overflow:hidden 도 없다(§3.10 GOTCHA —
  # 가로 flex 형제가 짓눌려 줄 높이가 2배로 붕괴하는, 요구 1과 같은 계열의 함정).
  if ! grep -qF '.session-model{' "$hub_template_file"; then
    note_failure "T25-151: hub_template.html 에 .session-model 규칙이 없음"
  fi
  if ! grep -qF 'var MODEL_LABEL_MAX_CHARS = 10;' "$hub_template_file"; then
    note_failure "T25-151: hub_template.html 에 MODEL_LABEL_MAX_CHARS = 10 상수가 없음"
  fi
  if ! grep -qF 'function sessionModelLabel(model){' "$hub_template_file"; then
    note_failure "T25-151: hub_template.html 에 sessionModelLabel(model) 함수가 없음"
  fi
  if ! grep -qF 'function renderSessionModel(model){' "$hub_template_file"; then
    note_failure "T25-151: hub_template.html 에 renderSessionModel(model) 함수가 없음"
  fi
  local session_model_rule
  session_model_rule=$(grep -oE '\.session-model\{[^}]*\}' "$hub_template_file" | head -1)
  if [[ "$session_model_rule" == *"#"* ]]; then
    note_failure "T25-151: .session-model 규칙에 # 색 리터럴이 있음(G9 위반)"
  fi
  if [[ "$session_model_rule" == *"overflow:hidden"* ]]; then
    note_failure "T25-151: .session-model 규칙에 overflow:hidden 이 있음(§3.10 GOTCHA)"
  fi

  # T25-152(정+역, 문서 정합, 선례: T25-137·T25-142·T25-146 과 같은 형태): hub/README.md
  # 「프라이버시 고지」에 transcript 읽기 조항, 「화면 배치」에 모델·effort 서술이 있다(정).
  # 역: 「알려진 한계」에 "transcript 없는 세션은 표시되지 않는다" 계열 조항이 있다.
  if ! grep -qF 'transcript' "$hub_readme_file" || ! grep -qF '128KiB' "$hub_readme_file"; then
    note_failure "T25-152: hub/README.md 「프라이버시 고지」에 transcript 꼬리 읽기 조항이 없음"
  fi
  if ! grep -qF '지금 쓰고 있는 모델과 노력(effort)' "$hub_readme_file"; then
    note_failure "T25-152: hub/README.md 「화면 배치」에 모델·effort 서술이 없음"
  fi
  if ! grep -qF 'transcript 가 없는 세션은 모델이 표시되지 않는다' "$hub_readme_file"; then
    note_failure "T25-152: hub/README.md 「알려진 한계」에 transcript 부재 한계 조항이 없음"
  fi

  # T25-153(정+역, MC1·MC4, docs/prps/impl-panel-dispatch-unit-and-session-meta-chips.md):
  # 칩 공유 규칙 '.session-id,.session-model{…}' 이 존재하고 그 안에 background:var(--soft) ·
  # padding:0 6px 이 있다(정). 역: 그 규칙에 # 색 리터럴이 없고, overflow:hidden 이 없다
  # (§4.3 의 F·G 기각 근거를 기계화 — 세로 패딩이 슬며시 들어와 줄 높이가 늘어나는 회귀를
  # 잡는다, GOTCHA 6).
  local session_chip_shared_rule
  session_chip_shared_rule=$(grep -oE '\.session-id,\.session-model\{[^}]*\}' "$hub_template_file" | head -1)
  if [[ -z "$session_chip_shared_rule" ]]; then
    record_failure "$test_name" "T25-153: 칩 공유 규칙 '.session-id,.session-model{…}' 미발견"
    return 1
  fi
  if [[ "$session_chip_shared_rule" != *'background:var(--soft)'* ]]; then
    note_failure "T25-153: 칩 공유 규칙에 background:var(--soft) 없음"
  fi
  if [[ "$session_chip_shared_rule" != *'padding:0 6px'* ]]; then
    note_failure "T25-153: 칩 공유 규칙에 padding:0 6px 없음(세로 패딩 회귀 가능성)"
  fi
  if [[ "$session_chip_shared_rule" == *'#'* ]]; then
    note_failure "T25-153: 칩 공유 규칙에 # 색 리터럴이 있음"
  fi
  if [[ "$session_chip_shared_rule" == *'overflow:hidden'* ]]; then
    note_failure "T25-153: 칩 공유 규칙에 overflow:hidden 이 있음(§3.10 GOTCHA)"
  fi

  # T25-154(정, MC5): var MODEL_LABEL_MAX_CHARS = 10; 이고, 그 위 주석에 '시작 12/25' 와
  # '278px' 이 있다 — 형식 의존성 근거가 사라지면 다음 라운드가 상한을 다시 18로 올릴 수 있다.
  local model_label_const_context
  model_label_const_context=$(grep -B 12 -F 'var MODEL_LABEL_MAX_CHARS = 10;' "$hub_template_file")
  if [[ -z "$model_label_const_context" ]]; then
    record_failure "$test_name" "T25-154: MODEL_LABEL_MAX_CHARS = 10 주변 주석 추출 실패"
    return 1
  fi
  if ! grep -qF '시작 12/25' <<< "$model_label_const_context"; then
    note_failure "T25-154: MODEL_LABEL_MAX_CHARS 주석에 '시작 12/25' 형식 의존성 근거 미발견"
  fi
  if ! grep -qF '278px' <<< "$model_label_const_context"; then
    note_failure "T25-154: MODEL_LABEL_MAX_CHARS 주석에 '278px' 하한 근거 미발견"
  fi

  # T25-155(정, 문서 정합): hub/README.md 「화면 배치」에 세션 ID·모델이 칩으로 보인다는
  # 서술과 10자 상한이 있다.
  if ! grep -qF '**칩**' "$hub_readme_file"; then
    note_failure "T25-155: hub/README.md 「화면 배치」에 세션 ID·모델이 칩으로 보인다는 서술 미발견"
  fi
  if ! grep -qF '표시 상한 **10자**' "$hub_readme_file"; then
    note_failure "T25-155: hub/README.md 「화면 배치」에 '10자' 표시 상한 서술 미발견"
  fi

  # T25-156(존재, docs/prps/hub-session-tree-and-per-session-dashboards.md 결정 ST9·ST13·
  # ST14): hub_project.py 에 세션별 대시보드 디렉토리 상수와 레지스트리 조립 함수
  # tier1_file_path·dashboard_file_key 가 있다.
  if ! grep -qF 'SESSION_DASHBOARDS_RELATIVE_DIRECTORY = ".claude/dashboards"' "$hub_project_file"; then
    note_failure "T25-156: hub_project.py 에 SESSION_DASHBOARDS_RELATIVE_DIRECTORY = \".claude/dashboards\" 상수가 없음"
  fi
  if ! grep -qF 'def tier1_file_path(' "$hub_project_file"; then
    note_failure "T25-156: hub_project.py 에 def tier1_file_path( 가 없음"
  fi
  if ! grep -qF 'def dashboard_file_key(' "$hub_project_file"; then
    note_failure "T25-156: hub_project.py 에 def dashboard_file_key( 가 없음"
  fi

  # T25-157(정+역, 결정 ST14, T25-113 확장): hub_model.py 가 레지스트리 값 조립을
  # hub_project.tier1_file_path 한 곳에 위임한다. 역방향: 옛 조립("/" + PROJECT_DASHBOARD_
  # RELATIVE_PATH 문자열 접합)이 세션 항목 추가를 계기로 되살아나지 않았다.
  if ! grep -qF 'tier1_file_path(' "$hub_model_file"; then
    note_failure "T25-157: hub_model.py 에 tier1_file_path( 호출이 없음"
  fi
  if grep -qF '"/" + PROJECT_DASHBOARD_RELATIVE_PATH' "$hub_model_file"; then
    note_failure "T25-157: hub_model.py 에 옛 조립(\"/\" + PROJECT_DASHBOARD_RELATIVE_PATH)이 남아 있음(T25-113 되돌림)"
  fi
  # T25-157 확장(검수 2회차 B-4): hub_model.py 는 이제 PROJECT_DASHBOARD_RELATIVE_PATH 를 import
  # 조차 하지 않아 위 grep 은 그 상수를 참조하는 조립만 잡는다 — 새 문자열 리터럴로 다시
  # 조립하는 형태(예: project.path + "/" + ".claude/dashboard.html")는 통과시켜 이빨이 빈다.
  # "/" + 문자열 접합 자체가 0건이어야 한다는 조건으로 그 구멍을 막는다.
  if grep -qF '"/" +' "$hub_model_file"; then
    note_failure "T25-157: hub_model.py 에 \"/\" + 문자열 접합이 있음 — 경로 조립이 tier1_file_path 밖에서 부활했을 수 있음(T25-113 되돌림)"
  fi

  # T25-158(정합, 선례: T25-136 의 dzRequestRefresh 비교, docs/prps/dashboard-into-hub.md M1
  # 로 대상 재조준): hub/README.md 「대시보드 경로 규칙」 절의 .claude/dashboards 리터럴과
  # hub_project.py 의 SESSION_DASHBOARDS_RELATIVE_DIRECTORY 상수 값이 같아야 한다. 그 절은
  # M1 이 아직 신설하지 않았을 수 있다 — CLAUDE_CODE_SESSION_ID 마커 부재로 그 상태를
  # 감지해 이번 회차는 건너뛰고(M2 단독 배포 시점에도 성립시키기 위함), M1 착수 후에는
  # 정상적으로 값 불일치를 잡는다.
  local session_dashboards_relative_directory_value
  session_dashboards_relative_directory_value=$(grep -oE 'SESSION_DASHBOARDS_RELATIVE_DIRECTORY = "[^"]+"' "$hub_project_file" \
    | head -1 | sed -E 's/.*= "([^"]+)"/\1/')
  if [[ -z "$session_dashboards_relative_directory_value" ]]; then
    note_failure "T25-158: hub_project.py 에서 SESSION_DASHBOARDS_RELATIVE_DIRECTORY 상수를 추출하지 못함"
  elif grep -qF 'CLAUDE_CODE_SESSION_ID' "$dashboard_command_file" \
      && ! grep -qF "$session_dashboards_relative_directory_value" "$dashboard_command_file"; then
    note_failure "T25-158: hub/README.md 경로 규칙에 hub_project.py 상수 값(${session_dashboards_relative_directory_value})이 없음"
  fi

  # T25-159(개정 2 — hub-unified-card-tree-ui PRP §10.1, 결정 U1·U12): 보기 모드 개념 자체가
  # 사라지므로(모드 이원화 폐기) 이 가드의 의미가 「보기 모드 저장 키가 1곳」에서 「보기 모드
  # 잔재가 0곳」으로 뒤집힌다. 그 자리를 대신하는 새 사용자 상태 키(dzh-expanded-projects)에는
  # 같은 2중 검사 형태(리터럴 수 + 줄 앵커)를 그대로 복제한다 — 그 형태의 근거는 개정 1 때
  # 실측으로 남겼다: 리터럴 카운트만으로는 "선언을 주석 처리한" 뮤테이션을 못 잡는다(검수
  # 2회차 B-1). 줄 시작을 "  var" 로 고정하는 앵커라야 "//" 접두가 붙는 위장을 잡는다.
  # 개정 3(이슈 1, docs/prps/hub-ui-4-issues.md §2, 결정 TR1) — 카드 트리가 상시 표시가
  # 되며 확장 토글·localStorage 영속 자체가 사라진다(U1~U7·U9 번복). 아래 두 검사의
  # 기대값이 「1(상수 선언 1곳만)」에서 「0(상수 자체가 없다)」으로 다시 뒤집힌다 — 잔재
  # 역가드다(T25-186 → T25-190 선례).
  local view_mode_relic_count_159 view_mode_prefix_relic_count_159 view_toggle_id_relic_count_159
  local view_icon_relic_count_159 view_toggle_class_relic_count_159
  local view_cards_relic_count_159 view_tree_relic_count_159 aria_pressed_relic_count_159
  view_mode_relic_count_159=$(grep -c "dzh-view-mode" "$hub_template_file")
  view_mode_prefix_relic_count_159=$(grep -c "VIEW_MODE_" "$hub_template_file")
  view_toggle_id_relic_count_159=$(grep -c "dzh-view-toggle" "$hub_template_file")
  view_icon_relic_count_159=$(grep -c "view-icon-" "$hub_template_file")
  view_toggle_class_relic_count_159=$(grep -cF '.view-toggle' "$hub_template_file")
  if [[ "$view_mode_relic_count_159" -ne 0 || "$view_mode_prefix_relic_count_159" -ne 0 \
      || "$view_toggle_id_relic_count_159" -ne 0 || "$view_icon_relic_count_159" -ne 0 \
      || "$view_toggle_class_relic_count_159" -ne 0 ]]; then
    note_failure "T25-159: 보기 모드 잔재가 남아 있음(dzh-view-mode ${view_mode_relic_count_159}·VIEW_MODE_ ${view_mode_prefix_relic_count_159}·dzh-view-toggle ${view_toggle_id_relic_count_159}·view-icon- ${view_icon_relic_count_159}·.view-toggle ${view_toggle_class_relic_count_159}, 기대 전부 0)"
  fi
  view_cards_relic_count_159=$(grep -c "dzh-view-cards" "$hub_template_file")
  view_tree_relic_count_159=$(grep -c "dzh-view-tree" "$hub_template_file")
  aria_pressed_relic_count_159=$(grep -c "aria-pressed" "$hub_template_file")
  if [[ "$view_cards_relic_count_159" -ne 0 || "$view_tree_relic_count_159" -ne 0 ]]; then
    note_failure "T25-159: 옛 2버튼 잔재(dzh-view-cards ${view_cards_relic_count_159}건·dzh-view-tree ${view_tree_relic_count_159}건, 기대 둘 다 0)"
  fi
  if [[ "$aria_pressed_relic_count_159" -ne 0 ]]; then
    note_failure "T25-159: aria-pressed 잔재가 ${aria_pressed_relic_count_159}건(기대 0 — 통합 후 동작 라벨 규약으로 완전히 대체돼야 한다)"
  fi
  local expanded_key_literal_count_159 expanded_key_declaration_count_159
  expanded_key_literal_count_159=$(grep -c "dzh-expanded-projects" "$hub_template_file")
  if [[ "$expanded_key_literal_count_159" -ne 0 ]]; then
    note_failure "T25-159: 'dzh-expanded-projects' 리터럴이 ${expanded_key_literal_count_159}건(기대 0 — 카드 트리 기본화로 확장 상태 저장 자체가 사라졌다, TR1)"
  fi
  expanded_key_declaration_count_159=$(grep -cE "^  var EXPANDED_PROJECTS_STORAGE_KEY = 'dzh-expanded-projects';$" "$hub_template_file")
  if [[ "$expanded_key_declaration_count_159" -ne 0 ]]; then
    note_failure "T25-159: EXPANDED_PROJECTS_STORAGE_KEY 상수 선언이 ${expanded_key_declaration_count_159}건(기대 0 — TR1 로 삭제됐어야 한다)"
  fi

  # T25-160(개정 — hub-unified-card-tree-ui PRP §10.1, 결정 U2): 소비자가 renderProject
  # 하나뿐이 된 뒤에도 "공유 강제"는 유효하다 — 의미가 "필터를 우회하지 않는다"로 좁아질
  # 뿐이다. renderProjectTree( 는 트리 폐기(U2)로 존재 자체가 회귀이므로 0건을 요구하는
  # 방향으로 뒤집는다.
  if grep -qF 'function renderProjectTree(' "$hub_template_file"; then
    note_failure "T25-160: hub_template.html 에 function renderProjectTree( 가 남아 있음(U2 위반)"
  fi
  if ! grep -qF 'function visibleSessionsOf(' "$hub_template_file"; then
    note_failure "T25-160: hub_template.html 에 function visibleSessionsOf( 가 없음"
  fi
  local render_project_body_160
  render_project_body_160=$(sed -n '/function renderProject(project){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$render_project_body_160" ]]; then
    note_failure "T25-160: renderProject() 범위 추출 실패 — 앵커가 깨졌다"
  else
    if ! grep -qF 'visibleSessionsOf(' <<< "$render_project_body_160"; then
      note_failure "T25-160: renderProject() 이 visibleSessionsOf( 를 호출하지 않음"
    fi
    if grep -qF '.filter(shouldRenderSession)' <<< "$render_project_body_160"; then
      note_failure "T25-160: renderProject() 에 .filter(shouldRenderSession) 직접 호출이 남아있음(공유 위반)"
    fi
  fi

  # T25-161(신설, M3, 결정 ST26, T25-107 관용구): 세션 노드의 신원 속성 3개
  # (data-session-id·data-session-short-id·data-project-name) 모두 리터럴이 정확히 2건
  # (렌더 상수 선언 1 + 패널 상수 선언 1 — 공유 스코프가 없어 리터럴이 두 곳에 산다) 이고,
  # escapeHtml(session.session_id) 호출이 2건 이상(세션 메타 칩 + 트리 노드 속성)이다.
  # 애초 data-session-id 만 검사 대상이었다(검수 1회차 지적) — 나머지 둘은 렌더 쪽이
  # 인라인 리터럴이라 값이 어긋나도(오타) 잡는 검사가 없었다: getAttribute 가 null 을 주고
  # 패널 제목이 "{프로젝트} · 세션 null" 이 되는 조용한 실패다. 이제 세 속성 모두 렌더 쪽에도
  # 상수가 있으므로 같은 계수 규칙으로 셋 다 검사한다.
  local data_session_id_count_161 data_session_short_id_count_161 data_project_name_count_161
  local escape_session_id_count_161
  data_session_id_count_161=$(grep -c "data-session-id" "$hub_template_file")
  if [[ "$data_session_id_count_161" -ne 2 ]]; then
    note_failure "T25-161: 'data-session-id' 리터럴이 ${data_session_id_count_161}건(기대 2 — 렌더 상수 1 + 패널 상수 1)"
  fi
  data_session_short_id_count_161=$(grep -c "data-session-short-id" "$hub_template_file")
  if [[ "$data_session_short_id_count_161" -ne 2 ]]; then
    note_failure "T25-161: 'data-session-short-id' 리터럴이 ${data_session_short_id_count_161}건(기대 2 — 렌더 상수 1 + 패널 상수 1)"
  fi
  data_project_name_count_161=$(grep -c "data-project-name" "$hub_template_file")
  if [[ "$data_project_name_count_161" -ne 2 ]]; then
    note_failure "T25-161: 'data-project-name' 리터럴이 ${data_project_name_count_161}건(기대 2 — 렌더 상수 1 + 패널 상수 1)"
  fi
  escape_session_id_count_161=$(grep -c 'escapeHtml(session\.session_id)' "$hub_template_file")
  if [[ "$escape_session_id_count_161" -lt 2 ]]; then
    note_failure "T25-161: escapeHtml(session.session_id) 호출이 ${escape_session_id_count_161}건(기대 2건 이상)"
  fi

  # T25-162(분할 — hub-unified-card-tree-ui PRP §10.1, 결정 U2): 트리 연결선 존재·트리 전용
  # 회귀 검사 4종(루트 폭·열림 강조·톤다운 축소)은 트리 폐기와 함께 대체 없이 사라진다 —
  # 검사 대상 자체가 없어졌다. <style> 블록 순수성(외부 리소스 참조 0건, PV9 — file:// 에서도
  # 열려야 한다)만 트리와 무관한 독립 계약이라 그대로 남는다.
  local style_block_162
  style_block_162=$(sed -n '/^<style>/,/^<\/style>/p' "$hub_template_file")
  if [[ -z "$style_block_162" ]]; then
    note_failure "T25-162: <style> 블록 앵커를 찾지 못함 — 앵커가 깨졌다"
  elif grep -qE '<script[^>]*src=|@import|https://' <<< "$style_block_162"; then
    note_failure "T25-162: <style> 블록에 외부 리소스 참조(<script src=·@import·https://)가 있음(PV9 위반)"
  fi

  # T25-163(신설, M3, 결정 ST23·ST25, M2 복수형 개정 — docs/prps/
  # hub-session-modal-and-partial-update.md 결정 SC7): 패널 IIFE 에 SESSION_ID_ATTRIBUTE·
  # findOpenTargetElements( (복수형 — 같은 신원이 목록·모달 두 곳에 있을 수 있어 배열을
  # 돌려준다) 가 있고 옛 findCardByProjectPath( ·단수형 findOpenTargetElement( 는 없다.
  # applyOpenCardMarking() 본문이 그 배열을 루프(targets.length)로 순회한다 — 순회 없이
  # 첫 요소만 쓰면 모달 쪽 표시가 조용히 빠진다(SC7 회귀). isSameDocument 판정식에
  # sessionId 비교가 포함된다(3성분 판정, ST25).
  local panel_iife_start_line_163
  panel_iife_start_line_163=$(grep -n 'var PANEL_OPEN_BODY_CLASS' "$hub_template_file" | head -1 | cut -d: -f1)
  if [[ -z "$panel_iife_start_line_163" ]]; then
    note_failure "T25-163: hub_template.html 에 var PANEL_OPEN_BODY_CLASS 를 찾지 못함 — 앵커가 깨졌다"
  else
    local panel_iife_body_163
    panel_iife_body_163=$(tail -n "+$panel_iife_start_line_163" "$hub_template_file")
    if ! grep -qF 'SESSION_ID_ATTRIBUTE' <<< "$panel_iife_body_163"; then
      note_failure "T25-163: 패널 IIFE 에 SESSION_ID_ATTRIBUTE 가 없음"
    fi
    if ! grep -qF 'function findOpenTargetElements(' <<< "$panel_iife_body_163"; then
      note_failure "T25-163: 패널 IIFE 에 function findOpenTargetElements( 이 없음"
    fi
    if grep -qF 'function findCardByProjectPath(' <<< "$panel_iife_body_163"; then
      note_failure "T25-163: 패널 IIFE 에 옛 function findCardByProjectPath( 이 남아 있음(ST23 회귀)"
    fi
    if grep -qF 'function findOpenTargetElement(' <<< "$panel_iife_body_163"; then
      note_failure "T25-163: 패널 IIFE 에 옛 단수형 function findOpenTargetElement( 이 남아 있음(결정 SC7 회귀)"
    fi
    local apply_open_card_marking_body_163
    apply_open_card_marking_body_163=$(sed -n '/function applyOpenCardMarking(){/,/^  }$/p' "$hub_template_file")
    if [[ -z "$apply_open_card_marking_body_163" ]]; then
      note_failure "T25-163: applyOpenCardMarking() 범위 추출 실패 — 앵커가 깨졌다"
    elif ! grep -qF 'targets.length' <<< "$apply_open_card_marking_body_163"; then
      note_failure "T25-163: applyOpenCardMarking() 본문이 targets.length 로 순회하지 않음(결정 SC7 위반 — 모달 쪽 표시가 빠질 수 있다)"
    fi
  fi
  local is_same_document_line_163
  is_same_document_line_163=$(grep -n 'var isSameDocument' "$hub_template_file" | head -1 | cut -d: -f1)
  if [[ -z "$is_same_document_line_163" ]]; then
    note_failure "T25-163: isSameDocument 판정식을 찾지 못함 — 앵커가 깨졌다"
  else
    local is_same_document_expr_163
    is_same_document_expr_163=$(sed -n "${is_same_document_line_163},$((is_same_document_line_163+6))p" "$hub_template_file" | sed -n '1,/;/p')
    if ! grep -qF 'sessionId' <<< "$is_same_document_expr_163"; then
      note_failure "T25-163: isSameDocument 판정식에 sessionId 비교가 없음(ST25 3성분 회귀)"
    fi
  fi

  # T25-164(역, 회귀 래칫 — 구현 2회차 검수 C-6, 구현 3회차로 세 번째 검사 재작성. 개정
  # (이슈 3, docs/prps/hub-ui-4-issues.md §4, 결정 WT2·WT6) — 워크플로우 칩 툴팁이
  # 제거되며 workflowChipTooltipText 자체가 사라진다(되돌림 방지는 T25-200 이 이어받는다)):
  # renderWorkflowChip 이 이 저장소 전체에서 가장 큰 신규 비신뢰 콘텐츠 표면
  # (label·선택 항목 E 채택 시 state 도 호스트 소유 파일에서 온다)인데 T25-11
  # (session.short_id)·T25-118·T25-130(state 배지) 같은 escapeHtml 회귀 가드가 없었다.
  # 긍정 검사는 workflowChipDisplayLabel 쪽 1개만 남는다(①의 workflowChipTooltipText
  # 경유 검사는 그 함수가 없으므로 삭제).
  if ! grep -qF 'escapeHtml(workflowChipDisplayLabel(' "$hub_template_file"; then
    note_failure "T25-164: renderWorkflowChip 의 표시 라벨이 escapeHtml 을 경유하지 않음"
  fi
  # 세 번째 검사(구현 3회차 검수 재작성, 이슈 3 로 대상 필드가 좁혀졌다): agent.label(·
  # 선택 항목 E 채택 시 agent.state) 필드 접근이 workflowChipDisplayLabel~renderWorkflowRun
  # 구간 **바깥**에서 새로 생기지 않는지를 겨냥한다 — "새 렌더 경로가 이 헬퍼들을 우회해
  # 필드를 직접 문자열에 꽂는" 것이 실제 사각이다. 끝 앵커를 renderWorkflowRun 으로 둔
  # 이유(개정) — E 채택 시 agent.state 를 읽는 errorClass 산식이 renderWorkflowChip 본문에
  # 있어, 그 함수까지 구간에 포함해야 그 참조가 "구간 안"으로 잡힌다(끝 앵커를
  # renderWorkflowChip 자신으로 두면 그 함수 본문이 구간 밖이 되어 오탐이 난다).
  local workflow_chip_helpers_body
  workflow_chip_helpers_body=$(awk '
    /^  function workflowChipDisplayLabel\(agent\)\{/{flag=1}
    /^  function renderWorkflowRun\(workflow\)\{/{exit}
    flag{print}
  ' "$hub_template_file")
  if [[ -z "$workflow_chip_helpers_body" ]]; then
    record_failure "$test_name" "T25-164: workflowChipDisplayLabel~renderWorkflowRun 사이 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  local raw_field_access_total raw_field_access_in_helpers
  raw_field_access_total=$(grep -oE 'agent\.(label|state)' "$hub_template_file" | wc -l | tr -d ' ')
  raw_field_access_in_helpers=$(grep -oE 'agent\.(label|state)' <<< "$workflow_chip_helpers_body" | wc -l | tr -d ' ')
  if [[ "$raw_field_access_total" -ne "$raw_field_access_in_helpers" ]]; then
    note_failure "T25-164: agent.label/state 가 workflowChipDisplayLabel~renderWorkflowRun 구간 바깥에서 직접 참조됨(전체 $raw_field_access_total, 구간 내부 $raw_field_access_in_helpers)"
  fi

  # T25-165(역, ★순수 계약 — 구현 2회차 검수 C-6): hub_workflow.py·hub_redact.py 는 새로
  # 추가된 ★순수 모듈인데(docs/prps/hub-workflow-visibility.md 결정 WF2·WF3), T25-150 이
  # hub_transcript.py 에 거는 것과 같은 검사가 이 둘에는 없었다. hub_redact.py 의 순수성은
  # 보안 요구다(WF3 — hub_hook 을 끌어들이면 순환 임포트가 생긴다).
  local hub_workflow_file="$REPO_ROOT/hub/bin/hub_workflow.py"
  local hub_redact_file="$REPO_ROOT/hub/bin/hub_redact.py"
  if grep -qE 'open\(|Path\(|time\.|os\.' "$hub_workflow_file"; then
    note_failure "T25-165: hub_workflow.py 에 순수 계약 위반 흔적(open(/Path(/time./os.)이 있음"
  fi
  if grep -qE 'open\(|Path\(|time\.|os\.' "$hub_redact_file"; then
    note_failure "T25-165: hub_redact.py 에 순수 계약 위반 흔적(open(/Path(/time./os.)이 있음"
  fi

  # T25-166(역, 계약 A 정적 래칫 — 루프 밖 보완 HIGH-B): StringFieldLengthRatchetTest
  # (test_hub_workflow.py)는 dataclasses.fields() 를 순회하지만, 병리적 페이로드를 만드는
  # 픽스처(_agent_item·_run_json)가 소스 JSON 키를 하드코딩한다 — 새 문자열 필드가
  # 추가돼도 그 필드의 소스 키가 픽스처 오버라이드 목록에 없으면 파서가 빈 문자열을 만들어
  # 그 테스트가 조용히 통과한다(열거의 구멍이 어서션에서 픽스처로 옮겨진 것 — 검수가 사본에
  # 상한 없는 notes: str 필드를 추가해 실증했다). 이 정적 검사는 픽스처에 의존하지 않고
  # hub_workflow.py 의 생성자 호출부 자체를 검사한다: WorkflowAgentView·WorkflowRunView
  # 생성의 모든 키워드 인자 값이 승인된 상한 헬퍼(_scrubbed_and_clipped·_metadata_field·
  # _bounded_index·_parse_agents) 중 하나로 시작해야 한다.
  #
  # **개정(이슈 3, docs/prps/hub-ui-4-issues.md §4, 결정 WT3·WT4)**: phase_title·
  # prompt_preview·result_preview 3개 필드가 워크플로우 칩 툴팁 제거와 함께 빠지며
  # `_optional_scrubbed_and_clipped`(result_preview 전용 헬퍼)가 고아가 돼 삭제됐다 —
  # 승인 목록에서도 제거한다. 죽은 이름을 목록에 남기면 「승인된 헬퍼」가 허구가 된다(TR2
  # 와 같은 판단). `_metadata_field` 는 선택 항목 E 채택으로 state 필드가 남아 함께 남는다.
  #
  # **정정(이 판 — 검사 자체의 실효화 결함 수정)**: 이전 판은 `\w+=IDENT(` 한 정규식만
  # 썼고 "원천 차단한다"고 적었으나, 그 정규식은 값이 **직접 함수 호출**일 때만 반응해
  # `notes=item.get(...)`(점 표기)·`notes=item["x"]`(첨자)·`notes=RAW_DEFAULT`(원시 변수
  # 대입)가 전부 미탐지로 통과했다(재현 확인) — 이 검사가 막으려던 그 우회 자체가
  # 통과하면서 주석만 "막는다"고 단정한 것이었다.
  #
  # **기제**: kwarg 시작을 세 위치에서 승인 후보로 본다 — (1) 줄 시작의 `kwarg=`(여러
  # 줄로 펼친 호출, `_parse_agent_item` 의 WorkflowAgentView(...) 형태), (2) 생성자 이름의
  # 여는 괄호 바로 뒤의 `kwarg=`(한 줄로 붙은 호출의 첫 kwarg, `parse_workflow_run` 의
  # `WorkflowRunView(agents=...)` 형태 — 줄 시작 앵커만 쓰면 이 kwarg 자체가 검사망에서
  # 빠진다), (3) 콤마 바로 뒤의 `kwarg=`(한 줄로 붙은 호출에서 두 번째 이후 kwarg — (2)는
  # 여는 괄호 직후 첫 kwarg 만 잡으므로 그 뒤로 이어지는 kwarg 는 (3) 없이는 전부
  # 빠진다, MEDIUM-1·아래 추가 정정 참조). 잡은 뒤에는 `=` 다음이 승인 헬퍼 이름 + `(`
  # 로 **시작**하는지만 본다(그 뒤·안쪽은 안 본다 — 헬퍼가 중첩 호출을 인자로 받는 것은
  # 정상이다). `=` 바로 다음 문자가 다시 `=`이면 버린다(`==` 오탐 방지 — `!=`·`<=`·`>=`
  # 는 연산자 문자가 식별자와 `=` 사이에 끼어 있어 애초에 `kwarg=` 자체가 안 걸린다).
  #
  # **추가 정정(2회차 보완 — MEDIUM-1, 콤마로 이어 붙인 두 번째 kwarg 누락 수정)**: 위
  # (1)·(2) 어느 쪽에도 걸리지 않는 세 번째 형태가 있었다 — 한 줄 생성자에
  # `WorkflowRunView(agents=..., notes=payload.get("notes"))`처럼 콤마로 두 번째 kwarg
  # 를 이어 붙이면 그 kwarg 는 줄 시작도 생성자 여는 괄호 직후도 아니라서 전혀 수집되지
  # 않았다(검수 재현: 이 형태를 주입해도 미승인 목록이 비어 있었다). `WorkflowRunView`
  # 는 현재 한 줄 생성자라 여기 필드를 추가하는 가장 자연스러운 최소 diff 가 정확히 이
  # 모양이므로 원리적 한계가 아니라 현실적으로 재발하는 형태로 보고 (3)을 추가했다.
  #
  # **한계(이 기제에서 곧바로 따라온다)**: 실제 괄호 깊이를 세지 않고 세 텍스트 위치(줄
  # 시작·생성자 여는 괄호 직후·콤마 직후)만 보므로, 그 위치 밖의 kwarg 는 안 보고 그
  # 위치 안이면 몇 겹 중첩됐든 승인 후보로 본다. 비망라 예시: (a) 중첩 호출의 인자
  # 자체가 새 줄 시작에서 시작하는 kwarg 라면(현재 소스의 중첩은 전부 한 줄에 이어 쓰여
  # 있어 발동하지 않는다) 바깥 생성자 인자로 오인될 수 있다. (b) (3)은 콤마가 인자
  # 경계인지 따지지 않으므로, 승인 헬퍼 호출 **안쪽**의 콤마도 대상이 된다 — 트리거는
  # 둘이고 서로 독립이다. (b-1) 승인 헬퍼가 콤마로 구분된 여러 인자를 받게 바뀌는 경우
  # (현재 다섯 헬퍼는 전부 위치 인자 1개만 받아 발동하지 않는다). (b-2) **코드 구조를
  # 전혀 바꾸지 않고 문자열 리터럴 값만으로도** 같은 오탐이 난다 — 헬퍼에 넘기는 문자열
  # 안에 `,식별자=` 형태의 부분 문자열이 우연히 들어가면 그렇다(실측: `item.get("a,b")`
  # 는 안전하지만 `item.get("a,key=1")`·`item.get("a, k=2")` 는 오탐, `item.get("a,k==2")`
  # 는 `[^=]` 가드가 막아 안전). b-2 는 시그니처 변경이 필요 없어 b-1 보다 발생 문턱이
  # 낮다. 현재 소스에는 둘 다 없다(실측 확인). (c, MEDIUM-2 — 오탐, 거부된 축소안
  # 포함) "줄 시작"은 텍스트 위치일 뿐
  # "생성자 인자 목록 안"이라는 뜻이 아니다 — 같은 함수 본문에 `debug_flag=1`처럼 `=`
  # 앞뒤 공백 없는 지역 변수 대입이 있으면(실측 확인) 생성자 kwarg 가 전혀 아닌데도
  # (1)에 걸려 오탐을 낸다. 이 오탐을 줄이려고 (1)을
  # `^[[:space:]]*\w+=[A-Za-z_]\w*\(`(값이 식별자+괄호로 시작)로 좁히는 방안을
  # 검토했으나, 이 축소는 점 표기 값인 `notes=item.get(...)`(위 정정 문단의 1회차
  # 우회)를 다시 통과시킨다(`item.get(` 은 식별자 뒤에 `.`이 와서 매칭되지 않음 — 실측
  # 확인) — 좁히면 닫았던 원래 결함이 되살아나므로 채택하지 않았고, 이 한계로만 남긴다.
  # (d, LOW) `WorkflowRunView(**fields)`처럼 `**` 스플랫으로 kwarg 를 통째로 넘기면 세
  # 위치 전부 `\w+=` 형태를 전제하므로 원리적으로 못 잡는다(이 모듈은 스플랫 사용 0건).
  # 이 목록은 비망라이고, 텍스트 위치 휴리스틱이라는 사실 자체가 위에서 열거하지 않은
  # 우회 형태의 부재를 보장하지 않는다 — 전수 증명이 아니다.
  local approved_ctor_helpers='_scrubbed_and_clipped|_metadata_field|_bounded_index|_parse_agents'
  local parse_agent_item_body parse_workflow_run_body
  parse_agent_item_body=$(awk '
    /^def _parse_agent_item\(/{flag=1}
    /^def _parse_agents\(/{exit}
    flag{print}
  ' "$hub_workflow_file")
  parse_workflow_run_body=$(awk '
    /^def parse_workflow_run\(/{flag=1}
    flag{print}
  ' "$hub_workflow_file")
  if [[ -z "$parse_agent_item_body" || -z "$parse_workflow_run_body" ]]; then
    record_failure "$test_name" "T25-166: _parse_agent_item~parse_workflow_run 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  # kwarg 시작 후보 세 갈래(위 기제 참조): (1) 줄 시작 `^\s*kwarg=` — 여러 줄로 펼친
  # WorkflowAgentView(...) 형태. (2) 생성자 이름의 여는 괄호 직후 `kwarg=` — 한 줄로 붙은
  # WorkflowRunView(agents=...) 형태의 첫 kwarg. (3) 콤마 직후 `kwarg=` — 한 줄로 붙은
  # 호출에서 두 번째 이후 kwarg(MEDIUM-1, 위 추가 정정 참조). `=` 바로 다음 문자를
  # [^=]로 제한해 `==` 오탐을 막는다(`!=`·`<=`·`>=`는 연산자 문자가 식별자·`=` 사이에
  # 끼어 애초에 안 걸린다). 두 본문 다 세 패턴 전부를 대상으로 돌린다 — 어느 함수가
  # 어느 형태를 쓰는지 하드코딩하지 않기 위해서다(형태가 바뀌어도 검사가 계속 맞는
  # 갈래를 잡는다). 매치가 0건이면 grep 이 exit 1 을 내는데 set -euo pipefail 아래서
  # 파이프 앞단이라도 그대로 죽으므로(실측 확인) 여섯 grep 전부 `|| true` 로 막는다.
  local ctor_names='WorkflowAgentView|WorkflowRunView'
  local all_ctor_kwarg_calls unapproved_ctor_kwarg_calls
  all_ctor_kwarg_calls=$(
    { grep -oE '^[[:space:]]*\w+=[^=][^,]*' <<< "$parse_agent_item_body" || true
      grep -oE '^[[:space:]]*\w+=[^=][^,]*' <<< "$parse_workflow_run_body" || true
      grep -oE "($ctor_names)\(\w+=[^=][^,]*" <<< "$parse_agent_item_body" || true
      grep -oE "($ctor_names)\(\w+=[^=][^,]*" <<< "$parse_workflow_run_body" || true
      grep -oE ',[[:space:]]*\w+=[^=][^,]*' <<< "$parse_agent_item_body" || true
      grep -oE ',[[:space:]]*\w+=[^=][^,]*' <<< "$parse_workflow_run_body" || true
    } | sed -E "s/^[[:space:]]*(($ctor_names)\()?//; s/^,[[:space:]]*//" | sort -u
  )
  # 승인 판정은 접미(=$) 가 아니라 접두(^) 로 본다 — 위에서 이미 값 전체(중첩 호출 포함)를
  # 잡아 왔으므로 "승인 헬퍼로 시작하는가"만 확인하면 되고, 그 뒤에 뭐가 더 있는지는
  # (헬퍼가 자기 안에서 어떻게 값을 받는지는) 헬퍼 자신의 책임이라 여기서 다시 보지 않는다.
  unapproved_ctor_kwarg_calls=$(grep -vE "^\w+=($approved_ctor_helpers)\(" <<< "$all_ctor_kwarg_calls" || true)
  if [[ -n "$unapproved_ctor_kwarg_calls" ]]; then
    note_failure "T25-166: WorkflowAgentView/WorkflowRunView 생성자 인자가 승인된 상한 헬퍼를 거치지 않음 — $unapproved_ctor_kwarg_calls"
  fi

  # T25-167(정+역, 되돌림 방지 — T25-101 관용구, docs/prps/hub-collect-split-for-merge.md):
  # hub_config.py·hub_atomic_write.py 가 존재하고, 이동한 심볼의 정의가 hub_collect.py 에
  # 되살아나지 않았다. 되살아나면 실사용 경로와 테스트 대상이 갈라진다(read_server_record 의
  # 검수 m3 와 같은 실패 모드). 옮긴 뒤 공개 이름이 된 두 심볼(encode_safe_utf8·
  # atomic_write_text)은 옛 비공개 이름(되돌림을 잡는다)과 지금 이름(복사를 잡는다)을 함께
  # 든다 — 한쪽만 들면 다른 쪽을 못 잡는다. 나머지 셋은 hub_config.py 에서도 이름이 그대로다.
  local hub_collect_split_file
  for hub_collect_split_file in "$hub_config_file" "$hub_atomic_write_file"; do
    if [[ ! -f "$hub_collect_split_file" ]]; then
      record_failure "$test_name" "T25-167: $hub_collect_split_file 이 존재하지 않음"
      return 1
    fi
  done
  local hub_collect_split_relocated_def
  for hub_collect_split_relocated_def in 'def _validate_config_overrides(' 'def _clamp_interval_overrides(' \
      '_CONFIG_FIELD_TYPES' 'def _encode_safe_utf8(' 'def encode_safe_utf8(' 'def _atomic_write_text(' \
      'def atomic_write_text('; do
    if grep -qF -- "$hub_collect_split_relocated_def" "$hub_collect_file"; then
      note_failure "T25-167: hub_collect.py 에 이동한 심볼($hub_collect_split_relocated_def)이 남아 있음(hub_config.py·hub_atomic_write.py 로 이동했어야 함)"
    fi
  done

  # T25-245(신설, T25-167 바로 곁의 정방향 짝): T25-167 은 "옛 이름이 hub_collect.py 로
  # 되돌아오지 않았는가"만 본다. 이동한 심볼이 새 집에서 또 개명되면(예: encode_safe_utf8 →
  # 다른 이름) 그 새 이름으로의 복사를 T25-167 의 하드코딩된 옛 이름 목록은 잡지 못한다 —
  # 조용히 눈이 먼다. 지금 이름 5개가 각자의 새 집에 실제로 정의돼 있는지를 직접 확인해 그
  # 구멍을 메운다. 이름이 또 바뀌면 이 검사와 T25-167 의 이동 심볼 목록을 함께 고쳐야 한다.
  if ! grep -qF 'def encode_safe_utf8(' "$hub_atomic_write_file"; then
    note_failure "T25-245: hub_atomic_write.py 에 'def encode_safe_utf8(' 이 없음 — 이름이 바뀌었으면 T25-167 의 이동 심볼 목록도 함께 고쳐라"
  fi
  if ! grep -qF 'def atomic_write_text(' "$hub_atomic_write_file"; then
    note_failure "T25-245: hub_atomic_write.py 에 'def atomic_write_text(' 이 없음 — 이름이 바뀌었으면 T25-167 의 이동 심볼 목록도 함께 고쳐라"
  fi
  if ! grep -qF 'def _clamp_interval_overrides(' "$hub_config_file"; then
    note_failure "T25-245: hub_config.py 에 'def _clamp_interval_overrides(' 이 없음 — 이름이 바뀌었으면 T25-167 의 이동 심볼 목록도 함께 고쳐라"
  fi
  if ! grep -qF 'def _validate_config_overrides(' "$hub_config_file"; then
    note_failure "T25-245: hub_config.py 에 'def _validate_config_overrides(' 이 없음 — 이름이 바뀌었으면 T25-167 의 이동 심볼 목록도 함께 고쳐라"
  fi
  if ! grep -qE '^_CONFIG_FIELD_TYPES[[:space:]]*[:=]' "$hub_config_file"; then
    note_failure "T25-245: hub_config.py 에 _CONFIG_FIELD_TYPES 줄 시작 대입이 없음 — 이름이 바뀌었으면 T25-167 의 이동 심볼 목록도 함께 고쳐라"
  fi

  # T25-168(역, 조용한 무력화 방지 — docs/prps/hub-collect-split-for-merge.md 고유 위험.
  # docs/prps/hub-subagent-liveness-signal.md §11 R4 의 후속 분리로 write_server_record 가
  # hub_server_state_read.py 로 옮겨가며 5건 중 1건이 그 모듈로 넘어가 기대치가 5 → 4 로
  # 줄었다 — 같은 위험(자신도 hub_atomic_write 를 임포트해 호출한다)이 그 모듈에도 그대로
  # 있어 같은 가드 두 개를 나란히 건다):
  # hub_collect.py 가 `from hub_atomic_write import atomic_write_text` 형태로 이름을 자기
  # 네임스페이스에 복사해 오면, test_hub_collect.py 의
  # mock.patch.object(hub_atomic_write, "atomic_write_text", ...) 가 아무 효과 없이 통과한다
  # (테스트는 초록인데 검증은 사라진다). 정규화된 호출(hub_atomic_write.atomic_write_text(
  # 형태, 정확히 4건)을 정적으로 못 박는다.
  if grep -qE '^from hub_atomic_write import' "$hub_collect_file"; then
    note_failure "T25-168: hub_collect.py 에 from hub_atomic_write import 형태가 있음(mock.patch.object 무력화 위험)"
  fi
  local atomic_write_call_count
  atomic_write_call_count=$(grep -oF 'hub_atomic_write.atomic_write_text(' "$hub_collect_file" | wc -l | tr -d ' ')
  if [[ "$atomic_write_call_count" -ne 4 ]]; then
    note_failure "T25-168: hub_collect.py 의 hub_atomic_write.atomic_write_text( 호출이 ${atomic_write_call_count}건(기대 4)"
  fi
  local hub_server_state_read_file="$REPO_ROOT/hub/bin/hub_server_state_read.py"
  if grep -qE '^from hub_atomic_write import' "$hub_server_state_read_file"; then
    note_failure "T25-168: hub_server_state_read.py 에 from hub_atomic_write import 형태가 있음(mock.patch.object 무력화 위험)"
  fi
  local server_state_read_atomic_write_call_count
  server_state_read_atomic_write_call_count=$(grep -oF 'hub_atomic_write.atomic_write_text(' "$hub_server_state_read_file" | wc -l | tr -d ' ')
  if [[ "$server_state_read_atomic_write_call_count" -ne 1 ]]; then
    note_failure "T25-168: hub_server_state_read.py 의 hub_atomic_write.atomic_write_text( 호출이 ${server_state_read_atomic_write_call_count}건(기대 1)"
  fi

  # T25-170(신설, dashboard-ui-polish-4 PRP §6, 결정 S1~S4): .head-row 가 스크롤해도
  # 상단에 고정된다.
  local head_row_rule_170
  head_row_rule_170=$(grep -oE '\.head-row\{[^}]*\}' "$hub_template_file" | head -1)
  local head_row_sticky_token
  for head_row_sticky_token in 'position:sticky' 'top:0' 'z-index:10' 'background:var(--bg)'; do
    if [[ "$head_row_rule_170" != *"$head_row_sticky_token"* ]]; then
      note_failure "T25-170a: .head-row{ 선언에 $head_row_sticky_token 이 없음"
    fi
  done

  # T25-170e(신설, docs/prps/dashboard-hub-signal-tuning.md 결정 D12 — 상단 여백 32px 이
  # sticky 요소 안에 있는지). T25-170c(이동 없음)와 목적이 다르다 — 이쪽은 결정 S3 의
  # 픽셀 동일성(스크롤 최상단 화면이 지금과 같다)을 지킨다. 리터럴이 padding:32px 0 10px 에서
  # padding:32px var(--dzh-wrap-gutter) 10px 로 바뀐 이유는 결정 D19(거터 누출 수정 후속) —
  # 세로 padding(32px·10px)은 그대로이고 가로 padding 만 --dzh-wrap-gutter 토큰을 쓴다.
  if [[ "$head_row_rule_170" != *"padding:32px var(--dzh-wrap-gutter) 10px"* ]]; then
    note_failure "T25-170e: .head-row{ 선언에 padding:32px var(--dzh-wrap-gutter) 10px 가 없음(상단 여백이 sticky 요소 밖으로 빠지면 스크롤 초반 헤더가 다시 따라 올라간다)"
  fi

  if ! grep -qF '.head-row{display:flex' "$hub_template_file"; then
    note_failure "T25-170b: .head-row{display:flex 로 시작하지 않음(T25-59 앵커 보존 재확인)"
  fi

  if ! grep -qF '.wrap{max-width:1440px;margin:0 auto 32px' "$hub_template_file"; then
    note_failure "T25-170c: .wrap 상단 마진이 0 이 아님(스크롤 초반 헤더가 따라 올라간다)"
  fi

  local head_row_z_index_170 usage_z_index_170
  head_row_z_index_170=$(grep -oE '\.head-row\{[^}]*z-index:[0-9]+' "$hub_template_file" | grep -oE '[0-9]+$' | head -1)
  usage_z_index_170=$(grep -oE '\.usage\{[^}]*z-index:[0-9]+' "$hub_template_file" | grep -oE '[0-9]+$' | head -1)
  if [[ -z "$head_row_z_index_170" || -z "$usage_z_index_170" \
      || "$head_row_z_index_170" -ge "$usage_z_index_170" ]]; then
    note_failure "T25-170d: .head-row 의 z-index(${head_row_z_index_170:-없음})가 .usage 의 z-index(${usage_z_index_170:-없음})보다 낮지 않음(헤더가 사용량·상세 패널을 덮는 층 역전)"
  fi

  # T25-173(신설, docs/prps/dashboard-hub-signal-tuning.md 결정 D19 — .head-row 배경이 .wrap
  # 좌우 거터까지 덮어야 스크롤 중 카드 그림자가 헤더 밑에서도 가려진다). 리터럴이 아니라
  # 관계를 고정한다(T25-172 와 같은 관례) — G=--dzh-wrap-gutter, .head-row 의 가로 margin
  # M·가로 padding P 가 다음을 만족해야 한다: M+P==0(콘텐츠 원점 불변, 안 그러면 제목이 카드와
  # 어긋난다) · -M>=G(배경이 거터를 완전히 덮음) · margin-top==0(D15, 마진 상쇄로 스크롤
  # 초반 헤더가 따라 올라가는 결함 재발 방지). .wrap 의 가로 padding 도 G 와 같아야 한다(단일
  # 출처가 실제로 지켜지는지). 성분을 못 찾으면 T25-172 의 None 처리와 같은 관례로 공허 통과
  # 대신 실패로 보고한다. margin-top 위반은 검수 R2 전까지 T25-177a 의 두 번째 발화
  # 지점이었다(이 저장소가 T22-170a·T22-170b 에서 쓴 관례 — 가드 하나가 서브체크 2개를
  # 갖되 원장 행은 그 중 하나만 겨눈다) — 등록 뮤테이션(margin 가로 성분→0)이 COVER 만
  # 재현하고 margin-top 회귀에는 전용 변조행이 없었다(검수 R2 LOW 지적). 지금은 그 둘로
  # 가른 것과 같은 판단으로 T25-177d 로 분리했다 — 원장 1열
  # 유일성이 강제하는 것은 「새 변조행에 다른 guard_id 가 필요하다」뿐이고, margin-top
  # 발화 지점을 T25-177d 로 개명한 것은 강제가 아니라 「한 ID 의 서브체크는 그 ID 의
  # 변조행이 재현한다」는 1:1 대응을 지키려는 선택이다(SOURCE_GUARD_ID_FLOOR 주석 참고).
  local head_row_gutter_output
  head_row_gutter_output=$(python3 - "$hub_template_file" <<'PYEOF'
import re
import sys

GUTTER_VAR_RE = re.compile(r"^var\(--dzh-wrap-gutter\)$")
GUTTER_NEG_RE = re.compile(r"^calc\(\s*-1\s*\*\s*var\(--dzh-wrap-gutter\)\s*\)$")
PX_RE = re.compile(r"^(-?\d+)px$")


def split_top_level(value):
    # 공백으로 토큰을 나누되 괄호(중첩 포함) 안의 공백·별표는 그대로 둔다 —
    # "calc(-1 * var(--dzh-wrap-gutter))" 를 한 토큰으로 지키기 위함이다.
    tokens, current, depth = [], [], 0
    for ch in value:
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        if ch.isspace() and depth == 0:
            if current:
                tokens.append("".join(current))
                current = []
            continue
        current.append(ch)
    if current:
        tokens.append("".join(current))
    return tokens


def resolve_px(token, gutter):
    if token is None:
        return None
    if GUTTER_VAR_RE.match(token):
        return gutter
    if GUTTER_NEG_RE.match(token):
        return -gutter
    if token == "0":
        return 0
    match = PX_RE.match(token)
    return int(match.group(1)) if match else None


def extract_rule_body(source, selector):
    match = re.search(re.escape(selector) + r"\{([^}]*)\}", source)
    return match.group(1) if match else None


def extract_shorthand_tokens(body, property_name):
    match = re.search(r"(?:^|;)" + property_name + r":([^;}]+)", body)
    return split_top_level(match.group(1).strip()) if match else None


def horizontal_component(tokens):
    if tokens is None:
        return None
    if len(tokens) == 1:
        return tokens[0]
    if len(tokens) in (2, 3):
        return tokens[1]
    if len(tokens) == 4:
        # 4-value 단축 속성(top/right/bottom/left)은 좌우(tokens[1]·tokens[3])가 같을 때만
        # "가로 성분" 이라는 단일 값이 존재한다 — 이 가드는 좌우 대칭 관계 하나만 단언하도록
        # 설계됐으므로(검수 R2 MEDIUM 1), 비대칭이면 tokens[1] 만 보고 공허 통과시키는 대신
        # 해석 실패(None)로 보고한다.
        return tokens[1] if tokens[1] == tokens[3] else None
    return None


# 검수 R2 MEDIUM 2 의 관례(T25-172) — 완결 인용 주석이 leftmost-match 를 앞지르는 것을 막는다.
source = open(sys.argv[1], encoding="utf-8").read()
source = re.sub(r"/\*.*?\*/", "", source, flags=re.DOTALL)

gutter_match = re.search(r"--dzh-wrap-gutter:(\d+)px", source)
if gutter_match is None:
    for tag in ("WRAP", "SUM", "COVER", "MARGINTOP"):
        print(f"{tag}:--dzh-wrap-gutter 토큰을 찾지 못함")
    raise SystemExit(0)
gutter = int(gutter_match.group(1))

wrap_body = extract_rule_body(source, ".wrap")
if wrap_body is None:
    print("WRAP:.wrap{ 규칙을 찾지 못함")
else:
    wrap_padding = horizontal_component(extract_shorthand_tokens(wrap_body, "padding"))
    if wrap_padding is None:
        print("WRAP:.wrap{ 에 padding 선언이 없음")
    else:
        wrap_px = resolve_px(wrap_padding, gutter)
        if wrap_px is None:
            print(f"WRAP:.wrap 의 가로 padding 값을 해석하지 못함({wrap_padding!r})")
        elif wrap_px != gutter:
            print(f"WRAP:.wrap 의 가로 padding({wrap_px}) 이 거터 G({gutter})와 다름")
        else:
            print("WRAP:OK")

head_body = extract_rule_body(source, ".head-row")
if head_body is None:
    for tag in ("SUM", "COVER", "MARGINTOP"):
        print(f"{tag}:.head-row{{ 규칙을 찾지 못함")
    raise SystemExit(0)

margin_tokens = extract_shorthand_tokens(head_body, "margin")
padding_tokens = extract_shorthand_tokens(head_body, "padding")
margin_h = horizontal_component(margin_tokens)
padding_h = horizontal_component(padding_tokens)
margin_top = margin_tokens[0] if margin_tokens else None

M = resolve_px(margin_h, gutter)
P = resolve_px(padding_h, gutter)
MT = resolve_px(margin_top, gutter)

if margin_tokens is None:
    print("SUM:.head-row{ 에 margin 선언이 없음")
elif padding_tokens is None:
    print("SUM:.head-row{ 에 padding 선언이 없음")
elif M is None:
    print(f"SUM:.head-row 의 가로 margin 값을 해석하지 못함({margin_h!r})")
elif P is None:
    print(f"SUM:.head-row 의 가로 padding 값을 해석하지 못함({padding_h!r})")
elif M + P != 0:
    print(f"SUM:.head-row 콘텐츠 원점이 어긋남(margin{M:+d}px + padding{P:+d}px = {M + P}px, 기대 0)")
else:
    print("SUM:OK")

if margin_tokens is None:
    print("COVER:.head-row{ 에 margin 선언이 없음")
elif M is None:
    print(f"COVER:.head-row 의 가로 margin 값을 해석하지 못함({margin_h!r})")
elif -M < gutter:
    print(f"COVER:.head-row 배경이 거터를 완전히 덮지 못함(-margin={-M}px < G={gutter}px)")
else:
    print("COVER:OK")

if margin_tokens is None:
    print("MARGINTOP:.head-row{ 에 margin 선언이 없음")
elif MT is None:
    print(f"MARGINTOP:.head-row 의 margin-top 값을 해석하지 못함({margin_top!r})")
elif MT != 0:
    print(f"MARGINTOP:.head-row 의 margin-top 이 0 이 아님({MT}px, D15 위반 — 마진 상쇄로 sticky 가 늦게 걸린다)")
else:
    print("MARGINTOP:OK")
PYEOF
)

  local wrap_gutter_status_173 sum_status_173 cover_status_173 margintop_status_173
  wrap_gutter_status_173=$(grep '^WRAP:' <<< "$head_row_gutter_output" | head -1 | cut -d: -f2-)
  sum_status_173=$(grep '^SUM:' <<< "$head_row_gutter_output" | head -1 | cut -d: -f2-)
  cover_status_173=$(grep '^COVER:' <<< "$head_row_gutter_output" | head -1 | cut -d: -f2-)
  margintop_status_173=$(grep '^MARGINTOP:' <<< "$head_row_gutter_output" | head -1 | cut -d: -f2-)

  if [[ "$wrap_gutter_status_173" != "OK" ]]; then
    note_failure "T25-177c: .wrap 의 가로 padding 이 거터 토큰(--dzh-wrap-gutter)과 어긋남 — ${wrap_gutter_status_173:-검사 결과 없음}"
  fi
  if [[ "$sum_status_173" != "OK" ]]; then
    note_failure "T25-177b: .head-row 콘텐츠 원점(margin+padding)이 0 이 아님 — ${sum_status_173:-검사 결과 없음}"
  fi
  if [[ "$cover_status_173" != "OK" ]]; then
    note_failure "T25-177a: .head-row 배경이 .wrap 거터를 완전히 덮지 못함 — ${cover_status_173:-검사 결과 없음}"
  fi
  if [[ "$margintop_status_173" != "OK" ]]; then
    note_failure "T25-177d: .head-row margin-top 이 0 이 아님(결정 D15 재발 위험) — ${margintop_status_173:-검사 결과 없음}"
  fi

  # T25-178(신설, hub-unified-card-tree-ui PRP §9.5·§10.2-1, 결정 U2): 삭제가 부분적이어서
  # 죽은 CSS·죽은 함수가 남는 것을 막는다 — 보기 모드 잔재는 T25-159 가 별도로 문다(관심사
  # 분리). 뮤테이션 가능한 손잡이가 8개라 정규식 배열로 묶어 순회한다(T25-68 의 관용구).
  local tree_relic_token tree_relic_count_178
  for tree_relic_token in 'tree-section' 'tree-node' 'tree-root' 'tree-leaf' \
      'renderProjectTree' 'renderTreeRoot' 'renderSessionNode' 'initializeTreeRootScrollPositions'; do
    tree_relic_count_178=$(grep -c -- "$tree_relic_token" "$hub_template_file")
    if [[ "$tree_relic_count_178" -ne 0 ]]; then
      note_failure "T25-178: 트리 잔재 '$tree_relic_token' 이 ${tree_relic_count_178}건(기대 0 — U2 로 조직도 은유를 폐기했다)"
    fi
  done

  # T25-179(신설, GOTCHA 4, T25-66 관용구 복제 — hub-unified-card-tree-ui PRP §10.2-3): 확장
  # 토글 리스너 등록이 if(!isServed){ 뒤로 가면 file:// 모드에서 확장이 통째로 죽는다. T25-66
  # 처럼 리스너 본문 안의 유일한 리터럴 위치로 판정한다 — 리스너 전체가 뒤로 옮겨지면 본문도
  # 함께 옮겨지므로 등록 줄 자체를 앵커로 잡을 필요가 없다.
  # 개정(이슈 1, docs/prps/hub-ui-4-issues.md §2, 결정 TR1 — PRP 자체 계획표에는 없던
  # 개정이다. TR1 이 확장 토글 리스너 자체를 삭제하면서 "등록 순서" 판정의 대상이
  # 사라져 이 가드가 함께 깨진다는 것을 tests/run.sh 를 실제로 돌려 발견했다): 확인할
  # 리스너가 없으므로 잔재 역가드로 바꾼다(T25-186 → T25-190 선례) — EXPAND_TOGGLE_SELECTOR
  # 식별자 자체가 파일에서 사라졌는지를 본다. T25-196(card-expand-toggle 리터럴 검사)과는
  # 검사하는 문자열 형태가 달라(식별자 대 CSS 클래스 문자열) 중복이 아니다.
  local expand_toggle_selector_relic_count_179
  expand_toggle_selector_relic_count_179=$(grep -c 'EXPAND_TOGGLE_SELECTOR' "$hub_template_file")
  if [[ "$expand_toggle_selector_relic_count_179" -ne 0 ]]; then
    note_failure "T25-179: EXPAND_TOGGLE_SELECTOR 잔재가 ${expand_toggle_selector_relic_count_179}건(기대 0 — TR1 로 확장 토글 리스너 자체가 사라졌다)"
  fi

  # T25-180(신설, hub-unified-card-tree-ui PRP §10.2-4): 확장 토글 리스너가 중복 등록되면
  # 클릭 1회에 상태가 2번 뒤집혀 제자리로 온다(T25-169f 와 같은 실패 모드).
  # 개정(이슈 1, 결정 TR1 — 위 T25-179 와 같은 이유의 같은 발견): 리스너 자체가 없으므로
  # 「정확히 1건」 판정 대신 그 등록 지점의 리터럴이 0건인지로 바꾼다.
  local expand_toggle_closest_count_180
  expand_toggle_closest_count_180=$(grep -coF 'closest(EXPAND_TOGGLE_SELECTOR)' "$hub_template_file")
  if [[ "$expand_toggle_closest_count_180" -ne 0 ]]; then
    note_failure "T25-180: closest(EXPAND_TOGGLE_SELECTOR) 가 ${expand_toggle_closest_count_180}건(기대 0 — TR1 로 확장 토글 리스너 자체가 사라졌다)"
  fi

  # T25-181(신설, ★최고 위험 — hub-unified-card-tree-ui PRP §7.5·§10.2-5, 결정 U10): 드래그
  # 3리스너가 하나라도 옛 '[data-project-path]' 전체 조회로 되돌아가면 세션 행이 이 속성을
  # 갖게 된 지금, 참조 노드가 #dzh-app 의 자식이 아니게 되어 NotFoundError 로 dragover 가
  # 죽거나(라이브 이동 정지), 마지막 세션 행 위에서는 카드가 격자 맨 뒤로 조용히 튄다(§7.5).
  # 셋 다 CARD_SELECTOR 를 경유해야 한다.
  local drag_listeners_body_181
  drag_listeners_body_181=$(sed -n "/document.addEventListener('dragstart', function(event){/,/document.addEventListener('dragend', function(){/p" "$hub_template_file")
  if [[ -z "$drag_listeners_body_181" ]]; then
    record_failure "$test_name" "T25-181: 드래그 리스너 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if grep -qF "closest('[data-project-path]')" <<< "$drag_listeners_body_181"; then
    note_failure "T25-181: 드래그 리스너 본문에 closest('[data-project-path]') 형태가 남아 있음(★결정 U10 위반 — 세션 행 위에서 드래그가 깨진다)"
  fi
  local card_selector_closest_count_181
  card_selector_closest_count_181=$(grep -oF 'closest(CARD_SELECTOR)' <<< "$drag_listeners_body_181" | wc -l | tr -d ' ')
  if [[ "$card_selector_closest_count_181" -lt 3 ]]; then
    note_failure "T25-181: dragstart·dragover·drop 중 CARD_SELECTOR 를 경유하는 곳이 ${card_selector_closest_count_181}건뿐(기대 3건 이상 — 결정 U10 위반)"
  fi

  # T25-182(신설, hub-unified-card-tree-ui PRP §7.4·§10.2-6): 확장 셰브론 클릭이 패널까지
  # 열지 않도록 패널 IIFE 클릭 리스너에 조기 반환이 있고, 그것이 CLICKABLE_CARD_SELECTOR
  # 판정보다 앞줄이다. 옛 .tree-leaf 가드의 잔존 여부는 T25-178 이 잔재 0 으로 확인한다.
  # 개정(이슈 1, docs/prps/hub-ui-4-issues.md §2, 결정 TR1) — 셰브론 버튼 자체가 삭제돼
  # 조기 반환이 가드할 대상이 없다. 삭제하고 역가드로 교체한다(T25-186 → T25-190 선례):
  # 패널 IIFE 클릭 리스너가 지웠던 그 조기 반환 리터럴이 0건 — T25-196 의
  # card-expand-toggle 리터럴 검사(파일 전체)보다 좁혀, 그 조기 반환 형태 자체가 되살아
  # 나는지를 겨냥한다.
  local expand_toggle_panel_guard_relic_182
  expand_toggle_panel_guard_relic_182=$(grep -cF "closest('.card-expand-toggle')" "$hub_template_file")
  if [[ "$expand_toggle_panel_guard_relic_182" -ne 0 ]]; then
    note_failure "T25-182: closest('.card-expand-toggle') 잔재가 ${expand_toggle_panel_guard_relic_182}건(기대 0 — TR1 로 셰브론 자체가 사라졌다)"
  fi

  # T25-183(신설, hub-unified-card-tree-ui PRP §7.2, 불변식 OC-A): sessionRowAttributes 본문에
  # data-dashboard-key·data-panel-empty-reason 이 함께 있다 — 키가 없는데 사유도 없으면
  # 클릭이 조용히 실패한다(hub-panel-empty-state PRP 의 출발점이던 결함).
  local session_row_attrs_body_183
  session_row_attrs_body_183=$(sed -n '/function sessionRowAttributes(project, session){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$session_row_attrs_body_183" ]]; then
    record_failure "$test_name" "T25-183: sessionRowAttributes() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'data-dashboard-key' <<< "$session_row_attrs_body_183" \
      || ! grep -qF 'data-panel-empty-reason' <<< "$session_row_attrs_body_183"; then
    note_failure "T25-183: sessionRowAttributes() 에 data-dashboard-key/data-panel-empty-reason 쌍이 없음(불변식 OC-A 위반)"
  fi

  # T25-184 는 폐기했다(카드 상세보기 정리 M2, 결정 MX4·MX13, docs/prps/hub-session-modal-cleanup.md
  # §10.1) — 지키던 것은 프로젝트 「이전 작업」 톤다운 셀렉터의 자식 결합자 > 였는데(결정 U11, 그 톤다운이
  # 세션 진행률까지 물들이지 않게), 그 셀렉터 자체가 카드에서 걷혀 T25-88 의 역가드(.card[data-tier1- 0건)가
  # 덮는다. 번호는 다시 쓰지 않는다.

  # T25-185(신설, hub-unified-card-tree-ui PRP §10.2-9): 둘 중 하나만 남으면 접힘 카드에
  # 진행률이 그대로 뜨거나(높이 파열) 펼쳐도 진행률이 안 뜬다.
  # 개정(이슈 1, docs/prps/hub-ui-4-issues.md §2, 결정 TR3·TR4) — 두 규칙 모두 삭제됐다
  # (카드 높이는 항상 340px, 세션별 진행률은 항상 렌더). 삭제하고 역가드로 교체한다
  # (T25-186 → T25-190 선례) — 옛 규칙 리터럴 그대로가 되살아나지 않는지 본다(T25-196 의
  # 파일 전체 card-expanded 0건 검사보다 좁혀, 이 특정 두 규칙의 부활을 겨냥한다).
  if grep -qF '.card.card-expanded{height:auto}' "$hub_template_file"; then
    note_failure "T25-185: hub_template.html 에 .card.card-expanded{height:auto} 규칙이 되살아남(TR4 위반)"
  fi
  if grep -qF '.card:not(.card-expanded) .session-tier1{display:none}' "$hub_template_file"; then
    note_failure "T25-185: hub_template.html 에 .card:not(.card-expanded) .session-tier1{display:none} 규칙이 되살아남(TR3 위반)"
  fi

  # T25-186 은 삭제됐다 — 사용자가 halo 자체를 되돌리라고 해(hub-tree-view-and-signal-fixes
  # PRP §4·결정 V1) 그 규칙이 사라졌으므로 "규칙 존재" 단언이 정확히 반대로 뒤집힌다. 그
  # 자리를 아래 역가드 T25-190(결정 V11)이 잇는다.
  #
  # T25-190(신설, 역가드 — 결정 V1·V11, hub-tree-view-and-signal-fixes PRP §4.2·§11.2):
  # .badge.state-working 이 든 어떤 선택자의 규칙 본문에도 box-shadow·animation 이 없어야
  # 한다 — halo(또는 맥동)가 다른 선택자 이름으로 검토 없이 되살아나지 않는다는 사용자
  # 결정(2026-09-10)의 기계적 표현.
  local badge_working_halo_190
  badge_working_halo_190=$(grep -oE '[^{}]*\.badge\.state-working\{[^}]*\}' "$hub_template_file" | grep -E 'box-shadow|animation' || true)
  if [[ -n "$badge_working_halo_190" ]]; then
    note_failure "T25-190: state-working 규칙에 halo 가 있음(결정 U8 재발) — $badge_working_halo_190"
  fi

  # T25-192(신설, 정 — 결정 V9, hub-tree-view-and-signal-fixes PRP §6.2·§11.2): 세션 행의
  # 세로 여백을 li 2px + 버튼 5px 로 재배분한 둘의 2배 합이 옛 li 7px 둘의 2배 합(14)과
  # 같아야 한다(행 높이 증분 0, 접힘 카드에 보이는 세션 수 불변) — 리터럴이 아니라 관계를
  # 고정한다(T25-177 의 python 산술 관용구).
  local session_row_padding_sum_output session_row_padding_sum_status
  session_row_padding_sum_output=$(python3 - "$hub_template_file" <<'PYEOF'
import re
import sys

source = open(sys.argv[1], encoding="utf-8").read()
source = re.sub(r"/\*.*?\*/", "", source, flags=re.DOTALL)

li_match = re.search(r"^  \.sessions li\{padding:(\d+)px 0", source, re.MULTILINE)
row_match = re.search(r"^  \.session-row\{[^}]*padding:(\d+)px (\d+)px", source, re.MULTILINE)

if li_match is None:
    print("SUM:.sessions li{ 의 세로 padding(N)을 찾지 못함")
elif row_match is None:
    print("SUM:.session-row{ 의 padding(M px H px)을 찾지 못함")
else:
    li_px = int(li_match.group(1))
    row_px = int(row_match.group(1))
    total = 2 * li_px + 2 * row_px
    if total != 14:
        print(f"SUM:li{li_px}+버튼{row_px}의 2배 합이 {total}px(기대 14)")
    else:
        print("SUM:OK")
PYEOF
)
  session_row_padding_sum_status=$(grep '^SUM:' <<< "$session_row_padding_sum_output" | head -1 | cut -d: -f2-)
  if [[ "$session_row_padding_sum_status" != "OK" ]]; then
    note_failure "T25-192: 세션 행 세로 여백 합이 14px 가 아님 — ${session_row_padding_sum_status:-검사 결과 없음}"
  fi

  # T25-193(신설, 정 — ★결정 V9, hub-tree-view-and-signal-fixes PRP §6.3·§11.2): 좌우 8px
  # 번짐 네 숫자(ul margin·ul padding·버튼 margin·버튼 폭 초과분/2)가 모두 같아야 한다 —
  # 어긋나면 .sessions{overflow-y:auto} 의 overflow-x 가 auto 로 강제돼 접힘 카드에 가로
  # 스크롤바가 되살아난다(직전 회차가 0개로 만든 것의 재발).
  # 개정(이슈 1, docs/prps/hub-ui-4-issues.md §2, 결정 TR6) — 옛 펼침 스코프의
  # padding-left:24px(1단 들여쓰기)가 이 규칙의 padding 에 합쳐져 `padding:0 8px 0 24px`
  # (상 0·우 8·하 0·좌 24)가 됐다. 정규식이 우측 padding 만 잡던 것을 좌측까지 함께
  # 잡도록 넓히고, 좌측 = 우측 + 16(1단 들여쓰기, V2~V8 기하)이라는 산술을 새로 검사한다.
  local session_row_bleed_output session_row_bleed_status
  session_row_bleed_output=$(python3 - "$hub_template_file" <<'PYEOF'
import re
import sys

source = open(sys.argv[1], encoding="utf-8").read()
source = re.sub(r"/\*.*?\*/", "", source, flags=re.DOTALL)

TREE_INDENT_PX = 16  # 결정 TR6 — 1단 들여쓰기(V2~V8 트리 기하)

sessions_match = re.search(
    r"^  \.sessions\{[^}]*margin:10px -(\d+)px 0;padding:0 (\d+)px 0 (\d+)px", source, re.MULTILINE
)
row_match = re.search(r"^  \.session-row\{[^}]*width:calc\(100% \+ (\d+)px\);margin:0 -(\d+)px", source, re.MULTILINE)

if sessions_match is None:
    print("BLEED:.sessions{ 의 margin/padding(B1·B2·좌측 들여쓰기)을 찾지 못함")
elif row_match is None:
    print("BLEED:.session-row{ 의 width/margin(W·B3)을 찾지 못함")
else:
    b1 = int(sessions_match.group(1))
    b2 = int(sessions_match.group(2))
    left_padding = int(sessions_match.group(3))
    w = int(row_match.group(1))
    b3 = int(row_match.group(2))
    if b1 == b2 == b3 and w == 2 * b1 and left_padding == b2 + TREE_INDENT_PX:
        print("BLEED:OK")
    else:
        print(
            f"BLEED:ul margin{b1}·ul padding{b2}·ul 좌측{left_padding}(기대 우측+{TREE_INDENT_PX})·"
            f"버튼 margin{b3}·버튼 폭초과분{w}(기대 2×margin)"
        )
PYEOF
)
  session_row_bleed_status=$(grep '^BLEED:' <<< "$session_row_bleed_output" | head -1 | cut -d: -f2-)
  if [[ "$session_row_bleed_status" != "OK" ]]; then
    note_failure "T25-193: 가로 번짐 불일치 — ${session_row_bleed_status:-검사 결과 없음}"
  fi

  # T25-191·T25-191a 는 삭제됐다(이슈 1, docs/prps/hub-ui-4-issues.md §2, 결정 TR1·TR2) —
  # 사용자가 카드 트리를 상시 표시로 확정해(TR1) .card.card-expanded 스코프 자체가
  # 사라졌다(TR2). 둘 다 "스코프 밖 유출"(완전·부분)을 겨냥한 가드였는데, 스코프가 없으면
  # "유출"이라는 개념 자체가 성립하지 않는다 — 연결선 선택자는 이제 **항상** 스코프 없이
  # 존재하는 것이 정상 상태다(T25-186 → T25-190 이 halo 삭제 때 세운 선례와 같은 형태).
  # 그 자리를 아래 둘이 나눠 잇는다: 정방향(연결선 규칙이 스코프 없이 존재하는가)은 신설
  # T25-197 이, 역방향(.card.card-expanded 문자열 자체가 되살아나지 않는가 — 완전 유출과
  # 부분 유출을 가르던 구분 자체가 필요 없어졌다)은 신설 T25-196 의 card-expanded 리터럴
  # 0건 검사가 더 넓게 흡수한다.
  #
  # T25-194(개정 — 결정 LM2, docs/prps/hub-session-row-layout-and-modal-size.md; 원래는 V7 의 order 선언 존재
  # 검사였다, hub-tree-view-and-signal-fixes PRP §5.4·§11.2): 세션 줄·세션 카드 안의 순서는 CSS order 가 아니라 DOM 순서
  # 가 정한다 — 화면 낭독기는 버튼 안 자식을 DOM 순서로 읽는다(WCAG 1.3.2). 정 — ① .session-row 가 세로 flex
  # 컨테이너다(발췌 <span> 의 블록화가 줄 모양을 만든다) ② renderSessionContent() 가 다섯 조각 호출을 각각 한 번씩,
  # 메타 → 발췌 → 진행률 → 실행 줄 → 워크플로 순서로 부른다. 역 — ③ 직계 자식에 order 선언이 없다(DOM/시각 불일치가
  # 되살아난다). 호출을 한 번씩만 세는 이유: 뒤에 같은 호출을 또 붙여 순서를 어기는 변조가 첫 등장만 보면 통과한다.
  local render_session_content_body_194 call_line_194 previous_call_line_194 call_name_194
  previous_call_line_194=0
  if ! grep -qF '.session-row{display:flex;flex-direction:column}' "$hub_template_file"; then
    note_failure "T25-194: .session-row 가 세로 flex 컨테이너(display:flex;flex-direction:column)가 아님"
  fi
  render_session_content_body_194=$(sed -n '/function renderSessionContent(session){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$render_session_content_body_194" ]]; then
    record_failure "$test_name" "T25-194: renderSessionContent() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  for call_name_194 in renderSessionMeta renderSessionExcerpt renderSessionProgress renderAgentRunList renderWorkflowRun; do
    if [[ "$(grep -cF -- "${call_name_194}(" <<< "$render_session_content_body_194")" -ne 1 ]]; then
      note_failure "T25-194: renderSessionContent() 의 자식 호출이 정확히 한 번씩이 아님 — 그 호출 수가 어긋난 이름: ${call_name_194}"
      continue
    fi
    call_line_194=$(grep -nF -- "${call_name_194}(" <<< "$render_session_content_body_194" | head -1 | cut -d: -f1)
    if [[ "$call_line_194" -le "$previous_call_line_194" ]]; then
      note_failure "T25-194: renderSessionContent() 의 자식 호출 순서가 메타→발췌→진행률→실행 줄→워크플로가 아님 — 순서가 어긋난 호출: ${call_name_194}"
    fi
    previous_call_line_194="$call_line_194"
  done
  if grep -qE '>\.(session-tier1|workflow-runs|agent-run-list)\{order' "$hub_template_file"; then
    note_failure "T25-194: 세션 줄·카드의 직계 자식에 CSS order 선언이 되살아남(DOM 순서와 시각 순서가 갈라진다)"
  fi

  # T25-195(신설, 역 — 제약 7·결정 V11, hub-tree-view-and-signal-fixes PRP §5.6·§11.2):
  # 「정적, 새 애니메이션 없음」 승인(2026-09-10)을 어기는 @keyframes 선언이 조용히
  # 추가되지 않는다 — 지금 2개(card-working-glow · dzh-refresh-spin)로 고정한다. 줄 시작
  # 앵커(^[[:space:]]*@keyframes)를 쓴다 — 맨 grep -c '@keyframes' 는 주석 안의 언급(D5
  # 설명 문단의 "@keyframes 이름(card-working-glow)은")까지 세어 실측 3이 나온다(오탐).
  local keyframes_count_195
  keyframes_count_195=$(grep -cE '^[[:space:]]*@keyframes[[:space:]]' "$hub_template_file" || true)
  if [[ "$keyframes_count_195" -ne 2 ]]; then
    note_failure "T25-195: @keyframes 개수가 ${keyframes_count_195}개(기대 2) — 새 애니메이션이 조용히 추가됐을 수 있음"
  fi

  # T25-187 은 삭제됐다(이슈 1, docs/prps/hub-ui-4-issues.md §2, 결정 TR1) — 검사 대상이던
  # applyCardExpandedState() 와 EXPANDED_CARD_CLASS 상수 자체가 삭제돼(트리가 상시 표시가
  # 되며 두 경로가 공유할 확장 상태가 없다) "두 경로가 같은 상수를 쓰는가"라는 질문이
  # 성립하지 않는다(T25-186 선례). 대체 역가드를 두지 않는 이유 — EXPANDED_CARD_CLASS 라는
  # 식별자가 되살아나면 그 값(문자열 'card-expanded')이 신설 T25-196 의 card-expanded
  # 리터럴 0건 검사에 이미 걸린다.

  # T25-196(신설, 역 — 이슈 1, docs/prps/hub-ui-4-issues.md §2, 결정 TR1 되돌림 방지): 카드
  # 확장 기능(토글·localStorage 영속) 전체가 삭제됐다 — 그 흔적 4종이 조용히 되살아나지
  # 않는지 리터럴 수로 고정한다(T25-178 의 순회 관용구).
  local card_expand_relic_token_196 card_expand_relic_count_196
  for card_expand_relic_token_196 in 'card-expanded' 'card-expand-toggle' 'dzh-expanded-projects' 'EXPAND_TOGGLE_ICON_SVG'; do
    card_expand_relic_count_196=$(grep -c -- "$card_expand_relic_token_196" "$hub_template_file")
    if [[ "$card_expand_relic_count_196" -ne 0 ]]; then
      note_failure "T25-196: 카드 확장 잔재 '$card_expand_relic_token_196' 이 ${card_expand_relic_count_196}건(기대 0 — TR1 로 삭제됐어야 한다)"
    fi
  done

  # T25-197(신설, 정 — 이슈 1, docs/prps/hub-ui-4-issues.md §2, 결정 TR2·TR6): 트리 연결선
  # 규칙이 .card.card-expanded 스코프 없이(TR2) 존재하고, 좌측 들여쓰기가 .sessions 의
  # padding 에 합쳐졌다(TR6, T25-193 과 짝인 정방향 확인).
  local tree_connector_literal_197
  for tree_connector_literal_197 in \
    '.sessions li::before{top:0;height:18px;width:8px;box-shadow:inset 0 -1px 0 0 var(--muted)}' \
    '.sessions li:first-child::before{top:-10px;height:28px}' \
    '.sessions li::after{top:17px;bottom:0}' \
    '.sessions li:last-child::after{display:none}' \
    '.session-tier1::before{top:0;height:18px;width:8px;box-shadow:inset 0 -1px 0 0 var(--muted)}'; do
    if ! grep -qF -- "$tree_connector_literal_197" "$hub_template_file"; then
      note_failure "T25-197: 트리 연결선 리터럴 '$tree_connector_literal_197' 이 스코프 없이 존재하지 않음"
    fi
  done
  if ! grep -qF '.sessions{list-style:none;margin:10px -8px 0;padding:0 8px 0 24px' "$hub_template_file"; then
    note_failure "T25-197: .sessions{ 의 padding 이 0 8px 0 24px(TR6 병합) 형태가 아님"
  fi

  # T25-198(신설, 역 — 이슈 1, docs/prps/hub-ui-4-issues.md §2, 결정 TR7): 구분선 대신
  # 연결선이 형제를 가른다(결정 V2 계승) — .sessions li{ 규칙 본문에 border-top 이 되살아
  # 나지 않는지 본다.
  local sessions_li_rule_198
  sessions_li_rule_198=$(grep -oE '^  \.sessions li\{[^}]*\}' "$hub_template_file" | head -1)
  if [[ -z "$sessions_li_rule_198" ]]; then
    record_failure "$test_name" "T25-198: .sessions li{ 규칙 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if grep -qF 'border-top' <<< "$sessions_li_rule_198"; then
    note_failure "T25-198: .sessions li{ 규칙 본문에 border-top 이 되살아남(TR7 위반, 구분선 부활)"
  fi

  # T25-200(신설, 역 — 이슈 3, docs/prps/hub-ui-4-issues.md §4, 결정 WT2 되돌림 방지):
  # renderWorkflowChip 본문에 data-tooltip 이 되살아나지 않는지, 그리고 삭제된 헬퍼
  # workflowChipTooltipText·WORKFLOW_RESULT_TOOLTIP_SEPARATOR 가 파일 전체에서 0건인지
  # 본다. WORKFLOW_STATE_ERROR 는 선택 항목 E(실패 칩 시각 상태)가 채택돼 예외다 — 여전히
  # errorClass 산식에 쓰인다.
  local render_workflow_chip_body_200
  render_workflow_chip_body_200=$(awk '
    /^  function renderWorkflowChip\(agent\)\{/{flag=1}
    /^  function renderWorkflowRun\(workflow\)\{/{exit}
    flag{print}
  ' "$hub_template_file")
  if [[ -z "$render_workflow_chip_body_200" ]]; then
    record_failure "$test_name" "T25-200: renderWorkflowChip~renderWorkflowRun 사이 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if grep -qF 'data-tooltip' <<< "$render_workflow_chip_body_200"; then
    note_failure "T25-200: renderWorkflowChip() 에 data-tooltip 이 되살아남(결정 WT1 위반)"
  fi
  local workflow_tooltip_relic_token_200 workflow_tooltip_relic_count_200
  for workflow_tooltip_relic_token_200 in 'workflowChipTooltipText' 'WORKFLOW_RESULT_TOOLTIP_SEPARATOR'; do
    workflow_tooltip_relic_count_200=$(grep -c -- "$workflow_tooltip_relic_token_200" "$hub_template_file")
    if [[ "$workflow_tooltip_relic_count_200" -ne 0 ]]; then
      note_failure "T25-200: 워크플로우 칩 툴팁 잔재 '$workflow_tooltip_relic_token_200' 이 ${workflow_tooltip_relic_count_200}건(기대 0 — WT2 로 삭제됐어야 한다)"
    fi
  done

  # T25-201(신설, 정 — 이슈 3, docs/prps/hub-ui-4-issues.md §4, 결정 WT6 — 무관 툴팁 생존
  # 확인, 회귀 방향이 조용해 가장 중요하다): 워크플로우 칩 툴팁(WT2)을 지우다가 같은
  # .agent-chip 클래스를 쓰는 다른 툴팁(실행 목록 행)이나 세션 ID·발췌 툴팁까지 함께
  # 죽지 않았는지 본다. 개정(결정 AR12, docs/prps/hub-agent-runs-and-prompt-source.md) —
  # renderAgentChip/visibleAgentRuns 는 renderAgentRunRow/renderAgentRunList 로 갈렸다.
  local render_agent_chip_body_201
  render_agent_chip_body_201=$(awk '
    /^  function renderAgentRunRow\(run, nowMs\)\{/{flag=1}
    /^  function renderAgentRunList\(runs\)\{/{exit}
    flag{print}
  ' "$hub_template_file")
  if [[ -z "$render_agent_chip_body_201" ]]; then
    record_failure "$test_name" "T25-201: renderAgentRunRow~renderAgentRunList 사이 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  # 두 리터럴은 실제 소스에서 줄바꿈으로 갈라져 있다(속성 여는 부분과 escapeHtml 호출이
  # 다음 줄에 있다) — grep -F 는 줄 단위라 이어붙인 한 문자열로는 안 잡히므로 따로 본다.
  if ! grep -qF 'data-tooltip="' <<< "$render_agent_chip_body_201" \
      || ! grep -qF 'escapeHtml(agentRunTooltipText(run))' <<< "$render_agent_chip_body_201"; then
    note_failure "T25-201: renderAgentRunRow() 의 data-tooltip 이 agentRunTooltipText 를 경유하지 않음(다른 툴팁이 함께 죽었을 수 있음)"
  fi
  if ! grep -qF 'function agentRunTooltipText(run){' "$hub_template_file"; then
    note_failure "T25-201: agentRunTooltipText() 자체가 사라짐(다른 툴팁이 함께 죽었을 수 있음)"
  fi
  if ! grep -qF "data-tooltip=\"' + escapeHtml(session.session_id)" "$hub_template_file"; then
    note_failure "T25-201: session-id 의 data-tooltip 이 사라짐(다른 툴팁이 함께 죽었을 수 있음)"
  fi
  if ! grep -qF "' data-tooltip=\"' + escapeHtml(fullText) + '\"'" "$hub_template_file"; then
    note_failure "T25-201: renderSessionExcerpt() 의 data-tooltip 이 사라짐(다른 툴팁이 함께 죽었을 수 있음)"
  fi
  # (d) 파일 전체 data-tooltip=" 리터럴 개수(T25-107 「정확히 N회」 관용구) — 이 숫자는
  # "화면에 커스텀 툴팁을 띄우는 트리거가 몇 개인가"의 대리 지표라, 개수가 바뀌면 그 트리거가
  # hub/README.md 「화면 배치」의 트리거 목록에도 함께 반영됐는지가 진짜 점검 대상이다(이
  # 검사 자체는 그 문서 반영까지는 못 본다 — 숫자만 못박아 사람이 diff 에서 보게 한다).
  # PRP 1회차 추정은 18 → 17(워크플로우 칩 툴팁 제거 1건)이었으나, 이슈 1(TR1)도 같은
  # 파일에서 함께 구현해 확장 셰브론 자신의 data-tooltip 도 사라진다(renderExpandToggle
  # 삭제) — 실측 18 → 16(−2). hub-card-gate-and-run-list-reset PRP(결정 CG9)가 orphan 칩의
  # 툴팁(TIER1_ORPHAN_TOOLTIP)을 새로 추가해 16 → 17(+1). docs/prps/hub-rate-limit-interruption.md
  # 결정 RI10 이 renderStateBadge() 의 interrupted 분기에 자기 줄(세션 배지는
  # interruptedBadgeTooltipText, 프로젝트 배지는 INTERRUPTED_TOOLTIP_PROJECT)을 새로
  # 추가해 17 → 18(+1) — 이 새 트리거(「한도 초과」 상태 배지)는 hub/README.md 「화면 배치」의
  # 트리거 목록(새로고침 버튼·…·소식 없음 상태 배지 다음)에 이미 함께 반영돼 있다(같은
  # PRP 구현). docs/prps/hub-session-modal-and-partial-update.md(결정 SC1·SC5) 가 카드
  # 상세보기 모달을 도입해 18 → 20(+2) — 모달 닫기 버튼("닫기 (Esc)", 상세 패널 닫기 버튼과
  # 글자까지 같은 문구·같은 트리거 종류라 README 목록에 새 항목을 만들지 않는다)과 모달
  # 루트의 티어 배지(카드의 티어 배지와 같은 문구·같은 트리거 종류 — README 의 "티어 배지"
  # 항목이 이미 포괄한다) — 둘 다 새 트리거 **종류**가 아니라 같은 종류의 새 인스턴스라
  # README 목록 자체를 고칠 필요가 없다. docs/prps/hub-subagent-background-pause.md(결정
  # BW10) 이 renderStateBadge() 의 background 분기에 자기 줄(세션 배지는
  # backgroundBadgeTooltipText, 프로젝트 배지는 BACKGROUND_TOOLTIP_PROJECT)을 새로 추가해
  # 20 → 21(+1) — 이 새 트리거(「백그라운드 대기」 상태 배지)는 hub/README.md 「화면 배치」의
  # 트리거 목록(…한도 초과 상태 배지 다음)에 이미 함께 반영돼 있다(같은 PRP 구현).
  # docs/prps/hub-session-modal-cleanup.md(결정 MX4)가 카드·카드 상세보기 머리의 프로젝트 단위
  # 진행률을 걷으며 「주인 세션 없음」 칩의 툴팁(진행률 렌더 함수의 라벨 툴팁 인자)이 함께 사라져
  # 21 → 20(−1) — 그 칩은 위 목록(「화면 배치」의 트리거 종류)에 든 적이 없어 문서 쪽 반영은 없다.
  # 같은 문서 M3(결정 MX1)가 카드 상세보기 머리의 패널 속성 함수를 걷으며 그 안의 file:// 안내 툴팁
  # 한 줄도 사라져 20 → 19(−1) — 트리거 종류 「file:// 안내」는 세션 줄·세션 카드가 같은 문구로 계속 달고
  # 있어 문서 쪽 반영은 역시 없다(사라진 것은 머리라는 인스턴스 하나다).
  # docs/prps/hub-session-row-layout-and-modal-size.md(결정 LM5)가 진행률 줄 맨 앞 단계 칩(renderTier1ActiveStep)에
  # 직전 기록 요약 툴팁을 달아 19 → 20(+1) — 걷힌 진행중 단계 줄이 화면에 그리던 그 요약의 유일한 자리다(요약이 있을 때만
  # 단다 — 보이는 글자와 같은 툴팁은 소음이다). hub/README.md 「화면 배치」 진행률 줄 서술에 반영했다.
  # docs/prps/harness-benchmark-adoption.md ⑨ 가 세션 식별 줄에 비용·컨텍스트 칩(renderSessionCost)을 더하며 20 → 21(+1) —
  # 정가 기준 추정 고지가 없으면 숫자가 청구액으로 읽히므로 칩이 있으면 툴팁이 늘 붙는다. 같은 README 목록(위 툴팁 서술)에 반영했다.
  # 같은 문서 개정 LM12 가 그 단계 칩을 걷으며 칩의 툴팁도 함께 사라져 21 → 20(−1) — hub/README.md 「화면 배치」 진행률 줄 서술에서 칩과 그 툴팁
  # 서술을 걷었다.
  # docs/prps/hub-approval-wait-badge.md(결정 AW4)가 세션 첫 줄에 승인 대기 표지(renderApprovalWaitBadge)를 더하며 20 → 21(+1) —
  # 표지의 판정 기준·거둬지는 조건을 말하는 정적 툴팁이다(보이는 글자 「승인 대기」에 없는 정보). hub/README.md 「화면 배치」의 승인 대기
  # 항목과 툴팁 서술에 반영했다.
  # 기대값을 21로 고정한다: 다른 트리거가 함께 죽으면 20 이하, 추가(단계 칩 툴팁 부활 포함)가 되돌아오면 22 이상.
  local data_tooltip_attribute_count_201
  data_tooltip_attribute_count_201=$(grep -c 'data-tooltip="' "$hub_template_file")
  if [[ "$data_tooltip_attribute_count_201" -ne 21 ]]; then
    note_failure "T25-201: data-tooltip=\" 리터럴이 ${data_tooltip_attribute_count_201}건(기대 21)"
  fi

  # T25-202(신설, 역 — 이슈 3, docs/prps/hub-ui-4-issues.md §4, 결정 WT3·WT4 서버 되돌림
  # 방지): hub_workflow.py 에서 제거된 필드·헬퍼가 되살아나지 않는지 본다. _metadata_field·
  # WORKFLOW_METADATA_MAX_CHARS 는 선택 항목 E(state 필드 유지)가 채택돼 예외다 — 여전히
  # 쓰인다.
  local workflow_py_relic_token_202 workflow_py_relic_count_202
  for workflow_py_relic_token_202 in 'promptPreview' 'resultPreview' 'prompt_preview' 'result_preview' \
      'phaseTitle' 'phase_title' '_optional_scrubbed_and_clipped'; do
    workflow_py_relic_count_202=$(grep -c -- "$workflow_py_relic_token_202" "$hub_workflow_file")
    if [[ "$workflow_py_relic_count_202" -ne 0 ]]; then
      note_failure "T25-202: hub_workflow.py 에 '$workflow_py_relic_token_202' 잔재가 ${workflow_py_relic_count_202}건(기대 0 — WT3·WT4 로 삭제됐어야 한다)"
    fi
  done

  # T25-203(신설, 정 — 이슈 4, docs/prps/hub-ui-4-issues.md §5, 결정 FT4): 순서가 뒤집히면
  # 사유가 거짓이 된다 — 키가 있는 끝난 대시보드가 FILE_MODE_DASHBOARD_HINT(서버를 켜라)로
  # 잘못 설명된다.
  local session_panel_empty_reason_body_203
  session_panel_empty_reason_body_203=$(sed -n '/function sessionPanelEmptyReason(session, isClickable){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$session_panel_empty_reason_body_203" ]]; then
    record_failure "$test_name" "T25-203: sessionPanelEmptyReason() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  local finished_task_branch_line_203 dashboard_key_branch_line_203
  finished_task_branch_line_203=$(grep -n 'tier1_is_finished_task' <<< "$session_panel_empty_reason_body_203" | head -1 | cut -d: -f1)
  dashboard_key_branch_line_203=$(grep -n 'session.dashboard_key' <<< "$session_panel_empty_reason_body_203" | head -1 | cut -d: -f1)
  if [[ -z "$finished_task_branch_line_203" || -z "$dashboard_key_branch_line_203" \
      || "$finished_task_branch_line_203" -ge "$dashboard_key_branch_line_203" ]]; then
    note_failure "T25-203: sessionPanelEmptyReason() 에서 tier1_is_finished_task 분기가 session.dashboard_key 분기보다 앞에 있지 않음(결정 FT4 위반 — 순서가 뒤집히면 사유가 거짓이 된다)"
  fi

  # T25-204(신설, 정+역 — 이슈 4, docs/prps/hub-ui-4-issues.md §5, 결정 FT2·FT6): 세대 판정
  # 함수·상수가 있고, 임계값은 새 리터럴을 만들지 않고 stale_after_ms 를 재사용한다.
  if ! grep -qF 'def is_session_tier1_from_finished_task(' "$hub_session_file"; then
    note_failure "T25-204: hub_session.py 에 is_session_tier1_from_finished_task() 가 없음"
  fi
  if ! grep -qF 'TIER1_FINISHED_PERCENT' "$hub_session_file"; then
    note_failure "T25-204: hub_session.py 에 TIER1_FINISHED_PERCENT 상수가 없음"
  fi
  local is_session_tier1_from_finished_task_body_204
  is_session_tier1_from_finished_task_body_204=$(awk '
    /^def is_session_tier1_from_finished_task\(/{flag=1}
    /^def compute_session_view\(/{exit}
    flag{print}
  ' "$hub_session_file")
  if [[ -z "$is_session_tier1_from_finished_task_body_204" ]]; then
    record_failure "$test_name" "T25-204: is_session_tier1_from_finished_task~compute_session_view 사이 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'stale_after_ms' <<< "$is_session_tier1_from_finished_task_body_204"; then
    note_failure "T25-204: is_session_tier1_from_finished_task() 가 stale_after_ms 를 쓰지 않음(결정 FT2 위반 — 새 임계값 상수를 재사용하지 않고 있음)"
  fi
  # 30 * 60(분→ms 환산 곱셈) 형태로 좁힌다 — 이 함수의 docstring 은 commands/dashboard.md
  # 의 「30분 이내 갱신이면 RECENT」 문구를 그대로 인용하므로(정확한 인용을 위해 손대지
  # 않는다), 산문 속 "30" 까지 잡는 \b30\b 는 그 인용문에서 오탐한다(실측 확인).
  if grep -qE '\b30[[:space:]]*\*[[:space:]]*60\b' <<< "$is_session_tier1_from_finished_task_body_204"; then
    note_failure "T25-204: is_session_tier1_from_finished_task() 본문에 새 '30 * 60' 리터럴이 있음(결정 FT2 위반 — stale_after_ms 재사용 대신 하드코딩)"
  fi

  # T25-188(신설, hub-unified-card-tree-ui PRP §10.2-13 · 개정, hub-tree-view-and-signal-fixes
  # PRP §11.1): 화면과 문서가 어긋난 채 남는 것을 막는다(T25-36·T25-45 와 같은 관용구).
  # "트리 모드"·"보기 토글" 을 토큰으로 쓴다 — 맨 "트리"만 쓰면 "트리거" 등 무관 낱말과
  # 부분 문자열이 겹친다(실측). 확장부가 트리 서술로 바뀌어 "연결선"을 첫 서브체크에 더한다.
  if ! grep -qF '확장' "$hub_readme_file" || ! grep -qF '세션 행' "$hub_readme_file" \
    || ! grep -qF '연결선' "$hub_readme_file"; then
    note_failure "T25-188: hub/README.md 에 확장·세션 행·연결선 서술이 없음"
  fi
  if grep -qF '트리 모드' "$hub_readme_file" || grep -qF '보기 토글' "$hub_readme_file"; then
    note_failure "T25-188: hub/README.md 에 트리 모드·보기 토글 서술이 남아 있음"
  fi

  # ── docs/prps/hub-agent-runs-and-prompt-source.md §10.2 신설분(T25-205~T25-212) ──

  # T25-205(신설, ★순수 계약 — T25-150·T25-165 와 같은 기준): hub_subagent.py·
  # hub_subagent_read.py 가 존재하고, hub_subagent.py(★순수, 결정 AR2)에 파일시스템·시각
  # 접근 흔적이 없다.
  local hub_subagent_file="$REPO_ROOT/hub/bin/hub_subagent.py"
  local hub_subagent_read_file="$REPO_ROOT/hub/bin/hub_subagent_read.py"
  if [[ ! -f "$hub_subagent_file" ]]; then
    record_failure "$test_name" "T25-205: hub_subagent.py 가 존재하지 않음"
    return 1
  fi
  if [[ ! -f "$hub_subagent_read_file" ]]; then
    record_failure "$test_name" "T25-205: hub_subagent_read.py 가 존재하지 않음"
    return 1
  fi
  if grep -qE 'open\(|Path\(|time\.|os\.' "$hub_subagent_file"; then
    note_failure "T25-205: hub_subagent.py 에 순수 계약 위반 흔적(open(/Path(/time./os.)이 있음"
  fi

  # T25-206(신설, 계약 A 기계적 강제 — T25-166 과 같은 판단, 더 단순한 형태로 충분하다):
  # hub_subagent.py 의 SubagentMeta 는 필드가 5개뿐이라(title·agent_type·model·
  # started_at_ms·resume_title) T25-166 급의 kwarg 승인 목록 정규식 없이도, "문자열 성격 필드 수" ==
  # "승인된 상한 헬퍼(_scrubbed_and_clipped·_metadata_field) 호출 수"라는 산술 등식 하나로
  # 같은 것을 강제할 수 있다. started_at_ms(int)만 두 헬퍼를 거치지 않아야 한다.
  # 재개 요약 필드가 생긴 뒤(hub-agent-title-and-excerpt-freshness.md M2, 결정 TF8·TF13)에도 논리는 그대로다:
  # 문자열 필드 4(title·agent_type·model·resume_title) == 헬퍼 호출 줄 4(parse_subagent_meta 3 + 재개 요약을
  # 제목으로 만드는 _resume_summary_title 1). 재개 요약의 스크럽을 빼먹으면 3 ≠ 4 로 이 가드가 잡는다.
  local subagent_meta_body_206 subagent_str_field_count_206 subagent_helper_call_count_206
  subagent_meta_body_206=$(awk '/^class SubagentMeta:/{flag=1; next} flag && /^# ----/{exit} flag{print}' "$hub_subagent_file")
  if [[ -z "$subagent_meta_body_206" ]]; then
    record_failure "$test_name" "T25-206: SubagentMeta 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  subagent_str_field_count_206=$(grep -cE '^\s+[a-z_]+:\s*str\b' <<< "$subagent_meta_body_206")
  subagent_helper_call_count_206=$(grep -E '_scrubbed_and_clipped\(|_metadata_field\(' "$hub_subagent_file" | grep -cv '^def ')
  if [[ "$subagent_str_field_count_206" -ne "$subagent_helper_call_count_206" ]]; then
    note_failure "T25-206: SubagentMeta 의 문자열 필드 수($subagent_str_field_count_206)와 상한 헬퍼 호출 수($subagent_helper_call_count_206)가 다름(계약 A 미적용 필드가 있을 수 있음)"
  fi

  # T25-207(신설, GOTCHA 4 유지 — T25-92 의 결정 AR4 판 재확인): summarize_agent_runs 본문에
  # is_running_subagent( 호출이 있고, ended_at_ms is None 직접 비교가 없다. T25-92 와 같은
  # 이유로 종료 앵커(`flag && /^def /{exit}`)를 건다(재검수 1회차 M5).
  local summarize_agent_runs_body_207
  summarize_agent_runs_body_207=$(awk '/^def summarize_agent_runs\(/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_session_file")
  if [[ -z "$summarize_agent_runs_body_207" ]]; then
    record_failure "$test_name" "T25-207: summarize_agent_runs 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if [[ "$(grep -c 'is_running_subagent(' <<< "$summarize_agent_runs_body_207")" -eq 0 ]]; then
    note_failure "T25-207 재확인: summarize_agent_runs 자신의 본문에서 is_running_subagent 호출을 찾지 못함(GOTCHA 4)"
  fi
  if [[ "$(grep -c 'ended_at_ms is None' <<< "$summarize_agent_runs_body_207")" -ne 0 ]]; then
    note_failure "T25-207 재확인: summarize_agent_runs 자신의 범위에 ended_at_ms is None 직접 비교가 새로 생김"
  fi

  # T25-208(신설, 결정 AR5 — K2 + agent_id 타이브레이커): 정렬 키가 실행 중 우선과 agent_id
  # 동률 처리를 함께 갖는다.
  if ! grep -qF '0 if run.is_running else 1' <<< "$summarize_agent_runs_body_207"; then
    note_failure "T25-208: summarize_agent_runs 정렬 키에 실행 중 우선순위(K2)가 없음"
  fi
  if ! grep -qF 'run.agent_id' <<< "$summarize_agent_runs_body_207"; then
    note_failure "T25-208: summarize_agent_runs 정렬 키에 agent_id 타이브레이커가 없음"
  fi

  # T25-209(신설, 결정 AR8·AR11·AR12): 실행 목록 렌더 계약 4가지가 템플릿에 있고,
  # shouldRenderSession 이 visibleAgentRunRows 를 경유한다(GOTCHA 3).
  local agent_run_list_token_209
  for agent_run_list_token_209 in "MAX_VISIBLE_AGENT_RUNS" "visibleAgentRunRows" "renderAgentRunList" ".agent-run-list{"; do
    if ! grep -qF "$agent_run_list_token_209" "$hub_template_file"; then
      note_failure "T25-209: hub_template.html 에 $agent_run_list_token_209 이 없음"
    fi
  done
  local should_render_session_body_209
  should_render_session_body_209=$(sed -n '/function shouldRenderSession(session){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$should_render_session_body_209" ]]; then
    note_failure "T25-209: shouldRenderSession() 범위 추출 실패 — 앵커가 깨졌다"
  elif ! grep -qF 'visibleAgentRunRows' <<< "$should_render_session_body_209"; then
    note_failure "T25-209: shouldRenderSession() 이 visibleAgentRunRows 를 경유하지 않음"
  fi

  # T25-210(신설, 역 — 결정 AR12 되돌림 방지): 첫 줄 타입 합계 칩 행의 흔적
  # (MAX_VISIBLE_AGENT_CHIPS·.agent-runs{)이 남아 있지 않다.
  if grep -qF 'MAX_VISIBLE_AGENT_CHIPS' "$hub_template_file"; then
    note_failure "T25-210: hub_template.html 에 MAX_VISIBLE_AGENT_CHIPS 가 남아 있음(결정 AR12 되돌림)"
  fi
  if grep -qF '.agent-runs{' "$hub_template_file"; then
    note_failure "T25-210: hub_template.html 에 .agent-runs{ 규칙이 남아 있음(결정 AR12 되돌림)"
  fi

  # T25-211(신설, 역 — 결정 PS4): 훅의 프롬프트 발췌 생산 심볼이 전부 사라졌다. 역의 역 —
  # hub_session_facts.parse_event_line 의 소비 쪽(payload.get("p"))도 사라졌다. 재조준(M1,
  # 결정 BW11) — parse_event_line 전체가 hub_session_facts.py 로 옮겼다. 본문 추출 실패를
  # 침묵 통과가 아니라 실패로 보고한다(GOTCHA 6 — 옮긴 코드를 물던 역방향 검사는 대상이
  # 없으면 "없음"이 곧 통과가 된다. 예전에는 이 검사가 그 함정에 있었다).
  local prompt_symbol_211
  for prompt_symbol_211 in "PROMPT_EXCERPT_MAX_CHARS" "strip_auto_injected_blocks" "AUTO_INJECTED_PROMPT_BLOCK"; do
    if grep -qF "$prompt_symbol_211" "$hub_hook_file"; then
      note_failure "T25-211: hub_hook.py 에 $prompt_symbol_211 이 남아 있음(결정 PS4 되돌림)"
    fi
  done
  if grep -qF '"p"' "$hub_hook_file"; then
    note_failure "T25-211: hub_hook.py 에 \"p\" 키 흔적이 남아 있음(결정 PS4 되돌림)"
  fi
  local parse_event_line_body_211
  parse_event_line_body_211=$(awk '/^def parse_event_line\(/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_session_facts_file")
  if [[ -z "$parse_event_line_body_211" ]]; then
    record_failure "$test_name" "T25-211: parse_event_line() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if grep -qF '"p"' <<< "$parse_event_line_body_211"; then
    note_failure "T25-211: hub_session_facts.parse_event_line 에 \"p\" 키 소비가 남아 있음(결정 PS4 되돌림)"
  fi
  # 재검수 1회차 M9 — 설계 §10.2 「문서 정합」 행(README·commands/hub.md 에 옛 500자 보관
  # 고지가 되살아나지 않는가)이 빠져 있었다. T25-104 의 "12개 파일" 부정 검사와 같은 관용구.
  if grep -qF "500자" "$hub_readme_file"; then
    note_failure "T25-211: hub/README.md 에 '500자' 문자열이 남아 있음(옛 프롬프트 보관 고지 되돌림)"
  fi
  if grep -qF "프롬프트 앞부분(500자)" "$hub_command_file"; then
    note_failure "T25-211: commands/hub.md 에 '프롬프트 앞부분(500자)' 문구가 남아 있음(옛 설치 동의 문구 되돌림)"
  fi

  # T25-212(신설, 결정 AR8 — 320px 붕괴 방어선): .agent-run>.agent-chip 규칙에
  # flex:0 0 auto 가 있다. 지우면 칩 글자가 두 줄로 찢어진다(목업 1차 실측).
  local agent_run_chip_rule_212
  agent_run_chip_rule_212=$(grep -F '.agent-run>.agent-chip{' "$hub_template_file")
  if [[ -z "$agent_run_chip_rule_212" ]]; then
    note_failure "T25-212: hub_template.html 에 .agent-run>.agent-chip{ 규칙이 없음"
  elif [[ "$agent_run_chip_rule_212" != *"flex:0 0 auto"* ]]; then
    note_failure "T25-212: .agent-run>.agent-chip{ 규칙에 flex:0 0 auto 가 없음(320px 칩 줄바꿈 방어선 누락)"
  fi

  # ── docs/prps/hub-live-session-native-source.md §7.5 신설분(T25-213~217) ──

  # T25-213(신설, ★순수 계약 — T25-205 와 동형): hub_live_session.py·hub_live_session_read.py
  # 가 존재하고, hub_live_session.py(★순수, 결정 LS2)에 파일시스템·시각 접근 흔적이 없다.
  local hub_live_session_file="$REPO_ROOT/hub/bin/hub_live_session.py"
  local hub_live_session_read_file="$REPO_ROOT/hub/bin/hub_live_session_read.py"
  if [[ ! -f "$hub_live_session_file" ]]; then
    record_failure "$test_name" "T25-213: hub_live_session.py 가 존재하지 않음"
    return 1
  fi
  if [[ ! -f "$hub_live_session_read_file" ]]; then
    record_failure "$test_name" "T25-213: hub_live_session_read.py 가 존재하지 않음"
    return 1
  fi
  if grep -qE 'open\(|Path\(|time\.|os\.' "$hub_live_session_file"; then
    note_failure "T25-213: hub_live_session.py 에 순수 계약 위반 흔적(open(/Path(/time./os.)이 있음"
  fi

  # T25-214(신설, 잎 계약 — T25-102 와 동형): hub_live_session.py 는 어떤 허브 모듈도
  # 임포트하지 않는다(결정 LS2 — hub_live_session 은 잎, hub_session←hub_project←hub_model
  # 사슬의 시작점). 앵커는 줄 시작 들여쓰기를 허용한다(검수 1회차 L2) — 함수 안에
  # 들여써서 넣은 `    import hub_parse` 는 ^(import|from) 로는 못 잡는다.
  if grep -qE '^[[:space:]]*(import|from) hub_' "$hub_live_session_file"; then
    note_failure "T25-214: hub_live_session.py 가 다른 허브 모듈을 임포트함(잎 모듈 계약 위반)"
  fi

  # T25-215(신설, 결정 LS5 화해 표 — 행 누락 방지, 검수 1회차 H2 로 강화): hub_session.py
  # 에 화해 표의 네 분기(not_listed·busy·idle·listed)가 모두 있다 — 표의 한 행이 조용히
  # 사라지는 것을 막는다. bare 토큰이 아니라 "roster == "X"" 전체 비교식을 찾는다 —
  # "idle" 은 이 파일에 SessionState 리터럴·반환형 선언·반환값으로 8회 등장해(검수 1회차
  # 재현), idle 행을 통째로 지워도 bare 토큰 grep 은 나머지 7회에 가려 통과했다. 네 서브체크를
  # for 루프 하나의 공유 note_failure 호출로 묶지 않고 각자 독립된 호출로 푼다(T25-170a~e 와
  # 같은 형태) — 공유 호출이면 collect_guard_ids 가 "T25-215" 하나만 추출해 서브체크별 변조행을
  # 등록할 수 없다(재작업 중 실측: T37-11 K5 가 T25-215b·T25-215c 를 소스에 없는 고아 원장
  # ID 로 잡았다).
  if ! grep -qF -- 'roster == "not_listed"' "$hub_session_file"; then
    note_failure "T25-215: hub_session.py 에 not_listed 분기가 없음(결정 LS5 화해 표 행 누락)"
  fi
  if ! grep -qF -- 'roster == "busy"' "$hub_session_file"; then
    note_failure "T25-215b: hub_session.py 에 busy 분기가 없음(결정 LS5 화해 표 행 누락)"
  fi
  if ! grep -qF -- 'roster == "idle"' "$hub_session_file"; then
    note_failure "T25-215c: hub_session.py 에 idle 분기가 없음(결정 LS5 화해 표 행 누락)"
  fi
  if ! grep -qF -- 'roster == "listed"' "$hub_session_file"; then
    note_failure "T25-215d: hub_session.py 에 listed 분기가 없음(결정 LS5 화해 표 행 누락)"
  fi

  # T25-216(신설, 결정 LS8 — footgun 방어선 고정, 검수 1회차 M3 로 강화): hub_live_session.py
  # 에 pid 유효성 검사 전체 식이 있다 — bare "pid > 0" 부분문자열은 그 자리에 가짜 주석만
  # 남기고 실제 검사를 지워도(예: "# invariant: pid > 0") 걸리지 않는다(검수 1회차 재현,
  # rc=0). bool 배제(검수 1회차 L1)·상한(검수 1회차 H1-3)까지 포함한 전체 식을 고정한다.
  if ! grep -qF 'isinstance(pid, int) and not isinstance(pid, bool) and 0 < pid <= LIVE_SESSION_PID_MAX' "$hub_live_session_file"; then
    note_failure "T25-216: hub_live_session.py 에 pid 유효성 검사 전체 식이 없음(결정 LS8 footgun 방어선 누락)"
  fi

  # 래칫 고지(검수 2회차 L2): 위 T25-215·215b·215c·215d·216 은 전부 grep -qF 문자열 매칭이라
  # 소스에 실제 검사 대신 그 문자열을 담은 **주석**만 남겨도(예: "# roster == \"busy\"") 통과한다
  # — 이 다섯은 「검출기」가 아니라 「래칫」이다(그 문자열이 소스 어딘가에 있다는 사실만
  # 고정하고, 실제로 동작하는지는 단위 테스트가 따로 검증한다). 참고: hub_session.py 의
  # _compute_base_state 함수 안에 이미 "# roster == \"unknown\"" 주석이 있어, 훗날 unknown
  # 용 서브체크를 같은 grep -qF 방식으로 추가하면 그 주석 자체에 걸려 코드를 지워도 항상
  # 통과하는 오탐이 난다(T39-5 의 줄 번호 인용 래칫 — python/coding-style.md 관례대로
  # 함수명으로 앵커한다, 파일:줄번호 형태를 쓰지 않는다).

  # T25-217(신설, 결정 LS11 — SESSIONS_DIR 경로 고정, 검수 1회차 M4): hub_collect.py 의
  # SESSIONS_DIR 이 ~/.claude/sessions 를 가리킨다. 리터럴이 흔들리면(예: "session" 오타)
  # 디렉터리 자체가 사라져 모든 세션이 unknown 으로 조용히 폴백한다 — 오늘의 동작과
  # 구분되지 않는 완전 무성음 고장이라 기계적으로 고정한다.
  if ! grep -qF '".claude" / "sessions"' "$hub_collect_file"; then
    note_failure "T25-217: hub_collect.py 의 SESSIONS_DIR 이 .claude/sessions 를 가리키지 않음"
  fi

  # ── docs/prps/hub-session-list-and-glow-fixes.md §8.1 신설분(T25-218~T25-221) ──

  # T25-218 은 폐기했다(카드 상세보기 정리 M3, 결정 MX1·MX13, docs/prps/hub-session-modal-cleanup.md
  # §10.1) — 지키던 것은 「프로젝트 요약(모달 루트)도 끝난 대시보드를 사유로 대체한다」(결정 CD1~CD7)였는데,
  # 루트가 어떤 경우에도 패널을 열지 않게 되며 템플릿의 상수·클릭 가능 산식·사유 분기와 README 서술이
  # 함께 사라져 대상이 없다(그 부재는 T25-247 의 역검사가 문다). 서버 필드·헬퍼(ProjectView 의
  # tier1_is_finished_task, is_project_tier1_from_finished_session_task)의 존재는 tests/hub 의
  # test_hub_project 가 이미 행동으로 덮고, 서버 계약 가지치기는 후속 과제다(같은 문서 MX12). 번호는
  # 다시 쓰지 않는다.

  # T25-219(신설, 이슈 2 — 결정 SO1~SO5): 세션 목록 정렬이 상태 우선순위를 먼저 본다.
  # ① 서버 PROJECT_STATE_PRIORITY 와 클라이언트 SESSION_STATE_ORDER 의 4값 순서를 각각
  # 추출해 대조(추출 실패도 실패로 보고 — 공허 통과 방지) ② visibleSessionsOf() 가
  # sessionStateRank( 를 경유한다 ③ 역 — 시간 단독 비교로 되돌아가지 않았다.
  # 상태 이름만 뽑는다 — "PROJECT_STATE_PRIORITY: tuple[SessionState, ...] = (...)" 처럼
  # 타입 힌트에 소문자가 섞여 있어 순서 문자열 전체에 [a-z]+ 를 걸면 "SessionState" 의
  # 소문자 부분("ession"·"tate")까지 끼어든다(실측 확인) — 튜플/배열 리터럴 부분만 먼저
  # 잘라내고, 그 안에서 인용부호로 감싼 토큰만 추출한다.
  local server_state_priority_214 client_state_order_214
  server_state_priority_214=$(grep -oE 'PROJECT_STATE_PRIORITY[^=]*= \([^)]*\)' "$hub_project_file" | head -1)
  client_state_order_214=$(grep -oE 'SESSION_STATE_ORDER = \[[^]]*\]' "$hub_template_file" | head -1)
  if [[ -z "$server_state_priority_214" ]]; then
    note_failure "T25-219: hub_project.py 에서 PROJECT_STATE_PRIORITY 선언을 찾지 못함"
  elif [[ -z "$client_state_order_214" ]]; then
    note_failure "T25-219: hub_template.html 에서 SESSION_STATE_ORDER 선언을 찾지 못함"
  else
    local server_states_214 client_states_214
    server_states_214=$(grep -oE '"[a-z]+"' <<< "$server_state_priority_214" | tr -d '"' | tr '\n' ',')
    client_states_214=$(grep -oE "'[a-z]+'" <<< "$client_state_order_214" | tr -d "'" | tr '\n' ',')
    if [[ -z "$server_states_214" || "$server_states_214" != "$client_states_214" ]]; then
      note_failure "T25-219: PROJECT_STATE_PRIORITY(${server_states_214})와 SESSION_STATE_ORDER(${client_states_214})의 순서가 어긋남"
    fi
  fi
  local visible_sessions_of_body_214
  visible_sessions_of_body_214=$(sed -n '/function visibleSessionsOf(project){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$visible_sessions_of_body_214" ]]; then
    note_failure "T25-219: visibleSessionsOf() 범위 추출 실패 — 앵커가 깨졌다"
  else
    if ! grep -qF 'compareSessionsForDisplay' <<< "$visible_sessions_of_body_214"; then
      note_failure "T25-219: visibleSessionsOf() 가 compareSessionsForDisplay 를 경유하지 않음(결정 SO4 위반 — 비교 함수만 교체해야 한다)"
    fi
    if grep -qE 'return b\.last_event_at_ms - a\.last_event_at_ms;? *\}' <<< "$visible_sessions_of_body_214"; then
      note_failure "T25-219: visibleSessionsOf() 에 시간 단독 비교가 남아 있음(결정 SO1 되돌림 — 상태 우선순위가 사라졌다)"
    fi
  fi
  # sessionStateRank 경유는 비교 함수 쪼(SO1·SO5) 자신의 몸통에서 확인한다 — visibleSessionsOf
  # 는 비교 함수를 교체만 하고(SO4), 상태 순위 조회는 compareSessionsForDisplay 안에서 한다.
  local compare_sessions_for_display_body_214
  compare_sessions_for_display_body_214=$(sed -n '/function compareSessionsForDisplay(a, b){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$compare_sessions_for_display_body_214" ]]; then
    note_failure "T25-219: compareSessionsForDisplay() 범위 추출 실패 — 앵커가 깨졌다"
  elif ! grep -qF 'sessionStateRank(' <<< "$compare_sessions_for_display_body_214"; then
    note_failure "T25-219: compareSessionsForDisplay() 가 sessionStateRank( 를 경유하지 않음(결정 SO3 위반)"
  fi

  # T25-220(신설, 이슈 3 — 결정 PT1~PT7, (A) 채택 확정 §5.4): 끝난 작업 경계 이전에 시작된
  # 실행은 화면에서 빠진다. ① hub_session.py 의 필드·인자 ② compute_session_view 에서 FT
  # 판정이 summarize_agent_runs 호출보다 앞줄(순서가 뒤집히면 경계를 못 넘긴다) ③ 클라이언트
  # visibleAgentRunRows() 가 run.is_previous_task 를 경유한다((A) 안 — 필터가 여기 있다) ④ 역
  # — 새 30*60 리터럴이 없다(경계는 stale_after_ms 파생이지 새 임계값이 아니다) ⑤ README 서술.
  if ! grep -qF 'is_previous_task: bool = False' "$hub_session_file"; then
    note_failure "T25-220: hub_session.py 의 SubagentRunView 에 is_previous_task 필드가 없음"
  fi
  if ! grep -qF 'previous_task_boundary_ms' "$hub_session_file"; then
    note_failure "T25-220: hub_session.py 에 previous_task_boundary_ms 인자가 없음"
  fi
  # 3회차 개정(docs/prps/hub-card-gate-and-run-list-reset.md §7.1 「T25-220 개정」) — RL2 가
  # PT1 의 FT 게이트를 폐지하며 "FT 판정이 summarize_agent_runs 호출보다 앞줄" 제약 자체가
  # 사라졌다. 자리를 지우지 않고 무는 대상을 바꾼다 — summarize_agent_runs 호출이
  # previous_task_boundary_ms() 로 유도한 경계를 받는지로.
  local compute_session_view_body_215
  compute_session_view_body_215=$(awk '/^def compute_session_view\(/{flag=1} /^def summarize_agent_runs\(/{exit} flag{print}' "$hub_session_file")
  if [[ -z "$compute_session_view_body_215" ]]; then
    note_failure "T25-220: compute_session_view~summarize_agent_runs 사이 본문 추출 실패 — 앵커가 깨졌다"
  elif ! grep -qF 'previous_task_boundary_ms(tier1, last_human_prompt_at_ms, is_dashboard_enabled)' <<< "$compute_session_view_body_215"; then
    note_failure "T25-220: compute_session_view() 의 summarize_agent_runs() 호출이 previous_task_boundary_ms() 로 유도한 경계를 받지 않음(결정 RL2 위반 — PT1 의 FT 게이트는 폐지됐다)"
  fi
  local visible_agent_run_rows_body_215
  visible_agent_run_rows_body_215=$(sed -n '/function visibleAgentRunRows(runs){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$visible_agent_run_rows_body_215" ]]; then
    note_failure "T25-220: visibleAgentRunRows() 범위 추출 실패 — 앵커가 깨졌다"
  elif ! grep -qF 'run.is_previous_task' <<< "$visible_agent_run_rows_body_215"; then
    note_failure "T25-220: visibleAgentRunRows() 가 run.is_previous_task 를 경유하지 않음(결정 PT4-A 위반)"
  fi

  # T25-220 서브체크(재검수 1회차 MEDIUM-1): renderAgentRunList() 의 오버플로 카운트
  # (currentTaskRunCount, 1430행)가 visibleAgentRunRows() 의 필터 조건(!run.is_previous_task,
  # 1399행)을 리터럴로 복제한다 — 공유 헬퍼로 뽑지 않은 이유는 바로 위 검사가 이미
  # visibleAgentRunRows 본문의 그 리터럴을 앵커로 쓰기 때문이다(hub-session-list-and-glow-fixes
  # PRP §8.1). 그 대가로 두 리터럴이 드리프트하면(visibleAgentRunRows 의 필터에 조건이
  # 추가되는데 1430행이 갱신되지 않으면) "+N건 더" 카운트가 실제보다 커지는 회귀가 조용히
  # 재발하므로, 두 필터 리터럴을 각각 추출해 대조한다 — currentTaskRunCount 줄에
  # "run.is_previous_task" 라는 낱말이 있는지만 보면 1427행 주석이 같은 낱말을 이미 언급해
  # 공허 통과한다(실측 확인).
  local render_agent_run_list_body_215 current_task_run_count_line_215
  render_agent_run_list_body_215=$(sed -n '/function renderAgentRunList(runs){/,/^  }$/p' "$hub_template_file")
  current_task_run_count_line_215=$(grep -F 'currentTaskRunCount =' <<< "$render_agent_run_list_body_215" | head -1)
  if [[ -z "$render_agent_run_list_body_215" ]]; then
    note_failure "T25-220: renderAgentRunList() 범위 추출 실패 — 앵커가 깨졌다"
  elif [[ -z "$current_task_run_count_line_215" ]]; then
    note_failure "T25-220: renderAgentRunList() 에 currentTaskRunCount 산식이 없음(오버플로 카운트 가드 소실)"
  else
    local visible_run_filter_215 current_task_run_filter_215
    visible_run_filter_215=$(grep -oE 'filter\(function\(run\)\{ return [^;]+; \}\)' <<< "$visible_agent_run_rows_body_215" | head -1)
    current_task_run_filter_215=$(grep -oE 'filter\(function\(run\)\{ return [^;]+; \}\)' <<< "$current_task_run_count_line_215" | head -1)
    if [[ -z "$visible_run_filter_215" || "$visible_run_filter_215" != "$current_task_run_filter_215" ]]; then
      note_failure "T25-220: renderAgentRunList() 의 currentTaskRunCount 필터가 visibleAgentRunRows() 필터 조건과 어긋남(오버플로 카운트 드리프트)"
    fi
  fi
  local summarize_agent_runs_body_215
  summarize_agent_runs_body_215=$(awk '/^def summarize_agent_runs\(/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_session_file")
  if grep -qE '\b30[[:space:]]*\*[[:space:]]*60\b' <<< "$summarize_agent_runs_body_215"; then
    note_failure "T25-220: summarize_agent_runs() 본문에 하드코딩된 30분→ms 곱셈 리터럴이 있음(결정 PT1 위반 — 경계는 stale_after_ms 파생이어야 한다)"
  fi
  if ! grep -qF '끝난 작업의 실행은 목록에서 빠지고' "$hub_readme_file"; then
    note_failure "T25-220: hub/README.md 에 이전 작업 실행이 목록에서 빠진다는 서술이 없음((A) 채택 확정 반영)"
  fi

  # T25-220 서브체크(재검수 1회차 MEDIUM-2, PRP §5.4 4항 「(A) 채택 확정」): 실행이 전부
  # 이전 작업인 done 세션은 보이는 실행·칩이 0개가 되어 세션 줄 자체가 사라지는 2차 효과를
  # 결정 V2 의 정확한 귀결로 수용한다(회귀가 아니다). 이 저장소에는 hub_template.html 의
  # JS 를 실행하는 테스트 메커니즘이 없어(node/jsdom 부재 — 이 파일의 T25-2xx 검사 전부가
  # grep 기반 구조 검사인 것과 같은 이유) 그 동작(행이 실제로 사라진다)을 실행해 고정할 수
  # 없으므로, 기존 관례를 따라 shouldRenderSession() 의 done 숨김 조건식 전체를 리터럴로
  # 고정해 위 T25-209(visibleAgentRunRows 경유 확인)와 T25-220(is_previous_task 경유 확인)가
  # 이미 잇는 연쇄의 마지막 고리를 채운다.
  local should_render_session_body_215
  should_render_session_body_215=$(sed -n '/function shouldRenderSession(session){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$should_render_session_body_215" ]]; then
    note_failure "T25-220: shouldRenderSession() 범위 추출 실패 — 앵커가 깨졌다"
  elif ! grep -qF "if(session.state === 'done' && !displayableExcerpt(session.task_excerpt) && !hasVisibleChip) return false;" <<< "$should_render_session_body_215"; then
    note_failure "T25-220: shouldRenderSession() 의 done 숨김 조건식이 리터럴과 다름(결정 V2 의 2차 효과 고정 깨짐)"
  fi

  # T25-221(신설, 이슈 4 — 결정 GW1·GW2): 작업중 카드 글로우의 spread 를 -1px 로,
  # card-open 조합의 spread 도 함께 -1px 로 올린다(blur 차 14 vs 20 으로 판별자를 남긴다).
  # 기본 규칙의 box-shadow 선언은 셀렉터·여는 중괄호와 다른 물리 행에 있다(줄바꿈된 CSS
  # 선언) — grep 은 한 줄 단위로만 매칭하므로 `.card.card-working::after{...}` 를 통째로
  # 앵커하지 않고, 세미콜론으로 끝나는 그 선언 자체(다중 선언 블록 중 하나)만 리터럴로
  # 뽑는다. card-open 조합 규칙은 한 줄짜리 단일 선언이라 셀렉터까지 함께 앵커할 수 있다.
  local card_working_shadow_216 card_open_shadow_216
  card_working_shadow_216=$(grep -oE 'box-shadow:inset 0 0 [0-9]+px -[0-9]+px var\(--accent\);' "$hub_template_file" | head -1)
  card_open_shadow_216=$(grep -oE '\.card\.card-open\.card-working::after\{box-shadow:inset 0 0 [0-9]+px -[0-9]+px var\(--accent\)\}' "$hub_template_file" | head -1)
  if [[ "$card_working_shadow_216" != "box-shadow:inset 0 0 14px -1px var(--accent);" ]]; then
    note_failure "T25-221: .card.card-working::after 의 inset bloom 이 14px -1px 가 아님(결정 GW1 위반) — '${card_working_shadow_216:-없음}'"
  fi
  if [[ "$card_open_shadow_216" != '.card.card-open.card-working::after{box-shadow:inset 0 0 20px -1px var(--accent)}' ]]; then
    note_failure "T25-221: .card.card-open.card-working::after 의 inset bloom 이 20px -1px 가 아님(결정 GW2 위반) — '${card_open_shadow_216:-없음}'"
  fi
  # blur 는 카드-open 조합이 여전히 더 넓다(20 > 14) — spread 를 같게 맞춰도 판별자가 blur
  # 차로 남는다는 결정 GW2 의 근거를 부등식으로 직접 확인한다(리터럴이 아니라 관계를 고정).
  # "inset 0 0 " 의 두 오프셋 0 을 blur 값으로 잘못 집는 것을 피하려고(grep -oE '[0-9]+' 는
  # 첫 매치가 그 0 이 되어 늘 0 대 0 을 비교하는 공허 통과를 낸다 — 실측 확인) sed 캡처
  # 그룹으로 "inset 0 0 " 바로 뒤 숫자만 뽑는다.
  local card_working_blur_216 card_open_blur_216
  card_working_blur_216=$(sed -E 's/.*inset 0 0 ([0-9]+)px.*/\1/' <<< "$card_working_shadow_216")
  card_open_blur_216=$(sed -E 's/.*inset 0 0 ([0-9]+)px.*/\1/' <<< "$card_open_shadow_216")
  if [[ -z "$card_working_blur_216" || -z "$card_open_blur_216" || "$card_working_blur_216" == "$card_working_shadow_216" ]] \
      || ! [[ "$card_open_blur_216" -gt "$card_working_blur_216" ]] 2>/dev/null; then
    note_failure "T25-221: card-open 조합의 blur(${card_open_blur_216:-?})가 기본 규칙의 blur(${card_working_blur_216:-?})보다 넓지 않음(결정 GW2 의 판별자 근거 위반)"
  fi

  # ── docs/prps/hub-card-gate-and-run-list-reset.md §7.1 신설분(T25-222~T25-223) ──

  # T25-222(신설, 결정 RL1~RL5·RL8·RL10, dashboard-into-hub.md M2 로 ⑨ 재조준): 실행
  # 목록의 경계가 대시보드 작업 시작 시각(기록 파일 밖의 디렉터리 조회 없이 얻는 값)으로
  # 바뀐다. ① SessionFacts 필드 ② 훅 분기가 채운다 ③ Tier1Snapshot 필드 ④ 경계 유도가
  # 순수 함수 1곳 ⑤ 네 갈래가 다 있다 ⑥ 역 — FT 파생 경계가 되살아나지 않았다 ⑦ 실행 중
  # 면제(RL3) ⑧ tier1_is_finished_task 는 살아 있다(RL5) ⑨ 역 — 순수·I/O 모듈 넷에
  # init-values 리터럴이 남지 않는다(HD8) ⑩ 수집이 추가 디렉토리 조회를 하지 않는다
  # ⑪ RL10 스위치 이름·경로가 정본과 같다 ⑫ RL10 페일 방향이 켜짐이다 ⑬ README 서술.
  # last_prompt_at_ms 필드·대입 2건은 M1(결정 BW11)로 hub_session_facts.py 에 재조준했다 —
  # SessionFacts·_apply_tracked_event 둘 다 그 모듈로 옮겼기 때문이다. 나머지(아래
  # previous_task_boundary_ms·compute_session_view·summarize_agent_runs 대상)는 표시 판정
  # 쪽이라 hub_session.py 에 그대로 남는다.
  if ! grep -qF 'last_prompt_at_ms: int | None = None' "$hub_session_facts_file"; then
    note_failure "T25-222: hub_session_facts.py 의 SessionFacts 에 last_prompt_at_ms 필드가 없음(결정 RL1 위반)"
  fi
  if ! grep -qF 'last_prompt_at_ms = event.received_at_ms' "$hub_session_facts_file"; then
    note_failure "T25-222: hub_session_facts.py 의 _apply_tracked_event() 가 last_prompt_at_ms 를 채우지 않음(결정 RL1 위반)"
  fi
  if ! grep -qF 'task_started_at_ms: int | None = None' "$REPO_ROOT/hub/bin/hub_parse.py"; then
    note_failure "T25-222: hub_parse.py 의 Tier1Snapshot 에 task_started_at_ms 필드가 없음(결정 RL8 위반)"
  fi
  if ! grep -qF 'def previous_task_boundary_ms(' "$hub_session_file"; then
    note_failure "T25-222: hub_session.py 에 previous_task_boundary_ms() 가 없음(결정 RL8 위반)"
  fi
  local compute_session_view_body_222
  compute_session_view_body_222=$(awk '/^def compute_session_view\(/{flag=1} /^def summarize_agent_runs\(/{exit} flag{print}' "$hub_session_file")
  if [[ -z "$compute_session_view_body_222" ]]; then
    note_failure "T25-222: compute_session_view~summarize_agent_runs 사이 본문 추출 실패 — 앵커가 깨졌다"
  else
    if ! grep -qF 'previous_task_boundary_ms(' <<< "$compute_session_view_body_222"; then
      note_failure "T25-222: compute_session_view() 본문이 previous_task_boundary_ms() 를 호출하지 않음(결정 RL8 위반)"
    fi
    if grep -qF 'tier1.file_mtime_ms if' <<< "$compute_session_view_body_222"; then
      note_failure "T25-222: compute_session_view() 에 tier1.file_mtime_ms if 가 남아 있음(결정 RL2 위반 — FT 파생 경계가 되살아났다)"
    fi
    if ! grep -qF 'is_session_tier1_from_finished_task(' <<< "$compute_session_view_body_222"; then
      note_failure "T25-222: compute_session_view() 가 is_session_tier1_from_finished_task() 를 더 이상 호출하지 않음(결정 RL5 위반 — 클릭 게이트·CD1 승격이 무너진다)"
    fi
  fi
  local previous_task_boundary_ms_body_222
  previous_task_boundary_ms_body_222=$(awk '/^def previous_task_boundary_ms\(/{flag=1} /^def compute_session_view\(/{exit} flag{print}' "$hub_session_file")
  if [[ -z "$previous_task_boundary_ms_body_222" ]]; then
    note_failure "T25-222: previous_task_boundary_ms() 범위 추출 실패 — 앵커가 깨졌다"
  else
    if ! grep -qF 'if tier1 is None or tier1.task_started_at_ms is None:' <<< "$previous_task_boundary_ms_body_222"; then
      note_failure "T25-222: previous_task_boundary_ms() 에 작업 시작 미상 갈래(RL8-(c)/(d))가 없음"
    fi
    if ! grep -qF 'if not is_dashboard_enabled:' <<< "$previous_task_boundary_ms_body_222"; then
      note_failure "T25-222: previous_task_boundary_ms() 에 is_dashboard_enabled 갈래가 없음(결정 RL10 위반)"
    fi
    if ! grep -qF 'if tier1.percent >= TIER1_FINISHED_PERCENT:' <<< "$previous_task_boundary_ms_body_222"; then
      note_failure "T25-222: previous_task_boundary_ms() 에 끝난 작업 갈래(RL8-(b))가 없음"
    fi
    if ! grep -qF 'return max(tier1.task_started_at_ms, last_prompt_at_ms)' <<< "$previous_task_boundary_ms_body_222"; then
      note_failure "T25-222: previous_task_boundary_ms() 에 max(작업 시작, 마지막 프롬프트) 갈래(RL8-(b))가 없음"
    fi
  fi
  local summarize_agent_runs_body_222
  summarize_agent_runs_body_222=$(awk '/^def summarize_agent_runs\(/{flag=1} flag{print}' "$hub_session_file")
  if ! grep -qF 'and not is_running' <<< "$summarize_agent_runs_body_222"; then
    note_failure "T25-222: summarize_agent_runs() 가 and not is_running 을 경유하지 않음(결정 RL3 위반 — 실행 중인 실행이 다시 숨을 수 있다)"
  fi
  # ⑨ 역방향(dashboard-into-hub.md M2 HD8 재조준) — 네 순수·I/O 모듈은 M2 재작성으로
  # init-values 리터럴을 잃는다. 기록기(hub_dashboard_log.py)는 리텐션 패턴으로 그 문자열을
  # 계속 갖고(§10.5), hub/README.md 는 구세대 산출물로 계속 언급하므로(§7.2.1) 둘 다
  # 이 대상에서 뺀다.
  local init_values_leftover_file
  for init_values_leftover_file in \
      "$hub_project_file" "$hub_collect_file" \
      "$REPO_ROOT/hub/bin/hub_parse.py" "$REPO_ROOT/hub/bin/hub_dashboard_render.py"; do
    if grep -qF 'init-values' "$init_values_leftover_file"; then
      note_failure "T25-222: $init_values_leftover_file 에 init-values 리터럴이 남아 있음(HD8 위반)"
    fi
  done
  local read_session_dashboard_snapshots_body_222
  read_session_dashboard_snapshots_body_222=$(awk '/^def read_session_dashboard_snapshots\(/{flag=1} /^def read_dashboard_enabled\(/{exit} flag{print}' "$hub_collect_file")
  if [[ -z "$read_session_dashboard_snapshots_body_222" ]]; then
    note_failure "T25-222: read_session_dashboard_snapshots() 범위 추출 실패 — 앵커가 깨졌다"
  elif [[ "$(grep -oF 'iterdir()' <<< "$read_session_dashboard_snapshots_body_222" | wc -l | tr -d ' ')" != "1" ]]; then
    note_failure "T25-222: read_session_dashboard_snapshots() 안의 iterdir() 호출이 1건이 아님(RL8 수집 비용 계약 위반 — 작업 시작 시각을 기록 파일 밖의 디렉터리 조회로 얻으면 안 된다)"
  fi
  # 재조준(docs/prps/dashboard-into-hub.md HD1·HD2·§17-2 안 A): role-separation.md 는 더 이상
  # dashboard_enabled 를 언급하지 않는다 — 그 스위치 서술은 hub/rules/dashboard-recording.md
  # 로 옮겨갔다(허브가 없으면 role-separation.md 에 포인터도 남기지 않는다, 승인 항목 2).
  local doc_file_222
  for doc_file_222 in "$dashboard_command_file" "$REPO_ROOT/hub/rules/dashboard-recording.md"; do
    if ! grep -qF 'dashboard_enabled' "$doc_file_222"; then
      note_failure "T25-222: $doc_file_222 에 dashboard_enabled 리터럴이 없음(RL10 스위치 이름이 정본과 어긋남)"
    fi
    if ! grep -qF '.claude/settings.local.json' "$doc_file_222"; then
      note_failure "T25-222: $doc_file_222 에 .claude/settings.local.json 리터럴이 없음(RL10 스위치 경로가 정본과 어긋남)"
    fi
  done
  if ! grep -qF 'dashboard_enabled' "$hub_collect_file"; then
    note_failure "T25-222: hub_collect.py 에 dashboard_enabled 리터럴이 없음(RL10 위반)"
  fi
  if ! grep -qF '.claude/settings.local.json' "$hub_collect_file"; then
    note_failure "T25-222: hub_collect.py 에 .claude/settings.local.json 리터럴이 없음(RL10 위반)"
  fi
  local read_dashboard_enabled_body_222
  read_dashboard_enabled_body_222=$(awk '/^def read_dashboard_enabled\(/{flag=1} /^def _read_tier1_for_root\(/{exit} flag{print}' "$hub_collect_file")
  if [[ -z "$read_dashboard_enabled_body_222" ]]; then
    note_failure "T25-222: read_dashboard_enabled() 범위 추출 실패 — 앵커가 깨졌다"
  else
    if ! grep -qF 'return True' <<< "$read_dashboard_enabled_body_222"; then
      note_failure "T25-222: read_dashboard_enabled() 에 return True 가 없음(RL10 페일 방향 계약 위반)"
    fi
    local except_block_222
    except_block_222=$(awk '/except \(OSError, json\.JSONDecodeError\):/{flag=1; next} flag{print; exit}' <<< "$read_dashboard_enabled_body_222")
    if grep -qF 'return False' <<< "$except_block_222"; then
      note_failure "T25-222: read_dashboard_enabled() 의 except 분기가 return False 를 씀(RL10 페일 방향 위반 — 읽기 실패는 켜짐으로 넘어져야 한다)"
    fi
  fi
  if ! grep -qF '작업이 시작된 뒤에 시작된 실행만 남는다' "$hub_readme_file"; then
    note_failure "T25-222: hub/README.md 에 작업이 시작된 뒤에 시작된 실행만 남는다는 서술이 없음"
  fi
  if ! grep -qF '대시보드를 끈 프로젝트' "$hub_readme_file"; then
    note_failure "T25-222: hub/README.md 에 대시보드를 끈 프로젝트의 동작 서술이 없음(RL10)"
  fi

  # T25-223(역전환 — 카드 상세보기 정리 M2·M3, 결정 MX4·MX1·MX13, docs/prps/hub-session-modal-cleanup.md
  # §10.1; 원래는 주인 세션이 화면에 없는 카드에 경고 칩과 톤다운을 붙이는 정방향 가드였다, 결정 CG1~CG3·
  # CG8~CG12): 카드·카드 상세보기 머리의 프로젝트 단위 진행률이 걷히며(M2) 그 경고(「주인 세션 없음」 칩과
  # 톤다운 스코프 속성)의 라벨·툴팁 상수, 라벨 판정 함수, 스코프 속성 함수와 속성이 템플릿 어디에도
  # 되살아나지 않고, 머리를 누를 수 있는지 가르던 게이트가 사라지며(M3) 그 게이트만 쓰던 주인 세션 판정
  # 함수도 되살아나지 않는다(주석 포함, T25-178 선례 — 걷은 식별자를 템플릿 주석에 다시 적지 않는다).
  # README 에도 그 경고 서술이 없다.
  # 일곱 줄로 나눠 쓴다(반복문 대신) — 반복문 메시지는 변수를 보간해 소스에 리터럴로 나타나지 않아 원장
  # 판별자 자격(T37-13)을 못 채운다(T25-240 관례와 같은 이유).
  if grep -qF -- 'TIER1_ORPHAN_LABEL' "$hub_template_file"; then
    note_failure "T25-223: hub_template.html 에 걷은 주인 세션 없음 라벨 상수가 되살아남(결정 MX4 위반 — 주석에도 다시 적지 않는다)"
  fi
  if grep -qF -- 'TIER1_ORPHAN_TOOLTIP' "$hub_template_file"; then
    note_failure "T25-223: hub_template.html 에 걷은 주인 세션 없음 툴팁 상수가 되살아남(결정 MX4 위반 — 주석에도 다시 적지 않는다)"
  fi
  if grep -qF -- 'projectTier1Label' "$hub_template_file"; then
    note_failure "T25-223: hub_template.html 에 걷은 진행률 경고 라벨 판정 함수가 되살아남(결정 MX4 위반 — 주석에도 다시 적지 않는다)"
  fi
  if grep -qF -- 'tier1ScopeAttributes' "$hub_template_file"; then
    note_failure "T25-223: hub_template.html 에 걷은 톤다운 스코프 속성 함수가 되살아남(결정 MX4 위반 — 주석에도 다시 적지 않는다)"
  fi
  if grep -qF -- 'data-tier1-orphan' "$hub_template_file"; then
    note_failure "T25-223: hub_template.html 에 걷은 주인 세션 없음 스코프 속성이 되살아남(결정 MX4 위반 — 주석에도 다시 적지 않는다)"
  fi
  if grep -qF -- 'isTier1OwnerVisible' "$hub_template_file"; then
    note_failure "T25-223: hub_template.html 에 걷은 주인 세션 판정 함수가 되살아남(결정 MX1 위반 — 그 판정을 쓰던 머리 게이트가 사라졌다, 주석에도 다시 적지 않는다)"
  fi
  if grep -qF -- '주인 세션 없음' "$hub_readme_file"; then
    note_failure "T25-223: hub/README.md 에 걷은 주인 세션 없음 경고 서술이 남아 있음(결정 MX4 위반 — 카드에는 그 칩이 없다)"
  fi

  # T25-224(신설, 결정 SL7 — 함정 PS7 회피, docs/prps/hub-subagent-liveness-signal.md): 서브
  # 에이전트 생존 신호 읽기 함수가 존재하고, 그 시그니처와 _read_session_annotations 의
  # 호출 양쪽에 record_prompt_excerpt 가 없다(역방향) — mtime 은 프롬프트 발췌가 아니므로
  # 그 게이트 안에 들어가는 실수는 설정을 끈 환경에서만 발현돼 리뷰로만 잡히고 테스트로는
  # 안 잡힌다.
  if ! grep -qF 'def read_unfinished_subagent_activity(' "$hub_subagent_read_file"; then
    record_failure "$test_name" "T25-224: hub_subagent_read.py 에 def read_unfinished_subagent_activity( 이 없음"
    return 1
  fi
  local read_unfinished_activity_body_224 read_session_annotations_body_224
  read_unfinished_activity_body_224=$(awk '/^def read_unfinished_subagent_activity\(/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_subagent_read_file")
  read_session_annotations_body_224=$(awk '/^def _read_session_annotations\(/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_collect_file")
  if [[ -z "$read_unfinished_activity_body_224" || -z "$read_session_annotations_body_224" ]]; then
    record_failure "$test_name" "T25-224: 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if grep -qF 'record_prompt_excerpt' <<< "$read_unfinished_activity_body_224"; then
    record_failure "$test_name" "T25-224 역방향: read_unfinished_subagent_activity 가 record_prompt_excerpt 로 게이팅됨(함정 PS7, SL7 위반)"
    return 1
  fi
  local unfinished_activity_call_224
  unfinished_activity_call_224=$(grep -F 'read_unfinished_subagent_activity(' <<< "$read_session_annotations_body_224")
  if [[ -z "$unfinished_activity_call_224" ]]; then
    record_failure "$test_name" "T25-224: _read_session_annotations 본문에서 read_unfinished_subagent_activity( 호출을 찾지 못함"
    return 1
  fi
  if grep -qF 'record_prompt_excerpt' <<< "$unfinished_activity_call_224"; then
    record_failure "$test_name" "T25-224 역방향: _read_session_annotations 의 read_unfinished_subagent_activity 호출에 record_prompt_excerpt 가 넘어감(함정 PS7 위반)"
    return 1
  fi

  # T25-225(신설, 결정 SL2·SL5 — docs/prps/hub-subagent-liveness-signal.md): 상태·칩 단일
  # 판정자(T25-92·T25-207 승계)와 D2 방어(값이 뷰에 새지 않음, G9)를 SL 설계 판에서 함께
  # 문다. _compute_base_state·summarize_agent_runs 두 본문의 is_running_subagent( 호출
  # 자리에 subagent_activity_by_agent_id 가 넘어가는지를, 그 호출이 있는 줄 자체에서
  # 본다(정상화 대입문 등 무관한 줄의 우연한 언급에 속지 않는다).
  local base_state_body_225 summarize_agent_runs_body_225 session_view_body_225
  base_state_body_225=$(awk '/^def _compute_base_state\(/{flag=1; next} flag && /^def compute_session_view\(/{exit} flag{print}' "$hub_session_file")
  summarize_agent_runs_body_225=$(awk '/^def summarize_agent_runs\(/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_session_file")
  session_view_body_225=$(awk '/^class SessionView:/{flag=1; next} flag && /^# ----/{exit} flag{print}' "$hub_session_file")
  if [[ -z "$base_state_body_225" || -z "$summarize_agent_runs_body_225" || -z "$session_view_body_225" ]]; then
    record_failure "$test_name" "T25-225: 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  local base_state_is_running_call_225 summarize_is_running_call_225
  base_state_is_running_call_225=$(grep -F 'is_running_subagent(' <<< "$base_state_body_225")
  summarize_is_running_call_225=$(grep -F 'is_running_subagent(' <<< "$summarize_agent_runs_body_225")
  if [[ -z "$base_state_is_running_call_225" ]]; then
    note_failure "T25-225: _compute_base_state 의 is_running_subagent 호출 자체가 사라짐(GOTCHA 4, T25-92 영역 회귀)"
  elif ! grep -qF 'subagent_activity_by_agent_id' <<< "$base_state_is_running_call_225"; then
    note_failure "T25-225: _compute_base_state 의 is_running_subagent 호출에 subagent_activity_by_agent_id 를 넘기지 않음(상태·칩 불일치 위험, G6 위반)"
  fi
  if [[ -z "$summarize_is_running_call_225" ]]; then
    note_failure "T25-225: summarize_agent_runs 의 is_running_subagent 호출 자체가 사라짐(GOTCHA 4, T25-207 영역 회귀)"
  elif ! grep -qF 'subagent_activity_by_agent_id' <<< "$summarize_is_running_call_225"; then
    note_failure "T25-225: summarize_agent_runs 의 is_running_subagent 호출에 subagent_activity_by_agent_id 를 넘기지 않음(상태·칩 불일치 위험, G6 위반)"
  fi
  if grep -qF 'activity' <<< "$session_view_body_225"; then
    record_failure "$test_name" "T25-225 역방향: SessionView 에 activity 를 포함하는 필드가 생김(D2 방어 위반, G9 — 매 수집마다 snapshot_content_key 가 바뀐다)"
    return 1
  fi

  # T25-226(신설, 결정 SL4·LS9 — 이 설계에서 가장 값진 가드, docs/prps/
  # hub-subagent-liveness-signal.md): stale 판정이 last_known_activity_at_ms( 를 경유하고,
  # 그 함수 본문에 살아있는 세션 명부 참조가 없다 — 명부 오판의 유일한 독립 상한(결정
  # LS9)이 조용히 재발하는 것을 막는다(이 결함의 출발점 자체가 이 재발 형태였다).
  local compute_session_view_body_226 last_known_activity_body_226
  compute_session_view_body_226=$(awk '/^def compute_session_view\(/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_session_file")
  last_known_activity_body_226=$(awk '/^def last_known_activity_at_ms\(/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_session_file")
  if [[ -z "$compute_session_view_body_226" || -z "$last_known_activity_body_226" ]]; then
    record_failure "$test_name" "T25-226: 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'last_known_activity_at_ms(' <<< "$compute_session_view_body_226"; then
    record_failure "$test_name" "T25-226 역방향: compute_session_view 본문에 last_known_activity_at_ms( 호출이 없음(G5 위반 — stale 판정이 옛 방식으로 되돌아갔다)"
    return 1
  fi
  if grep -qF 'is_stale = base_state != "done" and (now_ms - facts.last_event_at_ms)' <<< "$compute_session_view_body_226"; then
    record_failure "$test_name" "T25-226 역방향: is_stale 이 옛 facts.last_event_at_ms 직접 참조로 되돌아감(이 결함의 출발점이 재발)"
    return 1
  fi
  # T25-226 서브체크(재검수 2회차 HIGH-2): 명부 정보를 bool 하나로 접어
  # last_known_activity_at_ms 의 세 번째 인자로 몰래 넘기면, 그 함수 본문에는 'roster'
  # 문자열이 등장하지 않아 바로 아래 검사를 우회한다 — 호출 자체가 정확히 두 인자
  # (facts, subagent_activity_by_agent_id)로만 이뤄지는지 고정해 그 우회를 막는다.
  if ! grep -qF 'last_known_activity_at_ms(facts, subagent_activity_by_agent_id)' <<< "$compute_session_view_body_226"; then
    record_failure "$test_name" "T25-226 역방향: last_known_activity_at_ms 호출의 인자가 facts, subagent_activity_by_agent_id 두 개가 아님(명부를 접어 넘기는 인자가 추가돼 결정 LS9 의 독립 상한을 우회할 수 있음)"
    return 1
  fi
  # T25-226 서브체크(재검수 2회차 HIGH-2): 대소문자 구분 고정 문자열은 로스터 계열
  # 타입명(RosterState 등 대문자로 시작하는 식별자)을 놓친다 — 대소문자를 무시한다.
  if grep -qFi 'roster' <<< "$last_known_activity_body_226"; then
    record_failure "$test_name" "T25-226 역방향: last_known_activity_at_ms 본문에 명부 참조(roster)가 등장함(결정 LS9 의 독립 상한 위반)"
    return 1
  fi

  # T25-227(신설, §9 기각 G 재확인 — docs/prps/hub-subagent-liveness-signal.md): 상수를
  # 올리는 우회를 막고, 문서 두 곳에 개정 토큰이 있다(GOTCHA 10 관례). 상수 리터럴 자체를
  # 여기서 다시 묻지 않는 이유(T37-15 그룹 절단 수정, 실측 확인) — T25-91 이 이미 그
  # 리터럴을 존재·순서 두 경로로 물고, 그 순서 검사(GOTCHA 1)가 record_failure + return 1
  # 로 그룹을 끊는다. 그 리터럴을 겨냥한 변조는 이 자리에 도달하지도 못하므로(T25-1 이
  # T25-149 를 가리던 것과 같은 그룹 절단 형태, tests/mutations.tsv 한계 절 참고), 중복
  # 검사를 남기지 않고 뺐다.
  local readme_sl_token
  for readme_sl_token in '마지막 기록 이후' '도는 중인 서브에이전트가 기록을 남기는 동안에는 소식 없음으로 뒤집히지 않는다'; do
    if ! grep -qF -- "$readme_sl_token" "$hub_readme_file"; then
      note_failure "T25-227: hub/README.md 에 '$readme_sl_token' 토큰이 없음"
    fi
  done
  if ! grep -qF '결정 SL1~SL9' "$hub_dashboard_prp_file"; then
    note_failure "T25-227: docs/prps/hub-dashboard.md 에 결정 SL1~SL9 개정 토큰이 없음"
  fi

  # T25-241(신설, 정 — 결정 RI-G1, docs/prps/hub-rate-limit-interruption.md §8.3): 훅
  # 이벤트가 7개로 늘었다는 사실이 소스·문서 세 곳(HOOK_EVENTS·README·commands/hub.md)에
  # 함께 반영돼 있는지 본다. 착수 시점 main 최대 T25 번호(228) 및 hub-session-modal
  # 워크트리의 선점 구간(T25-228~239)과 겹치지 않도록 T25-241 부터 배정한다(§10).
  if ! grep -qF '"StopFailure"' "$hub_settings_file"; then
    note_failure "T25-241: hub_settings.py 의 HOOK_EVENTS 에 \"StopFailure\" 가 없음"
  fi
  if ! grep -qF '전역 훅 7' "$hub_readme_file"; then
    note_failure "T25-241: hub/README.md 에 '전역 훅 7' 고지가 없음"
  fi
  if ! grep -qF '전역 훅 7개' "$hub_command_file"; then
    note_failure "T25-241: commands/hub.md 에 '전역 훅 7개' 고지가 없음"
  fi
  if ! grep -qF 'StopFailure' "$hub_command_file"; then
    note_failure "T25-241: commands/hub.md 에 StopFailure 표기가 없음"
  fi

  # T25-242(신설, 역(프라이버시) — 결정 RI-G2, docs/prps/hub-rate-limit-interruption.md §8.3):
  # hub_hook.py 는 error_details·last_assistant_message 문자열 리터럴을 갖지 않는다(StopFailure
  # 입력의 두 자유 텍스트 필드 — RI7). StopFailure 투영은 반드시 normalize_error_kind( 를
  # 경유해야 한다 — 원문 오류 문구를 그대로 옮기는 우회(fields["er"] = payload.get("error"))를
  # 막는다. 검수 1회차 LOW — 파일 어디든 normalize_error_kind( 가 있으면 통과하던 옛 검사는
  # 그 호출을 주석으로만 남기고 대입 자체는 우회하는 변조를 놓친다. fields["er"] 대입 줄
  # **그 줄 자체**에 normalize_error_kind( 가 있는지로 좁힌다. 검수 2회차 LOW — 고정 문자열
  # 검색은 주석 줄에도 걸려, 원래 대입 줄을 주석으로 남기고 그 아래에 원문 대입을 쓰는 변조를
  # 놓친다. 줄 머리(공백만 허용)부터 대입이 시작되는 줄만 인정한다.
  local forbidden_free_text_key_242
  for forbidden_free_text_key_242 in '"error_details"' '"last_assistant_message"'; do
    if grep -qF -- "$forbidden_free_text_key_242" "$hub_hook_file"; then
      note_failure "T25-242: hub_hook.py 에 $forbidden_free_text_key_242 문자열 리터럴이 있음(RI7 프라이버시 위반)"
    fi
  done
  if ! grep -qE '^[[:space:]]*fields\["er"\] = hub_transcript\.normalize_error_kind\(' "$hub_hook_file"; then
    note_failure "T25-242: hub_hook.py 의 fields[\"er\"] 대입 줄이 normalize_error_kind( 를 경유하지 않음"
  fi

  # T25-243(신설, 정 — 결정 RI-G3, docs/prps/hub-rate-limit-interruption.md §8.3): 템플릿
  # STATE_LABEL·STATE_GLYPH 에 interrupted 키가 있고, .badge.state-interrupted{ 규칙이
  # 존재하며 그 본문에 animation·box-shadow 가 없다(T25-190 의 halo 금지 정신과 같은 검사 —
  # 새 색 토큰 0·애니메이션 0 이 이 배지의 설계 결정이다).
  if ! grep -qE 'STATE_LABEL = \{[^}]*interrupted:' "$hub_template_file"; then
    note_failure "T25-243: hub_template.html 의 STATE_LABEL 에 interrupted: 키가 없음"
  fi
  if ! grep -qE 'STATE_GLYPH = \{[^}]*interrupted:' "$hub_template_file"; then
    note_failure "T25-243: hub_template.html 의 STATE_GLYPH 에 interrupted: 키가 없음"
  fi
  local badge_interrupted_rule_243
  badge_interrupted_rule_243=$(grep -oE '[^{}]*\.badge\.state-interrupted\{[^}]*\}' "$hub_template_file")
  if [[ -z "$badge_interrupted_rule_243" ]]; then
    note_failure "T25-243: hub_template.html 에 .badge.state-interrupted{ 규칙이 없음"
  elif grep -qE 'animation|box-shadow' <<< "$badge_interrupted_rule_243"; then
    note_failure "T25-243: .badge.state-interrupted 규칙에 animation/box-shadow 가 있음(halo 금지 위반) — $badge_interrupted_rule_243"
  fi

  # T25-244(신설, 역(프라이버시) — 결정 RI-G4, docs/prps/hub-rate-limit-interruption.md §8.3):
  # _turn_failure_from_line 본문은 message.content(대화 본문)에 닿지 않는다 — 함수 본문에
  # "content"·"message" 문자열 리터럴(따옴표 포함 — payload.get("message") 형태)이 없어야
  # 한다. 프라이버시 고지 산문(이 함수 자신의 docstring)의 "message.content" 라는 평문
  # 서술은 따옴표가 없어 이 검사에 걸리지 않는다. 검수 1회차 LOW — 큰따옴표만 잡던 옛
  # 정규식은 payload.get('message') 처럼 홑따옴표로 우회된다 — 두 따옴표 모두 잡는다.
  local turn_failure_from_line_body_244
  turn_failure_from_line_body_244=$(awk '/^def _turn_failure_from_line\(/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_transcript_file")
  if [[ -z "$turn_failure_from_line_body_244" ]]; then
    record_failure "$test_name" "T25-244: _turn_failure_from_line 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if grep -qE "['\"]content['\"]|['\"]message['\"]" <<< "$turn_failure_from_line_body_244"; then
    note_failure "T25-244: _turn_failure_from_line 본문에 content/message 리터럴 접근이 있음(RI7 프라이버시 위반 — message.content 를 읽으면 안 된다)"
  fi

  # T25-229(신설, M1, 결정 PU1·PU6 — docs/prps/hub-session-modal-and-partial-update.md):
  # render() 가 #dzh-app 을 부분 갱신(reconcileChildren)으로 고치는지, 통째 교체
  # (innerHTML·insertAdjacentHTML)로 되돌아가지 않았는지 확인한다.
  local render_fn_body_229
  render_fn_body_229=$(sed -n '/function render(){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$render_fn_body_229" ]]; then
    record_failure "$test_name" "T25-229: render() 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'reconcileChildren(app,' <<< "$render_fn_body_229"; then
    record_failure "$test_name" "T25-229: render() 본문에 reconcileChildren(app, 호출이 없음(통째 교체로 회귀)"
    return 1
  fi
  if grep -qF 'app.innerHTML' "$hub_template_file"; then
    record_failure "$test_name" "T25-229 역방향: hub_template.html 에 app.innerHTML 대입이 남아 있음(통째 교체로 회귀)"
    return 1
  fi
  if grep -qF 'insertAdjacentHTML' "$hub_template_file"; then
    record_failure "$test_name" "T25-229 역방향: hub_template.html 에 insertAdjacentHTML 이 남아 있음(2단계 조립으로 회귀)"
    return 1
  fi

  # T25-230(신설, M1, 결정 PU2): 렌더 키 속성 리터럴은 상수 선언 한 곳에만 살고, 카드·세션
  # 줄·실행 줄 세 렌더 함수는 그 상수(RENDER_KEY_ATTRIBUTE)를 통해서만 키를 단다 — 세션
  # <li> 가 키 없이 나가 정렬이 바뀔 때 줄이 변신하는 회귀(§2.2)를 막는다.
  local render_key_literal_count_230
  render_key_literal_count_230=$(grep -cF "'data-render-key'" "$hub_template_file")
  if [[ "$render_key_literal_count_230" -ne 1 ]]; then
    record_failure "$test_name" "T25-230: 'data-render-key' 리터럴이 정확히 1건이어야 하는데 ${render_key_literal_count_230}건 발견됨"
    return 1
  fi
  local render_project_body_230 render_session_body_230 render_agent_run_row_body_230
  render_project_body_230=$(sed -n '/function renderProject(project){/,/^  }$/p' "$hub_template_file")
  render_session_body_230=$(sed -n '/function renderSession(project, session){/,/^  }$/p' "$hub_template_file")
  render_agent_run_row_body_230=$(sed -n '/function renderAgentRunRow(run, nowMs){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$render_project_body_230" || -z "$render_session_body_230" || -z "$render_agent_run_row_body_230" ]]; then
    record_failure "$test_name" "T25-230: 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'RENDER_KEY_ATTRIBUTE' <<< "$render_project_body_230"; then
    record_failure "$test_name" "T25-230: renderProject 본문에 RENDER_KEY_ATTRIBUTE 참조가 없음(카드 키 누락)"
    return 1
  fi
  if ! grep -qF 'RENDER_KEY_ATTRIBUTE' <<< "$render_session_body_230"; then
    record_failure "$test_name" "T25-230: renderSession 본문에 RENDER_KEY_ATTRIBUTE 참조가 없음(세션 줄 키 누락)"
    return 1
  fi
  if ! grep -qF 'RENDER_KEY_ATTRIBUTE' <<< "$render_agent_run_row_body_230"; then
    record_failure "$test_name" "T25-230: renderAgentRunRow 본문에 RENDER_KEY_ATTRIBUTE 참조가 없음(실행 줄 키 누락)"
    return 1
  fi

  # T25-231(신설, M1, 결정 PU3·PU4): aria-describedby 보존 예외가 선언에 살아 있고
  # syncAttributes 가 그 상수를 실제로 보는지, patchNode 가 텍스트를 nodeValue 대입으로만
  # 고치고 replaceChild 로 바꿔치기하지 않는지 확인한다 — 지우면 뜬 툴팁의 보조기술 연결이
  # 끊기거나(전자) 텍스트만 바뀌어도 구조 변화로 오인돼 툴팁이 꺼진다(후자, PU5 와 상충).
  local preserved_attrs_decl_231 sync_attrs_body_231 patch_node_body_231
  preserved_attrs_decl_231=$(grep -F 'var RECONCILE_PRESERVED_ATTRIBUTES' "$hub_template_file")
  if [[ -z "$preserved_attrs_decl_231" ]] || ! grep -qF "'aria-describedby'" <<< "$preserved_attrs_decl_231"; then
    record_failure "$test_name" "T25-231: RECONCILE_PRESERVED_ATTRIBUTES 선언에 aria-describedby 가 없음"
    return 1
  fi
  sync_attrs_body_231=$(sed -n '/function syncAttributes(liveElement, nextElement){/,/^  }$/p' "$hub_template_file")
  patch_node_body_231=$(sed -n '/function patchNode(liveNode, nextNode){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$sync_attrs_body_231" || -z "$patch_node_body_231" ]]; then
    record_failure "$test_name" "T25-231: 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'RECONCILE_PRESERVED_ATTRIBUTES' <<< "$sync_attrs_body_231"; then
    record_failure "$test_name" "T25-231: syncAttributes 본문이 RECONCILE_PRESERVED_ATTRIBUTES 를 보지 않음(보존 예외 삭제)"
    return 1
  fi
  if ! grep -qF 'nodeValue' <<< "$patch_node_body_231"; then
    record_failure "$test_name" "T25-231: patchNode 본문에 nodeValue 대입이 없음(텍스트 갱신 경로 소실)"
    return 1
  fi
  if grep -qF 'replaceChild' <<< "$patch_node_body_231"; then
    record_failure "$test_name" "T25-231 역방향: patchNode 본문에 replaceChild 가 있음(텍스트 교체가 구조 변화를 일으켜 PU5 옵저버가 오발화)"
    return 1
  fi

  # T25-232(신설, M1, 결정 PU5): 툴팁 해제 옵저버가 .wrap 을 subtree 까지 관찰하는지 확인한다
  # — #dzh-app 직계만 보던 예전 관찰로 돌아가면 카드 안 깊은 곳에서 트리거가 사라져도
  # 옵저버가 발화하지 않아 고아 툴팁이 남는다(결정 T6 재발).
  local wrap_observer_call_232
  wrap_observer_call_232=$(grep -F 'tooltipDismissObserver.observe(wrapElForTooltipObserver' "$hub_template_file")
  if [[ -z "$wrap_observer_call_232" ]]; then
    record_failure "$test_name" "T25-232: tooltipDismissObserver.observe(wrapElForTooltipObserver 호출을 찾지 못함 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'subtree: true' <<< "$wrap_observer_call_232"; then
    record_failure "$test_name" "T25-232: .wrap 관찰 호출에 subtree: true 가 없음(직계 관찰로 회귀 — 고아 툴팁 재발)"
    return 1
  fi

  # ── M2(카드 상세보기, docs/prps/hub-session-modal-and-partial-update.md 결정 SC1~SC17) 신규
  # 가드 — T25-233~240 ──

  # T25-233(전환 — 카드 상세보기 정리 M3, 결정 MX1; 원래는 결정 SC4 「패널 속성의 유일한 담체가 모달 루트로
  # 옮겨 갔다」의 정방향 가드였다): 이제 카드도 모달 머리도 패널 속성을 갖지 않는다 — 프로젝트의 대시보드를
  # 여는 요소는 세션 줄과 모달 세션 카드(sessionRowAttributes)뿐이다. renderProject() 본문에는 그 속성도
  # 그 담체를 만들던 함수 호출도 남아 있으면 안 되고(주석 포함 — 카드는 모달을 여는 표지만 단다, 그 표지는
  # T25-256), renderSessionModalRoot() 본문에도 패널 속성과 누르는 요소(<button)가 없다. 머리 제목은
  # 눌리지 않는 span 이며 그 id 상수는 남는다(다이얼로그의 aria-labelledby 대상 — D15).
  local render_project_body_233
  render_project_body_233=$(sed -n '/function renderProject(project){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$render_project_body_233" ]]; then
    record_failure "$test_name" "T25-233: renderProject() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  local forbidden_card_panel_token_233
  for forbidden_card_panel_token_233 in 'projectPanelAttributes(' 'data-dashboard-key' 'data-panel-empty-reason'; do
    if grep -qF -- "$forbidden_card_panel_token_233" <<< "$render_project_body_233"; then
      record_failure "$test_name" "T25-233: renderProject() 본문에 $forbidden_card_panel_token_233 이 남아 있음(결정 SC4 위반 — 카드가 다시 패널을 여는 회귀)"
      return 1
    fi
  done
  local render_session_modal_root_body_233
  render_session_modal_root_body_233=$(sed -n '/function renderSessionModalRoot(project, visibleSessions){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$render_session_modal_root_body_233" ]]; then
    record_failure "$test_name" "T25-233: renderSessionModalRoot() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  # 여섯 줄로 나눠 쓴다(반복문 대신) — 반복문 메시지는 변수를 보간해 소스에 리터럴로 나타나지 않아 원장
  # 판별자 자격(T37-13)을 못 채운다(T25-240 관례와 같은 이유).
  if grep -qF 'projectPanelAttributes(' <<< "$render_session_modal_root_body_233"; then
    note_failure "T25-233: renderSessionModalRoot() 본문에 projectPanelAttributes( 호출이 되살아남(결정 MX1 위반 — 루트가 다시 패널을 연다)"
  fi
  if grep -qF 'data-project-path' <<< "$render_session_modal_root_body_233"; then
    note_failure "T25-233: renderSessionModalRoot() 본문에 data-project-path 가 있음(결정 MX1 위반 — 루트는 패널 타깃이 아니다)"
  fi
  if grep -qF 'data-dashboard-key' <<< "$render_session_modal_root_body_233"; then
    note_failure "T25-233: renderSessionModalRoot() 본문에 data-dashboard-key 가 있음(결정 MX1 위반 — 루트는 패널 타깃이 아니다)"
  fi
  if grep -qF 'data-panel-empty-reason' <<< "$render_session_modal_root_body_233"; then
    note_failure "T25-233: renderSessionModalRoot() 본문에 data-panel-empty-reason 이 있음(결정 MX1 위반 — 루트는 패널 타깃이 아니다)"
  fi
  if grep -qF '<button' <<< "$render_session_modal_root_body_233"; then
    note_failure "T25-233: renderSessionModalRoot() 본문에 <button 이 있음(결정 MX1 위반 — 누를 곳이 없는 머리의 포커스 가능 버튼은 보조기술에 거짓말이다)"
  fi
  if ! grep -qF 'SESSION_MODAL_TITLE_ID' <<< "$render_session_modal_root_body_233"; then
    note_failure "T25-233: renderSessionModalRoot() 본문에 SESSION_MODAL_TITLE_ID 가 없음(다이얼로그의 aria-labelledby 대상이 끊긴다)"
  fi

  # T25-234(신설, M2, 결정 SC6·T25-160 확장): 모달 세션 카드는 카드 세션 줄과 글자 그대로
  # 같은 속성 계약(sessionRowAttributes)·같은 키(RENDER_KEY_ATTRIBUTE)·같은 본문
  # (renderSessionContent)을 쓴다. 모달 본문은 반드시 visibleSessionsOf() 를 경유해야
  # 한다(T25-160 계약을 모달에 확장) — .filter(shouldRenderSession) 을 직접 부르면 필터
  # 로직이 카드와 모달에서 갈라질 수 있다.
  local render_session_card_body_234
  render_session_card_body_234=$(sed -n '/function renderSessionCard(project, session){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$render_session_card_body_234" ]]; then
    record_failure "$test_name" "T25-234: renderSessionCard() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  local required_session_card_token_234
  for required_session_card_token_234 in 'sessionRowAttributes(' 'RENDER_KEY_ATTRIBUTE' 'renderSessionContent('; do
    if ! grep -qF -- "$required_session_card_token_234" <<< "$render_session_card_body_234"; then
      record_failure "$test_name" "T25-234: renderSessionCard() 본문에 $required_session_card_token_234 이 없음(결정 SC6 위반)"
      return 1
    fi
  done
  local session_modal_body_html_body_234
  session_modal_body_html_body_234=$(sed -n '/function sessionModalBodyHtml(project){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$session_modal_body_html_body_234" ]]; then
    record_failure "$test_name" "T25-234: sessionModalBodyHtml() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'visibleSessionsOf(' <<< "$session_modal_body_html_body_234"; then
    record_failure "$test_name" "T25-234: sessionModalBodyHtml() 이 visibleSessionsOf( 를 경유하지 않음(T25-160 계약 위반)"
    return 1
  fi
  if grep -qF '.filter(shouldRenderSession)' <<< "$session_modal_body_html_body_234"; then
    record_failure "$test_name" "T25-234: sessionModalBodyHtml() 에 .filter(shouldRenderSession) 직접 호출이 있음(공유 필터 우회 — 모달이 카드와 다른 세션 집합을 보일 수 있다)"
    return 1
  fi

  # T25-235(신설, M2, 결정 SC4, T25-66 관용구): 카드 상세보기를 여는 클릭 리스너는 반드시
  # 마지막 `if(!isServed){` 줄보다 앞에 등록돼야 한다 — 뒤로 가면 file:// 모드에서 모달이
  # 통째로 죽는다(GOTCHA).
  local open_modal_listener_line_235 is_served_gate_line_235
  open_modal_listener_line_235=$(grep -n "openSessionModal(card.getAttribute(" "$hub_template_file" | head -1 | cut -d: -f1)
  is_served_gate_line_235=$(grep -n 'if(!isServed){' "$hub_template_file" | tail -1 | cut -d: -f1)
  if [[ -z "$open_modal_listener_line_235" || -z "$is_served_gate_line_235" \
      || "$open_modal_listener_line_235" -ge "$is_served_gate_line_235" ]]; then
    record_failure "$test_name" "T25-235: 카드 상세보기 리스너가 if(!isServed){ 뒤에 등록됨(또는 찾지 못함) — file:// 모드에서 모달 소실"
    return 1
  fi

  # T25-236(신설, M2, 결정 SC8): ESC 순서는 등록 순서가 아니라 이벤트 단계로 정해진다 —
  # 패널이 실제로 닫았을 때만 preventDefault 하고(표준 "처리됨" 신호), 모달은 window
  # 버블 단계에서 event.defaultPrevented 만 본다(렌더 IIFE 가 패널의 변수·클래스를
  # 몰라도 되는 근거).
  local close_panel_call_line_236
  close_panel_call_line_236=$(grep -n 'closeDetailPanel();' "$hub_template_file" | head -1 | cut -d: -f1)
  if [[ -z "$close_panel_call_line_236" ]]; then
    record_failure "$test_name" "T25-236: closeDetailPanel(); 호출 줄을 찾지 못함 — 앵커가 깨졌다"
    return 1
  fi
  local next_line_after_close_panel_236
  next_line_after_close_panel_236=$(sed -n "$((close_panel_call_line_236 + 1))p" "$hub_template_file")
  if ! grep -qF 'event.preventDefault();' <<< "$next_line_after_close_panel_236"; then
    record_failure "$test_name" "T25-236: closeDetailPanel(); 다음 줄이 event.preventDefault(); 가 아님(결정 SC8 위반)"
    return 1
  fi
  if ! grep -qF "window.addEventListener('keydown'" "$hub_template_file"; then
    record_failure "$test_name" "T25-236: window.addEventListener('keydown' 리스너(모달 ESC)를 찾지 못함(결정 SC8 위반)"
    return 1
  fi
  local window_keydown_body_236
  window_keydown_body_236=$(sed -n "/window.addEventListener('keydown', function(event){/,/^  });$/p" "$hub_template_file")
  if [[ -z "$window_keydown_body_236" ]]; then
    record_failure "$test_name" "T25-236: window 키다운 리스너 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'event.defaultPrevented' <<< "$window_keydown_body_236"; then
    record_failure "$test_name" "T25-236: 모달 ESC 리스너가 event.defaultPrevented 를 보지 않음(결정 SC8 위반 — ESC 한 번에 패널·모달 동시 닫힘)"
    return 1
  fi

  # T25-237(신설, M2, 역, 결정 SC2 기각안 재확인): 네이티브 <dialog>+showModal()·popover 를
  # 도입하지 않는다 — 바깥 전부를 inert 로 만들어 패널까지 못 쓰게 되기 때문이다(확정 5
  # 위반). 검수 1회차 MEDIUM 개정(2026-09-24) — 예전엔 '<dialog '(트레일링 공백)로 속성을
  # 동반한 태그만 잡아, 속성 없는 `<dialog>` 가 새로 들어와도 이 줄이 통과했다. 지금은
  # '<dialog' 로 시작하는 줄을 전부 뽑고 SP1 근거 문단의 "<dialog> 를 쓰지 않는 이유"라는
  # 산문 인용 한 줄만(고정 문구 "를 쓰지 않는 이유"로 식별 — 그 문단은 M1 이전부터 있던
  # 정당한 설계 근거이고 지우지 않는다) 걸러내고 하나라도 남으면 실패한다. 산문 줄의
  # 존재를 전제하지 않으므로 산문이 나중에 지워져도 이 검사는 공허하게 통과·실패하지
  # 않는다. 파이프 끝의 `|| true` 는 산문만 있어 필터 뒤 0줄이 되는 정상 상태에서 grep 의
  # exit 1 이 set -e 로 스크립트를 통째로 죽이는 것을 막는다(실측 확인).
  # 세 줄로 나눠 쓴다(반복문 대신) — 반복문 메시지는 변수를 보간해 소스에 리터럴로
  # 나타나지 않아 원장 판별자 자격(T37-13)을 못 채운다.
  local dialog_tag_lines_237
  dialog_tag_lines_237=$(grep -F -- '<dialog' "$hub_template_file" | grep -vF -- '를 쓰지 않는 이유' || true)
  if [[ -n "$dialog_tag_lines_237" ]]; then
    record_failure "$test_name" "T25-237: hub_template.html 에 <dialog 태그가 있음(네이티브 모달 도입 — 결정 SC2 위반)"
    return 1
  fi
  if grep -qF -- 'showModal(' "$hub_template_file"; then
    record_failure "$test_name" "T25-237: hub_template.html 에 showModal( 호출이 있음(네이티브 모달 도입 — 결정 SC2 위반)"
    return 1
  fi
  if grep -qF -- 'popover=' "$hub_template_file"; then
    record_failure "$test_name" "T25-237: hub_template.html 에 popover= 속성이 있음(네이티브 모달 도입 — 결정 SC2 위반)"
    return 1
  fi

  # T25-238(신설, M2, 결정 SC9·SC10): renderSessionModal() 이 앵커 포착 → 맞대기 → 앵커
  # 복원 순서를 지키고, render() 는 revealOpenSessionCard( 를 부르지 않는다(매 렌더
  # 재중앙정렬은 옛 결함 4 의 재발 원인이었다) · ResizeObserver 콜백이 폭 변화(contentRect.width)
  # 만 본다.
  local render_session_modal_body_238
  render_session_modal_body_238=$(sed -n '/function renderSessionModal(){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$render_session_modal_body_238" ]]; then
    record_failure "$test_name" "T25-238: renderSessionModal() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  local capture_line_238 reconcile_line_238 restore_line_238
  capture_line_238=$(grep -n 'captureStripAnchor(' <<< "$render_session_modal_body_238" | head -1 | cut -d: -f1)
  reconcile_line_238=$(grep -n 'reconcileChildren(' <<< "$render_session_modal_body_238" | head -1 | cut -d: -f1)
  restore_line_238=$(grep -n 'restoreStripAnchor(' <<< "$render_session_modal_body_238" | head -1 | cut -d: -f1)
  if [[ -z "$capture_line_238" || -z "$reconcile_line_238" || -z "$restore_line_238" \
      || ! "$capture_line_238" -lt "$reconcile_line_238" \
      || ! "$reconcile_line_238" -lt "$restore_line_238" ]]; then
    record_failure "$test_name" "T25-238: renderSessionModal() 이 captureStripAnchor → reconcileChildren → restoreStripAnchor 순을 지키지 않음(결정 SC9 위반)"
    return 1
  fi
  local render_fn_body_238
  render_fn_body_238=$(sed -n '/function render(){/,/^  }$/p' "$hub_template_file")
  if grep -qF 'revealOpenSessionCard(' <<< "$render_fn_body_238"; then
    record_failure "$test_name" "T25-238: render() 가 revealOpenSessionCard( 를 부름(결정 SC10 위반 — 매 렌더 재중앙정렬, 옛 결함 4 재발)"
    return 1
  fi
  if ! grep -qF 'contentRect.width' "$hub_template_file"; then
    record_failure "$test_name" "T25-238: ResizeObserver 콜백이 contentRect.width 를 비교하지 않음(결정 SC10 위반)"
    return 1
  fi

  # T25-239(신설, M2, 결정 SC1·SC2·SC11·SC13): 모달 규칙 블록에 색 리터럴이 없고(새 색 토큰
  # 0개), 목록 스크롤 잠금이 밀어내기 모드의 사용량 이동 규칙보다 소스 순서상 뒤에 있어야
  # 이긴다(T25-239), reduced-motion 무효화가 모달 전이·세션 카드 glow 양쪽에 있으며, 세션
  # 카드 작업중 강조가 카드와 같은 keyframes(card-working-glow)를 공유한다(새 keyframes
  # 없음).
  local session_modal_css_block_239
  session_modal_css_block_239=$(sed -n '/^  \.session-modal{position:absolute/,/^<\/style>$/p' "$hub_template_file")
  if [[ -z "$session_modal_css_block_239" ]]; then
    record_failure "$test_name" "T25-239: 모달 CSS 블록 앵커를 찾지 못함 — 앵커가 깨졌다"
    return 1
  fi
  if grep -qE '#[0-9a-fA-F]{3,6}' <<< "$session_modal_css_block_239"; then
    record_failure "$test_name" "T25-239: 모달 CSS 블록에 하드코딩된 # 색 리터럴이 있음(새 색 토큰 0개 위반)"
    return 1
  fi
  local scroll_lock_line_239 panel_push_usage_line_239
  scroll_lock_line_239=$(grep -n 'body.dzh-session-modal-open{overflow:hidden}' "$hub_template_file" | head -1 | cut -d: -f1)
  panel_push_usage_line_239=$(grep -n 'body.dzh-panel-open #dzh-usage{transform:' "$hub_template_file" | head -1 | cut -d: -f1)
  if [[ -z "$scroll_lock_line_239" || -z "$panel_push_usage_line_239" \
      || "$scroll_lock_line_239" -le "$panel_push_usage_line_239" ]]; then
    record_failure "$test_name" "T25-239: 모달 스크롤 잠금이 밀어내기 모드 사용량 이동 규칙보다 앞(또는 부재) — 소스 순서상 뒤여야 이긴다"
    return 1
  fi
  local reduced_motion_token_239
  for reduced_motion_token_239 in \
      'body.dzh-session-modal-open .session-modal{transition:none}' \
      '.session-card.card-working::after{animation:none;opacity:1}'; do
    if ! grep -qF -- "$reduced_motion_token_239" "$hub_template_file"; then
      record_failure "$test_name" "T25-239: prefers-reduced-motion 무효화에 $reduced_motion_token_239 이 없음"
      return 1
    fi
  done
  local card_working_glow_usage_count_239
  card_working_glow_usage_count_239=$(grep -cF 'animation:card-working-glow 2s ease-in-out infinite' "$hub_template_file")
  if [[ "$card_working_glow_usage_count_239" -lt 2 ]]; then
    record_failure "$test_name" "T25-239: animation:card-working-glow 2s ease-in-out infinite 사용이 ${card_working_glow_usage_count_239}건뿐(카드+세션 카드 2건 기대 — 새 keyframes 를 만들지 않고 공유해야 한다)"
    return 1
  fi

  # T25-240(신설, M2, 승인 4 = 안 B, 결정 SC12): 루트↔세션 연결선(안 B)이 실제로 그려진다 —
  # 버스(가로 줄)와 줄기(루트 아래) 규칙이 모두 존재해야 "이 프로젝트 아래 이 세션들"이라는
  # 관계가 선으로 보인다.
  # 세 줄로 나눠 쓴다(반복문 대신) — 반복문 메시지는 변수를 보간해 소스에 리터럴로
  # 나타나지 않아 원장 판별자 자격(T37-13)을 못 채운다.
  if ! grep -qF -- '.session-strip-linked>li::before{' "$hub_template_file"; then
    record_failure "$test_name" "T25-240: hub_template.html 에 연결선 드롭 규칙(.session-strip-linked>li::before)이 없음(승인 4 안 B 위반 — 연결선 부분 삭제)"
    return 1
  fi
  if ! grep -qF -- '.session-strip-linked>li::after{' "$hub_template_file"; then
    record_failure "$test_name" "T25-240: hub_template.html 에 연결선 버스 규칙(.session-strip-linked>li::after)이 없음(승인 4 안 B 위반 — 연결선 부분 삭제)"
    return 1
  fi
  if ! grep -qF -- '.session-modal-root.root-linked::after{' "$hub_template_file"; then
    record_failure "$test_name" "T25-240: hub_template.html 에 연결선 줄기 규칙(.session-modal-root.root-linked::after)이 없음(승인 4 안 B 위반 — 연결선 부분 삭제)"
    return 1
  fi

  # ── 카드 상세보기 모달 작은 결함 2건 수정(hub-modal-and-subagent-pause 워크트리) 신규
  # 가드 — T25-246~247 (T25-245 는 main 커밋 b81ddaa 가 먼저 쓴 번호라 이 뒤부터 잇는다) ──

  # T25-246(신설, 결함 ②, 2026-09-28): 세션 카드 li 에 min-width:0 이 없으면 flex 아이템의
  # 자동 최소 크기(min-width:auto, 내용의 min-content)가 줄바꿈 없는 실행 줄 제목에 밀려
  # 카드 폭이 정한 폭보다 넓어지고 그 제목의 말줄임(ellipsis)이 죽는다(폭이 280px 이던 때의 실측 —
  # 지금 폭은 메인 카드와 비슷한 --session-card-width 다, 결정 MX8 개정. 가드는 폭 값이 아니라 min-width:0 만 본다).
  local session_strip_li_rule_246
  session_strip_li_rule_246=$(grep -oE '\.session-strip>li\{[^}]*\}' "$hub_template_file" | head -1)
  if [[ -z "$session_strip_li_rule_246" ]]; then
    record_failure "$test_name" "T25-246: hub_template.html 에 .session-strip>li{...} 규칙을 찾지 못함 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF -- 'min-width:0' <<< "$session_strip_li_rule_246"; then
    record_failure "$test_name" "T25-246: .session-strip>li 규칙에 min-width:0 이 없음(결함 ② 회귀 — 실행 줄 제목이 카드 폭을 밀어 말줄임이 죽는다)"
    return 1
  fi

  # T25-247(역전환 — 카드 상세보기 정리 M3, 결정 MX1·MX13, docs/prps/hub-session-modal-cleanup.md §10.1;
  # 원래는 결함 ③(2026-09-28)의 정방향 가드였다: 모달 루트는 그 대시보드를 여는 유일한 길일 때만 패널
  # 속성을 단다): 루트가 어떤 경우에도 패널을 열지 않게 되며 그 게이트 판정 함수, 패널 속성 함수,
  # 프로젝트판 사유 함수·상수와, 루트를 누를 수 있게 하던 CSS(패널 속성에 거는 커서·hover 규칙, 열림 표시)가
  # 템플릿 어디에도 되살아나지 않는다(주석 포함, T25-178 선례 — 걷은 식별자를 템플릿 주석에 다시 적지
  # 않는다). 사유 함수는 세션판(sessionPanelEmptyReason)이 남아 있어 함수 정의 형태로 센다.
  # 여섯 줄로 나눠 쓴다(반복문 대신) — 반복문 메시지는 변수를 보간해 소스에 리터럴로 나타나지 않아 원장
  # 판별자 자격(T37-13)을 못 채운다(T25-240 관례와 같은 이유).
  if grep -qF -- 'isRootOnlyDashboardPath' "$hub_template_file"; then
    note_failure "T25-247: hub_template.html 에 걷은 루트 게이트 판정 함수가 되살아남(결정 MX1 위반 — 루트는 어떤 경우에도 패널을 열지 않는다, 주석에도 다시 적지 않는다)"
  fi
  if grep -qF -- 'projectPanelAttributes' "$hub_template_file"; then
    note_failure "T25-247: hub_template.html 에 걷은 루트 패널 속성 함수가 되살아남(결정 MX1 위반 — 루트는 패널 타깃이 아니다, 주석에도 다시 적지 않는다)"
  fi
  if grep -qF -- 'function panelEmptyReason(' "$hub_template_file"; then
    note_failure "T25-247: hub_template.html 에 걷은 프로젝트판 사유 함수가 되살아남(결정 MX1 위반 — 사유의 출처는 세션 쪽 하나다, 주석에도 다시 적지 않는다)"
  fi
  if grep -qF -- 'PROJECT_FINISHED_TASK_REASON' "$hub_template_file"; then
    note_failure "T25-247: hub_template.html 에 걷은 프로젝트판 끝난 작업 사유 상수가 되살아남(결정 MX1 위반 — 주석에도 다시 적지 않는다)"
  fi
  if grep -qF -- '.session-modal-root[data-' "$hub_template_file"; then
    note_failure "T25-247: hub_template.html 에 루트를 누를 수 있게 하는 속성 CSS 가 되살아남(결정 MX1 위반 — 루트는 눌리지 않는다)"
  fi
  if grep -qF -- '.session-modal-root.card-open' "$hub_template_file"; then
    note_failure "T25-247: hub_template.html 에 루트의 열림 표시 CSS 가 되살아남(결정 MX1 위반 — 루트는 패널 타깃이 아니라 열릴 수 없다)"
  fi

  # ── 백그라운드 대기 표시(hub-subagent-background-pause.md) 신규 가드 — T25-248~253
  # (M1 이 T25-253 을 먼저 배정했고, 이 회차(M2~M4)가 T25-248~252 를 채운다) ──

  # T25-248 BW-G1(신설, 정 — 결정 BW2, docs/prps/hub-subagent-background-pause.md §8.3): 훅의
  # bt·sw 투영이 실제로 정규화·재검증 경로를 경유하는지 본다 — 원문을 그대로 옮기는 우회를
  # 잡는다.
  if ! grep -qF 'hub_session_facts.BACKGROUND_REPORTING_EVENT_NAMES' "$hub_hook_file"; then
    note_failure "T25-248: hub_hook.py 의 _project_fields 가 BACKGROUND_REPORTING_EVENT_NAMES 로 게이트하지 않음"
  fi
  local task_type_counts_body_248
  task_type_counts_body_248=$(awk '/^def _task_type_counts\(/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_hook_file")
  if [[ -z "$task_type_counts_body_248" ]]; then
    record_failure "$test_name" "T25-248: _task_type_counts() 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'normalize_background_task_type(' <<< "$task_type_counts_body_248"; then
    note_failure "T25-248: _task_type_counts() 가 normalize_background_task_type( 을 경유하지 않음"
  fi
  if ! grep -qE '^[[:space:]]*fields\["bt"\] = _task_type_counts\(' "$hub_hook_file"; then
    note_failure "T25-248: hub_hook.py 에 fields[\"bt\"] = _task_type_counts( 로 시작하는 줄이 없음"
  fi
  if ! grep -qE '^[[:space:]]*fields\["sw"\] = _one_shot_wakeup_count\(' "$hub_hook_file"; then
    note_failure "T25-248: hub_hook.py 에 fields[\"sw\"] = _one_shot_wakeup_count( 로 시작하는 줄이 없음"
  fi
  local one_shot_wakeup_count_body_248
  one_shot_wakeup_count_body_248=$(awk '/^def _one_shot_wakeup_count\(/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_hook_file")
  if [[ -z "$one_shot_wakeup_count_body_248" ]]; then
    record_failure "$test_name" "T25-248: _one_shot_wakeup_count() 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF '"recurring"' <<< "$one_shot_wakeup_count_body_248"; then
    note_failure "T25-248: _one_shot_wakeup_count() 에 \"recurring\" 이 없음"
  fi

  # T25-249 BW-G2(신설, 역(프라이버시) — 결정 BW2, docs/prps/hub-subagent-background-pause.md
  # §8.3): hub_hook.py 는 description·command·prompt·schedule 문자열 리터럴을 갖지 않는다
  # (background_tasks·session_crons 의 자유 텍스트 필드 — RI7 프라이버시 고지와 같은 계열).
  # bt·sw 투영 함수 세 개(_background_fields·_task_type_counts·_one_shot_wakeup_count)는
  # id·status·agent_type 리터럴도 갖지 않는다 — 호스트가 이미 running·pending 만 실어도
  # (§1.3-2) status 로 거르고 싶은 유혹을 막는다.
  local forbidden_free_text_key_249
  for forbidden_free_text_key_249 in '"description"' '"command"' '"prompt"' '"schedule"'; do
    if grep -qF -- "$forbidden_free_text_key_249" "$hub_hook_file"; then
      note_failure "T25-249: hub_hook.py 에 $forbidden_free_text_key_249 문자열 리터럴이 있음(BW2 프라이버시 위반)"
    fi
  done
  local background_projection_body_249
  background_projection_body_249=$(awk '/^def _background_fields\(/{flag=1} flag{print} /^def _append_event_line\(/{exit}' "$hub_hook_file")
  if [[ -z "$background_projection_body_249" ]]; then
    record_failure "$test_name" "T25-249: _background_fields()~_one_shot_wakeup_count() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  local forbidden_field_key_249
  for forbidden_field_key_249 in '"id"' '"status"' '"agent_type"'; do
    if grep -qF -- "$forbidden_field_key_249" <<< "$background_projection_body_249"; then
      note_failure "T25-249: hub_hook.py 의 bt·sw 투영 함수에 $forbidden_field_key_249 리터럴이 있음(BW2 프라이버시 위반)"
    fi
  done

  # T25-250 BW-G3(신설, 정 — 결정 BW10, docs/prps/hub-subagent-background-pause.md §8.3):
  # 템플릿 STATE_LABEL·STATE_GLYPH 에 background 키가 있고, BACKGROUND_SESSION_LABEL 상수와
  # stateLabel() 의 background 분기가 있으며, .badge.state-background{ 규칙이 존재하고 그
  # 본문에 animation·box-shadow 가 없다(T25-190·T25-243 의 halo 금지 정신과 같은 검사).
  # renderSessionContent() 가 session.background_wait 를 renderStateBadge 에 넘기는지도 본다.
  if ! grep -qE 'STATE_LABEL = \{[^}]*background:' "$hub_template_file"; then
    note_failure "T25-250: hub_template.html 의 STATE_LABEL 에 background: 키가 없음"
  fi
  if ! grep -qE 'STATE_GLYPH = \{[^}]*background:' "$hub_template_file"; then
    note_failure "T25-250: hub_template.html 의 STATE_GLYPH 에 background: 키가 없음"
  fi
  if ! grep -qF "var BACKGROUND_SESSION_LABEL = '백그라운드 대기';" "$hub_template_file"; then
    note_failure "T25-250: hub_template.html 에 BACKGROUND_SESSION_LABEL 상수가 없음"
  fi
  local state_label_fn_body_250
  state_label_fn_body_250=$(sed -n '/function stateLabel(state, baseState, interruption, nowMs){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$state_label_fn_body_250" ]]; then
    record_failure "$test_name" "T25-250: stateLabel() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF "if(state === 'background') return BACKGROUND_SESSION_LABEL;" <<< "$state_label_fn_body_250"; then
    note_failure "T25-250: stateLabel() 에 background 분기가 없음"
  fi
  local badge_background_rule_250
  badge_background_rule_250=$(grep -oE '[^{}]*\.badge\.state-background\{[^}]*\}' "$hub_template_file")
  if [[ -z "$badge_background_rule_250" ]]; then
    note_failure "T25-250: hub_template.html 에 .badge.state-background{ 규칙이 없음"
  elif grep -qE 'animation|box-shadow' <<< "$badge_background_rule_250"; then
    note_failure "T25-250: .badge.state-background 규칙에 animation/box-shadow 가 있음(halo 금지 위반) — $badge_background_rule_250"
  fi
  local render_session_content_body_250
  render_session_content_body_250=$(sed -n '/function renderSessionContent(session){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$render_session_content_body_250" ]]; then
    record_failure "$test_name" "T25-250: renderSessionContent() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'session.background_wait' <<< "$render_session_content_body_250"; then
    note_failure "T25-250: renderSessionContent() 가 session.background_wait 를 넘기지 않음"
  fi

  # T25-251 BW-G4(신설, 정+역 — 결정 BW4·BW5·BW6·BW8, docs/prps/
  # hub-subagent-background-pause.md §8.3): 깨우는 종류 집합에 subagent·teammate 가 없고
  # (이중 계산 방지, U3) · 상한 상수 값이 맞고 · _display_state() 의 사다리 순서(background 가
  # interrupted 뒤·stale 앞)가 지켜지고 · 프로젝트 LIVE_SESSION_STATES 에 background 가 있다.
  local waking_background_task_types_line_251
  waking_background_task_types_line_251=$(grep -E '^WAKING_BACKGROUND_TASK_TYPES' "$hub_session_file")
  if [[ -z "$waking_background_task_types_line_251" ]]; then
    note_failure "T25-251: hub_session.py 에 WAKING_BACKGROUND_TASK_TYPES 선언을 찾지 못함"
  elif grep -qE '"subagent"|"teammate"' <<< "$waking_background_task_types_line_251"; then
    note_failure "T25-251: WAKING_BACKGROUND_TASK_TYPES 에 subagent/teammate 가 있음(이중 계산 — U3 위반)"
  fi
  if ! grep -qF 'BACKGROUND_WAIT_MAX_MS = 90 * 60 * 1000' "$hub_session_file"; then
    note_failure "T25-251: hub_session.py 에 BACKGROUND_WAIT_MAX_MS = 90 * 60 * 1000 선언이 없음"
  fi
  local display_state_body_251
  display_state_body_251=$(awk '/^def _display_state\(/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_session_file")
  if [[ -z "$display_state_body_251" ]]; then
    record_failure "$test_name" "T25-251: _display_state() 본문 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  local interrupted_return_line_251 background_return_line_251 stale_return_line_251
  interrupted_return_line_251=$(grep -nF 'return "interrupted"' <<< "$display_state_body_251" | head -1 | cut -d: -f1)
  background_return_line_251=$(grep -nF 'return "background"' <<< "$display_state_body_251" | head -1 | cut -d: -f1)
  stale_return_line_251=$(grep -nF 'return "stale"' <<< "$display_state_body_251" | head -1 | cut -d: -f1)
  if [[ -z "$interrupted_return_line_251" || -z "$background_return_line_251" || -z "$stale_return_line_251" ]]; then
    note_failure "T25-251: _display_state() 에 interrupted/background/stale 반환 줄 중 하나가 없음"
  elif ! ((interrupted_return_line_251 < background_return_line_251 && background_return_line_251 < stale_return_line_251)); then
    note_failure "T25-251: _display_state() 의 사다리 순서가 어긋남(background 가 interrupted 뒤·stale 앞이 아님)"
  fi
  local live_session_states_line_251
  live_session_states_line_251=$(grep -E '^LIVE_SESSION_STATES' "$hub_project_file")
  if [[ -z "$live_session_states_line_251" ]]; then
    note_failure "T25-251: hub_project.py 에 LIVE_SESSION_STATES 선언을 찾지 못함"
  elif ! grep -qF '"background"' <<< "$live_session_states_line_251"; then
    note_failure "T25-251: LIVE_SESSION_STATES 에 background 가 없음(BW8 위반)"
  fi

  # T25-252 BW-G5(신설, 정(문서) — 결정 BW2·BW5, docs/prps/hub-subagent-background-pause.md
  # §8.3): 배포 문서 세 곳에 정본 문구가 있는지 확인한다.
  if ! grep -qF '종류별 개수' "$hub_readme_file"; then
    note_failure "T25-252: hub/README.md 에 '종류별 개수' 토큰이 없음"
  fi
  if ! grep -qF '작업중 > 한도 초과 > 백그라운드 대기 > 대기 > 소식 없음 > 완료' "$hub_readme_file"; then
    note_failure "T25-252: hub/README.md 에 정렬 순서 문장(백그라운드 대기 포함)이 없음"
  fi
  if ! grep -qF '종류별 개수' "$hub_command_file"; then
    note_failure "T25-252: commands/hub.md 에 '종류별 개수' 토큰이 없음"
  fi
  if ! grep -qF '결정 BW1~BW12' "$hub_dashboard_prp_file"; then
    note_failure "T25-252: docs/prps/hub-dashboard.md 에 결정 BW1~BW12 개정 토큰이 없음"
  fi

  # T25-253 BW-G6(신설, 정+역 — 분리 계약, docs/prps/hub-subagent-background-pause.md §8.3
  # 결정 BW11): hub_session.py 의 입력·사실·필터·파싱·접기 절이 hub_session_facts.py 로
  # 분리된 뒤에도 그 계약이 유지되는가. ① 새 파일이 존재하고 ★순수 표지를 단다 ②
  # hub_transcript 외 허브 모듈을 임포트하지 않는다(순수 레이어 경계 — 무엇을 안 쓰는지가
  # 아니라 무엇을 쓰는지를 직접 본다, T25-10 과 상호보완) ③ 역 — hub_session.py 에 이동한
  # 심볼(parse_event_line·build_session_facts·HookEvent·SessionFacts)의 재정의가 없다
  # (되돌림 방지) ④ 짝 테스트 파일이 존재한다(MS9 — 소스 1:테스트 1).
  if [[ ! -f "$hub_session_facts_file" ]]; then
    record_failure "$test_name" "T25-253: hub_session_facts.py 가 존재하지 않음"
    return 1
  fi
  if ! grep -qF '★순수' "$hub_session_facts_file"; then
    note_failure "T25-253: hub_session_facts.py 에 ★순수 표지가 없음"
  fi
  local non_transcript_hub_import_253
  non_transcript_hub_import_253=$(grep -E '^(import|from) hub_' "$hub_session_facts_file" | grep -v 'hub_transcript')
  if [[ -n "$non_transcript_hub_import_253" ]]; then
    note_failure "T25-253: hub_session_facts.py 가 hub_transcript 외 허브 모듈을 임포트함(${non_transcript_hub_import_253})"
  fi
  local relocated_facts_symbol_253
  for relocated_facts_symbol_253 in 'def parse_event_line(' 'def build_session_facts(' 'class HookEvent:' 'class SessionFacts:'; do
    if grep -qF -- "$relocated_facts_symbol_253" "$hub_session_file"; then
      note_failure "T25-253: hub_session.py 에 이동한 심볼의 재정의($relocated_facts_symbol_253)가 남아 있음(분리 계약 위반)"
    fi
  done
  if [[ ! -f "$REPO_ROOT/tests/hub/test_hub_session_facts.py" ]]; then
    record_failure "$test_name" "T25-253: tests/hub/test_hub_session_facts.py 가 존재하지 않음"
    return 1
  fi

  # ── 카드 상세보기 정리 7건(hub-session-modal-cleanup.md) 신규 가드 — T25-254 부터 마일스톤
  # 순서대로 배정한다(같은 문서 §10.1 표 — M1 이 T25-254, M2 가 T25-255, M3 이 T25-256 을 쓴다) ──

  # T25-254(신설, 정+역 — M1, 결정 MX10, docs/prps/hub-session-modal-cleanup.md §10.1): 실행중
  # 칩은 글리프 없이 강조색과 보조기술용 텍스트(.sr-only 「 진행 중」)로만 실행 중을 말한다.
  # 정 — renderAgentRunRow() 에 그 텍스트가 남아 있다(글리프를 걷으며 화면 낭독기 채널까지
  # 지우는 회귀 방지). 역 — 같은 본문에 글리프 span 이 없다. 역 — 글리프 상수·CSS 는 파일 전체
  # (주석 포함, T25-178 선례)에 없다: 걷은 식별자를 템플릿 주석에 다시 적지 않는다.
  # 네 줄로 나눠 쓴다(반복문 대신) — 반복문 메시지는 변수를 보간해 소스에 리터럴로 나타나지
  # 않아 원장 판별자 자격(T37-13)을 못 채운다(T25-240 관례와 같은 이유).
  local render_agent_run_row_body_254
  render_agent_run_row_body_254=$(sed -n '/function renderAgentRunRow(run, nowMs){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$render_agent_run_row_body_254" ]]; then
    record_failure "$test_name" "T25-254: renderAgentRunRow() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF -- "'<span class=\"sr-only\"> ' + AGENT_RUN_RUNNING_LABEL" <<< "$render_agent_run_row_body_254"; then
    note_failure "T25-254: renderAgentRunRow() 에 보조기술용 진행 중 텍스트(.sr-only)가 없음(결정 MX10 위반 — 글리프와 함께 화면 낭독기 채널까지 지웠다)"
  fi
  if grep -qF -- 'class="glyph"' <<< "$render_agent_run_row_body_254"; then
    note_failure "T25-254: renderAgentRunRow() 본문에 글리프 span 이 되살아남(결정 MX10 위반 — 요청으로 뺀 실행중 칩의 ● 가 돌아왔다)"
  fi
  if grep -qF -- 'AGENT_RUN_RUNNING_GLYPH' "$hub_template_file"; then
    note_failure "T25-254: hub_template.html 에 실행중 칩 글리프 상수가 남아 있음(결정 MX10 — 주석에도 다시 적지 않는다)"
  fi
  if grep -qF -- '.agent-chip .glyph' "$hub_template_file"; then
    note_failure "T25-254: hub_template.html 에 실행중 칩 글리프 CSS 가 남아 있음(결정 MX10 — 주석에도 다시 적지 않는다)"
  fi

  # T25-255(신설, 정+역 — M2, 결정 MX4·MX5, docs/prps/hub-session-modal-cleanup.md §10.1): 카드와 카드
  # 상세보기 머리는 프로젝트 단위 진행률을 그리지 않고, 진행률은 세션 줄·세션 카드가 함께 쓰는
  # renderSessionProgress() 에서만 그려진다. 역 — renderProject()·renderSessionModalRoot() 본문에
  # renderTier1( 호출도 project.tier1 읽기도 없다(되살아나면 주인 세션이 목록에 없는 대시보드의 진행률이
  # 카드에 다시 붙는다). 정 — renderSessionProgress() 가 세션 자신의 tier1 로 진행률을 그리고, 진행률 렌더
  # 함수는 라벨 인자와 null 가드를 걷은 시그니처다(결정 LM6 이 더했던 끝난 작업 여부 인자는 LM12 가 걷었다).
  # 여섯 줄로 나눠 쓴다(반복문 대신) — 반복문 메시지는 변수를 보간해 소스에 리터럴로 나타나지 않아 원장
  # 판별자 자격(T37-13)을 못 채운다(T25-240 관례와 같은 이유).
  local render_project_body_255 render_session_modal_root_body_255 render_session_progress_body_255
  render_project_body_255=$(sed -n '/function renderProject(project){/,/^  }$/p' "$hub_template_file")
  render_session_modal_root_body_255=$(sed -n '/function renderSessionModalRoot(project, visibleSessions){/,/^  }$/p' "$hub_template_file")
  render_session_progress_body_255=$(sed -n '/function renderSessionProgress(session){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$render_project_body_255" || -z "$render_session_modal_root_body_255" || -z "$render_session_progress_body_255" ]]; then
    record_failure "$test_name" "T25-255: renderProject()·renderSessionModalRoot()·renderSessionProgress() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if grep -qF -- 'renderTier1(' <<< "$render_project_body_255"; then
    note_failure "T25-255: renderProject() 본문에 renderTier1( 호출이 되살아남(결정 MX4 위반 — 카드에 프로젝트 단위 진행률이 돌아왔다)"
  fi
  if grep -qF -- 'project.tier1' <<< "$render_project_body_255"; then
    note_failure "T25-255: renderProject() 본문이 project.tier1 을 읽음(결정 MX4 위반 — 카드는 프로젝트 단위 진행률을 그리지 않는다)"
  fi
  if grep -qF -- 'renderTier1(' <<< "$render_session_modal_root_body_255"; then
    note_failure "T25-255: renderSessionModalRoot() 본문에 renderTier1( 호출이 되살아남(결정 MX4 위반 — 카드 상세보기 머리에 프로젝트 단위 진행률이 돌아왔다)"
  fi
  if grep -qF -- 'project.tier1' <<< "$render_session_modal_root_body_255"; then
    note_failure "T25-255: renderSessionModalRoot() 본문이 project.tier1 을 읽음(결정 MX4 위반 — 머리는 프로젝트 단위 진행률을 그리지 않는다)"
  fi
  if ! grep -qF -- 'renderTier1(session.tier1)' <<< "$render_session_progress_body_255"; then
    note_failure "T25-255: renderSessionProgress() 가 renderTier1(session.tier1) 로 세션 자기 진행률을 그리지 않음(결정 MX4·LM12 — 진행률은 그 대시보드를 기록한 세션 아래에서만 보인다)"
  fi
  if ! grep -qF -- 'function renderTier1(tier1){' "$hub_template_file"; then
    note_failure "T25-255: 진행률 렌더 함수가 한 인자 시그니처 function renderTier1(tier1){ 가 아님(결정 MX4 — 이전 작업·주인 세션 없음 라벨 인자와 null 가드는 걷었고, 끝난 작업 여부 인자는 단계 칩이 걷히며(결정 LM12) 함께 걷었다)"
  fi

  # T25-256(신설, 정+역 — M3, 결정 MX2·MX13, docs/prps/hub-session-modal-cleanup.md §10.1): 카드는 보일
  # 세션이 있을 때만 카드 상세보기를 연다. 정 — ① renderProject() 가 그 조건을 보일 세션 수에서 한 번
  # 파생하고(opensSessionModal) 모달 표지를 그 조건 아래에서만 단다 ② data-project-path 는 무조건 단다
  # (드래그 재정렬·순서 저장이 그 셀렉터를 쓴다 — 결정 U10, 보일 세션이 없는 카드도 순서는 바꿀 수 있어야
  # 한다) ③ 표지 이름은 상수 한 곳에만 살고(quoted 리터럴 1건) 클릭 리스너는 그 상수로 만든 셀렉터로 카드를
  # 고른다 ④ CARD_SELECTOR 는 그대로다. 역 — renderProjectNameEl() 은 표지와 같은 한 값(opensSessionModal)만
  # 보고 button/span 을 가른다: 티어·대시보드 키·서버 여부로 가르던 옛 OC11 회귀(결정 N6 「없는 기능을
  # 있는 척하지 않는다」)가 없다. 열 수 있는 제목은 보조기술 표지(aria-haspopup)를 그대로 단다.
  # 반복문 밖의 고정 문구로 나눠 쓴다 — 반복문 메시지는 변수를 보간해 소스에 리터럴로 나타나지 않아 원장
  # 판별자 자격(T37-13)을 못 채운다(T25-240 관례와 같은 이유).
  local render_project_body_256 render_project_name_el_body_256
  render_project_body_256=$(sed -n '/function renderProject(project){/,/^  }$/p' "$hub_template_file")
  render_project_name_el_body_256=$(sed -n '/function renderProjectNameEl(project, opensSessionModal){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$render_project_body_256" || -z "$render_project_name_el_body_256" ]]; then
    record_failure "$test_name" "T25-256: renderProject()·renderProjectNameEl() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF -- 'var opensSessionModal = visibleSessions.length > 0;' <<< "$render_project_body_256"; then
    note_failure "T25-256: renderProject() 가 opensSessionModal 을 visibleSessions.length > 0 으로 파생하지 않음(결정 MX2 위반 — 모달을 여는 조건이 보일 세션 수에서 갈라졌다)"
  fi
  local opener_attribute_line_256
  opener_attribute_line_256=$(grep -F -- 'SESSION_MODAL_OPENER_ATTRIBUTE' <<< "$render_project_body_256" || true)
  if ! grep -qF -- 'opensSessionModal ?' <<< "$opener_attribute_line_256"; then
    note_failure "T25-256: renderProject() 가 모달 표지(SESSION_MODAL_OPENER_ATTRIBUTE)를 opensSessionModal 조건 없이 붙임(결정 MX2 위반 — 보일 세션이 없는 카드도 모달을 연다)"
  fi
  if ! grep -qF -- "var cardAttrs = ' data-project-path=\"'" <<< "$render_project_body_256"; then
    note_failure "T25-256: renderProject() 의 카드 속성이 data-project-path 로 무조건 시작하지 않음(결정 MX2 위반 — 보일 세션이 없는 카드가 드래그 재정렬·순서 저장에서 빠진다)"
  fi
  local modal_opener_literal_count_256
  modal_opener_literal_count_256=$(grep -cF -- "'data-opens-session-modal'" "$hub_template_file") || true
  if [[ "$modal_opener_literal_count_256" != "1" ]]; then
    note_failure "T25-256: hub_template.html 의 모달 표지 이름 리터럴이 ${modal_opener_literal_count_256}건(기대 1 — 이름은 상수 한 곳에만 산다)"
  fi
  if ! grep -qF -- "var SESSION_MODAL_CARD_SELECTOR = '.card[' + SESSION_MODAL_OPENER_ATTRIBUTE + ']';" "$hub_template_file"; then
    note_failure "T25-256: SESSION_MODAL_CARD_SELECTOR 가 모달 표지 상수로 만든 셀렉터가 아님(결정 MX2 위반)"
  fi
  if ! grep -qF -- 'var card = event.target.closest(SESSION_MODAL_CARD_SELECTOR);' "$hub_template_file"; then
    note_failure "T25-256: 카드 상세보기 클릭 리스너가 SESSION_MODAL_CARD_SELECTOR 로 카드를 고르지 않음(결정 MX2 위반 — 보일 세션이 없는 카드도 모달을 연다)"
  fi
  if ! grep -qF -- "var CARD_SELECTOR = '.card[data-project-path]';" "$hub_template_file"; then
    note_failure "T25-256: CARD_SELECTOR 가 .card[data-project-path] 가 아님(결정 MX2·U10 위반 — 드래그·순서 저장이 보일 세션이 있는 카드로 좁아진다)"
  fi
  if ! grep -qF -- '<span class="project-name">' <<< "$render_project_name_el_body_256"; then
    note_failure "T25-256: renderProjectNameEl() 에 눌리지 않는 span 분기가 없음(결정 MX2 위반 — 모달을 열지 못하는 카드의 제목도 버튼이다)"
  fi
  if ! grep -qF -- 'aria-haspopup="dialog"' <<< "$render_project_name_el_body_256"; then
    note_failure "T25-256: renderProjectNameEl() 의 버튼에 aria-haspopup=\"dialog\" 가 없음(결정 SC4 위반 — 모달을 여는 제목의 보조기술 표지)"
  fi
  local name_el_condition_token_256
  for name_el_condition_token_256 in 'project.tier' 'dashboard_key' 'isServed'; do
    if grep -qF -- "$name_el_condition_token_256" <<< "$render_project_name_el_body_256"; then
      note_failure "T25-256: renderProjectNameEl() 가 $name_el_condition_token_256 을 봄(결정 MX2 위반 — button/span 은 보일 세션 유무 한 값으로만 가른다, 옛 OC11 회귀)"
    fi
  done

  # T25-257(신설, 정+역 — M4, 결정 MX6·MX13, docs/prps/hub-session-modal-cleanup.md §10.1): 루트↔세션 연결선
  # (줄기·드롭·버스)과 칸 번짐의 기하는 .session-modal-body 에 선언한 사용자 정의 속성 5개(bleed·gap·link-x·
  # link-stem·link-drop)에서만 파생된다 — 줄기(루트 쪽)와 드롭(칸 쪽)이 각자 리터럴을 갖던 것이 1px 어긋남과
  # 줄기가 버스 아래로 삐져나오던 결함의 원인이었다. 정 — ① 속성 다섯이 그 규칙 안에 각각 정확히 한 번
  # 선언되고 파일 전체에서도 한 번뿐이다(규칙 안 계수만으로는 다른 규칙이나 @media 에서 같은 속성을 다시 선언해도
  # 잡히지 않는다 — 그러면 그 범위의 줄기·드롭·버스만 본문과 다른 값을 쓴다. 파일 전체 계수는 콜론 앞에 공백을 낀
  # 선언 형태도 세고 주석까지 세므로, 주석에는 속성 이름 뒤에 콜론을 붙여 적지 않는다) ② 줄기·드롭이 같은 link-x 로
  # 왼쪽 자리를 잡고(줄기 x = 드롭 x 가 구성상 성립한다) 줄기 높이는 link-stem, 드롭의 높이·윗자리와 버스의
  # 윗자리는 link-drop 이다 ③ 칸의 위 패딩이 stem + drop 이라 줄기 아랫끝이 버스 윗변과 만난다 ④ 프레임의 음수
  # 여백과 칸의 안쪽·스크롤 패딩이 같은 bleed 짝이고 카드 간격이
  # gap 이다 ⑤ 첫 카드 버스는 link-x 에서 시작하고 끝 카드 버스는 link-x + gap / 2 폭이며 가운데 카드 버스는
  # 양쪽으로 gap / 2 씩 번진다(그래서 버스가 첫 드롭 왼쪽에 꼬리를 남기지도, 끝 드롭에 못 닿지도, 이웃 카드 버스와
  # 이어지지 않아 간격에 구멍이 나지도 않는다). 역 — 줄기·드롭·버스·칸 규칙에
  # left/right/width/height/top/padding-top 의 px 리터럴이 없다(M3 이 임시로 넣었던 땜질값 셋이 이 대상이다: 루트
  # 여백이 바뀌면 다시 어긋난다). 규칙이 여러 줄이라 extract_flattened_css_rules 로 뽑는다. 반복문 밖의 고정 문구로
  # 나눠 쓴다 — 반복문 메시지는 변수를 보간해 소스에 리터럴로 나타나지 않아 원장 판별자 자격(T37-13)을 못 채운다
  # (T25-240 관례와 같은 이유).
  local modal_body_rule_257 strip_frame_rule_257 strip_rule_257 strip_linked_rule_257
  local stem_rule_257 drop_rule_257 bus_rules_257 middle_bus_rule_257
  modal_body_rule_257=$(extract_flattened_css_rules "$hub_template_file" '\.session-modal-body' | head -1)
  strip_frame_rule_257=$(extract_flattened_css_rules "$hub_template_file" '\.session-strip-frame' | head -1)
  strip_rule_257=$(extract_flattened_css_rules "$hub_template_file" '\.session-strip' | head -1)
  strip_linked_rule_257=$(extract_flattened_css_rules "$hub_template_file" '\.session-strip\.session-strip-linked' | head -1)
  stem_rule_257=$(extract_flattened_css_rules "$hub_template_file" '\.session-modal-root\.root-linked::after' | head -1)
  drop_rule_257=$(extract_flattened_css_rules "$hub_template_file" '\.session-strip-linked>li::before' | head -1)
  bus_rules_257=$(extract_flattened_css_rules "$hub_template_file" '\.session-strip-linked>li(:first-child|:last-child)?::after')
  middle_bus_rule_257=$(extract_flattened_css_rules "$hub_template_file" '\.session-strip-linked>li::after' | head -1)
  if [[ -z "$modal_body_rule_257" || -z "$strip_frame_rule_257" || -z "$strip_rule_257" || -z "$strip_linked_rule_257" \
      || -z "$stem_rule_257" || -z "$drop_rule_257" || -z "$bus_rules_257" ]]; then
    record_failure "$test_name" "T25-257: 연결선·칸·프레임 CSS 규칙 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  local link_property_257 link_property_count_257 link_property_file_count_257
  for link_property_257 in --session-strip-bleed --session-strip-gap --session-link-x --session-link-stem --session-link-drop; do
    link_property_count_257=$(grep -oF -- "${link_property_257}:" <<< "$modal_body_rule_257" | wc -l | tr -d ' ' || true)
    if [[ "$link_property_count_257" != "1" ]]; then
      note_failure "T25-257: .session-modal-body 의 ${link_property_257} 선언이 ${link_property_count_257}건(기대 1 — 연결선 기하 속성은 이 규칙에서 한 번만 선언한다, 결정 MX6)"
    fi
    link_property_file_count_257=$(grep -oE -- "${link_property_257}[[:space:]]*:" "$hub_template_file" | wc -l | tr -d ' ' || true)
    if [[ "$link_property_file_count_257" != "1" ]]; then
      note_failure "T25-257: hub_template.html 전체에서 ${link_property_257} 선언이 ${link_property_file_count_257}건(기대 1 — 본문 규칙 밖의 다른 규칙이나 @media 에서 다시 선언하면 그 범위의 줄기·드롭·버스만 본문과 다른 값을 쓴다, 결정 MX6)"
    fi
  done
  if ! grep -qF -- 'left:var(--session-link-x)' <<< "$stem_rule_257"; then
    note_failure "T25-257: 줄기 규칙의 왼쪽 자리가 --session-link-x 가 아님(결정 MX6 위반 — 줄기 x 와 드롭 x 가 같은 속성에서 나오지 않으면 스크롤 0 에서 어긋난다)"
  fi
  if ! grep -qF -- 'top:100%' <<< "$stem_rule_257"; then
    note_failure "T25-257: 줄기 규칙이 루트 아랫변(top:100%)에서 시작하지 않음(결정 MX6 위반)"
  fi
  if ! grep -qF -- 'height:var(--session-link-stem)' <<< "$stem_rule_257"; then
    note_failure "T25-257: 줄기 규칙의 높이가 --session-link-stem 이 아님(결정 MX6 위반 — 줄기 아랫끝이 버스와 만나는 값은 칸 위 패딩과 같은 속성에서 나와야 한다)"
  fi
  if ! grep -qF -- 'left:var(--session-link-x)' <<< "$drop_rule_257"; then
    note_failure "T25-257: 드롭 규칙의 왼쪽 자리가 --session-link-x 가 아님(결정 MX6 위반 — 줄기 x 와 드롭 x 가 어긋난다)"
  fi
  if ! grep -qF -- 'top:calc(-1 * var(--session-link-drop))' <<< "$drop_rule_257"; then
    note_failure "T25-257: 드롭 규칙의 윗자리가 -1 * --session-link-drop 이 아님(결정 MX6 위반 — 드롭 아랫끝이 카드 윗변과 어긋난다)"
  fi
  if ! grep -qF -- 'height:var(--session-link-drop)' <<< "$drop_rule_257"; then
    note_failure "T25-257: 드롭 규칙의 높이가 --session-link-drop 이 아님(결정 MX6 위반)"
  fi
  if ! grep -qF -- 'top:calc(-1 * var(--session-link-drop))' <<< "$bus_rules_257"; then
    note_failure "T25-257: 버스 규칙의 윗자리가 -1 * --session-link-drop 이 아님(결정 MX6 위반 — 버스가 줄기 아랫끝과 어긋난다)"
  fi
  if ! grep -qF -- '.session-strip-linked>li:first-child::after{left:var(--session-link-x)}' <<< "$bus_rules_257"; then
    note_failure "T25-257: 첫 카드 버스 규칙이 왼쪽 끝을 --session-link-x 로 잡지 않음(결정 MX6 위반 — 버스가 첫 드롭 x 보다 왼쪽으로 삐져나가 꼬리가 남는다)"
  fi
  if ! grep -qF -- '.session-strip-linked>li:last-child::after{right:auto;width:calc(var(--session-link-x) + var(--session-strip-gap) / 2)}' <<< "$bus_rules_257"; then
    note_failure "T25-257: 끝 카드 버스 규칙의 폭이 link-x + gap / 2 가 아님(결정 MX6 위반 — 버스가 끝 드롭 x 에 못 닿거나 지나친다)"
  fi
  if ! grep -qF -- 'left:calc(var(--session-strip-gap) / -2)' <<< "$middle_bus_rule_257"; then
    note_failure "T25-257: 가운데 카드 버스 규칙의 왼쪽 번짐이 gap 의 절반(left:calc(var(--session-strip-gap) / -2))이 아니거나 규칙이 없음(결정 MX6 위반 — 이웃 카드 버스와 이어지지 않아 간격에 구멍이 난다)"
  fi
  if ! grep -qF -- 'right:calc(var(--session-strip-gap) / -2)' <<< "$middle_bus_rule_257"; then
    note_failure "T25-257: 가운데 카드 버스 규칙의 오른쪽 번짐이 gap 의 절반(right:calc(var(--session-strip-gap) / -2))이 아니거나 규칙이 없음(결정 MX6 위반 — 이웃 카드 버스와 이어지지 않아 간격에 구멍이 난다)"
  fi
  if ! grep -qF -- 'padding-top:calc(var(--session-link-stem) + var(--session-link-drop))' <<< "$strip_linked_rule_257"; then
    note_failure "T25-257: 연결선이 있는 칸의 위 패딩이 stem + drop 이 아님(결정 MX6 위반 — 줄기 아랫끝이 버스 윗변과 만나지 않는다)"
  fi
  if ! grep -qF -- 'margin:0 calc(-1 * var(--session-strip-bleed))' <<< "$strip_frame_rule_257"; then
    note_failure "T25-257: 칸 프레임의 음수 여백이 --session-strip-bleed 가 아님(결정 MX6 위반 — 루트 왼끝과 첫 카드 왼끝이 어긋난다)"
  fi
  if ! grep -qE 'padding:[^;]*var\(--session-strip-bleed\)' <<< "$strip_rule_257" \
      || ! grep -qF -- 'scroll-padding-inline:var(--session-strip-bleed)' <<< "$strip_rule_257"; then
    note_failure "T25-257: 칸의 안쪽 패딩·스크롤 패딩이 --session-strip-bleed 가 아님(결정 MX6 위반 — 프레임 번짐과 짝이 깨진다)"
  fi
  if ! grep -qF -- 'gap:var(--session-strip-gap)' <<< "$strip_rule_257"; then
    note_failure "T25-257: 칸의 카드 간격이 --session-strip-gap 이 아님(결정 MX6 위반 — 버스가 잇는 간격과 카드 간격이 갈라진다)"
  fi
  if grep -qE '(^|[;{ ])(left|right|width|height|top|padding-top):-?[0-9.]+px' <<< "${stem_rule_257} ${drop_rule_257} ${bus_rules_257} ${strip_linked_rule_257}"; then
    note_failure "T25-257: 줄기·드롭·버스·칸 규칙에 left/right/width/height/top/padding-top 의 px 리터럴이 있음(결정 MX6 위반 — 땜질값은 루트 여백이 바뀌면 다시 어긋난다)"
  fi

  # T25-258(개정 — 결정 LM8·LM9, docs/prps/hub-session-row-layout-and-modal-size.md; 원래는 M4 결정 MX7·MX8 의 가드였다,
  # docs/prps/hub-session-modal-cleanup.md §10.1; 2026-10 개정 — 사용량 패널과 무관한 자리·윗변이 영역 높이의 12.5% 에 걸리는
  # 위치(30% 가 가운데처럼 보여 재재개정)·스크롤 막대 숨김·메인 카드와 비슷한 카드 폭): 카드 상세보기 창은 내용 높이이고 윗변이 영역(헤더 아래 ~ 화면 아래) 윗변에서
  # 영역 높이의 12.5% 아래에 걸리며, 세션 카드는 메인 카드와 비슷한 폭이다. 정 — ① 다이얼로그가 height 가 아니라 max-height:100%
  # 이고 세로 margin 이 0(스페이서가 자리를 정한다 — 자동 여백이면 남는 공간을 위아래로 나눠 가운데로 돌아간다)이며 내용이 넘치면
  # 다이얼로그가 세로 스크롤한다 ② 오버레이(.session-modal)가 세로 flex 컨테이너이고 padding-bottom:16px 고정이다 — 사용량 패널
  # (떠 있는 컴포넌트)이 있어도 그 여백이 바뀌지 않는다(SC16 개정: 역 — .session-modal 규칙 어디에도 --usage-clearance 가 없다)
  # 창 앞 스페이서(.session-modal::after)는 order:-1 · flex:0 1 12.5% 이고 창은 flex-shrink:0 이라 넘치면 스페이서가 먼저 줄어든다
  # 다이얼로그가 container-type:inline-size 라 카드 폭이 cqw 로 창 폭을 읽는다 ③ 본문·프레임·칸이 세로 flex 사슬(본문·프레임은
  # display:flex + flex-direction:column)이고 셋 다 flex:1 0 auto 다 — 창 높이가 내용에서 나오므로 grow(1)는 비활성이고 끝의 0 이
  # 하중을 진다: 칸은 overflow-x:auto 라 스크롤 컨테이너이고 그 자동 최소 높이는 0 이라, 줄어들 수 있으면(1) 창이 max-height 에
  # 닿아 넘치는 순간 칸이 자기 안에서 세로 스크롤한다(SC6 이 기각한 가로·세로 스크롤 칸의 겹침, LM9). Chrome 154 실측으로는
  # 세 단계 중 하나만 0 이어도 칸이 줄지 않는다 — 셋을 다 못박는 것은 중복 방어다 ④ 세션 카드 li 의 폭이 --session-card-width 이고
  # 그 값이 본문 규칙 + 컨테이너 쿼리 둘(2열·3열 문턱)에서 메인 그리드의 열 수를 따르되 폭은 칸 안쪽 폭 기준(max(320px, calc((100cqw − 간격 합)/열 수)))이라 2·3개가 칸에 딱 들어간다 ⑤ 칸의 스크롤 막대는 보이지 않는다
  # (scrollbar-width:none 과 ::-webkit-scrollbar 의 display:none 짝).
  # 역 — 다이얼로그 규칙에 고정 높이 선언(height 와 calc 의 조합)이 없고 옛 사용량 변형 규칙도 없다. 소스의 모달 규칙 선택자 뒤에는
  # 여는 중괄호를 주석에 적지 않는다(extract_flattened_css_rules 의 한계).
  local dialog_rules_258 dialog_rule_258 modal_rules_258 modal_rule_258 spacer_rule_258 container_rules_258
  local modal_body_rule_258 strip_frame_rule_258 strip_rule_258 strip_item_rule_258
  dialog_rules_258=$(extract_flattened_css_rules "$hub_template_file" '\.session-modal-dialog')
  dialog_rule_258=$(head -1 <<< "$dialog_rules_258")
  modal_rules_258=$(extract_flattened_css_rules "$hub_template_file" '\.session-modal')
  modal_rule_258=$(grep -F -- 'position:absolute' <<< "$modal_rules_258" | head -1 || true)
  spacer_rule_258=$(extract_flattened_css_rules "$hub_template_file" '\.session-modal::after' | head -1)
  container_rules_258=$(tr '\n' ' ' < "$hub_template_file" | tr -s ' ' | grep -oE '@container \(min-width:[0-9]+px\)\{ \.session-modal-body\{[^}]*\}' || true)
  modal_body_rule_258=$(extract_flattened_css_rules "$hub_template_file" '\.session-modal-body' | head -1)
  strip_frame_rule_258=$(extract_flattened_css_rules "$hub_template_file" '\.session-strip-frame' | head -1)
  strip_rule_258=$(extract_flattened_css_rules "$hub_template_file" '\.session-strip' | head -1)
  strip_item_rule_258=$(extract_flattened_css_rules "$hub_template_file" '\.session-strip>li' | head -1)
  if [[ -z "$dialog_rule_258" || -z "$modal_rule_258" || -z "$spacer_rule_258" || -z "$modal_body_rule_258" || -z "$strip_frame_rule_258" \
      || -z "$strip_rule_258" || -z "$strip_item_rule_258" ]]; then
    record_failure "$test_name" "T25-258: 오버레이·다이얼로그·본문·프레임·칸·카드 li CSS 규칙 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qE '(^|[;{ ])max-height:100%' <<< "$dialog_rule_258"; then
    note_failure "T25-258: .session-modal-dialog 의 높이 상한이 max-height:100% 가 아님(결정 LM8 위반 — 창이 내용 높이로 자라다 가용 영역에서 멈추지 않는다)"
  fi
  if ! grep -qF -- 'margin:0 var(--dzh-wrap-gutter)' <<< "$dialog_rule_258"; then
    note_failure "T25-258: .session-modal-dialog 의 세로 margin 이 0 이 아님(결정 LM8 재개정 위반 — 자동 여백이면 창이 남는 세로 공간의 가운데로 돌아가 12.5% 지점에 걸리지 않는다)"
  fi
  if grep -qE '(^|[;{ ])height:calc\(' <<< "$dialog_rules_258"; then
    note_failure "T25-258: .session-modal-dialog 규칙에 고정 높이 선언이 남아 있음(결정 LM8 위반 — 창이 내용이 아니라 가용 높이 전부를 차지한다)"
  fi
  if grep -qF -- 'body.has-usage .session-modal-dialog{' "$hub_template_file"; then
    note_failure "T25-258: 옛 사용량 변형 규칙 body.has-usage .session-modal-dialog 가 남아 있음(결정 LM8 위반 — 사용량 여백은 오버레이의 아래 여백이 가진다)"
  fi
  if ! grep -qF -- 'overflow-y:auto' <<< "$dialog_rule_258"; then
    note_failure "T25-258: .session-modal-dialog 에 overflow-y:auto 가 없음(결정 LM8 위반 — 내용이 넘칠 때 다이얼로그가 세로 스크롤해야 한다)"
  fi
  if ! grep -qE 'display:flex;[^}]*flex-direction:column' <<< "$modal_rule_258" || ! grep -qF -- 'padding-bottom:16px' <<< "$modal_rule_258"; then
    note_failure "T25-258: .session-modal 이 세로 flex 컨테이너(display:flex + flex-direction:column)에 padding-bottom:16px 가 아님(결정 LM8 위반 — 가운데 영역의 아랫변이 정해지지 않는다)"
  fi
  if grep -qF -- 'usage-clearance' <<< "$modal_rules_258"; then
    note_failure "T25-258: .session-modal 계열 규칙이 --usage-clearance 를 읽음(결정 SC16 개정 위반 — 사용량 패널 상태가 창의 자리·최대 높이를 바꾼다. 사용량 여백은 카드 목록 .wrap 만 가진다)"
  fi
  if ! grep -qF -- 'flex:0 1 12.5%' <<< "$spacer_rule_258" || ! grep -qF -- 'order:-1' <<< "$spacer_rule_258" || ! grep -qF -- 'flex-shrink:0' <<< "$dialog_rule_258"; then
    note_failure "T25-258: 창 앞 스페이서(.session-modal::after 의 order:-1 · flex:0 1 12.5%)나 창의 flex-shrink:0 이 없음(결정 LM8 재재개정 위반 — 창이 12.5% 지점에 걸리지 않거나, 넘칠 때 스페이서가 줄지 않고 창을 깎는다)"
  fi
  if ! grep -qF -- 'container-type:inline-size' <<< "$dialog_rule_258"; then
    note_failure "T25-258: .session-modal-dialog 에 container-type:inline-size 가 없음(결정 MX8 개정 위반 — 세션 카드 폭이 창 폭을 읽지 못해 메인 카드 폭과 갈라진다)"
  fi
  if ! grep -qF -- 'flex:1 0 auto' <<< "$modal_body_rule_258"; then
    note_failure "T25-258: .session-modal-body 가 flex:1 0 auto 가 아님(결정 LM9 위반 — 넘칠 때 줄지 않으려면 shrink 0)"
  fi
  if ! grep -qF -- 'flex:1 0 auto' <<< "$strip_frame_rule_258"; then
    note_failure "T25-258: .session-strip-frame 이 flex:1 0 auto 가 아님(결정 LM9 위반 — 프레임이 줄면 칸이 자기 안에서 세로 스크롤한다)"
  fi
  if ! grep -qF -- 'flex:1 0 auto' <<< "$strip_rule_258"; then
    note_failure "T25-258: .session-strip 이 flex:1 0 auto 가 아님(결정 LM9 위반 — 칸은 스크롤 컨테이너라 shrink 0 이 아니면 내용 높이 밑으로 줄어 세로 스크롤한다, GOTCHA 8)"
  fi
  if ! grep -qE 'display:flex;[^}]*flex-direction:column' <<< "${modal_body_rule_258}"; then
    note_failure "T25-258: .session-modal-body 가 세로 flex 컨테이너(display:flex + flex-direction:column)가 아님(결정 LM9 위반 — 프레임이 높이를 이어받지 못한다)"
  fi
  if ! grep -qE 'display:flex;[^}]*flex-direction:column' <<< "${strip_frame_rule_258}"; then
    note_failure "T25-258: .session-strip-frame 이 세로 flex 컨테이너(display:flex + flex-direction:column)가 아님(결정 LM9 위반 — 칸이 높이를 이어받지 못한다)"
  fi
  if ! grep -qF -- 'flex:0 0 var(--session-card-width)' <<< "$strip_item_rule_258"; then
    note_failure "T25-258: .session-strip>li 가 flex:0 0 var(--session-card-width) 가 아님(결정 MX8 개정 위반 — 세션 카드 폭이 메인 카드 폭을 따르지 않는다)"
  fi
  if ! grep -qF -- '(min-width:610px)' <<< "$container_rules_258" || ! grep -qF -- '(min-width:942px)' <<< "$container_rules_258" \
      || [[ $(grep -oF -- '--session-card-width:max(320px, calc(' <<< "$container_rules_258" | wc -l) -ne 2 ]]; then
    note_failure "T25-258: 세션 카드 폭의 2열·3열 컨테이너 쿼리(610px·942px, 각각 --session-card-width:max(320px, calc(…)))가 없음(결정 MX8 개정 위반 — 넓은 화면의 카드 폭이 메인 카드와 갈라진다)"
  fi
  if ! grep -qF -- 'scrollbar-width:none' <<< "$strip_rule_258" || ! grep -qF -- '.session-strip::-webkit-scrollbar{display:none}' "$hub_template_file"; then
    note_failure "T25-258: 칸의 스크롤 막대 숨김(scrollbar-width:none 과 ::-webkit-scrollbar 의 display:none)이 없음(요구 3 위반 — 가로 스크롤 막대가 보인다)"
  fi

  # T25-259(개정 — 결정 LM4, docs/prps/hub-session-row-layout-and-modal-size.md; 원래는 M4 결정 MX9 의 가드였다,
  # docs/prps/hub-session-modal-cleanup.md §10.1): 카드 상세보기는 카드 목록보다 덜 보여 주지 않는다 — 모달 세션 카드
  # 안의 실행 줄 제목(.agent-run-title)은 폭 때문에 잘리지 않는다. 카드 목록 쪽의 한 줄 말줄임은 340px 고정 카드 때문에
  # 그대로 남고, 명세가 더 큰 .session-card 스코프 덮어쓰기 한 규칙만 모달을 푼다. 정 — ① .session-card .agent-run-title
  # 이 white-space:normal 이다 ② overflow-wrap:anywhere 를 갖는다(끊을 곳 없는 긴 토큰). 역 — ③ 걷힌 진행중 단계 줄의
  # 스코프 규칙이 없다(그 줄이 걷혔다 — 되살아나면 T25-263 과 같은 회귀다). 진행중 단계 해제 3선언은 그 줄과 함께 걷혔다.
  local run_title_override_rule_259
  run_title_override_rule_259=$(extract_flattened_css_rules "$hub_template_file" '\.session-card \.agent-run-title' | head -1)
  if [[ -z "$run_title_override_rule_259" ]]; then
    record_failure "$test_name" "T25-259: 모달 세션 카드의 잘림 해제 CSS 규칙(.session-card .agent-run-title) 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF -- 'white-space:normal' <<< "$run_title_override_rule_259"; then
    note_failure "T25-259: 모달 세션 카드의 .agent-run-title 에 white-space:normal 이 없음(결정 MX9 위반 — 실행 줄 제목이 한 줄 말줄임으로 잘린다)"
  fi
  if ! grep -qF -- 'overflow-wrap:anywhere' <<< "$run_title_override_rule_259"; then
    note_failure "T25-259: 모달 세션 카드의 .agent-run-title 에 overflow-wrap:anywhere 가 없음(결정 MX9 위반 — 끊을 곳 없는 긴 제목이 가로로 잘린다)"
  fi
  if [[ -n "$(extract_flattened_css_rules "$hub_template_file" '\.session-card \.tier1-active')" ]]; then
    note_failure "T25-259: 걷힌 진행중 단계 줄의 모달 스코프 규칙이 되살아남(결정 LM4 위반 — 진행중 단계 줄은 진행률 줄 앞 칩으로 접혔다)"
  fi

  # T25-260(신설, 정+역 — M1, 결정 TF1·TF14, docs/prps/hub-agent-title-and-excerpt-freshness.md §10.1): 세션 줄
  # 발췌의 출처 서술이 README 에서 코드(hub_transcript.parse_session_tail)와 어긋나지 않는다. 발췌는 꼬리의 마지막
  # 사람 프롬프트 줄에서 호스트 규칙으로 유도한 값과 last-prompt 값 중 파일에서 더 뒤의 것이고(TF1), 호스트가
  # last-prompt 를 32KiB 마다만 다시 적는 것이 그렇게 읽는 이유다(원인 토큰). 정 — ① 새 규칙 토큰(사람이 입력한 프롬프트
  # 줄) ② 원인 토큰(32KiB). 역 — ③ 옛 정의문 조각(발췌 = 마지막 프롬프트(last-prompt) 라는 한 문장 정의)이 없다. 동치 — ④
  # 스크럽 입력 상한(M1 검수 MEDIUM): README 가 알린 「앞 N자 안에서」의 N 이 hub_transcript.py 의
  # DERIVED_PROMPT_SCRUB_INPUT_MAX_CHARS 와 같다. 교차 파일 동치라 상한을 바꾸고 문서를 안 고치면 사용자에게 알린 마스킹
  # 범위가 실제와 어긋난다(README 의 쉼표 표기 2,000 은 걷어서 비교한다). 메시지는 반복문 밖의 고정 문구로 나눠 쓴다
  # (T25-240 관례와 같은 이유 — 원장 판별자 자격, T37-13).
  if ! grep -qF -- '사람이 입력한 프롬프트 줄' "$hub_readme_file"; then
    note_failure "T25-260: hub/README.md 에 발췌 새 규칙 토큰(사람이 입력한 프롬프트 줄)이 없음(결정 TF1 위반 — 발췌가 last-prompt 줄만으로 설명돼 사용자가 본 지연의 출처가 문서에 없다)"
  fi
  if ! grep -qF -- '32KiB' "$hub_readme_file"; then
    note_failure "T25-260: hub/README.md 에 발췌 지연 원인 토큰(32KiB)이 없음(결정 TF1 위반 — 호스트가 last-prompt 를 늦게 다시 적는다는 이유가 없으면 사람 줄을 먼저 읽는 규칙이 근거 없이 남는다)"
  fi
  if grep -qF -- '프롬프트(`last-prompt`)다' "$hub_readme_file"; then
    note_failure "T25-260: hub/README.md 에 옛 발췌 정의문이 남아 있음(결정 TF1 위반 — 발췌가 last-prompt 값 하나라고 다시 말하면 코드의 사람 줄 우선 규칙과 어긋난다)"
  fi
  local scrub_cap_in_code_260 scrub_cap_in_readme_260
  scrub_cap_in_code_260=$(grep -oE '^DERIVED_PROMPT_SCRUB_INPUT_MAX_CHARS = [0-9]+$' "$hub_transcript_file" | grep -oE '[0-9]+$' || true)
  scrub_cap_in_readme_260=$(grep -oE '앞 [0-9,]+자 안에서' "$hub_readme_file" | head -1 | grep -oE '[0-9,]+' | tr -d ',' || true)
  if [[ -z "$scrub_cap_in_code_260" || "$scrub_cap_in_code_260" != "$scrub_cap_in_readme_260" ]]; then
    note_failure "T25-260: hub/README.md 의 유도 경로 스크럽 입력 상한(앞 ${scrub_cap_in_readme_260:-없음}자 안에서)이 hub_transcript.py 의 DERIVED_PROMPT_SCRUB_INPUT_MAX_CHARS(${scrub_cap_in_code_260:-없음})와 다름(결정 TF4 위반 — 상한을 바꾸고 문서를 안 고치면 사용자에게 알린 마스킹 범위가 실제와 어긋난다)"
  fi

  # T25-261(신설, 교차 파일 동치 — M2, 결정 TF9·TF10·TF14, docs/prps/hub-agent-title-and-excerpt-freshness.md §9.4):
  # README 의 재개 요약 읽기 고지가 코드(hub_subagent_read.py)와 어긋나지 않는다. 다시 불러낸(재개한) 실행이 있는 세션은 부모
  # transcript 끝에서 RESUME_TITLE_SCAN_MAX_BYTES 까지 읽어 재개 요청(SendMessage)의 요약(summary)을 제목으로 쓴다(사용자 프롬프트에서
  # 파생된 글을 읽는 것이라 고지 대상이다). 동치 — ① README 가 알린 「transcript 끝에서 최대 N MiB」의 N 이 코드 상수
  # (RESUME_TITLE_SCAN_MAX_BYTES = N * 1024 * 1024)의 N 과 같다: 읽는 범위를 바꾸고 고지를 안 고치면 사용자에게 알린 범위가 실제와
  # 어긋난다. 정 — ② README 가 무엇을 읽는지(SendMessage 와 요약(summary))를 말한다: 이것이 빠지면 고지가 실제 읽기보다 좁다.
  # 메시지는 반복문 밖의 고정 문구로 나눠 쓴다(T25-240 관례와 같은 이유 — 원장 판별자 자격, T37-13). 원장 행은 ① 만 문다 — ② 는
  # 이 ID 의 다른 검사이고 그 변조로는 발화하지 않는다.
  # ② 는 고지 문단(① 의 「끝에서 최대 N MiB」 가 든 최상위 불릿)만 본다 — README 전체에서 찾으면 「알려진 한계」 문단이 같은 토큰을 말해
  # 고지에서 지워도 통과한다(M2 검수 LOW-2). 문단 경계는 줄 시작의 「- 」 불릿 또는 「#」 제목이라 줄바꿈 위치에 기대지 않는다. 한계: 문단 단위라
  # 같은 불릿 안 어느 문장의 토큰이든 센다.
  local resume_scan_mib_in_code_261 resume_scan_mib_in_readme_261 resume_notice_bullet_261
  resume_scan_mib_in_code_261=$(sed -nE 's/^RESUME_TITLE_SCAN_MAX_BYTES = ([0-9]+) \* 1024 \* 1024$/\1/p' "$hub_subagent_read_file" | head -1)
  resume_scan_mib_in_readme_261=$(grep -oE '끝에서 최대 \*\*[0-9]+MiB\*\*' "$hub_readme_file" | head -1 | grep -oE '[0-9]+' || true)
  if [[ -z "$resume_scan_mib_in_code_261" || "$resume_scan_mib_in_code_261" != "$resume_scan_mib_in_readme_261" ]]; then
    note_failure "T25-261: hub/README.md 의 재개 요약 읽기 범위(끝에서 최대 ${resume_scan_mib_in_readme_261:-없음}MiB)가 hub_subagent_read.py 의 RESUME_TITLE_SCAN_MAX_BYTES(${resume_scan_mib_in_code_261:-없음}MiB)와 다름(결정 TF9 위반 — 읽는 범위를 바꾸고 고지를 안 고치면 사용자에게 알린 범위가 실제와 어긋난다)"
  fi
  resume_notice_bullet_261=$(awk '/^(- |#)/ { if (hit) exit; bullet = "" } { bullet = bullet $0 "\n" } /끝에서 최대 \*\*[0-9]+MiB\*\*/ { hit = 1 } END { if (hit) printf "%s", bullet }' "$hub_readme_file")
  if ! grep -qF 'SendMessage' <<< "$resume_notice_bullet_261" || ! grep -qF '요약(`summary`)' <<< "$resume_notice_bullet_261"; then
    note_failure "T25-261: hub/README.md 의 고지 문단(끝에서 최대 N MiB 가 든 불릿)에 고지 토큰(SendMessage·요약(summary))이 없음(결정 TF9·TF10 위반 — 무엇을 읽는지 알리지 않으면 고지가 실제 읽기보다 좁다. 알려진 한계 문단의 같은 토큰은 세지 않는다)"
  fi

  # T25-262(신설, 정+역 — 결정 LM3, docs/prps/hub-session-row-layout-and-modal-size.md): 2단 가지(진행률·실행 줄·워크플로)의
  # 레일은 「각 가지 갈고리 + 마지막이 아니면 아래 레일」이다. 정 — ① 실행 줄·워크플로가 같은 레일 규칙(top:9px;bottom:0 —
  # 9 = 갈고리 상자(top -4, 높이 14)의 바닥선 y)을 갖고 진행률 레일은 top:17px;bottom:0 이다(17 = 갈고리 바닥선 y, display:none
  # 이 없다 — 마지막 가지만 끈다) ② 세 가지 모두 :last-child 에서 레일을 끈다(버튼의 마지막 자식은 늘 가지다 — 진행률 노드가 늘
  # 렌더되고 발췌 뒤에 오기 때문이다. 버튼 끝에 새 형제를 더하는 변경은 이 전제를 깬다). 역 — ③ DOM 순서에 기대던 옛 형제
  # 결합자(.workflow-runs ~ .session-tier1)가 없다(시각 순서와 반대 방향으로 쓰여 있던 것). bottom 이 0 인 이유: 다음 가지의 갈고리
  # 상자가 top:-4px 로 이 가지의 바닥에서 시작하므로 레일이 바닥에서 끝나야 둘이 맞닿는다(bottom:-4px 는 4px 겹쳐 그 구간만 진해진다 —
  # 헤드리스 Chrome 실측, PRP 원안 산식 정정). 원장 행은 ② 의 워크플로 쪽을 문다 — 다른 둘은 같은 규칙 안의 다른 선택자다.
  local branch_rail_rule_262 progress_rail_rule_262 last_child_rule_262
  branch_rail_rule_262=$(extract_flattened_css_rules "$hub_template_file" '\.agent-run-list::after,\.workflow-runs::after' | head -1)
  progress_rail_rule_262=$(extract_flattened_css_rules "$hub_template_file" '\.session-tier1::after' | grep -F -- 'top:17px' | head -1 || true)
  last_child_rule_262=$(extract_flattened_css_rules "$hub_template_file" '\.session-tier1:last-child::after,\.agent-run-list:last-child::after,\.workflow-runs:last-child::after' | head -1)
  if ! grep -qF -- 'top:9px;bottom:0' <<< "$branch_rail_rule_262"; then
    note_failure "T25-262: 실행 줄·워크플로 가지의 레일(.agent-run-list::after, .workflow-runs::after)이 top:9px;bottom:0 이 아님(결정 LM3 위반 — 다음 가지의 갈고리와 맞닿지 않는다)"
  fi
  if ! grep -qF -- 'top:17px;bottom:0' <<< "$progress_rail_rule_262" || grep -qF -- 'display' <<< "$progress_rail_rule_262"; then
    note_failure "T25-262: 진행률 가지의 레일(.session-tier1::after)이 top:17px;bottom:0 이 아니거나 display 를 가짐(결정 LM3 위반 — 진행률 노드가 늘 켜진 레일을 갖고 마지막일 때만 끈다)"
  fi
  if ! grep -qF -- 'display:none' <<< "$last_child_rule_262"; then
    note_failure "T25-262: 마지막 가지의 레일을 끄는 :last-child 규칙(세 가지의 ::after → display:none)이 없음(결정 LM3 위반 — 마지막 가지 아래로 레일이 삐져나온다)"
  fi
  if grep -qF -- '.workflow-runs ~ .session-tier1' "$hub_template_file"; then
    note_failure "T25-262: DOM 순서에 기대던 옛 형제 결합자(.workflow-runs ~ .session-tier1)가 되살아남(결정 LM3·LM2 위반 — 시각 순서와 반대 방향의 결합자다)"
  fi

  # T25-263(개정, 정+역 — 결정 LM4·LM12, docs/prps/hub-session-row-layout-and-modal-size.md): 진행중 단계는 별도 줄도, 진행률 줄 맨 앞
  # 칩도 아니다 — 칩은 아래 서브에이전트 실행 칩(.agent-chip)과 헷갈려 걷었다(LM12, 옛 LM5·LM6). 정 — ① renderTier1() 이 .tier1-pct
  # 문자열을 제목(escapeHtml(tier1.title))으로 시작한다. 역 — ② 칩 렌더·판정 함수 이름 ③ 칩 클래스(tier1-step) ④ 칩 전용 상수
  # (보조기술용 라벨·「커밋 전」)가 템플릿 어디에도 없다(되살아남 방지 — 이름을 문자열로 묻던 옛 가드가 개명에 눈이 멀지 않도록 옛 이름을
  # 부재로 문다) ⑤ 별도 줄 마크업이 없고 ⑥ 그 CSS 기본 규칙이 없다(TC 부활 방지 — 줄 시작 앵커로 주석 안의 언급은 세지 않는다). 메시지는
  # 반복문 밖의 고정 문구로 나눠 쓴다(T25-240 관례와 같은 이유 — 원장 판별자 자격, T37-13). 원장 행은 ③ 을 문다.
  local render_tier1_body_263
  render_tier1_body_263=$(sed -n '/^  function renderTier1(tier1){$/,/^  }$/p' "$hub_template_file")
  if [[ -z "$render_tier1_body_263" ]]; then
    record_failure "$test_name" "T25-263: renderTier1() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF -- "tier1-pct\">' + escapeHtml(tier1.title)" <<< "$render_tier1_body_263"; then
    note_failure "T25-263: renderTier1() 이 .tier1-pct 를 제목(escapeHtml(tier1.title))으로 시작하지 않음(결정 LM12 위반 — 진행률 줄 맨 앞에 다른 것이 끼었다)"
  fi
  if grep -qE 'renderTier1ActiveStep|tier1StageChipContent' "$hub_template_file"; then
    note_failure "T25-263: 단계 칩 렌더·판정 함수 이름이 되살아남(결정 LM12 위반 — 진행률 줄 맨 앞 칩이 돌아왔다)"
  fi
  if grep -qF -- 'tier1-step' "$hub_template_file"; then
    note_failure "T25-263: 단계 칩 클래스(tier1-step)가 되살아남(결정 LM12 위반 — 서브에이전트 실행 칩과 헷갈리는 칩이 돌아왔다)"
  fi
  if grep -qE 'TIER1_STAGE_SR_LABEL|STAGE_AWAITING_COMMIT' "$hub_template_file"; then
    note_failure "T25-263: 단계 칩 전용 상수(보조기술용 라벨·「커밋 전」)가 되살아남(결정 LM12 위반 — 칩을 걷으며 함께 걷은 상수다)"
  fi
  if grep -qF -- 'class="tier1-active"' "$hub_template_file"; then
    note_failure "T25-263: 별도 진행중 단계 줄 마크업(class=\"tier1-active\")이 되살아남(결정 LM4 위반 — 단계명이 별도 줄로 돌아왔다)"
  fi
  if grep -qE '^  \.tier1-active\{' "$hub_template_file"; then
    note_failure "T25-263: 진행중 단계 줄의 CSS 기본 규칙(.tier1-active)이 되살아남(결정 LM4 위반 — 걷힌 2줄 클램프(TC2)가 돌아왔다)"
  fi

  # ── docs/prps/hub-usage-panel-account.md §11.4 신설분(T25-264~268, 사용량 패널의 계정 줄) ──
  # 번호는 병합 직전 main 을 다시 세어 겹치면 다시 매긴다(PRP 머리말).

  # T25-264(신설, ★순수 계약 — T25-213 과 동형, 결정 AC8): hub_account.py 가 존재하고 파일시스템·시각
  # 접근 흔적이 없다. 이 모듈은 ~/.claude.json 본문 문자열만 받는다 — 읽기는 hub_collect.read_account_info 소관이다.
  local hub_account_file="$REPO_ROOT/hub/bin/hub_account.py"
  if [[ ! -f "$hub_account_file" ]]; then
    record_failure "$test_name" "T25-264: hub_account.py 가 존재하지 않음"
    return 1
  fi
  if grep -qE 'open\(|Path\(|time\.|os\.' "$hub_account_file"; then
    note_failure "T25-264: hub_account.py 에 순수 계약 위반 흔적(open(/Path(/time./os.)이 있음"
  fi

  # T25-265(신설, 잎 계약 — T25-214 와 동형, 결정 AC8): hub_account.py 는 어떤 허브 모듈도 임포트하지
  # 않는다(들여쓴 함수 안 임포트까지 잡는다).
  if grep -qE '^[[:space:]]*(import|from) hub_' "$hub_account_file"; then
    note_failure "T25-265: hub_account.py 가 다른 허브 모듈을 임포트함(잎 모듈 계약 위반)"
  fi

  # T25-266(신설, 결정 AC5·GOTCHA 3): renderUsagePanel 호출부는 정확히 둘이고(render()·토글 클릭 리스너) 둘 다 계정
  # 인자를 넘긴다 — 한쪽이 빠지면 첫 렌더에만 계정이 보이거나 접었다 펼칠 때 사라진다. T25-266b: 이름-값 한 쌍을 그리는
  # 함수가 값을 escapeHtml 로 거친다(결정 AC6 — 사용자 데이터(조직 이름)가 HTML 로 해석되지 않는다).
  local usage_panel_account_call_count account_pair_body
  usage_panel_account_call_count=$(grep -cF 'renderUsagePanel(snapshot.usage, snapshot.rate_limit_resets, snapshot.account)' "$hub_template_file" || true)
  if [[ "$usage_panel_account_call_count" -ne 2 ]]; then
    note_failure "T25-266: hub_template.html 의 renderUsagePanel 호출부 중 계정 인자를 넘기는 곳이 ${usage_panel_account_call_count}곳(기대 2 — 결정 AC5 위반, 한쪽이 빠지면 계정 줄이 첫 렌더에만 보이거나 토글에서 사라진다)"
  fi
  account_pair_body=$(sed -n '/^  function renderUsageAccountPair(term, value){$/,/^  }$/p' "$hub_template_file")
  if [[ -z "$account_pair_body" ]]; then
    record_failure "$test_name" "T25-266b: renderUsageAccountPair() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF -- 'escapeHtml(value)' <<< "$account_pair_body"; then
    note_failure "T25-266b: 계정 줄의 값이 escapeHtml 을 거치지 않음(결정 AC6 위반 — 조직 이름·이메일이 HTML 로 해석된다)"
  fi

  # T25-267(신설, 문서 정합, 결정 AC7·§5.9): hub/README.md·commands/hub.md 가 끄는 스위치(show_account_info)와 출처
  # (~/.claude.json)를 알리고, README 설정 표에 스위치 행이 있다 — 이메일·조직 이름이 hub.html 평문에 남는 새 노출을
  # 고지 없이 두지 않는다.
  local account_notice_file account_notice_token
  for account_notice_file in "$hub_readme_file" "$hub_command_file"; do
    for account_notice_token in 'show_account_info' '~/.claude.json'; do
      if ! grep -qF -- "$account_notice_token" "$account_notice_file"; then
        note_failure "T25-267: 계정 정보 고지 토큰($account_notice_token)이 $(basename "$account_notice_file") 에 없음(결정 AC7 위반 — 새 노출(이메일·조직 이름)의 출처와 끄는 법을 알리지 않는다)"
      fi
    done
  done
  if ! grep -qE '^\| `show_account_info` \| `true` \|' "$hub_readme_file"; then
    note_failure "T25-267: hub/README.md 설정 표에 show_account_info 행(기본값 true)이 없음(결정 AC7 위반)"
  fi

  # T25-268(신설, 경로 리터럴 — T25-217 과 동형, 결정 AC12): hub_collect.py 의 CLAUDE_GLOBAL_CONFIG_PATH 가 홈의
  # .claude.json 을 가리킨다. 단위 테스트는 이 상수를 임시·중화 경로로 바꿔 끼우므로 리터럴의 오탈자를 못 잡는다 —
  # 오타가 나면 계정 줄이 영영 안 뜨는데(파일 없음은 정상 부재라 경고도 없다) 오늘의 동작과 구분되지 않는다.
  if ! grep -qF 'Path.home() / ".claude.json"' "$hub_collect_file"; then
    note_failure "T25-268: hub_collect.py 의 CLAUDE_GLOBAL_CONFIG_PATH 가 홈의 .claude.json 을 가리키지 않음"
  fi

  # ── docs/prps/hub-live-activity.md §10.5 신설분(T25-269~274, 실행 중 활동 표시) ──
  # 번호는 병합 직전 main 을 다시 세어 겹치면 다시 매긴다(PRP 머리말).

  # T25-269(신설, 읽기 화이트리스트 — 결정 LA1·PRP §9.1·§9.3): hub_activity.py 가 호스트 기록에서 읽는 키 리터럴은
  # {type, timestamp, message, content, id, name, tool_use_id, text} 안이다 — 호스트 기록을 읽는 코드를 이 모듈 하나에 가두고, 읽는
  # 키 목록을 이 가드가 고정한다(새 키를 읽는 변경은 이 목록과 README 고지를 함께 고치는 커밋이어야 한다). 정 — `.get("…"` 첫
  # 인자와 `["…"]` 의 키 리터럴 전부가 목록 안이다(닫는 `]` 까지 맞춰야 `ToolKind = Literal["read", …]` 같은 타입 별칭이 걸리지
  # 않는다). 추출이 0건이면 공허 통과라 앵커 실패다. 역 — 명령·출력·설명 텍스트를 나르는 키(input·toolUseResult·stdout·
  # description·prompt·command)의 리터럴이 0건이다. 원장 행은 정방향(화이트리스트 밖 키)을 문다.
  local hub_activity_file="$REPO_ROOT/hub/bin/hub_activity.py"
  local activity_key_allowlist_269='content id message name text timestamp tool_use_id type'
  local activity_key_literals_269 activity_keys_outside_allowlist_269 activity_forbidden_literal_269
  if [[ ! -f "$hub_activity_file" ]]; then
    record_failure "$test_name" "T25-269: hub_activity.py 가 존재하지 않음"
    return 1
  fi
  activity_key_literals_269=$(grep -oE '\.get\("[^"]+"|\["[^"]+"\]' "$hub_activity_file" | grep -oE '"[^"]+"' | tr -d '"' | sort -u || true)
  if [[ -z "$activity_key_literals_269" ]]; then
    record_failure "$test_name" "T25-269: hub_activity.py 에서 키 접근 리터럴을 하나도 추출하지 못함 — 추출 패턴이 깨졌다"
    return 1
  fi
  activity_keys_outside_allowlist_269=$(comm -23 <(echo "$activity_key_literals_269") <(tr ' ' '\n' <<< "$activity_key_allowlist_269" | sort) | tr '\n' ' ')
  if [[ -n "$activity_keys_outside_allowlist_269" ]]; then
    note_failure "T25-269: hub_activity.py 가 화이트리스트 밖 키 리터럴(${activity_keys_outside_allowlist_269% })을 읽음(결정 LA1·§9.1 위반 — 읽는 필드가 늘면 이 목록과 README 고지를 함께 고쳐야 한다)"
  fi
  for activity_forbidden_literal_269 in input toolUseResult stdout description prompt command; do
    if grep -qF "\"${activity_forbidden_literal_269}\"" "$hub_activity_file"; then
      note_failure "T25-269: hub_activity.py 에 읽으면 안 되는 필드 리터럴(\"${activity_forbidden_literal_269}\")이 있음(결정 LA1·§9.1 위반 — 명령·출력·설명 텍스트는 어떤 형태로도 읽지 않는다)"
    fi
  done

  # T25-270(신설, 출력 구조 — 결정 LA3·PRP §9.2·§9.3): 스냅샷으로 나가는 활동 타입 셋(ToolKindCounts·BackgroundOutputView·
  # SubagentActivity)의 필드 주석에 자유 문자열(str)이 없다 — 닫힌 리터럴(ToolKind)·정수·None·셋 자신만 허용돼 명령·출력·경로·도구
  # 이름이 뷰에 실릴 길이 없다. 필드 줄(`    이름: 형`)만 보고 줄 끝 주석은 뗀다. 타입 힌트를 재귀로 걷는 단위 검사
  # (tests/hub/test_hub_activity.py ActivityContractTest)와 짝이다. 필드 줄이 하나도 안 잡히면 공허 통과라 앵커 실패다.
  local activity_contract_fields_270
  activity_contract_fields_270=$(awk '
    /^class (ToolKindCounts|BackgroundOutputView|SubagentActivity):/ { inside = 1; next }
    /^[^ #]/ { inside = 0 }
    inside && /^    [A-Za-z_][A-Za-z0-9_]*:/ { sub(/#.*/, ""); print }
  ' "$hub_activity_file")
  if [[ -z "$activity_contract_fields_270" ]]; then
    record_failure "$test_name" "T25-270: hub_activity.py 의 활동 계약 타입 셋(ToolKindCounts·BackgroundOutputView·SubagentActivity) 필드 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if grep -qE '(^|[^A-Za-z0-9_])str([^A-Za-z0-9_]|$)' <<< "$activity_contract_fields_270"; then
    note_failure "T25-270: 활동 계약 타입의 필드에 자유 문자열(str) 주석이 있음(결정 LA3·§9.2 위반 — 명령·출력·경로·도구 이름이 hub.html 에 실릴 수 있다)"
  fi

  # T25-271(신설, 지금 시각 없음 — 결정 LA11·PRP §9.3): hub_activity.py 의 값은 파일 내용과 stat 의 함수다. 지금 시각을 받거나
  # 읽으면 아무 일이 없어도 수집마다 값이 바뀌어 snapshot_content_key 의 쓰기 억제(D2)가 깨진다. 토큰 now_ms·time.·.now( 가 주석·
  # docstring 까지 0건이다. 시각이 필요한 판정은 hub_session 이 정적 시각(stall_suspect_at_ms)으로 채워 내보낸다.
  if grep -qE 'now_ms|time\.|\.now\(' "$hub_activity_file"; then
    note_failure "T25-271: hub_activity.py 에 지금 시각 토큰(now_ms 또는 time. 또는 .now()이 있음(결정 LA11 위반 — 활동 값이 수집마다 바뀌어 hub.html 쓰기 억제가 무력해진다)"
  fi

  # T25-272(신설, 배선 — 결정 LA1·LA8·LA13): ① hub_subagent_read.py 에 read_live_activity 정의가 있다 ② 그 시그니처와
  # hub_collect._read_session_annotations 의 호출에 record_prompt_excerpt 가 없다(SL7 의 함정 — 활동은 프롬프트 발췌가 아니라
  # 그 스위치로 게이팅하지 않는다. 걸면 스위치를 끈 사용자에게서만 기능이 조용히 사라진다) ③ hub_session.summarize_agent_runs
  # 본문에 도는 실행에만 활동을 싣는 술어가 있다(끝난 실행·좀비에 활동 줄이 붙는 것을 막는다). 범위 추출이 비면 앵커 실패다.
  # 원장 행은 ② 의 호출 쪽을 문다.
  local live_activity_signature_272 live_activity_call_272 summarize_agent_runs_body_272
  if ! grep -qF 'def read_live_activity(' "$hub_subagent_read_file"; then
    note_failure "T25-272: hub_subagent_read.py 에 def read_live_activity( 정의가 없음(결정 LA1 위반 — 활동 읽기의 진입점이 사라졌다)"
  fi
  live_activity_signature_272=$(sed -n '/^def read_live_activity($/,/^) ->/p' "$hub_subagent_read_file")
  live_activity_call_272=$(sed -n '/hub_subagent_read\.read_live_activity($/,/^    )$/p' "$hub_collect_file")
  summarize_agent_runs_body_272=$(sed -n '/^def summarize_agent_runs(/,/^def [a-z_]*(/p' "$hub_session_file")
  if [[ -z "$live_activity_signature_272" || -z "$live_activity_call_272" || -z "$summarize_agent_runs_body_272" ]]; then
    record_failure "$test_name" "T25-272: read_live_activity 시그니처·호출과 summarize_agent_runs 본문 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if grep -qF 'record_prompt_excerpt' <<< "$live_activity_signature_272"; then
    note_failure "T25-272: read_live_activity 시그니처에 record_prompt_excerpt 가 있음(결정 LA13 위반 — SL7 의 함정, 활동 표시를 발췌 스위치로 게이팅한다)"
  fi
  if grep -qF 'record_prompt_excerpt' <<< "$live_activity_call_272"; then
    note_failure "T25-272: _read_session_annotations 의 read_live_activity 호출에 record_prompt_excerpt 를 넘김(결정 LA13 위반 — SL7 의 함정, 활동 표시를 발췌 스위치로 게이팅한다)"
  fi
  if ! grep -qF 'if is_running and found is not None' <<< "$summarize_agent_runs_body_272"; then
    note_failure "T25-272: summarize_agent_runs 에 도는 실행에만 활동을 싣는 술어(if is_running and found is not None)가 없음(결정 LA8 위반 — 끝난 실행·좀비에도 활동 줄이 붙는다)"
  fi

  # T25-273(신설, 교차 파일 동치 — 결정 LA2·LA8·LA13, T25-261 과 같은 모양): hub/README.md 가 알린 수치가 코드 상수와 같다.
  # ① 활동 읽기 범위 — README 의 「끝 **N MiB**」(서브에이전트·transcript 항목·알려진 한계 어디든)가 가리키는 값이 단 하나이고
  # hub_activity.py 의 ACTIVITY_WINDOW_BYTES 를 MiB 로 환산한 값과 같다. ② 「새 기록 없음」 기준 — README 의 「**N분** 넘게 비」가
  # SUBAGENT_STALL_SUSPECT_AFTER_MS 를 분으로 환산한 값과 같다. ③ 역 — 옛 약속(「대화 기록(agent-<id>.jsonl)은 읽지 않는다」)이
  # README 에 남아 있지 않다(코드가 도는 실행의 기록 끝을 읽는데 고지가 안 읽는다고 말하면 사용자에게 한 약속이 거짓이다).
  # T25-261 이 「끝에서 최대 **N MiB**」(재개 요약 읽기)를 물므로 이 가드의 「끝 **N MiB**」 형태는 그것과 겹치지 않게 골랐다
  # (서로의 첫 일치를 흔들지 않는다). 메시지는 고정 문구다(원장 판별자 자격, T37-13). 원장 행은 ① 만 문다.
  local bytes_per_mib=$((1024 * 1024)) milliseconds_per_minute=60000
  local activity_window_mib_in_code_273 activity_window_mib_in_readme_273 stall_minutes_in_code_273 stall_minutes_in_readme_273
  activity_window_mib_in_code_273=$(read_python_product_constant "$hub_activity_file" ACTIVITY_WINDOW_BYTES "$bytes_per_mib")
  activity_window_mib_in_readme_273=$(grep -oE '끝 \*\*[0-9]+MiB\*\*' "$hub_readme_file" | grep -oE '[0-9]+' | sort -u | tr '\n' ' ' | sed 's/ $//' || true)
  if [[ -z "$activity_window_mib_in_code_273" || "$activity_window_mib_in_code_273" != "$activity_window_mib_in_readme_273" ]]; then
    note_failure "T25-273: hub/README.md 의 활동 읽기 범위(끝 ${activity_window_mib_in_readme_273:-없음}MiB)가 hub_activity.py 의 ACTIVITY_WINDOW_BYTES(${activity_window_mib_in_code_273:-없음}MiB)와 다름(결정 LA2 위반 — 읽는 범위를 바꾸고 고지를 안 고치면 사용자에게 알린 범위가 실제와 어긋난다)"
  fi
  stall_minutes_in_code_273=$(read_python_product_constant "$hub_activity_file" SUBAGENT_STALL_SUSPECT_AFTER_MS "$milliseconds_per_minute")
  stall_minutes_in_readme_273=$(grep -oE '\*\*[0-9]+분\*\* 넘게 비' "$hub_readme_file" | grep -oE '[0-9]+' | sort -u | tr '\n' ' ' | sed 's/ $//' || true)
  if [[ -z "$stall_minutes_in_code_273" || "$stall_minutes_in_code_273" != "$stall_minutes_in_readme_273" ]]; then
    note_failure "T25-273: hub/README.md 의 「새 기록 없음」 기준(${stall_minutes_in_readme_273:-없음}분 넘게 비어)이 hub_activity.py 의 SUBAGENT_STALL_SUSPECT_AFTER_MS(${stall_minutes_in_code_273:-없음}분)와 다름(결정 LA8 위반 — 임계를 바꾸고 고지를 안 고치면 사용자에게 알린 기준이 실제와 어긋난다)"
  fi
  if grep -qF '대화 기록(`agent-<id>.jsonl`)은 **읽지 않는다.**' "$hub_readme_file"; then
    note_failure "T25-273: hub/README.md 에 옛 「대화 기록은 읽지 않는다」 약속이 남아 있음(결정 LA1 위반 — 코드는 도는 실행의 기록 끝을 읽는데 고지가 안 읽는다고 말한다)"
  fi

  # T25-274(신설, 템플릿 정합 — 결정 LA8·LA9, T25-219 와 같은 모양): ① 「새 기록 없음」 규칙(.agent-run-activity-stall{)에 # 색
  # 리터럴·animation·box-shadow 가 없다 — 새 색 토큰 0·애니메이션 0, 소식 없음 배지와 같은 --attention 글자색뿐이다. ② 문구 표
  # 둘(TOOL_KIND_NOUN·TOOL_KIND_PENDING_LABEL)의 키 집합이 파이썬 hub_activity.TOOL_KINDS 와 같다 — 양쪽에서 뽑아 대조한다(종류를
  # 하나 더하고 한쪽 표를 빠뜨리면 그 종류의 활동 줄이 undefined 로 찍힌다) ③ renderAgentRunRow 가 renderAgentRunActivity( 를
  # 부른다 — 활동 줄이 실행 줄에 붙는 유일한 경로다. 규칙·함수 범위 추출이 비면 앵커 실패다. 원장 행은 ② 를 문다.
  local activity_stall_rule_274 render_agent_run_row_body_274 tool_kinds_in_code_274 tool_kind_noun_keys_274 tool_kind_pending_keys_274
  activity_stall_rule_274=$(extract_flattened_css_rules "$hub_template_file" '\.agent-run-activity-stall')
  render_agent_run_row_body_274=$(sed -n '/^  function renderAgentRunRow(run, nowMs){$/,/^  }$/p' "$hub_template_file")
  if [[ -z "$activity_stall_rule_274" || -z "$render_agent_run_row_body_274" ]]; then
    record_failure "$test_name" "T25-274: .agent-run-activity-stall 규칙·renderAgentRunRow() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if grep -qE '#|animation|box-shadow' <<< "$activity_stall_rule_274"; then
    note_failure "T25-274: .agent-run-activity-stall 규칙에 # 색 리터럴·animation·box-shadow 가 있음(결정 LA8 위반 — 새 기록 없음은 --attention 글자색만 쓴다)"
  fi
  tool_kinds_in_code_274=$(grep -oE '^TOOL_KINDS[^=]*= \([^)]*\)' "$hub_activity_file" | head -1 | grep -oE '"[a-z]+"' | tr -d '"' | sort | tr '\n' ',' || true)
  tool_kind_noun_keys_274=$(grep -oE 'TOOL_KIND_NOUN = \{[^}]*\}' "$hub_template_file" | head -1 | grep -oE '[a-z]+:' | tr -d ':' | sort | tr '\n' ',' || true)
  tool_kind_pending_keys_274=$(grep -oE 'TOOL_KIND_PENDING_LABEL = \{[^}]*\}' "$hub_template_file" | head -1 | grep -oE '[a-z]+:' | tr -d ':' | sort | tr '\n' ',' || true)
  if [[ -z "$tool_kinds_in_code_274" || "$tool_kinds_in_code_274" != "$tool_kind_noun_keys_274" || "$tool_kinds_in_code_274" != "$tool_kind_pending_keys_274" ]]; then
    note_failure "T25-274: TOOL_KIND_NOUN(${tool_kind_noun_keys_274:-없음})·TOOL_KIND_PENDING_LABEL(${tool_kind_pending_keys_274:-없음})의 키 집합이 hub_activity.TOOL_KINDS(${tool_kinds_in_code_274:-없음})와 다름(결정 LA3 위반 — 한쪽 표에 없는 종류의 활동 줄이 깨진다)"
  fi
  if ! grep -qF 'renderAgentRunActivity(' <<< "$render_agent_run_row_body_274"; then
    note_failure "T25-274: renderAgentRunRow() 가 renderAgentRunActivity( 를 부르지 않음(결정 LA9 위반 — 활동 줄이 실행 줄에 붙지 않는다)"
  fi

  # T25-275(신설, docs/prps/harness-versioning.md 결정 UN1): 새 릴리스 확인(hub_release_read.py)의 git 실행이 ① argv 리스트다 —
  # subprocess.Popen( 바로 다음 줄이 `[` 로 시작하는 리스트 리터럴이다(셸 문자열 조립 금지, rules/python/security.md) ② shell= 인자가
  # 어디에도 없다 ③ stdin 을 닫고(DEVNULL) 대화형 질문을 막는다(GIT_TERMINAL_PROMPT_ENV_NAME 에 "0") ④ 원격에 쓰기를 하는 git 하위
  # 명령(fetch·pull·push·clone)을 부르지 않는다 — 저장소를 바꾸지 않는 ls-remote 한 가지만 쓴다는 설계(UN1)의 기계적 강제. T25-61·
  # T25-114 와 같은 정적 계열이다. 원장 행은 ① 만 문다(argv 를 셸 문자열로 바꾸는 변조).
  local hub_release_read_file_275="$REPO_ROOT/hub/bin/hub_release_read.py"
  local popen_next_lines_275
  popen_next_lines_275=$(grep -A1 'subprocess\.\(Popen\|run\|call\|check_output\)(' "$hub_release_read_file_275" | grep -v 'subprocess\.' | grep -v '^--$' || true)
  if [[ -z "$popen_next_lines_275" ]] || grep -qvE '^[[:space:]]*\[' <<< "$popen_next_lines_275"; then
    note_failure "T25-275: hub_release_read.py 의 subprocess 호출 인자가 argv 리스트 리터럴이 아님(셸 문자열 조립 의심)"
  fi
  if grep -qE 'shell[[:space:]]*=' "$hub_release_read_file_275"; then
    note_failure "T25-275: hub_release_read.py 에 shell= 인자가 있음(셸 경유 금지)"
  fi
  if ! grep -qF 'stdin=subprocess.DEVNULL' "$hub_release_read_file_275" || ! grep -qE 'GIT_TERMINAL_PROMPT_ENV_NAME: "0"' "$hub_release_read_file_275"; then
    note_failure "T25-275: hub_release_read.py 가 stdin 을 닫지 않거나 GIT_TERMINAL_PROMPT=0 을 걸지 않음(서버에는 제어 터미널이 없어 질문이 뜨면 영원히 막힌다)"
  fi
  if grep -qE '"(fetch|pull|push|clone)"' "$hub_release_read_file_275"; then
    note_failure "T25-275: hub_release_read.py 가 저장소를 바꾸는 git 하위 명령을 부름(결정 UN1 위반 — ls-remote 만 쓴다)"
  fi

  # T25-276(신설, 결정 UN10): hub/README.md 가 원격 확인의 네트워크 호출을 고지하고 끄는 수단을 적는다 — 서버가 6시간마다
  # git ls-remote --tags 를 실행한다는 사실·스위치 이름(update_check_enabled)·기록 파일(release_check.json)이 문서에 있다.
  # 코드는 네트워크 호출을 기본으로 켜 두는데(D5) 고지가 없으면 사용자에게 한 약속이 비는 것이다. commands/hub.md 도 /hub status
  # 필드를 적는다. 원장 행은 스위치 이름을 문다.
  local release_notice_token_276
  for release_notice_token_276 in 'update_check_enabled' 'release_check.json' 'git ls-remote --tags'; do
    if ! grep -qF -- "$release_notice_token_276" "$hub_readme_file"; then
      note_failure "T25-276: hub/README.md 에 새 버전 알림 고지 토큰(${release_notice_token_276})이 없음(결정 UN10 위반 — 기본 켜짐인 네트워크 호출의 고지와 끄는 수단)"
    fi
  done
  if ! grep -qF 'release_check' "$hub_command_file"; then
    note_failure "T25-276: commands/hub.md 의 /hub status 필드 설명에 release_check 가 없음(결정 UN10)"
  fi

  # T25-277(신설, 결정 UN8 — 갱신 불변식 H1⁗ 개정): hub_template.html 맨 위 데이터 계약 주석(DZH:HUB 데이터 계약 ~ 첫 `-->`)이 새
  # 정적 노드 둘(#dzh-harness-version·#dzh-update)을 폴링이 속성·textContent 단위로만 갱신하는 노드로 등재한다. 등재가 빠지면 다음
  # 사람이 이 노드를 교체 대상으로 오해해 복사 피드백 상태를 지운다. 원장 행은 #dzh-update 를 문다.
  local data_contract_comment_277
  data_contract_comment_277=$(sed -n '/DZH:HUB 데이터 계약/,/^-->/p' "$hub_template_file")
  if [[ -z "$data_contract_comment_277" ]]; then
    record_failure "$test_name" "T25-277: hub_template.html 데이터 계약 주석 추출 실패 — 앵커(DZH:HUB 데이터 계약 ~ -->)가 깨졌다"
    return 1
  fi
  if ! grep -qF '#dzh-update' <<< "$data_contract_comment_277" || ! grep -qF '#dzh-harness-version' <<< "$data_contract_comment_277"; then
    note_failure "T25-277: hub_template.html 데이터 계약 주석(불변식 H1⁗)에 #dzh-harness-version·#dzh-update 등재가 없음(결정 UN8)"
  fi

  # T25-278(신설, 결정 UN9): 복사 IIFE 가 isServed 가드 바깥에 있다 ① 복사 IIFE 블록(UPDATE_COPIED_CLASS 선언부터 그 IIFE 의 끝까지)의
  # 코드 줄(주석 제외)에 isServed 가 없다 ② 그 IIFE 의 클릭 리스너가 렌더 IIFE 의 `if(!isServed){` 조기 반환 줄보다 앞에 있다 — 뒤로
  # 옮기면 file:// 모드에서 복사가 조용히 죽는다(GOTCHA 4 선례). 블록·앵커 추출이 비면 앵커 실패다. 원장 행은 ① 을 문다.
  local copy_iife_code_278 copy_listener_line_278 first_guard_line_278
  copy_iife_code_278=$(awk '/var UPDATE_COPIED_CLASS = /{inside=1} inside && /^\}\)\(\);$/{exit} inside{print}' "$hub_template_file" | grep -vE '^[[:space:]]*//' || true)
  copy_listener_line_278=$(grep -n "updateButton.addEventListener('click'" "$hub_template_file" | head -1 | cut -d: -f1)
  first_guard_line_278=$(grep -n '^  if(!isServed){$' "$hub_template_file" | head -1 | cut -d: -f1)
  if [[ -z "$copy_iife_code_278" || -z "$copy_listener_line_278" || -z "$first_guard_line_278" ]]; then
    record_failure "$test_name" "T25-278: 복사 IIFE·클릭 리스너·렌더 IIFE 의 if(!isServed){ 앵커 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if grep -qF 'isServed' <<< "$copy_iife_code_278"; then
    note_failure "T25-278: 복사 IIFE 의 코드가 isServed 를 참조함(결정 UN9 위반 — file:// 모드에서 복사가 죽는다)"
  fi
  if [[ "$copy_listener_line_278" -ge "$first_guard_line_278" ]]; then
    note_failure "T25-278: 복사 클릭 리스너(${copy_listener_line_278}행)가 렌더 IIFE 의 if(!isServed){ 조기 반환(${first_guard_line_278}행) 뒤에 있음(결정 UN9 위반)"
  fi

  # T25-279(신설, 결정 UN1·모듈 경계): 새 모듈의 임포트 방향이 지켜진다 ① hub_release.py(★순수 잎)는 어떤 허브 모듈도 임포트하지
  # 않는다 ② hub_release_read.py 는 hub_collect·hub_server 를 임포트하지 않는다(그 둘이 이 모듈을 부르므로 순환이 된다).
  # 원장 행은 ② 를 문다.
  if grep -qE '^(import|from)[[:space:]]+hub' "$REPO_ROOT/hub/bin/hub_release.py"; then
    note_failure "T25-279: hub_release.py(잎 모듈)가 허브 모듈을 임포트함(순환 방지 계약 위반)"
  fi
  if grep -qE '^(import|from)[[:space:]].*hub_(collect|server)\b' "$hub_release_read_file_275"; then
    note_failure "T25-279: hub_release_read.py 가 hub_collect·hub_server 를 임포트함(순환 의존)"
  fi

  # T25-280(신설, 정 — 결정 AW1~AW4·AW7, docs/prps/hub-approval-wait-badge.md): 승인 대기 표지의 배선. ① hub_parse.py 의 Tier1Snapshot 이
  # `is_approval_step_active: bool = False` 사실 필드를 선언한다 ② isAwaitingApproval() 본문이 그 필드(`tier1.is_approval_step_active`)를
  # 읽는다(서버 필드만 개명해도 화면이 눈먼 채 항상 false 가 되지 않게 — 개명하면 정적 가드가 눈이 먼다) ③ renderSessionContent() 의 첫 줄
  # 구간(T25-127 과 같은 awk 추출 — class="session-line" 뒤 첫 </div> 앞)에 renderApprovalWaitBadge(session) 호출이 있다(호출이 식별 줄·
  # 진행률 줄로 옮겨지거나 지워지면 표지가 첫 줄에서 사라진다) ④ `.badge.approval-wait{` 규칙이 있고 그 본문에 animation 이 없다(halo·pulse 금지 —
  # glow 는 working 전용, T25-190 계열) ⑤ hub/README.md 「화면 배치」에 승인 대기 서술이 있다(T25-36·T25-152 관례). 메시지는 반복문 밖의 고정
  # 문구로 나눠 쓴다(T25-240 관례와 같은 이유 — 원장 판별자 자격, T37-13). 원장 행은 ③ 을 문다.
  local hub_parse_file_280="$REPO_ROOT/hub/bin/hub_parse.py"
  local awaiting_body_280 approval_badge_body_280 session_content_body_280 first_line_segment_280 approval_rule_280
  if ! grep -qF 'is_approval_step_active: bool = False' "$hub_parse_file_280"; then
    note_failure "T25-280: hub_parse.py 에 is_approval_step_active: bool = False 선언이 없음(결정 AW2 위반 — 승인 단계 진행중 사실이 스냅샷에 실리지 않는다)"
  fi
  awaiting_body_280=$(sed -n '/^  function isAwaitingApproval(session){$/,/^  }$/p' "$hub_template_file")
  if [[ -z "$awaiting_body_280" ]]; then
    record_failure "$test_name" "T25-280: isAwaitingApproval() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  if ! grep -qF 'tier1.is_approval_step_active' <<< "$awaiting_body_280"; then
    note_failure "T25-280: isAwaitingApproval() 이 서버 사실 tier1.is_approval_step_active 를 읽지 않음(결정 AW2 위반 — 필드 이름이 서버와 어긋나면 표지가 영영 안 뜬다)"
  fi
  approval_badge_body_280=$(sed -n '/^  function renderApprovalWaitBadge(session){$/,/^  }$/p' "$hub_template_file")
  session_content_body_280=$(sed -n '/function renderSessionContent(session){/,/^  }$/p' "$hub_template_file")
  if [[ -z "$approval_badge_body_280" || -z "$session_content_body_280" ]]; then
    record_failure "$test_name" "T25-280: renderApprovalWaitBadge()·renderSessionContent() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  first_line_segment_280=$(awk '
    /class="session-line"/ { in_range=1 }
    in_range {
      if (match($0, /<\/div>/)) { print substr($0, 1, RSTART-1); exit }
      print
    }
  ' <<< "$session_content_body_280")
  if ! grep -qF 'renderApprovalWaitBadge(session)' <<< "$first_line_segment_280"; then
    note_failure "T25-280: 승인 대기 표지 호출이 첫 줄(session-line) 구성 안에 없음(결정 AW3 위반 — 표지가 상태 배지 뒤에서 사라지거나 다른 줄로 옮겨졌다)"
  fi
  approval_rule_280=$(extract_flattened_css_rules "$hub_template_file" '\.badge\.approval-wait' | head -1)
  if [[ -z "$approval_rule_280" ]]; then
    note_failure "T25-280: .badge.approval-wait 규칙이 없음(결정 AW4 위반 — 표지가 스타일 없이 그려진다)"
  elif grep -qF 'animation' <<< "$approval_rule_280"; then
    note_failure "T25-280: .badge.approval-wait 규칙에 animation 이 있음(결정 AW4 위반 — halo·pulse 는 working 전용이다)"
  fi
  if ! grep -qF '승인 대기' "$hub_readme_file"; then
    note_failure "T25-280: hub/README.md 에 승인 대기 설명이 없음(결정 AW7 위반 — 화면 배치 문서가 표지를 알리지 않는다)"
  fi

  # T25-281(신설, 역 — 결정 AW5, docs/prps/hub-approval-wait-badge.md): 승인 대기 표지는 결정 LM12 가 걷은 단계 칩의 부활이 아니다.
  # ① renderApprovalWaitBadge() 본문에 agent-chip 이 없다(서브에이전트 실행 칩과 같은 모양·클래스를 쓰지 않는다) ② renderTier1() 본문에
  # approval-wait·renderApprovalWaitBadge 가 없다(표지는 첫 줄에 살지 진행률 줄에 되돌아가지 않는다) ③ 템플릿에 따옴표로 닫힌 정확한
  # 리터럴 \'승인\' 이 없다 — 화면이 단계 이름으로 승인을 다시 판정하지 않는다(판정은 서버 사실 하나, AW2. 라벨 \'승인 대기\' 는 걸리지
  # 않는다). 메시지는 반복문 밖의 고정 문구다. 원장 행은 ① 을 문다.
  if grep -qF 'agent-chip' <<< "$approval_badge_body_280"; then
    note_failure "T25-281: 승인 대기 표지가 실행 칩 클래스(agent-chip)를 씀(결정 AW5 위반 — 걷힌 단계 칩과 같은 혼동이 돌아온다)"
  fi
  if grep -qE 'approval-wait|renderApprovalWaitBadge' <<< "$render_tier1_body_263"; then
    note_failure "T25-281: renderTier1() 이 승인 대기 표지를 그림(결정 AW3·AW5 위반 — 표지가 진행률 줄로 옮겨졌다)"
  fi
  if grep -qF "'승인'" "$hub_template_file"; then
    note_failure "T25-281: 템플릿에 단계 이름 리터럴 '승인' 이 있음(결정 AW2 위반 — 화면이 단계 이름으로 승인 대기를 다시 판정한다)"
  fi

  finish_group "$test_name"
}

# T26: 상시 컨텍스트 예산 래칫 (결함 3) — 실측이 상수를 넘지 않는지, README.md 의 두
# 선언 지점이 상수와 일치하는지 확인한다. 새 메커니즘을 만들지 않고 기존 패턴(T22-138 의
# 상수 vs 실측 비교 · T25 의 문서·상수 정합성)을 그대로 복제한다.
test_always_on_context_budget() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T26"
  local test_desc="상시 컨텍스트 예산 래칫 (T26-1~T26-3)"
  log_test_name "$test_name" "$test_desc"

  # T26-1: 실측이 예산 상수를 넘지 않는다.
  local actual_bytes
  actual_bytes=$(cat "$REPO_ROOT/CLAUDE.md" "$REPO_ROOT/rules/README.md" "$REPO_ROOT/rules/common/"*.md \
    "$REPO_ROOT/rules/workflow/"*.md | wc -c | tr -d ' ')
  if [[ "$actual_bytes" -gt "$ALWAYS_ON_CONTEXT_BUDGET_BYTES" ]]; then
    note_failure "T26-1: 실측 ${actual_bytes}B > 예산 ${ALWAYS_ON_CONTEXT_BUDGET_BYTES}B"
  fi

  # T26-2·T26-3: README.md 의 두 선언 지점(상시 컨텍스트 절·rules 구성 절)이 상수·실측치와
  # 일치. 문구는 "<숫자,콤마>B" 형태로 고정돼 있어야 grep -oE 로 기계 추출할 수 있다(T25
  # 문서·상수 정합성 패턴의 복제).
  local readme_file="$REPO_ROOT/README.md"
  local declared_bytes_1 declared_bytes_2 declared_match_count

  # T26-2 선행 조건: 매칭이 정확히 2건이어야 한다 — head -1/tail -1 만으로는 두 선언 중
  # 하나가 지워져도 남은 하나를 양쪽으로 읽어 통과해버린다(검수 M2 지적).
  declared_match_count=$(grep -oE '실측 [0-9,]+B' "$readme_file" | wc -l | tr -d ' ')
  if [[ "$declared_match_count" -ne 2 ]]; then
    note_failure "T26-2: README.md 에 '실측 <n>B' 패턴이 정확히 2건이어야 하는데 ${declared_match_count}건 발견됨"
  fi

  declared_bytes_1=$(grep -oE '실측 [0-9,]+B' "$readme_file" | head -1 | grep -oE '[0-9,]+' | tr -d ',')
  if [[ -z "$declared_bytes_1" ]]; then
    note_failure "T26-2: README.md 상시 컨텍스트 절에서 '실측 <n>B' 패턴을 찾지 못함"
  else
    if [[ "$declared_bytes_1" -ne "$ALWAYS_ON_CONTEXT_BUDGET_BYTES" ]]; then
      note_failure "T26-2: README.md 첫 선언=${declared_bytes_1}B, 상수=${ALWAYS_ON_CONTEXT_BUDGET_BYTES}B"
    fi
    # 상수와만 비교하면 상수 자체가 실측과 따로 노는 경우를 못 잡는다 — 이 그룹이 방금 구한
    # actual_bytes(T26-1) 와도 직접 비교한다(검수 M2 지적).
    if [[ "$declared_bytes_1" -ne "$actual_bytes" ]]; then
      note_failure "T26-2: README.md 첫 선언=${declared_bytes_1}B, 실측=${actual_bytes}B"
    fi
  fi

  declared_bytes_2=$(grep -oE '실측 [0-9,]+B' "$readme_file" | tail -1 | grep -oE '[0-9,]+' | tr -d ',')
  if [[ -z "$declared_bytes_2" ]]; then
    note_failure "T26-3: README.md rules 구성 절에서 '실측 <n>B' 패턴을 찾지 못함"
  elif [[ "$declared_bytes_2" -ne "$ALWAYS_ON_CONTEXT_BUDGET_BYTES" ]]; then
    note_failure "T26-3: README.md 두 번째 선언=${declared_bytes_2}B, 상수=${ALWAYS_ON_CONTEXT_BUDGET_BYTES}B"
  fi

  finish_group "$test_name"
}

# T30(재발 방지책 — PRP audit-remediation R2 §7 충돌1, 감사 full-audit-2026-08.md install.sh:12
# CONFIRMED): RULES_FILE_COUNT·AGENTS_FILE_COUNT 는 COMMANDS_FILE_COUNT(T22-138)·
# HUB_FILE_COUNT(T25-1)와 달리 실제 소스 파일 수와의 파리티 검사가 없었다 — 여기서 그 형태를
# 복제한다. 소스측 상수 대조이므로(§7 충돌1: 대상 디렉토리 총량 계수와는 무관한 결론) 설치를
# 거치지 않고 레포의 rules/·agents/ 를 직접 센다.
test_rules_and_agents_file_count_parity() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T30"
  local test_desc="RULES_FILE_COUNT·AGENTS_FILE_COUNT 소스 파일 수 파리티"
  log_test_name "$test_name" "$test_desc"

  local declared_rules declared_agents actual_rules actual_agents
  declared_rules=$(grep -oE '^readonly RULES_FILE_COUNT=[0-9]+' "$INSTALL_SCRIPT" | grep -oE '[0-9]+$')
  declared_agents=$(grep -oE '^readonly AGENTS_FILE_COUNT=[0-9]+' "$INSTALL_SCRIPT" | grep -oE '[0-9]+$')
  actual_rules=$(find "$REPO_ROOT/rules" -type f | wc -l | tr -d ' ')
  actual_agents=$(ls "$REPO_ROOT/agents"/* | wc -l | xargs echo)

  if ! assert_equals "$actual_rules" "$declared_rules" "RULES_FILE_COUNT 일치"; then
    note_failure "T30-1: RULES_FILE_COUNT=$declared_rules, 실제 파일 수=$actual_rules"
  fi
  if ! assert_equals "$actual_agents" "$declared_agents" "AGENTS_FILE_COUNT 일치"; then
    note_failure "T30-2: AGENTS_FILE_COUNT=$declared_agents, 실제 파일 수=$actual_agents"
  fi

  finish_group "$test_name"
}

# T27: manifest v2 해시 대장 + 툼스톤 삭제 경로 (결함 4·5, D-1~D-5 전 판정)
# CODING_HARNESS_REMOVALS_FILE 시임으로 레포의 실제 removals.txt(docs/prps/dashboard-into-hub.md
# HD1 이후 4줄을 담고 있다) 대신 임시 툼스톤 목록을 주입한다 — HOME 치환과 같은 성격의
# 테스트 전용 훅.
#
# 한계(비망라, A6 회귀 T27-11~T27-13, tests-hardening PRP §0-3·§9): 메타문자 재현은
# "re[po]"·"ta[rget]" 두 조합만 실측했고 다른 ERE/글롭 메타문자(`*`·`?`·`+` 등)나 각
# 위치의 조합을 전수 검증하지 않는다. 검수 회차에 14조합까지 이탈 없음이 확인됐으나
# 그것도 표본이다 — 전수 증명이 아니다.
test_manifest_ledger_and_removals() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T27"
  local test_desc="v2 해시 대장 · 툼스톤 삭제 경로 (D-1~D-5)"
  log_test_name "$test_name" "$test_desc"

  local sandbox_ledger sandbox_d1 sandbox_d2 sandbox_d3 sandbox_d4 sandbox_d5a sandbox_d5b \
    sandbox_dry sandbox_empty sandbox_stale repo_copy
  sandbox_ledger=$(mktemp -d); sandbox_d1=$(mktemp -d); sandbox_d2=$(mktemp -d)
  sandbox_d3=$(mktemp -d); sandbox_d4=$(mktemp -d); sandbox_d5a=$(mktemp -d)
  sandbox_d5b=$(mktemp -d); sandbox_dry=$(mktemp -d); sandbox_empty=$(mktemp -d)
  sandbox_stale=$(mktemp -d); repo_copy=$(mktemp -d)
  register_cleanup_path "$sandbox_ledger" "$sandbox_d1" "$sandbox_d2" "$sandbox_d3" "$sandbox_d4" \
    "$sandbox_d5a" "$sandbox_d5b" "$sandbox_dry" "$sandbox_empty" "$sandbox_stale" "$repo_copy"

  # ---- T27-1: v3 대장 항목 수 == 관리 파일 수(rules+agents+commands, CLAUDE.md 은 대장에서 소멸) ----
  ( cd "$sandbox_ledger" && "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 )
  local manifest_file="$sandbox_ledger/.claude/.coding-harness.json"
  local declared_rules declared_agents declared_commands expected_ledger_count actual_ledger_count
  declared_rules=$(grep -oE '^readonly RULES_FILE_COUNT=[0-9]+' "$INSTALL_SCRIPT" | grep -oE '[0-9]+$')
  declared_agents=$(grep -oE '^readonly AGENTS_FILE_COUNT=[0-9]+' "$INSTALL_SCRIPT" | grep -oE '[0-9]+$')
  declared_commands=$(grep -oE '^readonly COMMANDS_FILE_COUNT=[0-9]+' "$INSTALL_SCRIPT" | grep -oE '[0-9]+$')
  expected_ledger_count=$((declared_rules + declared_agents + declared_commands))
  actual_ledger_count=$(grep -cE '^    ".*": "[0-9a-f]{64}",?$' "$manifest_file")
  if ! assert_equals "$expected_ledger_count" "$actual_ledger_count" "대장 항목 수"; then
    note_failure "T27-1: 대장 항목 수=$actual_ledger_count, 기대=$expected_ledger_count"
  fi

  # ---- T27-2 (D-2): 대장 해시 일치 → 삭제 ----
  # D-5(살아있는 파일의 툼스톤은 레포 버그)가 fail-closed 이므로, 레포에 실존하는 파일로는
  # 이 경로를 만들 수 없다 — "예전엔 레포에 있었지만 지금은 제거된 파일"을 흉내내려면 레포에
  # 없는 가상의 경로를 쓰고, 그 경로의 대장 항목을 직접 주입해야 한다. grep 기반 조회
  # (read_installed_ledger_hash) 는 JSON 구조가 아니라 리터럴 줄만 보므로, manifest 파일
  # 끝에 한 줄 추가하는 것으로 충분하다. 한계(검수 L1): 이 주입은 "files" 오브젝트를 닫는 `}`
  # 바깥에 줄을 붙이는 것이라 결과 manifest 는 엄밀한 JSON 이 아니다 — 여기서 통과하는 이유는
  # 순전히 조회가 grep 기반 줄 매칭이기 때문이다. 아래 T27-4·T27-5·T27-8 도 같은 기법을 쓴다.
  ( cd "$sandbox_d2" && "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 )
  local tombstoned_relative_path="rules/common/__t27_tombstoned.md"
  local tombstoned_target_path="$sandbox_d2/.claude/$tombstoned_relative_path"
  cp "$sandbox_d2/.claude/rules/common/testing.md" "$tombstoned_target_path"
  local tombstoned_hash
  tombstoned_hash=$(compute_sha256_for_test "$tombstoned_target_path")
  echo "    \"$tombstoned_relative_path\": \"$tombstoned_hash\"" >> "$sandbox_d2/.claude/.coding-harness.json"
  echo "$tombstoned_relative_path" > "$sandbox_d2/removals.txt"

  ( cd "$sandbox_d2" && CODING_HARNESS_REMOVALS_FILE="$sandbox_d2/removals.txt" \
    "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 )
  if [[ -f "$tombstoned_target_path" ]]; then
    note_failure "T27-2 (D-2): 대장 일치 툼스톤이 삭제되지 않음"
  fi

  # ---- T27-3 (D-1): 대상에 없는 파일 → 조용히 skip (멱등, 실패하지 않음) ----
  echo "rules/common/does-not-exist.md" > "$sandbox_d1/removals.txt"
  ( cd "$sandbox_d1" && "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 )
  local d1_exit=0
  ( cd "$sandbox_d1" && CODING_HARNESS_REMOVALS_FILE="$sandbox_d1/removals.txt" \
    "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 ) || d1_exit=$?
  if [[ "$d1_exit" -ne 0 ]]; then
    note_failure "T27-3 (D-1): 대상에 없는 파일의 툼스톤 처리 중 실패(exit $d1_exit)"
  fi

  # ---- T27-4 (D-4): 사용자가 수정한 파일은 --force 로도 삭제하지 않는다 ----
  # C1 가드는 T27-5·T27-8 이 담당한다 — T27-4 는 대장 항목을 직접 주입하므로 C1 회귀(v1
  # manifest 의 "files" 대장 부재) 경로를 지나지 않는다.
  # D-5(살아있는 파일의 툼스톤은 레포 버그)가 fail-closed 로 먼저 발동하는 것을 피하려면
  # T27-2 와 같은 방식(레포에 없는 가상 경로 + 대장 항목 직접 주입)을 써야 한다 — 실존하는
  # rules/common/testing.md 를 쓰면 check_preconditions 단계에서 설치가 시작도 못 하고
  # 중단돼, 아래 단언이 "아무것도 안 됐으니 파일이 그대로 있다"는 무의미한 통과가 된다.
  local d4_relative_path="rules/common/__t27_d4_modified.md"
  local d4_target_path="$sandbox_d4/.claude/$d4_relative_path"
  ( cd "$sandbox_d4" && "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 )
  cp "$sandbox_d4/.claude/rules/common/testing.md" "$d4_target_path"
  local d4_hash
  d4_hash=$(compute_sha256_for_test "$d4_target_path")
  echo "    \"$d4_relative_path\": \"$d4_hash\"" >> "$sandbox_d4/.claude/.coding-harness.json"
  echo "$d4_relative_path" > "$sandbox_d4/removals.txt"
  echo "# 사용자 수정" >> "$d4_target_path"   # 주입한 대장 해시와 불일치하게 만든다

  local d4_output d4_exit=0
  d4_output=$( cd "$sandbox_d4" && CODING_HARNESS_REMOVALS_FILE="$sandbox_d4/removals.txt" \
    "$INSTALL_SCRIPT" --scope project --force 2>&1 ) || d4_exit=$?
  if [[ "$d4_exit" -ne 0 ]]; then
    note_failure "T27-4 (D-4): 보호는 실패가 아닌데 exit ${d4_exit}로 중단됨"
  fi
  if [[ ! -f "$d4_target_path" ]]; then
    note_failure "T27-4 (D-4): 수정된 파일이 --force 로 삭제됨(기대: 보호)"
  fi
  if ! grep -qF "$d4_relative_path — 수정된 파일이라 삭제하지 않습니다" <<< "$d4_output"; then
    note_failure "T27-4 (D-4): stdout 에 D-4 보호 로그가 없음"
  fi
  if ! grep -qF '툼스톤 처리: 제거 0건, 보호 1건' <<< "$d4_output"; then
    note_failure "T27-4 (D-4): 툼스톤 처리 요약 로그가 기대와 다름"
  fi
  if ! grep -qE '"version": 3' "$sandbox_d4/.claude/.coding-harness.json"; then
    note_failure "T27-4 (D-4): 설치가 완주하지 않아 manifest 가 v3 로 재기록되지 않음 — D-4 보호 중 설치가 중단됨"
  fi

  # ---- T27-5 (D-3): 대장에 항목 없음(v1 설치본 흉내) → 보호 ----
  # C1 이 실제로 재현되던 자리 — v1 manifest 는 "files" 대장 자체가 없어
  # read_installed_ledger_hash 의 grep 이 반드시 미스매치한다. T27-4 와 같은 이유로
  # 레포에 없는 가상 경로를 쓴다.
  local d3_relative_path="rules/common/__t27_d3_legacy.md"
  local d3_target_path="$sandbox_d3/.claude/$d3_relative_path"
  ( cd "$sandbox_d3" && "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 )
  cp "$sandbox_d3/.claude/rules/common/testing.md" "$d3_target_path"
  echo "$d3_relative_path" > "$sandbox_d3/removals.txt"
  cat > "$sandbox_d3/.claude/.coding-harness.json" <<'MANIFEST_V1_EOF'
{
  "version": 1,
  "scope": "project"
}
MANIFEST_V1_EOF
  local d3_output d3_exit=0
  d3_output=$( cd "$sandbox_d3" && CODING_HARNESS_REMOVALS_FILE="$sandbox_d3/removals.txt" \
    "$INSTALL_SCRIPT" --scope project 2>&1 ) || d3_exit=$?
  if [[ "$d3_exit" -ne 0 ]]; then
    note_failure "T27-5 (D-3): 보호는 실패가 아닌데 exit ${d3_exit}로 중단됨 — C1 회귀"
  fi
  if [[ ! -f "$d3_target_path" ]]; then
    note_failure "T27-5 (D-3): 대장 없는 v1 설치본에서 파일이 삭제됨(기대: 보호)"
  fi
  if ! grep -qF "$d3_relative_path — 설치 이력을 확인할 수 없어" <<< "$d3_output"; then
    note_failure "T27-5 (D-3): stdout 에 D-3 보호 로그가 없음"
  fi
  if ! grep -qF '툼스톤 처리: 제거 0건, 보호 1건' <<< "$d3_output"; then
    note_failure "T27-5 (D-3): 툼스톤 처리 요약 로그가 기대와 다름"
  fi
  if ! grep -qE '"version": 3' "$sandbox_d3/.claude/.coding-harness.json"; then
    note_failure "T27-5 (D-3): 설치가 완주하지 않아 manifest 가 v3 로 재기록되지 않음 — C1 회귀"
  fi

  # ---- T27-6 (D-5): 형식 위반(세 네임스페이스 밖 경로) → 설치 전체 중단(fail-closed) ----
  echo "CLAUDE.md" > "$sandbox_d5a/removals.txt"
  ( cd "$sandbox_d5a" && "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 )
  local d5a_exit=0
  ( cd "$sandbox_d5a" && CODING_HARNESS_REMOVALS_FILE="$sandbox_d5a/removals.txt" \
    "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 ) || d5a_exit=$?
  if [[ "$d5a_exit" -ne 1 ]]; then
    note_failure "T27-6 (D-5): 형식 위반 removals.txt 가 설치를 중단시키지 않음(exit $d5a_exit)"
  fi

  # ---- T27-7 (D-5): 레포에 아직 존재하는 파일의 툼스톤(레포 버그) → fail-closed ----
  echo "rules/common/testing.md" > "$sandbox_d5b/removals.txt"   # 레포에 실존 — 레포 버그 시나리오
  ( cd "$sandbox_d5b" && "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 )
  local d5b_exit=0
  ( cd "$sandbox_d5b" && CODING_HARNESS_REMOVALS_FILE="$sandbox_d5b/removals.txt" \
    "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 ) || d5b_exit=$?
  if [[ "$d5b_exit" -ne 1 ]]; then
    note_failure "T27-7 (D-5): 살아있는 파일의 툼스톤이 설치를 중단시키지 않음(exit $d5b_exit)"
  fi

  # ---- T27-8: --dry-run 은 삭제 계획만 출력하고 실제로 지우지 않는다 ----
  # D-3(v1 흉내) 시나리오를 dry-run 으로 돌린다 — T27-5 와 같은 이유로 가상 경로를 쓰고,
  # 여기서는 추가로 "무부작용"(manifest 가 실제로는 갱신되지 않음)까지 확인한다. T27-5 와
  # 겹치지 않게 dry-run 이라는 별도 축(플래그)을 검증한다.
  local dry_relative_path="rules/common/__t27_dry_legacy.md"
  local dry_target_path="$sandbox_dry/.claude/$dry_relative_path"
  ( cd "$sandbox_dry" && "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 )
  cp "$sandbox_dry/.claude/rules/common/testing.md" "$dry_target_path"
  echo "$dry_relative_path" > "$sandbox_dry/removals.txt"
  cat > "$sandbox_dry/.claude/.coding-harness.json" <<'MANIFEST_V1_EOF'
{
  "version": 1,
  "scope": "project"
}
MANIFEST_V1_EOF
  local dry_output dry_exit=0
  dry_output=$( cd "$sandbox_dry" && CODING_HARNESS_REMOVALS_FILE="$sandbox_dry/removals.txt" \
    "$INSTALL_SCRIPT" --scope project --dry-run 2>&1 ) || dry_exit=$?
  if [[ "$dry_exit" -ne 0 ]]; then
    note_failure "T27-8: dry-run 계획 출력이 exit ${dry_exit}로 실패함 — C1 회귀"
  fi
  if [[ ! -f "$dry_target_path" ]]; then
    note_failure "T27-8: --dry-run 인데 툼스톤 파일이 실제로 삭제됨"
  fi
  if ! grep -qF "$dry_relative_path — 설치 이력을 확인할 수 없어" <<< "$dry_output"; then
    note_failure "T27-8: --dry-run 계획 출력에 툼스톤 보호(D-3) 문구가 없음"
  fi
  if ! grep -qF '툼스톤 처리: 제거 0건, 보호 1건' <<< "$dry_output"; then
    note_failure "T27-8: --dry-run 계획의 툼스톤 처리 요약이 기대와 다름"
  fi
  if ! grep -qE '"version": 1' "$sandbox_dry/.claude/.coding-harness.json"; then
    note_failure "T27-8: --dry-run 인데 manifest 가 실제로 갱신됨(무부작용 위반)"
  fi

  # ---- T27-9: 레포 원본 removals.txt(헤더 주석뿐) → 삭제 루프가 안전하게 no-op ----
  local empty_exit=0
  ( cd "$sandbox_empty" && "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 ) || empty_exit=$?
  if [[ "$empty_exit" -ne 0 ]]; then
    note_failure "T27-9: 레포 원본 removals.txt(주석뿐)로 설치 시 실패(exit $empty_exit)"
  fi

  # ---- T27-10: 대장 일치 "낡은 사본" — --force 없이 자동 갱신 ----
  # repo_copy 는 rules/agents/commands·install.sh·CLAUDE.md 만 복제한 가벼운 사본이다(.git 등
  # 제외). 여기서 소스 파일 하나를 "레포가 전진한 것"처럼 바꾼 뒤, 원본 레포로 이미 설치된
  # sandbox_stale 에 이 사본으로 재설치한다 — 대상 해시는 원본 설치 시점의 대장과 일치하고
  # (사용자가 손대지 않았으므로) 소스만 달라진, 정확히 "낡은 사본" 상황이다.
  cp -R "$REPO_ROOT/rules" "$REPO_ROOT/agents" "$REPO_ROOT/commands" "$repo_copy/"
  cp "$REPO_ROOT/install.sh" "$REPO_ROOT/CLAUDE.md" "$repo_copy/"
  echo "# repo advanced" >> "$repo_copy/rules/common/coding-style.md"
  ( cd "$sandbox_stale" && "$INSTALL_SCRIPT" --scope project > /dev/null 2>&1 )
  local stale_exit=0
  ( cd "$sandbox_stale" && "$repo_copy/install.sh" --scope project > /dev/null 2>&1 ) || stale_exit=$?
  if [[ "$stale_exit" -ne 0 ]]; then
    note_failure "T27-10: 대장 일치 낡은 사본인데 --force 없이 갱신되지 않음(exit $stale_exit)"
  elif ! grep -q "repo advanced" "$sandbox_stale/.claude/rules/common/coding-style.md"; then
    note_failure "T27-10: 낡은 사본 자동 갱신이 실제로 반영되지 않음"
  fi

  # ---- T27-11 (A6 회귀, PRP tests-hardening §0-3): 레포 경로에 ERE/글롭 메타문자가 있어도
  # 매니페스트 대장이 무의미해지지 않는다. install.sh 의 build_files_ledger_json 인용 수정을
  # 고정한다. 재현: 레포 사본을 "re[po]" 이름 디렉토리에 두고 --scope project 로 설치하면,
  # 인용 없이 접두사를 제거하는 옛 코드에서는 대장 키가 절대경로로 남고 해시가 빈 문자열이
  # 된다(§0-3 실측 — 이 사본 안 sha256sum 은 대상 부재로 실패하지만, save_manifest_file 이
  # `|| return 1` 로 호출돼 그 함수 트리 전체에서 set -e 가 꺼지므로(§4.1 GOTCHA 1과 동일 계열)
  # 조용히 빈 문자열로 이어지고 설치는 exit 0 으로 끝난다).
  local metachar_repo_base metachar_target_base metachar_repo_dir metachar_target
  metachar_repo_base=$(mktemp -d); metachar_target_base=$(mktemp -d)
  # 등록 거부(빈 값 — mktemp 실패로 흘러든 경우가 대표적이다)를 판정으로 올린다: 거부는
  # 등록만 막고 이어지는 mkdir·cp 를 막지 않아, 반환값을 버리면 진단이 하류에서 엉킨다.
  register_cleanup_path "$metachar_repo_base" "$metachar_target_base" \
    || note_failure "T27-11 (A6): 사전조건 실패 — 임시 디렉토리 생성/등록이 거부됨(mktemp 실패 의심)"
  metachar_repo_dir="$metachar_repo_base/re[po]"
  metachar_target="$metachar_target_base/ta[rget]"
  mkdir -p "$metachar_repo_dir" "$metachar_target"
  cp -R "$REPO_ROOT/rules" "$REPO_ROOT/agents" "$REPO_ROOT/commands" "$metachar_repo_dir/"
  cp "$REPO_ROOT/install.sh" "$metachar_repo_dir/"

  local metachar_exit=0
  ( cd "$metachar_target" && "$metachar_repo_dir/install.sh" --scope project > /dev/null 2>&1 ) \
    || metachar_exit=$?
  if [[ "$metachar_exit" -ne 0 ]]; then
    note_failure "T27-11 (A6): 메타문자 경로 최초 설치가 exit ${metachar_exit}로 실패함"
  fi

  local metachar_manifest="$metachar_target/.claude/.coding-harness.json"
  if [[ ! -f "$metachar_manifest" ]]; then
    note_failure "T27-11 (A6): 메타문자 경로 설치의 manifest 가 생성되지 않음"
  else
    local metachar_ledger_total metachar_ledger_valid_hash metachar_ledger_absolute_key
    metachar_ledger_total=$(grep -cE '^    ".*": ".*",?$' "$metachar_manifest")
    metachar_ledger_valid_hash=$(grep -cE '^    ".*": "[0-9a-f]{64}",?$' "$metachar_manifest")
    metachar_ledger_absolute_key=$(grep -cE '^    "/' "$metachar_manifest")
    if [[ "$metachar_ledger_total" -eq 0 ]]; then
      note_failure "T27-11 (A6): 대장 항목이 0건 — 사전조건 실패(메타문자 사본에 rules/agents/commands 가 없거나 설치가 대장을 채우지 못함)"
    elif [[ "$metachar_ledger_valid_hash" -ne "$metachar_ledger_total" ]]; then
      note_failure "T27-11 (A6): 레포 경로 메타문자로 대장 해시가 빈 문자열 — 대장 ${metachar_ledger_total}건 중 유효한 sha256 은 ${metachar_ledger_valid_hash}건뿐(§0-3 재현)"
    fi
    if [[ "$metachar_ledger_absolute_key" -ne 0 ]]; then
      note_failure "T27-11 (A6): 대장 키 ${metachar_ledger_absolute_key}건이 절대경로 — 접두사 제거 실패(§0-3 재현)"
    fi
  fi

  # ---- T27-12 (A6 회귀): 설치 대상 경로에 메타문자가 있어도 "낡은 사본"이 오분류되어
  # 차단되지 않는다. install.sh 의 filter_modified_files 인용 수정을 고정한다. 위 T27-11 의
  # 설치를 baseline 으로 재사용해 repo 쪽 파일 하나를 전진시키고 target 쪽 파일 하나를 지운
  # 뒤(T27-13 준비도 겸함) 강제 없이 재설치한다.
  #
  # 두 프로브 대상의 존재를 먼저 단언한다 — 개명·삭제되면 조작이 무동작이 되어 아래 기대
  # 개수가 조용히 떨어지고 T27-13 이 「결측 누락」이라는 틀린 원인을 보고한다(검수 Minor 3).
  # 관리 파일 개명은 이 저장소에서 실제로 일어나는 사건이다(project CLAUDE.md §5 툼스톤 규약).
  local metachar_probe_stale="$metachar_repo_dir/rules/common/coding-style.md"
  local metachar_probe_missing="$metachar_target/.claude/rules/common/testing.md"
  local metachar_expected_updates=2   # 전진 1건(낡은 사본) + 결측 1건(복원)
  if [[ ! -f "$metachar_probe_stale" ]]; then
    note_failure "T27-12 (A6): 사전조건 실패 — 전진용 프로브 파일 부재: $metachar_probe_stale"
  fi
  if [[ ! -f "$metachar_probe_missing" ]]; then
    note_failure "T27-12 (A6): 사전조건 실패 — 결측용 프로브 파일 부재: $metachar_probe_missing"
  fi
  echo "# t27 메타문자 프로브" >> "$metachar_probe_stale"
  rm -f "$metachar_probe_missing"

  local metachar_reinstall_output metachar_reinstall_exit=0
  metachar_reinstall_output=$( cd "$metachar_target" \
    && "$metachar_repo_dir/install.sh" --scope project 2>&1 ) || metachar_reinstall_exit=$?
  if [[ "$metachar_reinstall_exit" -ne 0 ]]; then
    note_failure "T27-12 (A6): 메타문자 경로 재설치가 중단됨(exit ${metachar_reinstall_exit}) — 원인은 대상 경로 오분류(filter_modified_files) · 대장 조회 실패(T27-11 동시 발화) · 사본 준비 실패 중 하나다. 사유 줄: $(grep -E '^\[(ERROR|WARN)\]' <<< "$metachar_reinstall_output" | head -3 | tr '\n' ' ')"
  elif ! grep -q "t27 메타문자 프로브" "$metachar_target/.claude/rules/common/coding-style.md"; then
    note_failure "T27-12 (A6): 재설치가 exit 0 인데 낡은 사본 갱신이 실제로 반영되지 않음"
  fi

  # ---- T27-13 (A6 회귀): 레포 경로 메타문자로 결측 파일이 갱신 개수 집계에서 누락되지
  # 않는다. install.sh 의 list_missing_managed_files 인용 수정을 고정한다. T27-12 가 이미
  # 차단(exit != 0)을 잡은 경우 여기서는 재판정하지 않는다 — 차단되면 이 로그 줄 자체가
  # 나오지 않아 재판정이 공허해진다.
  if [[ "$metachar_reinstall_exit" -eq 0 ]] \
    && ! grep -qF "rules/  ${metachar_expected_updates}개 갱신 (관리 대상 ${declared_rules}개)" <<< "$metachar_reinstall_output"; then
    note_failure "T27-13 (A6): 레포 경로 메타문자로 결측 파일이 개수 집계에서 누락 — 기대 ${metachar_expected_updates}개, 실제: $(grep -E 'rules/[[:space:]]+[0-9]+개 갱신' <<< "$metachar_reinstall_output" | head -1)"
  fi

  # ---- T27-14 (H2 이스케이프, PRP shell-hardening §9-2·§7-4): 관리 파일 상대경로에 "
  # 가 있어도 대장 키가 올바르게 이스케이프되어 기록·조회 양쪽에서 대칭적으로 동작한다.
  # T27-10 의 "낡은 사본" 재설치 관용구를 확장해 파일 하나를 " 포함 이름으로 바꾼다 —
  # read_installed_ledger_hash 조회 이스케이프 누락(GOTCHA 4, 이 항목의 대표적 실패)이
  # 있으면 재설치가 대장 조회 실패로 "modified" 오분류돼 --force 없이 갱신되지 않는다
  # (실측: 조회 쪽만 되돌리면 이 재설치가 exit 1 로 --force 를 요구한다).
  local repo_copy_esc sandbox_esc
  repo_copy_esc=$(mktemp -d); sandbox_esc=$(mktemp -d)
  register_cleanup_path "$repo_copy_esc" "$sandbox_esc"
  cp -R "$REPO_ROOT/rules" "$REPO_ROOT/agents" "$REPO_ROOT/commands" "$repo_copy_esc/"
  cp "$REPO_ROOT/install.sh" "$repo_copy_esc/"
  local esc_relative_path='rules/common/__t27_esc".md'
  mv "$repo_copy_esc/rules/common/coding-style.md" "$repo_copy_esc/$esc_relative_path"

  ( cd "$sandbox_esc" && "$repo_copy_esc/install.sh" --scope project > /dev/null 2>&1 )
  local esc_manifest="$sandbox_esc/.claude/.coding-harness.json"
  # 정확한 이스케이프 표현(\" 등)을 전제하지 않는다 — 인용부호 앞쪽 접두만 확인해, 대장에
  # 이 경로의 항목이 아예 없어지는(쓰기 쪽 회귀) 형태만 잡는다.
  if ! grep -qF 'rules/common/__t27_esc' "$esc_manifest"; then
    note_failure "T27-14 (H2 이스케이프): 최초 설치의 대장에 인용부호 포함 경로 키가 없음(쓰기 쪽 이스케이프 회귀 의심)"
  fi

  echo "# t27 이스케이프 전진" >> "$repo_copy_esc/$esc_relative_path"
  local esc_reinstall_output esc_reinstall_exit=0
  esc_reinstall_output=$( cd "$sandbox_esc" \
    && "$repo_copy_esc/install.sh" --scope project 2>&1 ) || esc_reinstall_exit=$?
  if [[ "$esc_reinstall_exit" -ne 0 ]]; then
    note_failure "T27-14 (H2 이스케이프): 인용부호 포함 파일의 낡은 사본 재설치가 --force 없이 exit ${esc_reinstall_exit}로 실패함 — read_installed_ledger_hash 조회 이스케이프 누락 의심"
  elif ! grep -qF "t27 이스케이프 전진" "$sandbox_esc/.claude/$esc_relative_path"; then
    note_failure "T27-14 (H2 이스케이프): 재설치가 exit 0 인데 인용부호 포함 파일의 갱신이 반영되지 않음"
  fi

  # ---- T27-15·T27-16 (M1·m1, S1 검수 1회차): escape_json_string 의 제어문자 거부.
  # $PWD(=--scope project 의 target_base_dir)에 개행(0x0a, §7-4 가 거부 근거로 명시한
  # 문자)이 든 디렉토리를 만들어 그 안에서 설치를 실행한다. 관리 파일의 상대경로에
  # 개행을 심는 방식(T27-11~14 의 메타문자·인용부호 관용구를 그대로 확장하는 방식)은
  # 시도했으나 재현되지 않았다 — find | while read 파이프라인이 개행을 레코드
  # 구분자로 여겨 읽으며 소비해 버려, escape_json_string 에 그 문자가 끝내 전달되지
  # 않는다(실측). $PWD·$REPO_ROOT 는 find 를 거치지 않는 평범한 변수 확장이라 그 문제가
  # 없다 — 검수자의 원 재현("개행 든 $PWD")과 같은 형태로 되돌아간 이유다.
  local ctrl_base ctrl_dirname
  ctrl_base=$(mktemp -d)
  register_cleanup_path "$ctrl_base"
  ctrl_dirname=$'t27ctrl'$'\n''dir'
  mkdir -p "$ctrl_base/$ctrl_dirname"

  # ---- T27-15 (M1): case 문 브래킷 범위 [$'\x01'-$'\x1f'] 는 바이트가 아니라 콜레이션
  # 순서로 해석돼, 이 스위트의 기본 실행 로케일(C)에서만 우연히 안전했던 결함이다.
  # en_US.UTF-8 이 없는 환경에서는 로케일 의존 검사를 건너뛴다.
  # grep -q 는 첫 매치에서 곧바로 종료해, locale -a 가 아직 쓰는 중이면 SIGPIPE 를
  # 받는다 — set -o pipefail 아래에서는 grep 이 찾았어도 파이프 전체 상태가 141 로
  # 새어 이 if 가 거짓으로 읽힌다(실측). -q 를 빼고 출력을 버려 끝까지 읽게 한다.
  if locale -a 2> /dev/null | grep -x 'en_US.UTF-8' > /dev/null; then
    local sandbox_ctrl_locale ctrl_locale_exit=0
    sandbox_ctrl_locale=$(mktemp -d)
    register_cleanup_path "$sandbox_ctrl_locale"
    ( cd "$ctrl_base/$ctrl_dirname" \
      && HOME="$sandbox_ctrl_locale" LC_ALL=en_US.UTF-8 "$INSTALL_SCRIPT" --scope project \
      > /dev/null 2>&1 ) || ctrl_locale_exit=$?
    if [[ "$ctrl_locale_exit" -eq 0 ]]; then
      note_failure "T27-15 (M1): LC_ALL=en_US.UTF-8 에서 개행 든 \$PWD 가 있어도 설치가 exit 0 — 제어문자 거부가 로케일에 따라 무력화됨(§7-4 회귀)"
    fi
  else
    log_warn "T27-15 (M1): en_US.UTF-8 로케일이 이 환경에 없어 로케일 의존 회귀 검사를 건너뜀"
  fi

  # ---- T27-16 (m1): 거부가 실제로 발화할 때 관리 파일이 하나도 먼저 설치되지 않는다
  # (check_preconditions 로 승격 — 이전에는 build_manifest_json 마지막 단계에서 발화해
  # 전량 복사 후 실패했다). 로케일은 스위트 기본(C)으로 충분하다 — "언제" 거부되는지를
  # 보는 것이지 "거부되는가"(그건 위 T27-15)가 아니다.
  local sandbox_ctrl_order order_exit=0
  sandbox_ctrl_order=$(mktemp -d)
  register_cleanup_path "$sandbox_ctrl_order"
  ( cd "$ctrl_base/$ctrl_dirname" && HOME="$sandbox_ctrl_order" "$INSTALL_SCRIPT" \
    --scope project > /dev/null 2>&1 ) || order_exit=$?
  if [[ "$order_exit" -eq 0 ]]; then
    note_failure "T27-16 (m1): 개행 든 \$PWD 가 있는데도 설치가 exit 0"
  fi
  if [[ -e "$ctrl_base/$ctrl_dirname/.claude" ]]; then
    note_failure "T27-16 (m1): 제어문자 거부 전에 .claude/ 가 이미 생성됨(check_preconditions 승격 실패 의심)"
  fi

  finish_group "$test_name"
}

# T28: rules/ 벤더링 문서의 사실 오류 3건 재발 방지 (PRP audit-remediation Q4 — F-6 이빨 ①)
# A-1(rules/web/hooks.md 훅 JSON 무효 스키마 + $FILE_PATH) · A-2(rules/react/patterns.md 의
# React Native 부재 단정) · A-3(rules/common/performance.md effort 지속성 오기)의 로컬
# 패치가 상류 재동기화로 되돌아가면 이 그룹이 즉시 잡는다(결정 AR16 3층 장치 중 "테스트
# 이빨" — 문서 1절 + 이 그룹이 사람 절차와 기계 강제를 나눠 맡는다).
# T28-4 는 그 3건에 더해 rules/common/coding-style.md 의 중첩 한도 로컬 패치를 고정한다
# (tests-hardening PRP §9 A2) — 되돌림이 길이 중립이라 T26 바이트 래칫이 원리적으로 못 잡는
# 자리다.
#
# 한계(비망라) — T28-2·T28-3·T28-4 는 리터럴 문자열의 존재/부재를 보는 정적 검사다. 같은
# 뜻을 다른 낱말로 되돌리는 편집(예: 중첩 한도를 숫자 없는 산문으로만 서술)이나, 토큰은
# 남기고 주변 문장의 의미를 뒤집는 편집은 잡지 못한다. T28-1 만 구조(JSON 스키마)를 본다.
# 전수 증명이 아니다.
test_rules_vendor_patch_guards() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T28"
  local test_desc="rules/ 벤더링 문서 재발 방지 4종 — 훅 JSON 스키마(T28-1) · 부재 단정 가드(T28-2) · effort 앵커(T28-3) · 중첩 한도 계약(T28-4)"
  log_test_name "$test_name" "$test_desc"

  # ---- T28-1 (AR1): rules/ 아래 모든 .md 의 ```json 블록 중 최상위 hooks 키를 가진 것은
  # 전부 매처 그룹에 hooks 배열 + type=="command" 를 가져야 한다(공식 3단 스키마: 이벤트 →
  # 매처 그룹 → hooks 배열의 {type, command}). 같은 스캔에서 존재하지 않는 변수 $FILE_PATH
  # 의 사용도 함께 잡는다 — 둘 다 A-1 이 고친 결함이라 한 스캔에서 보는 것이 자연스럽다.
  local hooks_schema_output
  hooks_schema_output=$(python3 - "$REPO_ROOT" <<'PYEOF'
import json
import os
import re
import sys

repo_root = sys.argv[1]
rules_dir = os.path.join(repo_root, "rules")
json_fence_pattern = re.compile(r"```json\r?\n(.*?)```", re.DOTALL)

schema_errors = []
file_path_hits = []
blocks_checked = 0

for dirpath, _dirnames, filenames in os.walk(rules_dir):
    for filename in sorted(filenames):
        if not filename.endswith(".md"):
            continue
        file_path = os.path.join(dirpath, filename)
        relative_path = os.path.relpath(file_path, repo_root)
        text = open(file_path, encoding="utf-8").read()

        if "$FILE_PATH" in text:
            file_path_hits.append(relative_path)

        for block in json_fence_pattern.findall(text):
            try:
                parsed = json.loads(block)
            except json.JSONDecodeError:
                continue
            if not isinstance(parsed, dict) or "hooks" not in parsed:
                continue
            blocks_checked += 1
            events = parsed["hooks"]
            if not isinstance(events, dict):
                schema_errors.append(f"{relative_path}: 최상위 hooks 필드가 객체가 아님")
                continue
            for event_name, matcher_groups in events.items():
                if not isinstance(matcher_groups, list):
                    schema_errors.append(f"{relative_path}: {event_name} 값이 배열이 아님")
                    continue
                for group in matcher_groups:
                    if not isinstance(group, dict):
                        schema_errors.append(f"{relative_path}: {event_name} 매처 그룹이 객체가 아님")
                        continue
                    handlers = group.get("hooks")
                    if not isinstance(handlers, list) or not handlers:
                        schema_errors.append(
                            f"{relative_path}: {event_name} 매처 그룹에 hooks 배열이 없음"
                            "(구형 2단 스키마 가능성)"
                        )
                        continue
                    for handler in handlers:
                        if (
                            not isinstance(handler, dict)
                            or handler.get("type") != "command"
                            or not handler.get("command")
                        ):
                            schema_errors.append(
                                f"{relative_path}: {event_name} hooks 엔트리가 "
                                'type=="command"·command 를 갖추지 못함'
                            )

print(f"BLOCKS_CHECKED:{blocks_checked}")
for hit in file_path_hits:
    print(f"FILE_PATH_HIT:{hit}")
for error in schema_errors:
    print(f"SCHEMA_ERROR:{error}")
PYEOF
)
  local hooks_blocks_checked_count
  hooks_blocks_checked_count=$(grep '^BLOCKS_CHECKED:' <<< "$hooks_schema_output" | head -1 | cut -d: -f2)
  if [[ -z "$hooks_blocks_checked_count" || "$hooks_blocks_checked_count" -eq 0 ]]; then
    note_failure "T28-1: rules/ 에서 최상위 hooks 키를 가진 json 블록을 하나도 못 찾음 — 추출 앵커 소실 가능(공허 통과 방지)"
  fi
  while IFS= read -r hit_line; do
    [[ -z "$hit_line" ]] && continue
    note_failure "T28-1: ${hit_line#FILE_PATH_HIT:} 에 존재하지 않는 변수 \$FILE_PATH 사용"
  done < <(grep '^FILE_PATH_HIT:' <<< "$hooks_schema_output" || true)
  while IFS= read -r error_line; do
    [[ -z "$error_line" ]] && continue
    note_failure "T28-1: ${error_line#SCHEMA_ERROR:}"
  done < <(grep '^SCHEMA_ERROR:' <<< "$hooks_schema_output" || true)

  # ---- T28-2 (AR2): 배포 트리에 실재하는 디렉토리를 "not yet present" 로 서술하는 부재
  # 단정을 rules/ 전체에서 금지한다(A-2 의 재발 방지). 지금은 정당한 용례가 없으므로 0건을
  # 요구한다 — 미래에 생기면 그때 이 검사를 개정한다(YAGNI, PRP §4 AR2).
  local not_yet_present_hits
  not_yet_present_hits=$(grep -rn "not yet present" "$REPO_ROOT/rules" || true)
  if [[ -n "$not_yet_present_hits" ]]; then
    note_failure "T28-2: rules/ 에 '부재' 단정이 남아 있음 — ${not_yet_present_hits//$'\n'/ ; }"
  fi

  # ---- T28-3 (AR3): rules/common/performance.md 의 effort 지속성 서술이 공식 문서의
  # 계약 토큰(persist across sessions)을 담고 있는지 확인한다. §7 충돌 3 기준대로 산문
  # 전문이 아니라 최소 토큰만 고정한다 — 무해한 문장 다듬기(어순 변경·조사 수정)에는
  # 반응하지 않는다.
  if ! grep -q "persist across sessions" "$REPO_ROOT/rules/common/performance.md"; then
    note_failure "T28-3: rules/common/performance.md 에 'persist across sessions' 토큰이 없음"
  fi

  # ---- T28-4 (A2, tests-hardening PRP §9): 중첩 한도 계약. 상류값 `>4 levels` → 로컬
  # 패치값 `>3 levels` 는 **길이 중립 패치**라 상류 재동기화로 되돌아가도 T26 바이트 래칫이
  # 원리적으로 못 잡는다 — NOTICE.md §5 「이 커버리지 판정의 근거와 한계」 절이 그 사실을 적어
  # 뒀고, S3b 이전에는 이 토큰을 보는 검사가 이 파일에 아예 없었다(실측 0건). 존재(로컬값)와
  # 부재(상류값)를 함께 단언한다: 부재 쪽이 되돌림을 직접 잡고, 존재 쪽이 그 문장이 통째로
  # 사라지는 형태를 잡는다. 등장 횟수는 세지 않고 파일별 존재만 본다 — 정당한 문장 추가로 2곳이 3곳이 되는
  # 성장에서 검사가 빨개지면 정비자가 상수를 올리거나 검사를 지우기 쉽다(T32-7 이 카운트를
  # 블록 귀속으로 바꾼 것과 같은 판단).
  local nesting_contract_file
  for nesting_contract_file in rules/common/coding-style.md rules/common/code-review.md; do
    if ! grep -qF -- ">3 levels" "$REPO_ROOT/$nesting_contract_file"; then
      note_failure "T28-4: $nesting_contract_file 에 중첩 한도 계약 토큰 '>3 levels' 가 없음(로컬 패치가 사라졌다)"
    fi
    if grep -qF -- ">4 levels" "$REPO_ROOT/$nesting_contract_file"; then
      note_failure "T28-4: $nesting_contract_file 에 상류값 '>4 levels' 가 남아 있음(재동기화로 되돌아갔다 — 길이 중립이라 T26 은 못 잡는다)"
    fi
  done

  finish_group "$test_name"
}

# T29: 미배포 에이전트 13종 참조 재발 방지 (PRP audit-remediation R1 — F-6 이빨 ②)
# F-3(rules/common/agents.md 로스터를 배포 4종 — design-architect·implementer·
# code-reviewer·Explore — 로 교체) 이후, 참조 파일 여러 곳에서 정리한 미배포 에이전트
# 13종이 상류 재동기화로 되돌아오면 이 그룹이 즉시 잡는다.
#
# 검수 3회차 실측: 2회차의 "볼드·표 행·'Use `이름`' 백틱" 세 패턴 한정은 실제 표기
# 12형태 중 4개만 잡았다 — 백틱형이라도 "Use " 접두가 없으면(예: "See `tdd-guide`
# for ...", "Delegate to `security-reviewer` when ...") 전부 놓쳤고, 평문형("Use the
# tdd-guide agent")·문장 내장 볼드형("**STOP and use security-reviewer agent
# when:**")도 마찬가지였다. 이 저장소가 이번 회차에 스스로 채택한 "Delegate to
# **code-reviewer** with a ... lens" 어투가 그 미검출 계열과 같은 모양이라는 사실이
# 이 사각지대가 가상이 아님을 보여준다.
#
# 그래서 형태별 3패턴을 이름의 어휘 경계 매칭 1패턴으로 교체했다:
# (?<![\w-])이름(?![\w-]) (대소문자 무시). 이름 앞뒤에 단어문자·하이픈이 오지 않는
# 모든 등장을 형태(볼드·표 행·백틱·평문) 구분 없이 잡으면서, 하이픈·단어문자를 둘 다
# 경계로 취급하는 덕분에 `design-architect` 안의 `architect`, `architecture` 안의
# `architect` 는 구조적으로 배제한다. 이 패턴은 기존 3패턴이 잡던 것을 전부 포함하는
# 상위 집합임을 실측으로 확인했다(구현 보고 참조) — 그래서 3패턴은 제거했다.
#
# R1 4회차(사용자 승인 A 안 — 예외 장치 제거): 경계 매칭을 예외 없이 적용하면 정당한
# 고지 산문 2곳(rules/common/code-review.md:68 · rules/react/security.md:180)에서
# 위양성이 났었다 — 두 곳 다 "이 에이전트는 상류 번들에만 있다"고 알리는 문장 안에
# 이름을 직접 나열했기 때문이다. 이번 회차는 예외 처리 대신 그 문장에서 이름 자체를
# 뺐다(문장이 전하는 의미 — "이 리뷰어들은 상류 번들에만 있다" — 는 그대로 보존).
# 그래서 이 검사는 **예외 0개**다: 매칭된 줄은 예외 없이 전부 실패로 잡는다.
#
# 잔존 위험 — 완전성 주장이 아니라 실측한 범위 안에서의 한계 서술이다(의도적 설계
# 아님). 이 검사는 이름을 리터럴 문자열로 두고, 앞뒤가 단어문자도 하이픈도 아닐
# 때만 매칭한다(대소문자 무시, 예외 없음). 그 기제에서 곧바로 따라오는 한계: 이름이
# 그 리터럴 그대로 나타나지 않으면 이 검사는 걸지 못한다.
#
# 아래는 실측한 범위에서 확인된 회피 경로의 비망라 예시이며, 카테고리로 묶어
# 적는다(회피 경로 자체는 원리적으로 무한하다 — 예컨대 키릴 і·그리스 ο 같은 동형
# 문자 치환은 실측하지 않았고 아래 목록에도 없다):
#   - 표기 변형 — 공백("tdd guide") · 언더스코어("tdd_guide") · 낙타표기
#     ("TddGuide").
#   - 유니코드·인코딩 치환 — 비하이픈 하이픈류인 U+2011(NON-BREAKING HYPHEN) ·
#     U+2013(EN DASH) 로 하이픈을 대체한 표기(예: "tdd‑guide" — 에디터의 스마트
#     대시 자동 치환에서 실제로 발생하고, 렌더링 시 일반 하이픈과 육안 구분이 거의
#     안 된다. 구현 4회차 실측)에 더해, 제로폭 공백 U+200B 삽입 · 소프트 하이픈
#     U+00AD · 전각 하이픈 U+FF0D · HTML 엔티티(`&#8209;` 등)도 같은 방식으로
#     경계를 깨뜨린다(검수 렌즈 F 실측). 정규식의 `-` 는 U+002D(HYPHEN-MINUS)만
#     경계로 인식하므로, 이런 치환·삽입·인코딩은 전부 이름 앞뒤 경계를 깨 못
#     잡는다.
#   - 마크업 분절 — 강조·코드 마크업이 이름 내부에 끼어들어 연속된 문자열로
#     나타나지 않는 경우(예: `**tdd**-guide`, `` `tdd`-`guide` `` — 검수 렌즈 F
#     실측).
#   - 단어문자·하이픈 인접 결합 — 이름에 단어문자·하이픈이 곧바로 붙어 경계가
#     깨지는 경우: 복수형("tdd-guides") · 하이픈 합성어("self-tdd-guide") ·
#     선행 밑줄("_tdd-guide") · 후행 숫자("tdd-guide2"). design-architect 안의
#     architect 를 구조적으로 배제하는 것과 같은 메커니즘의 반대급부다.
#   - 줄바꿈 분리 — 이름이 물리적 줄바꿈으로 쪼개지는 경우.
# 실측 시도한 범위에서 이 이상은 확인하지 않았다(구현 4회차·검수 렌즈 F 보고
# 참조). 전수 증명이 아니다 — 위 범위 밖의 회피 경로가 남아 있을 수 있다.
#
# 오탐 부담(잔존 위험과 별개 개념 — 이쪽은 과소검출이 아니라 과다검출) — `architect`·
# `planner` 는 일반 영어 낱말이라, 미배포 에이전트를 지목하는 게 아니라 평범한 명사로
# 쓰인 정당한 산문도 이 검사에 걸린다(예: "the architect of this system"). 발생 시
# 표현을 바꿔 피한다. 또한 이 검사는 **줄 단위**라 코드펜스·URL·frontmatter 안에
# 이름이 등장해도 그대로 걸린다 — 이 역시 과다검출이며, 위 잔존 위험(과소검출)과는
# 반대 방향이다.
test_rules_agent_denylist_guard() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T29"
  local test_desc="미배포 에이전트 13종 참조 금지 — 이름 경계 매칭, 형태 무관, 예외 없음 (T29-1)"
  log_test_name "$test_name" "$test_desc"

  local denylist_output
  denylist_output=$(python3 - "$REPO_ROOT" <<'PYEOF'
import os
import re
import sys

repo_root = sys.argv[1]
rules_dir = os.path.join(repo_root, "rules")

# 상류 ECC 에는 실재하나 이 저장소가 배포하지 않는 에이전트 13종(rules/common/agents.md 의
# "Available Agents" 절 참조 정리 대상과 동일 — PRP audit-remediation §4 F-3).
UNDEPLOYED_AGENTS = [
    "planner", "architect", "tdd-guide", "security-reviewer",
    "build-error-resolver", "e2e-runner", "refactor-cleaner", "doc-updater",
    "rust-reviewer", "python-reviewer", "go-reviewer", "typescript-reviewer",
    "react-reviewer",
]

# 이름의 어휘 경계(하이픈·단어문자 모두 경계로 취급)만 검사한다 — 볼드·표 행·백틱·
# 평문 등 표기 형태에 무관하게 이름이 단독 토큰으로 나타나는 모든 경우를 잡는다.
# 예외 없음(R1 4회차) — 이 13종은 rules/ 어디에도 나타나서는 안 된다.
boundary_patterns = {
    name: re.compile(r"(?<![\w-])" + re.escape(name) + r"(?![\w-])", re.IGNORECASE)
    for name in UNDEPLOYED_AGENTS
}

hits = []
files_scanned = 0

for dirpath, _dirnames, filenames in os.walk(rules_dir):
    for filename in sorted(filenames):
        if not filename.endswith(".md"):
            continue
        file_path = os.path.join(dirpath, filename)
        relative_path = os.path.relpath(file_path, repo_root)
        files_scanned += 1
        with open(file_path, encoding="utf-8") as fh:
            lines = fh.readlines()
        for lineno, line in enumerate(lines, start=1):
            for name in UNDEPLOYED_AGENTS:
                if boundary_patterns[name].search(line):
                    # 스캔된 원문을 그대로 실어 나르므로, 그 안에 리터럴 백슬래시
                    # 시퀀스(\t·\n 등)가 있으면 하류의 echo -e(log_error) 가 실제
                    # 탭·개행으로 해석해 로그가 쪼개진다(T29 4회차 검수 실측 —
                    # log_error 자체는 ANSI 색상 출력에 -e 가 필요해 건드리지 않고,
                    # 이 스캔 경로에서만 백슬래시를 이스케이프해 리터럴로 고정한다).
                    escaped_line = line.strip().replace("\\", "\\\\")
                    hits.append(f"{relative_path}:{lineno}: `{name}` 재등장 — {escaped_line}")

print(f"FILES_SCANNED:{files_scanned}")
for hit in hits:
    print(f"HIT:{hit}")
PYEOF
)
  local files_scanned_count
  files_scanned_count=$(grep '^FILES_SCANNED:' <<< "$denylist_output" | head -1 | cut -d: -f2)
  if [[ -z "$files_scanned_count" || "$files_scanned_count" -eq 0 ]]; then
    note_failure "T29-1: rules/ 에서 .md 파일을 하나도 못 찾음 — 스캔 경로 소실 가능(공허 통과 방지)"
  fi
  while IFS= read -r hit_line; do
    [[ -z "$hit_line" ]] && continue
    note_failure "T29-1: ${hit_line#HIT:}"
  done < <(grep '^HIT:' <<< "$denylist_output" || true)

  finish_group "$test_name"
}

# T31(PRP claude-md-split — CLAUDE.md 배포 채널 이관, 후속으로 설계 워크플로우 가드 편입):
# rules/workflow/ 신설과 CLAUDE.md 배포 폐지, 루트 CLAUDE.md 의 프로젝트 지침 전환을
# 고정하는 래칫. T31-1~T31-5 전부 성립한다(이관 3단계 완료 — 신설·배포 폐지·루트 교체가
# 모두 끝났다). T31-6 은 그 이관으로 이 트리에 들어온 문단 하나의 인용 계약을 고정한다
# (tests-hardening PRP A5). T31-7(2026-09-11, 허브 카드/트리 통합 설계 사고 후속)은 대상이
# rules/workflow 가 아니라 agents/design-architect.md 다. T31-1~T31-6 은 전부 이관 산출물을
# 고정하는 검사였으므로 그룹 이름도 「rules/workflow 이관 고정 래칫」이었는데, T31-7 을
# 얹으면서 「워크플로우 지침 고정 래칫」으로 넓혔다 — 「이 그룹은 원래부터 그 뜻이었다」가
# 아니라 **이번에 범위를 넓혔다**는 기록이다(검수 1회차 MEDIUM 반영 — 사후 재정의로 라벨과
# 내용이 어긋나는 것을 피한다). 새 그룹을 만들지 않은 이유는 검사의 형태가 T31-6 과 같아서다
# — 리터럴 토큰의 존재로 지침 문단의 수축·삭제를 막는 정적 검사이고, 그 한계도 공유한다.
#
# 한계(비망라) — T31-2·T31-3·T31-5·T31-6·T31-7 은 리터럴 문자열의 존재/부재를 보는 정적
# 검사다. 같은 뜻을 다른 낱말로 쓴 되돌림, 토큰은 남기고 주변 문장의 의미를 뒤집는 편집,
# 그리고 T31-6 이 고정하지 않은 나머지 절(예: 모델 특정을 부인하는 문장)의 소실은 잡지
# 못한다. 반대 방향(위양성)도 실재한다 — T31-6 의 세 토큰은 한국어 산문 조각이라 뜻이
# 유지되는 다듬기에도 발화한다: `n=1` 을 `n = 1` 로 띄우거나 `재현율 주장` 을 `재현율 쪽
# 주장` 으로 늘리는 편집이 그렇다(뒤 예시의 근거는 같은 트리 안에 있다 — 아래 T31-6
# 인라인 주석 자신이 「재현율 쪽 주장」이라고 써서 그 고정 토큰을 포함하지 않는다). 그때
# 고쳐야 하는 것은 대상 문단이 아니라 **이 토큰 목록**이다 — T32-7 선례가 경고한 「빨개지면
# 검사를 지운다」로 가지 않기 위한 처방이다. T31-7 에는 그 위에 한 겹이 더 있다 — 이 가드는
# 지침 문서에 토큰 3종이 남아 있는지만 보고, design-architect 가 그 지침을 따라 **실제로
# 프리뷰 목업을 만들었는지는 검사하지 못한다**(만드는 행위 자체는 세션마다 다른 산출물이라
# 정적 토큰 검사의 대상이 될 수 없다 — 그 이행 여부는 검수의 몫이다).
# 전수 증명이 아니다.
#
# T31-8(2026-09-11, 보고 중복·비개발자 보고 지침 신설 후속)은 대상이 다시
# rules/workflow/role-separation.md 로 돌아온다 — 「공통 규칙」 첫 항목이 사용자용 보고를
# 중복 지시하던 문장("각 단계의 산출물…을 사용자에게 보고한다")을, 메인 세션이 단계마다
# 한 번만·비개발자 기준으로 쓰는 보고 계약으로 치환한 부분을 고정한다. 검사 형태와 한계는
# T31-6·T31-7 과 같다 — 리터럴 토큰 4종의 존재만 보고, 세션이 그 문구를 실제로 지키는지는
# 검수의 몫이다.
#
# T31-9(2026-10-01, K6 증분 판정과 검수자 지침 개정 — docs/prps/t37-incremental-k6.md §12)도 대상이
# rules/workflow/role-separation.md 다 — 3단계의 「전체 검증은 메인 세션이 커밋 직전에 1회 돌린다」
# 한 항목을 고정한다. 검수자가 전체 스위트를 내려놓은 뒤에는 그 의무가 이 항목에만 적혀 있다(에이전트
# 파일은 검수자 컨텍스트에만 실리고 메인 세션이 읽는 것은 상시 규칙이다). 검사 형태와 한계는 T31-6~T31-8
# 과 같다 — 리터럴 토큰 하나의 존재만 보고, 메인 세션이 그 의무를 실제로 이행하는지는 검수의 몫이다.
#
# T31-10(docs/prps/harness-benchmark-adoption.md §9-3)은 대상이 agents/ 의 frontmatter 다 — 세 작업
# 에이전트의 tools 에 정식 이름 Agent 가 있고 옛 이름 Task·괄호 목록 Agent(…) 가 없는지, effort 줄이 허용 값인지,
# explore 가 omitClaudeMd: true 이고 effort 줄이 없는지를 본다. frontmatter 범위는 첫 --- 쌍 사이로
# 자른다. 새 가드는 원장에 변조행이 아니라 면제행으로 등록했다 — 사용자 결정(2026-10-08, 전체 검사
# 시간 보호)이고, 대신 「일부러 깨뜨려 실패 확인」을 구현 시 수동 1회 했다(같은 문서 §10-3).
# 한계 — 존재·값 형식만 보는 정적 검사다. 값 자체(예: effort 를 high 에서 max 로)의 변경, tools 에
# 다른 도구를 슬쩍 더하는 편집, 런타임이 그 키를 실제로 해석하는지(옛 CLI 는 무시할 수 있다)는
# 보지 못한다. 위양성이 나면 고칠 것은 대상 파일이 아니라 이 검사의 패턴이다.
#
# T31-11(같은 문서 §9-3)은 검수·구현 보고의 증거 계약을 고정한다 — 검수자 지적의 재현 칸([재현]) ·
# 구현자 보고를 미검증 주장으로 받는 순서 · FAIL 사유 범주 · /code-review 커맨드의 Reproduction 요구
# · 구현자의 사전 조건·RED 실행 명령·계획 리마인더. (경로, 토큰) 쌍은 이 함수 안의 지역 배열이다
# (최상위 배열은 증분 K6 를 전체 재확인으로 바꾸므로 피했다). 등록 방식·한계는 T31-10 과 같다 —
# 토큰의 존재만 보고, 같은 뜻을 다른 낱말로 되돌리는 편집이나 토큰은 두고 의미를 뒤집는 편집,
# 에이전트가 계약을 실제로 지키는지는 보지 못한다. 위양성이 나면 고칠 것은 대상 문단이 아니라
# 이 토큰 목록이다.
test_rules_workflow_guardrails() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T31"
  local test_desc="워크플로우 지침 고정 래칫 (T31-1~T31-11)"
  log_test_name "$test_name" "$test_desc"

  # ---- T31-1: rules/workflow/ 4파일 존재 — 파일명 리터럴 고정, 개명·누락이 곧 실패 ----
  local workflow_file
  for workflow_file in role-separation.md model-routing.md code-quality-baseline.md \
    project-instructions-checklist.md; do
    if [[ ! -f "$REPO_ROOT/rules/workflow/$workflow_file" ]]; then
      note_failure "T31-1: rules/workflow/$workflow_file 미존재"
    fi
  done

  # ---- T31-2: workflow 파일에 paths: frontmatter 없음 — launch 로드가 설계의 성립 조건 ----
  local paths_frontmatter_hits
  paths_frontmatter_hits=$(grep -lE '^paths:' "$REPO_ROOT"/rules/workflow/*.md 2> /dev/null || true)
  if [[ -n "$paths_frontmatter_hits" ]]; then
    note_failure "T31-2: rules/workflow/ 에 paths: frontmatter 가 있음(조건부 로드로 전락) — $paths_frontmatter_hits"
  fi

  # ---- T31-3: install.sh 에 $REPO_ROOT/CLAUDE.md 리터럴 0건 — CLAUDE.md 배포 부활 차단.
  # 은퇴 로직은 레포 원본을 읽지 않는다(대장·센티널 판정이므로) — 이 0건이 성립하는 이유.
  if grep -qF '$REPO_ROOT/CLAUDE.md' "$INSTALL_SCRIPT"; then
    note_failure "T31-3: install.sh 에 \$REPO_ROOT/CLAUDE.md 리터럴이 남아있음 — CLAUDE.md 배포 부활 의심"
  fi

  # ---- T31-4: .claude/rules 가 이 레포에 커밋되지 않음 — 자기 설치 방지(이중 로드 재발 차단) ----
  local self_installed_rules
  self_installed_rules=$(cd "$REPO_ROOT" && git ls-files .claude/rules 2> /dev/null || true)
  if [[ -n "$self_installed_rules" ]]; then
    note_failure "T31-4: .claude/rules 가 레포에 커밋됨(자기 설치 의심) — $self_installed_rules"
  fi

  # ---- T31-5: 루트 CLAUDE.md 에 '전역 개발 지침' 0건 — 전역 지침으로의 회귀 차단 ----
  if grep -qF '전역 개발 지침' "$REPO_ROOT/CLAUDE.md"; then
    note_failure "T31-5: 루트 CLAUDE.md 에 '전역 개발 지침' 문구가 남아있음 — 전역 지침으로 회귀"
  fi

  # ---- T31-6 (A5, tests-hardening PRP §9): model-routing 의 A/B 실험 인용 문단이 감사
  # 이후 **수축된 상태**로 남아 있는지 본다. 원 감사(full-audit-2026-08 의 `model-facts`,
  # CONFIRMED)가 지적한 것은 과대 서술 두 개였다 — 검출이 서로 겹치지 않았다는 재현율
  # 쪽 주장과 "메인 세션 = opus" 라는 모델 특정이 둘 다 인용 원문에 없었다. 검수자가 사건의
  # 방향이 반대(독립 심판이 메인 세션의 접지 판단을 사후 교정한 관찰 1건)임을 밝혀 문단이
  # 지금 문안으로 줄었다. 아래 세 토큰이 그 수축 결과의 뼈대다 — 표본 크기(n=1) · 재현율
  # 쪽 주장을 부인하는 절 · 심판이 교정한 대상(접지 판단). 하나라도 사라지면 문단이 과대
  # 서술로 되돌아갔을 가능성이 있다. 원 앵커는 docs/prps/full-audit-2026-08.md:346 이고,
  # 그것이 CLAUDE.md:154 를 거쳐 rules/workflow/model-routing.md 로 두 번 옮겨온 경위는
  # PRP §19-1 에 있다(워크플로우 규칙 분리 때 함께 이동했다).
  local quote_contract_token
  for quote_contract_token in "n=1" "재현율 주장" "접지 판단"; do
    if ! grep -qF -- "$quote_contract_token" "$REPO_ROOT/rules/workflow/model-routing.md"; then
      note_failure "T31-6: rules/workflow/model-routing.md 에 인용 계약 토큰 '$quote_contract_token' 이 없음(A/B 실험 인용이 과대 서술로 되돌아갔을 수 있다)"
    fi
  done

  # ---- T31-7 (2026-09-11 허브 카드/트리 통합 설계 사고 후속): design-architect 에 심은
  # 「화면이 바뀌는 설계에는 프리뷰 목업을 함께 낸다」절이 조용히 빠지거나 핵심 요구만
  # 빠지는 회귀를 막는다. 대상은 rules/workflow 가 아니라 agents/design-architect.md 다
  # (그룹 머리 주석 참고). 아래 세 토큰이 그 절의 뼈대다 — 절 제목(프리뷰 목업) · 「현재」
  # 와 「제안」을 나란히 두라는 대조 요구 · 목업 전용 장치 격리 접두(.mock-). 하나라도
  # 사라지면 절 전체 또는 핵심 요구 하나가 삭제됐을 가능성이 있다(그룹 머리 주석의 T31-7
  # 한계 절 참고 — 목업을 실제로 만들었는지는 검사하지 못한다).
  local preview_mockup_token
  for preview_mockup_token in "프리뷰 목업" "「현재」와 「제안」을 나란히" ".mock-"; do
    if ! grep -qF -- "$preview_mockup_token" "$REPO_ROOT/agents/design-architect.md"; then
      note_failure "T31-7: agents/design-architect.md 에 프리뷰 목업 지침 토큰 '$preview_mockup_token' 이 없음(화면이 바뀌는 설계에 목업을 요구하는 절이 삭제됐거나 축소됐을 수 있다)"
    fi
  done

  # ---- T31-8 (보고 중복·비개발자 보고 지침 신설): 「공통 규칙」의 보고 계약이 조용히
  # 옛 문장(각 단계 산출물을 사용자에게 보고)으로 되돌아가거나 요건 하나만 빠지는 회귀를
  # 막는다. 아래 네 토큰이 그 계약의 뼈대다 — 저자·횟수(단계마다 한 번만) · 수신자 기준
  # (비개발자) · 승인 게이트 요구(승인하면 무슨 일이 일어나는지) · 제목 금지(난이도를
  # 가리키는 제목). 하나라도 사라지면 요건 하나가 삭제됐을 가능성이 있다(그룹 머리 주석의
  # 정적 토큰 검사 한계 절이 그대로 적용된다).
  local report_contract_token
  for report_contract_token in "단계마다 한 번만" "비개발자" "승인하면 무슨 일이 일어나는지" \
    "난이도를 가리키는 제목"; do
    if ! grep -qF -- "$report_contract_token" "$REPO_ROOT/rules/workflow/role-separation.md"; then
      note_failure "T31-8: rules/workflow/role-separation.md 에 보고 계약 토큰 '$report_contract_token' 이 없음(사용자용 보고를 메인이 한 번만·비개발자 기준으로 쓰라는 요건이 삭제됐거나 축소됐을 수 있다)"
    fi
  done

  # ---- T31-9 (K6 증분 판정·검수자 지침 개정): 「전체 검증은 메인 세션이 커밋 직전에 1회 돌린다」는
  # 의무가 조용히 압축·삭제되는 회귀를 막는다. 검수자가 전체 스위트를 내려놓은 뒤(agents/
  # code-reviewer.md·commands/code-review.md 개정)에는 이 문장이 그 의무의 유일한 자리다. 아래 토큰
  # 하나가 그 문장의 뼈대다 — 사라지면 의무가 삭제됐거나 「커밋 전에」처럼 시점이 흐려졌을 수 있다
  # (그룹 머리 주석의 정적 토큰 검사 한계가 그대로 적용된다).
  local commit_gate_token="커밋 직전에 1회"
  if ! grep -qF -- "$commit_gate_token" "$REPO_ROOT/rules/workflow/role-separation.md"; then
    note_failure "T31-9: rules/workflow/role-separation.md 에 전체 검증 의무 토큰 '$commit_gate_token' 이 없음(검수자가 전체 스위트를 내려놓은 뒤 메인 세션이 커밋 직전에 전체를 돌린다는 의무가 삭제됐거나 시점이 흐려졌을 수 있다)"
  fi

  # ---- T31-10 (docs/prps/harness-benchmark-adoption.md §9-3): 서브에이전트 frontmatter 계약.
  # (a) 세 작업 에이전트의 tools 에 정식 이름 Agent 가 있고 옛 이름 Task 와 괄호 목록 Agent(…) 가
  # 없다. 서브에이전트 정의에서는 Agent(타입) 허용 목록이 무시된다(Claude Code 문서 sub-agents 의
  # Agent(agent_type) 절 — 그 문법은 claude --agent 로 메인 스레드를 돌릴 때만 적용된다) — 그래서 제한처럼
  # 보이는 괄호 표기를 남기지 않는다. 표기 일관성 가드일 뿐 스폰이 기계로 막힌다는 보증이 아니다(「Explore 만
  # 띄운다」는 본문 지침이다) · (b) 같은 세 파일에 effort 줄이 있고 값이
  # 허용 집합 안이다(값 자체는 잠그지 않는다 — 조정은 설계 결정이다) · (c) explore 는
  # omitClaudeMd: true 이고 effort 줄이 없다(haiku 에는 effort 레벨이 없다). frontmatter 는 첫
  # --- 쌍 사이만 본다 — 본문에 같은 낱말이 있어도 대상이 아니다. 한계는 그룹 머리 주석 참고.
  local spawn_agent_name agent_frontmatter agent_tools_line agent_tool_tokens agent_legacy_spawn_tokens
  for spawn_agent_name in design-architect implementer code-reviewer; do
    agent_frontmatter=$(awk '/^---$/ { fence_count++; next } fence_count == 1 { print } fence_count >= 2 { exit }' \
      "$REPO_ROOT/agents/${spawn_agent_name}.md" 2> /dev/null || true)
    agent_tools_line=$(grep -E '^tools:' <<< "$agent_frontmatter" || true)
    agent_tool_tokens=$(tr ',' '\n' <<< "${agent_tools_line#tools:}" | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')
    if ! grep -qx 'Agent' <<< "$agent_tool_tokens"; then
      note_failure "T31-10: agents/${spawn_agent_name}.md frontmatter 의 tools 에 정식 이름 Agent 가 없음(하위 에이전트를 부르는 도구 표기가 빠졌다)"
    fi
    agent_legacy_spawn_tokens=$(grep -E '^(Task|Agent\(.*)$' <<< "$agent_tool_tokens" || true)
    if [[ -n "$agent_legacy_spawn_tokens" ]]; then
      note_failure "T31-10: agents/${spawn_agent_name}.md frontmatter 의 tools 에 옛 이름 Task 또는 괄호 목록 Agent(…) 가 있음(서브에이전트 정의에서는 괄호 목록이 무시된다) — $agent_legacy_spawn_tokens"
    fi
    if ! grep -qE '^effort: (low|medium|high|xhigh|max)$' <<< "$agent_frontmatter"; then
      note_failure "T31-10: agents/${spawn_agent_name}.md frontmatter 에 effort 줄이 없거나 허용 값(low|medium|high|xhigh|max)이 아님(서브에이전트 effort 가 세션 값 복제로 되돌아간다)"
    fi
  done
  local explore_frontmatter
  explore_frontmatter=$(awk '/^---$/ { fence_count++; next } fence_count == 1 { print } fence_count >= 2 { exit }' \
    "$REPO_ROOT/agents/explore.md" 2> /dev/null || true)
  if ! grep -qxF 'omitClaudeMd: true' <<< "$explore_frontmatter"; then
    note_failure "T31-10: agents/explore.md frontmatter 에 omitClaudeMd: true 가 없음(탐색 에이전트가 CLAUDE.md 계층을 디스패치마다 다시 싣는다)"
  fi
  if grep -qE '^effort:' <<< "$explore_frontmatter"; then
    note_failure "T31-10: agents/explore.md frontmatter 에 effort 줄이 있음(haiku 에는 effort 레벨이 없어 값이 무의미하다)"
  fi

  # ---- T31-11 (docs/prps/harness-benchmark-adoption.md §9-3): 검수·구현 보고의 증거 계약 토큰.
  # (경로, 토큰) 쌍의 그룹 안 지역 평탄 배열이다 — 최상위 배열(PATCH_CONTRACT_PAIRS)이 아니라 여기
  # 두는 이유는 최상위 배열을 바꾸면 증분 K6 가 전체 재확인으로 바뀌기 때문이다(설계 D6). 토큰은
  # 계약의 뼈대다 — 검수 지적의 재현 칸 · 구현자 보고를 미검증 주장으로 받는 순서 · FAIL 사유 범주 ·
  # 커맨드 쪽 재현 요구. 하나라도 사라지면 그 요구가 삭제됐거나 옛 「수정안 제안」 양식으로
  # 되돌아갔을 수 있다(그룹 머리 주석의 정적 토큰 검사 한계가 그대로 적용된다).
  local evidence_contract_pairs=(
    "agents/code-reviewer.md"   "[재현]"
    "agents/code-reviewer.md"   "미검증 주장"
    "agents/code-reviewer.md"   "사유 범주"
    "commands/code-review.md"   "Reproduction"
    "agents/implementer.md"     "사전 조건"
    "agents/implementer.md"     "RED 실행 명령"
    "agents/implementer.md"     "계획 리마인더"
  )
  local evidence_pair_index
  for ((evidence_pair_index = 0; evidence_pair_index < ${#evidence_contract_pairs[@]}; evidence_pair_index += 2)); do
    if ! grep -qF -- "${evidence_contract_pairs[evidence_pair_index + 1]}" \
      "$REPO_ROOT/${evidence_contract_pairs[evidence_pair_index]}"; then
      note_failure "T31-11: ${evidence_contract_pairs[evidence_pair_index]} 에 증거 계약 토큰 '${evidence_contract_pairs[evidence_pair_index + 1]}' 이 없음(재현 의무·미검증 주장 순서·사유 범주 요구가 삭제됐거나 옛 수정안 양식으로 되돌아갔을 수 있다)"
    fi
  done

  finish_group "$test_name"
}

# T32(PRP audit-remediation R3 — F-1·F-2·F-6 이빨 ③, 검수 R3 2회차 지적 ⑧⑨⑬ ·
# 3회차 지적 ③(T32-7 카운트→블록 귀속)으로 갱신):
# LICENSE·NOTICE.md 신설과, NOTICE.md 가 담아야 하는 상류·제3자 고지 토큰을 고정하는
# 래칫이다. §5(로컬 패치 정본 목록)의 재동기화 규칙이 "사람 절차"라면 이 그룹은 그
# 규칙을 사람이 안 지켜도 잡아내는 "기계 강제" 쪽이다 — 재동기화나 실수로 두 파일이나
# 그 안의 토큰이 지워지면 다른 어떤 그룹도 아닌 이 그룹이 잡는다.
#
# 2회차 지적으로 갱신한 것 3가지:
#  (a) T32-2 는 원래 'MIT' 단일 토큰이었는데, MIT 면책 문단의 'LIMITED' 안에도
#      부분일치해(L-I-**MIT**-E-D) LICENSE 1행의 제목이 통째로 다른 문자열로
#      바뀌어도 면책 문단만 남아 있으면 통과했다(검수 실측: `perl -i -pe 's/MIT
#      License/XXX License/ if $. == 1' LICENSE` 후 31/31 그린). 'MIT License'
#      (제목 2단어)로 좁혀 이 우회를 막는다.
#  (b) T32-4 의 URL 앵커를 상류의 현재 정칭 `https://github.com/affaan-m/ECC` 로
#      갱신했다(§2 참조). 구 슬러그 `everything-claude-code` 는 리다이렉트로 살아
#      있지만, 이 검사는 URL 문자열이 파일에 있는지만 보는 정적 검사라 리다이렉트가
#      끊기는 시점(제3자가 그 슬러그를 재사용하는 새 저장소를 만드는 시점)을 스스로
#      감지하지 못한다 — 그래서 항상 지금 시점에 유효한 정칭을 앵커로 쓴다.
#  (c) T32-7~T32-9 신설: 기존 4토큰('MIT License'·URL·'Affaan Mustafa'·'lucide')은
#      전부 제목·URL·이름류라, 허가 고지 **본문**(의무 조항)이나 면책 문단이
#      통째로 삭제돼도 걸리지 않았다. T32-8 은 lucide ISC 블록의 고유 문구, T32-9 는
#      Feather 저작권 고지 줄 자체(단독 'Cole Bemis' 토큰은 §6 매핑 표에도 2회 더
#      나타나 저작권 줄만 지워져도 그 두 표 행 때문에 통과해버리므로 앵커로 못 쓴다
#      — 실측).
#
#      T32-7 은 ECC-MIT·Feather-MIT 두 블록 각각에 허가 고지 문장("shall be included
#      in all")이 귀속되는지를 본다 — **블록 귀속**이다(검수 R3 3회차 지적 ③ 반영).
#      최초 버전은 문서 전체에서 그 문장의 등장 횟수(==2)만 셌는데, 그 방식에서
#      곧바로 따라오는 한계가 있었다 — §6 에 제3자 MIT 고지가 정상적으로 하나 더
#      늘기만 해도(예: 다른 아이콘·글꼴 자산 추가) 등장이 3이 되어 위양성으로
#      실패한다. 정상적인 성장에서 검사가 빨개지면 정비자가 상수를 3·4·…로 계속
#      올리거나 검사 자체를 지우기 쉽고, 그 시점에 이 이빨은 영구히 빠진다 — 검사가
#      컴플라이언스를 더 잘 지키는 방향에서 실패하는 셈이다. 블록 귀속은 카운트가
#      아니라 "각 저작권 줄(T32-5·T32-9 가 이미 고정하는 앵커)이 속한 펜스 블록
#      안에 같은 허가 고지 문장이 있는가"를 보므로, 제3 블록이 몇 개 늘어나도
#      영향받지 않는다.
#
#      블록 귀속에서 곧바로 따라오는 한계: 이 검사는 각 저작권 줄이 "속한 펜스
#      블록 안"만 보므로, 두 저작권 줄이 같은 블록에 있거나 펜스 밖에 있으면
#      귀속 판정 자체가 성립하지 않는다 — 지금 NOTICE.md 구조(각 고지가 자기
#      펜스 블록 안에 있음)에서만 유효하다. 비망라 예시: 이 구조가 바뀌어 두
#      고지가 펜스 없이 나란히 적히면 이 검사는 "블록 없음"으로 판정해 실패한다
#      (조용한 통과는 아니다). 전수 증명이 아니다 — 펜스 블록 구조에 의존하지
#      않는 다른 형태의 삭제·치환까지 모두 잡는다는 뜻은 아니다.
#
# T32-10 (신설, rules-docs-sync 묶음 1 — §21-7 항목 6): T32-4 가 상류의 현재 정칭
# 존재를 보는 것의 짝으로, 배포 트리(rules/·agents/·commands/)에 상류 구 슬러그
# (`everything-claude-code`)가 남아 있지 않은지 본다. 기제는 세 디렉토리에 대한 재귀
# 리터럴 문자열 검색이다 — 그 기제에서 따라오는 한계는 문자열 일치에 갇힌다는 것이다:
# 슬러그를 URL 형태가 아니라 산문으로만(예: "개명 전 저장소") 가리키는 새 문장은 이
# 검사를 피해 간다. 비망라 예시 — 이 저장소가 NOTICE.md 처럼 개명 이력을 조회 근거와
# 함께 남기는 각주를 배포 트리 쪽에도 추가하면, 이 검사는 그 각주와 실제 되돌림을
# 구분하지 못하고 똑같이 실패로 잡는다(§10 R1 과 같은 위양성 형태 — 그때는 이 검사의
# 스캔 범위를 좁혀야 한다). 전수 증명이 아니다 — 위 세 디렉토리 밖에 새 배포 경로가
# 생기면 이 스캔 목록에 없는 한 검사되지 않는다.
#
# T32-10 사전조건(검수 1회차 MEDIUM — 분모 없는 부정 단언, T37-11·T37-12·T37-14 와 같은
# 구조): 기제는 위 재귀 검색(grep -rl)이 인자로 받은 세 디렉토리 중 일부가 없어도, 남은
# 디렉토리에서 찾은 결과만으로 조용히 통과 판정을 낸다는 것이다 — 재현: rules/ 하나만
# 치우고 agents/·commands/ 는 그대로 둔 채 세 디렉토리 파일 수를 합쳐서만 셌더니 그
# 합계가 0 보다 커 여전히 공허 통과였다. 그래서 아래 사전조건은 세 디렉토리를 각각
# 따로 세고, 하나라도 0건이면 그 자체로 실패시킨다. 그 기제에서 따라오는 한계는, 이
# 분기 자신은 원장 변조행으로 검증되지 않는다는 것이다 — mutation_sed 는 파일 내용만
# 고치는 sed 한 줄이라 디렉토리를 사라지게 만들지 못한다(T37-11·T37-12·T37-14 가 원장
# 에서 면제행인 것과 같은 처지 — 그 3열이 `-` 다). 다만 본 단정(구 슬러그 존재 쪽)은
# 등록된 변조행으로 매 실행 검증되므로 위 선례들보다는 강한 상태다 — 선례들은 본 단정
# 자체가 원장 밖에 있다. 비망라 예시 — 세 디렉토리 모두 파일 수가 0 보다 크더라도,
# 구 슬러그가 남은 파일 하나만 권한 등으로 읽히지 않으면 이 사전조건과 본 단정이
# 함께 공허하게 통과할 수 있다(파일 노드 수만 세고 개별 파일의 읽기 가능 여부는 보지
# 않는다). 전수 증명이 아니다.
#
# 이 사전조건이 막는 구멍은 지금 다른 검사가 우연히 막고 있었다(접지 렌즈 재현) —
# rules/ 가 없어지면 T30-1(파일 수 파리티)·T22-1(설치 의존)·T26-2(바이트 예산)가 먼저
# 하드 실패해, 이 서브체크의 공허 통과 자체가 드러나지 않았다. 아래 사전조건은 그
# 우연한 의존 없이도 스스로 무는 검사로 만든다.
test_license_and_notice_guardrails() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T32"
  local test_desc="LICENSE·NOTICE.md 존재와 필수 토큰 (T32-1~T32-9) · 배포 트리 상류 구 슬러그 부재(T32-10)"
  log_test_name "$test_name" "$test_desc"

  # ---- T32-1·T32-2: 루트 LICENSE 존재 + 'MIT License' 토큰(제목 2단어 — 'MIT' 단독은
  # 면책 문단의 'LIMITED' 에 부분일치해 제목이 통째로 바뀌어도 통과한다, 검수 실측) ----
  if [[ ! -f "$REPO_ROOT/LICENSE" ]]; then
    note_failure "T32-1: LICENSE 미존재"
  fi
  if ! grep -qF "MIT License" "$REPO_ROOT/LICENSE" 2> /dev/null; then
    note_failure "T32-2: LICENSE 에 'MIT License' 토큰 없음(또는 파일 미존재)"
  fi

  # ---- T32-3~T32-6: 루트 NOTICE.md 존재 + ECC URL·저작자·lucide 토큰 3종 ----
  if [[ ! -f "$REPO_ROOT/NOTICE.md" ]]; then
    note_failure "T32-3: NOTICE.md 미존재"
  fi
  if ! grep -qF "https://github.com/affaan-m/ECC" "$REPO_ROOT/NOTICE.md" 2> /dev/null; then
    note_failure "T32-4: NOTICE.md 에 ECC URL 토큰 없음(또는 파일 미존재)"
  fi
  if ! grep -qF "Affaan Mustafa" "$REPO_ROOT/NOTICE.md" 2> /dev/null; then
    note_failure "T32-5: NOTICE.md 에 'Affaan Mustafa' 토큰 없음(또는 파일 미존재)"
  fi
  if ! grep -qiF "lucide" "$REPO_ROOT/NOTICE.md" 2> /dev/null; then
    note_failure "T32-6: NOTICE.md 에 'lucide' 토큰 없음(또는 파일 미존재)"
  fi

  # ---- T32-7: NOTICE.md 의 MIT 허가 고지 본문("shall be included in all")이
  # ECC-MIT · Feather-MIT 두 블록 각각에 귀속되는지 본다(카운트가 아니라 블록
  # 귀속 — 위 (c) 참조). 펜스 블록을 뽑아 각 저작권 줄이 속한 블록 "안"에 같은
  # 허가 고지 문장이 있는지만 확인하므로, 제3의 MIT 고지가 늘어도 무관하다. ----
  local block_attribution_output
  block_attribution_output=$(python3 - "$REPO_ROOT/NOTICE.md" <<'PYEOF'
import re
import sys

path = sys.argv[1]
try:
    with open(path, encoding="utf-8") as fh:
        text = fh.read()
except FileNotFoundError:
    text = ""

blocks = re.findall(r"```\r?\n(.*?)```", text, re.DOTALL)
PERMISSION_NOTICE_SENTENCE = "shall be included in all"


def status_for(anchor):
    matches = [block for block in blocks if anchor in block]
    if not matches:
        return "ANCHOR_MISSING"
    if not all(PERMISSION_NOTICE_SENTENCE in block for block in matches):
        return "PERMISSION_NOTICE_MISSING"
    return "OK"


print(f"BLOCKS_FOUND:{len(blocks)}")
print(f"ECC:{status_for('Copyright (c) 2026 Affaan Mustafa')}")
print(f"FEATHER:{status_for('Copyright (c) 2013-present Cole Bemis')}")
PYEOF
)
  local ecc_block_status feather_block_status
  ecc_block_status=$(grep '^ECC:' <<< "$block_attribution_output" | cut -d: -f2)
  feather_block_status=$(grep '^FEATHER:' <<< "$block_attribution_output" | cut -d: -f2)
  if [[ "${ecc_block_status:-}" != "OK" ]]; then
    note_failure "T32-7: ECC-MIT 블록('Copyright (c) 2026 Affaan Mustafa')의 허가 고지 문장 귀속 실패 — ${ecc_block_status:-상태 없음(파일 미존재 가능)}"
  fi
  if [[ "${feather_block_status:-}" != "OK" ]]; then
    note_failure "T32-7: Feather-MIT 블록('Copyright (c) 2013-present Cole Bemis')의 허가 고지 문장 귀속 실패 — ${feather_block_status:-상태 없음(파일 미존재 가능)}"
  fi

  # ---- T32-8: lucide ISC 허가 고지 본문의 ISC 고유 문구(MIT 문구와 겹치지 않는다) ----
  if ! grep -qF "Permission to use, copy, modify, and/or distribute" "$REPO_ROOT/NOTICE.md" 2> /dev/null; then
    note_failure "T32-8: NOTICE.md 에 lucide ISC 허가 고지 문구 없음(또는 파일 미존재)"
  fi

  # ---- T32-9: Feather MIT 저작권 고지 줄 자체 ----
  if ! grep -qF "Copyright (c) 2013-present Cole Bemis" "$REPO_ROOT/NOTICE.md" 2> /dev/null; then
    note_failure "T32-9: NOTICE.md 에 Feather MIT 저작권 고지 줄 없음(또는 파일 미존재)"
  fi

  # ---- T32-10 (§21-7 항목 6 — 대칭 부재 단언, 위 헤더 참조): 배포 트리에 상류 구
  # 슬러그가 남아 있지 않은지 확인한다. 어서션 범위를 rules/·agents/·commands/ 로
  # 좁힌 이유 — NOTICE.md(개명 전 이름임을 조회 근거와 함께 명시하는 자리)와
  # docs/prps/(핀된 역사)에는 구 슬러그가 정당하게 남아 있어, 저장소 전체를 보면
  # 그 둘을 오폭한다 ----
  # 사전조건(검수 1회차 MEDIUM) — 세 디렉토리를 각각 따로 세어 하나라도 스캔할 파일이
  # 없으면 실패로 본다(셋을 합친 총계만 보면 하나가 비어도 나머지가 채워 공허 통과
  # 하는 것을 재현으로 확인). 한계는 위 T32-10 헤더 주석에 적는다.
  local rules_scan_file_count agents_scan_file_count commands_scan_file_count
  rules_scan_file_count=$(find "$REPO_ROOT/rules" -type f 2> /dev/null | wc -l | tr -d ' ')
  agents_scan_file_count=$(find "$REPO_ROOT/agents" -type f 2> /dev/null | wc -l | tr -d ' ')
  commands_scan_file_count=$(find "$REPO_ROOT/commands" -type f 2> /dev/null | wc -l | tr -d ' ')
  if [[ "$rules_scan_file_count" -eq 0 || "$agents_scan_file_count" -eq 0 || "$commands_scan_file_count" -eq 0 ]]; then
    note_failure "T32-10: 사전조건 실패 — rules/·agents/·commands/ 중 스캔할 파일이 없는 디렉토리가 있음(rules=${rules_scan_file_count} agents=${agents_scan_file_count} commands=${commands_scan_file_count}) — 아래 부재 단정은 공허 통과일 수 있었다"
  else
    local old_slug_hits
    old_slug_hits=$(grep -rlF "affaan-m/everything-claude-code" "$REPO_ROOT/rules" "$REPO_ROOT/agents" "$REPO_ROOT/commands" 2> /dev/null || true)
    if [[ -n "$old_slug_hits" ]]; then
      note_failure "T32-10: 배포 트리에 상류 구 슬러그가 남아 있음 — ${old_slug_hits//$'\n'/ ; }"
    fi
  fi

  finish_group "$test_name"
}

# T33 (G1·T33-1·T33-2, docs/prps/dashboard-worktree-bash-gate.md §8.3 — 역방향 가드): commands/dashboard.md·
# hub.md 의 bash 코드 블록에 워크트리 격리 세션의 Bash 관문이 거부하는 3구문(비-$HOME 대문자
# 환경변수 읽기·셸 for·heredoc)이 다시 들어오면 실패한다(G1). 코드 블록 판정(fenced 또는 4칸 이상
# 들여쓰기)은 T22-161 의 awk 규칙을 재사용한다.
#
# T33-1·T33-2(신설, 2026-09-23 EnterWorktree 격리 메인 세션 실측, v2.1.280) — G1 과 별개의
# 거부 형태가 실측으로 드러났다: 관문이 거부하는 것은 `$HOME` 확장 자체가 아니라 python3
# **프로그램 자리**(첫 피연산자)에 실행 시점 값이 오는 형태다(`python3 "$HOME/…"` 거부,
# `python3 -- "$HOME/…"` 통과 — 관문 메시지 요지: "a computed argument goes after the
# script or --"). 대시보드 헬퍼 런처(commands/dashboard.md·rules/workflow/role-separation.md)
# 가 이 형태였고, 근본 해결로 두 파일 런처의 `python3` 뒤에 `-- ` 를 넣었다. T33-1 은 이
# 거부 형태가 재발하지 않는지(역방향 — 후속 확장으로 네 파일, 한계 10 항), T33-2 는 고친
# 런처 리터럴이 두 파일에 정확히 각 1회 있는지(정방향 고정)를 본다 — T33-2 대상은 G1 의
# dashboard.md·hub.md 쌍과 달리 런처가 실제로 사는 dashboard.md·role-separation.md 쌍이다.
#
# 대상을 commands/*.md 전체가 아니라 dashboard.md·hub.md 로 좁힌다(G1 한정) — 오탐 실측(가드를 걸기
# 전 commands/*.md 전체를 이 패턴으로 스캔) 결과 prp-implement.md 의 $ARGUMENTS·$SERVER_PID·
# $SERVER_READY·$TEST_EXIT, prp-pr.md 의 $ARGUMENTS 가 걸렸다. 이들은 Claude Code 가 실행
# 전에 텍스트로 치환하는 플레이스홀더이거나 같은 스크립트 안에서 대입되는 지역 변수라 실제
# 환경변수 읽기가 아니지만, 텍스트 패턴만으로는 "지역 대입 vs 외부 환경변수"를 구분할 수
# 없다. 이 PRP 가 실제로 손댄 두 파일로 좁히는 것이 그 구분 로직을 새로 만드는 것보다
# 단순하다(YAGNI) — 이번 변경의 목적은 dashboard.md 의 관문 거부 회귀를 잡는 것이지 다른
# 커맨드 문서의 셸 관용구를 감사하는 것이 아니다.
#
# 검수 2회차(HIGH-1·HIGH-2)로 판정 로직을 강화했다 — 원래 awk 는 (i) `$HOME`·`$dz_*`·`$DZ_*`
# 예외를 **줄 단위**로 걸어, 런처 줄처럼 `$HOME` 이 이미 있는 줄에 새 위반(`$FOO` 등)이
# 추가돼도 줄 전체가 예외 처리돼 검출하지 못했고(실측: 런처 줄 끝에 `; echo "$FOO"` 를
# 붙여도 통과), (ii) `for` 검출이 줄 시작 앵커(`^[[:space:]]*for`)라 이 문서의 지배적
# 편집 패턴인 "기존 줄에 `;` 로 이어 붙이기"(`; for x in a b; do …; done`)를 못 잡았다.
# 지금은 (i) 허용 패턴을 gsub 로 줄에서 먼저 지우고 남은 텍스트만 검사하는 **토큰 단위**
# 판정, (ii) `for` 앵커를 줄 시작 또는 세미콜론 뒤(`(^|;)[[:space:]]*for`)로 완화했다.
#
# 이 가드가 못 잡는 것(한계, 비망라, PRP §8.3 + 검수 2회차 반영 — MEDIUM-4 + T33-1·T33-2
# 신설 2026-09-23):
#   1. $(...) 는 검출 대상에 넣지 않았다 — echo "$(pwd)" 는 관문을 통과하고
#      if [ -n "$(find …)" ] 는 거부되는 등 판정이 문맥 의존이라(실측 M4·M5·M6), 텍스트
#      패턴만으로 구분할 수 없다. 전부 금지하면 통과하는 형태까지 막는 과잉 차단이 된다.
#   2. 셸 for 와 파이썬 for 를 문맥으로 구분하지 못한다 — 실측 사례: 개정 전 문서의
#      `for port in (8791, 8792, 8793):` 은 python3 -c 문자열 안의 파이썬 코드였다. 문서에
#      파이썬 루프를 다시 쓰면 오탐이 난다. 앵커 완화(위 (ii))는 세미콜론 뒤 위치를 넓힌
#      것일 뿐 이 문맥 구분 문제와는 무관하다 — 여전히 못 잡는다.
#   3. 앵커 완화(ii)의 트레이드오프 — 셸 **문자열 리터럴** 안에 `; for … in …` 형태의
#      텍스트가 그대로 등장해도(예: 에러 메시지·echo 인자) 오탐한다. 지금 두 문서에는
#      그런 문자열이 없어 기대값 0 이 성립하지만(§8.3 오탐 실측 갱신 확인 완료), 생기면
#      가드가 걸린다 — 그때는 오탐인지 실제 위반인지 판정해서 대응한다.
#   4. heredoc 의 크기 경계(관문이 몇 줄부터 거부하는지)를 모른다 — 통과하는 작은 heredoc
#      (실측 M9, 9줄)까지 전부 금지하는 과잉 차단이지만, 경계를 모르는 채로 통과를 허용하면
#      회귀를 놓치므로 의도적으로 보수적으로 잡는다.
#   5. 관문의 실제 구현을 읽지 않았다 — 위 3구문은 이 세션의 관측(M1~M16)에서 재현된
#      것이고, 관문이 바뀌면 이 가드도 낡는다.
#   6. 파일 범위가 commands/dashboard.md·hub.md 2개로 고정돼 있다(위 narrowing 문단
#      참조) — 신규 커맨드 파일에 거부 구문이 들어와도 이 for 목록에 수동으로 추가하지
#      않으면 검사 대상에서 빠진다.
#   7. HIGH-4 의 서버 기동 줄(`trap 'exit 0' TERM; python3 -m http.server …`)은 이 가드가
#      구조적으로 잡을 수 없다 — D5 결정으로 그 줄을 그대로 보존하는데, `trap` 을 거부
#      패턴에 넣으면 보존 대상인 그 줄 자체가 즉시 실패한다. 이 실패는 스위트가 아니라
#      실제 관문 거부 메시지로만 검출된다(commands/dashboard.md 의 `trap 'exit 0' TERM`
#      서버 기동 줄 참조).
#   8. 검수 3회차(G1 브레이스 검출 누락)로 브레이스 형태(`${VAR}`)를 검출에 추가하고,
#      허용 패턴도 대칭으로 넓혔다(`${HOME}`·`${dz_…}`·`${DZ_…}`, 접미 연산자
#      `:-`·`%%`·`##` 등 포함 — 뮤테이션 4종 + 두 문서 오탐 0건 실측). 다만 **허용
#      접두어 뒤에 브레이스가 중첩되면** 놓친다 — 허용 gsub 의 `[^}]*` 가 첫 `}` 까지
#      탐욕적으로 지우므로, `${DZ_FOO:-${SOME_BAD_VAR}}` 처럼 `DZ_` 뒤에 다른 브레이스
#      참조가 중첩되면 안쪽 `${SOME_BAD_VAR}` 까지 함께 지워져 검출 0건이 된다(실측:
#      사본 테스트). 지금 두 문서에는 중첩 브레이스가 없어 기대값 0 이 성립하지만,
#      생기면 이 가드를 통과한다. 같은 기제가 `HOME`·`dz_` 접두어에도 적용된다
#      (`${HOME:-${SOME_BAD_VAR}}` 도 검출 0 — 검수 3회차 실측). 반대로 허용 접두어가
#      **먼저 매치되지 않는** 중첩(`${SOME_BAD_VAR:-${OTHER}}`)은 정상 검출된다.
#   9. **이 목록은 전수가 아니다.** 검수 3회차가 목록 밖에서 두 특성을 더 실측했다:
#      (a) 백슬래시 이스케이프 `\${VAR}` 를 **오탐**한다 — 셸이 확장하지 않는 리터럴인데
#      위반으로 잡는다(과다검출이라 안전 쪽 오류다). (b) 소문자 변수(`${some_var}`)는
#      `[A-Z_]` 제약으로 애초에 대상 밖이다 — 브레이스형이 아니라 1·2회차의 평문
#      검출부터 있던 특성이고, 환경변수는 대문자·이 문서의 지역 변수는 `dz_` 소문자라는
#      관례와 일관돼 의도된 것으로 본다. 둘 다 두 문서에 0건(실측). **이 항목의 존재
#      이유는 다음 검수자가 같은 재현을 반복하지 않게 하고, 이 목록을 완결된 것으로
#      단정하지 않게 하는 것이다.**
#  10. T33-1 의 검사 대상은 2026-09-23 후속 확장으로 dashboard.md·role-separation.md·
#      hub.md·harness-update.md 4개가 됐다 — hub.md(같은 모양 `python3 "$HOME/…"` 12줄)·
#      harness-update.md(3줄)에도 같은 거부 형태가 있음이 드러나 두 파일도 `python3 -- ` 로
#      고치고 대상에 추가했다. T33-2(정방향 고정)는 여전히 dashboard.md·role-separation.md
#      2개뿐이다 — 그 둘만 런처 리터럴(DASHBOARD_LAUNCHER_CANONICAL_FORM)을 공유하고,
#      hub.md·harness-update.md 는 서브커맨드마다 문자열이 달라 같은 정방향 고정을 적용할
#      단일 대상이 없다. hub.md·harness-update.md 의 `-- ` 형태는 dashboard_helper.py 경로로
#      잰 M16 관찰(python3 프로그램 자리에 계산값이 오면 거부)에 기댄 것이고, hub.py
#      경로로 따로 재측정하지는 않았다 — 같은 정적 규칙이 다른 스크립트 경로에도
#      적용된다는 추론이다.
#  11. hub.md 의 훅·statusLine 명령 문자열 2줄(install-hooks/install-statusline 이 기록하는
#      실행 문자열)은 Bash 도구가 아니라 훅 실행기·statusLine 실행기가 그대로 실행하고
#      글자 단위 동일성 자체가 설치 판정의 키라 고치지 않는다 — 그래서 이 두 줄은 T33-1
#      패턴에 계속 걸린다. 지금은 `# DZH_HUB_HOOK`·`# DZH_HUB_STATUSLINE` 마커(hub_settings.py
#      의 HOOK_MARKER·STATUSLINE_MARKER 와 같은 문자열)가 붙은 줄만 걸러 세지 않는다.
#      한계 — 이 필터는 마커 문자열로만 줄을 가린다. 그래서 이 두 마커 중 하나를 우연히
#      포함하는 **다른** Bash 도구 런처 줄이 생기면(마커는 지금 훅·statusLine 전용으로
#      예약된 의미다) 이 가드가 그 줄도 함께 놓친다.
#  12. T33-1·T33-2 도 5 와 같은 근거를 공유한다 — 관문 구현을 읽지 않은, 2026-09-23
#      EnterWorktree 세션의 거부·통과 관측(M1~M16)에서 귀납한 휴리스틱이라 관문 판정이
#      바뀌면 함께 낡는다.
test_dashboard_bash_gate_regression() {
  local test_name="T33"
  local test_desc="워크트리 Bash 관문 거부 구문 회귀 가드 (G1·T33-1·T33-2)"
  log_test_name "$test_name" "$test_desc"

  local target_file gate_violation_count
  for target_file in "$REPO_ROOT/hub/rules/dashboard-recording.md" "$REPO_ROOT/commands/hub.md"; do
    gate_violation_count=$(awk '
      /^[[:space:]]*```/ { fenced = !fenced; next }
      { code = fenced || /^[[:space:]]{4,}[^ ]/ }
      code {
        line = $0
        gsub(/\$HOME/, "", line)
        gsub(/\$\{HOME[^}]*\}/, "", line)
        gsub(/\$dz_[A-Za-z0-9_]*/, "", line)
        gsub(/\$\{dz_[^}]*\}/, "", line)
        gsub(/\$DZ_[A-Za-z0-9_]*/, "", line)
        gsub(/\$\{DZ_[^}]*\}/, "", line)
        if (line ~ /\$[A-Z_]{2,}/ || line ~ /\$\{[A-Z_]{2,}/) count++
      }
      code && (/^[[:space:]]*for[[:space:]]+[A-Za-z_][A-Za-z0-9_]*[[:space:]]+in[[:space:]]/ || /;[[:space:]]*for[[:space:]]+[A-Za-z_][A-Za-z0-9_]*[[:space:]]+in[[:space:]]/) { count++ }
      code && /<</ { count++ }
      END { print count + 0 }
    ' "$target_file")
    if [[ "$gate_violation_count" -ne 0 ]]; then
      record_failure "$test_name" "G1: $target_file 의 bash 코드 블록에 관문 거부 구문이 ${gate_violation_count}건 있음(비-\$HOME 환경변수·셸 for·heredoc)"
      return 1
    fi
  done

  # T33-1(역방향, docs/prps/dashboard-into-hub.md M1 로 다섯 파일째 hub/README.md 추가) —
  # python3 프로그램 자리(첫 피연산자)에 실행 시점 값이 오는 형태(예: `python3 "$HOME/…"`)가
  # 다섯 파일 전체 텍스트(코드 블록 제한 없음, 위 T33-1·T33-2 신설 문단·한계 10 항 참고)
  # 어디에도 없어야 한다. `python3 -- "$HOME/…"`·`python3 /literal/…` 는 이 패턴에 걸리지 않는다.
  #
  # hub.md 의 훅·statusLine 명령 문자열 2줄(`# DZH_HUB_HOOK`·`# DZH_HUB_STATUSLINE` 마커,
  # 위 한계 11 항 참고)은 의도적으로 고치지 않아 이 패턴에 계속 걸리므로, 마커가 붙은
  # 줄만 걸러 세지 않는다.
  local computed_arg_pattern='python3([[:space:]]+-[A-Za-z]+)*[[:space:]]+"?\$'
  local hook_marker="# DZH_HUB_HOOK"
  local statusline_marker="# DZH_HUB_STATUSLINE"
  local computed_arg_file computed_arg_hits
  for computed_arg_file in "$REPO_ROOT/hub/rules/dashboard-recording.md" "$REPO_ROOT/rules/workflow/role-separation.md" "$REPO_ROOT/commands/hub.md" "$REPO_ROOT/commands/harness-update.md" "$REPO_ROOT/hub/README.md"; do
    computed_arg_hits=$(grep -E "$computed_arg_pattern" "$computed_arg_file" | grep -vcF -e "$hook_marker" -e "$statusline_marker") || true
    if [[ "$computed_arg_hits" -ne 0 ]]; then
      record_failure "$test_name" "T33-1: $computed_arg_file 에 python3 프로그램 자리에 계산값이 오는 형태가 ${computed_arg_hits}건 있음(워크트리 격리 관문이 거부한다 — python3 -- 를 쓴다)"
      return 1
    fi
  done

  # T33-2(정방향 고정) — DASHBOARD_LAUNCHER_CANONICAL_FORM 이 두 파일 각각에 정확히 1회
  # 있어야 한다. 절대경로 리터럴로 "고치거나" `--` 를 지우는 변경이 여기서 걸린다.
  local launcher_file launcher_hits
  for launcher_file in "$REPO_ROOT/hub/rules/dashboard-recording.md" "$REPO_ROOT/hub/README.md"; do
    launcher_hits=$(grep -cF -- "$DASHBOARD_LAUNCHER_CANONICAL_FORM" "$launcher_file") || true
    if [[ "$launcher_hits" -ne 1 ]]; then
      record_failure "$test_name" "T33-2: $launcher_file 의 런처 문자열이 정확히 1회가 아님(실제 ${launcher_hits}건 — 워크트리 격리 관문이 python3 프로그램 자리의 계산값을 거부한다, python3 -- 형태를 지켜야 한다)"
      return 1
    fi
  done

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T34 (G2, docs/prps/dashboard-worktree-bash-gate.md §8.3 — 정합 가드, dashboard-native-data-source
# PRP 로 재작성, docs/prps/dashboard-into-hub.md M1 로 대상 재조준, M2 로 서브커맨드
# 재조준): hub/README.md 의 「헬퍼 스크립트」 표와 hub/bin/hub_dashboard_log.py 의 실제
# 디스패치가 일치한다(옛 commands/dashboard.md·commands/dashboard_helper.py 시절 만들어진
# 그룹이다). 서브커맨드 10종 → 5종 → 4종(init·log·step·switch, DN3·DN8·DN9·M2 HD15 —
# render·ANCHOR-FAIL 폐기)으로 줄고, URL 템플릿(자동 발행 폐기, DN8)은 더 이상 검사
# 대상이 아니다.
#
# 한계(비망라) — 검수 1회차 H1 이 지적한 행 단위 대응 검사(T34-1·T34-2, render 서브커맨드가
# ANCHOR-FAIL 을 낼 수 있는 유일한 행이었다)는 그 서브커맨드 자체가 M2 에서 폐기되며 대상을
# 잃어 함께 제거됐다. 남은 검사는 여전히 합본 검색이라 표·헬퍼 어디에도 그 문자열이
# "존재하는가"만 보고 "어느 행에 있어야 하는가"는 보지 않는다. 헬퍼가 어휘를 올바른
# 조건에서 출력하는지는 tests/hub/test_hub_dashboard_log.py 의 단위 테스트만이 확인한다.
test_dashboard_helper_table_dispatch_parity() {
  local test_name="T34"
  local test_desc="헬퍼 스크립트 표 ↔ 실제 디스패치 정합 (G2)"
  log_test_name "$test_name" "$test_desc"

  local dashboard_command_file="$REPO_ROOT/hub/README.md"
  local dashboard_helper_file="$REPO_ROOT/hub/bin/hub_dashboard_log.py"
  local dashboard_render_file="$REPO_ROOT/hub/bin/hub_dashboard_render.py"

  # 서브커맨드 4종 — 표에 있고(정방향) 디스패치에도 있다. G2 접두는 T34-3·T34-4 로
  # ID 승격됐다(docs/prps/dashboard-into-hub.md §14.1 — 원장 앵커 없는 산문 접두를 없앤다).
  local subcommand
  for subcommand in init log step switch; do
    if ! grep -qF "\`$subcommand\`" "$dashboard_command_file"; then
      record_failure "$test_name" "T34-3: 「헬퍼 스크립트」 표에 서브커맨드 미발견: $subcommand"
      return 1
    fi
    if ! grep -qF "subcommand == \"$subcommand\"" "$dashboard_helper_file"; then
      record_failure "$test_name" "T34-4: hub_dashboard_log.py 디스패치에 서브커맨드 미발견: $subcommand"
      return 1
    fi
  done

  # 역방향 — 디스패치 분기 수가 표의 서브커맨드 수(4)와 같다. 다르면 표에 없는 서브커맨드가
  # 디스패치에 몰래 추가된 것이다.
  local dispatched_count
  dispatched_count=$(grep -cE '(if|elif) subcommand ==' "$dashboard_helper_file")
  if [[ "$dispatched_count" -ne 4 ]]; then
    record_failure "$test_name" "T34-5: 디스패치 분기 수($dispatched_count) != 표의 서브커맨드 수(4)"
    return 1
  fi

  # 폐쇄 어휘 10종 — 표에 등장하는 어휘가 기록기(순수 층 포함) 안에 문자열로 존재한다.
  local vocab
  for vocab in OK NOSESSION DISABLED MKDIR-FAILED NOINIT BADKIND BADINDEX \
    ON OFF INVALID-SETTINGS; do
    if ! grep -qF -- "$vocab" "$dashboard_helper_file" "$dashboard_render_file"; then
      record_failure "$test_name" "T34-6: 폐쇄 어휘가 기록기에 없음: $vocab"
      return 1
    fi
  done

  log_ok "$test_name 통과"
  ((passed_tests++))
}

# T35 (결함 재발 방지 — commands/ 에 .py 소스가 생긴 뒤로 도달 가능해진 배포 결함, 사용자 실측
# 재현 + 2회차 검수 반영): __pycache__ 계열 바이트코드 파생물이 배포
# (copy_directory_contents)·대장(build_files_ledger_json)·로그 개수(install_directory 의
# outdated_count, list_missing/differing_managed_files 경유) 세 경로 중 어디로도 새지 않는지
# 확인하고, 그 배제 기제(cp -R 후 remove_pycache_from_target_directory 로 정리)가 진짜
# 실패(소스 누락)의 return 1 전파를 막지 않는지도 함께 확인한다.
#
# commands/__pycache__ 는 실제 py_compile 산출물로 재현한다(빈 파일 흉내는 find/diff 의
# 실제 동작을 검증하지 못한다).
#
# 2회차 갱신 — copy_directory_contents 가 find 기반 개별 복사에서 cp -R + 사후
# __pycache__ 제거로 되돌아갔다: 1회차의 "find 기반 배제 복사" 서술은 그래서 더 이상
# install.sh 를 가리키지 않는다.
#  - T35-5: list_differing_managed_files 의 -x __pycache__ 가 실제로 관측 가능한 차이를
#    만드는 유일한 경로(재설치 시 대상·소스 양쪽에 이름은 같고 내용이 다른 __pycache__
#    항목이 있는 경우)를 재현한다. 새 sandbox 에 1회만 설치해서는 이 경로에 닿지 않는다
#    — 그때는 소스에만 있어 항상 "Only in source"로만 나타난다(list_missing 쪽 경로이지
#    list_differing 쪽이 아니다, 2회차 검수 실측).
#  - T35-6: 소스 디렉토리 자체가 없을 때 실패하는지 확인한다(1회차 Critical 1 재현
#    방지). 글롭 메타문자 경로(1회차 Critical 2)는 검사하지 않는다 — 그 결함은
#    개별 파일의 상대경로를 문자열로 재구성하던 코드에서만 발생했는데
#    copy_directory_contents 가 cp -R 로 되돌아가며 그 코드 자체가 사라졌다. 존재하지
#    않는 코드 경로를 겨냥한 회귀 테스트는 의미가 없어 추가하지 않았다.
#    갱신(shell-hardening PRP, S1 검수 1회차 m2 반영) — 이 시나리오는 이제 cp -R 이전에
#    check_no_symlink_targets 의 관리 파일 열거(find)에서 더 일찍 잡힌다(find 가 사라진
#    rules/ 인자에서 부분 실패하고, 그 실패를 이제는 fail-closed 로 반영한다 — T15-2 가
#    같은 코드 경로를 등록한다). 검사 문구를 그 지점에 맞춰 갱신했다 — 이 서브체크가
#    지키려는 성질("소스 결측이 조용한 성공이 되지 않는다")은 그대로다.
#  - install.sh 호출 2곳(최초 설치·T35-5 재설치) 모두 exit code 를 먼저 확인해 이후
#    하위 검사의 전제로 삼는다 — 실패를 놓치면 이후 검사가 "애초에 아무것도 안
#    만들어졌다"는 이유로 우연히 통과할 수 있다(2회차 검수).
#
# 3회차 갱신 — remove_pycache_from_target_directory 가 find -exec 일괄 삭제에서 경로별
# 재검증(범위·이름 재확인) + 개별 rm 으로 바뀌었고, 삭제 자체가 dry-run 계획과 실제 삭제 건수
# 로그에도 나오게 됐다(3회차 검수 Major 1). 아래 네 건을 추가한다.
#  - T35-7: dry-run 계획 출력에 __pycache__ 정리 계획 문구가 나오는지.
#  - T35-8: find 검색 시작점이 실수로 한 단계 넓어져도(sed 로 install.sh 사본에 그 변경을
#    흉내낸다) 관리 대상 밖의 __pycache__ 는 지워지지 않는지 — 렌즈 C 의 3종 변조 중
#    스위트가 못 잡던 것(범위 이탈)을 겨냥한다.
#    이름 패턴이 넓어지는 나머지 하나(못 잡던 또 다른 하나)는 두 경로로 갈린다 — (i) 대상
#    디렉토리 자기 자신이 후보가 되는 경로는 그 부모가 정의상 대상 디렉토리 하위가 아니므로
#    범위 방어 분기가 이름 재확인보다 먼저 막고, (ii) 대상 안의 이름이 다른 디렉토리가 후보가
#    되는 경로는 remove_pycache_from_target_directory 자신의 이름 재확인 코드가 막는다(find
#    인자를 sed 로 바꿔야 하는 이 회귀 테스트 형태 대신, 구현 단계에는 둘 다 스크래치
#    스크립트로 확인했다 — 3회차 구현 보고 참고). ~~별도 시나리오를 추가하지 않았다.~~
#    **정정(4회차 갱신 문단, A10)**: (i)를 고정하는 시나리오를 T35-11 로 추가했다 — (ii)는
#    여전히 스크래치 확인만 있다.
#  - T35-9: 정리(rm -rf) 자체가 권한 등으로 실패해도 설치 전체는 exit 0 을 유지하고,
#    경고에 실패한 경로가 남는지(2회차 검수 Medium 2 + Minor 2).
#  - T35-10: report_global_command_overlap 의 `[[ -f ]]` 가드(2회차 검수 Medium 3)가 실제
#    로 발화하는 상황을 스위트 안에 처음 만든다 — HOME 을 오버라이드해 전역 비교 루프를
#    태우고, 전역 쪽에 __pycache__ 라는 이름의 파일을 미끼로 심어 가드가 없으면
#    디렉토리 대 파일 cmp 오류로 "differ" 오분류가 났을 상황을 재현한다.
#
# 4회차 갱신(S4, tests-hardening PRP §9 A10~A16) — remove_copied_pycache 를
# remove_pycache_from_target_directory 로 개명하고 A11~A16 을 손봤다. 아래 두 건을 추가한다.
#  - T35-11 (A10): find 의 -name '__pycache__' 가 '*' 등으로 넓어지면 대상 디렉토리 자기
#    자신도 find 의 후보가 된다 — 자기 자신의 부모는 정의상 대상 디렉토리의 하위가
#    아니므로 범위 방어 분기("범위 밖이라 건너뜀")가 이름 재확인보다 먼저 발화한다.
#    이 스위트가 부르는 실제 대상(rules·agents·commands)은 이름이 __pycache__ 가
#    아니므로 정상 코드에서는 이 분기가 발화하지 않고, $install_output 에 그 경고가
#    하나라도 있다는 것 자체가 -name 필터 폭이 달라졌다는 신호다. 이전에는 이 변조를
#    스크래치 스크립트로만 확인해 검증이 커밋되지 않았다 — 아래 원장 등록이 그 확인을
#    영구화한다. 한계(비망라) — 이 검사가 잡는 경로는 대상 디렉토리 자신이 후보가 되는
#    경로(그 부모가 항상 범위 밖이 되는 성질) 하나다. -name 이 '__pycache__*'처럼
#    대상 디렉토리의 실제 이름(rules·agents·commands)과는 무관하게 좁게 어긋나는
#    변조는, 그런 이름의 허구 후보가 이 스위트의 fixture 에 없는 한 같은 경로로
#    드러나지 않는다. 전수 증명이 아니다.
#  - T35-12 (A12, tests-hardening PRP §9 — 원장 T35-12 가 이 서브체크와 짝을 이룬다):
#    install.sh 의 remove_pycache_from_target_directory 안 `[[ -d ]] || continue` 가드(위 4회차
#    갱신 주석 참고) 회귀 검사다. 그 가드는 "평범한 중첩"이 아니라 "혼합"(대상 디렉토리 자체가
#    쓰기 금지라 자신은 못 지워도 그 rm -rf 재귀가 안의 중첩 자식은 먼저 지우는 경우)에서만
#    발화한다. target_directory 자신의 모드는 cp -R 가 옮기지 않으므로 최초 설치 한 번으로는 이
#    상태를 못 만든다 — (1) 정상 설치로 대상을 만들고, (2) 그 대상 안에 중첩 __pycache__ 를
#    직접 만든 뒤 대상 디렉토리 자체를 555 로 바꾸고, (3) 재설치한다. 가드가 없으면 이미 사라진
#    중첩 후보에 대한 rm -rf 가 "성공"을 반환해 "__pycache__ N개 정리" 줄이 헛되이 나온다 — 그
#    부재를 단언한다(555 는 재설치 로그 확인 직후 chmod -R u+w 로 되돌린다). 한계(비망라) —
#    대상 디렉토리 자체가 쓰기 금지인 경우만 겨냥한다. 그보다 깊은 중간 디렉토리 하나만 쓰기
#    금지인 변형은 같은 경로로 드러나지 않는다. 전수 증명이 아니다.
test_pycache_excluded_from_deployment() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T35"
  local test_desc="commands/__pycache__ 배포·대장·로그 배제 + 소스 누락 시 실패 전파 (재발 방지)"
  log_test_name "$test_name" "$test_desc"

  local sandbox fake_repo fake_sandbox
  local fake_repo_scope fake_sandbox_scope fake_repo_perm fake_sandbox_perm
  local overlap_project_sandbox overlap_home_sandbox
  local a12_repo a12_sandbox
  sandbox=$(mktemp -d)
  fake_repo=$(mktemp -d)
  fake_sandbox=$(mktemp -d)
  fake_repo_scope=$(mktemp -d)
  fake_sandbox_scope=$(mktemp -d)
  fake_repo_perm=$(mktemp -d)
  fake_sandbox_perm=$(mktemp -d)
  overlap_project_sandbox=$(mktemp -d)
  overlap_home_sandbox=$(mktemp -d)
  a12_repo=$(mktemp -d)
  a12_sandbox=$(mktemp -d)
  # $REPO_ROOT/commands/__pycache__ 를 스위트 끝까지 남기지 않아야 한다는 요구(2회차 검수
  # Minor 3)는 이전에는 RETURN 트랩으로 해결했다 — EXIT 트랩은 같은 시그널에 여러 번 걸리면
  # 마지막 설치만 발화하므로, 이 함수가 스위트의 마지막 실행자가 아니면 그 정리가 이후 그룹의
  # 트랩 설치에 덮여 사라졌기 때문이다. S2(tests-hardening PRP §4.3)가 함수별 trap EXIT 설치를
  # register_cleanup_path 로 바꾸면서 그 전제 자체가 사라졌다 — 통상적인 방식으로는 이
  # 파일에 전역 suite_exit_guard 외의 EXIT 트랩이 남지 않아(그 경계는 verify_trap_hygiene
  # 주석 참고) 어떤 그룹의 등록도 서로 덮어쓰지 않고, 정리는 트랩 재발화가 아니라
  # finish_group 의 명시 호출(cleanup_registered_paths)이 맡는다. 이 함수가
  # 아래에서 finish_group 을 부르는 순간 등록된 경로 전부(REPO_ROOT/commands/__pycache__
  # 포함)가 그 자리에서 정리되므로, RETURN 트랩 특유의 "함수 반환마다 호출 스택 전체에서
  # 재발화"·"재실행이 실패하는 명령을 넣으면 set -e 가 끊는다"는 두 제약은 이 트랩을
  # 지움으로써 함께 소멸한다.
  register_cleanup_path "$sandbox" "$fake_repo" "$fake_sandbox" "$fake_repo_scope" \
    "$fake_sandbox_scope" "$fake_repo_perm" "$fake_sandbox_perm" \
    "$overlap_project_sandbox" "$overlap_home_sandbox" "$a12_repo" "$a12_sandbox" \
    "$REPO_ROOT/commands/__pycache__"

  _synthesize_commands_pycache_file "$REPO_ROOT"

  if [[ ! -d "$REPO_ROOT/commands/__pycache__" ]]; then
    note_failure "T35-0: 사전조건 실패 — py_compile 로 commands/__pycache__ 를 만들지 못함(python3 미설치 가능) — 아래 검사는 공허 통과일 수 있음"
  fi

  local install_output install_exit=0
  install_output=$( cd "$sandbox" && "$INSTALL_SCRIPT" --scope project 2>&1 ) || install_exit=$?
  if [[ "$install_exit" -ne 0 ]]; then
    # 3회차 검수 Medium 1 — T35-0(독립 서브체크, note_failure)이 이미 실패해
    # group_failures 에 쌓인 게 있으면 여기 합친다. T35-0b 는 이후 전 검사의 전제라
    # 종속 서브체크 관행(record_failure + return)을 그대로 따르는데, 그러면
    # finish_group 을 거치지 않아 group_failures 가 최종 요약(failed_list)에 반영되지
    # 않고 사라진다 — 실패 총합은 정확하지만(note_failure 는 failed_tests 를 건드리지
    # 않는다) 무엇이 실패했는지가 리포트에서 빠진다.
    local reason="T35-0b: 최초 설치가 exit ${install_exit} 로 실패함 — 이후 T35-1~T35-12 전제 불성립(출력 마지막 3줄: $(tail -3 <<< "$install_output"))"
    if ((${#group_failures[@]} > 0)); then
      reason="${group_failures[0]} | $reason"
    fi
    record_failure "$test_name" "$reason"
    return 1
  fi

  # ---- T35-1 (배포 경로): 대상 commands/ 에 __pycache__ 미존재 ----
  if [[ -e "$sandbox/.claude/commands/__pycache__" ]]; then
    note_failure "T35-1: 대상에 __pycache__ 가 배포됨: $sandbox/.claude/commands/__pycache__"
  fi

  # ---- T35-1 (건수 보고, 3회차 검수 Major 1-2): 실제로 지운 게 있으면 조용히 지우지
  # 않고 건수를 로그로 남긴다. 위에서 T35-0 이 성공했다면(소스에 __pycache__ 존재) 이
  # 최초 설치는 commands/__pycache__ 를 최소 1개 정리했어야 한다.
  if [[ -d "$REPO_ROOT/commands/__pycache__" ]] \
    && ! grep -qE '__pycache__ [0-9]+개 정리' <<< "$install_output"; then
    note_failure "T35-1: 설치 로그에 __pycache__ 정리 건수 보고가 없음(기대 패턴: '__pycache__ N개 정리')"
  fi

  # ---- T35-2 (대장 경로): manifest 에 pycache 항목 0건 ----
  local manifest_file="$sandbox/.claude/.coding-harness.json"
  local pycache_ledger_hits
  pycache_ledger_hits=$(grep -c 'pycache' "$manifest_file" 2> /dev/null || true)
  if [[ "${pycache_ledger_hits:-0}" -ne 0 ]]; then
    note_failure "T35-2: 대장에 pycache 항목 ${pycache_ledger_hits}건 등재됨"
  fi

  # ---- T35-3 (로그 개수 == 실제 설치 파일 수): install.sh 의 선언 COMMANDS_FILE_COUNT 를
  # grep 으로 뽑아 실제 설치 결과와 맞춘다 — 하드코딩 상수 비교가 아니므로 commands/ 파일이
  # 정상적으로 하나 늘어 상수가 함께 갱신되면 이 검사도 그대로 따라가 위양성을 내지 않는다.
  local declared_commands actual_installed_commands
  declared_commands=$(grep -oE '^readonly COMMANDS_FILE_COUNT=[0-9]+' "$INSTALL_SCRIPT" | grep -oE '[0-9]+$')
  actual_installed_commands=$(find "$sandbox/.claude/commands" -type f 2> /dev/null | wc -l | tr -d ' ')
  if ! grep -qF "commands/  ${declared_commands}개 파일" <<< "$install_output"; then
    note_failure "T35-3: 설치 로그에 'commands/  ${declared_commands}개 파일' 문구 없음"
  fi
  if [[ "$actual_installed_commands" -ne "$declared_commands" ]]; then
    note_failure "T35-3: 선언 개수=${declared_commands}, 실제 설치 파일 수=${actual_installed_commands}"
  fi

  # ---- T35-4 (배제 기준 과잉 적용 방지): rules/ 의 정당한 하위 디렉토리 전부 배포 ----
  local declared_rules actual_installed_rules
  declared_rules=$(grep -oE '^readonly RULES_FILE_COUNT=[0-9]+' "$INSTALL_SCRIPT" | grep -oE '[0-9]+$')
  actual_installed_rules=$(find "$sandbox/.claude/rules" -type f 2> /dev/null | wc -l | tr -d ' ')
  if [[ "$actual_installed_rules" -ne "$declared_rules" ]]; then
    note_failure "T35-4: rules/ 설치 파일 수=${actual_installed_rules}, 기대=${declared_rules}(배제 기준 과잉 적용 의심)"
  fi

  # ---- T35-5 (list_differing_managed_files 경로, 2회차 검수 Major 2): 대상에 소스와
  # 이름은 같고 내용이 다른 __pycache__ 항목이 있어도(재설치 시나리오) --force 없이
  # 재설치가 성공해야 한다. diff 가 "Files … differ" 를 내려면 소스·대상 양쪽에 같은
  # 이름의 파일이 있어야 하므로, 재설치 직전에 대상 쪽에 그런 파일을 직접 심는다.
  local pycache_sample_path pycache_sample_name=""
  pycache_sample_path=$(find "$REPO_ROOT/commands/__pycache__" -type f 2> /dev/null | head -1)
  [[ -n "$pycache_sample_path" ]] && pycache_sample_name=$(basename "$pycache_sample_path")

  if [[ -z "$pycache_sample_name" ]]; then
    note_failure "T35-5: 사전조건 실패 — source __pycache__ 에서 샘플 파일을 찾지 못함(T35-0 실패와 동일 원인 가능)"
  else
    mkdir -p "$sandbox/.claude/commands/__pycache__"
    printf 'STALE-DIFFERENT-BYTECODE-CONTENT' > "$sandbox/.claude/commands/__pycache__/$pycache_sample_name"

    local reinstall_output reinstall_exit=0
    reinstall_output=$( cd "$sandbox" && "$INSTALL_SCRIPT" --scope project 2>&1 ) || reinstall_exit=$?
    if [[ "$reinstall_exit" -ne 0 ]]; then
      note_failure "T35-5: 대상 __pycache__ 내용 차이만으로 재설치가 exit ${reinstall_exit} 로 실패함(기대 0) — list_differing_managed_files 의 -x __pycache__ 회귀 의심(충돌 경고: $(grep -F "수정된 파일이" <<< "$reinstall_output" || true))"
    fi
    if [[ -e "$sandbox/.claude/commands/__pycache__" ]]; then
      note_failure "T35-5: 재설치 후에도 대상에 __pycache__ 가 남아있음"
    fi
  fi

  # ---- T35-6 (Critical 1 회귀 방지, 2회차 검수): 소스 디렉토리 자체가 없으면 설치가
  # 조용히 성공(0개 복사)하지 않고 실패해야 한다. 실제 레포의 rules/ 를 지울 수
  # 없으므로 install.sh 사본을 격리된 가짜 레포에 두고 그 사본의 rules/ 만 빼고 실행한다
  # — REPO_ROOT 는 install.sh 자신의 파일 위치에서 계산되므로($(dirname "$0")), 사본을
  # 옮기면 그 사본 기준으로 재계산된다.
  #
  # 갱신(shell-hardening PRP, S1 검수 1회차 m2 반영) — 이 시나리오는 이제 cp -R 이전에
  # check_no_symlink_targets 의 관리 파일 열거(find)에서 더 일찍 잡힌다(find 가 사라진
  # rules/ 인자에서 부분 실패하고, 그 실패를 이제는 fail-closed 로 반영한다). 검사
  # 문구를 그 지점에 맞춰 갱신했다 — 이 서브체크가 지키려는 성질("소스 결측이 조용한
  # 성공이 되지 않는다")은 그대로다. 같은 코드 경로의 회귀는 T15-2(m2)가 별도로 등록한다.
  cp "$INSTALL_SCRIPT" "$fake_repo/install.sh"
  chmod +x "$fake_repo/install.sh"
  mkdir -p "$fake_repo/agents" "$fake_repo/commands"
  echo "stub" > "$fake_repo/agents/a.md"
  echo "stub" > "$fake_repo/commands/c.md"
  # rules/ 는 의도적으로 만들지 않는다 — "소스 누락" 재현.

  local missing_source_output missing_source_exit=0
  missing_source_output=$( cd "$fake_sandbox" && "$fake_repo/install.sh" --scope project 2>&1 ) \
    || missing_source_exit=$?
  if [[ "$missing_source_exit" -eq 0 ]]; then
    note_failure "T35-6: rules/ 소스가 통째로 없는데 설치가 exit 0 으로 성공함(무성 실패 회귀, 1회차 Critical 1)"
  fi
  # 3회차 검수 Major 3 — exit code 만 보면, install.sh 가 나중에 더 이른 지점에서 다른
  # 이유로 실패하도록 바뀌어도 이 검사는 통과해 버려 Critical 1 회귀를 놓친다. 실제로
  # 의도한 자리(check_no_symlink_targets 의 관리 파일 열거, m2 수정 후 cp -R 보다 먼저
  # 실행된다)에서 실패하는지 문구로 못박는다.
  if ! grep -qF "관리 파일 열거 실패" <<< "$missing_source_output"; then
    note_failure "T35-6: 실패 원인이 예상 지점(check_no_symlink_targets, '관리 파일 열거 실패' 문구)이 아님 — 실제 출력 마지막 3줄: $(tail -3 <<< "$missing_source_output")"
  fi

  # ---- T35-7 (dry-run 계획 가시성, 3회차 검수 Major 1-4): __pycache__ 정리가 dry-run
  # 계획 출력에도 나와야 한다 — 실제 삭제 경로인데 계획에는 안 보이면 사용자가 무엇이
  # 지워질지 미리 알 수 없다. $sandbox 는 이미 설치돼 있지만 dry-run 은 파일시스템을
  # 건드리지 않으므로 재사용해도 안전하다.
  local dry_run_output dry_run_exit=0
  dry_run_output=$( cd "$sandbox" && "$INSTALL_SCRIPT" --scope project --dry-run 2>&1 ) || dry_run_exit=$?
  if [[ "$dry_run_exit" -ne 0 ]]; then
    note_failure "T35-7: dry-run 이 exit ${dry_run_exit} 로 실패함(기대 0)"
  fi
  if ! grep -qF "__pycache__ 정리" <<< "$dry_run_output"; then
    note_failure "T35-7: dry-run 계획 출력에 __pycache__ 정리 계획 문구가 없음"
  fi

  # ---- T35-8 (범위 방어, 3회차 검수 Minor 1): remove_pycache_from_target_directory 의 find
  # 검색 시작점이 실수로 한 단계 넓어지는 변경이 있어도(렌즈 C 변조 3 재현: find 의 첫 인자를
  # "$target_directory" 에서 "$target_directory/.." 로), 관리 대상 밖(.claude/ 바로 아래)의
  # __pycache__ 는 지워지지 않아야 한다. install.sh 사본을 sed 로 그렇게 바꿔 격리된 가짜
  # 레포에서 실행한다 — 실제 레포·install.sh 는 건드리지 않는다.
  cp -R "$REPO_ROOT/rules" "$REPO_ROOT/agents" "$REPO_ROOT/commands" "$fake_repo_scope/"
  cp "$INSTALL_SCRIPT" "$fake_repo_scope/install.sh"
  chmod +x "$fake_repo_scope/install.sh"
  sed -i.bak 's|find "$target_directory" -type d|find "$target_directory/.." -type d|' \
    "$fake_repo_scope/install.sh"
  rm -f "$fake_repo_scope/install.sh.bak"

  if ! grep -qF 'find "$target_directory/.." -type d' "$fake_repo_scope/install.sh"; then
    note_failure "T35-8: sed 변조가 적용되지 않음(사전조건 실패 — install.sh 의 find 호출 형태가 달라졌을 수 있음, 아래 결과는 무의미)"
  else
    mkdir -p "$fake_sandbox_scope/.claude/__pycache__decoy_parent/__pycache__"
    echo "decoy" > "$fake_sandbox_scope/.claude/__pycache__decoy_parent/__pycache__/decoy.pyc"
    _synthesize_commands_pycache_file "$fake_repo_scope"

    local scope_exit=0
    ( cd "$fake_sandbox_scope" && "$fake_repo_scope/install.sh" --scope project ) > /dev/null 2>&1 \
      || scope_exit=$?
    if [[ "$scope_exit" -ne 0 ]]; then
      note_failure "T35-8: 변조 사본 설치가 exit ${scope_exit} 로 실패함(사전조건 불성립, 아래 결과는 무의미)"
    fi
    if [[ ! -f "$fake_sandbox_scope/.claude/__pycache__decoy_parent/__pycache__/decoy.pyc" ]]; then
      note_failure "T35-8: 범위 방어 미작동 — 관리 대상 밖(.claude/ 바로 아래)의 미끼 __pycache__ 가 삭제됨"
    fi
    if [[ -e "$fake_sandbox_scope/.claude/commands/__pycache__" ]]; then
      note_failure "T35-8: 범위 방어가 정당한 삭제(commands/__pycache__)까지 막음(과잉 차단)"
    fi
  fi

  # ---- T35-9 (정리 실패 분기, 3회차 검수 Medium 2 + Minor 2): __pycache__ 삭제 자체가
  # 권한 등으로 실패해도 설치 전체는 exit 0 을 유지해야 하고(무해 계약), 경고에는 실패한
  # 경로가 남아야 한다(이전에는 target_directory 만 나와 어떤 파일이 문제인지 알 수
  # 없었다 — Minor 2). 소스 __pycache__ 를 555(쓰기 금지)로 만들면 cp -R 가 그 모드까지
  # 그대로 옮긴다(이 머신에서 실측 확인 — BSD cp) — 대상에서도 안의 파일을 지울 수 없어
  # rm -rf 가 실패한다. 실제 레포를 건드리지 않도록 격리된 사본에서 한다.
  cp -R "$REPO_ROOT/rules" "$REPO_ROOT/agents" "$REPO_ROOT/commands" "$fake_repo_perm/"
  cp "$INSTALL_SCRIPT" "$fake_repo_perm/install.sh"
  chmod +x "$fake_repo_perm/install.sh"
  _synthesize_commands_pycache_file "$fake_repo_perm"

  if [[ ! -d "$fake_repo_perm/commands/__pycache__" ]]; then
    note_failure "T35-9: 사전조건 실패 — 격리 사본에서 py_compile 로 __pycache__ 를 만들지 못함(아래 결과는 무의미)"
  else
    chmod 555 "$fake_repo_perm/commands/__pycache__"

    local perm_output perm_exit=0
    perm_output=$( cd "$fake_sandbox_perm" && "$fake_repo_perm/install.sh" --scope project 2>&1 ) \
      || perm_exit=$?
    # 555 를 남겨두면 함수 반환 시 트랩의 rm -rf 가 이 경로를 못 지운다 — 여기서 바로
    # 되돌린다(트랩은 정리 전용으로 단순하게 유지, rm -rf 앞에 chmod 를 얹지 않는다).
    chmod -R u+w "$fake_repo_perm/commands/__pycache__" "$fake_sandbox_perm" 2> /dev/null || true

    if [[ "$perm_exit" -ne 0 ]]; then
      note_failure "T35-9: __pycache__ 정리 실패가 설치 자체를 exit ${perm_exit} 로 실패시킴(기대 0, 무해 계약 위반)"
    fi
    # "__pycache__ 정리 실패"만 보면 부족하다 — 이전 방식(target_directory 만 나오는
    # "…commands 의 __pycache__ 정리 실패")도 이 부분문자열을 그대로 포함해 신·구를
    # 구분하지 못한다(직접 재현해 확인). 개선판은 실패한 경로 자체(pycache_path)가
    # "…commands/__pycache__" 형태로 슬래시와 함께 나온다 — 이전 방식에는 "commands" 와
    # "__pycache__" 사이에 " 의 "가 끼어 이 부분문자열이 나오지 않는다.
    if ! grep -qF "commands/__pycache__ 정리 실패" <<< "$perm_output"; then
      note_failure "T35-9: 정리 실패 경고에 실패한 경로 전체(…commands/__pycache__)가 안 보임 — 출력: $(grep -F '정리' <<< "$perm_output")"
    fi
  fi

  # ---- T35-10 (전역 커맨드 비교 루프의 [[ -f ]] 가드, 2회차 검수 Medium 3): 이 스위트
  # 전체에서 report_global_command_overlap 의 루프가 "$REPO_ROOT/commands 에 __pycache__
  # 가 있고 + HOME 이 오버라이드돼 루프에 실제로 진입하는" 상황에 한 번도 놓이지 않는다
  # (T18 은 이 상황이 되기 전에 실행되고 끝난다) — 그래서 그 가드가 실제로 무언가를
  # 막는지 이 스위트만으로는 검증된 적이 없었다. 전역 쪽에 __pycache__ 라는 이름의
  # "파일"을 미끼로 심어, 가드가 없다면 디렉토리(source) 대 파일(global) cmp 오류로
  # "differ" 오분류가 나는 상황을 만든다.
  mkdir -p "$overlap_home_sandbox/.claude/commands"
  cp "$REPO_ROOT/commands"/*.md "$overlap_home_sandbox/.claude/commands/"
  echo "decoy — 디렉토리가 아니라 파일" > "$overlap_home_sandbox/.claude/commands/__pycache__"

  local overlap_output overlap_exit=0
  overlap_output=$( cd "$overlap_project_sandbox" \
    && HOME="$overlap_home_sandbox" "$INSTALL_SCRIPT" --scope project 2>&1 ) || overlap_exit=$?
  if [[ "$overlap_exit" -ne 0 ]]; then
    note_failure "T35-10: HOME 오버라이드 설치가 exit ${overlap_exit} 로 실패함(사전조건 불성립, 아래 결과는 무의미)"
  fi
  # "__pycache__" 단순 포함 검사는 안 된다 — remove_pycache_from_target_directory 자신의 "N개
  # 정리" 로그(T35-1/-7 이 단언하는 바로 그 문구)에도 이 문자열이 정상적으로 등장한다. 여기서
  # 봐야 할 건 전역 비교 "differ" 경고 줄 안에 __pycache__ 가 끼어 있는지뿐이다.
  local overlap_differ_line
  overlap_differ_line=$(grep -F "전역 커맨드와 내용이 다릅니다" <<< "$overlap_output" || true)
  if grep -qF "__pycache__" <<< "$overlap_differ_line"; then
    note_failure "T35-10: 전역 비교 'differ' 경고에 __pycache__ 가 등장함([[ -f ]] 가드 미작동 의심) — 해당 줄: $overlap_differ_line"
  fi

  # ---- T35-11 (A10, tests-hardening PRP §9 — 원장 T35-11 이 이 서브체크와 짝을 이룬다):
  # 위 T35 헤더의 "4회차 갱신" 문단 참고. $install_output 은 T35-0 의 최초 설치 로그다.
  if grep -qF "범위 밖이라 건너뜀" <<< "$install_output"; then
    note_failure "T35-11: 정상 설치 로그에 범위 방어 경고가 발생함(find 이름 필터 광역화 의심) — 해당 줄: $(grep -F '범위 밖이라 건너뜀' <<< "$install_output")"
  fi

  # ---- T35-12 (A12, tests-hardening PRP §9 — 원장 T35-12 가 이 서브체크와 짝을 이룬다):
  # remove_pycache_from_target_directory 의 `[[ -d ]] || continue` 가드 회귀 검사 — 위 "4회차
  # 갱신" 문단 참고. 대상 디렉토리 자체가 555 인 "혼합" 상황이 필요해 최소 소스로 정상 설치 →
  # 대상에 중첩 __pycache__ 를 직접 심고 대상 자체를 555 로 바꿈 → 재설치, 3단계로 만든다
  # (target_directory 자신의 모드는 cp -R 가 옮기지 않아 최초 설치 한 번으로는 이 상태에 못
  # 닿는다).
  mkdir -p "$a12_repo/rules" "$a12_repo/agents" "$a12_repo/commands"
  echo stub > "$a12_repo/rules/r.md"
  echo stub > "$a12_repo/agents/a.md"
  echo stub > "$a12_repo/commands/c.md"
  cp "$INSTALL_SCRIPT" "$a12_repo/install.sh"
  chmod +x "$a12_repo/install.sh"

  local a12_first_exit=0
  ( cd "$a12_sandbox" && "$a12_repo/install.sh" --scope project ) > /dev/null 2>&1 \
    || a12_first_exit=$?
  local a12_target="$a12_sandbox/.claude/commands"

  if [[ "$a12_first_exit" -ne 0 || ! -d "$a12_target" ]]; then
    note_failure "T35-12: 사전조건 실패 — A12 회귀용 최초 설치가 실패함(exit ${a12_first_exit}, 아래 결과는 무의미)"
  else
    mkdir -p "$a12_target/__pycache__/__pycache__"
    chmod 555 "$a12_target"

    local a12_output a12_exit=0
    a12_output=$( cd "$a12_sandbox" && "$a12_repo/install.sh" --scope project 2>&1 ) || a12_exit=$?
    # 555 를 남겨두면 트랩의 rm -rf 가 이 경로를 못 지운다 — 여기서 바로 되돌린다(T35-9 와
    # 같은 관용구).
    chmod -R u+w "$a12_target" 2> /dev/null || true

    if [[ "$a12_exit" -ne 0 ]]; then
      note_failure "T35-12: A12 회귀 재설치가 exit ${a12_exit} 로 실패함(기대 0, 무해 계약 위반)"
    fi
    if grep -qE '__pycache__ [0-9]+개 정리' <<< "$a12_output"; then
      note_failure "T35-12: 이미 사라진 중첩 __pycache__ 후보가 정리 성공으로 오집계됨(A12 가드 회귀 의심) — 출력: $(grep -E '__pycache__ [0-9]+개 정리' <<< "$a12_output")"
    fi
    if ! grep -qF "__pycache__ 정리 실패 1건" <<< "$a12_output"; then
      note_failure "T35-12: 정리 실패 건수가 기대(1건)와 다름 — 출력: $(grep -F '정리 실패' <<< "$a12_output")"
    fi
  fi

  finish_group "$test_name"
}

# T35-0 개정(docs/prps/dashboard-into-hub.md M1, HD1): commands/ 에 더 이상 .py 소스가 없어
# python3 -m py_compile commands/*.py 글롭이 아무것도 매칭하지 못한다(대상 없이 실행되면
# __pycache__ 가 생기지 않아 위 검사들이 공허 통과가 된다). 이 헬퍼는 임시 .py 파일
# 하나를 py_compile.compile() 로 직접 지정한 cfile 위치(<대상>/commands/__pycache__/)에
# 컴파일해 "실물 바이트코드"를 흉내 없이 만든다(빈 파일 흉내 금지 원칙 유지, 위 T35 헤더
# 참고) — 가드가 지키는 remove_pycache_from_target_directory 경로(find 로 __pycache__ 를
# 찾아 지우는 로직)는 디렉터리 존재·내용만 보므로 이 방식으로도 똑같이 검증된다. 정의를
# test_pycache_excluded_from_deployment() 뒤로 옮긴 이유(검수 2회차 N2) — 원래 위치(T35
# 머리 주석과 그 함수 정의 사이)에 있으면 anchor_function 해소가 "정의 바로 위 주석
# 블록"을 그 함수 정의 직전 줄에서 찾는데, 그 자리가 이 헬퍼의 `}` 와 빈 줄이 돼 있어
# T35-11·T35-12 앵커 해소가 실패했다(공백/헬퍼 정의는 `#` 로 시작하지 않는다).
_synthesize_commands_pycache_file() {
  local target_repo_dir="$1"
  ( cd "$target_repo_dir" && python3 -c "
import os, py_compile, sys, tempfile
pycache_dir = 'commands/__pycache__'
os.makedirs(pycache_dir, exist_ok=True)
fd, tmp_path = tempfile.mkstemp(suffix='.py')
os.write(fd, b'x = 1\n')
os.close(fd)
cfile = os.path.join(pycache_dir, 'sentinel.' + sys.implementation.cache_tag + '.pyc')
py_compile.compile(tmp_path, cfile=cfile, doraise=True)
os.remove(tmp_path)
" ) > /dev/null 2>&1
}

# T36 전용 헬퍼(G-1 회귀, tests-hardening PRP 2회차 검수). 미끼 디렉토리를 만들어 주어진
# 인자로 tests/run.sh 를 중첩 실행한 뒤 미끼가 생존했는지 반환값으로 알린다(0=생존·1=삭제됨).
# CODING_HARNESS_TEST_HOME 을 이 호출 하나에만 지정하므로(prefix 대입) 바깥 스위트가 이미 그
# 변수를 쓰고 있어도 이 호출 동안만 미끼 경로로 덮인다.
assert_decoy_survives_nested_run() {
  local decoy_dir survived=1
  decoy_dir=$(mktemp -d)
  mkdir -p "$decoy_dir/keep"
  echo "canary" > "$decoy_dir/keep/important.txt"
  CODING_HARNESS_TEST_HOME="$decoy_dir" bash "$REPO_ROOT/tests/run.sh" "$@" > /dev/null 2>&1 || true
  [[ -f "$decoy_dir/keep/important.txt" ]] && survived=0
  rm -rf "$decoy_dir"
  return "$survived"
}

# T36-3·T36-4 의 조각 프로브 스크립트를 만든다 — 재구현이 아니라 추출이다: 이 파일의
# `set -euo pipefail` 줄부터 `trap suite_exit_guard EXIT` 줄까지를 그대로 떼어낸다.
# 거기에 조각이 자기 몫으로 만든 임시 디렉토리 두 개(전역 HOME 샌드박스 · 중립 대피
# 디렉토리)의 실제 경로를 marker 파일에 한 줄씩 적는 줄을 덧붙인다. 경로를 조각 자신에게
# 물어보는 이유: 이 환경의 mktemp 은 TMPDIR 재지정을 반영하지 않아(아래 T36-3 주석의 실측)
# 조각이 어디에 만들지 부모가 통제할 수 없고, 공유 임시 디렉토리의 항목 집합을 비교하는
# 방식은 무관한 프로세스와 함께 쓰는 자리라 비결정적이다(T36-6 주석이 같은 이유로 그 비교를
# 자동 검사에서 뺐다). 세 번째 인자부터는 조각 끝에 덧붙일 추가 줄이다(T36-4 가 두 플래그를
# 세우는 데 쓴다).
#
# T36-11(검수 2회차 지적) — awk 의 범위 패턴은 닫는 앵커가 한 줄도 맞지 않으면 조용히 **파일
# 끝까지** 출력한다. 트랩 함수 개명 같은 평범한 리팩토링이 그것을 만든다: 재현에서 조각이
# 138줄에서 파일 전체로 커져 파일 끝의 main "$@" 까지 들어갔고, 조각이 실제로 스위트 배너를
# 찍고 main 에 진입했다. 그때 트랩 위생 검사는 EXIT 1곳을 그대로 보고해 통과했고, 시끄럽게
# 발화한 T36-3·T36-5·T36-8 중 어느 것도 원인을 말하지 않았다. 피해가 멈춘 것은 조각의
# REPO_ROOT 가 공유 임시 디렉토리라 install.sh 가 없다는 우연 덕이었다. 그래서 추출물의
# 마지막 줄이 닫는 앵커 자신인지 먼저 단언하고, 어긋나면 조각을 **아예 쓰지 않고** 1 을
# 반환한다(없는 스크립트는 main 에 진입할 방법도 없다 — fail-close).
#
# 원장에 등록된 변조 매개체는 닫는 앵커 줄에 **공백 한 칸 삽입**이다(육안 비가시 — 원장 행만
# 읽어서는 그 취약함이 보이지 않는다). 공백 정규화가 그 삽입을 지우면 변조 적용의 사전조건
# (sed 적용 후 바이트가 바뀌어야 한다)에서 fail-loud 로 걸린다.
#
# 한계(비망라) — 이 단언이 보는 것은 추출물의 **마지막 줄**뿐이다. 여는 앵커가 안 맞아
# 추출이 빈 값이 되는 형태는 같은 대조에 걸리지만, 범위 안쪽 내용이 잘못된 경우(추출 대상
# 블록 자체의 결함)는 판정하지 않는다. 호출부로의 파급도 남는다 — 여기서 1 을 반환하면
# 호출부는 없는 스크립트를 실행해 T36-3(사전조건)·T36-8(종료 코드)·T36-5(검출 메시지 부재)
# 까지 함께 발화한다. 진단이 여러 줄로 흩어지지만 그중 한 줄이 원인을 정확히 말한다.
# 전수 증명이 아니다.
write_trap_fragment_probe() {
  local script_path="$1" marker_path="$2"
  shift 2
  # 닫는 앵커를 한 곳에만 적고 awk 프로그램과 아래 단언이 함께 쓴다(두 리터럴이 따로
  # 표류하는 것을 막는다). awk 프로그램을 겹따옴표로 조립하므로 정규식의 $ 는 \$ 로 넘긴다.
  local closing_anchor='trap suite_exit_guard EXIT'
  local extracted extra_line
  extracted=$(awk "/^set -euo pipefail\$/,/^${closing_anchor}\$/" "$REPO_ROOT/tests/run.sh")
  if [[ "${extracted##*$'\n'}" != "$closing_anchor" ]]; then
    note_failure "T36-11: 사전조건 실패 — 트랩 조각 추출이 닫는 앵커에서 끝나지 않음(마지막 줄 '${extracted##*$'\n'}') — 앵커가 개명돼 범위가 파일 끝까지 번졌다"
    return 1
  fi
  {
    printf '%s\n' "$extracted"
    echo "printf '%s\\n%s\\n' \"\$GLOBAL_HOME_SANDBOX\" \"\$CLEANUP_NEUTRAL_CWD\" > \"$marker_path\""
    # 파싱 완주 센티널의 명시 옵트인(§18 이관 2 의 근본 수정). 조각은 파일의 일부만 떼어
    # 돌리므로 파일 마지막의 SCRIPT_FULLY_PARSED=1 이 구조적으로 도달 불가다 — 옵트인이
    # 없으면 조각의 트랩이 "파싱이 완주하지 못함"으로 exit 1 을 강제해 T36-8(자식 종료
    # 코드 0 기대)이 오진한다(이 옵트인 한 줄을 떼고 전체 실행: T36-8 1건 + T36-12 1건 +
    # T37-15 5건 → 34/36. 재측정 확인).
    # 이 한 줄이 T36-3·T36-4 두 호출부를 함께 덮는다.
    echo "SCRIPT_FULLY_PARSED=1"
    for extra_line in "$@"; do
      echo "$extra_line"
    done
  } > "$script_path"
}

# marker 파일에 적힌 경로 중 **아직 남아 있는** 것을 공백으로 이어 낸다(전부 정리됐으면 빈
# 값). marker 가 없으면 빈 값이다 — 두 호출부의 처리가 다르다: T36-3 쪽은 marker 첫 줄이
# 비었는지를 사전조건으로 따로 단언하고, T36-4 쪽은 그런 단언 없이 조각의 종료 코드 판정
# (T36-8)과 검출 메시지 판정(T36-5)이 먼저 발화하는 데 기댄다. 어느 쪽이든 marker 부재가
# 조용한 통과가 되지는 않는다.
surviving_recorded_paths() {
  local marker_path="$1" recorded survivors=""
  [[ -f "$marker_path" ]] || return 0
  while IFS= read -r recorded; do
    [[ -z "$recorded" ]] && continue
    if [[ -e "$recorded" ]]; then
      survivors+="${survivors:+ }$recorded"
    fi
  done < "$marker_path"
  printf '%s' "$survivors"
}

# T36(tests-hardening PRP, 2회차 검수 G-1·G-2 회귀 + S2 K4b). suite_exit_guard 의 처방을
# 고정한다: (1) 호출자가 지정한 CODING_HARNESS_TEST_HOME 은 지우지 않는다(G-1 소유권 구분,
# T36-1·T36-2) · (2) 그 처방이 기본 정리(호출자가 지정하지 않았을 때 자체 mktemp 디렉토리를
# 지우는 것)를 깨뜨리지 않는다(T36-3) · (3) 요약 전 종료를 검출하면 항상 비0 으로 끝난다
# (G-2 fail-close, T36-4·T36-5) · (4) register_cleanup_path 로 등록한 경로는
# cleanup_registered_paths 호출로 실제로 지워진다 — 읽기 전용으로 만든 경로를 포함해서
# (K4b 절반, T36-6) · (5) 그 정리가 등록 경로 안에 서 있는 채로 일어나도(cd 대피) 그
# 프로세스의 작업 디렉토리는 죽지 않는다(T36-7) · (6) 정리가 **실패**했을 때 그 사실이
# 종료 코드로 강제된다(T36-10, PRP §17 이관 2). 조각 프로브 두 개(T36-3·T36-4)에 붙는
# 자식 종료 코드·임시 디렉토리 잔여 단언은 T36-8·T36-9 다(같은 PRP §17 이관 1).
#
# T36-1·T36-2 는 S2 이전에는 이 트랩이 "유일하게 설치된 EXIT 트랩"일 때만 성립했다 — 함수
# 마다 자기 trap 을 새로 걸던 시절에는 스위트 실행 순서상 나중에 도는 다른 그룹의 trap 이
# 이 트랩을 덮어썼기 때문이다. S2(tests-hardening PRP §4.3)가 그 함수별 trap 설치를
# register_cleanup_path 로 교체해 이 트랩이 스크립트 전체에서 유일한 EXIT 트랩으로 남고
# (그 상태는 verify_trap_hygiene 가 실행마다 검사한다 — 한계는 그 함수 주석에), 이제는
# --only 로 어느 그룹을 고르든 같은 결과가 나온다. 그래도 T26(install.sh 를 부르지 않아
# 빠르다)을 그대로 쓰는 이유는 순전히 실행 속도다. 나머지(T36-3·T36-4·T36-5, 그리고 그 위에
# 올라탄 T36-8·T36-9·T36-11)는 어느 그룹이 실행되는지와 무관하게 트랩 자체의 동작만으로
# 결정되므로, 전체 스위트를 다시 돌리는 대신
# $REPO_ROOT/tests/run.sh 에서 set -euo pipefail 줄부터 trap suite_exit_guard EXIT 줄까지만
# 그대로 추출해(재구현이 아니다) 별도 프로세스로 실행한다 — T36-3 은 그 프로세스가 실제로
# 만든 $GLOBAL_HOME_SANDBOX 경로를 파일로 받아 종료 후 남았는지 확인하고(TMPDIR 재지정으로
# 그 경로를 미리 통제하려 했으나 이 환경의 셸 실행 샌드박스에서 지켜지지 않는 것을 직접
# 확인해 대신 이 방식을 쓴다), T36-4·T36-5 는 두 플래그를 직접 세워 요약 전 종료를 흉내낸다.
# 렌즈 G 의 실제 재현(T28 함수 본문에 unbound 변수 주입)은 이 그룹이 아니라 구현 보고의
# 수용 시험에서 별도로 재현한다.
#
# T36-6 은 register_cleanup_path/cleanup_registered_paths 를 별도 서브셸에서 직접 불러
# 등록·정리가 맞물리는지만 본다. CODING_HARNESS_TEST_HOME 을 지정한 전체 스위트 실행이 시스템
# 공유 임시 디렉토리(TMPDIR 아래)에 아무것도 안 남기는지까지는 자동 검사로 못박지 않는다 —
# 그 디렉토리는 이 스위트만 쓰는 게 아니라 동시에 실행 중인 무관한 프로세스와도 공유돼(이
# 환경은 TMPDIR 재지정도 mktemp 의 실제 생성 위치에 반영되지 않는다, 위 T36-3 참고) 항목
# 수의 증감이 이 코드와 무관하게 흔들릴 수 있어(비결정적), 그 전체 경로 확인은 자동 회귀
# 검사 대신 구현 보고의 1회성 실측 비교로 남긴다.
#
# T36-7 은 T36-6 과 달리 실제로 등록 경로 안에 cd 한 채 정리를 부른다 — T36-6 은 cd 를
# 하지 않아 cleanup_registered_paths 의 cd 대피 자체는 운동시키지 않았다. 서브셸의 cwd
# 가 정리 후에도 유효한지 pwd -P 로 판정하고, 판정 전에 "실제로 등록 경로에 서 있었는지"·
# "실제로 지워졌는지"를 먼저 확인해 공허 통과를 막는다.
#
# 한계(비망라) — 이 그룹은 여기서 고정한 항목만 검증한다. tests-hardening PRP §4.4 가
# 계획하는 원장 기반 뮤테이션 하네스(변조 사본 생성·정방향 PASS·역방향 FAIL 단언을 등록된
# 모든 보호 분기에 대해 반복)는 S3 의 몫이고 여기서는 만들지 않는다 — 전수 증명이 아니다.
test_suite_exit_guard_regression() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T36"
  local test_desc="suite_exit_guard 소유권 구분(G-1)·fail-close(G-2) 회귀"
  log_test_name "$test_name" "$test_desc"

  local probes_run=0

  ((probes_run++)) || true
  if ! assert_decoy_survives_nested_run --list; then
    note_failure "T36-1: --list 호출에서 호출자가 준 CODING_HARNESS_TEST_HOME 이 삭제됨(G-1 회귀)"
  fi

  ((probes_run++)) || true
  if ! assert_decoy_survives_nested_run --only T26; then
    note_failure "T36-2: --only T26(install.sh 미호출로 빠른 그룹) 호출에서 호출자가 준 CODING_HARNESS_TEST_HOME 이 삭제됨(G-1 회귀)"
  fi

  ((probes_run++)) || true
  # TMPDIR 재지정에 기대지 않는다 — 이 환경(셸 실행 샌드박스)에서 TMPDIR 지정이 mktemp 의
  # 실제 생성 위치를 바꾸지 않는 것을 직접 확인했다(구현 보고에 재현 기록). 대신 아래 G-2
  # 프로브와 같은 방식으로 트랩 정의 블록만 추출해 실행하고(write_trap_fragment_probe),
  # 그 안에서 만들어진 임시 디렉토리 두 개의 실제 경로를 marker 파일로 받아 적어 스크립트
  # 종료 후 남아 있는지 직접 확인한다 — 어디에 만들어지든 경로 자체는 스크립트가 알려주므로
  # 안전하다. 첫 줄($GLOBAL_HOME_SANDBOX)이 이 서브체크의 대상이고, 두 줄 전체는 아래
  # T36-9 가 본다.
  local self_owned_probe_dir self_owned_probe_script self_owned_path_marker self_owned_created_dir
  local self_owned_exit=0 self_owned_survivors
  self_owned_probe_dir=$(mktemp -d)
  self_owned_probe_script="$self_owned_probe_dir/probe.sh"
  self_owned_path_marker="$self_owned_probe_dir/created_paths.txt"
  write_trap_fragment_probe "$self_owned_probe_script" "$self_owned_path_marker" || true
  ( unset CODING_HARNESS_TEST_HOME; bash "$self_owned_probe_script" ) > /dev/null 2>&1 || self_owned_exit=$?
  self_owned_created_dir=$(head -1 "$self_owned_path_marker" 2> /dev/null || true)
  self_owned_survivors=$(surviving_recorded_paths "$self_owned_path_marker")
  if [[ -z "$self_owned_created_dir" ]]; then
    note_failure "T36-3: 사전조건 실패 — 자체 mktemp 디렉토리 경로를 확인하지 못함(프로브 스크립트 오류 가능)"
  elif [[ -d "$self_owned_created_dir" ]]; then
    note_failure "T36-3: CODING_HARNESS_TEST_HOME 미지정 시 자체 mktemp 디렉토리($self_owned_created_dir)가 정리되지 않음 — 소유권 구분이 기본 정리를 깨뜨림"
  fi
  # T36-8·T36-9(PRP §17 이관 1). 이 조각은 추출 범위 밖에 정의된 심볼을 참조하면 죽는데,
  # 그 실패가 부모 판정에 도달하지 않아 전체 실행이 exit 0 · 실패 0 으로 통과했다 —
  # S2 회차에 두 번 재발했고(cleanup_registered_paths 미정의 · CLEANUP_PATHS 미선언) 두 번
  # 다 잡은 것은 검사가 아니라 손으로 센 임시 디렉토리 증감이었다. 이미 조각을 돌리고 있으니
  # 두 단언으로 그 계열을 기계에 넘긴다: 자식의 종료 코드(정상 경로는 0 — 실측으로 declare -F
  # 가드 제거 시 127 · declare -p 가드 제거 시 1)와, 조각이 만든 임시 디렉토리의 잔여
  # (두 가드 제거가 각각 delta +7 · +2 를 남겼다).
  #
  # 한계(비망라) — T36-9 가 보는 것은 조각이 marker 에 적은 경로뿐이다: 추출 범위에 세
  # 번째 mktemp 가 생기면 그 경로는 이 단언의 시야 밖이고, 공유 임시 디렉토리 전체의 증감은
  # 여기서 보지 않는다(그 비교가 비결정적인 이유는 write_trap_fragment_probe 주석).
  # 세 번째 조각 프로브(T36-10 의 더 넓은 추출)도 임시 디렉토리 두 개를 만들지만 marker 를
  # 쓰지 않아 어떤 잔여 단언의 시야에도 없다 — 그 두 디렉토리를 지우는 것은 **조각 자신의
  # EXIT 트랩**(= 이 프로브의 시험 대상)이므로, 그것이 회귀하면 잔여를 보는 단언이 없다.
  # 그 두 경로는 프로브 루트 **밖**(공유 임시 디렉토리의 형제)이라 프로브 루트 등록이 덮는
  # 것은 루트 자신과 그 안의 스크립트·undeletable 뿐이다(검수 2회차 실측, 구현 재확인).
  # 위 T36-3 의 샌드박스 단언과 T36-9 는 그 한 경로에서 대상이 겹친다 — 진단이 서로
  # 다르므로(소유권 구분 회귀 / 트랩이 마지막 정리에 도달하지 못함) 둘 다 남긴다.
  # 전수 증명이 아니다.
  if ((self_owned_exit != 0)); then
    note_failure "T36-8: 조각 실행 자식이 예상과 다른 종료 코드 ${self_owned_exit}(기대 0)로 끝남 — 추출 범위 밖 심볼 참조로 트랩이 중간에 죽는 계열이 부모 판정에 도달하지 않던 자리"
  fi
  if [[ -n "$self_owned_survivors" ]]; then
    note_failure "T36-9: 조각이 만든 임시 디렉토리가 종료 후에도 남음 — $self_owned_survivors (트랩이 마지막 정리에 도달하지 못했다)"
  fi
  rm -rf "$self_owned_probe_dir"

  ((probes_run++)) || true
  local guard_fragment_dir guard_fragment_script guard_fragment_marker
  local guard_fragment_output guard_fragment_exit=0 guard_fragment_survivors
  guard_fragment_dir=$(mktemp -d)
  guard_fragment_script="$guard_fragment_dir/probe.sh"
  guard_fragment_marker="$guard_fragment_dir/created_paths.txt"
  write_trap_fragment_probe "$guard_fragment_script" "$guard_fragment_marker" \
    'TEST_EXECUTION_STARTED=1' 'SUMMARY_PRINTED=0' || true
  # 조각 호출에서 CODING_HARNESS_TEST_HOME 을 끊는다(위 T36-3 의 호출과 대칭). 끊지 않으면
  # 조각이 호출자의 그 값을 GLOBAL_HOME_SANDBOX 로 물려받아 SANDBOX_IS_OURS=0 이 되고,
  # 트랩이 소유권 구분(G-1)대로 그 호출자 소유 경로를 지우지 않은 것을 아래 T36-9 가
  # "조각이 만든 임시 디렉토리가 남음"으로 오진한다 — 검수 2회차에 재현됐다(같은 커밋에서
  # 인자 없는 실행은 36/36, CODING_HARNESS_TEST_HOME 지정 실행은 35/36). run_group_in_mirror
  # 도 같은 이유로 같은 관용구를 쓴다.
  guard_fragment_output=$( ( unset CODING_HARNESS_TEST_HOME; bash "$guard_fragment_script" ) 2>&1 ) || guard_fragment_exit=$?
  guard_fragment_survivors=$(surviving_recorded_paths "$guard_fragment_marker")
  rm -rf "$guard_fragment_dir"

  local guard_fragment_output_flat="${guard_fragment_output//$'\n'/ }"
  if [[ "$guard_fragment_exit" -eq 0 ]]; then
    note_failure "T36-4: 요약 전 종료를 검출하고도 exit 0 을 반환함(G-2 회귀) — 출력: ${guard_fragment_output_flat:0:200}"
  elif [[ "$guard_fragment_exit" -ne 1 ]]; then
    # 종료 코드가 0 이 아니라는 것만 보면(옛 판정) 조각이 **무관한 이유로** 죽은 경우도
    # G-2 통과로 셌다 — 실측: declare -F 가드 제거 시 127 로 죽으면서 T36-4·T36-5 가 둘 다
    # 통과했다. 트랩이 강제하는 값은 1 이므로 그 정확값을 요구한다(§17 이관 1).
    note_failure "T36-8: 요약 전 종료 조각이 트랩의 강제값 1 이 아닌 종료 코드 ${guard_fragment_exit} 로 끝남 — 요약 미출력 검출과 무관한 이유로 죽었다: ${guard_fragment_output_flat:0:200}"
  fi
  if [[ "$guard_fragment_output" != *"스위트가 요약 전에 종료됨"* ]]; then
    note_failure "T36-5: 요약 전 종료 검출 메시지가 출력에 없음 — 출력 일부: ${guard_fragment_output_flat:0:200}"
  fi
  if [[ -n "$guard_fragment_survivors" ]]; then
    note_failure "T36-9: 요약 전 종료 조각이 만든 임시 디렉토리가 종료 후에도 남음 — $guard_fragment_survivors (트랩이 마지막 정리에 도달하지 못했다)"
  fi

  ((probes_run++)) || true
  # T36-6(K4b 절반, S2). 별도 서브셸에서 CLEANUP_PATHS 를 비운 채로 register_cleanup_path
  # 를 불러 두 일반 경로와 읽기 전용(555) 경로 하나를 등록하고, cleanup_registered_paths
  # 가 셋 다 실제로 지우는지 본다 — 읽기 전용 경로는 cleanup_registered_paths 의 chmod
  # 선행 없이는 rm -rf 만으로 지워지지 않으므로, 그 chmod-선행 관용구(T7·T27 이 필요로
  # 했던 것을 단일 함수로 흡수한 부분)가 계속 성립하는지를 함께 고정한다. 서브셸을 쓰는
  # 이유: 이 실험이 CLEANUP_PATHS 를 비우고 채우는데, 그 변경이 이 함수(T36) 자신이 아직
  # 쓰고 있을 바깥 스코프의 CLEANUP_PATHS 에 새지 않아야 한다.
  local trap_hygiene_probe_a trap_hygiene_probe_b trap_hygiene_probe_readonly
  trap_hygiene_probe_a=$(mktemp -d)
  trap_hygiene_probe_b=$(mktemp -d)
  trap_hygiene_probe_readonly=$(mktemp -d)
  echo canary > "$trap_hygiene_probe_readonly/file.txt"
  chmod 555 "$trap_hygiene_probe_readonly"
  (
    CLEANUP_PATHS=()
    register_cleanup_path "$trap_hygiene_probe_a" "$trap_hygiene_probe_b" "$trap_hygiene_probe_readonly"
    cleanup_registered_paths
  )
  if [[ -d "$trap_hygiene_probe_a" || -d "$trap_hygiene_probe_b" || -d "$trap_hygiene_probe_readonly" ]]; then
    note_failure "T36-6: register_cleanup_path 로 등록한 경로가 cleanup_registered_paths 호출 후에도 남음(K4b 회귀)"
    chmod -R u+w "$trap_hygiene_probe_a" "$trap_hygiene_probe_b" "$trap_hygiene_probe_readonly" 2> /dev/null || true
    rm -rf "$trap_hygiene_probe_a" "$trap_hygiene_probe_b" "$trap_hygiene_probe_readonly"
  fi

  ((probes_run++)) || true
  # T36-7(cd 대피 회귀 전용 프로브). T36-6 은 cd 를 전혀 하지 않아 cleanup_registered_paths
  # 가 등록 경로 안에 서 있는 채로 그 경로를 지우는 상황(T1 은 cd "$sandbox" 뒤 그대로
  # 반환하고, T22 는 자기 sandbox 로 cd 한 채 finish_group 까지 간다 — 매 실행에서 실제로
  # 벌어진다)을 운동시키지 않는다. 여기서는 서브셸에서 등록 경로로 실제로 cd 한 뒤
  # cleanup_registered_paths 를 부르고, 그 서브셸의 cwd 가 삭제 후에도 유효한 위치인지
  # pwd -P 로 본다 — 죽은 cwd 에서는 pwd -P 가 "getcwd: cannot access parent
  # directories" 로 실패한다. 서브셸을 쓰는 이유는 T36-6 과 같다(CLEANUP_PATHS 격리).
  # 공허 통과 방지: 정리 직전 $PWD 가 실제로 등록 경로 자신이었는지, 정리 후 그 경로가
  # 실제로 사라졌는지를 최종 판정 전에 먼저 확인해 그중 하나라도 어긋나면 그 사실
  # 자체를(고유 토큰 T36-7 과 함께) 보고하고 cwd 판정으로 넘어가지 않는다. 아래
  # cd_evac_result 는 2>&1 없이 stdout 만 받는다 — cleanup_registered_paths 가 실패해
  # log_error 를 남기면(이 프로브의 정상 실행에서는 도달하지 않지만) 그 텍스트가 위
  # 토큰들과 섞여 아래 elif 사슬 전부가 조용히 지나갈 수 있었다(PRP §17 이관 4, 목으로
  # 재현) — log_error 를 stderr 로 옮겨 이 경로를 닫았다.
  # 한계(비망라) — 심볼릭 링크를 경유한 cd, 등록 경로의 하위 디렉토리에서의 cd 는 이
  # 프로브가 다루지 않는다. 전수 증명이 아니다.
  local cd_evac_probe_dir cd_evac_result
  cd_evac_probe_dir=$(mktemp -d)
  cd_evac_result=$(
    CLEANUP_PATHS=()
    register_cleanup_path "$cd_evac_probe_dir"
    if ! cd "$cd_evac_probe_dir" 2> /dev/null; then
      echo "CD_FAILED"
      exit 0
    fi
    pre_pwd="$PWD"
    cleanup_registered_paths
    if [[ "$pre_pwd" != "$cd_evac_probe_dir" ]]; then
      echo "PRECONDITION_FAILED:$pre_pwd"
      exit 0
    fi
    if [[ -d "$cd_evac_probe_dir" ]]; then
      echo "NOT_DELETED"
      exit 0
    fi
    if ! pwd -P > /dev/null 2>&1; then
      echo "PWD_DEAD"
      exit 0
    fi
    echo "OK"
  )
  if [[ "$cd_evac_result" == "CD_FAILED" ]]; then
    note_failure "T36-7: 사전조건 실패 — 프로브가 자기 샌드박스로 cd 하지 못함(mktemp 또는 cd 오류), 아래 결과는 무의미"
  elif [[ "$cd_evac_result" == PRECONDITION_FAILED:* ]]; then
    note_failure "T36-7: 사전조건 실패 — 정리 직전 \$PWD(${cd_evac_result#PRECONDITION_FAILED:})가 등록 경로 자신이 아님, 아래 결과는 무의미"
  elif [[ "$cd_evac_result" == "NOT_DELETED" ]]; then
    note_failure "T36-7: cleanup_registered_paths 호출 후에도 등록 경로가 삭제되지 않음(사전조건 불성립, cd 대피 검증 무의미)"
  elif [[ "$cd_evac_result" == "PWD_DEAD" ]]; then
    note_failure "T36-7: 등록 경로 안에 서 있는 채로 정리한 뒤 cwd 가 죽음(pwd -P 실패) — cd 대피 회귀"
  fi
  rm -rf "$cd_evac_probe_dir" 2> /dev/null || true

  ((probes_run++)) || true
  # T36-10(PRP §17 이관 2). suite_exit_guard 의 「정리하지 못한 경로가 남으면 exit 1 로
  # 강제」 블록 전용 회귀 가드다 — 그 블록을 통째로 삭제해도 전체 실행이 36/36 으로
  # 통과하는 것이 실측됐다. 정상 실행에서 정리가 실패하는 자리가 없기 때문이다
  # (cleanup_registered_paths 는 chmod -R 755 를 먼저 걸고 rm -rf 한다).
  #
  # 정리 실패를 만드는 방법: 등록 경로의 **부모** 디렉토리를 555 로 만든다. 정리 함수의
  # chmod 는 등록 경로 자신과 그 하위에만 걸리므로 부모의 쓰기 금지가 그대로 남고, 그
  # 상태에서는 등록 경로를 부모에서 떼어낼 수 없어 rm -rf 가 실패한다(실측: "Permission
  # denied" + 디렉토리 잔존). chflags uchg 도 같은 실패를 만들지만 쓰지 않는다 — 555 는 이
  # 파일이 이미 쓰는 관용구이고(T35-9·T36-6) 회수가 chmod 하나로 끝난다. 두 방식의 차이는
  # **회수 명령뿐이다** — 555 도 프로브가 chmod 555 와 chmod 755 사이에서 죽으면 공유 임시
  # 디렉토리에 남고 평범한 rm -rf 를 이긴다(검수 2회차에 이 시그니처의 09-04 자 잔여 2건이
  # 실제로 발견됐고 chmod -R u+w + rm -rf 로만 회수됐다). 그래서 이 루트를
  # register_cleanup_path 에 등록해 중단 경로를 트랩의 fail-safe 에 맡긴다 —
  # cleanup_registered_paths 가 chmod -R 755 를 선행한 뒤 rm -rf 하므로 회수 순서가 정확히
  # 맞는다. 권한 복구를 정리보다 먼저 한다(GOTCHA 10). root 로 돌리면 555 가 무시돼 정리가
  # 성공하는데, 그때 이 프로브는 "가드가 발화하지 않음"으로 시끄럽게 실패한다(fail-loud,
  # 조용한 통과가 아니다).
  #
  # 조각은 T36-3·T36-4 보다 넓게 떼어낸다 — 정리 함수 자신과 그것이 부르는 log_error·색상
  # 상수·CLEANUP_PATHS 선언이 전부 필요하므로 `set -euo pipefail` 줄부터
  # cleanup_registered_paths 정의의 닫는 괄호까지를 한 덩어리로 추출한다(재구현이 아니다 —
  # write_trap_fragment_probe 와 같은 원칙, 범위만 다르다).
  #
  # 판정 순서가 두 단계인 이유: 종료 코드만 보면 "정리 실패를 애초에 만들지 못한 프로브"와
  # "만들었는데 종료 코드가 강제되지 않은 회귀"가 같은 값(0)으로 뭉개진다. 정리 실패
  # 로그를 사전조건으로 먼저 확인하고, 그 다음에 종료 코드를 본다.
  local cleanup_fail_probe_root cleanup_fail_registered cleanup_fail_script
  local cleanup_fail_output cleanup_fail_exit=0
  cleanup_fail_probe_root=$(mktemp -d)
  register_cleanup_path "$cleanup_fail_probe_root"
  cleanup_fail_registered="$cleanup_fail_probe_root/undeletable"
  cleanup_fail_script="$cleanup_fail_probe_root/probe.sh"
  mkdir -p "$cleanup_fail_registered"
  {
    awk '/^set -euo pipefail$/ {emit = 1} emit {print} /^cleanup_registered_paths\(\) \{$/ {in_body = 1} in_body && /^\}$/ {exit}' "$REPO_ROOT/tests/run.sh"
    echo 'CLEANUP_PATHS=()'
    echo "register_cleanup_path \"$cleanup_fail_registered\""
    # 위 write_trap_fragment_probe 와 같은 이유의 옵트인이고, 여기서 빠뜨리는 대가는 더
    # 나쁘다: 센티널이 종료 코드를 1 로 강제하면 이 프로브가 기대하는 값(1)이 우연히
    # 맞아떨어져 아래 T36-10 의 종료 코드 판정이 영구히 공허해진다(이 옵트인 한 줄을 떼고
    # 전체 실행: T36-12 1건 + T37-15 5건 → 34/36 이고, 그 실행에서 T36-10 자신의 판정은
    # 한 번도 발화하지 않았다. 재측정 확인). 두 추출 지점의 옵트인 누락은 T36-12 가
    # 대조로 잡는다.
    echo 'SCRIPT_FULLY_PARSED=1'
  } > "$cleanup_fail_script"
  chmod 555 "$cleanup_fail_probe_root"
  cleanup_fail_output=$(bash "$cleanup_fail_script" 2>&1) || cleanup_fail_exit=$?
  chmod 755 "$cleanup_fail_probe_root" 2> /dev/null || true
  local cleanup_fail_flat="${cleanup_fail_output//$'\n'/ }"
  if [[ "$cleanup_fail_output" != *"rm -rf 가 등록된 경로 일부를 지우지 못함"* ]]; then
    note_failure "T36-10: 사전조건 실패 — 프로브가 정리 실패를 만들지 못함(부모 디렉토리 555 가 존중되지 않았거나 조각 추출 범위가 어긋났다), 아래 판정은 무의미: ${cleanup_fail_flat:0:200}"
  elif [[ "$cleanup_fail_exit" -ne 1 ]]; then
    note_failure "T36-10: 정리 실패를 검출하고도 종료 코드가 강제되지 않음 — 종료 ${cleanup_fail_exit}(기대 1): ${cleanup_fail_flat:0:200}"
  fi
  rm -rf "$cleanup_fail_probe_root"

  ((probes_run++)) || true
  # T36-12(§18 이관 2 의 근본 수정이 만든 함정을 기계에 넘긴다). 파싱 완주 센티널은 조각
  # 프로브에서 구조적으로 설 수 없어 명시 옵트인(조각 끝의 SCRIPT_FULLY_PARSED 대입 한 줄)
  # 을 요구한다 — 앞으로 새 조각 프로브를 쓰면서 그 옵트인을 빠뜨리면, 센티널이 종료 코드를
  # 1 로 강제해 그 프로브의 종료 코드 판정이 조용히 무의미해진다. 구현 중 실제로 관측된
  # 형태다: T36-10 의 프로브(write_trap_fragment_probe 를 쓰지 않고 자기 awk 로 더 넓게
  # 추출하는 쪽)에 옵트인을 넣지 않았을 때, 그 프로브가 기대하는 종료 코드 1 이 센티널의
  # 강제값과 우연히 같아 T36-10 의 종료 코드 판정이 영구히 공허해졌다.
  #
  # 계수 기준(무엇을 세는지):
  #  - 추출 지점 = **주석이 아닌** 줄에서 `awk` 가 이 파일의 여는 앵커 리터럴보다 앞에 오는
  #    줄. 주석 제거는 방어적 전처리다 — 이 파일은 그 앵커 리터럴을 주석에서 상시 인용한다
  #    (리터럴을 담은 주석 5곳 · 그중 앵커로서의 인용이 4곳 — 나머지 1곳은 셸 옵션 언급이다.
  #    이 전처리가 방어하는 집합은 의미가 아니라 리터럴로 결정되므로 5곳이 그 집합이다).
  #    그중 같은 줄에 `awk` 가 앞서는 것은 0곳이라, 지금은 전처리 유무와 무관하게
  #    추출 지점이 2곳으로 읽힌다(재측정 확인). 주석에 `awk` 와 그 앵커를 함께 담은 줄을
  #    심으면 전처리가 그것을 걸러 이 대조가 침묵하는 것도 확인했으니, 전처리 자체는
  #    예방적으로 유효하다 — count_trap_installs_max 가 같은 이유로 같은 전처리를 쓴다.
  #  - 옵트인 발행 = 조각에 그 대입만을 그대로 써 넣는 `echo` 줄(따옴표 안이 대입 전체와
  #    정확히 일치하는 형태). 트랩 자신의 진단 메시지도 그 대입을 문구로 인용하므로
  #    (echo 줄이다) 느슨한 패턴은 그것까지 옵트인으로 센다 — 실측으로 확인하고 좁혔다.
  #
  # 분모가 0 이면 실패로 처리한다(공허 통과 방지 — 이 파일의 확립된 관용구): 추출 패턴이
  # 고장나 0곳이 되면 `0 == 0` 으로 옵트인 0곳과 우연히 맞아 조용히 통과한다.
  #
  # 한계(비망라) — 이것은 두 정적 패턴의 **개수 대조**이지 짝짓기가 아니다. 추출 지점 하나를
  # 지우면서 무관한 옵트인 하나를 함께 넣는 형태는 총계가 유지돼 통과한다(SOURCE_GUARD_ID_
  # FLOOR 의 같은 한계와 동형). 옵트인이 실제로 그 조각 스크립트에 들어가는지(엉뚱한 파일로
  # 리다이렉트되지 않는지)도 보지 않는다 — 그 자리는 T36-8 의 자식 종료 코드 단언이 간접적
  # 으로만 받친다. 추출을 awk 가 아닌 도구(sed·grep)로 쓰는 새 프로브는 추출 지점 계수에서
  # 빠지지만, 그 프로브의 옵트인은 계수에 잡혀 대조가 어긋나므로 fail-loud 로 드러난다.
  # 반대로 주석이 아닌 줄의 **문자열 리터럴**은 추출이 아니어도 추출 지점으로 센다 — 이
  # 그룹 본문에 `awk` 와 그 앵커를 함께 담은 log_info 문구를 넣으니 계수가 3곳으로 읽혀
  # 대조가 어긋났다(재현 확인). 방향은 fail-loud 라 공허 통과가 아니지만, 계수가 "실제
  # 추출"이 아니라 "그 형태의 줄"을 센다는 같은 성질의 대가다.
  # 두 계수는 grep 의 **줄** 수다 — 옵트인 쪽은 패턴이 줄 전체를 앵커해 한 줄에 둘이 올 수
  # 없으니 등가지만, 추출 쪽은 한 줄에 awk 추출을 두 번 쓰면 1곳으로 읽는다(그 경우 대조가
  # 어긋나 발화하므로 안전한 방향이다). 이 대조는 지금 이후의 신규 누락만 막는다 — 옵트인을
  # 빠뜨린 채 지나간 과거 회차가 있었다면, 그 회차에서 실제로 공허했던 판정(그 라운드의
  # T36-10 종료 코드 판정)을 소급해 되돌리지는 않는다(PRP §20-8 신규 2). 전수 증명이 아니다.
  #
  # 여는 앵커를 리터럴로 쓰지 않고 변수에 담는 이유(실측으로 잡은 자기 오염): 계수 명령
  # 자신이 주석이 아닌 줄이라, 그 줄에 `awk` 와 앵커 리터럴이 함께 있으면 자기 자신을 세 번째
  # 추출 지점으로 센다(2곳인데 3곳으로 읽혔다). write_trap_fragment_probe 가 닫는 앵커를
  # 변수에 담는 것과 같은 관용구다.
  local fragment_extraction_points sentinel_optin_emissions
  local fragment_opening_anchor='set -euo pipefail'
  fragment_extraction_points=$(grep -v '^[[:space:]]*#' "$REPO_ROOT/tests/run.sh" \
    | grep -c "awk .*$fragment_opening_anchor") || true
  sentinel_optin_emissions=$(grep -cE "^[[:space:]]*echo \"SCRIPT_FULLY_PARSED=1\"\$|^[[:space:]]*echo 'SCRIPT_FULLY_PARSED=1'\$" \
    "$REPO_ROOT/tests/run.sh") || true
  if [[ "$fragment_extraction_points" -eq 0 ]]; then
    note_failure "T36-12: 사전조건 실패 — 조각 추출 지점이 0곳(추출 패턴 고장, 옵트인 대조의 분모가 공허하다)"
  elif [[ "$fragment_extraction_points" -ne "$sentinel_optin_emissions" ]]; then
    note_failure "T36-12: 조각 추출 지점 ${fragment_extraction_points}곳 vs 파싱 완주 센티널 옵트인 발행 ${sentinel_optin_emissions}곳 — 새 조각 프로브가 옵트인을 빠뜨리면 그 프로브의 종료 코드 판정이 조용히 무의미해진다"
  fi

  ((probes_run++)) || true
  # T36-13(PRP §17 이관 4 회귀 가드 — 검수 산문 렌즈 HIGH 차단 해소). 위 T36-7 은 정상 실행에서
  # cleanup_registered_paths 가 실패하지 않아 log_error 에 도달하지 않는다 — 그래서 log_error
  # 의 스트림 전환(stdout→stderr, 위 그 함수 주석 참고) 자체를 실제로 무는 검사가 없었다(검수
  # 실측: log_error 의 >&2 를 되돌려도 --only T36 이 그대로 통과). 여기서는 T36-10 과 같은
  # 방법(등록 경로의 부모를 555 로 만들어 chmod -R 755 이후에도 살아남는 rm -rf 실패를 실제로
  # 만든다 — 그 함수 주석이 이 방식을 chflags uchg 대신 고른 이유를 적어 뒀다)으로 정리 실패를
  # 유발하고, 호출을 T36-7 과 같은 방식(2>&1 없이 stdout 만 변수로 캡처)으로 감싸 그 캡처에
  # [ERROR] 문구가 섞이는지 직접 확인한다. stderr 는 별도 파일로 받아, "정리 실패 자체를 못
  # 만들었다"(사전조건 실패)와 "문구가 stdout 으로 유출됨"(회귀)을 두 단계로 구분한다 — T36-10
  # 의 "판정 순서가 두 단계인 이유"와 같은 이유다.
  #
  # 555 를 고르는 이유(이식성 + 원복 보장) — chflags uchg 도 같은 rm -rf 실패를 만들지만
  # (T36-10 주석) macOS 전용이고, 무엇보다 cleanup_registered_paths 자신의 fail-safe(그
  # 함수의 chmod -R 755)가 uchg 는 되돌리지 못한다(chflags nouchg 호출이 이 파일 어디에도
  # 없다) — 이 프로브가 중간에 죽어도 register_cleanup_path 로 미리 등록해 두면 전역 EXIT
  # 트랩(suite_exit_guard)의 fail-safe 가 555 잔여는 그 chmod -R 755 로 스스로 되돌리지만
  # uchg 잔여는 되돌리지 못한다 — 555 는 기존 안전망과 합성되고 uchg 는 합성되지 않는다는
  # 것이 이 선택의 근거다(T35-9·T36-6·T36-10 이 이미 같은 이유로 555 를 쓴다).
  #
  # T36-10 과 실패 유발 기법은 같지만 판정 대상이 다르다 — 그쪽은 종료 코드 강제를, 이쪽은
  # stdout/stderr 분리를 본다. 서로 대체하지 않으므로 「중복」으로 보고 한쪽을 지우면 그
  # 축의 회귀가 무방비가 된다.
  #
  # 한계(비망라) — 이 프로브가 검사하는 대상은 log_error 한 함수의 스트림에 한정된다:
  # log_info·log_ok·log_warn 은 대상이 아니고(위 그 함수 주석이 옮기지 않는 이유를 적었다),
  # 이 파일의 다른 39곳(구현 보고 전수 점검)의 2>&1 유무는 이 프로브가 아니라 그 자리 각각의
  # 판정 로직에 달려 있다. 전수 증명이 아니다.
  local stream_probe_root stream_probe_target stream_probe_stderr_file
  local stream_probe_stdout stream_probe_stderr stream_probe_combined
  stream_probe_root=$(mktemp -d)
  register_cleanup_path "$stream_probe_root"
  stream_probe_target="$stream_probe_root/undeletable"
  stream_probe_stderr_file=$(mktemp)
  mkdir -p "$stream_probe_target"
  chmod 555 "$stream_probe_root"
  # 이 프로브 자체가 밟은 함정(실측) — `2> file` 을 닫는 `)` 뒤로 옮기면(`$( … ) 2> file`)
  # 명령 치환 서브셸 내부의 stderr 는 잡히지 않고 터미널로 샌다(bash 가 대입 전용
  # 단순 명령의 리다이렉션을 값 전개보다 나중에 적용하기 때문). 안쪽 `{ … } 2> file` 형태를
  # 유지해야 한다.
  stream_probe_stdout=$(
    {
      CLEANUP_PATHS=()
      register_cleanup_path "$stream_probe_target"
      cleanup_registered_paths
    } 2> "$stream_probe_stderr_file"
  )
  chmod 755 "$stream_probe_root" 2> /dev/null || true
  stream_probe_stderr=$(cat "$stream_probe_stderr_file" 2> /dev/null || true)
  rm -f "$stream_probe_stderr_file"
  rm -rf "$stream_probe_root"
  stream_probe_combined="${stream_probe_stdout}${stream_probe_stderr}"
  if [[ "$stream_probe_combined" != *"rm -rf 가 등록된 경로 일부를 지우지 못함"* ]]; then
    note_failure "T36-13: 사전조건 실패 — 정리 실패를 실제로 만들지 못함(부모 555 가 존중되지 않았을 수 있다), 아래 판정은 무의미 — 캡처: ${stream_probe_combined:0:200}"
  elif [[ "$stream_probe_stdout" == *"rm -rf 가 등록된 경로 일부를 지우지 못함"* ]]; then
    note_failure "T36-13: log_error 출력이 stdout 으로 샘 — cleanup_registered_paths 실패 로그가 2>&1 없는 캡처에 섞임(log_error 가 stderr(>&2) 로 쓰지 않는 회귀): ${stream_probe_stdout:0:200}"
  fi

  if [[ "$probes_run" -ne 9 ]]; then
    note_failure "T36-0: 이 그룹이 실행해야 할 검사 9건 중 ${probes_run}건만 실행됨(공허 통과 방지)"
  fi

  finish_group "$test_name"
}

# ============================================================================
# 뮤테이션 원장 하네스 (S3a, tests-hardening PRP §4.4·§7 — G1·G2 를 기계로 닫는다)
# ============================================================================

# 원장 한 줄(탭 구분)을 \x1f(unit separator)로 재구분해 낸다. bash 의 IFS=tab read 는
# tab 을 공백류로 취급해 빈 필드를 collapse 한다(실측 확인) — awk BEGIN 블록 안에서
# OFS 를 지정해 우회한다(awk 의 -F/-v 플래그로 \x1f 같은 16진 이스케이프를 넘기면
# 이 환경의 awk(BWK awk 20200816)가 해석하지 못한다는 것도 실측 확인했다 — 그래서
# 항상 프로그램 문자열 안에서만 \x1f 를 쓴다).
reformat_mutation_row_fields() {
  awk -F'\t' 'BEGIN{OFS="\x1f"} {$1=$1; print}' <<< "$1"
}

# 한 줄의 탭 구분 열 수를 센다(awk NF — read 의 collapse 문제를 피한다).
count_mutation_row_columns() {
  awk -F'\t' '{print NF}' <<< "$1"
}

# candidate 가 TEST_GROUPS(§6-2)에 등록된 그룹 ID 인지 검사한다.
is_registered_test_group() {
  local candidate="$1" entry
  for entry in "${TEST_GROUPS[@]}"; do
    [[ "${entry%%:*}" == "$candidate" ]] && return 0
  done
  return 1
}

# guard_id 가 §6-1 불변식 1(포맷 T[0-9]+-[0-9a-z]+ + 원장 내 유일성)을 만족하는지 검사한다.
# 유일성 누적은 호출자(parse_mutation_ledger)가 선언한 seen_guard_ids 배열을 동적 스코프로
# 공유한다 — bash 3.2 에 연관 배열이 없어(GOTCHA 3) 선형 탐색으로 대신한다. 이 선형 탐색은
# T37 의 병목이 아니다 — 실행 시간은 변조행마다 미러를 뜨고 변조 후 그룹을 돌리는 데서
# 나온다(변조 전 실행은 그룹당 1회다). 행 수와 실측 시간은 커밋마다 움직이는 값이라 적지
# 않는다(옛 문면의 「398행·8초대」가 둘 다 낡아 있었다) — 기본 실행은 증분이라(이번 변경이
# 닿은 행만 판정) 전체 재확인 시간은 `time CODING_HARNESS_K6_FULL=1 bash tests/run.sh --only T37`
# 로 잰다. PRP §12.
validate_guard_id_token() {
  local guard_id="$1"
  [[ "$guard_id" =~ ^T[0-9]+-[0-9a-z]+$ ]] || return 1
  local seen
  if ((${#seen_guard_ids[@]} > 0)); then
    for seen in "${seen_guard_ids[@]}"; do
      [[ "$seen" == "$guard_id" ]] && return 1
    done
  fi
  seen_guard_ids+=("$guard_id")
  return 0
}

# target_path 가 §6-1 불변식 2(레포 상대경로 · 실재)를 만족하는지 검사한다.
#
# 존재 검사만으로는 부족했던 이유(검수 1회차에서 재현된 결함): 이 값은 아래 apply_mutation
# 에서 "$mirror_dir/$target_path" 로 문자열 결합돼 sed -i 의 대상이 된다. 절대 경로나 `..`
# 가 섞인 값은 미러 봉쇄 밖을 가리키면서 "$REPO_ROOT/$1" 존재 검사를 동시에 통과할 수
# 있고, 그 상태로 실제 저장소 파일이 변조되는 것이 실측됐다. 원장은 사람이 손으로 쓰는
# 파일이라 「검증은 저장소를 읽기 전용으로 대한다」는 전제를 깨뜨릴 수 있는 열을 파서에서
# 막는다(현행 원장 전 행의 target_path 가 레포 상대경로라 위양성이 없다).
#
# 이 함수가 막는 것은 **target_path 열이 여는 쓰기 경로 하나**다. 같은 행의 mutation_sed
# 열도 독립적인 쓰기 경로다 — `s/…/…/w <경로>` 처럼 sed 의 파일 명령을 담으면 target_path
# 가 미러 안이어도 미러 밖에 파일이 실제로 생긴다(검수 3회차에 재현됐다). 그쪽은 불변식 4
# (mutation_sed_is_write_safe)가 막는다. 두 열을 각각 봐야 하는 이유가 이것이다.
validate_mutation_target_path() {
  [[ "$1" != /* ]] || return 1
  [[ "$1" != *..* ]] || return 1
  [[ -e "$REPO_ROOT/$1" ]]
}

# 면제행 구조(불변식 3): exempt_reason 이 있고, expect_group·expect_token·anchor_function
# 은 반드시 "-"(anchor_function 추가는 ledger-anchor-column PRP §5-2).
validate_exempt_row_structure() {
  local expect_group="$1" expect_token="$2" exempt_reason="$3" anchor_function="$4"
  [[ -n "$exempt_reason" ]] || return 1
  [[ "$expect_group" == "-" && "$expect_token" == "-" && "$anchor_function" == "-" ]]
}

# mutation_sed 가 미러 밖에 쓰지 않는 형태인지 검사한다(불변식 4의 한 절). 0=안전, 1=거부.
#
# 왜 필요한가(검수 3회차에 재현된 결함): sed 는 치환만 하는 언어가 아니다 — `w`/`W` 플래그와
# 독립 명령 `w`/`W`/`r`/`R`, 그리고 GNU 의 `e` 는 임의 경로를 파일로 열거나 셸을 실행한다.
# 원장 한 행이 target_path 는 미러 안에 두고 mutation_sed 에 `1s/$/ /w /절대/경로` 를 담으면
# 불변식 2(절대경로·`..` 거부) · 불변식 4(`-f` 요구) · mutation_target_is_inside_mirror 의
# 3층을 전부 통과하면서 미러 밖에 파일이 실제로 생겼다(BSD sed 로 재현). 그 열을 여기서 막는다.
#
# 기제: sed 스크립트를 파싱하지 않는다. 백슬래시 이스케이프를 **2단으로** 지워 구분자
# 계수를 정규화한 뒤 **주소 하나 + `/` 구분자 s 명령 하나**라는 형태만 인식하고, 인식한
# 형태에서는 플래그 자리가 어디인지 알 수 있으므로 그 자리에서만 파일 명령 글자를 거부한다.
# 스크립트 전체를 글자로 훑으면 안 되는 이유: `s/echo/true/` 처럼 패턴·치환문에 그 글자가
# 든 정상 변조가 함께 걸린다(실측 — 글자 집합 {w,W,r,R,e} 로 전체를 훑으면 현행 원장 4행
# 중 4행이 걸리고, `e` 를 뺀 {w,W,r,R} 로도 3행이 걸린다. 그래서 이 대조는 플래그 자리에
# 한정한다).
#
# 정규화의 **순서가 규약이다**(검수 3회차 차단 1 로 재현된 우회): `\\` 쌍을 먼저 지우고,
# 그 다음에 이스케이프된 구분자 `\/` 를 지운다. 순서를 바꾸면 `\\/` — sed 에서 「이스케이프된
# 백슬래시 + **진짜** 구분자」 — 에서 `\/` 대조가 뒤쪽 백슬래시와 그 진짜 구분자를 함께
# 지워 구분자를 이 대조의 시야에서 감춘다. 그러면 플래그 자리의 `w` 가 치환문 안에 있는
# 것처럼 보여 아래 tail 대조를 빠져나간다(`s/^  total_tests=.*$/  total_tests=37\\/w ../zzq1`
# 이 수락되고, 그 sed 가 미러도 레포도 아닌 곳에 18바이트 파일을 실제로 만드는 것을
# 실측했다). `\\` 를 먼저 지우면 진짜 구분자가 남아 형태 인식이 그 행을 fail-close 로
# 거부한다. 회귀는 T37-5 의 `\\/` fixture 가 고정한다.
#
# 한계(비망라) — 인식하지 못하는 형태는 안전 여부를 판정하지 않고 거부한다(fail-close):
# 다른 구분자(`s|a|b|`) · `;` 로 이어붙인 여러 명령 · 주소 범위 · `y///` · 독립 `r`/`w`
# 명령이 전부 여기 해당하고, 그 형태가 필요해지면 이 함수를 넓히는 커밋에 이유를 남긴다.
# 반대 방향으로, 인식한 형태 안에서도 이 대조가 못 보는 sed 문법이 남을 수 있다 — 이것은
# 패턴 검사이지 sed 문법의 전수 증명이 아니다. 다만 위 `\\/` 우회는 그 일반 면책 안에 있던
# 것이 **아니다** — 1단 정규화가 실제로 수락했고 미러 밖 쓰기가 재현된, 놓쳤던 구멍이다.
# 심볼릭 링크를 경유하는 쓰기는 이 함수가
# 아니라 BSD sed 자신이 막는다(`in-place editing only works for regular files`) — 그리고
# 이 레포에는 심볼릭 링크가 0개다(검수 실측).
mutation_sed_is_write_safe() {
  # 순서 의존(위 「정규화의 순서가 규약이다」) — 1단 `\\` 쌍, 2단 `\/`. 바꾸면 우회가 살아난다.
  local normalized="${1//\\\\/}"
  normalized="${normalized//\\\//}"
  local recognized_shape='^([0-9]+|\$)?s/[^/]*/[^/]*/([^/]*)$'
  [[ "$normalized" =~ $recognized_shape ]] || return 1
  [[ "${BASH_REMATCH[2]}" != *[wWrRe]* ]]
}

# 변조행 구조(불변식 4 + GOTCHA 7): exempt_reason 은 비어야 하고, expect_token 이 있어야
# 하고, anchor_function(8번째 열, ledger-anchor-column PRP §5-2)이 맨 함수명 형식
# (^[A-Za-z_][A-Za-z0-9_]*$)이어야 하고, expect_group 은 등록된 그룹이면서 이 하네스
# 자신($MUTATION_HARNESS_GROUP)이면 안 된다 — 미러 안에서 이 그룹을 실행하는 것은 무한
# 재귀라(GOTCHA 7) 원장 단계에서부터 차단한다. 변조 대상은 정규 파일이어야 하고(sed -i 의
# 대상이므로 디렉토리·특수 파일은 무효다), mutation_sed 는 위 write-safe 형태여야 한다.
#
# 이 두 요구를 면제행에 걸지 않는 이유: 면제행은 apply_mutation 에 도달하는 실행 경로가
# 없어 `-f` 도 write-safe 도 안전에 기여하지 않고, 대상의 실재는 불변식 2 의 `-e` 가 이미
# 요구한다.
#
# 조건별로 log_error 를 남기는 이유(PRP §18 이관 11) — 예전에는 호출자(아래
# validate_and_collect_mutation_row)가 이 함수의 반환값 0/1 만 보고 "변조행 구조 위반"
# 이라는 한 문구로만 보고해, 6개 조건 중 무엇이 걸렸는지 원장 작성자가 알 수 없었다(3회차
# 실측 — write-safe 거부가 이 문구로만 나왔다). 여기서 조건별 사유를 먼저 찍고 그대로
# return 1 하면, 호출자의 기존 메시지가 뒤이어 한 번 더 찍힌다 — 새 문구를 덧붙일 뿐
# 기존 "변조행 구조 위반(guard_id=…, expect_group=…)" 문구는 그대로 남는다(T37-5·T37-6 이
# 그 문구의 부분 문자열에 앵커한다, GOTCHA 참고). 호출 규약(인자·반환값)은 바꾸지 않았다.
validate_mutation_row_structure() {
  local expect_group="$1" expect_token="$2" exempt_reason="$3" target_path="$4" mutation_sed="$5" anchor_function="$6"
  if [[ -n "$exempt_reason" ]]; then
    log_error "validate_mutation_row_structure: exempt_reason 이 비어있지 않음(변조행은 면제 사유를 가질 수 없다): '$exempt_reason'"
    return 1
  fi
  if [[ -z "$expect_token" ]]; then
    log_error "validate_mutation_row_structure: expect_token 공백(변조행은 실패 메시지 판별 토큰이 있어야 한다)"
    return 1
  fi
  if [[ ! "$anchor_function" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]]; then
    log_error "validate_mutation_row_structure: anchor_function 형식 위반(맨 함수명이어야 함 — 괄호·중괄호·경로·줄번호 금지): '$anchor_function'"
    return 1
  fi
  if [[ ! -f "$REPO_ROOT/$target_path" ]]; then
    log_error "validate_mutation_row_structure: target_path 가 정규 파일이 아님(sed -i 의 대상이어야 한다): '$target_path'"
    return 1
  fi
  if ! mutation_sed_is_write_safe "$mutation_sed"; then
    log_error "validate_mutation_row_structure: mutation_sed 가 write-safe 형태로 인식되지 않음(구분자·플래그 자리 확인): '$mutation_sed'"
    return 1
  fi
  if [[ "$expect_group" == "$MUTATION_HARNESS_GROUP" ]]; then
    log_error "validate_mutation_row_structure: expect_group 이 하네스 자신(${MUTATION_HARNESS_GROUP})을 가리킴(GOTCHA 7 — 미러 안에서 무한 재귀)"
    return 1
  fi
  if ! is_registered_test_group "$expect_group"; then
    log_error "validate_mutation_row_structure: expect_group 이 TEST_GROUPS 에 등록되지 않음: '$expect_group'"
    return 1
  fi
  return 0
}

# 한 행의 §6-1 불변식 1~6 전부를 검사한다. 위반이면 log_error 로 사유(줄 번호·guard_id
# 포함)를 보고하고 1을 반환한다. 통과하면 raw_line 을 그대로 output_rows(동적 스코프,
# parse_mutation_ledger 가 선언)에 쌓는다.
validate_and_collect_mutation_row() {
  local line_number="$1" raw_line="$2"
  local field_count
  field_count=$(count_mutation_row_columns "$raw_line")
  if [[ "$field_count" -ne 8 ]]; then
    log_error "parse_mutation_ledger:${line_number}: 열 수 ${field_count}(기대 8)"
    return 1
  fi

  local reformatted guard_id target_path mutation_sed expect_group expect_token defect_description exempt_reason anchor_function
  reformatted=$(reformat_mutation_row_fields "$raw_line")
  IFS=$'\x1f' read -r guard_id target_path mutation_sed expect_group expect_token defect_description exempt_reason anchor_function <<< "$reformatted"

  if ! validate_guard_id_token "$guard_id"; then
    log_error "parse_mutation_ledger:${line_number}: guard_id 포맷/유일성 위반: '$guard_id'"
    return 1
  fi
  if ! validate_mutation_target_path "$target_path"; then
    log_error "parse_mutation_ledger:${line_number}: target_path 무효(레포 상대경로가 아니거나 실재하지 않음): '$target_path'(guard_id=$guard_id)"
    return 1
  fi
  if [[ -z "$defect_description" ]]; then
    log_error "parse_mutation_ledger:${line_number}: defect_description 공백(guard_id=$guard_id)"
    return 1
  fi

  if [[ "$mutation_sed" == "-" ]]; then
    if ! validate_exempt_row_structure "$expect_group" "$expect_token" "$exempt_reason" "$anchor_function"; then
      log_error "parse_mutation_ledger:${line_number}: 면제행 구조 위반(guard_id=$guard_id)"
      return 1
    fi
  else
    if ! validate_mutation_row_structure "$expect_group" "$expect_token" "$exempt_reason" "$target_path" "$mutation_sed" "$anchor_function"; then
      log_error "parse_mutation_ledger:${line_number}: 변조행 구조 위반(guard_id=$guard_id, expect_group=$expect_group)"
      return 1
    fi
  fi

  output_rows+=("$raw_line")
  return 0
}

# 원장을 파싱해 정규화된 행을 stdout 에 낸다(§6-1 불변식 1~6, PRP §7 시그니처). 주석(#)·
# 빈 줄은 무시한다. 위반 행이 하나라도 있으면 조용히 건너뛰지 않고 **반환 1**(전체 파싱
# 실패 — 부분 출력 없음, §6-1 불변식 6 산문 그대로).
#
# `exit` 를 쓰지 않는 이유 — PRP §7 시그니처 문구는 "불변식 위반은 exit 1" 이지만 그대로
# 옮기면 안 된다: 시나리오 테스트 mutation_ledger_fixture_is_rejected 가 이 함수를 명령
# 치환·서브셸 없이 직접 부르므로, exit 로 바꾸면 T37-1~T37-8 에서 스위트 자체가 그 자리에서
# 죽는다. 주석을 따라 "고치는" 정비를 막기 위해 여기 적어 둔다.
parse_mutation_ledger() {
  local ledger_path="$1"
  if [[ ! -f "$ledger_path" ]]; then
    log_error "parse_mutation_ledger: 원장 파일 미존재: $ledger_path"
    return 1
  fi

  local seen_guard_ids=() output_rows=() line_number=0 raw_line
  while IFS= read -r raw_line || [[ -n "$raw_line" ]]; do
    ((line_number++)) || true
    [[ -z "$raw_line" ]] && continue
    [[ "$raw_line" =~ ^[[:space:]]*# ]] && continue
    validate_and_collect_mutation_row "$line_number" "$raw_line" || return 1
  done < "$ledger_path"

  # bash 3.2 는 빈 배열이어도 "${arr[@]}" 순회 자체가 set -u 에서 unbound 이므로(실측
  # 확인 — verify_group_registry_parity 의 같은 함정과 동일) 원소가 있을 때만 순회한다.
  local row
  if ((${#output_rows[@]} == 0)); then
    return 0
  fi
  for row in "${output_rows[@]}"; do
    printf '%s\n' "$row"
  done
}

# tests/run.sh 소스에서 note_failure/record_failure 호출의 리터럴 "T{n}-{k}" ID 접두를
# 추출한다(NOTE_FAILURE_ID_LESS_RATCHET 주석의 추출 규칙과 동일 — 줄 시작이 호출인 것만,
# 주석 제외, 한 줄에 여럿이면 첫 것만). 정렬된 유일 목록을 낸다(PRP §7 시그니처).
#
# 한계(비망라) — 줄 시작 앵커의 대가다: `x=$(f) || { note_failure "T40-1: …"; }` 처럼 호출이
# 줄 중간에 오면 그 ID 는 이 집합에도 래칫의 분모에도 들어가지 않아, 「ID 를 붙이는 순간
# 완비 검사가 그 ID 를 요구한다」는 K5 의 요구를 빠져나간다. 이 파일 자신이 그 형태를 한 개
# 갖고 있었고(assert_guard_bites 의 미러 생성 실패 보고 — T37-15 가 이 집합에서 빠지는 것을
# 실측한 뒤 줄 시작 형태로 고쳤다), 앵커를 없애면 주석·문자열 안의 단순 언급까지 세어
# 래칫의 분모가 오염되므로 앵커는 유지하고 이 한계를 표기한다.
#
# 같은 계열의 두 번째 구멍 — 여는 따옴표가 작은따옴표인 호출(`note_failure 'T25-37: …'`)도
# 이 집합에서 빠진다. 아래 정규식이 `"` 를 요구하기 때문이고, 이 파일에 실제로 1건 있다
# (같은 ID 가 큰따옴표 형태로도 있어 K5 구멍이 실제로 열리지는 않았다 — 실측 확인).
# 이 형태는 NOTE_FAILURE_ID_LESS_RATCHET 의 분모가 대신 잡는다(그 상수 주석의 분해 (d)).
# 전수 증명이 아니다.
collect_guard_ids() {
  local source_path="$1"
  local line
  while IFS= read -r line; do
    if [[ "$line" =~ \"(T[0-9]+-[0-9a-z]+) ]]; then
      echo "${BASH_REMATCH[1]}"
    fi
  done < <(grep -E '^[[:space:]]*(note_failure|record_failure)[[:space:]]' "$source_path") | sort -u
}

# 개별 미러 사본을 담는 부모 디렉토리. T37 본문이 mktemp -d 로 만들어 register_cleanup_path
# 로 등록한 뒤 여기에 넣는다(빈 값이면 make_repo_mirror 가 실패한다).
#
# 이 간접층이 있는 이유(주제 5-a): 개별 미러를 직접 등록할 수는 없다 — make_repo_mirror 는
# 항상 mirror_dir=$(make_repo_mirror) 형태(명령 치환)로 불리고, 명령 치환은 서브셸이라 그
# 안의 register_cleanup_path 는 CLEANUP_PATHS 를 서브셸 사본에만 채운다(실측 확인).
# assert_guard_bites 가 정상 경로에서 미러를 즉시 rm -rf 하므로 정상 경로 누수는 0 이지만,
# 중단(SIGTERM·Ctrl-C·CI 타임아웃)에는 그 rm 에 도달하지 못해 11MB 사본이 남았다 — S2 가
# 세운 fail-safe(suite_exit_guard → cleanup_registered_paths)는 CLEANUP_PATHS 만 보므로
# 그 경로에 닿지 않았다. 부모 디렉토리 한 개를 등록해 두면 개별 미러를 등록하지 않고도
# 중단 시 정리가 fail-safe 에 걸린다.
MUTATION_MIRROR_ROOT=""

# K6 증분 판정(docs/prps/t37-incremental-k6.md)의 새 상수·전역 — 하네스 구역에 둔다. T36 조각
# 프로브가 떼어 내는 범위(set -euo pipefail 줄부터 trap suite_exit_guard EXIT 줄과
# cleanup_registered_paths 닫는 줄까지)는 이 구역보다 위라 프로브가 흔들리지 않는다.
#
# 비교 기준 원격 참조 이름(§4). 기준은 `git merge-base HEAD <이 참조>` 다 — 로컬 main 이 아니라
# 원격 추적 참조를 쓰는 이유: main 체크아웃에서 커밋한 뒤 게이트를 다시 돌리면 로컬 main 은 HEAD 와
# 같아 방금 커밋한 변경을 놓친다. 원격 이름이 다른 저장소에서 바꿀 자리다.
readonly K6_DIFF_BASE_REF="origin/main"

# 가드 블록(그룹 함수 안에서 서브체크 ID 를 담은 줄과 토큰 보고 줄을 감싼 구간)에 앞뒤로 붙이는 여유
# 줄 수(§3-2 의 W). 블록 밖 준비 코드가 가드 판정에 닿는 경로를 덮는 폭이다 — 넓힐수록 선택이 늘고
# (시간이 든다) 좁힐수록 줄어든다(놓치는 경로가 는다). 선택 범위만 바꾸고 판정은 바꾸지 않으므로 이
# 값을 고쳐도 전체 재확인이 필요 없다.
readonly K6_GUARD_BLOCK_MARGIN_LINES=10

# 전체 재확인 요청 환경변수 이름(§6) — 출력 문면과 판정이 같은 이름을 보게 상수로 둔다.
readonly K6_FULL_REQUEST_ENV_NAME="CODING_HARNESS_K6_FULL"

# 스위트 끝 요약(print_test_summary)이 찍는 K6 한 줄 — T37-15 가 채운다. T37 이 돌지 않은 실행에서는
# 빈 값이라 요약에 이 줄이 없다. 최상위에서 빈 값을 대입해 호출자 환경의 상속값을 덮는다
# (SCRIPT_FULLY_PARSED 와 같은 이유 — 상속된 값이 거짓 K6 줄을 찍지 못하게 한다).
K6_SUMMARY_LINE=""

# 변조 가능한 레포 사본을 MUTATION_MIRROR_ROOT 아래에 만들고 경로를 stdout 으로 낸다
# (PRP §7). .git 은 rsync 시간·용량에 무의미해 제외한다(실측 rsync -a --exclude .git
# ≈ 150-170ms·11MB, 구현 보고 근거).
#
# mktemp 결과를 검사하는 이유(검수 1회차 Critical): set -e 는 그룹 함수 호출 트리에서 꺼져
# 있어(GOTCHA 1) mktemp 실패가 빈 문자열로 조용히 흐르고, 그 빈 값이 rsync 목적지로 가면
# `rsync -a "$REPO_ROOT/" "/"` 가 된다. 빈 경로를 하류로 넘기지 않고 여기서 끊는다.
make_repo_mirror() {
  if [[ -z "$MUTATION_MIRROR_ROOT" || ! -d "$MUTATION_MIRROR_ROOT" ]]; then
    log_error "make_repo_mirror: 미러 루트가 준비되지 않음('$MUTATION_MIRROR_ROOT') — T37 본문이 mktemp -d 로 만들고 register_cleanup_path 로 등록한 뒤 MUTATION_MIRROR_ROOT 에 넣어야 한다"
    return 1
  fi
  local mirror_dir
  mirror_dir=$(mktemp -d "$MUTATION_MIRROR_ROOT/mirror.XXXXXX") || mirror_dir=""
  if [[ -z "$mirror_dir" || ! -d "$mirror_dir" ]]; then
    log_error "make_repo_mirror: mktemp -d 가 미러 경로를 만들지 못함(임시 공간 부족·죽은 TMPDIR·inode 고갈 가능) — 빈 경로를 하류의 rsync·rm 인자로 넘기지 않고 여기서 끊는다"
    return 1
  fi
  if ! rsync -a --exclude .git "$REPO_ROOT/" "$mirror_dir/" > /dev/null 2>&1; then
    log_error "make_repo_mirror: rsync 로 레포 사본 생성 실패($mirror_dir)"
    rm -rf -- "$mirror_dir"
    return 1
  fi
  echo "$mirror_dir"
}

# full_path 가 mirror_dir 봉쇄 안에 있는지 실제 경로(pwd -P, 심볼릭 링크 해소)로 확인한다.
# 파서(validate_mutation_target_path)가 이미 절대경로·`..` 를 거부하지만, 원장은 사람이
# 손으로 쓰는 파일이라 sed -i 의 대상 경로를 쓰기 직전에 한 번 더 본다.
# 0=봉쇄 안, 1=봉쇄 밖(또는 경로 해소 실패).
#
# 한계(비망라) — 이 함수가 보는 것은 **sed -i 의 대상 경로**뿐이고, 그것이 저장소에 쓰는
# 유일한 경로는 아니다: 같은 행의 mutation_sed 가 sed 의 파일 명령을 담으면 대상 경로가
# 봉쇄 안이어도 미러 밖에 쓴다(검수 3회차 재현). 그쪽은 파서의 mutation_sed_is_write_safe
# 가 막고 이 자리에서는 다시 보지 않는다 — apply_mutation 에 닿는 mutation_sed 는
# 파서를 통과한 원장 행과 T37-16 의 하드코딩 fixture 뿐이어서, 여기 한 층을 더 두면
# 도달 경로 없는 코드가 된다. 전수 증명이 아니다.
mutation_target_is_inside_mirror() {
  local mirror_dir="$1" full_path="$2"
  local resolved_mirror resolved_parent
  resolved_mirror=$(cd "$mirror_dir" && pwd -P) || return 1
  resolved_parent=$(cd "$(dirname "$full_path")" && pwd -P) || return 1
  case "$resolved_parent/" in
    "$resolved_mirror"/*) return 0 ;;
  esac
  return 1
}

# 사본 안 target_path 에 sed_script 를 적용하고 실제로 바이트가 바뀌었는지 해시로
# 확인한다(기존 T35-8 의 grep 존재-확인보다 강하다, PRP §4.4-(2)-3). sed -i 는 BSD 라
# -i.bak 형태를 쓰고 .bak 를 지운다(GOTCHA 4). 0=바뀜, 1=안 바뀜(사전조건 실패로 취급).
apply_mutation() {
  local mirror_dir="$1" target_path="$2" sed_script="$3"
  local full_path="$mirror_dir/$target_path"
  if [[ ! -f "$full_path" ]]; then
    log_error "apply_mutation: 사본 안에 대상 파일 없음: $full_path"
    return 1
  fi
  if ! mutation_target_is_inside_mirror "$mirror_dir" "$full_path"; then
    log_error "apply_mutation: 변조 대상이 미러 봉쇄 밖을 가리킴 — 쓰기를 거부한다: $full_path"
    return 1
  fi
  local before_hash after_hash
  before_hash=$(compute_sha256_for_test "$full_path")
  sed -i.bak "$sed_script" "$full_path"
  rm -f "$full_path.bak"
  after_hash=$(compute_sha256_for_test "$full_path")
  [[ "$before_hash" != "$after_hash" ]]
}

# 사본에서 그룹 하나만 실행한다. stdout=로그 전문, 반환=그룹 판정(0=PASS, PRP §7 시그니처).
# 바깥 스위트가 CODING_HARNESS_TEST_HOME 을 지정했더라도 이 중첩 실행에는 물려주지 않는다
# (T36-3 선례와 같은 이유 — 물려주면 중첩 실행이 바깥과 같은 HOME 을 동시에 써 경합한다).
# GOTCHA 7 — group_id 가 이 하네스 자신이면 무한 재귀이므로 parse_mutation_ledger 가 이미
# 그런 행을 거부하지만, 이 함수도 방어적으로 한 번 더 막는다(이중화).
run_group_in_mirror() {
  local mirror_dir="$1" group_id="$2"
  if [[ "$group_id" == "$MUTATION_HARNESS_GROUP" ]]; then
    log_error "run_group_in_mirror: ${MUTATION_HARNESS_GROUP} 을 미러에서 실행하는 것은 무한 재귀라 금지됨(GOTCHA 7)"
    return 1
  fi
  ( unset CODING_HARNESS_TEST_HOME; bash "$mirror_dir/tests/run.sh" --only "$group_id" ) 2>&1
  return $?
}

# 원장 한 행에 대해 sed 적용 확인 → 정방향 FAIL → 토큰 일치를 차례로 검사한다(K6, PRP §7
# 시그니처). 사전조건이 깨지면(sed 미적용) "사전조건 실패"로 보고하고 뒤 단계로 넘어가지
# 않는다 — A9 의 해법(PRP §4.4-(2)-2) 중 「변조 전 PASS」는 행마다가 아니라 그룹마다 한 번
# 확인하도록 옮겼다: judge_k6_selected_rows 가 같은 그룹의 행을 판정하기 전에
# run_k6_group_precondition 으로 확인한다(docs/prps/t37-incremental-k6.md §7). 그 쌍이
# "변조로 넓어졌다"와 "이미 넓게 출하됐다"를 구분하는 근거는 그룹 단위로도 그대로 성립한다.
# 그래서 이 함수의 전제는 「호출자가 그룹 사전조건을 이미 확인했다」다 — T37-16 만 예외로,
# 바깥 실행에서 T29 가 통과한다는 사실 위에서 사전조건 없이 직접 부른다. note_failure 에
# 정적 접두 "T37-15"를 쓴다 — guard_id 는 호출마다 달라지는 값이라 소스 텍스트에 리터럴로
# 나타나지 않으므로 collect_guard_ids 가 추출하지 못한다(대신 이 정적 접두가 추출된다 —
# 그러려면 그 호출이 줄 시작이어야 한다, collect_guard_ids 의 한계 절).
#
# mirror_dir 를 register_cleanup_path 로 등록하지 않고 이 함수 안에서 직접 rm -rf 한다
# (단일 종료 지점, 실패 메시지는 지역 변수에 모았다가 마지막에 한 번만 note_failure).
# 이유: 이 함수는 T37-16(자기 고정점)에서 output=$(assert_guard_bites ...) 형태(명령
# 치환)로도 불린다 — 그러면 이 함수 몸통 전체가 서브셸에서 실행되므로, 어디에 두든
# register_cleanup_path 는 부모(T37)의 CLEANUP_PATHS 에 반영되지 않는다(실측 확인,
# make_repo_mirror 주석과 같은 함정). rm -rf 는 서브셸 안에서도 실제 파일을 지우므로
# 이 함정에서 자유롭다. 중단(SIGTERM·Ctrl-C) 경로에서 이 rm 에 도달하지 못하는 경우의
# fail-safe 는 개별 미러가 아니라 MUTATION_MIRROR_ROOT 등록이 담당한다(그 변수 주석 참고).
assert_guard_bites() {
  local guard_id="$1" target_path="$2" sed_script="$3" group_id="$4" token="$5"
  local mirror_dir
  if ! mirror_dir=$(make_repo_mirror); then
    note_failure "T37-15: $guard_id 미러 생성 실패"
    return
  fi

  local failure_message=""
  if ! apply_mutation "$mirror_dir" "$target_path" "$sed_script"; then
    failure_message="T37-15: $guard_id 사전조건 실패 — sed 적용 후 바이트 변화 없음(패턴 불일치 가능)"
  else
    local mutated_output mutated_exit=0
    mutated_output=$(run_group_in_mirror "$mirror_dir" "$group_id") || mutated_exit=$?
    if [[ "$mutated_exit" -eq 0 ]]; then
      failure_message="T37-15: $guard_id 가드 무력화 — 변조 후에도 $group_id 가 PASS(K6 회귀)"
    elif [[ "$mutated_output" != *"$token"* ]]; then
      failure_message="T37-15: $guard_id 실패 메시지에 토큰 '$token' 없음(무관한 이유로 실패했을 수 있음)"
    fi
  fi

  rm -rf -- "$mirror_dir"
  [[ -n "$failure_message" ]] && note_failure "$failure_message"
  # `return 0` 을 명시하는 이유(검수 3회차 실측): 위 한 줄이 마지막 문장이면 함수의 반환값이
  # `[[ -n "$failure_message" ]]` 의 결과가 되어 **실패 없음 → 1 · 실패 있음 → 0** 으로
  # 뒤집힌다. 현재 호출부 두 곳은 반환값을 소비하지 않아 무해하지만 이 함수는 K6 판정의
  # 유일한 진입점이라, 누가 `if assert_guard_bites …; then` 로 감싸면 판정이 정확히 뒤집히고
  # 그 형태는 "항상 통과"라 T37-16 도 잡지 못한다(고정점은 출력만 보고 반환값을 보지 않는다).
  # 판정은 note_failure 로만 보고하고 반환값에는 의미를 두지 않음을 여기서 고정한다.
  return 0
}

# 주어진 미러에서 그룹을 변조 없이 1회 실행한다. 0=PASS, 1=FAIL.
#
# 실행할 때마다 호출자(T37)가 선언한 동적 스코프 변수 precondition_groups_run 에 1을 더한다 —
# 이 계수가 호출부가 아니라 이 함수 안에 있어야 호출을 지우는 변경이 T37-15 의 단언 d(실행한
# 그룹 수 == 선택 행의 서로 다른 그룹 수)에 드러난다(호출부에 두면 호출만 지워도 계수가 남아
# 단언이 침묵한다). 이 함수의 실행 줄을 지우는 변경은 T37-26 이 스텁 미러로 문다. 그래서
# T37-26 은 이 함수를 서브셸 안에서 불러 계수가 T37 바깥으로 새지 않게 한다.
#
# 한계(비망라) — 계수는 「이 함수가 불렸다」는 사실이지 「그룹이 실제로 돌았다」는 증명이
# 아니다. 전수 증명이 아니다.
run_k6_group_precondition() {
  local mirror_dir="$1" group_id="$2" precondition_exit=0
  run_group_in_mirror "$mirror_dir" "$group_id" > /dev/null || precondition_exit=1
  ((precondition_groups_run++)) || true
  return "$precondition_exit"
}

# 그룹 하나의 변조 전 실행(사전조건)을 새 미러에서 수행한다. 0=PASS, 1=그룹 FAIL, 2=미러 생성 실패.
#
# 그룹마다 새 미러를 쓰는 이유: 여러 그룹이 미러 하나를 공유하면 앞 그룹 실행의 잔여물
# (__pycache__ 등)이 뒤 그룹 판정에 섞이는 새 결합이 생긴다 — 미러 생성(0.16초)을 그룹 수만큼
# 아끼는 것은 그 결합을 들일 만큼 값지지 않다. 미러를 이 함수 안에서 직접 rm -rf 하는 이유는
# assert_guard_bites 와 같다(명령 치환 안의 정리 등록은 부모에 반영되지 않는다 — 중단 경로의
# fail-safe 는 MUTATION_MIRROR_ROOT 등록이 맡는다).
precheck_k6_group() {
  local group_id="$1" mirror_dir precondition_exit=0
  mirror_dir=$(make_repo_mirror) || return 2
  run_k6_group_precondition "$mirror_dir" "$group_id" || precondition_exit=1
  rm -rf -- "$mirror_dir"
  return "$precondition_exit"
}

# 선택 행 파일(\x1f 구분 8열)에서 expect_group(4열)이 group_id 인 행만 원장 순서대로 낸다.
k6_rows_of_group() {
  local selected_rows_file="$1" group_id="$2"
  awk -v group_id="$group_id" 'BEGIN{FS="\x1f"} $4 == group_id' "$selected_rows_file"
}

# 사전조건 실패를 그룹 단위로 한 번 보고하고 그 그룹의 행을 판정이 아니라 「생략」으로 센다.
# 행마다 보고하지 않는 이유: T25 한 그룹이 변조 전에 FAIL 이면 같은 메시지가 132건 쌓여 원인이
# 묻힌다. 계수는 호출자(T37)의 동적 스코프 변수에 더한다.
report_k6_group_precondition_failure() {
  local selected_rows_file="$1" group_id="$2" group_row_count="$3" precheck_exit="$4"
  local skipped_guard_ids preview_suffix=""
  ((precondition_groups_failed++)) || true
  precondition_skipped_rows=$((precondition_skipped_rows + group_row_count))
  skipped_guard_ids=$(k6_rows_of_group "$selected_rows_file" "$group_id" \
    | awk 'BEGIN{FS="\x1f"} {print $1}' | head -n "$GUARD_ID_LIST_PREVIEW_LIMIT" | tr '\n' ' ')
  if ((group_row_count > GUARD_ID_LIST_PREVIEW_LIMIT)); then
    preview_suffix="…(앞 ${GUARD_ID_LIST_PREVIEW_LIMIT}개)"
  fi
  if ((precheck_exit == 2)); then
    # 미러를 못 만들어 실행 자체가 없었어도 이 그룹은 사전조건을 시도한 것으로 센다(단언 d 의 분모와 맞춘다).
    ((precondition_groups_run++)) || true
    note_failure "T37-15: ${group_id} 사전조건용 미러 생성 실패 — 이 그룹의 선택 행 ${group_row_count}개 판정 생략: ${skipped_guard_ids}${preview_suffix}"
  else
    note_failure "T37-15: ${group_id} 사전조건 불성립 — 변조 전 ${group_id} 가 이미 FAIL(원장 무효 가능성) — 이 그룹의 선택 행 ${group_row_count}개 판정 생략: ${skipped_guard_ids}${preview_suffix}"
  fi
}

# 그룹 하나를 판정한다 — 사전조건을 1회 확인하고, 통과하면 그 그룹의 선택 행마다
# assert_guard_bites 를 부른다(행마다 새 미러 — 변조 격리의 단위). 계수는 호출자(T37)의 동적
# 스코프 변수에 더한다(rows_judged · precondition_skipped_rows · precondition_groups_failed).
judge_k6_group() {
  local selected_rows_file="$1" group_id="$2"
  local group_row_count precheck_exit=0
  group_row_count=$(k6_rows_of_group "$selected_rows_file" "$group_id" | grep -c .) || true
  precheck_k6_group "$group_id" || precheck_exit=$?
  if ((precheck_exit != 0)); then
    report_k6_group_precondition_failure "$selected_rows_file" "$group_id" "$group_row_count" "$precheck_exit"
    return 0
  fi
  local row_guard row_target row_sed row_group row_token
  while IFS=$'\x1f' read -r row_guard row_target row_sed row_group row_token _ _ _; do
    [[ -z "$row_guard" ]] && continue
    ((rows_judged++)) || true
    assert_guard_bites "$row_guard" "$row_target" "$row_sed" "$row_group" "$row_token"
  done < <(k6_rows_of_group "$selected_rows_file" "$group_id")
}

# 선택된 변조행(\x1f 구분 8열 파일, 원장 순서)을 그룹 단위로 판정한다 — 선택 행에 나오는
# expect_group 을 처음 등장 순서로 한 번씩 훑고 그룹마다 judge_k6_group 을 부른다. 변조 전
# 실행을 별도 캐시 자료구조 없이 이 루프 구조로 메모이즈한다(bash 3.2 에 연관 배열이 없고,
# 순서만 바꾸면 조회가 필요 없다 — docs/prps/t37-incremental-k6.md §7-1).
judge_k6_selected_rows() {
  local selected_rows_file="$1" group_id
  while IFS= read -r group_id; do
    [[ -z "$group_id" ]] && continue
    judge_k6_group "$selected_rows_file" "$group_id"
  done < <(awk 'BEGIN{FS="\x1f"} !seen[$4]++ {print $4}' "$selected_rows_file")
}

# K6 용 git 호출 래퍼. 잠금 없이 읽는다(GIT_OPTIONAL_LOCKS=0 — 같은 저장소의 동시 세션과
# index.lock 을 다투지 않는다). 호출자 환경의 GIT_DIR·GIT_WORK_TREE·GIT_INDEX_FILE 도 지운다 — 훅 안에서
# 스위트를 돌리면 이 변수들이 서 있어 `-C` 로 지정한 저장소가 아니라 훅의 저장소를 향하고, 특히
# 임시 저장소 fixture(T37-24)의 git init·commit 이 호출자의 저장소를 건드릴 수 있다.
k6_git() {
  env -u GIT_DIR -u GIT_WORK_TREE -u GIT_INDEX_FILE GIT_OPTIONAL_LOCKS=0 git "$@"
}

# 비교 기준(병합 기준점)을 낸다. 성공: stdout=40자 sha·반환 0 / 실패: stdout=사유 한 줄·반환 1.
#
# 실패는 환경 사유다 — git 저장소가 아니거나(`.git` 없는 격리 사본) 작업 폴더가 작업 트리의 루트가 아니거나
# (다른 저장소 안에 놓인 사본) 원격 추적 참조가 없거나 공통 조상이 없는 경우. 테스트 실패가 아니라 「기준을
# 정할 수 없으니 전체로 간다」(fail-close)의 이유이므로 이 함수는 note_failure 를 부르지 않는다 —
# plan_k6_rows 가 그 사유를 모드 줄에 싣는다(docs/prps/t37-incremental-k6.md §4).
#
# 작업 폴더가 루트인지 따로 확인하는 이유: 부모 디렉터리 어딘가에 git 저장소가 있으면 `git -C` 가 그
# 저장소를 조용히 가리켜, 이 사본과 무관한 변경을 기준으로 삼을 수 있다.
resolve_k6_diff_base() {
  local repo_root="$1"
  local physical_root toplevel base_sha
  physical_root=$(cd "$repo_root" 2> /dev/null && pwd -P) || {
    echo "작업 폴더에 들어갈 수 없음"
    return 1
  }
  toplevel=$(k6_git -C "$repo_root" rev-parse --show-toplevel 2> /dev/null) || {
    echo "git 저장소가 아님"
    return 1
  }
  if [[ "$toplevel" != "$physical_root" ]]; then
    echo "작업 폴더가 작업 트리의 루트가 아님(다른 저장소 안에 놓인 사본)"
    return 1
  fi
  if ! k6_git -C "$repo_root" rev-parse --verify --quiet "refs/remotes/${K6_DIFF_BASE_REF}^{commit}" > /dev/null 2>&1; then
    echo "${K6_DIFF_BASE_REF} 없음"
    return 1
  fi
  base_sha=$(k6_git -C "$repo_root" merge-base HEAD "refs/remotes/${K6_DIFF_BASE_REF}" 2> /dev/null) || {
    echo "HEAD 와 ${K6_DIFF_BASE_REF} 의 공통 조상이 없음"
    return 1
  }
  echo "$base_sha"
}

# 기준 대비 변경 입력을 out_dir 에 쓴다(changed_files.txt · run_sh.diff · ledger.diff · numstat.txt). 0=성공, 1=git 실패(stdout=사유).
#
# 변경 파일 목록은 작업 트리 전체(커밋 + 스테이지 + 미스테이지)와 추적되지 않는 새 파일의 합집합이다 —
# `git diff <기준>` 은 추적되지 않는 새 파일을 보지 않으므로 ls-files --others 를 더한다.
# numstat.txt 는 하네스 두 파일의 줄 단위 변경량(`추가\t삭제\t경로`)이다 — 단언 e(check_k6_diff_was_read)가
# 「내용이 실제로 바뀌었는가」를 코어와 독립으로 알아야 실행 비트만 바뀐 변경(diff 가 비어 있다)을 거짓 이상으로
# 읽지 않는다.
# git 호출마다 반환값을 직접 본다: set -e 는 그룹 호출 트리에서 꺼져 있어(GOTCHA 1) 실패한 git 이 빈
# 출력으로 흐르면 「바뀐 게 없다 → 0행」이 된다 — 이 설계의 유일한 fail-open 경로다(§19 GOTCHA 1).
collect_k6_change_inputs() {
  local repo_root="$1" base_sha="$2" out_dir="$3"
  local tracked_files untracked_files
  tracked_files=$(k6_git -C "$repo_root" -c core.quotepath=off diff --name-only --no-renames "$base_sha") || {
    echo "git diff --name-only 실패"
    return 1
  }
  untracked_files=$(k6_git -C "$repo_root" -c core.quotepath=off ls-files --others --exclude-standard) || {
    echo "git ls-files --others 실패"
    return 1
  }
  printf '%s\n%s\n' "$tracked_files" "$untracked_files" | grep -v '^$' > "$out_dir/changed_files.txt" || true
  k6_git -C "$repo_root" diff -U0 --no-color --no-ext-diff --no-textconv --no-renames "$base_sha" -- tests/run.sh \
    > "$out_dir/run_sh.diff" || {
    echo "git diff(tests/run.sh) 실패"
    return 1
  }
  k6_git -C "$repo_root" diff -U0 --no-color --no-ext-diff --no-textconv --no-renames "$base_sha" -- tests/mutations.tsv \
    > "$out_dir/ledger.diff" || {
    echo "git diff(tests/mutations.tsv) 실패"
    return 1
  }
  k6_git -C "$repo_root" diff --numstat --no-color --no-ext-diff --no-textconv --no-renames "$base_sha" \
    -- tests/run.sh tests/mutations.tsv > "$out_dir/numstat.txt" || {
    echo "git diff --numstat 실패"
    return 1
  }
}

# 선택 코어 호출 래퍼 — 인자를 그대로 넘긴다. -B 는 바이트코드(__pycache__)를 만들지 않는다 — 작업 트리에
# 생긴 잔여물이 미러를 거쳐 다른 검사의 파일 수 계수를 흔든 선례가 있다(T22-138).
k6_selection_core() { python3 -B "$REPO_ROOT/tests/k6_selection.py" "$@"; }

# K6 모드를 정한다(순수). stdout=`<모드>\t<종류>\t<사유>`, 반환 0(요청 값이 1 이 아니면 2).
#
# 우선순위는 요청 > 환경 사유 > 계산 이상 > 공용 부분 변경 > 없음(증분)이고, 증분이 되는 길은 마지막
# 하나뿐이다 — 어느 입력이든 판단이 흐려지면 전체로 간다(fail-close). 요청 값이 1 이 아니면(`yes`·`true`·
# `0` 등) 전체로 돌고 반환 2 로 호출자가 실패로 알리게 한다: 오타가 의도와 반대로 증분을 조용히 돌리지
# 않게 하면서 의도(대개 전체)는 살린다(§6).
decide_k6_mode() {
  local full_request="$1" environment_reason="$2" anomaly_reason="$3" common_change_reason="$4"
  if [[ "$full_request" == "1" ]]; then
    printf 'full\trequest\t%s=1 요청\n' "$K6_FULL_REQUEST_ENV_NAME"
  elif [[ -n "$full_request" ]]; then
    printf 'full\tinvalid-request\t%s=%s — 값이 1 이 아니라 전체로 돈다\n' "$K6_FULL_REQUEST_ENV_NAME" "$full_request"
    return 2
  elif [[ -n "$environment_reason" ]]; then
    printf 'full\tenvironment\t%s\n' "$environment_reason"
  elif [[ -n "$anomaly_reason" ]]; then
    printf 'full\tanomaly\t%s\n' "$anomaly_reason"
  elif [[ -n "$common_change_reason" ]]; then
    printf 'full\tcommon-change\t%s\n' "$common_change_reason"
  else
    printf 'incremental\tnone\t\n'
  fi
  return 0
}

# 코어 레코드 파일(탭 구분)에서 키가 같은 첫 레코드의 값을 낸다. 없으면 빈 값.
k6_core_value() {
  local records_file="$1" record_key="$2"
  awk -F'\t' -v record_key="$record_key" '$1 == record_key {print $2; exit}' "$records_file"
}

# 계산 이상을 기록한다 — 모드 줄에 실을 첫 사유를 남기고 실패로 보고한다. 이상이 생기면 전체로 간다
# (decide_k6_mode 의 계산 이상 갈래). 호출자(plan_k6_rows)의 동적 스코프 변수 anomaly_reason 을 쓴다.
flag_k6_anomaly() {
  local reason="$1"
  if [[ -z "$anomaly_reason" ]]; then
    anomaly_reason="$reason"
  fi
  note_failure "T37-15: ${reason} — K6 전체로 전환한다"
}

# harness_repo_path 의 내용이 실제로 바뀌었으면(git diff --numstat 의 추가+삭제 줄 수 > 0) 코어가 그 파일의
# 변경 줄을 하나 이상 읽었어야 한다. 변경 줄 해석이 고장 나거나 diff 입력이 비어 「바뀐 게 없다」로 읽는 것을
# 막는다(단언 e) — 위반하면 계산 이상이다. 바뀐 파일 목록이 아니라 numstat 으로 보는 이유: 실행 비트(chmod)만
# 바뀐 파일은 목록에는 들지만 diff 가 비어 있어, 목록만 보면 정당한 변경을 거짓 이상(전체 재확인 + 실패)으로 읽는다.
check_k6_diff_was_read() {
  local plan_dir="$1" harness_repo_path="$2" parsed_change_count="$3" content_change_count
  content_change_count=$(awk -F'\t' -v harness_repo_path="$harness_repo_path" \
    '$3 == harness_repo_path {total += $1 + $2} END {print total + 0}' "$plan_dir/numstat.txt")
  if ((content_change_count > 0 && parsed_change_count == 0)); then
    flag_k6_anomaly "${harness_repo_path} 의 내용이 바뀌었는데(numstat ${content_change_count}줄) 코어가 변경 줄을 하나도 읽지 못함"
  fi
}

# 코어가 낸 첫 FULL 위치(함수명 · top-level · k6_selection.py)를 모드 줄에 실을 사유 문장으로 바꾼다.
format_k6_common_change_reason() {
  case "$1" in
    k6_selection.py) echo "공용 부분 변경(tests/k6_selection.py)" ;;
    top-level) echo "공용 부분 변경(tests/run.sh 의 최상위 코드)" ;;
    *) echo "공용 부분 변경(tests/run.sh 의 $1)" ;;
  esac
}

# 코어 출력을 읽어 일관성(단언 a·e)을 확인하고 공용 부분 변경 사유를 정한다. 호출자(plan_k6_rows 계열)의
# 동적 스코프 변수 common_change_reason 을 채우고, ledger_mutation_rows(T37)와 대조한다.
read_k6_core_records() {
  local plan_dir="$1"
  local records_file="$plan_dir/core_records.txt"
  local first_full examined runsh_changes ledger_changes
  first_full=$(k6_core_value "$records_file" FULL)
  examined=$(k6_core_value "$records_file" EXAMINED)
  runsh_changes=$(k6_core_value "$records_file" RUNSH_CHANGES)
  ledger_changes=$(k6_core_value "$records_file" LEDGER_CHANGES)
  if [[ "$examined" != "$ledger_mutation_rows" ]]; then
    flag_k6_anomaly "선택 코어가 읽은 변조행 ${examined:-없음}행이 원장 변조행 ${ledger_mutation_rows}행과 다름"
  fi
  check_k6_diff_was_read "$plan_dir" "tests/run.sh" "${runsh_changes:-0}"
  check_k6_diff_was_read "$plan_dir" "tests/mutations.tsv" "${ledger_changes:-0}"
  if [[ -n "$first_full" ]]; then
    common_change_reason=$(format_k6_common_change_reason "$first_full")
  fi
}

# 선택 코어에 넘길 그룹→함수 대응 파일을 쓴다(TEST_GROUPS 전개 — `<그룹ID>\t<함수명>`).
write_k6_group_functions() {
  local output_file="$1" entry
  : > "$output_file"
  for entry in "${TEST_GROUPS[@]}"; do
    printf '%s\t%s\n' "${entry%%:*}" "${entry#*:}" >> "$output_file"
  done
}

# 비교 기준을 정하고 변경 입력을 모아 선택 코어를 돌린다. 결과는 호출자(plan_k6_rows)의 동적 스코프 변수
# (environment_reason · anomaly_reason · common_change_reason · k6_base_short · k6_changed_file_count)와
# plan_dir 의 core_records.txt 로 남는다. 이 단계의 모든 실패는 「전체로 간다」로 끝난다(fail-close).
inspect_k6_changes() {
  local plan_dir="$1" base_sha collect_reason core_exit=0 core_detail=""
  if ! base_sha=$(resolve_k6_diff_base "$REPO_ROOT"); then
    environment_reason="비교 기준을 정할 수 없음(${base_sha}) — fail-close"
    return 0
  fi
  k6_base_short="${base_sha:0:7}"
  if ! collect_reason=$(collect_k6_change_inputs "$REPO_ROOT" "$base_sha" "$plan_dir"); then
    flag_k6_anomaly "변경 입력을 모으지 못함(${collect_reason})"
    return 0
  fi
  k6_changed_file_count=$(grep -c . "$plan_dir/changed_files.txt") || true
  write_k6_group_functions "$plan_dir/group_functions.tsv"
  k6_selection_core select \
    --source "$REPO_ROOT/tests/run.sh" \
    --mutation-rows "$plan_dir/mutation_rows.tsv" \
    --changed-files "$plan_dir/changed_files.txt" \
    --run-sh-diff "$plan_dir/run_sh.diff" \
    --ledger-diff "$plan_dir/ledger.diff" \
    --group-functions "$plan_dir/group_functions.tsv" \
    --harness-group "$MUTATION_HARNESS_GROUP" \
    --core-repo-path tests/k6_selection.py \
    --margin "$K6_GUARD_BLOCK_MARGIN_LINES" \
    > "$plan_dir/core_records.txt" 2> "$plan_dir/core_stderr.txt" || core_exit=$?
  if ((core_exit != 0)); then
    if [[ -s "$plan_dir/core_stderr.txt" ]]; then
      core_detail=" — $(head -c 200 "$plan_dir/core_stderr.txt" | tr '\n' ' ')"
    fi
    flag_k6_anomaly "선택 코어가 비정상 종료함(종료 코드 ${core_exit})${core_detail}"
    return 0
  fi
  read_k6_core_records "$plan_dir"
}

# 선택 행 파일(\x1f 구분 8열, 원장 순서)을 쓴다 — 증분이면 코어가 고른 행만, 그 밖의 모드는 변조행 전부.
# 판정을 `== "full"` 이 아니라 `!= "incremental"` 로 하는 이유: 모드 값이 비었거나 모르는 값이면(결정 출력을
# 못 읽은 경우 등) 증분으로 읽혀 조용히 0행이 되는 대신 전부 판정하는 쪽(fail-close)으로 기울게 한다.
write_k6_selected_rows() {
  local plan_dir="$1"
  if [[ "$k6_mode" != "incremental" ]]; then
    awk -F'\t' 'BEGIN{OFS="\x1f"} $3 != "-" {$1=$1; print}' "$plan_dir/mutation_rows.tsv" > "$k6_selected_rows_file"
  else
    awk -F'\t' 'BEGIN{OFS="\x1f"} FNR == NR {if ($1 == "ROW") wanted[$2] = 1; next} $3 != "-" && ($1 in wanted) {$1=$1; print}' \
      "$plan_dir/core_records.txt" "$plan_dir/mutation_rows.tsv" > "$k6_selected_rows_file"
  fi
}

# 코어의 ASCII 근거 코드를 로그에 찍을 한국어 이름으로 바꾼다(로케일과 무관하게 코어 출력이 깨지지 않게
# 코어는 ASCII 만 낸다 — 이름 매핑은 이쪽 몫이다).
k6_reason_label() {
  case "$1" in
    ledger) echo "원장" ;;
    target) echo "대상 파일" ;;
    block) echo "가드 블록" ;;
    name) echo "변수 정의" ;;
    later) echo "앞선 줄" ;;
    unresolved) echo "블록 미상" ;;
    *) echo "$1" ;;
  esac
}

# 선택 행 중 근거 코드가 reason_code 를 포함하는 행 수를 센다.
count_k6_rows_with_reason() {
  local records_file="$1" reason_code="$2"
  awk -F'\t' -v reason_code="$reason_code" \
    '$1 == "ROW" && index("," $3 ",", "," reason_code ",") {count++} END {print count + 0}' "$records_file"
}

# 선택 행의 앞 GUARD_ID_LIST_PREVIEW_LIMIT 개를 `ID(근거,근거) …` 로 낸다.
format_k6_selected_preview() {
  local records_file="$1" record_type guard_id reason_codes code reason_labels preview="" shown=0
  while IFS=$'\t' read -r record_type guard_id reason_codes; do
    [[ "$record_type" == "ROW" ]] || continue
    ((shown < GUARD_ID_LIST_PREVIEW_LIMIT)) || break
    reason_labels=""
    for code in ${reason_codes//,/ }; do
      reason_labels="${reason_labels:+${reason_labels},}$(k6_reason_label "$code")"
    done
    preview="${preview}${guard_id}(${reason_labels}) "
    ((shown++)) || true
  done < "$records_file"
  printf '%s' "${preview% }"
}

# 선택 행의 근거별 행 수를 `근거 원장 2 · 대상 파일 9 · …` 로 낸다(한 행이 여러 근거에 걸리면 각각 센다).
# 블록 미상 행이 있으면 끝에 따로 붙인다 — 그 행은 어느 규칙과도 무관하게 항상 선택된 fail-close 다.
format_k6_reason_summary() {
  local records_file="$1" unresolved_count summary
  summary="근거 원장 $(count_k6_rows_with_reason "$records_file" ledger)"
  summary="${summary} · 대상 파일 $(count_k6_rows_with_reason "$records_file" target)"
  summary="${summary} · 가드 블록 $(count_k6_rows_with_reason "$records_file" block)"
  summary="${summary} · 변수 정의 $(count_k6_rows_with_reason "$records_file" name)"
  summary="${summary} · 앞선 줄 $(count_k6_rows_with_reason "$records_file" later)"
  unresolved_count=$(count_k6_rows_with_reason "$records_file" unresolved)
  if ((unresolved_count > 0)); then
    summary="${summary} · 블록 미상 ${unresolved_count}"
  fi
  printf '%s' "$summary"
}

# K6 모드·행 수·기준·근거를 한 줄로 찍고 스위트 끝 요약용 줄(K6_SUMMARY_LINE)을 채운다. 매 실행 찍는 이유:
# 증분이 조용히 0행으로 도는 것(선택 계산 고장)이 이 줄로만 사람 눈에 드러난다(§9). 전체 재확인 명령은 증분
# 줄 끝에 항상 싣는다 — 사용자가 「전체 재확인」을 요청하면 메인 세션이 로그에서 바로 찾는다.
log_k6_plan() {
  local records_file="$1"
  local full_command="${K6_FULL_REQUEST_ENV_NAME}=1 bash tests/run.sh"
  if [[ "$k6_mode" != "incremental" ]]; then
    log_info "K6 전체: ${k6_selected_rows}/${ledger_mutation_rows}행 판정 — 사유: ${k6_reason}"
    K6_SUMMARY_LINE="K6: 전체 ${k6_selected_rows}/${ledger_mutation_rows}행 — 사유: ${k6_reason}"
    return 0
  fi
  K6_SUMMARY_LINE="K6: 증분 ${k6_selected_rows}/${ledger_mutation_rows}행(기준 ${k6_base_short}) · 전체 재확인: ${full_command}"
  if ((k6_selected_rows == 0)); then
    log_info "K6 증분: 0/${ledger_mutation_rows}행 판정 — 기준 ${k6_base_short} · 바뀐 파일 ${k6_changed_file_count}개 · 원장 행·대상 파일·가드 블록·변수 정의·앞선 줄 어디에도 닿지 않음 — 전체 재확인: ${full_command}"
    return 0
  fi
  local preview_overflow=""
  if ((k6_selected_rows > GUARD_ID_LIST_PREVIEW_LIMIT)); then
    preview_overflow=" … 외 $((k6_selected_rows - GUARD_ID_LIST_PREVIEW_LIMIT))행"
  fi
  log_info "K6 증분: ${k6_selected_rows}/${ledger_mutation_rows}행 판정 — 기준 ${k6_base_short}(${K6_DIFF_BASE_REF} 과의 병합 기준점) · 바뀐 파일 ${k6_changed_file_count}개 · $(format_k6_reason_summary "$records_file") — 전체 재확인: ${full_command}"
  log_info "K6 선택 행(앞 ${GUARD_ID_LIST_PREVIEW_LIMIT}개): $(format_k6_selected_preview "$records_file")${preview_overflow}"
}

# 코어 레코드 파일(탭 구분)에서 키가 같은 레코드가 몇 줄인지 센다.
count_k6_core_records() {
  local records_file="$1" record_key="$2"
  awk -F'\t' -v record_key="$record_key" '$1 == record_key {count++} END {print count + 0}' "$records_file"
}

# 모드를 정하고(decide_k6_mode) 선택 행 파일과 행 수를 채운다. 호출자(plan_k6_rows)의 동적 스코프 변수
# (full_request · environment_reason · anomaly_reason · common_change_reason)를 읽고 k6_mode · k6_reason ·
# k6_selected_rows 를 쓴다. 요청 값이 1 이 아니면(반환 2) 실패로 보고한다 — 이때 모드는 전체다.
settle_k6_mode_and_rows() {
  local plan_dir="$1" decision decision_exit=0
  decision=$(decide_k6_mode "$full_request" "$environment_reason" "$anomaly_reason" "$common_change_reason") || decision_exit=$?
  IFS=$'\t' read -r k6_mode _ k6_reason <<< "$decision"
  if ((decision_exit == 2)); then
    note_failure "T37-15: ${k6_reason}"
  fi
  write_k6_selected_rows "$plan_dir"
  k6_selected_rows=$(grep -c . "$k6_selected_rows_file") || true
}

# 증분일 때 코어 출력이 선택 행 파일과 모드로 빠짐없이 옮겨졌는지 확인한다(배선 단언 g — 새 ID 없이 T37-15 로
# 보고한다): 코어의 ROW 레코드 수는 선택 행 수와 같아야 하고 FULL 레코드는 0 이어야 한다. 이 둘이 어긋나면 bash
# 배선(awk 조인·FULL 사유 읽기)이 고장 나 증분이 조용히 0행으로 도는 것이므로 계산 이상으로 보고 전체로 가게
# 한다. 0 이면 통과, 1 이면 어긋남(이상은 flag_k6_anomaly 가 기록한다).
verify_k6_incremental_wiring() {
  local plan_dir="$1" core_row_count core_full_count
  core_row_count=$(count_k6_core_records "$plan_dir/core_records.txt" ROW)
  core_full_count=$(count_k6_core_records "$plan_dir/core_records.txt" FULL)
  if ((core_row_count == k6_selected_rows && core_full_count == 0)); then
    return 0
  fi
  flag_k6_anomaly "코어 출력이 선택 행·모드로 그대로 옮겨지지 않음 — 코어 ROW ${core_row_count}건·FULL ${core_full_count}건인데 증분의 선택 행은 ${k6_selected_rows}행"
  return 1
}

# 이번 실행에서 판정할 변조행을 정한다(오케스트레이션) — 요청·기준·변경 입력·코어·모드 결정을 차례로 부르고,
# 선택 행 파일과 호출자(T37)의 동적 스코프 상태(k6_mode · k6_reason · k6_base_short ·
# k6_changed_file_count · k6_selected_rows · k6_selected_rows_file)를 채운다. 요청이 있으면(`1` 이든 오타든)
# 선택 계산을 하지 않는다 — 어차피 전체이고 계산이 실패할 일도 없다. 결정의 종류(요청·환경·계산 이상·공용
# 변경·없음)는 decide_k6_mode 가 낸 두 번째 열이지만 소비자가 없어 읽지 않는다 — T37-25 만 그 열을 본다.
# 증분으로 정해졌어도 배선 단언(verify_k6_incremental_wiring)이 어긋나면 계산 이상으로 다시 정해 전체로 간다.
plan_k6_rows() {
  local ledger_rows="$1" work_dir="$2"
  local plan_dir="$work_dir/k6_plan"
  local full_request="${!K6_FULL_REQUEST_ENV_NAME:-}"
  local environment_reason="" anomaly_reason="" common_change_reason=""
  mkdir -p "$plan_dir"
  printf '%s\n' "$ledger_rows" > "$plan_dir/mutation_rows.tsv"
  k6_selected_rows_file="$work_dir/k6_selected_rows.txt"
  if [[ -z "$full_request" ]]; then
    inspect_k6_changes "$plan_dir"
  fi
  settle_k6_mode_and_rows "$plan_dir"
  if [[ "$k6_mode" == "incremental" ]] && ! verify_k6_incremental_wiring "$plan_dir"; then
    settle_k6_mode_and_rows "$plan_dir"
  fi
  log_k6_plan "$plan_dir/core_records.txt"
}

# 신설(ledger-anchor-column PRP §5-1) — source_path 안에서 "<function_name>() {" 정의
# 줄 번호를 낸다. 정의 hit 이 1 이 아니면 빈 문자열을 낸다 — 0건(미정의)·2건 이상(중복
# 정의) 모두 호출자가 앵커 해소 실패로 다룬다. grep -o | wc -l 로 세는 이유: BSD grep -cE
# 는 대상이 없을 때 아무것도 출력하지 않는다(파일이 있고 0건일 때만 grep -c 가 "0"을
# 낸다).
find_function_definition_line() {
  local source_path="$1" function_name="$2"
  local pattern="^${function_name}"'\(\) \{'
  local hit_count
  hit_count=$(grep -oE "$pattern" "$source_path" | wc -l | tr -d ' ') || true
  [[ "$hit_count" == "1" ]] || return 0
  grep -nE "$pattern" "$source_path" | head -1 | cut -d: -f1
}

# 신설(ledger-anchor-column PRP §5-1) — definition_line 부터 **다음 최상위 함수 정의
# 직전**까지를 몸통으로 낸다(guard_token_is_inside_anchor 의 교차검증이 쓴다).
#
# 끝을 "^}" 로 잡지 않는 이유(실측된 함정, 같은 문서 §10-3): 이 파일의 heredoc
# (test_manifest_ledger_and_removals 안의 MANIFEST_V1_EOF)이 열 0 에 "}" 를 담고 있어,
# 첫 "^}" 를 끝으로 잡으면 그 함수의 몸통이 111줄에서 조기 절단된다(재현: sed -n
# '/^test_manifest_ledger_and_removals() {/,/^}/p' tests/run.sh | wc -l → 111, 실제
# 함수는 그보다 훨씬 길다). "다음 최상위 함수 정의 직전"으로 잡으면 그 heredoc 을 몸통
# 중간의 평범한 텍스트로 통과시킨다.
#
# 한계(비망라) — 함수 사이의 최상위 코드가 몸통에 포함된다(허용 방향으로 느슨하다 —
# 교차검증이 통과하기 쉬워진다). 함수 안에 열 0 으로 함수를 정의하는 중첩이나 heredoc
# 안에 함수 정의 형태의 줄이 있으면 몸통이 잘못 끊길 수 있다. 전수 증명이 아니다.
extract_function_body() {
  local source_path="$1" definition_line="$2"
  awk -v start="$definition_line" '
    NR == start { in_body = 1 }
    in_body && NR > start && /^[A-Za-z_][A-Za-z0-9_]*\(\) \{/ { exit }
    in_body { print }
  ' "$source_path"
}

# block_end_line 에서 역방향으로 "#" 로 시작하는 연속 줄만 모아 doc-comment 블록을 낸다.
# bash 3.2 환경에는 tac/tail -r 가 없어(이 머신에서 실측 확인) awk 배열로 역방향을
# 흉내낸다.
extract_preceding_comment_block() {
  local full_path="$1" block_end_line="$2"
  awk -v end="$block_end_line" '
    NR <= end { lines[NR] = $0 }
    END {
      i = end; start = end + 1
      while (i > 0 && lines[i] ~ /^#/) { start = i; i-- }
      for (j = start; j <= end; j++) print lines[j]
    }
  ' "$full_path"
}

# §4.6 의 한계 표기 존재 검사(개정, ledger-anchor-column PRP §5-1). anchor_function(8번째
# 열, 선언)의 정의를 tests/run.sh 에서 찾고, 그 정의 바로 위 주석 블록에 한계 표기
# 3종(실측한 범위/비망라/전수 증명이 아니) 중 하나라도 있는지 본다. 반환은 3상태다 —
# 0=표기 있음, 1=표기 없음, 2=앵커 해소 실패(정의 hit≠1 이거나 직전 주석 블록이 아예
# 없음).
#
# 이전 판(S3b)은 앵커를 5열 expect_token 에서 **파생**시켰다 — 토큰이 등장하는 줄의
# 최근접 선행 함수 정의를 앵커로 삼았고, 그래서 토큰이 tests/run.sh 안에서 유일할 것을
# 요구했다(그 유일성이 이 검사가 아니라 그 파생 알고리즘의 전제였다). 이 판은 앵커를
# 8번째 열의 **선언**으로 받는다 — 파생이 없으므로 5열의 유일성 제약도 이 함수의
# 전제에서 빠진다(5열은 이제 §5-2 로 재조준된 별개 제약을 진다).
#
# 3상태로 나눈 이유(주제 5-c·6-c, S3b 의 유산): 「토큰 미발견」·「함수 앵커 부재」도
# 「표기 없음」과 같은 1 로 뭉개면 (i) 표기가 있는데도 없다고 보고하는 위양성과 (ii)
# 앵커가 다른 함수로 옮겨가 실제 가드의 표기 부재를 놓치는 위음성이 같은 값에 섞인다.
#
# 한계(비망라) — §4.6 의 「위양성이 구조적으로 없다」는 *검사 대상 집합을 원장 등록
# 행으로 좁힌 것*에 대한 진술이고 이 함수 반환값의 보증이 아니다. 선언된 anchor_function
# 이 실제로 그 가드를 담고 있는 함수인지는 이 함수가 보지 않는다 — 그것은
# guard_token_is_inside_anchor 의 교차검증이 다룬다(§10-2). 전수 증명이 아니다.
has_limit_annotation_for_guard() {
  local anchor_function="$1"
  local full_path="$REPO_ROOT/tests/run.sh"
  local func_line
  func_line=$(find_function_definition_line "$full_path" "$anchor_function")
  [[ -n "$func_line" ]] || return 2
  local comment_block
  comment_block=$(extract_preceding_comment_block "$full_path" "$((func_line - 1))")
  [[ -n "$comment_block" ]] || return 2
  [[ "$comment_block" == *"실측한 범위"* || "$comment_block" == *"비망라"* \
    || "$comment_block" == *"전수 증명이 아니"* ]]
}

# 신설(ledger-anchor-column PRP §5-3, 검수 1회차 Major A) — tests/run.sh 의 실패 보고
# 호출 줄(줄 시작이 note_failure·record_failure·log_error·echo 중 하나인 줄)에서 token 이
# 몇 번 등장하는지 센다. 5열 expect_token 원장 헤더가 약속한 "판별자 자격"(발화 지점
# 하나를 지목하는가) 검사를 실제로 수행하는 자리다 — 이전 판은 앵커를 토큰에서
# 파생시켜 이 유일성을 파생의 전제조건으로 강제했고, 이번 판(선언형 앵커)은 그 파생이
# 없어 유일성을 검사하는 코드도 함께 비었다(검수 1회차 실측 — collect_guard_ids 로
# count_token_hits_in_file 를 찾으면 0건).
#
# grep -F | wc -l 로 세는 이유: find_function_definition_line 과 같은 근거다 — 첫 grep 이
# 0건이면 파이프에 빈 stdin 이 넘어가고 wc -l 은 빈 입력에서도 "0"을 안정적으로 낸다
# (BSD grep -c 가 존재하지 않는 파일 인자에서 보이는 침묵과는 다른 경로다).
#
# 한계(비망라, 설계 §5-3) — 분모 정규식이 줄 시작 앵커와 4개 명령 이름에 결합돼 있다:
# 줄 중간에서 보고하는 호출, printf 로 보고하는 자리, 변수에 담아 뒤에서 찍는 형태,
# 파이썬 층의 발화 지점은 이 분모에 없다. 전수 증명이 아니다.
count_token_hits_in_report_lines() {
  local source_path="$1" token="$2"
  grep -E "$FAILURE_REPORT_LINE_PATTERN" "$source_path" \
    | grep -F -- "$token" | wc -l | tr -d ' ' || true
}

# 신설(ledger-anchor-column PRP §10-2) — 선언된 anchor_function 의 위조를 막는
# 교차검증. anchor_function 이 파생이 아니라 선언이 되면서 열리는 공허 통과 경로(445행의
# 앵커를 한계 표기가 확실한 함수 하나로 몰면, T37-13 이 표기 검사는 통과시키면서 실제
# 가드의 주석은 한 줄도 보지 않게 된다)를 이 함수가 닫는다 — expect_token(5열)이
# anchor_function 의 몸통 안의 실패 보고 호출 줄에 실제로 나타나는지 확인해, 선언된
# 앵커가 그 가드의 발화 지점을 정말로 담고 있는지 검증한다. 반환 3상태 — 0=보고 줄 안에
# 있음, 1=없음(위조 의심), 2=앵커 해소 실패(정의 hit≠1).
#
# 몸통 전체가 아니라 보고 줄로 좁히는 이유(검수 1회차 Major B) — 몸통 전체 부분문자열
# 대조는 주석도 함께 본다. 이 저장소는 에러 문구를 주석에 그대로 인용하는 관행이 있어,
# 앵커의 실제 가드와 무관한 함수라도 그 문구를 언급하는 주석 한 줄만 있으면 통과했다
# (재현 — extract_function_body 몸통에 "# … EXIT 트랩 설치" 주석을 넣고
# guard_token_is_inside_anchor "extract_function_body" "EXIT 트랩 설치" 를 호출하면
# 개정 전 rc=0, 개정 후 rc=1). 보고 줄만 보면 주석은 애초에 분모에 들지 않는다.
#
# 방향이 has_limit_annotation_for_guard 와 반대다 — 저 함수는 "선언된 앵커에 한계
# 표기가 있는가"를 보고, 이 함수는 "선언된 앵커가 진짜 그 가드의 자리인가"를 본다.
# 토큰의 모양(길이·유일성)에는 아무 제약을 얹지 않는다 — 유일성은
# count_token_hits_in_report_lines 가 별도로 검사한다(T37-13).
#
# 한계(비망라) — 보고 줄 판정 정규식이 결합한 한계를 그대로 물려받는다: 줄 중간에서
# 보고하는 호출, printf 로 보고하는 자리는 이 몸통 필터에서도 빠진다. 전수 증명이 아니다.
guard_token_is_inside_anchor() {
  local anchor_function="$1" expect_token="$2"
  local full_path="$REPO_ROOT/tests/run.sh"
  local func_line
  func_line=$(find_function_definition_line "$full_path" "$anchor_function")
  [[ -n "$func_line" ]] || return 2
  local body report_lines
  body=$(extract_function_body "$full_path" "$func_line")
  report_lines=$(grep -E "$FAILURE_REPORT_LINE_PATTERN" <<< "$body")
  [[ "$report_lines" == *"$expect_token"* ]]
}

# 여러 줄(각각 이미 탭으로 구분된 문자열)을 fixture_root 아래 임시 파일에 써서 경로를 낸다
# — parse_mutation_ledger 시나리오 테스트 전용 fixture 생성기(T37-1~T37-8).
#
# fixture_root 를 인자로 받는 이유(주제 1-c): 이 함수는 명령 치환으로 불리므로 안에서
# register_cleanup_path 를 부를 수 없고(서브셸이라 부모의 배열에 반영되지 않는다, 실측
# 확인), 그렇다고 호출자가 `register_cleanup_path "$(dirname "$fixture_path")"` 로 되받으면
# mktemp 실패로 경로가 빈 문자열일 때 dirname 이 그것을 `/` 로 증폭시켜 정리 대상이
# 디스크 최상단이 된다(검수 1회차 Critical). T37 본문이 미리 만들어 등록한 루트를 받아 그
# 아래에만 파일을 만들면 그 dirname 관용구 자체가 없어진다.
write_ledger_fixture() {
  local fixture_root="$1"
  shift
  if [[ -z "$fixture_root" || ! -d "$fixture_root" ]]; then
    log_error "write_ledger_fixture: fixture 루트가 준비되지 않음('$fixture_root')"
    return 1
  fi
  local fixture_path
  fixture_path=$(mktemp "$fixture_root/fixture.XXXXXX") || fixture_path=""
  if [[ -z "$fixture_path" || ! -f "$fixture_path" ]]; then
    log_error "write_ledger_fixture: mktemp 이 fixture 파일을 만들지 못함(임시 공간 부족 가능)"
    return 1
  fi
  printf '%s\n' "$@" > "$fixture_path"
  echo "$fixture_path"
}

# fixture_path 가 parse_mutation_ledger 에서 거부되고, 그 거부 사유가 expected_reason 을
# 담고 있는지 함께 확인한다 — 호출자가 리터럴 ID 로 note_failure 를 불러야
# collect_guard_ids 가 그 ID 를 추출한다(이 함수 자신은 note_failure 를 부르지 않는다 —
# 부르면 인자로 받은 동적 문자열이라 추출되지 않는 ID 없는 호출이 된다).
#
# 종료 코드만 보면 안 되는 이유(PRP §4.4-(2)-4 의 명시 금지): 이전 판은 반환값만 봤고,
# parse_mutation_ledger 는 「파일 미존재」에도 1 을 내므로 fixture 생성 자체를 고장낸 변조
# (printf 를 true 로 치환)에서 T37-1~T37-7 의 단언 10건이 전부 조용히 통과했다(실측).
# 기대 사유를 함께 단언하면 "의도한 불변식이 거부했다"와 "무관한 이유로 거부됐다"가
# 갈린다. log_error 가 stdout 으로 쓰므로 2>&1 로 함께 캡처한다.
mutation_ledger_fixture_is_rejected() {
  local fixture_path="$1" expected_reason="$2"
  local output
  if output=$(parse_mutation_ledger "$fixture_path" 2>&1); then
    return 1
  fi
  [[ "$output" == *"$expected_reason"* ]]
}

# fixture_path 가 parse_mutation_ledger 에서 성공하면 낸 행 수를 stdout 으로 내고 0을,
# 실패하면 1을 반환한다(호출자가 리터럴 ID 로 note_failure 를 부른다 — 위 함수와 같은 이유).
mutation_ledger_fixture_row_count() {
  local output
  output=$(parse_mutation_ledger "$1" 2>&1) || return 1
  grep -c . <<< "$output"
}

# T37 본문의 사전조건 판정 — fixture 루트와 미러 루트가 둘 다 실재하는 디렉토리인가.
# 0=둘 다 준비됨, 1=하나라도 준비되지 않음.
#
# 인라인 조건식을 함수로 뺀 이유(검수 3회차): 그룹 함수 안의 조건식은 정상 실행에서 항상
# 거짓이라 커버리지를 붙일 자리가 없었다 — 조건을 무력화해도 전체 실행이 통과했다(실측).
# 판정을 함수로 빼면 T37-20 이 그 판정을 세 방향(빈 값 · 미실재 · 정상)으로 직접 시험한다.
#
# 한계(비망라, PRP tests-hardening §18 이관 14) — T37-20 이 무는 것은 이 판정 함수이고
# 그것을 부르는 자리는 아니다. 호출부를 지우거나 반환값을 버리는 변경의 효과는 하네스
# 자신의 mktemp -d 가 실제로 실패할 때만 관측되는데, 하네스는 그 실패를 스스로 만들 수
# 없다(T37-18 은 apply_mutation 을 직접 부를 수 있어 호출부까지 물지만 여기는 그 우회로가
# 없다). 전수 증명이 아니다.
mutation_harness_roots_are_ready() {
  local fixture_root="$1" mirror_root="$2"
  [[ -n "$fixture_root" && -d "$fixture_root" ]] || return 1
  [[ -n "$mirror_root" && -d "$mirror_root" ]]
}

# 선택 코어 합성 fixture 의 가드 블록 여유 줄 수(T37-22·T37-23). 실물 상수(K6_GUARD_BLOCK_MARGIN_LINES)
# 대신 작은 값을 쓰는 이유: 블록이 서로 겹치지 않으려면 가드 사이가 여유의 두 배 이상 벌어져야 하는데, 실물
# 값이면 fixture 소스가 수십 줄 늘어난다. 여유 로직 자체(경계 안쪽은 고르고 바깥쪽은 고르지 않는다)는 이
# 값으로도 같은 모양으로 시험된다 — 실물 상수가 코어로 넘어가는 배선은 plan_k6_rows 의 몫이다.
readonly K6_FIXTURE_MARGIN_LINES=2

# 선택 코어 합성 fixture 의 소스를 dir/source.sh 에 쓴다(T37-22·T37-23 공용). 구성: 최상위 단일 줄 상수와
# 배열 · 헬퍼 함수(heredoc 안에 `#` 줄) · 그룹 함수(가드 셋 — 블록 밖에 `local` 정의와 `local` 없는 일반 대입,
# 첫째·둘째 가드 블록 안에 키워드 하나씩만 든 조기 종료 줄(return · record_failure · exit), 앞 둘 사이에 공용
# 줄과 heredoc, 둘째와 셋째 사이에 블록 밖 조기 종료 줄) · 하네스 그룹 함수. 조기 종료 줄을 블록 **안**에 두는 이유:
# 블록 밖 코드 줄은 「공용 줄」 규칙(R5 ②)으로도 뒤 행을 고르므로, 키워드 검출(R5 ①)이 고장나도 결과가 같아 보인다 —
# 블록 안(②가 덮지 않는 자리)에 둬야 ① 만 그 줄을 본다. 줄 번호를 적지 않는다 — 시나리오가 marker 문자열로 줄을
# 찾으므로 이 소스를 고쳐도 시나리오가 따라온다. 소스 줄을 printf 인자로 쓰는 이유: heredoc 이나 열 0 줄로 쓰면
# 이 파일 자신의 함수 구간·트랩 계수·heredoc 검사에 fixture 의 `name() {`·`}` 가 섞인다.
write_k6_fixture_source() {
  local dir="$1"
  local gap=('  :' '  :' '  :' '  :' '  :')
  printf '%s\n' \
    'readonly FIXTURE_LIMIT=3' \
    'readonly FIXTURE_LIST=(' \
    "  'one'" \
    ')' \
    '# helper doc comment' \
    'helper_one() {' \
    '  # helper inner comment' \
    '  local helper_value=1' \
    "  cat <<'HELPER_EOF'" \
    '# hash line inside heredoc' \
    'HELPER_EOF' \
    '}' \
    'test_group_alpha() {' \
    '  local alpha_flag=ready' \
    '  plain_total=0' \
    "${gap[@]}" \
    '  # T90-1: first guard' \
    '  if false; then' \
    '    note_failure "T90-1: first guard report marker-first"' \
    '    return 1' \
    '    record_failure "$test_name" "in-block"' \
    '  fi' \
    "${gap[@]}" \
    '  prepare_shared_state' \
    "  cat <<'ALPHA_EOF'" \
    '  return 77' \
    'ALPHA_EOF' \
    "${gap[@]}" \
    '  # T90-2: second guard' \
    '  if (( FIXTURE_LIMIT > 5 )) || [[ "$alpha_flag" == bad ]]; then' \
    '    note_failure "T90-2: second guard report marker-second"' \
    '    exit 3' \
    '  fi' \
    "${gap[@]}" \
    '  record_failure "$test_name" "cut early"; return 1' \
    "${gap[@]}" \
    '  # T90-3: third guard' \
    '  if [[ "$plain_total" -gt 9 ]]; then' \
    '    note_failure "T90-3: third guard report marker-third"' \
    '  fi' \
    '}' \
    'test_harness_group() {' \
    '  local harness_value=1' \
    '}' > "$dir/source.sh"
}

# 합성 fixture 의 원장 행(변조행 셋 + 면제행 하나)과 그룹→함수 대응을 dir 에 쓴다. 변조행의 토큰은 소스의 보고 줄
# 하나에만 있고(T37-13 의 판별자 자격과 같은 조건), 면제행은 선택에서 빠져야 한다 — EXAMINED 가 3 이어야 한다.
# 마지막 둘은 블록 미상(unresolved) 시험용이다 — 토큰이 보고 줄에 0건·여러 건이다.
write_k6_fixture_rows() {
  local dir="$1"
  printf '%s\n' \
    "$(printf 'T90-1\trules/a.md\ts/a/b/\tGA\tmarker-first\t결함1\t\t앵커')" \
    "$(printf 'T90-2\trules/b.md\ts/a/b/\tGA\tmarker-second\t결함2\t\t앵커')" \
    "$(printf 'T90-3\trules/c.md\ts/a/b/\tGA\tmarker-third\t결함3\t\t앵커')" \
    "$(printf 'T90-9\trules/z.md\t-\t-\t-\t결함9\t사유\t-')" > "$dir/rows.tsv"
  printf '%s\n' \
    "$(printf 'T90-7\trules/a.md\ts/a/b/\tGA\treport\t결함7\t\t앵커')" \
    "$(printf 'T90-8\trules/a.md\ts/a/b/\tGA\tno-such-marker\t결함8\t\t앵커')" > "$dir/rows_unresolved.tsv"
  printf '%s\n' "$(printf 'GA\ttest_group_alpha')" "$(printf 'HG\ttest_harness_group')" > "$dir/groups.tsv"
}

# 위치와 두 텍스트를 직접 주는 한 줄 변경 diff(`git diff -U0` 모양) — 소스 줄과 무관한 합성 변경(주석 위치 시험 등).
k6_fixture_raw_change_diff() {
  printf '%s\n' "diff --git a/f b/f" "--- a/f" "+++ b/f" "@@ -$1 +$1 @@" "-$2" "+$3"
}

# 소스 fixture 에서 marker 가 처음 나오는 줄 번호를 낸다.
k6_fixture_line_of() {
  grep -nF -- "$2" "$1/source.sh" | head -1 | cut -d: -f1
}

# 소스 fixture 의 한 줄을 바꾸는 diff 를 낸다 — 줄 번호는 marker 의 첫 등장으로 찾고, `+` 줄은 소스의 그 줄,
# `-` 줄은 old_text 다(소스 fixture 는 변경 뒤 버전이라 옛 줄은 따로 준다).
k6_fixture_line_change_diff() {
  local dir="$1" marker="$2" old_text="$3" line_number new_text
  line_number=$(k6_fixture_line_of "$dir" "$marker")
  new_text=$(sed -n "${line_number}p" "$dir/source.sh")
  k6_fixture_raw_change_diff "$line_number" "$old_text" "$new_text"
}

# 합성 fixture(dir)에 선택 코어 select 를 돌려 FULL·ROW·EXAMINED 레코드를 한 줄 요약으로 낸다(예
# `FULL:helper_one ROW:T90-2:name EXAMINED:3`). 시나리오가 주는 입력은 run.sh diff · 원장 diff · 바뀐 파일 목록
# (줄바꿈 구분 문자열)이고, 다섯째 인자로 원장 행 파일 이름(기본 rows.tsv)을 바꿀 수 있다. 코어가 비정상
# 종료하면 `CORE-FAILED:<종료 코드>` 를 낸다 — 어떤 기대값과도 같지 않다.
summarize_k6_fixture_selection() {
  local dir="$1" run_sh_diff_text="$2" ledger_diff_text="$3" changed_files_text="$4" rows_name="${5:-rows.tsv}"
  local core_output core_exit=0 summary
  printf '%s\n' "$run_sh_diff_text" > "$dir/run_sh.diff"
  printf '%s\n' "$ledger_diff_text" > "$dir/ledger.diff"
  printf '%s\n' "$changed_files_text" > "$dir/changed_files.txt"
  core_output=$(k6_selection_core select --source "$dir/source.sh" --mutation-rows "$dir/$rows_name" \
    --changed-files "$dir/changed_files.txt" --run-sh-diff "$dir/run_sh.diff" --ledger-diff "$dir/ledger.diff" \
    --group-functions "$dir/groups.tsv" --harness-group HG --core-repo-path tests/k6_selection.py \
    --margin "$K6_FIXTURE_MARGIN_LINES" 2>&1) || core_exit=$?
  if ((core_exit != 0)); then
    echo "CORE-FAILED:${core_exit}"
    return 0
  fi
  summary=$(awk -F'\t' '$1 == "FULL" {printf "FULL:%s ", $2} $1 == "ROW" {printf "ROW:%s:%s ", $2, $3} $1 == "EXAMINED" {printf "EXAMINED:%s", $2}' <<< "$core_output")
  echo "$summary"
}

# 합성 fixture 의 선택 요약이 기대값과 같은지 본다(0=같음). 다르면 실제 요약을 호출자(T37)의 동적 스코프 변수
# k6_fixture_actual 에 남겨 실패 메시지가 싣게 한다 — 인자는 summarize_k6_fixture_selection 과 같다.
k6_fixture_selection_is() {
  local expected="$1"
  shift
  k6_fixture_actual=$(summarize_k6_fixture_selection "$@")
  [[ "$k6_fixture_actual" == "$expected" ]]
}

# decide_k6_mode 의 결과를 `<모드>:<종류>:<반환값>` 한 줄로 낸다(T37-25 — 사유 문장은 보지 않는다).
summarize_k6_mode_decision() {
  local decision decision_exit=0
  decision=$(decide_k6_mode "$@") || decision_exit=$?
  printf '%s:%s' "$(cut -f1,2 <<< "$decision" | tr '\t' ':')" "$decision_exit"
}

# plan_k6_rows 시험(T37-25)용 스텁 셋 — 비교 기준 · 변경 입력 수집 · 선택 코어를 현재 셸에서 재정의한다. 호출자
# (summarize_k6_plan_scenario)의 동적 스코프 변수 stub_* 를 읽는다. 실물 함수를 덮어쓰므로 서브셸 안에서만 부른다.
define_k6_plan_stubs() {
  resolve_k6_diff_base() {
    if [[ -n "$stub_base_failure" ]]; then
      echo "$stub_base_failure"
      return 1
    fi
    echo "0123456789abcdef0123456789abcdef01234567"
  }
  collect_k6_change_inputs() {
    local out_dir="$3"
    if [[ -n "$stub_collect_failure" ]]; then
      echo "$stub_collect_failure"
      return 1
    fi
    printf 'tests/run.sh\n' > "$out_dir/changed_files.txt"
    printf '@@ -1 +1 @@\n-a\n+b\n' > "$out_dir/run_sh.diff"
    : > "$out_dir/ledger.diff"
    printf '%b\ttests/run.sh\n' "$stub_numstat" > "$out_dir/numstat.txt"
  }
  k6_selection_core() {
    if ((stub_core_exit != 0)); then
      echo "스텁 코어 고장" >&2
      return "$stub_core_exit"
    fi
    printf '%b' "${stub_records}EXAMINED\t${stub_examined}\nRUNSH_CHANGES\t${stub_runsh_changes}\nLEDGER_CHANGES\t0\n"
  }
}

# plan_k6_rows 의 배선을 스텁으로 시험한다(T37-25) — 시나리오가 정한 코어 레코드·git 실패를 스텁(define_k6_plan_stubs)
# 으로 흘려 보내고 plan_k6_rows 를 돌려 `<모드>|<선택 행 수>|<선택 ID들>|<사유>|<plan 로그>` 한 줄을 낸다. 실물 코어를
# 돌리는 T37-15 만으로는 「코어 출력 → 선택 행 파일·모드」 배선(awk 조인 · FULL 사유 읽기 · 계산 이상 전환)이 고장나도
# 증분 0행처럼 보일 뿐이라 레코드를 못 박아 두고 선택 행과 모드에 그대로 반영되는지 본다. 시나리오: rows(ROW 둘) ·
# full(FULL 하나) · none · modeonly(실행 비트만 바뀜 — numstat 0 이면 변경 줄 0 이어도 이상이 아니다) · norepo ·
# collectfail · crash · examined(코어가 읽은 변조행 수 어긋남) · unread(내용이 바뀌었는데 변경 줄 0) ·
# ghostrow(원장에 없는 ID 의 ROW) · badmode(결정이 모르는 모드 값을 냄 — 증분으로 기울지 않고 전체 행을 쓰며 전체로
# 로그해야 한다) · request(요청 변수 1 — 전체로 가야 한다) · badvalue(요청 변수가 1 이 아닌 값 — 전체로 가고 값 오류를
# 보고해야 한다). 전체가 서브셸이라 plan_k6_rows 가 쓰는 전역·상태가 T37 로 새지 않는다. 호출 환경의 요청 변수는 서브셸
# 맨 앞에서 지운다: 문서화된 전체 재확인 명령(`CODING_HARNESS_K6_FULL=1 bash tests/run.sh`)으로 돌려도 plan_k6_rows 가 그 값을
# 읽어 요청 없는 시나리오가 거짓 실패하지 않게 하고, 요청 시나리오는 이 서브셸 안에서만 변수를 둔다.
summarize_k6_plan_scenario() {
  (
    unset "$K6_FULL_REQUEST_ENV_NAME"
    local scenario="$1" work_dir="$2"
    local k6_mode="full" k6_reason="" k6_base_short="" k6_changed_file_count=0
    local k6_selected_rows=0 k6_selected_rows_file="" ledger_mutation_rows=3
    local stub_records="" stub_core_exit=0 stub_numstat='1\t1' stub_base_failure="" stub_collect_failure=""
    local stub_examined=3 stub_runsh_changes=2 ledger_rows selected_ids plan_log
    case "$scenario" in
      rows) stub_records='ROW\tT90-1\tblock\nROW\tT90-3\ttarget,name\n' ;;
      full) stub_records='FULL\thelper_one\n' ;;
      ghostrow) stub_records='ROW\tNO-SUCH-1\tblock\n' ;;
      modeonly) stub_runsh_changes=0; stub_numstat='0\t0' ;;
      unread) stub_runsh_changes=0 ;;
      examined) stub_examined=5 ;;
      crash) stub_core_exit=2 ;;
      norepo) stub_base_failure="git 저장소가 아님" ;;
      collectfail) stub_collect_failure="스텁 수집 실패" ;;
      request) export "${K6_FULL_REQUEST_ENV_NAME}=1" ;;
      badvalue) export "${K6_FULL_REQUEST_ENV_NAME}=yes" ;;
    esac
    define_k6_plan_stubs
    if [[ "$scenario" == "badmode" ]]; then
      decide_k6_mode() { printf 'unknown\tnone\t\n'; }
    fi
    ledger_rows=$(printf '%s\n' \
      "$(printf 'T90-1\trules/a.md\ts/a/b/\tGA\tmarker-first\t결함1\t\t앵커')" \
      "$(printf 'T90-2\trules/b.md\ts/a/b/\tGA\tmarker-second\t결함2\t\t앵커')" \
      "$(printf 'T90-3\trules/c.md\ts/a/b/\tGA\tmarker-third\t결함3\t\t앵커')" \
      "$(printf 'T90-9\trules/z.md\t-\t-\t-\t결함9\t사유\t-')")
    mkdir -p "$work_dir"
    plan_k6_rows "$ledger_rows" "$work_dir" > "$work_dir/plan.log" 2>&1
    selected_ids=$(cut -d $'\x1f' -f 1 "$k6_selected_rows_file" | tr '\n' ',')
    plan_log=$(tr '\n' ' ' < "$work_dir/plan.log")
    echo "${k6_mode}|${k6_selected_rows}|${selected_ids%,}|${k6_reason}|${plan_log}"
  )
}

# precheck_k6_group 의 세 반환을 `<실패 그룹>:<미러 생성 실패>:<통과>` 한 줄로 낸다(T37-26): 레지스트리에 없는 그룹 T0
# 는 실물 미러의 run.sh 가 인자 오류(exit 2)로 끝나 사전조건 FAIL 이므로 1, 미러 루트가 비면 미러를 못 만들어 2,
# run_group_in_mirror 를 0 반환 스텁으로 바꾸면 통과 0 이다. 호출마다 서브셸이라 계수(precondition_groups_run)와 스텁이
# T37 로 새지 않는다.
summarize_k6_precheck_scenarios() {
  local failing_exit=0 mirror_failure_exit=0 passing_exit=0
  ( precheck_k6_group "T0" ) > /dev/null 2>&1 || failing_exit=$?
  ( MUTATION_MIRROR_ROOT=""; precheck_k6_group "T29" ) > /dev/null 2>&1 || mirror_failure_exit=$?
  ( run_group_in_mirror() { return 0; }; precheck_k6_group "T29" ) > /dev/null 2>&1 || passing_exit=$?
  echo "${failing_exit}:${mirror_failure_exit}:${passing_exit}"
}

# judge_k6_selected_rows 의 배선을 스텁으로 시험한다(T37-26) — 서브셸 안에서 run_group_in_mirror(그룹 T25 만 변조 전
# FAIL)와 assert_guard_bites(부른 guard_id 기록)를 재정의하고 T29·T25·T29 순서 세 행 파일을 판정시켜
# `<판정 행>:<생략 행>:<실패 그룹>:<실행 그룹>|<판정을 부른 ID들>` 한 줄을 낸다. 미러는 실물(make_repo_mirror)이다.
# 그룹은 처음 등장 순서(T29, T25)로 한 번씩만 훑고, 사전조건이 깨진 T25 의 행은 판정하지 않고 생략으로 세야 한다.
summarize_k6_judge_scenario() {
  (
    local selected_rows_file="$1"
    local rows_judged=0 precondition_skipped_rows=0 precondition_groups_run=0 precondition_groups_failed=0
    local judged_ids=""
    run_group_in_mirror() {
      if [[ "$2" == "T25" ]]; then
        return 1
      fi
      return 0
    }
    assert_guard_bites() { judged_ids="${judged_ids}${judged_ids:+,}$1"; }
    judge_k6_selected_rows "$selected_rows_file" > /dev/null 2>&1
    echo "${rows_judged}:${precondition_skipped_rows}:${precondition_groups_failed}:${precondition_groups_run}|${judged_ids}"
  )
}

# T37(tests-hardening PRP S3a). 뮤테이션 원장(tests/mutations.tsv)과 그 파서·완비 검사
# (K5)·변조행 판정(K6)·ID 래칫·한계 표기 검사·공허 통과 방지·자기 고정점을 고정한다.
# 파서·수집기 자체는 합성 fixture 로 시험하고(T37-1~T37-10), 원장 완비성·래칫·한계
# 표기·공허 통과 방지·변조행 판정은 실물 tests/run.sh·tests/mutations.tsv 를 대상으로
# 한다(T37-11~T37-15). 변조행 판정(K6)은 기본 실행에서 이번 변경이 닿은 행만 판정하고(증분 —
# 규칙 정본은 tests/k6_selection.py 와 plan_k6_rows 의 주석, 요약은 tests/mutations.tsv 헤더 「K6 선택」
# 문단) 변조 전 실행은 그룹당 1회다 — 그 선택 코어(T37-21~T37-23)·비교 기준과 변경 입력 수집(T37-24)·
# 모드 결정(T37-25)·그룹 사전조건 판정(T37-26)은 합성 fixture 로 시험한다. T37 자신의 서브체크는
# 미러 안에서 T37 을 실행할 수 없어(무한 재귀, GOTCHA 7) 원장에 등록될 때 전부 면제행이다.
#
# 그 면제를 대신 받치는 것(§10-2-(2) 결정 (b))의 실제 범위 — T37-16(자기 고정점)이 잡는
# 것은 assert_guard_bites 의 판정이 「항상 통과」로 고장나는 **한 형태**다. 나머지
# 서브체크(파서 불변식 8종 · 수집기 2종 · 래칫 · 완비 검사 · 한계 표기 검사)의 판정이
# 고장나는 형태는 이 고정점이 다루지 않고, 그 자리는 각 서브체크에 붙은 분모 단언
# (검사 건수 == 원장 변조행 수 · 분모 > 0 · 서브체크 수 자기 일관성)이 부분적으로
# 대신한다. 전수 증명이 아니다.
test_mutation_ledger_harness() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T37"
  local test_desc="뮤테이션 원장 하네스 — 파서 불변식·완비 검사(K5)·변조행 판정(K6)·ID 래칫·한계 표기·자기 고정점"
  log_test_name "$test_name" "$test_desc"

  local probes_run=0
  local fixture_target="rules/common/testing.md"
  local mutation_ledger_path="$REPO_ROOT/tests/mutations.tsv"

  # 성공 경로에서도 출력하는 카운터(PRP §10-2-(3)). 층 3 을 만들지 않는 근거가 「층 2 의
  # 부재는 카운터 0 으로 드러난다」는 비대칭이므로, 통과했을 때도 이 수치가 로그에 남아야
  # 그 근거가 성립한다. 파싱 실패로 아래 블록이 건너뛰어지면 0 으로 남아 부재가 드러난다.
  local ledger_total_rows=0 ledger_mutation_rows=0 ledger_exempt_rows=0
  local limit_checks_performed=0
  # K6(T37-15) 상태 — plan_k6_rows·judge_k6_selected_rows 계열이 동적 스코프로 갱신한다
  # (parse_mutation_ledger 의 seen_guard_ids 와 같은 관례 — 호출 함수 안에서 다시 local 로
  # 선언하면 이 변수가 가려져 계수가 새 버린다).
  local k6_mode="full" k6_reason="" k6_base_short="" k6_changed_file_count=0
  local k6_selected_rows=0 k6_selected_rows_file="" k6_elapsed_seconds=0
  local rows_judged=0 precondition_skipped_rows=0 precondition_groups_run=0 precondition_groups_failed=0

  # fixture 파일과 미러 사본을 담는 루트 두 개를 여기서 한 번만 만들어 등록한다(주제 1-c·
  # 5-a). 개별 fixture·미러는 명령 치환 안에서 만들어져(서브셸) 스스로 등록할 수 없으므로,
  # 등록 가능한 부모를 현재 셸에서 만들어 두는 것이 fail-safe 를 되찾는 유일한 방법이다.
  # 여기서 mktemp 결과를 검사하는 이유: set -e 는 이 호출 트리에서 꺼져 있어(GOTCHA 1)
  # 실패가 빈 문자열로 조용히 흐르고, 빈 경로는 하류에서 파괴적 인자로 승격된다.
  local fixture_root
  fixture_root=$(mktemp -d) || fixture_root=""
  MUTATION_MIRROR_ROOT=$(mktemp -d) || MUTATION_MIRROR_ROOT=""
  if ! mutation_harness_roots_are_ready "$fixture_root" "$MUTATION_MIRROR_ROOT"; then
    note_failure "T37-0: 사전조건 실패 — fixture 루트('$fixture_root') 또는 미러 루트('$MUTATION_MIRROR_ROOT')를 mktemp -d 로 만들 수 없어 서브체크를 하나도 실행할 수 없다"
    finish_group "$test_name"
    return 0
  fi
  register_cleanup_path "$fixture_root" "$MUTATION_MIRROR_ROOT"

  # ---- T37-1: 열 수 불일치(7·9) → 파싱 실패 [불변식 6] ----
  # 아래 모든 fixture 시나리오는 "거부됐는가"뿐 아니라 "기대한 사유로 거부됐는가"까지
  # 단언한다(mutation_ledger_fixture_is_rejected 의 두 번째 인자) — 종료 코드만 보면
  # fixture 생성 자체를 고장낸 변조에서 전부 조용히 통과한다(그 함수 주석의 실측).
  # 열 수 7·9(구 6·8)는 8번째 열 anchor_function 신설의 결과다(ledger-anchor-column
  # PRP §7-4).
  ((probes_run++)) || true
  local fixture_cols7 fixture_cols9
  fixture_cols7=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-1\t%s\t-\t-\t-\t결함\t사유' "$fixture_target")")
  if ! mutation_ledger_fixture_is_rejected "$fixture_cols7" "열 수"; then
    note_failure "T37-1: 열 7개(anchor_function 누락)가 '열 수' 사유로 거부되지 않음(불변식 6 무력화)"
  fi
  fixture_cols9=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-2\t%s\t-\t-\t-\t결함\t사유\t앵커\t여분' "$fixture_target")")
  if ! mutation_ledger_fixture_is_rejected "$fixture_cols9" "열 수"; then
    note_failure "T37-1: 열 9개(여분 열)가 '열 수' 사유로 거부되지 않음(불변식 6 무력화)"
  fi

  # ---- T37-2: guard_id 포맷 위반·중복 → 파싱 실패 [불변식 1] ----
  ((probes_run++)) || true
  local fixture_badformat fixture_dup
  fixture_badformat=$(write_ledger_fixture "$fixture_root" "$(printf 'BADID\t%s\t-\t-\t-\t결함\t사유\t-' "$fixture_target")")
  if ! mutation_ledger_fixture_is_rejected "$fixture_badformat" "guard_id 포맷/유일성"; then
    note_failure "T37-2: guard_id 포맷 위반(BADID)이 'guard_id 포맷/유일성' 사유로 거부되지 않음(불변식 1 무력화)"
  fi
  fixture_dup=$(write_ledger_fixture "$fixture_root" \
    "$(printf 'T90-3\t%s\t-\t-\t-\t결함1\t사유1\t-' "$fixture_target")" \
    "$(printf 'T90-3\t%s\t-\t-\t-\t결함2\t사유2\t-' "$fixture_target")")
  if ! mutation_ledger_fixture_is_rejected "$fixture_dup" "guard_id 포맷/유일성"; then
    note_failure "T37-2: guard_id 중복(T90-3)이 'guard_id 포맷/유일성' 사유로 거부되지 않음(불변식 1 무력화)"
  fi

  # ---- T37-3: target_path 미실재·절대경로·`..` 이탈 → 파싱 실패 [불변식 2] ----
  # 뒤 두 형태가 이 서브체크에 있는 이유(주제 2): 절대경로·`..` 는 "$REPO_ROOT/$1" 존재
  # 검사를 통과하면서 "$mirror_dir/$target_path" 결합에서 미러 봉쇄 밖을 가리켜, 실제
  # 저장소 파일이 sed -i 로 변조되는 것이 검수에서 재현됐다.
  ((probes_run++)) || true
  local fixture_missing_path fixture_absolute_path fixture_escaping_path
  fixture_missing_path=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-4\trules/common/__does_not_exist__.md\t-\t-\t-\t결함\t사유\t-')")
  if ! mutation_ledger_fixture_is_rejected "$fixture_missing_path" "target_path 무효"; then
    note_failure "T37-3: target_path 미실재가 'target_path 무효' 사유로 거부되지 않음(불변식 2 무력화)"
  fi
  # 절대경로 프로브에 "/" 를 쓰는 이유: 존재 검사는 "$REPO_ROOT/$1" 결합으로 하므로 대부분의
  # 절대경로는 결합 결과가 실재하지 않아 존재 검사만으로도 우연히 걸러진다 — 그러면 이 프로브가
  # 절대경로 가드를 실제로 시험하지 못한다(가드를 지워도 통과하는 것을 실측했다). "/" 는
  # 결합 결과가 "$REPO_ROOT//" 로 실재하므로 절대경로 거부만이 이 행을 막는다.
  fixture_absolute_path=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-11\t/\t-\t-\t-\t결함\t사유\t-')")
  if ! mutation_ledger_fixture_is_rejected "$fixture_absolute_path" "target_path 무효"; then
    note_failure "T37-3: 절대경로 target_path 가 거부되지 않음(미러 봉쇄 밖으로 나가는 쓰기 경로가 열린다)"
  fi
  fixture_escaping_path=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-12\ttests/../%s\t-\t-\t-\t결함\t사유\t-' "$fixture_target")")
  if ! mutation_ledger_fixture_is_rejected "$fixture_escaping_path" "target_path 무효"; then
    note_failure "T37-3: '..' 이 섞인 target_path 가 거부되지 않음(미러 봉쇄 밖으로 나가는 쓰기 경로가 열린다)"
  fi

  # ---- T37-4: 면제행 구조 위반(expect_group 또는 anchor_function 이 "-" 아님) →
  # 파싱 실패 [불변식 3] ---- 둘째 프로브는 ledger-anchor-column PRP §5-2 신설(8번째 열
  # 요구를 면제행에도 건다).
  ((probes_run++)) || true
  local fixture_exempt_bad fixture_exempt_anchor_present
  fixture_exempt_bad=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-5\t%s\t-\tT29\t-\t결함\t사유\t-' "$fixture_target")")
  if ! mutation_ledger_fixture_is_rejected "$fixture_exempt_bad" "면제행 구조 위반"; then
    note_failure "T37-4: 면제행인데 expect_group != '-' 인 행이 '면제행 구조 위반' 사유로 거부되지 않음(불변식 3 무력화)"
  fi
  fixture_exempt_anchor_present=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-17\t%s\t-\t-\t-\t결함\t사유\tsome_function' "$fixture_target")")
  if ! mutation_ledger_fixture_is_rejected "$fixture_exempt_anchor_present" "면제행 구조 위반"; then
    note_failure "T37-4: 면제행인데 anchor_function != '-' 인 행이 '면제행 구조 위반' 사유로 거부되지 않음(불변식 3 무력화, ledger-anchor-column PRP §5-2)"
  fi

  # ---- T37-5: 변조행 구조 위반(exempt_reason 존재 · anchor_function 형식 위반) →
  # 파싱 실패 [불변식 4] ---- 아래 anchor_ok 는 형식만 맞으면 되는 자리를 채우는
  # placeholder 다(이 서브체크는 파서만 보므로 실재 함수일 필요가 없다).
  ((probes_run++)) || true
  local fixture_mutation_bad
  fixture_mutation_bad=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-6\t%s\ts/a/b/\tT29\ttoken\t결함\t사유있음\tanchor_ok' "$fixture_target")")
  if ! mutation_ledger_fixture_is_rejected "$fixture_mutation_bad" "변조행 구조 위반"; then
    note_failure "T37-5: 변조행인데 exempt_reason 이 비어있지 않은 행이 '변조행 구조 위반' 사유로 거부되지 않음(불변식 4 무력화)"
  fi
  local fixture_mutation_dir_target
  fixture_mutation_dir_target=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-13\trules\ts/a/b/\tT29\ttoken\t결함\t\tanchor_ok')")
  if ! mutation_ledger_fixture_is_rejected "$fixture_mutation_dir_target" "변조행 구조 위반"; then
    note_failure "T37-5: 변조 대상이 디렉토리인 행이 '변조행 구조 위반' 사유로 거부되지 않음(sed -i 의 대상은 정규 파일이어야 한다)"
  fi
  # 아래 세 형태가 이 서브체크에 있는 이유(검수 3회차 차단 2, 그리고 셋째는 차단 1):
  # mutation_sed 열은 target_path 와 독립된 쓰기 경로다. target_path 를 미러 안에 두고 `w`
  # 플래그로 미러 밖에 파일을 실제로 만드는 것이 재현됐다(3층 봉쇄 전부 통과). 세 프로브는
  # 서로 다른 분기를 문다 — 첫 것은 플래그 자리의 파일 명령 대조, 둘째는 인식 못하는 형태의
  # fail-close 거부, 셋째는 정규화 자신이 진짜 구분자를 감췄던 `\\/` 우회다. 셋째가 여기
  # 있는 이유가 특히 분명하다: 로직 구멍과 테스트 구멍이 같은 자리였다 — 판정 함수가 `\/`
  # 만 지우던 동안 이 서브체크에도 `\\/` 계열 fixture 가 없었다.
  local fixture_sed_file_command fixture_sed_unrecognized fixture_sed_escaped_backslash
  fixture_sed_file_command=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-14\t%s\ts/a/b/w escaped.txt\tT29\ttoken\t결함\t\tanchor_ok' "$fixture_target")")
  if ! mutation_ledger_fixture_is_rejected "$fixture_sed_file_command" "변조행 구조 위반"; then
    note_failure "T37-5: mutation_sed 의 sed 파일 명령(w 플래그)이 거부되지 않음(미러 봉쇄 3층을 전부 통과하면서 미러 밖에 파일을 만드는 경로가 열린다)"
  fi
  fixture_sed_unrecognized=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-15\t%s\ts|a|b|\tT29\ttoken\t결함\t\tanchor_ok' "$fixture_target")")
  if ! mutation_ledger_fixture_is_rejected "$fixture_sed_unrecognized" "변조행 구조 위반"; then
    note_failure "T37-5: 인식하지 못하는 mutation_sed 형태(다른 구분자)가 거부되지 않음(플래그 자리를 특정할 수 없는 형태는 fail-close 로 막아야 한다)"
  fi
  # 변조 스크립트를 printf 의 형식 문자열이 아니라 %s 인자로 넘기는 이유: 형식 문자열에 두면
  # printf 가 `\\` 를 `\` 로 접어 fixture 에 들어가는 것이 이 프로브가 물려는 형태가 아니게
  # 된다(형식 문자열에 쓰려면 `\\\\` 가 필요하다 — 인자로 넘겨 그 층을 없앤다).
  fixture_sed_escaped_backslash=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-16\t%s\t%s\tT29\ttoken\t결함\t\tanchor_ok' "$fixture_target" 's/^a.*$/b37\\/w ../zzq1')")
  if ! mutation_ledger_fixture_is_rejected "$fixture_sed_escaped_backslash" "변조행 구조 위반"; then
    note_failure "T37-5: 이스케이프된 백슬래시 뒤에 진짜 구분자가 오는 mutation_sed 형태가 거부되지 않음(정규화가 그 진짜 구분자를 감추면 플래그 자리의 w 가 치환문 안으로 보여 tail 대조를 빠져나간다 — 미러 밖에 파일이 실제로 생긴다)"
  fi
  # 아래 세 프로브는 ledger-anchor-column PRP §5-2 신설 — anchor_function 이 빈 값이거나
  # 맨 함수명 형식(^[A-Za-z_][A-Za-z0-9_]*$)이 아니면 거부돼야 한다.
  local fixture_anchor_blank fixture_anchor_call_literal fixture_anchor_file_symbol
  fixture_anchor_blank=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-18\t%s\ts/a/b/\tT29\ttoken\t결함\t\t' "$fixture_target")")
  if ! mutation_ledger_fixture_is_rejected "$fixture_anchor_blank" "변조행 구조 위반"; then
    note_failure "T37-5: anchor_function 이 빈 값인 행이 '변조행 구조 위반' 사유로 거부되지 않음(불변식 4 무력화, ledger-anchor-column PRP §5-2)"
  fi
  fixture_anchor_call_literal=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-19\t%s\ts/a/b/\tT29\ttoken\t결함\t\tfoo() {' "$fixture_target")")
  if ! mutation_ledger_fixture_is_rejected "$fixture_anchor_call_literal" "변조행 구조 위반"; then
    note_failure "T37-5: anchor_function 이 '함수명() {' 리터럴 형태인 행이 '변조행 구조 위반' 사유로 거부되지 않음(불변식 4 무력화, ledger-anchor-column PRP §5-2)"
  fi
  # 이 값의 콜론 뒤를 숫자로 쓰지 않는다 — 가드가 사는 파일의 경로 뒤에 마침표 확장자와
  # 콜론과 숫자를 이어 붙인 리터럴은 T39-5 의 줄 번호 인용 래칫(line_citation_pattern)이
  # tests/run.sh 안에서 세는 형태와 그대로 겹쳐, 래칫을 무력화하지 않고도 상한을 넘긴다
  # (실제로 겪었다 — 이 주석에는 그 리터럴을 다시 옮겨 적지 않는다, 겪은 그대로를 재현하게
  # 되기 때문이다). 콜론 뒤를 숫자가 아닌 심볼로 써서 "파일:심볼" 형태(§15 항목 1)를 그대로
  # 대표하면서 그 래칫을 피한다.
  fixture_anchor_file_symbol=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-20\t%s\ts/a/b/\tT29\ttoken\t결함\t\ttests/run.sh:some_symbol' "$fixture_target")")
  if ! mutation_ledger_fixture_is_rejected "$fixture_anchor_file_symbol" "변조행 구조 위반"; then
    note_failure "T37-5: anchor_function 이 '파일:심볼' 형태인 행이 '변조행 구조 위반' 사유로 거부되지 않음(불변식 4 무력화, ledger-anchor-column PRP §5-2)"
  fi

  # ---- T37-6: 자기 참조(expect_group == 이 그룹) 거부 → 파싱 실패 [GOTCHA 7] ----
  ((probes_run++)) || true
  local fixture_self_ref
  fixture_self_ref=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-7\t%s\ts/a/b/\t%s\ttoken\t결함\t\tanchor_ok' "$fixture_target" "$MUTATION_HARNESS_GROUP")")
  if ! mutation_ledger_fixture_is_rejected "$fixture_self_ref" "expect_group=$MUTATION_HARNESS_GROUP"; then
    note_failure "T37-6: expect_group 이 이 그룹 자신인 행(자기 참조)이 거부되지 않음(GOTCHA 7 무력화, 무한 재귀 위험)"
  fi

  # ---- T37-7: defect_description 공백 → 파싱 실패 [불변식 5] ----
  ((probes_run++)) || true
  local fixture_blank_defect
  fixture_blank_defect=$(write_ledger_fixture "$fixture_root" "$(printf 'T90-8\t%s\t-\t-\t-\t\t사유\t-' "$fixture_target")")
  if ! mutation_ledger_fixture_is_rejected "$fixture_blank_defect" "defect_description 공백"; then
    note_failure "T37-7: defect_description 공백이 'defect_description 공백' 사유로 거부되지 않음(불변식 5 무력화)"
  fi

  # ---- T37-8: 정상 경로 — 주석·빈 줄 무시 + 유효 면제행 1·변조행 1 파싱 성공 ----
  ((probes_run++)) || true
  local fixture_valid valid_row_count
  fixture_valid=$(write_ledger_fixture "$fixture_root" \
    "# 주석 줄 — 무시돼야 함" \
    "" \
    "$(printf 'T90-9\t%s\t-\t-\t-\t결함9\t사유9\t-' "$fixture_target")" \
    "$(printf 'T90-10\t%s\ts/a/b/\tT29\ttoken\t결함10\t\tanchor_ok' "$fixture_target")")
  if valid_row_count=$(mutation_ledger_fixture_row_count "$fixture_valid"); then
    if [[ "$valid_row_count" -ne 2 ]]; then
      note_failure "T37-8: 정상 원장 fixture 의 파싱 행 수 불일치(실제 $valid_row_count, 기대 2)"
    fi
  else
    note_failure "T37-8: 주석·빈줄 섞인 정상 원장인데 파싱 실패함(불변식 오작동)"
  fi

  # ---- T37-9: collect_guard_ids — ID 있는 호출 추출·ID 없는 호출 미포함·중복 제거 ----
  ((probes_run++)) || true
  local guard_id_fixture_file guard_id_fixture_output
  guard_id_fixture_file="$fixture_root/collect_guard_ids_fixture.sh"
  {
    echo 'note_failure "T91-1: 있는 ID 추출"'
    echo 'note_failure "산문, ID 없음 — 미포함돼야 함"'
    echo 'note_failure "T91-1: 같은 ID 두 번째 등장(중복 제거돼야 함)"'
  } > "$guard_id_fixture_file"
  guard_id_fixture_output=$(collect_guard_ids "$guard_id_fixture_file")
  if [[ "$(grep -c . <<< "$guard_id_fixture_output")" -ne 1 || "$guard_id_fixture_output" != "T91-1" ]]; then
    note_failure "T37-9: collect_guard_ids 추출 결과가 기대(T91-1 하나)와 다름 — 실제: ${guard_id_fixture_output:-<빈 값>}"
  fi

  # ---- T37-10: collect_guard_ids — 한 줄에 두 ID → 첫 것만 ----
  ((probes_run++)) || true
  local two_id_fixture_file two_id_output
  two_id_fixture_file="$fixture_root/two_id.sh"
  echo 'note_failure "T91-2: 첫번째ID T91-3: 두번째ID(첫 것만 추출돼야 함)"' > "$two_id_fixture_file"
  two_id_output=$(collect_guard_ids "$two_id_fixture_file")
  if [[ "$two_id_output" != "T91-2" ]]; then
    note_failure "T37-10: 한 줄에 두 ID 가 있을 때 첫 것만 추출되지 않음 — 실제: ${two_id_output:-<빈 값>}"
  fi

  # ---- T37-11 (K5): 실물 원장 파싱 사전조건 + 양방향 완비 검사 ----
  ((probes_run++)) || true
  local source_ids source_id_count ledger_rows ledger_parse_exit=0
  source_ids=$(collect_guard_ids "$REPO_ROOT/tests/run.sh")
  source_id_count=$(grep -c . <<< "$source_ids") || true
  # 차집합(소스 − 원장)은 소스 집합이 비면 공허하게 빈다 — 추출을 통째로 고장낸 변조에서
  # K5 가 통과하는 것을 실측했다. 분모를 먼저 단언한다(T28-1 의 BLOCKS_CHECKED > 0 선례).
  if ((source_id_count == 0)); then
    note_failure "T37-11: 사전조건 실패 — 소스에서 추출한 서브체크 ID 가 0건(collect_guard_ids 고장 — K5 의 차집합이 공허하게 빈다)"
  fi
  # 하한 래칫이 따로 필요한 이유(주제 3 통합 수정): 아래 역방향 차집합은 소스와 원장이
  # 함께 줄어드는 변경(가드를 지우고 그 원장 행도 함께 지운다)을 볼 수 없다 — 양쪽 집합이
  # 같이 작아지므로 두 차집합 모두 빈 채로 통과한다. 원장 밖 상수가 그 바닥을 못박는다.
  if ((source_id_count < SOURCE_GUARD_ID_FLOOR)); then
    note_failure "T37-11: 소스 서브체크 ID 가 ${source_id_count}건 — 하한 ${SOURCE_GUARD_ID_FLOOR}건 미달(가드가 대량 삭제됐거나 추출이 부분적으로 고장났다 — 정당한 삭제라면 SOURCE_GUARD_ID_FLOOR 를 내리는 커밋에 이유가 필요하다)"
  fi
  # 예약 번호가 실재 그룹이 되면 K5 가 그 그룹의 새 서브체크를 이미 등록된 것으로 오인한다.
  if is_registered_test_group "$RESERVED_LEDGER_ONLY_GROUP"; then
    note_failure "T37-11: 원장 전용 예약 그룹 번호 ${RESERVED_LEDGER_ONLY_GROUP} 가 레지스트리의 실제 그룹이 됨 — 원장의 예약 ID 를 다른 번호로 옮기지 않으면 K5 가 그 그룹의 새 서브체크를 등록된 것으로 오인한다"
  fi
  ledger_rows=$(parse_mutation_ledger "$mutation_ledger_path" 2>&1) || ledger_parse_exit=$?
  if ((ledger_parse_exit != 0)); then
    note_failure "T37-11: 사전조건 실패 — 실물 원장(tests/mutations.tsv) 파싱 자체가 실패함(아래 T37-13~T37-15 결과는 무의미): ${ledger_rows:0:300}"
  else
    ledger_total_rows=$(grep -c . <<< "$ledger_rows") || true
    ledger_mutation_rows=$(awk -F'\t' '$3 != "-"' <<< "$ledger_rows" | grep -c .) || true
    ledger_exempt_rows=$((ledger_total_rows - ledger_mutation_rows))
    local ledger_guard_ids missing_ids_text missing_ids_count
    ledger_guard_ids=$(awk -F'\t' '{print $1}' <<< "$ledger_rows")
    missing_ids_text=$(comm -23 <(sort -u <<< "$source_ids") <(sort -u <<< "$ledger_guard_ids"))
    if [[ -n "$missing_ids_text" ]]; then
      # 목록을 절단하는 이유: 추출·원장 어느 한쪽이 통째로 고장나면 이 목록이 수백 건이
      # 되어 한 줄에 쏟아진다(실측). 건수는 전부 보여 주고 예시만 앞에서 자른다.
      missing_ids_count=$(grep -c . <<< "$missing_ids_text") || true
      note_failure "T37-11: 원장 완비 검사 실패(K5, 소스 − 원장) — 미등록 ID ${missing_ids_count}건: $(head -n "$GUARD_ID_LIST_PREVIEW_LIMIT" <<< "$missing_ids_text" | tr '\n' ' ')..."
    fi
    # 역방향(원장 − 소스). 원장 전용 ID 는 1차 시민이라 "원장에 있고 소스에 없다"가 곧
    # 위반은 아니지만, 예약 접두를 쓰지 않은 원장 전용 ID 는 두 가지 실제 위반 중 하나다:
    # (i) 소스에서 그 가드가 사라진 고아 행 — 단방향 검사만으로는 등록된 가드를 소스에서
    #     지워도 차집합이 비어 조용히 통과한다(실측: 기존 가드 하나를 `:` 로 치환하니
    #     exit 0·PASS), (ii) 실재 그룹 번호를 빌려 쓴 행 — 나중에 그 그룹이 같은 번호의
    #     서브체크를 추가하면 K5 가 그것을 "이미 등록됨"으로 오인한다(T36-8·T36-9 사태).
    # 이 단언이 있어야 원장 헤더의 「예약 번호 규약」이 기계로 지켜진다.
    local ledger_only_text ledger_only_id unreserved_ledger_only=()
    ledger_only_text=$(comm -13 <(sort -u <<< "$source_ids") <(sort -u <<< "$ledger_guard_ids"))
    while IFS= read -r ledger_only_id; do
      [[ -z "$ledger_only_id" ]] && continue
      [[ "${ledger_only_id%%-*}" == "$RESERVED_LEDGER_ONLY_GROUP" ]] && continue
      unreserved_ledger_only+=("$ledger_only_id")
    done <<< "$ledger_only_text"
    if ((${#unreserved_ledger_only[@]} > 0)); then
      note_failure "T37-11: 원장 완비 검사 실패(K5, 원장 − 소스) — 예약 접두 ${RESERVED_LEDGER_ONLY_GROUP}- 가 아닌 원장 전용 ID ${#unreserved_ledger_only[@]}건: $(printf '%s ' "${unreserved_ledger_only[@]}" | cut -c1-200)... (소스에서 가드가 사라진 고아 행이거나 실재 그룹 번호를 빌려 쓴 행이다)"
    fi
  fi

  # ---- T37-12: ID 접두 부재 래칫(<= NOTE_FAILURE_ID_LESS_RATCHET) ----
  ((probes_run++)) || true
  local total_call_lines with_id_lines without_id_count
  total_call_lines=$(grep -cE '^[[:space:]]*(note_failure|record_failure)[[:space:]]' "$REPO_ROOT/tests/run.sh") || true
  with_id_lines=$(grep -E '^[[:space:]]*(note_failure|record_failure)[[:space:]]' "$REPO_ROOT/tests/run.sh" \
    | grep -cE '"T[0-9]+-[0-9a-z]+') || true
  # 분모를 먼저 단언한다(주제 3-a — 형제 세 곳에는 있는데 여기만 빠져 있었다). 분모가 0 이
  # 되면 without_id_count 가 음수가 되고 `-822 > 111` 이 거짓이라 래칫이 통과한다(실측).
  if ((total_call_lines == 0)); then
    note_failure "T37-12: 사전조건 실패 — note_failure/record_failure 호출 줄이 0건(래칫의 분모가 공허하다 — 추출 패턴 고장)"
  fi
  without_id_count=$((total_call_lines - with_id_lines))
  if ((without_id_count < 0)); then
    note_failure "T37-12: 래칫 계산 모순 — ID 없는 호출 수가 음수(${without_id_count}): 분모 ${total_call_lines}건보다 ID 보유 ${with_id_lines}건이 많다(두 패턴이 서로 다른 집합을 세고 있다)"
  fi
  if ((without_id_count > NOTE_FAILURE_ID_LESS_RATCHET)); then
    note_failure "T37-12: ID 접두 부재 래칫 초과 — 실제 ${without_id_count}건(상한 ${NOTE_FAILURE_ID_LESS_RATCHET})"
  fi

  # ---- T37-13 (§4.6): 원장의 변조행마다 한계 표기가 있는가 + 5열 토큰이 판별자
  # 자격(보고 줄 hit 1)을 갖는가 + 선언된 앵커가 위조되지 않았는가(면제행 제외,
  # ledger-anchor-column PRP §5-3·§10-2 로 신설) ----
  ((probes_run++)) || true
  if ((ledger_parse_exit == 0)); then
    # has_limit_annotation_for_guard·guard_token_is_inside_anchor 의 상태를 하나의
    # annotation_status 로 합쳐 갈라 보고한다(주제 5-c·6-c 의 유산 + §10-2 신설) — 앵커
    # 해소가 이미 실패(2)했으면 교차검증은 같은 이유로 또 실패할 뿐이라 건너뛴다.
    # 판별자 자격(count_token_hits_in_report_lines)은 앵커 해소와 독립인 별개 사실이라
    # annotation_status 케이스에 섞지 않고 discriminator_invalid 로 따로 모은다(검수
    # 1회차 Major A — 원장 헤더가 약속한 이 검사가 실행 코드 없이 문서에만 있었다).
    local limit_missing=() anchor_failed=() token_outside_anchor=() discriminator_invalid=()
    local row_guard row_target row_sed row_token row_anchor
    local annotation_status report_hit_count
    while IFS=$'\x1f' read -r row_guard _ row_sed _ row_token _ _ row_anchor; do
      [[ -z "$row_guard" ]] && continue
      [[ "$row_sed" == "-" ]] && continue
      ((limit_checks_performed++)) || true
      report_hit_count=$(count_token_hits_in_report_lines "$REPO_ROOT/tests/run.sh" "$row_token")
      if [[ "$report_hit_count" != "1" ]]; then
        discriminator_invalid+=("${row_guard}(${report_hit_count}건)")
      fi
      annotation_status=0
      has_limit_annotation_for_guard "$row_anchor" || annotation_status=$?
      if ((annotation_status == 0)) && ! guard_token_is_inside_anchor "$row_anchor" "$row_token"; then
        annotation_status=3
      fi
      # bash 함정(R5, ledger-anchor-column PRP §10-2): `*` 가 1 과 3 을 함께 받으므로
      # `3)` 분기를 명시하지 않으면 새 상태가 「표기 없음」으로 뭉개진다.
      case "$annotation_status" in
        0) ;;
        2) anchor_failed+=("$row_guard") ;;
        3) token_outside_anchor+=("$row_guard") ;;
        *) limit_missing+=("$row_guard") ;;
      esac
    done < <(awk -F'\t' 'BEGIN{OFS="\x1f"} {$1=$1; print}' <<< "$ledger_rows")
    if ((${#discriminator_invalid[@]} > 0)); then
      note_failure "T37-13: 판별자 자격 실패(§5-3) — expect_token 이 tests/run.sh 의 실패 보고 호출 줄에서 정확히 1건이 아님(0건 또는 2건 이상): ${discriminator_invalid[*]}"
    fi
    if ((${#limit_missing[@]} > 0)); then
      note_failure "T37-13: 한계 표기 존재 검사 실패(§4.6) — 가드 함수 주석에 한계 표기가 없음: ${limit_missing[*]}"
    fi
    if ((${#anchor_failed[@]} > 0)); then
      note_failure "T37-13: 앵커 해소 실패 — anchor_function 이 tests/run.sh 안에서 정의를 찾지 못했거나(0건) 중복 정의됐다(2건 이상): ${anchor_failed[*]}"
    fi
    if ((${#token_outside_anchor[@]} > 0)); then
      note_failure "T37-13: 앵커 교차검증 실패 — expect_token 이 선언된 anchor_function 의 몸통 밖에 있음(앵커 위조 가능성, ledger-anchor-column PRP §10-2): ${token_outside_anchor[*]}"
    fi
    # 루프가 한 행도 돌지 않아도 위 검사는 공허하게 통과한다(입력 스트림을 죽인 변조에서
    # 실측). 원장의 변조행 수와 실제 검사 건수가 같은지 단언해 그 자리를 막는다.
    if ((limit_checks_performed != ledger_mutation_rows)); then
      note_failure "T37-13: 한계 표기를 검사한 행 수 불일치 — 실제 ${limit_checks_performed}건(원장 변조행 ${ledger_mutation_rows}행)"
    fi
  fi

  # ---- T37-14: 공허 통과 방지 — 원장 총 행수·변조행 수가 0 이면 실패(T28-1 선례) ----
  ((probes_run++)) || true
  if ((ledger_parse_exit == 0)); then
    if [[ "$ledger_total_rows" -eq 0 ]]; then
      note_failure "T37-14: 원장 총 행수가 0 — parse_mutation_ledger 가 아무것도 못 냄(공허 통과 방지)"
    fi
    if [[ "$ledger_mutation_rows" -eq 0 ]]; then
      note_failure "T37-14: 원장에 변조행이 0개 — K6 을 실행할 판정 쌍이 없음(공허 통과 방지)"
    fi
    # 위 두 단언과 T37-13·전체 모드 T37-15 의 "검사 건수 == 변조행 수" 단언은 분모가 모두
    # 같은 원장에서 파생된다 — 변조행이 사라지면 `0 != 0` 으로 함께 침묵한다(주제 3-b). 원장
    # 밖 상수로 바닥을 못박아 그 자리를 막는다.
    if ((ledger_mutation_rows < LEDGER_MUTATION_ROW_FLOOR)); then
      note_failure "T37-14: 원장 변조행 ${ledger_mutation_rows}행 — 하한 ${LEDGER_MUTATION_ROW_FLOOR}행 미달(K6 층이 얇아졌다 — 변조행을 줄이려면 LEDGER_MUTATION_ROW_FLOOR 를 내리는 커밋에 이유가 필요하다)"
    fi
    # 면제행 상한 래칫(PRP §12 「면제행이 영구 도피처가 된다」의 두 번째 완화). 사유
    # 문자열의 진위는 기계가 검사하지 않으므로(tests/mutations.tsv 의 한계 절), 신규 가드를
    # 기존 공통 사유로 면제 등록하는 것 자체는 파서를 통과한다 — 그 등록이 "상수를 올리는
    # 커밋"으로 드러나게 만드는 것이 이 단언의 역할이다.
    if ((ledger_exempt_rows > LEDGER_EXEMPT_ROW_RATCHET)); then
      note_failure "T37-14: 원장 면제행 ${ledger_exempt_rows}행 — 상한 ${LEDGER_EXEMPT_ROW_RATCHET}행 초과(신규 가드를 공통 사유로 면제 등록했다면 변조행으로 올리거나, 상수를 올리는 커밋에 이유를 남겨야 한다)"
    fi
  fi

  # ---- T37-15 (K6): 이번 변경이 닿은 변조행을 그룹 단위로 판정 — 변조 전 실행은 그룹당 1회 ----
  # 기본 실행은 증분이다(plan_k6_rows 가 모드·근거·선택 행을 정한다 — 공용 부분 변경·전체 재확인 요청·
  # 기준 계산 불능·계산 이상이면 전체). 모드 줄은 매 실행 찍는다. 판정은 judge_k6_selected_rows 가 한다.
  ((probes_run++)) || true
  if ((ledger_parse_exit == 0)); then
    local k6_started_seconds=$SECONDS k6_distinct_groups
    plan_k6_rows "$ledger_rows" "$fixture_root"
    judge_k6_selected_rows "$k6_selected_rows_file"
    k6_elapsed_seconds=$((SECONDS - k6_started_seconds))
    # 판정할 행이 0 행이어도 이 블록은 조용히 통과한다 — 입력 스트림을 죽인 변조에서 전체
    # 실행이 exit 0 인 것을 실측했다(K6 층 전체가 공허해지는 자리). 세 단언이 그 자리를 막고,
    # 선택 코어의 입력 스트림 단언(a)·변경 줄 해석 단언(e)·git·코어 실패(f)·코어 출력이 선택 행·모드로
    # 옮겨졌는지의 배선 단언(g)은 plan_k6_rows 안에서 전체로 전환하며 실패를 보고한다. (b) 전체 모드의 선택
    # 행 수는 원장의 변조행 수와 같다.
    if [[ "$k6_mode" != "incremental" ]] && ((k6_selected_rows != ledger_mutation_rows)); then
      note_failure "T37-15: 전체 모드인데 선택한 행 수 불일치 — 선택 ${k6_selected_rows}행(원장 변조행 ${ledger_mutation_rows}행)"
    fi
    # (c) 판정한 행과 사전조건 때문에 생략한 행의 합은 선택 행 수와 같다 — 판정 루프가 행을
    # 건너뛰는 것을 막는다.
    if ((rows_judged + precondition_skipped_rows != k6_selected_rows)); then
      note_failure "T37-15: 판정한 행 수 불일치 — 판정 ${rows_judged}행 + 생략 ${precondition_skipped_rows}행 != 선택 ${k6_selected_rows}행"
    fi
    # (d) 사전조건을 실행한 그룹 수는 선택 행의 서로 다른 그룹 수와 같다 — 사전조건 호출이
    # 지워져도 아무 단언도 발화하지 않는 자리를 계수로 닫는다(run_k6_group_precondition 주석).
    k6_distinct_groups=$(cut -d $'\x1f' -f 4 "$k6_selected_rows_file" | sort -u | grep -c .) || true
    if ((precondition_groups_run != k6_distinct_groups)); then
      note_failure "T37-15: 사전조건을 실행한 그룹 수 불일치 — 실제 ${precondition_groups_run}개(선택 행의 서로 다른 그룹 ${k6_distinct_groups}개)"
    fi
  fi

  # ---- T37-16: 자기 고정점(음성 대조, §10-2-(2) 결정 (b)) — 판정 로직이 "항상 통과"로
  # 고장나면 물지 않는 변조도 통과시킨다. T29(rules/ 만 스캔)가 보지 않는
  # commands/*.md 줄 끝에 공백 1개를 더하는, 일부러 물지 않는 변조를 assert_guard_bites 에
  # 명령 치환 안에서 넘긴다(부수 효과 격리 — group_failures 오염 방지, T36-6/T36-7 선례) —
  # "가드 무력화" 분기가 정상 발화해 실패를 보고해야 정상이다. log_error 는 stdout 으로
  # 나가 캡처 변수에 섞이므로(S2 검수가 실측한 함정, 원 지적은 T36-7 이관 목록 4번) 기대
  # 패턴 어느 것도 없을 때 반드시 명시적으로 실패를 보고하는 else 분기를 둔다(공허 통과
  # 방지 — 이 원장 행은 tests/mutations.tsv 에 넣지 않는다, expect_group==T37 은
  # GOTCHA 7 로 파서가 거부한다). 대상 파일은 commands/dashboard.md 였으나 그 파일이
  # HD1(docs/prps/dashboard-into-hub.md)로 사라져 commands/hub.md 로 바꿨다 — T29 가
  # 보지 않는 commands/*.md 라는 조건은 그대로 만족한다.
  ((probes_run++)) || true
  local negative_control_output negative_control_flat
  negative_control_output=$(assert_guard_bites \
    "T37-16-fixture" "commands/hub.md" '1s/$/ /' "T29" "UNUSED-음성대조-토큰" 2>&1)
  negative_control_flat="${negative_control_output//$'\n'/ }"
  if [[ "$negative_control_output" == *"가드 무력화"* ]]; then
    :  # 기대한 실패 보고 확인됨 — 명령 치환(서브셸) 안에서 실행돼 T37 자신의
       # group_failures 를 오염시키지 않는다.
  elif [[ "$negative_control_output" == *"사전조건"* ]]; then
    note_failure "T37-16: 음성 대조 사전조건 불성립 — fixture 자체가 무효화됨: ${negative_control_flat:0:200}"
  else
    note_failure "T37-16: 음성 대조 실패 — 물지 않는 변조에도 '가드 무력화' 보고가 없음(판정 로직이 항상 통과로 고장했을 가능성) — 출력: ${negative_control_flat:0:200}"
  fi

  # ---- T37-17~T37-20: 이 하네스가 세운 가드 자신을 무는 서브체크(검수 3회차 차단 1) ----
  # 검수가 아래 네 가드를 각각 무력화(`if false`)했을 때 전체 실행이 그대로 PASS 였다
  # (실측). 무커버리지의 사유는 두 갈래다:
  #  - 앞 세 가드(위생 가드 · 미러 봉쇄 확인 · mktemp 가드 2종)는 note_failure 대신
  #    log_error + return 으로 보고한다 — collect_guard_ids 가 ID 를 보지 못하므로 K5 가
  #    원장 행을 요구하지 않았다.
  #  - 네 번째(T37 사전조건)는 note_failure 라 ID 도 원장 행도 있지만, 그 분기는 정상
  #    실행에서 도달하지 않으므로 판정을 고장내도 아무 단언이 발화하지 않았다.
  # 어느 쪽도 원장 변조행으로는 등록할 수 없다: 이 가드들은 T37 안에 있어 expect_group 이
  # T37 이 되고, 그러면 GOTCHA 7 로 파서가 그 행을 거부한다. 그래서 원장에는 면제행으로
  # 등록하고, 무는지는 여기서 직접 서브체크로 확인한다(재귀 문제가 없다 — 미러를 만들지
  # 않는다).

  # ---- T37-17: register_cleanup_path 위생 가드가 파괴적 경로를 거부하는가 ----
  # 양방향으로 본다 — "전부 거부"로 고장나면 스위트의 정리가 통째로 멈추고, "전부 통과"로
  # 고장나면 빈 값·`/` 가 chmod -R 755 · rm -rf 인자로 흘러간다(1회차 Critical 의 피해 경로).
  # CLEANUP_PATHS 를 비운 서브셸에서 부르는 이유는 T36-6 과 같다: 이 실험이 T37 자신이 아직
  # 쓰고 있는 바깥 스코프의 배열에 새지 않아야 한다.
  ((probes_run++)) || true
  local sanitizer_reject_probe sanitizer_accept_probe
  sanitizer_reject_probe=$(
    CLEANUP_PATHS=()
    register_cleanup_path "/" > /dev/null 2>&1 && printf 'accepted:' || printf 'rejected:'
    printf '%s' "${#CLEANUP_PATHS[@]}"
  )
  if [[ "$sanitizer_reject_probe" != "rejected:0" ]]; then
    note_failure "T37-17: register_cleanup_path 위생 가드가 '/' 등록을 막지 못함 — 기대 'rejected:0' 실제 '$sanitizer_reject_probe'(정리 단계의 chmod -R 755 · rm -rf 인자가 디스크 최상단이 된다)"
  fi
  sanitizer_accept_probe=$(
    CLEANUP_PATHS=()
    register_cleanup_path "$fixture_root/sanitizer_accept_probe" > /dev/null 2>&1 && printf 'accepted:' || printf 'rejected:'
    printf '%s' "${#CLEANUP_PATHS[@]}"
  )
  if [[ "$sanitizer_accept_probe" != "accepted:1" ]]; then
    note_failure "T37-17: register_cleanup_path 위생 가드가 정상 경로 등록을 거부함 — 기대 'accepted:1' 실제 '$sanitizer_accept_probe'(가드가 전부 거부로 고장나면 스위트의 정리가 통째로 멈춘다)"
  fi

  # ---- T37-18: 미러 봉쇄 확인이 봉쇄 밖을 가리키는 경로를 거부하는가 ----
  # 이것이 apply_mutation 의 마지막 쓰기 방어선이다(파서의 절대경로·`..` 거부가 첫 층).
  ((probes_run++)) || true
  local containment_probe_mirror="$fixture_root/containment_probe_mirror"
  mkdir -p "$containment_probe_mirror/inner"
  if ! mutation_target_is_inside_mirror "$containment_probe_mirror" "$containment_probe_mirror/inner/target.txt"; then
    note_failure "T37-18: 미러 봉쇄 확인이 봉쇄 안의 경로를 거부함(전부 거부로 고장나면 모든 변조행이 사전조건 실패가 되어 K6 층이 통째로 멈춘다)"
  fi
  if mutation_target_is_inside_mirror "$containment_probe_mirror" "$containment_probe_mirror/../escaped.txt"; then
    note_failure "T37-18: 미러 봉쇄 확인이 '..' 로 봉쇄 밖을 가리키는 경로를 통과시킴(sed -i 가 미러 밖 파일을 변조하는 경로가 열린다)"
  fi
  # 호출부까지 본다: 위 두 단언은 판정 함수 자신만 보므로, apply_mutation 에서 그 함수를
  # 부르는 한 줄을 지우면 두 단언이 그대로 통과한다(검수 3회차 실측 — 호출부만 무력화한
  # 전체 실행이 exit 0 이었다). 파서가 이런 target_path 를 이미 거부하니 여기서는
  # apply_mutation 을 직접 부른다(T37-16 이 assert_guard_bites 를 직접 부르는 것과 같은
  # 관용구). 마지막 단언이 음성 대조다 — 봉쇄가 쓰기 전에 끊지 못하면 미러 밖 파일이
  # 실제로 변조된다.
  local containment_outside_file="$fixture_root/containment_probe_outside.txt"
  printf 'canary\n' > "$containment_outside_file"
  local containment_call_output containment_call_exit=0
  containment_call_output=$(apply_mutation "$containment_probe_mirror" \
    "../containment_probe_outside.txt" 's/canary/pwned/' 2>&1) || containment_call_exit=$?
  local containment_call_flat="${containment_call_output//$'\n'/ }"
  if ((containment_call_exit == 0)) || [[ "$containment_call_output" != *"미러 봉쇄 밖"* ]]; then
    note_failure "T37-18: apply_mutation 이 미러 봉쇄 확인을 부르지 않음 — 종료 ${containment_call_exit}, 출력: ${containment_call_flat:0:200}"
  fi
  if [[ "$(cat "$containment_outside_file")" != "canary" ]]; then
    note_failure "T37-18: apply_mutation 이 미러 밖 파일을 실제로 변조함 — 봉쇄 확인이 쓰기 전에 끊지 못했다(파일 내용: $(cat "$containment_outside_file"))"
  fi

  # ---- T37-19: mktemp 실패를 검사하는 가드 2종(미러·fixture)이 발화하는가 ----
  # 읽기 전용(555) 디렉토리를 루트로 주면 mktemp 가 실제로 실패한다(실측). 이 가드가 없으면
  # 빈 경로가 하류로 흘러 `rsync -a "$REPO_ROOT/" "/"` · 빈 fixture 경로가 된다(1회차 Critical).
  # 빈 경로가 `/` 로 증폭되는 기제는 목적지 인자가 `"$mirror_dir/"` 라는 것이다 — 빈 값에
  # 붙은 그 슬래시가 디스크 최상단이 된다.
  # 권한 복구를 정리보다 먼저 한다(GOTCHA 10).
  #
  # 주의 — 이 프로브는 **무장(armed)** 성격이다: 정상 운영에서는 도달 불가였던 mktemp 실패
  # 분기를 매 실행마다 실제로 만든다. make_repo_mirror 의 mktemp 가드가 그 분기의 유일한
  # 방벽이므로 그 블록을 **삭제하거나 `if false` 로 거짓화하지 마라** — 그 조합은 위
  # `rsync -a "$REPO_ROOT/" "/"` 를 실제로 실행시킨다. 가드를 시험하려면 블록을 무력화하지
  # 말고 **반환값만 뒤집어라**.
  #
  # 그럼에도 실질 위험이 없는 근거는 **무장 조건과 피해 조건이 상호 배타적**이라는 것이다
  # (이 절은 실행이 아니라 추론이다 — root 로 돌려본 것이 아니다): 555 퍼미션이 존중되어야
  # mktemp 이 실패하는데 그것은 비-root 에서만 성립하고, 비-root 는 `/` 에 쓸 수 없다(실측 —
  # `/` 는 `drwxr-xr-x root wheel` 이고 uid 501 에서 `[ -w / ]` 가 거짓). root 는 DAC 를
  # 우회해 555 에서도 mktemp 이 **성공**하므로 위험 분기에 아예 도달하지 않고, 그때는 이
  # 프로브가 "가드가 발화하지 않음"으로 시끄럽게 실패한다(fail-loud, 조용한 피해가 아니다).
  # 이 배타성이 깨지는 조건도 적어 둔다 — **레포가 최상단에 `bin/`·`etc/`·`opt/` 같은
  # 디렉토리를 갖게 되면** root 실행 시 실제 덮어쓰기 경로가 열린다(현재 레포 최상단과 `/`
  # 최상단의 이름 교집합은 `.`·`..` 뿐 — 실측).
  ((probes_run++)) || true
  local mktemp_probe_readonly="$fixture_root/mktemp_probe_readonly"
  mkdir -p "$mktemp_probe_readonly"
  chmod 555 "$mktemp_probe_readonly"
  local mirror_mktemp_output fixture_mktemp_output mirror_mktemp_exit=0 fixture_mktemp_exit=0
  mirror_mktemp_output=$( MUTATION_MIRROR_ROOT="$mktemp_probe_readonly"; make_repo_mirror 2>&1 ) || mirror_mktemp_exit=$?
  fixture_mktemp_output=$(write_ledger_fixture "$mktemp_probe_readonly" "무의미한 행" 2>&1) || fixture_mktemp_exit=$?
  chmod u+w "$mktemp_probe_readonly" 2> /dev/null || true
  # 캡처한 출력에 줄바꿈이 섞여 있어(mktemp 자신의 stderr + log_error) 한 줄로 편다 —
  # T37-16 의 negative_control_flat 과 같은 관용구다.
  local mirror_mktemp_flat="${mirror_mktemp_output//$'\n'/ }"
  local fixture_mktemp_flat="${fixture_mktemp_output//$'\n'/ }"
  if ((mirror_mktemp_exit == 0)) || [[ "$mirror_mktemp_output" != *"mktemp -d 가 미러 경로를 만들지 못함"* ]]; then
    note_failure "T37-19: make_repo_mirror 의 mktemp 가드가 발화하지 않음(빈 미러 경로가 rsync 목적지로 흘러간다) — 종료 ${mirror_mktemp_exit}, 출력: ${mirror_mktemp_flat:0:200}"
  fi
  if ((fixture_mktemp_exit == 0)) || [[ "$fixture_mktemp_output" != *"mktemp 이 fixture 파일을 만들지 못함"* ]]; then
    note_failure "T37-19: write_ledger_fixture 의 mktemp 가드가 발화하지 않음(빈 fixture 경로가 printf 리다이렉션 대상이 된다) — 종료 ${fixture_mktemp_exit}, 출력: ${fixture_mktemp_flat:0:200}"
  fi

  # ---- T37-20: T37 자신의 사전조건 판정(mutation_harness_roots_are_ready) ----
  # 이 판정이 "항상 준비됨"으로 고장나면 빈 루트로 서브체크 전부가 무의미하게 돌고, "항상
  # 준비되지 않음"으로 고장나면 이 그룹이 첫 줄에서 조기 종료한다. 세 방향으로 본다.
  ((probes_run++)) || true
  if mutation_harness_roots_are_ready "" "$MUTATION_MIRROR_ROOT"; then
    note_failure "T37-20: 사전조건 판정이 빈 fixture 루트를 '준비됨'으로 봄(빈 경로가 하류의 mktemp·printf 인자로 흘러간다)"
  fi
  if mutation_harness_roots_are_ready "$fixture_root" "$fixture_root/__does_not_exist__"; then
    note_failure "T37-20: 사전조건 판정이 실재하지 않는 미러 루트를 '준비됨'으로 봄(make_repo_mirror 가 매 행에서 실패해 K6 층이 사전조건 실패로 뭉개진다)"
  fi
  if ! mutation_harness_roots_are_ready "$fixture_root" "$MUTATION_MIRROR_ROOT"; then
    note_failure "T37-20: 사전조건 판정이 실제로 준비된 두 루트를 '준비되지 않음'으로 봄(이 그룹이 서브체크를 하나도 실행하지 못하고 조기 종료한다)"
  fi
  # 한계(비망라) — 이 서브체크가 무는 것은 **판정 함수**다. 그 함수를 부르는 T37 본문의
  # 한 줄(위 사전조건 블록)을 지우는 변조는 여기서 드러나지 않는다: 그 호출부의 효과는
  # 이 그룹 자신의 mktemp -d 가 실제로 실패할 때만 관측되고, 하네스는 자기 루트에 대해
  # 그 실패를 만들어낼 수 없다(T37-18 은 apply_mutation 을 직접 부를 수 있어 호출부까지
  # 물지만, 여기는 그 우회로가 없다). 그 자리는 검수의 몫이다(§4.1 의 경계).
  # 전수 증명이 아니다.

  # ---- T37-21: 선택 코어의 diff 해석(parse-diff) ----
  # 코어가 변경 줄을 잘못 읽으면(헤더 줄을 변경으로 읽거나, 순수 삭제·혼합 hunk 의 위치를 틀리거나,
  # 내용이 `++`·`--` 로 시작하는 줄을 헤더로 오독하면) 선택이 조용히 빈다 — 합성 diff 한 벌을 기대
  # 레코드와 정확히 대조한다. 순수 삭제(`+c,0`)의 위치는 c(파일 맨 앞이라 c 가 0 이면 1), 혼합 hunk 의 `-` 줄
  # 위치는 새 쪽 시작이고, 주석·빈 줄은 `comment` 종류다. `\ No newline` 표지는 변경 줄이 아니다.
  ((probes_run++)) || true
  local parse_diff_fixture parse_diff_actual parse_diff_expected parse_diff_exit=0
  parse_diff_fixture=$(write_ledger_fixture "$fixture_root" \
    "diff --git a/f b/f" "index 111..222 100644" "--- a/f" "+++ b/f" \
    "@@ -1 +0,0 @@" "-first old" \
    "@@ -3,0 +4,2 @@ some_function() {" "+added one" "+added two" \
    "@@ -10,2 +11,0 @@" "-gone one" "-gone two" \
    "@@ -20 +22,2 @@" "-old" "+new one" "+new two" \
    "@@ -30,2 +33,2 @@" "---dash content" "-plain" "+++plus content" "+plain2" \
    "@@ -40 +44 @@" "-# old comment" "+# new comment" \
    "@@ -50 +54 @@" "-" "+" \
    "@@ -60 +64 @@" "-tail old" '\ No newline at end of file' "+tail new")
  parse_diff_actual=$(k6_selection_core parse-diff "$parse_diff_fixture" 2>&1) || parse_diff_exit=$?
  parse_diff_expected=$(printf '%s\t%s\t%s\n' 1 - code 4 + code 5 + code 11 - code 11 - code 22 - code 22 + code \
    23 + code 33 - code 33 - code 33 + code 34 + code 44 - comment 44 + comment 54 - comment 54 + comment \
    64 - code 64 + code)
  if ((parse_diff_exit != 0)) || [[ "$parse_diff_actual" != "$parse_diff_expected" ]]; then
    note_failure "T37-21: 선택 코어의 diff 해석이 기대 레코드와 다름 — 종료 ${parse_diff_exit}, 실제: ${parse_diff_actual//$'\n'/ | }"
  fi

  # ---- T37-22: 선택 코어 — 전체 재확인 트리거 판정 ----
  # 헬퍼 코드·최상위 배열·하네스 그룹 함수·heredoc 줄·삭제된 함수 정의·코어 파일이 바뀌면 전체(FULL)로 가고,
  # 주석·단일 줄 상수·일반 그룹 함수의 코드는 가지 않는다(그 셋은 행 선택이 맡는다). 합성 소스에서 각각 한 번씩
  # 본다 — 「항상 전체」로 고장나면 증분이 사라지고 「항상 증분」으로 고장나면 공용 부분 변경이 판정 없이 지나간다.
  ((probes_run++)) || true
  local k6_fixture_dir="$fixture_root/k6_core_fixture" k6_fixture_actual="" fixture_examined="EXAMINED:3"
  mkdir -p "$k6_fixture_dir"
  write_k6_fixture_source "$k6_fixture_dir"
  write_k6_fixture_rows "$k6_fixture_dir"
  if ! k6_fixture_selection_is "FULL:helper_one ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" 'local helper_value=1' '  local old_value=1')" "" ""; then
    note_failure "T37-22: 헬퍼 함수의 코드 변경이 전체 재확인(FULL)으로 판정되지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" '# helper inner comment' '  # old comment')" "" ""; then
    note_failure "T37-22: 헬퍼 함수 안 주석만 바뀐 변경이 전체 재확인으로 판정됨(주석은 공용 부분 변경이 아니다) — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" '# helper doc comment' '# old doc comment')" "" ""; then
    note_failure "T37-22: 최상위 주석만 바뀐 변경이 전체 재확인으로 판정됨 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "FULL:top-level ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" "'one'" "  'zero'")" "" ""; then
    note_failure "T37-22: 최상위 배열 줄의 변경이 전체 재확인으로 판정되지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "ROW:T90-2:name ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" 'readonly FIXTURE_LIMIT=3' 'readonly FIXTURE_LIMIT=2')" "" ""; then
    note_failure "T37-22: 단일 줄 상수의 변경이 전체 재확인으로 판정되거나 그 상수를 쓰는 가드 행을 고르지 못함 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "FULL:test_harness_group ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" 'local harness_value=1' '  local old_harness=1')" "" ""; then
    note_failure "T37-22: 하네스 그룹 함수의 코드 변경이 전체 재확인으로 판정되지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "FULL:helper_one ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" '# hash line inside heredoc' '# old hash line')" "" ""; then
    note_failure "T37-22: 헬퍼 안 heredoc 의 샵 줄 변경이 전체 재확인으로 판정되지 않음(heredoc 안의 줄은 주석처럼 보여도 코드다) — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "FULL:k6_selection.py ${fixture_examined}" "$k6_fixture_dir" "" "" "tests/k6_selection.py"; then
    note_failure "T37-22: 선택 코어 파일이 바뀐 파일 목록에 있는데 전체 재확인으로 판정되지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "ROW:T90-1:block ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" '  if false; then' '  if true; then')" "" ""; then
    note_failure "T37-22: 일반 그룹 함수 코드의 변경이 전체 재확인으로 판정됨(그 가드 블록의 행만 골라야 한다) — 실제: ${k6_fixture_actual}"
  fi
  # 함수 정의 줄이 지워진 diff 는 그 줄이 어느 함수 안에 있든(여기서는 최상위 주석 근처 위치) 공용 부분 변경이다 —
  # 지워진 줄은 새 파일에 없어 위치만으로는 함수를 알 수 없으므로 줄 텍스트(`이름() {`)로 알아본다.
  local fixture_doc_line
  fixture_doc_line=$(k6_fixture_line_of "$k6_fixture_dir" '# helper doc comment')
  if ! k6_fixture_selection_is "FULL:removed_helper ${fixture_examined}" "$k6_fixture_dir" \
    "$(printf '%s\n' "@@ -${fixture_doc_line} +$((fixture_doc_line - 1)),0 @@" "-removed_helper() {")" "" ""; then
    note_failure "T37-22: 함수 정의 줄이 삭제된 diff 가 전체 재확인으로 판정되지 않음(함수가 통째로 사라진 변경은 공용 부분 변경이다) — 실제: ${k6_fixture_actual}"
  fi

  # ---- T37-23: 선택 코어 — 행 선택 규칙 R1~R5 ----
  # 규칙마다 합성 변경 하나가 **기대한 행 하나만** 고른다 — 「항상 전부」로 고장나면 여러 행이 골라지고 「항상
  # 0행」이면 아무것도 골라지지 않는다(앞 서브체크의 케이스들이 「항상 0」 쪽을 함께 잡는다). 아무 변경이
  # 없으면 0행이고 EXAMINED 가 변조행 수와 같다(면제행은 세지 않는다). 가드 블록 여유는 위·아래 경계의 안쪽과
  # 바깥쪽을 모두 본다(한쪽만 보면 반대쪽 경계가 한 줄 넓거나 좁아져도 통과한다). R4 는 `local` 정의와 `local` 없는
  # 일반 대입을 따로 보고, R5 ① 은 return · record_failure · exit 키워드를 각각 가드 블록 **안** 줄로 본다(블록 밖
  # 줄은 R5 ② 도 같은 행을 골라 키워드 검출이 고장나도 결과가 같아 보인다).
  ((probes_run++)) || true
  local fixture_report_line fixture_second_head core_report_pattern
  fixture_report_line=$(k6_fixture_line_of "$k6_fixture_dir" 'note_failure "T90-1:')
  fixture_second_head=$(k6_fixture_line_of "$k6_fixture_dir" '# T90-2: second guard')
  if ! k6_fixture_selection_is "${fixture_examined}" "$k6_fixture_dir" "" "" ""; then
    note_failure "T37-23: 아무 변경이 없는데 행이 골라짐 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "ROW:T90-2:ledger ${fixture_examined}" "$k6_fixture_dir" "" \
    "$(printf '%s\n' "@@ -0,0 +1 @@" "+$(printf 'T90-2\trules/b.md\ts/a/b/\tGA\tmarker-second\t결함2\t\t앵커')")" ""; then
    note_failure "T37-23: R1(원장 diff 의 추가·변경 행)이 그 행 하나만 고르지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "ROW:T90-2:target ${fixture_examined}" "$k6_fixture_dir" "" "" "rules/b.md"; then
    note_failure "T37-23: R2(바뀐 파일 목록의 target_path)가 그 행 하나만 고르지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "ROW:T90-1:block ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" '  if false; then' '  if true; then')" "" ""; then
    note_failure "T37-23: R3(가드 블록 안의 변경 줄)이 그 행 하나만 고르지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "ROW:T90-1:block ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_raw_change_diff "$((fixture_report_line + K6_FIXTURE_MARGIN_LINES))" '  # old' '  # tweak')" "" ""; then
    note_failure "T37-23: R3 의 여유 경계 안쪽(보고 줄 + 여유 줄)의 주석 변경이 그 행을 고르지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_raw_change_diff "$((fixture_report_line + K6_FIXTURE_MARGIN_LINES + 1))" '  # old' '  # tweak')" "" ""; then
    note_failure "T37-23: R3 의 여유 경계 바깥쪽의 주석 변경이 행을 고름 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "ROW:T90-2:name ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" 'local alpha_flag=ready' '  local alpha_flag=old')" "" ""; then
    note_failure "T37-23: R4(그룹 함수 지역 변수 정의)가 그 변수를 참조하는 가드 블록의 행 하나만 고르지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "ROW:T90-2:name ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" 'readonly FIXTURE_LIMIT=3' 'readonly FIXTURE_LIMIT=2')" "" ""; then
    note_failure "T37-23: R4(최상위 단일 줄 상수)가 그 상수를 맨 낱말로 참조하는 가드 블록의 행 하나만 고르지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "ROW:T90-3:name ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" 'plain_total=0' '  plain_total=1')" "" ""; then
    note_failure "T37-23: R4(local 없는 일반 대입 정의)가 그 변수를 참조하는 가드 블록의 행 하나만 고르지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "ROW:T90-2:block ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_raw_change_diff "$((fixture_second_head - K6_FIXTURE_MARGIN_LINES))" '  # old' '  # tweak')" "" ""; then
    note_failure "T37-23: R3 의 위쪽 여유 경계 안쪽(ID 머리줄 − 여유 줄)의 주석 변경이 그 행을 고르지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_raw_change_diff "$((fixture_second_head - K6_FIXTURE_MARGIN_LINES - 1))" '  # old' '  # tweak')" "" ""; then
    note_failure "T37-23: R3 의 위쪽 여유 경계 바깥쪽(ID 머리줄 − 여유 줄 − 1)의 주석 변경이 행을 고름 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "ROW:T90-3:later ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" 'record_failure "$test_name" "cut early"' '  record_failure "$test_name" "old"; return 1')" "" ""; then
    note_failure "T37-23: R5(앞선 조기 종료 줄)가 그 줄보다 뒤의 행 하나만 고르지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "ROW:T90-1:block ROW:T90-2:later ROW:T90-3:later ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" '    return 1' '    return 0')" "" ""; then
    note_failure "T37-23: R5 ①(가드 블록 안 return 줄)이 그 블록의 행과 뒤 행들만 고르지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "ROW:T90-1:block ROW:T90-2:later ROW:T90-3:later ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" 'record_failure "$test_name" "in-block"' '    record_failure "$test_name" "old"')" "" ""; then
    note_failure "T37-23: R5 ①(가드 블록 안 record_failure 줄)이 그 블록의 행과 뒤 행들만 고르지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "ROW:T90-2:block ROW:T90-3:later ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" '    exit 3' '    exit 4')" "" ""; then
    note_failure "T37-23: R5 ①(가드 블록 안 exit 줄)이 그 블록의 행과 뒤 행(앞 행은 빼고)만 고르지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "ROW:T90-2:later ROW:T90-3:later ${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" 'prepare_shared_state' '  prepare_old_state')" "" ""; then
    note_failure "T37-23: R5(블록 밖 공용 줄)가 그 줄보다 뒤의 행 전부(앞 행은 빼고)를 고르지 않음 — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "${fixture_examined}" "$k6_fixture_dir" \
    "$(k6_fixture_line_change_diff "$k6_fixture_dir" '  return 77' '  return 78')" "" ""; then
    note_failure "T37-23: 그룹 함수 안 heredoc 의 return 줄 변경이 행을 고름(그 return 은 bash 의 조기 종료가 아니다) — 실제: ${k6_fixture_actual}"
  fi
  if ! k6_fixture_selection_is "ROW:T90-7:unresolved ROW:T90-8:unresolved EXAMINED:2" "$k6_fixture_dir" "" "" "" rows_unresolved.tsv; then
    note_failure "T37-23: 토큰 보고 줄이 정확히 1건이 아니어 블록을 정할 수 없는 행이 변경 없이도 선택되지 않음(행 단위 fail-close) — 실제: ${k6_fixture_actual}"
  fi
  # 코어(k6_selection.py)와 이 파일의 보고 줄 정의는 복제본이다 — 토큰 보고 줄은 T37-13 의 판별자 자격과 같은 분모로 봐야
  # 해서, 한쪽만 명령 이름이나 앵커를 바꾸면 코어가 블록 미상이나 엉뚱한 블록을 낸다. `[[:space:]]` 를 `\s` 로 바꿔 한 줄로 대조한다.
  core_report_pattern=$(python3 -B -c 'import sys; sys.path.insert(0, sys.argv[1]); import k6_selection; print(k6_selection.FAILURE_REPORT_LINE_PATTERN.pattern)' "$REPO_ROOT/tests" 2>&1) || true
  if [[ "$core_report_pattern" != "${FAILURE_REPORT_LINE_PATTERN//\[\[:space:\]\]/\\s}" ]]; then
    note_failure "T37-23: 코어의 보고 줄 정의(${core_report_pattern})가 이 파일의 FAILURE_REPORT_LINE_PATTERN(${FAILURE_REPORT_LINE_PATTERN})과 어긋남 — 한쪽만 고치면 코어가 블록 미상·엉뚱한 블록을 낸다"
  fi

  # ---- T37-24: 비교 기준(resolve_k6_diff_base)과 변경 입력 수집(collect_k6_change_inputs) ----
  # 임시 git 저장소로 본다. 저장소가 아니거나 origin/main 이 없거나 작업 폴더가 저장소의 하위 폴더면
  # 기준이 나오지 않아야 하고(전체로 가는 환경 사유), HEAD 가 origin/main 보다 앞서 있으면 기준은 origin/main
  # 의 커밋이어야 한다. 수집은 추적된 수정과 추적되지 않는 새 파일을 모두 담고(numstat 포함), 기준 커밋이 틀리면 빈
  # 출력으로 흐르지 않고 실패해야 한다(실패한 git 이 「바뀐 게 없다」가 되는 것이 이 설계의 유일한 fail-open 경로).
  # 임시 저장소에 쓰기 전에 init 성공과 대상 저장소 일치를 확인하는 게이트가 있어, 준비가 실패하면 쓰지 않고 보고한다.
  ((probes_run++)) || true
  local k6_repo="$fixture_root/k6_repo" k6_inputs_dir="$fixture_root/k6_inputs"
  local k6_base_output k6_base_commit k6_collect_output k6_collect_exit=0
  mkdir -p "$k6_repo/tests" "$k6_repo/sub" "$k6_inputs_dir"
  if k6_base_output=$(resolve_k6_diff_base "$k6_repo"); then
    note_failure "T37-24: git 저장소가 아닌 폴더에서 비교 기준이 나옴(.git 없는 격리 사본이 전체가 아니라 증분으로 돈다) — 출력: ${k6_base_output}"
  fi
  # 아래부터는 임시 저장소에 쓴다(add · commit · update-ref). init 이 성공했고 git 이 가리키는 저장소가 정말 이 임시
  # 폴더일 때만 쓴다 — init 이 실패했는데 쓰기를 이어 가면 git 이 위 폴더로 올라가며 바깥 저장소(임시 폴더가 저장소
  # 안에 놓인 환경 등)를 찾아 그 저장소에 커밋을 만들고 origin/main 을 옮길 수 있다. 그때는 준비 실패로 보고하고 쓰지 않는다.
  if ! k6_git -C "$k6_repo" init -q \
    || [[ "$(k6_git -C "$k6_repo" rev-parse --show-toplevel 2> /dev/null)" != "$(cd "$k6_repo" && pwd -P)" ]]; then
    note_failure "T37-24: 임시 저장소 준비 실패 — git init 이 실패했거나 git 이 이 임시 폴더가 아닌 저장소를 가리켜 add·commit·update-ref 를 건너뜀(바깥 저장소를 건드리지 않는 게이트)"
  else
    printf 'run\n' > "$k6_repo/tests/run.sh"
    printf 'ledger\n' > "$k6_repo/tests/mutations.tsv"
    printf 'tracked\n' > "$k6_repo/tracked.txt"
    k6_git -C "$k6_repo" add .
    k6_git -C "$k6_repo" -c user.name=k6 -c user.email=k6@invalid -c commit.gpgsign=false commit -q -m first
    if k6_base_output=$(resolve_k6_diff_base "$k6_repo"); then
      note_failure "T37-24: origin/main 이 없는 저장소에서 비교 기준이 나옴(기준 없이 증분으로 도는 길이 열린다) — 출력: ${k6_base_output}"
    fi
    k6_base_commit=$(k6_git -C "$k6_repo" rev-parse HEAD)
    k6_git -C "$k6_repo" update-ref refs/remotes/origin/main "$k6_base_commit"
    k6_git -C "$k6_repo" -c user.name=k6 -c user.email=k6@invalid -c commit.gpgsign=false commit -q --allow-empty -m second
    k6_base_output=$(resolve_k6_diff_base "$k6_repo") || k6_base_output="<실패: ${k6_base_output}>"
    if [[ "$k6_base_output" != "$k6_base_commit" ]]; then
      note_failure "T37-24: HEAD 가 origin/main 보다 앞설 때 비교 기준이 origin/main 의 커밋이 아님 — 기대 ${k6_base_commit}, 실제 ${k6_base_output}"
    fi
    if k6_base_output=$(resolve_k6_diff_base "$k6_repo/sub"); then
      note_failure "T37-24: 작업 폴더가 저장소의 하위 폴더인데 비교 기준이 나옴(이 사본과 무관한 변경이 기준이 된다) — 출력: ${k6_base_output}"
    fi
    printf 'run changed\n' > "$k6_repo/tests/run.sh"
    printf 'new\n' > "$k6_repo/new_file.txt"
    k6_collect_output=$(collect_k6_change_inputs "$k6_repo" "$k6_base_commit" "$k6_inputs_dir") || k6_collect_exit=$?
    if ((k6_collect_exit != 0)) \
      || ! grep -qxF 'tests/run.sh' "$k6_inputs_dir/changed_files.txt" \
      || ! grep -qxF 'new_file.txt' "$k6_inputs_dir/changed_files.txt" \
      || grep -qxF 'tracked.txt' "$k6_inputs_dir/changed_files.txt" \
      || ! grep -q '^@@ ' "$k6_inputs_dir/run_sh.diff" \
      || [[ -s "$k6_inputs_dir/ledger.diff" ]] \
      || ! grep -q $'^1\t1\ttests/run.sh$' "$k6_inputs_dir/numstat.txt"; then
      note_failure "T37-24: 변경 입력 수집이 기대와 다름(추적된 수정·추적되지 않는 새 파일은 담고 바뀌지 않은 파일은 빼며 run.sh diff 와 numstat 은 있고 원장 diff 는 비어야 한다) — 종료 ${k6_collect_exit}, 출력: ${k6_collect_output}, 목록: $(tr '\n' ' ' < "$k6_inputs_dir/changed_files.txt")"
    fi
    k6_collect_exit=0
    collect_k6_change_inputs "$k6_repo" "0000000000000000000000000000000000000000" "$k6_inputs_dir" > /dev/null 2>&1 || k6_collect_exit=$?
    if ((k6_collect_exit == 0)); then
      note_failure "T37-24: 존재하지 않는 기준 커밋으로 변경 입력 수집이 성공함(실패한 git 이 빈 출력으로 흘러 「바뀐 게 없다」가 된다)"
    fi
  fi

  # ---- T37-25: K6 모드 결정(decide_k6_mode)과 그 결과를 선택 행·모드로 옮기는 plan_k6_rows 의 배선 ----
  # 증분이 되는 길은 「요청 없음 · 환경 사유 없음 · 계산 이상 없음 · 공용 부분 변경 없음」 하나뿐이다. 각 입력
  # 하나가 전체로 가는지, 요청 값이 1 이 아니면 값 오류(반환 2)인지, 우선순위(요청 > 환경 > 계산 이상 > 공용 변경)가
  # 맞는지 본다. 케이스는 `기대 모드:종류:반환값|요청|환경 사유|계산 이상|공용 변경` 이다.
  ((probes_run++)) || true
  local mode_case mode_expected mode_request mode_environment mode_anomaly mode_common mode_actual
  for mode_case in \
    'full:request:0|1|||' \
    'full:invalid-request:2|yes|||' \
    'full:invalid-request:2|0|||' \
    'full:environment:0||origin/main 없음||' \
    'full:anomaly:0|||git diff 실패|' \
    'full:common-change:0||||공용 부분 변경(헬퍼)' \
    'incremental:none:0||||' \
    'full:request:0|1|환경|이상|공용' \
    'full:environment:0||환경|이상|공용' \
    'full:anomaly:0|||이상|공용'; do
    IFS='|' read -r mode_expected mode_request mode_environment mode_anomaly mode_common <<< "$mode_case"
    mode_actual=$(summarize_k6_mode_decision "$mode_request" "$mode_environment" "$mode_anomaly" "$mode_common")
    if [[ "$mode_actual" != "$mode_expected" ]]; then
      note_failure "T37-25: K6 모드 결정이 기대와 다름 — 케이스 '${mode_case}', 실제 '${mode_actual}'"
    fi
  done
  # plan_k6_rows 의 배선 — 코어가 낸 레코드(ROW·FULL)와 git 실패가 선택 행 파일과 모드에 그대로 반영되는지 스텁으로
  # 본다(summarize_k6_plan_scenario). 실물 코어를 도는 T37-15 만으로는 이 배선이 고장나도 증분 0행처럼 보일 뿐이다.
  # 케이스는 `시나리오|기대 모드|기대 선택 행 수|기대 선택 ID들|사유에 들어야 할 낱말|계획 로그에 들어야 할 낱말` 이다
  # (로그 낱말은 모드·행 수를 틀리게 찍는 변조를 문다 — 비워 두면 보지 않는다).
  local plan_case plan_name plan_expected_mode plan_expected_selected plan_expected_ids plan_reason_word plan_log_word
  local plan_summary plan_mode plan_selected plan_ids plan_reason plan_log
  for plan_case in \
    'rows|incremental|2|T90-1,T90-3||K6 증분: 2/3행' \
    'full|full|3|T90-1,T90-2,T90-3|helper_one|K6 전체: 3/3행' \
    'none|incremental|0|||K6 증분: 0/3행' \
    'modeonly|incremental|0|||K6 증분: 0/3행' \
    'badmode|unknown|3|T90-1,T90-2,T90-3||K6 전체: 3/3행' \
    'norepo|full|3|T90-1,T90-2,T90-3|비교 기준을 정할 수 없음' \
    'collectfail|full|3|T90-1,T90-2,T90-3|변경 입력을 모으지 못함' \
    'crash|full|3|T90-1,T90-2,T90-3|비정상 종료' \
    'examined|full|3|T90-1,T90-2,T90-3|읽은 변조행' \
    'unread|full|3|T90-1,T90-2,T90-3|변경 줄을 하나도 읽지 못함' \
    'ghostrow|full|3|T90-1,T90-2,T90-3|옮겨지지 않음' \
    'request|full|3|T90-1,T90-2,T90-3|CODING_HARNESS_K6_FULL=1 요청|K6 전체: 3/3행' \
    'badvalue|full|3|T90-1,T90-2,T90-3|값이 1 이 아니라|T37-15: CODING_HARNESS_K6_FULL=yes'; do
    IFS='|' read -r plan_name plan_expected_mode plan_expected_selected plan_expected_ids plan_reason_word plan_log_word <<< "$plan_case"
    plan_summary=$(summarize_k6_plan_scenario "$plan_name" "$fixture_root/k6_plan_${plan_name}")
    IFS='|' read -r plan_mode plan_selected plan_ids plan_reason plan_log <<< "$plan_summary"
    if [[ "$plan_mode" != "$plan_expected_mode" || "$plan_selected" != "$plan_expected_selected" \
      || "$plan_ids" != "$plan_expected_ids" || "$plan_reason" != *"$plan_reason_word"* \
      || "$plan_log" != *"$plan_log_word"* ]]; then
      note_failure "T37-25: plan_k6_rows 의 배선이 기대와 다름 — 시나리오 '${plan_name}', 기대 '${plan_expected_mode}|${plan_expected_selected}|${plan_expected_ids}|…${plan_reason_word}…|…${plan_log_word}…', 실제 '${plan_summary}'"
    fi
  done

  # ---- T37-26: 그룹 사전조건 판정(run_k6_group_precondition)이 PASS·FAIL 양방향을 구분하는가, 그리고 그
  # 판정을 부르는 배선(precheck_k6_group · judge_k6_selected_rows)이 실패한 그룹의 행을 판정하지 않는가 ----
  # 변조 전 실행은 그룹당 1회로 옮겨졌고(docs/prps/t37-incremental-k6.md §7), 이 판정이
  # 「항상 통과」로 고장나면 변조 전에 이미 FAIL 인 그룹의 변조 후 FAIL 을 「가드가 물었다」로
  # 오독하고, 「항상 실패」로 고장나면 모든 그룹이 사전조건 불성립으로 뭉개져 K6 층이 통째로
  # 멈춘다. 스텁 미러(tests/run.sh 가 exit 0 · exit 1 인 디렉토리)로 두 방향을 본다 — 진짜 그룹을
  # 돌리지 않으므로 재귀 문제가 없고, 서브셸 안에서 불러 이 함수의 계수(precondition_groups_run)가
  # T37 바깥으로 새지 않게 한다.
  ((probes_run++)) || true
  local precondition_stub_pass="$fixture_root/precondition_stub_pass"
  local precondition_stub_fail="$fixture_root/precondition_stub_fail"
  mkdir -p "$precondition_stub_pass/tests" "$precondition_stub_fail/tests"
  printf '%s\n' 'exit 0' > "$precondition_stub_pass/tests/run.sh"
  printf '%s\n' 'exit 1' > "$precondition_stub_fail/tests/run.sh"
  if ! ( run_k6_group_precondition "$precondition_stub_pass" "T29" ); then
    note_failure "T37-26: 사전조건 판정이 변조 전 PASS 인 그룹을 FAIL 로 판정함(항상 실패로 고장나면 모든 그룹이 사전조건 불성립으로 뭉개져 K6 층이 통째로 멈춘다)"
  fi
  if ( run_k6_group_precondition "$precondition_stub_fail" "T29" ); then
    note_failure "T37-26: 사전조건 판정이 변조 전 FAIL 인 그룹을 PASS 로 판정함(항상 통과로 고장나면 이미 FAIL 인 그룹의 변조 후 FAIL 을 「가드가 물었다」로 오독한다)"
  fi
  # 위 두 줄은 run_k6_group_precondition 자신만 본다. 그것을 부르는 precheck_k6_group(실패 그룹 1 · 미러 생성 실패 2 ·
  # 통과 0)과 판정 루프(judge_k6_group · judge_k6_selected_rows — 사전조건이 깨진 그룹의 행은 판정하지 않고 생략으로
  # 세고, 그룹은 처음 등장 순서로 한 번씩만 훑는다)의 배선은 따로 문다. 이 배선이 고장나도 지금까지는 변조 전 FAIL 인
  # 그룹의 행이 그대로 판정돼 실패 0건으로 통과했다.
  local precheck_actual judge_actual judge_rows_file="$fixture_root/judge_rows.txt"
  precheck_actual=$(summarize_k6_precheck_scenarios)
  if [[ "$precheck_actual" != "1:2:0" ]]; then
    note_failure "T37-26: precheck_k6_group 의 반환이 기대(없는 그룹 T0 → 1 · 미러 루트 없음 → 2 · 사전조건 통과 → 0)와 다름 — 실제 '${precheck_actual}'"
  fi
  printf 'T90-A\ta\tb\tT29\ttok\td\t\ta\nT90-B\ta\tb\tT25\ttok\td\t\ta\nT90-C\ta\tb\tT29\ttok\td\t\ta\n' \
    | awk -F'\t' 'BEGIN{OFS="\x1f"} {$1=$1; print}' > "$judge_rows_file"
  judge_actual=$(summarize_k6_judge_scenario "$judge_rows_file")
  if [[ "$judge_actual" != "2:1:1:2|T90-A,T90-C" ]]; then
    note_failure "T37-26: judge_k6_selected_rows 의 배선이 기대('판정 2 : 생략 1 : 실패 그룹 1 : 실행 그룹 2 | T90-A,T90-C' — 사전조건이 깨진 T25 의 행은 판정하지 않고 생략)와 다름 — 실제 '${judge_actual}'"
  fi

  # 카운터 출력(통과·실패 무관, PRP §10-2-(3)). 이 수치가 통과 로그에 남아야 층 2 의 부재가
  # 카운터 0 으로 드러나고, 그것이 층 3 을 만들지 않는 근거다.
  log_info "T37 원장 통계 — 총 ${ledger_total_rows}행(변조행 ${ledger_mutation_rows} · 면제행 ${ledger_exempt_rows}) · 소스 서브체크 ID ${source_id_count}건"
  local k6_mode_label="전체"
  if [[ "$k6_mode" == "incremental" ]]; then
    k6_mode_label="증분"
  fi
  log_info "T37 판정 통계 — K6 ${k6_mode_label} · 선택 ${k6_selected_rows}행 · 판정 ${rows_judged}행 · 사전조건 그룹 ${precondition_groups_run}개(실패 ${precondition_groups_failed}, 생략 ${precondition_skipped_rows}행) · K6 소요 ${k6_elapsed_seconds}초 · 한계 표기 검사 ${limit_checks_performed}건 · 서브체크 ${probes_run}건"

  # ---- T37-0: 실행한 서브체크 수의 자기 일관성 ----
  # 기대값을 리터럴이 아니라 원장에서 파생시킨다(비차단 지적): 리터럴 16 은 새 서브체크를
  # 추가하며 ((probes_run++)) 만 빼면 통과했다(실측). 원장의 이 그룹 접두 행 수에서 1 을
  # 빼면(빼는 1 은 이 T37-0 자신 — 서브체크가 아니라 그 개수를 세는 카운터 가드라
  # probes_run 을 올리지 않는다) 기대값이 되고, K5 가 「ID 를 붙이면 원장 행을 요구한다」를
  # 이미 강제하므로 서브체크를 늘리면 기대값이 따라 올라간다. 원장 파싱이 실패했으면
  # 기대값은 -1 로 남아 이 단언이 반드시 발화한다(공허 통과 방지).
  local ledger_harness_rows=0 expected_probe_count=-1
  if ((ledger_parse_exit == 0)); then
    ledger_harness_rows=$(awk -F'\t' -v prefix="${MUTATION_HARNESS_GROUP}-" 'index($1, prefix) == 1' <<< "$ledger_rows" | grep -c .) || true
    expected_probe_count=$((ledger_harness_rows - 1))
  fi
  if ((probes_run != expected_probe_count)); then
    note_failure "T37-0: 실행한 서브체크 ${probes_run}건이 기대값 ${expected_probe_count}건과 다름(원장의 ${MUTATION_HARNESS_GROUP}- 접두 행 ${ledger_harness_rows}행 − 카운터 가드 자신 1행, 공허 통과 방지)"
  fi

  finish_group "$test_name"
}

# T39(§21-7 항목 5 + 발견 (나), 설계 docs/prps/rules-docs-sync.md §4 「묶음 2」) 데이터
# 모델(§5-3) — (추출 정규식, 실측 키) 쌍의 평탄 배열. bash 3.2 에 declare -A 가 없어
# 위치 기반으로 순회한다(짝수 인덱스=정규식, 홀수 인덱스=키). 한계 표기·순서 의존 근거는
# 아래 test_prose_number_citation_hygiene() 바로 위 주석에 있다(T37-13 이 함수 정의
# 직전의 연속 주석 블록만 본다 — 배열 사이에 적으면 그 블록이 비어 보인다, 실측 확인).
readonly README_PROSE_DECLARATIONS=(
  '\*\*common/\*\* \([0-9]+ files\)'              "dir:common"
  '\*\*workflow/\*\* \([0-9]+ files\)'            "dir:workflow"
  '`typescript/` \([0-9]+ files\)'                "dir:typescript"
  '`react/` \([0-9]+ files\)'                     "dir:react"
  '`react-native/` \([0-9]+ files\)'              "dir:react-native"
  '`web/` \([0-9]+ files\)'                       "dir:web"
  '`python/` \([0-9]+ files\)'                    "dir:python"
  'All [0-9]+ rules'                              "agg:all"
  '\*\*Always loaded\*\* \([0-9]+ files\)'        "agg:always"
  '\*\*Conditionally loaded\*\* \([0-9]+ files\)' "agg:conditional"
)

# CLAUDE.md 의 배포 자산 수량 선언 vs install.sh 상수(T39-2). T30(rules/agents)·
# T22-138(commands)이 이미 상수 vs 실제 파일 수를 잠그므로, 여기서는 디렉토리를 다시
# 스캔하지 않고 그 상수를 대상으로 대조한다(D1 — 새 메커니즘을 만들지 않는다).
readonly CLAUDE_MD_ASSET_DECLARATIONS=(
  '`rules/` [0-9]+개'    "RULES_FILE_COUNT"
  '`agents/` [0-9]+개'   "AGENTS_FILE_COUNT"
  '`commands/` [0-9]+개' "COMMANDS_FILE_COUNT"
)

# T39-1 전용 — measure_key(위 배열의 홀수 열)를 실측값으로 바꾼다. "dir:<이름>"은
# rules/<이름> 최상위 파일 수, "agg:*"는 그 실측을 더한 집계다(README.md 자신 +1 은
# always-loaded 집계에서만 더한다 — §3-3 실측: 11+4+1=16).
readme_prose_actual_count() {
  local measure_key="$1"
  case "$measure_key" in
    dir:*)
      local dir_name="${measure_key#dir:}"
      find "$REPO_ROOT/rules/$dir_name" -maxdepth 1 -type f 2> /dev/null | wc -l | tr -d ' '
      ;;
    agg:all)
      find "$REPO_ROOT/rules" -type f | wc -l | tr -d ' '
      ;;
    agg:always)
      local common_count workflow_count
      common_count=$(find "$REPO_ROOT/rules/common" -maxdepth 1 -type f | wc -l | tr -d ' ')
      workflow_count=$(find "$REPO_ROOT/rules/workflow" -maxdepth 1 -type f | wc -l | tr -d ' ')
      echo $((common_count + workflow_count + 1))
      ;;
    agg:conditional)
      local ts_count react_count rn_count web_count python_count
      ts_count=$(find "$REPO_ROOT/rules/typescript" -maxdepth 1 -type f | wc -l | tr -d ' ')
      react_count=$(find "$REPO_ROOT/rules/react" -maxdepth 1 -type f | wc -l | tr -d ' ')
      rn_count=$(find "$REPO_ROOT/rules/react-native" -maxdepth 1 -type f | wc -l | tr -d ' ')
      web_count=$(find "$REPO_ROOT/rules/web" -maxdepth 1 -type f | wc -l | tr -d ' ')
      python_count=$(find "$REPO_ROOT/rules/python" -maxdepth 1 -type f | wc -l | tr -d ' ')
      echo $((ts_count + react_count + rn_count + web_count + python_count))
      ;;
  esac
}

# 산문이 인용하는 숫자의 위생. (a) 수량 선언은 실측(또는 잠긴 상수)과 일치해야 한다 —
# 이번 회차(묶음 2)는 이 축의 서브체크 3종(T39-1~T39-3)만 채운다. (b) 자기 수정에 따라
# 움직이는 줄 번호는 인용하지 않는 축(T39-4·T39-5)은 묶음 4 의 몫이라 아직 없다.
#
# 묶음 2 는 묶음 3·4 보다 먼저 선다(설계 §4) — 묶음 3·4 가 손대는 rules/python/·
# commands/ 의 파일 수량이 여기 T39-1·T39-2 파리티의 분모이므로, 분모 검사를 먼저
# 세워 두면 뒤 묶음의 편집이 그 분모를 흔드는 순간 이 그룹이 스스로 발화한다. 그 발화는
# 회귀가 아니라 이 순서의 목적이다(설계 §10 R2) — T22-138·T30 과 동형으로, 「문서가
# 자기 구성을 정확히 설명하는가」를 상시 감시하는 자리라 정상적인 파일 증감이 검사를
# 빨갛게 만드는 것 자체가 존재 이유다. 위양성(R1: 계약 토큰이 정당한 다듬기에도 발화)과는
# 다른 종류의 「빨개짐」이다 — 여기서 빨개지는 것은 산문 갱신을 잊었다는 신호다.
#
# 각 서브체크는 사전조건(추출이 정확히 1건)을 본 단정과 같은 서브체크 ID 로 먼저
# 확인한다 — 이 확인이 없으면 정규식이 조용히 0건을 매치해 선언 추출값이 비고 실측값도
# 우연히 0이면, bash 3.2 가 `[[ "" -eq "" ]]` 를 참으로 평가하는 성질(실측 확인) 탓에
# 본 단정(선언 대 실측)이 공허 통과할 수 있다. 사전조건과 본 단정이 ID 를 공유하는
# 관용구는 묶음 1 §14-2 를 그대로 따른다 — 새 ID 도 새 원장 행도 늘리지 않는다.
#
# 검수 1회차 Minor 반영: 사전조건 자신이 보는 계수 변수(match_count 류)는 grep -cE
# 직후 ${var:-0} 로 기본값을 채운다. 대상 파일이 없으면 grep -c 가 표준출력에 아무것도
# 내지 않아(있고 매치가 0건일 때만 "0"을 찍는다, 실측 확인) 진단 메시지의 숫자 자리가
# 비는 결함이 있었다. 기본값을 채운 뒤로는 이 계수 비교에 빈 문자열이 도달하지 않으므로,
# 위 문단이 쓰는 성질은 이 계수 비교의 근거가 아니게 됐다 — 그 성질이 여전히 막아야
# 하는 자리는 선언 추출값과 실측값 쪽이다.
#
# 기제: 세 서브체크 모두 「산문에서 정규식으로 추출한 선언 숫자를 실측(또는 잠긴
# 상수)과 비교」하는 형태다.
# 그 기제에서 따라오는 한계: 같은 뜻을 다른 표기(「N 개」·「스물」·표)로 옮기면 추출이
# 0건이 되어 사전조건 분기가 실패로 잡지만, 그 분기 자신도 지금의 정규식 표기에 갇혀
# 있다 — 표기가 바뀌면 검사 전체가 무엇도 보지 못하는 채로 통과한다.
# 비망라 예시 — 이 그룹이 보지 않는 것: 위 세 파일 밖의 다른 수량 인용(§13 대기열
# 1·2) · 줄 번호 인용(T39-4·T39-5, 아직 없음) · 숫자가 아닌 산문 표류.
# 전수 증명이 아니다.
#
# 오케스트레이터 실측(검수 1회차 반영 중 확인) — README_PROSE_DECLARATIONS 를 비우면
# 위 for 문이 0회 순회해 readme_expected_checks 도 0 이 되고, 이 그룹을 단독 실행
# (--only T39)했을 때 조용히 통과한다(재현 확인). 이 그룹 자신은 그 퇴행을 못 잡는다.
#
# 기제: 그것을 잡는 것은 이 그룹이 아니라 원장 판정 쌍이다(K6, tests/mutations.tsv 의
# T39-1 행) — 그 행은 rules/README.md 의 common 선언 숫자를 변조해 T39 를 다시
# 실행하는데, 배열이 비면 그 변조에도 T39 가 PASS 로 남아 판정 쌍이 실패를
# 보고한다(재현 확인).
#
# 한계: 그 방어는 배열 10쌍 중 common 하나만 겨냥한다 — common 쌍을 남기고 나머지
# 9쌍을 지워도 판정 쌍은 여전히 PASS 다(재현 확인). 표 구동 선택이 낳는 이 모양은
# §12 「표 구동 선택에서 따라오는 한계」가 T38 을 예로 적은 것과 같다.
#
# 비망라 예시 — 위 판정 쌍이 증명하지 않는 것: common 을 제외한 9쌍 각각의 개별 배선,
# CLAUDE_MD_ASSET_DECLARATIONS·rn_anchor 류에도 같은 모양이 있는지(이 회차는 확인하지
# 않았다). readme_checked 불일치 단언도 참고할 값이 있다 — 사전조건 실패가 이미
# note_failure 를 낸 뒤에만 발화할 수 있어(재현 확인) 단독 검출력이 없는 이중
# 안전장치이지만, 문면 자체가 거짓은 아니다.
#
# 전수 증명이 아니다.
#
# T39-4·T39-5(설계 §4 「묶음 4」, 항목 7·8) 기제 — 배포 트리(rules/·agents/·commands/)와
# tests/run.sh 자신에서 "파일명:줄번호" 형태 인용 수를 세어 각각의 래칫 상수와 비교하고,
# "currently line[s]/around lines N" 형태는 배포 트리에서 0건을 직접 단언한다(§7 이 이
# 형태엔 별도 상수를 두지 않는다고 정했다 — 늘 0인 래칫은 빈 그릇이다, YAGNI).
#
# 그 기제에서 따라오는 한계: 두 정규식이 보는 표기 형태에 갇힌다 — "N번째 줄"처럼 다른
# 표기로 줄 번호를 인용하면 세지 못한다. 래칫은 개수만 보므로 인용 하나를 지우고 다른
# 인용 하나를 넣으면 총계가 유지돼 발화하지 않는다(SOURCE_GUARD_ID_FLOOR 주석과 같은
# 한계).
#
# 자기 참조 처방 — 이 그룹의 grep 대상에는 tests/run.sh 자신이 들어간다. 그래서 이
# 문단을 포함해 이 파일에 새로 적는 주석은 "파일명:줄번호" 형태를 쓰지 않는다(썼다면 그
# 즉시 아래 래칫이 올랐을 것이다) — 정규식 리터럴 자신은 콜론 다음에 실제 숫자 문자가
# 오지 않아 자기 패턴에 매치하지 않음을 grep 으로 직접 확인했다(구현 시 실측).
#
# 비망라 예시 — 위 두 서브체크가 보지 않는 것: 두 표기 형태 밖의 줄 번호 인용 · 숫자가
# 아닌 형태의 문서 표류(구조도·예시 코드).
#
# 전수 증명이 아니다.
test_prose_number_citation_hygiene() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T39"
  local test_desc="산문 수량 파리티 — rules/README.md(T39-1) · CLAUDE.md 배포 자산(T39-2) · react-native 파일 수(T39-3) · 배포 트리 줄 번호 인용 래칫(T39-4) · run.sh 자신의 줄 번호 인용 래칫(T39-5)"
  log_test_name "$test_name" "$test_desc"

  # ---- T39-1: rules/README.md 산문 수량(디렉토리별 7 + 집계 3) vs 실측 ----
  local readme_file="$REPO_ROOT/rules/README.md"
  local readme_index readme_checked=0
  local readme_expected_checks=$((${#README_PROSE_DECLARATIONS[@]} / 2))
  for ((readme_index = 0; readme_index < ${#README_PROSE_DECLARATIONS[@]}; readme_index += 2)); do
    local readme_anchor="${README_PROSE_DECLARATIONS[readme_index]}"
    local readme_key="${README_PROSE_DECLARATIONS[readme_index + 1]}"
    local readme_match_count readme_declared readme_actual
    readme_match_count=$(grep -cE "$readme_anchor" "$readme_file") || true
    readme_match_count="${readme_match_count:-0}"
    if [[ "$readme_match_count" -ne 1 ]]; then
      note_failure "T39-1: 사전조건 실패 — rules/README.md 에서 '${readme_key}' 선언 패턴이 정확히 1건이어야 하는데 ${readme_match_count}건 발견됨(공허 통과 방지)"
      continue
    fi
    readme_declared=$(grep -oE "$readme_anchor" "$readme_file" | grep -oE '[0-9]+')
    readme_actual=$(readme_prose_actual_count "$readme_key")
    if [[ "$readme_declared" -ne "$readme_actual" ]]; then
      note_failure "T39-1: rules README 산문 수량이 실측과 불일치 — '${readme_key}' 선언=${readme_declared}, 실측=${readme_actual}"
    fi
    ((readme_checked++))
  done
  if ((readme_checked != readme_expected_checks)); then
    note_failure "T39-1: 검사한 선언 수가 기대와 다름 — 실제 ${readme_checked}건(기대 ${readme_expected_checks}건, 사전조건 실패로 건너뛴 항목이 있음)"
  fi

  # ---- T39-2: CLAUDE.md 배포 자산 3종(rules/·agents/·commands/) vs install.sh 상수 ----
  local claude_md_file="$REPO_ROOT/CLAUDE.md"
  local asset_index
  for ((asset_index = 0; asset_index < ${#CLAUDE_MD_ASSET_DECLARATIONS[@]}; asset_index += 2)); do
    local asset_regex="${CLAUDE_MD_ASSET_DECLARATIONS[asset_index]}"
    local asset_const="${CLAUDE_MD_ASSET_DECLARATIONS[asset_index + 1]}"
    local asset_prose_match asset_const_match asset_prose_value asset_const_value
    asset_prose_match=$(grep -cE "$asset_regex" "$claude_md_file") || true
    asset_const_match=$(grep -cE "^readonly ${asset_const}=[0-9]+" "$INSTALL_SCRIPT") || true
    asset_prose_match="${asset_prose_match:-0}"
    asset_const_match="${asset_const_match:-0}"
    if [[ "$asset_prose_match" -ne 1 || "$asset_const_match" -ne 1 ]]; then
      note_failure "T39-2: 사전조건 실패 — '${asset_const}' 대조에서 CLAUDE.md 선언 ${asset_prose_match}건, install.sh 상수 ${asset_const_match}건(정확히 1건씩이어야 함, 공허 통과 방지)"
      continue
    fi
    asset_prose_value=$(grep -oE "$asset_regex" "$claude_md_file" | grep -oE '[0-9]+')
    asset_const_value=$(grep -oE "^readonly ${asset_const}=[0-9]+" "$INSTALL_SCRIPT" | grep -oE '[0-9]+$')
    if [[ "$asset_prose_value" -ne "$asset_const_value" ]]; then
      note_failure "T39-2: CLAUDE.md 배포 자산 수량이 실측과 불일치 — ${asset_const} 선언=${asset_prose_value}, install.sh 상수=${asset_const_value}"
    fi
  done

  # ---- T39-3: rules/react/patterns.md 의 react-native "(N files: …)" vs 실측 ----
  local patterns_file="$REPO_ROOT/rules/react/patterns.md"
  local rn_anchor='\([0-9]+ files: coding-style'
  local rn_match_count
  rn_match_count=$(grep -cE "$rn_anchor" "$patterns_file") || true
  rn_match_count="${rn_match_count:-0}"
  if [[ "$rn_match_count" -ne 1 ]]; then
    note_failure "T39-3: 사전조건 실패 — rules/react/patterns.md 에서 react-native 파일 수 선언 패턴이 정확히 1건이어야 하는데 ${rn_match_count}건 발견됨(공허 통과 방지)"
  else
    local rn_declared rn_actual
    rn_declared=$(grep -oE "$rn_anchor" "$patterns_file" | grep -oE '[0-9]+')
    rn_actual=$(find "$REPO_ROOT/rules/react-native" -maxdepth 1 -type f 2> /dev/null | wc -l | tr -d ' ')
    if [[ "$rn_declared" -ne "$rn_actual" ]]; then
      note_failure "T39-3: react-native 파일 수 산문이 실측과 불일치 — 선언=${rn_declared}, 실측=${rn_actual}"
    fi
  fi

  # ---- T39-4: 배포 트리(rules/·agents/·commands/)의 인용 수 ≤ 래칫 ----
  local line_citation_pattern='[A-Za-z0-9_/.-]+\.(md|sh|py|tsv|json|html|txt):[0-9]+'
  local deployed_citation_count
  deployed_citation_count=$(grep -rhoE "$line_citation_pattern" \
    "$REPO_ROOT/rules" "$REPO_ROOT/agents" "$REPO_ROOT/commands" 2> /dev/null \
    | wc -l | tr -d ' ')
  if ((deployed_citation_count > LINE_CITATION_RATCHET_DEPLOYED)); then
    note_failure "T39-4: 배포 트리의 줄 번호 인용 수가 상한을 넘음 — 실제 ${deployed_citation_count}건(상한 ${LINE_CITATION_RATCHET_DEPLOYED}건)"
  fi

  # ---- T39-5: tests/run.sh 자신의 같은 인용 수 ≤ 래칫 + 배포 트리 "currently line" 0건 ----
  local suite_citation_count
  suite_citation_count=$(grep -oE "$line_citation_pattern" "$REPO_ROOT/tests/run.sh" | wc -l | tr -d ' ')
  if ((suite_citation_count > LINE_CITATION_RATCHET_SUITE)); then
    note_failure "T39-5: tests run.sh 의 줄 번호 인용 수가 상한을 넘음 — 실제 ${suite_citation_count}건(상한 ${LINE_CITATION_RATCHET_SUITE}건)"
  fi
  local drift_prone_citation_pattern='currently (line|lines|around lines) [0-9]+(-[0-9]+)?|currently lines [0-9]+ and [0-9]+'
  local drift_prone_citation_count
  drift_prone_citation_count=$(grep -rhoE "$drift_prone_citation_pattern" \
    "$REPO_ROOT/rules" "$REPO_ROOT/agents" "$REPO_ROOT/commands" 2> /dev/null \
    | wc -l | tr -d ' ')
  if ((drift_prone_citation_count != 0)); then
    note_failure "T39-5: 배포 트리에 currently line 형태 인용이 남음 — ${drift_prone_citation_count}건(0건이어야 함)"
  fi

  finish_group "$test_name"
}

# T38(§21-7 항목 1+2+3+4, 설계 docs/prps/rules-docs-sync.md §5-3) 데이터 모델 —
# (상대경로, 계약 토큰) 쌍의 평탄 배열. bash 3.2 에 declare -A 가 없어 위치 기반으로
# 순회한다(짝수 인덱스=경로, 홀수 인덱스=토큰). 항목 1(rules 밖 5) → 항목 2(rules/python
# 5, 존재 쪽만 — 부재 쪽은 UPSTREAM_PYTEST_TOKENS 가 따로 맡는다) → 항목 3(react/testing.md
# 미잠금 2성분) → 항목 4(잠기지 않는 성분 3) 순서로 이어붙였다. 아래 함수의 case 문이
# 경로 패턴으로 T38-1(rules/python/*)·T38-3(rules 밖)·T38-4(그 외)를 가른다 — 인덱스가
# 아니라 경로로 분류하므로 이 배열의 등재 순서 자체는 판정에 영향을 주지 않는다.
#
# 검수 1회차 HIGH 반영 — 세 토큰(prp-commit.md · react/testing.md·react/patterns.md 의
# skills 토큰)이 이미 벤더링 커밋 `5f9552f` 에 있어 되돌림을 못 무는 결함이 있었다
# (재현: `git show 5f9552f:<경로> | grep -qF -- '<토큰>'`). 국소 패치가 실제로 새로
# 도입한 문구로 세 토큰을 바꿨다. 재검증 중 네 번째 결함도 찾았다 —
# `rules/common/coding-style.md` 는 최초 반입 `602e377` 이후 이 저장소 안에서 파일
# 전체가 단 한 번도 바뀐 적이 없어, 그 파일에서 고르는 어떤 문구도 `5f9552f` 대조로는
# 되돌림을 구분하지 못한다. 그 항목은 표에서 뺐다 — T28-4 만 그 파일을 계속 잠근다
# (NOTICE.md §5 는 그 성분을 잠기지 않는 성분으로 되돌렸다).
readonly PATCH_CONTRACT_PAIRS=(
  "agents/code-reviewer.md"               "재검수 모드"
  "commands/code-review.md"               "VALIDATE (light)"
  "commands/prp-commit.md"                "Message style — applies to every convention above"
  "commands/prp-implement.md"             "Committed docs are not archived"
  "commands/prp-plan.md"                  "caller specifies an output"
  "rules/python/coding-style.md"          "Standard Library First"
  "rules/python/hooks.md"                 "Entry Points Always Exit 0"
  "rules/python/patterns.md"              "Pure Modules vs. I/O Modules"
  "rules/python/security.md"              "argv List, Never a Shell"
  "rules/python/testing.md"               "Use stdlib"
  "rules/react/testing.md"                "CRA itself is deprecated"
  "rules/react/testing.md"                "see its \`skills/react-testing/SKILL.md\`"
  "rules/common/development-workflow.md"  "skip steps whose tool"
  "rules/react/patterns.md"               "see its \`skills/react-patterns/SKILL.md\`"
  "rules/common/performance.md"           "no fixed thinking budget is reserved up front"
)

# T38-2 전용 — rules/python/testing.md 하나가 상류 pytest 관례로 되돌아왔을 때 나타나는
# 리터럴(D3 — 되돌림 리터럴을 지목할 근거가 있는 파일은 이 파일 하나다). 아래 네 토큰
# 모두 지금 rules/python/ 전체에서 0건이다(재현: grep -rcF '<토큰>' rules/python/).
readonly UPSTREAM_PYTEST_TOKENS=(
  "pytest.fixture"
  "@pytest.mark"
  "import pytest"
  "conftest.py"
)

# T38(§21-7 항목 1+2+3+4, 설계 §4 「묶음 3」) — NOTICE.md §5 커버리지 표의 미커버 11행과
# 「잠기지 않는 성분」 3건, 합쳐서 15개 (경로, 계약 토큰) 성분을 닫는다. 계약 토큰은
# 재동기화가 그 로컬 패치를 되돌리면 사라지거나(존재 쪽), 상류 관례가 되돌아오면
# 나타나는(부재 쪽) 리터럴이다.
#
# 기제: 세 부류다 — (a) PATCH_CONTRACT_PAIRS 표 구동 존재 검사(T38-1·T38-3·T38-4, 경로
# 패턴으로 메시지만 가른다) (b) rules/python/testing.md 한 파일에서만 상류 pytest 관례의
# 부재를 보는 UPSTREAM_PYTEST_TOKENS 검사(T38-2, D3 — 되돌아왔을 때 나타날 리터럴을
# 지목할 근거가 있는 파일은 이 파일 하나다) (c) 표 길이·순회 쌍 수 대조(T38-5).
#
# 그 기제에서 따라오는 한계: (a)는 같은 뜻을 다른 낱말로 되돌리는 편집이나, 토큰만
# 남기고 주변 문장의 의미를 뒤집는 편집을 보지 못한다(T28 헤더와 같은 한계). (b)는 그
# 네 토큰 밖의 다른 상류 pytest 관용구(예: fixture 없는 parametrize 데코레이터)가
# 들어와도 못 본다.
#
# 표 구동 선택에서 따라오는 한계(D2·R3, §12 원문과 같은 모양) — 원장의 변조행 5건은 각
# 메시지 분기의 루프 경로 하나씩만 문다. 표의 나머지 항목이 개별로 판정에 기여했다는
# 증거는 이 설계가 내지 않는다. T38-5 의 계수 단언은 「루프가 표 길이만큼 돌았다」까지고,
# UPSTREAM_PYTEST_TOKENS 배열에는 같은 형태의 계수 단언이 없다 — 그 배열이 비어도 이
# 그룹 자신은 그 퇴행을 스스로 잡지 못한다(T39 헤더가 README_PROSE_DECLARATIONS 에 대해
# 적은 것과 같은 모양). 그 방어는 이 그룹이 아니라 원장 판정 쌍(K6)이 맡는다.
#
# 위양성 처방(R1, T31 헤더와 같은 위험) — 정당한 문구 다듬기가 이 토큰 중 하나를 건드려
# 이 그룹이 빨개지면, 고칠 것은 그 문단이 아니라 위 두 배열의 토큰 목록이다(T32-7 이
# 경고한 「빨개지면 검사를 지운다」 회피).
#
# 비망라 예시 — 이 그룹이 보지 않는 것: 위 15성분 밖의 「패치 요지」 서술 자체(상류
# 재대조 없음 — 네트워크를 쓰지 않는다) · rules/python/testing.md 밖 4파일의 상류 관례
# 부재(D3 — 그 파일들은 존재 단언만 있다) · 숫자·구조 형태의 문서 표류.
#
# 전수 증명이 아니다.
test_vendor_patch_contract_tokens() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T38"
  local test_desc="벤더링 로컬 패치 계약 토큰 — rules/python 존재(T38-1)·상류 pytest 부재(T38-2)·rules 밖 존재(T38-3)·미잠금 성분(T38-4)·쌍 수 대조(T38-5)"
  log_test_name "$test_name" "$test_desc"

  # ---- T38-1·T38-3·T38-4: PATCH_CONTRACT_PAIRS 표 구동 존재 검사(경로로 메시지를 가른다) ----
  local pair_expected_checks=$((${#PATCH_CONTRACT_PAIRS[@]} / 2))
  local pair_checked=0
  local pair_index=0
  if (( ${#PATCH_CONTRACT_PAIRS[@]} % 2 != 0 )); then
    note_failure "T38-5: PATCH_CONTRACT_PAIRS 배열 길이가 홀수(${#PATCH_CONTRACT_PAIRS[@]}) — 마지막 짝이 조용히 빠질 수 있음"
  fi
  while ((pair_index < ${#PATCH_CONTRACT_PAIRS[@]})); do
    local rel_path="${PATCH_CONTRACT_PAIRS[pair_index]}"
    local expect_local_token="${PATCH_CONTRACT_PAIRS[pair_index + 1]}"
    if ! grep -qF -- "$expect_local_token" "$REPO_ROOT/$rel_path" 2> /dev/null; then
      case "$rel_path" in
        rules/python/*)
          note_failure "T38-1: rules python 로컬 패치 계약 토큰 부재 — $rel_path 에 '$expect_local_token' 없음"
          ;;
        agents/* | commands/*)
          # 검수 1회차 LOW 반영 — 리터럴 agents/code-reviewer.md 하나만 매치하던 것을
          # agents/* 로 넓혔다. 지금 배열엔 agents/ 항목이 그 파일 하나뿐이라 동작은
          # 그대로다 — 나중에 다른 agents/*.md 가 추가돼도 조용히 T38-4 로 새지 않는다.
          note_failure "T38-3: rules 밖 벤더링 파일의 로컬 패치 토큰 부재 — $rel_path 에 '$expect_local_token' 없음"
          ;;
        *)
          note_failure "T38-4: 미잠금 성분 계약 토큰 부재 — $rel_path 에 '$expect_local_token' 없음"
          ;;
      esac
    fi
    ((pair_checked++)) || true
    pair_index=$((pair_index + 2))
  done
  if ((pair_checked != pair_expected_checks)); then
    note_failure "T38-5: 검사한 계약 토큰 쌍 수가 표 길이와 불일치 — 실제 ${pair_checked}쌍(기대 ${pair_expected_checks}쌍)"
  fi

  # ---- T38-2: rules/python/testing.md 에 상류 pytest 관례가 재도입되지 않았는가(D3) ----
  # 검수 1회차 MEDIUM 반영 — 인덱스 기반으로 순회한다("${ARR[@]}" 전개를 쓰지 않는다).
  # bash 3.2 는 nounset 아래에서 빈 배열의 "${ARR[@]}" 전개를 unbound variable 로
  # 처리해 스위트 전체를 중단시킨다(PATCH_CONTRACT_PAIRS 와 같은 관용구로 통일해 없앴다).
  local pytest_index=0
  while ((pytest_index < ${#UPSTREAM_PYTEST_TOKENS[@]})); do
    local pytest_token="${UPSTREAM_PYTEST_TOKENS[pytest_index]}"
    if grep -qF -- "$pytest_token" "$REPO_ROOT/rules/python/testing.md" 2> /dev/null; then
      note_failure "T38-2: rules python 에 상류 pytest 관례가 재도입됨 — rules/python/testing.md 에 '$pytest_token' 있음"
    fi
    pytest_index=$((pytest_index + 1))
  done

  finish_group "$test_name"
}

# T40(신설, docs/prps/dashboard-into-hub.md HD2·HD10·HD11·HD12 — M1): 허브 진행 기록
# 규칙 채널(hub/rules/dashboard-recording.md → ~/.claude/rules/hub/) 배포·제거·문서 정합성.
# T25-2xx 를 쓰지 않는다(그 번호대는 다른 워크트리가 예약했다, §13) — 이 그룹이 그
# 대신이다. 하위 검증 T40-1~T40-15 — T40-12a~d 는 hub-uninstall-symlink-precondition
# (N7·N8), T40-13~15 는 dashboard-into-hub M2 다.
#
# 한계(비망라) — 이 그룹의 각 서브체크는 fail-fast(record_failure + return 1)라 한 실행에
# 하나만 발화한다. 실측한 범위는 grep/find 기반 정적 검사와 샌드박스 HOME 1회 설치·
# 제거뿐이다 — 동시에 여러 결함이 섞인 실전 상황, 또는 정적 검사가 못 보는 형태(예:
# 조건부로만 깨지는 경로)까지 보증하지는 않는다. 전수 증명이 아니다.
test_hub_dashboard_channel() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T40"
  local test_desc="허브 진행 기록 규칙 채널 배포·제거·문서 정합성 (T40-1~T40-15)"
  log_test_name "$test_name" "$test_desc"

  local hub_install_file_t40="$REPO_ROOT/hub/install.sh"
  local hub_rule_source_file_t40="$REPO_ROOT/hub/rules/dashboard-recording.md"
  local hub_readme_file_t40="$REPO_ROOT/hub/README.md"
  local harness_update_file_t40="$REPO_ROOT/commands/harness-update.md"

  # 순서 참고(검수 1회차 F6) — 정적 검사(T40-3·T40-4·T40-6·T40-5)를 실제 설치를 부르는
  # 행동 검사(T40-1·T40-2·T40-9·T40-10)보다 앞에 둔다. 뒤쪽 검사들은 서로 다른 결함을
  # 겨냥한 변조라도 "설치·제거가 예상대로 끝난다"는 같은 전제를 공유해, 정적 검사를
  # 뒤에 두면 행동 검사용 변조가 그 전제를 깨서 앞선 정적 검사가 먼저 발화해버린다
  # (실측: 규칙 제거 호출을 지우는 변조가 T40-3 대신 T40-2 에서 잡혔고, 규칙 파일에
  # paths: 를 주입하는 변조가 바이트 수도 늘려 T40-6 대신 T40-5 에서 잡혔다).

  # T40-3: perform_uninstall 본문에서 uninstall-statusline 호출 < 규칙 제거 < bin/ 삭제
  # 순서다(HD11 R2 — 규칙을 bin/ 보다 먼저 지운다. §11.6: bin/ 을 먼저 지우면 기록기 없는
  # 지침이 모든 세션에 남는, 가장 되돌리기 어려운 상태가 된다).
  local perform_uninstall_body_t40
  perform_uninstall_body_t40=$(awk '/^perform_uninstall\(\) \{/{flag=1; next} flag && /^\}/{exit} flag{print}' "$hub_install_file_t40")
  if [[ -z "$perform_uninstall_body_t40" ]]; then
    record_failure "$test_name" "T40-3: perform_uninstall() 범위 추출 실패 — 앵커가 깨졌다"
    return 1
  fi
  local statusline_line_t40 rule_removal_line_t40 bin_rm_line_t40
  statusline_line_t40=$(grep -n 'uninstall-statusline' <<< "$perform_uninstall_body_t40" | tail -1 | cut -d: -f1)
  rule_removal_line_t40=$(grep -n 'remove_managed_rule_files' <<< "$perform_uninstall_body_t40" | head -1 | cut -d: -f1)
  bin_rm_line_t40=$(grep -n 'rm -rf "\$TARGET_BIN_DIR"' <<< "$perform_uninstall_body_t40" | head -1 | cut -d: -f1)
  if [[ -z "$statusline_line_t40" || -z "$rule_removal_line_t40" || -z "$bin_rm_line_t40" ]]; then
    record_failure "$test_name" "T40-3: perform_uninstall() 순서 앵커(statusLine·규칙 제거·bin 삭제) 추출 실패"
    return 1
  fi
  if ! [[ "$statusline_line_t40" -lt "$rule_removal_line_t40" && "$rule_removal_line_t40" -lt "$bin_rm_line_t40" ]]; then
    record_failure "$test_name" "T40-3: perform_uninstall() 순서(statusLine 제거 < 규칙 제거 < bin/ 삭제)가 어긋남"
    return 1
  fi

  # T40-4: HUB_RULE_FILE_COUNT 가 hub/rules/ 의 실제 .md 파일 수와 같고, hub/README.md
  # 「파일 배치」가 그 경로를 고지한다.
  local declared_rule_count_t40 actual_rule_count_t40
  declared_rule_count_t40=$(grep -oE '^readonly HUB_RULE_FILE_COUNT=[0-9]+' "$hub_install_file_t40" | grep -oE '[0-9]+$')
  actual_rule_count_t40=$(find "$REPO_ROOT/hub/rules" -maxdepth 1 -type f -name '*.md' | wc -l | tr -d ' ')
  if [[ "$declared_rule_count_t40" -ne "$actual_rule_count_t40" ]]; then
    record_failure "$test_name" "T40-4: HUB_RULE_FILE_COUNT=$declared_rule_count_t40, 실제 hub/rules/*.md 파일 수=$actual_rule_count_t40"
    return 1
  fi
  if ! grep -qF 'rules/hub/' "$hub_readme_file_t40"; then
    record_failure "$test_name" "T40-4: hub/README.md 「파일 배치」에 규칙 경로(rules/hub/) 고지가 없음"
    return 1
  fi

  # T40-6: 규칙 파일에 paths: frontmatter 가 없고(상시 로드 — 조건부 로드로 전락하면 안
  # 된다) dashboard_enabled·.claude/settings.local.json 리터럴이 있다(RL10 스위치 계약).
  # T40-5(바이트 예산) 보다 앞에 둔다 — paths: 주입 변조가 바이트 수도 함께 늘리기 때문이다.
  if grep -qE '^paths:' "$hub_rule_source_file_t40"; then
    record_failure "$test_name" "T40-6: hub/rules/dashboard-recording.md 에 paths: frontmatter 가 있음(조건부 로드로 전락)"
    return 1
  fi
  if ! grep -qF 'dashboard_enabled' "$hub_rule_source_file_t40"; then
    record_failure "$test_name" "T40-6: hub/rules/dashboard-recording.md 에 dashboard_enabled 리터럴이 없음"
    return 1
  fi
  if ! grep -qF '.claude/settings.local.json' "$hub_rule_source_file_t40"; then
    record_failure "$test_name" "T40-6: hub/rules/dashboard-recording.md 에 .claude/settings.local.json 리터럴이 없음"
    return 1
  fi

  # T40-5(결정 ST8 승계, 옛 T22-163): 규칙 파일 바이트 수가 예산 래칫을 넘지 않는다(래칫 —
  # 줄어드는 것은 자유, 늘면 실패).
  local rule_file_actual_bytes_t40
  rule_file_actual_bytes_t40=$(wc -c < "$hub_rule_source_file_t40" | tr -d ' ')
  if [[ "$rule_file_actual_bytes_t40" -gt "$HUB_DASHBOARD_RULE_BUDGET_BYTES" ]]; then
    record_failure "$test_name" "T40-5: hub/rules/dashboard-recording.md 실측 ${rule_file_actual_bytes_t40}B > 예산 ${HUB_DASHBOARD_RULE_BUDGET_BYTES}B"
    return 1
  fi

  # T40-13~15(신설, docs/prps/dashboard-into-hub.md M2 — HD5·HD6·HD8·HD15): 허브가 세션별
  # JSONL 을 직접 읽고 요청 시점에 렌더한다 — HTML 을 만들거나 읽는 경로가 없다.
  local hub_dashboard_log_file_t40="$REPO_ROOT/hub/bin/hub_dashboard_log.py"
  local hub_project_file_t40="$REPO_ROOT/hub/bin/hub_project.py"
  local hub_collect_file_t40="$REPO_ROOT/hub/bin/hub_collect.py"
  local hub_server_file_t40="$REPO_ROOT/hub/bin/hub_server.py"
  local hub_parse_file_t40="$REPO_ROOT/hub/bin/hub_parse.py"

  # T40-13: 기록기·수집이 HTML 을 만들거나 읽지 않는다.
  if grep -qF 'import hub_dashboard_render' "$hub_dashboard_log_file_t40"; then
    record_failure "$test_name" "T40-13: hub_dashboard_log.py 가 여전히 hub_dashboard_render 를 임포트함(HD15 위반 — HTML 재발행 경로가 남았다)"
    return 1
  fi
  if grep -qF 'html_path' "$hub_dashboard_log_file_t40"; then
    record_failure "$test_name" "T40-13: hub_dashboard_log.py 에 html_path 가 남아 있음(HD8 위반)"
    return 1
  fi
  local read_session_dashboard_snapshots_body_t40
  read_session_dashboard_snapshots_body_t40=$(awk '/^def read_session_dashboard_snapshots\(/{flag=1; next} flag && /^def /{exit} flag{print}' "$hub_collect_file_t40")
  if ! grep -qF 'parse_dashboard_jsonl(' <<< "$read_session_dashboard_snapshots_body_t40"; then
    record_failure "$test_name" "T40-13: read_session_dashboard_snapshots() 가 parse_dashboard_jsonl( 을 부르지 않음(HD6 위반)"
    return 1
  fi
  if grep -qF 'parse_dashboard_html' "$hub_collect_file_t40"; then
    record_failure "$test_name" "T40-13: hub_collect.py 에 parse_dashboard_html 이 남아 있음(HD7 위반 — 레거시 HTML 파서 호출)"
    return 1
  fi
  if ! grep -qF -- '\.jsonl\Z' "$hub_project_file_t40"; then
    record_failure "$test_name" "T40-13: hub_project.py 의 SESSION_DASHBOARD_FILE_NAME_PATTERN 이 더 이상 \\.jsonl\\Z 로 끝나지 않음(HD6 위반)"
    return 1
  fi

  # T40-14: 서버가 요청 시점에 JSONL 을 렌더해 서빙한다. hub_parse.py 는 HTML 정규식
  # 파서를 더 이상 갖지 않는다.
  local serve_project_dashboard_body_t40
  serve_project_dashboard_body_t40=$(awk '/^    def _serve_project_dashboard\(/{flag=1; next} flag && /^    def /{exit} flag{print}' "$hub_server_file_t40")
  if ! grep -qF 'render_from_events(' <<< "$serve_project_dashboard_body_t40"; then
    record_failure "$test_name" "T40-14: _serve_project_dashboard() 가 render_from_events( 를 부르지 않음(HD5 위반)"
    return 1
  fi
  if ! grep -qF 'nosniff' <<< "$serve_project_dashboard_body_t40"; then
    record_failure "$test_name" "T40-14: _serve_project_dashboard() 응답에 nosniff 헤더가 없음"
    return 1
  fi
  if grep -qF '_STEP_LINE_PATTERN' "$hub_parse_file_t40"; then
    record_failure "$test_name" "T40-14: hub_parse.py 에 _STEP_LINE_PATTERN 이 남아 있음(HD6 위반 — HTML 정규식 파서가 아직 있다)"
    return 1
  fi
  if grep -qF 'parse_dashboard_html' "$hub_parse_file_t40"; then
    record_failure "$test_name" "T40-14: hub_parse.py 에 parse_dashboard_html 이 남아 있음(HD6 위반)"
    return 1
  fi

  # T40-15: 작업 시작 시각의 출처는 JSONL 첫 줄(init)의 time_ms 다 — 수집이 덮어쓰지 않는다.
  if ! grep -qF 'task_started_at_ms=' "$hub_parse_file_t40"; then
    record_failure "$test_name" "T40-15: hub_parse.py 에 task_started_at_ms= 대입이 없음(HD8 위반 — snapshot_from_events 가 init 시각을 채우지 않는다)"
    return 1
  fi
  if grep -qF 'task_started_at_ms=' <<< "$read_session_dashboard_snapshots_body_t40"; then
    record_failure "$test_name" "T40-15: read_session_dashboard_snapshots() 가 task_started_at_ms= 를 덮어씀(HD8 위반 — 수집이 채우면 안 된다)"
    return 1
  fi

  # T40-1: 샌드박스 HOME 으로 hub/install.sh 를 실행하면 규칙 파일이 배포되고, bin/ 파일
  # 수는 여전히 HUB_FILE_COUNT 와 일치한다(규칙 채널 추가가 bin/ 채널을 깨지 않는다).
  local sandbox_t40_install
  sandbox_t40_install=$(mktemp -d)
  register_cleanup_path "$sandbox_t40_install"
  HOME="$sandbox_t40_install" "$hub_install_file_t40" > /dev/null 2>&1
  if [[ ! -f "$sandbox_t40_install/.claude/rules/hub/dashboard-recording.md" ]]; then
    record_failure "$test_name" "T40-1: 허브 설치 후 \$HOME/.claude/rules/hub/dashboard-recording.md 미발견"
    return 1
  fi
  local installed_bin_count_t40 declared_bin_count_t40
  installed_bin_count_t40=$(find "$sandbox_t40_install/.claude/hub/bin" -maxdepth 1 -type f | wc -l | tr -d ' ')
  declared_bin_count_t40=$(grep -oE '^readonly HUB_FILE_COUNT=[0-9]+' "$hub_install_file_t40" | grep -oE '[0-9]+$')
  if [[ "$installed_bin_count_t40" -ne "$declared_bin_count_t40" ]]; then
    record_failure "$test_name" "T40-1: bin/ 설치 파일 수=$installed_bin_count_t40(기대 $declared_bin_count_t40)"
    return 1
  fi

  # T40-2: --uninstall 은 배포한 규칙 파일만 지운다 — 같은 디렉터리의 미끼 파일(우리
  # 소유가 아닌 파일)은 남겨야 한다(소유권 원칙, rm -rf 금지).
  echo "미끼" > "$sandbox_t40_install/.claude/rules/hub/decoy.md"
  HOME="$sandbox_t40_install" "$hub_install_file_t40" --uninstall > /dev/null 2>&1
  if [[ -e "$sandbox_t40_install/.claude/rules/hub/dashboard-recording.md" ]]; then
    record_failure "$test_name" "T40-2: --uninstall 이후에도 dashboard-recording.md 가 남아 있음"
    return 1
  fi
  if [[ ! -f "$sandbox_t40_install/.claude/rules/hub/decoy.md" ]]; then
    record_failure "$test_name" "T40-2: --uninstall 이 배포하지 않은 미끼 파일(decoy.md)까지 지움(소유권 원칙 위반)"
    return 1
  fi

  # T40-9(신설, 검수 1회차 F12 — 사용자가 고친 규칙 파일 보호 회귀 가드): 설치 → 규칙
  # 파일을 손으로 고침 → --force 없이 재설치하면 exit != 0 이고 "수정된 파일이" 경고가
  # 나오며, 사용자가 고친 내용이 그대로 남는다(bin/ 채널의 기존 보호와 대칭).
  local sandbox_t40_modified
  sandbox_t40_modified=$(mktemp -d)
  register_cleanup_path "$sandbox_t40_modified"
  HOME="$sandbox_t40_modified" "$hub_install_file_t40" > /dev/null 2>&1
  echo "# 사용자가 직접 수정함" >> "$sandbox_t40_modified/.claude/rules/hub/dashboard-recording.md"
  local modified_rule_content_before_t40
  modified_rule_content_before_t40=$(cat "$sandbox_t40_modified/.claude/rules/hub/dashboard-recording.md")
  local reinstall_output_t40 reinstall_exit_t40=0
  reinstall_output_t40=$(HOME="$sandbox_t40_modified" "$hub_install_file_t40" 2>&1) || reinstall_exit_t40=$?
  if [[ "$reinstall_exit_t40" -eq 0 ]]; then
    record_failure "$test_name" "T40-9: 규칙 파일을 수정한 뒤 --force 없이 재설치했는데 exit 0(수정 보호 회귀)"
    return 1
  fi
  if [[ "$reinstall_output_t40" != *"수정된 파일이"* ]]; then
    record_failure "$test_name" "T40-9: 재설치 경고에 '수정된 파일이' 문구가 없음"
    return 1
  fi
  if [[ "$(cat "$sandbox_t40_modified/.claude/rules/hub/dashboard-recording.md")" != "$modified_rule_content_before_t40" ]]; then
    record_failure "$test_name" "T40-9: --force 없는 재설치가 사용자가 수정한 규칙 파일을 덮어씀"
    return 1
  fi

  # T40-10(신설, 검수 1회차 F7 — 규칙 채널 심링크 거부 회귀 가드): 배포 파일 자리가
  # 심볼릭 링크면 --force 를 줘도 설치가 exit != 0 이고 링크 대상 내용이 그대로 남는다
  # (N3 의 bin/ 채널 방어와 대칭, check_no_symlink_rule_targets).
  local sandbox_t40_symlink
  sandbox_t40_symlink=$(mktemp -d)
  register_cleanup_path "$sandbox_t40_symlink"
  HOME="$sandbox_t40_symlink" "$hub_install_file_t40" > /dev/null 2>&1
  echo "사용자 dotfile 내용" > "$sandbox_t40_symlink/attacker.md"
  rm -f "$sandbox_t40_symlink/.claude/rules/hub/dashboard-recording.md"
  ln -s "$sandbox_t40_symlink/attacker.md" "$sandbox_t40_symlink/.claude/rules/hub/dashboard-recording.md"
  local symlink_exit_t40=0
  HOME="$sandbox_t40_symlink" "$hub_install_file_t40" --force > /dev/null 2>&1 || symlink_exit_t40=$?
  if [[ "$symlink_exit_t40" -eq 0 ]]; then
    record_failure "$test_name" "T40-10: 배포 파일 자리가 심볼릭 링크인데 --force 설치가 exit 0(심링크 관통 회귀)"
    return 1
  fi
  if [[ "$(cat "$sandbox_t40_symlink/attacker.md")" != "사용자 dotfile 내용" ]]; then
    record_failure "$test_name" "T40-10: 심볼릭 링크 대상 파일의 내용이 변경됨(관통 발생)"
    return 1
  fi

  # T40-11(신설, 검수 2회차 N4 — 제거 경로의 심링크 관통 회귀 가드. 검수 3회차 N7 뒤
  # 재서술 — hub-uninstall-symlink-precondition.md §1-(e)): 배포된 규칙 파일 자리가
  # 심볼릭 링크면 --uninstall 은 아무것도 바꾸지 않고 실패한다(PRP §11.6 「가장 나쁜
  # 잔존 상태」 방지 — 사전조건이 없으면 rm -f 가 그 심볼릭 링크만(원본은 남긴 채) 지우고
  # bin/ 까지 마저 지운 뒤 exit 0 [DONE] 으로 끝난다 — 사용자가 만든 링크를 사용자에게
  # 묻지 않고 지우는 소유권 위반이다).
  local sandbox_t40_uninstall_symlink
  sandbox_t40_uninstall_symlink=$(mktemp -d)
  register_cleanup_path "$sandbox_t40_uninstall_symlink"
  HOME="$sandbox_t40_uninstall_symlink" "$hub_install_file_t40" > /dev/null 2>&1
  echo "사용자 dotfile 내용" > "$sandbox_t40_uninstall_symlink/attacker_uninstall.md"
  rm -f "$sandbox_t40_uninstall_symlink/.claude/rules/hub/dashboard-recording.md"
  ln -s "$sandbox_t40_uninstall_symlink/attacker_uninstall.md" \
    "$sandbox_t40_uninstall_symlink/.claude/rules/hub/dashboard-recording.md"
  local uninstall_symlink_output_t40 uninstall_symlink_exit_t40=0
  uninstall_symlink_output_t40=$(HOME="$sandbox_t40_uninstall_symlink" "$hub_install_file_t40" --uninstall 2>&1) || uninstall_symlink_exit_t40=$?
  if [[ "$uninstall_symlink_exit_t40" -eq 0 ]]; then
    record_failure "$test_name" "T40-11: 규칙 파일이 심볼릭 링크인데 --uninstall 이 exit 0(관통·잔존 회귀)"
    return 1
  fi
  if [[ ! -d "$sandbox_t40_uninstall_symlink/.claude/hub/bin" ]]; then
    record_failure "$test_name" "T40-11: --uninstall 사전조건 실패에도 bin/ 이 지워짐(부분 제거 회귀)"
    return 1
  fi
  if [[ "$(cat "$sandbox_t40_uninstall_symlink/attacker_uninstall.md")" != "사용자 dotfile 내용" ]]; then
    record_failure "$test_name" "T40-11: --uninstall 이 심볼릭 링크 대상 파일의 내용을 변경함(관통 발생)"
    return 1
  fi
  if [[ "$uninstall_symlink_output_t40" != *"심볼릭 링크입니다"* ]]; then
    record_failure "$test_name" "T40-11: --uninstall 실패 출력에 '심볼릭 링크입니다' 문구가 없음"
    return 1
  fi
  if [[ "$uninstall_symlink_output_t40" != *"링크만 지운 뒤 다시 실행하십시오"* ]]; then
    record_failure "$test_name" "T40-11: --uninstall 실패 출력에 거부 A 안내(링크만 지운 뒤 다시 실행)가 없음"
    return 1
  fi
  if [[ "$uninstall_symlink_output_t40" != *"원본 파일은 건드리지 마십시오"* ]]; then
    record_failure "$test_name" "T40-11: --uninstall 실패 출력에 거부 A 안내(원본 파일은 그대로 두라)가 없음"
    return 1
  fi

  # T40-11 dry-run(검수 2회차 P3-b·E8④ — log_uninstall_plan 자신의 첫 줄 사전조건 호출이
  # 따로 빠지는 결함은 실제 실행 경로만 보는 위 단언들로는 드러나지 않는다. 같은 심링크
  # 상태에서 --uninstall --dry-run 도 거부되는지 별도로 확인한다).
  local uninstall_symlink_dryrun_exit_t40=0
  HOME="$sandbox_t40_uninstall_symlink" "$hub_install_file_t40" --uninstall --dry-run > /dev/null 2>&1 \
    || uninstall_symlink_dryrun_exit_t40=$?
  if [[ "$uninstall_symlink_dryrun_exit_t40" -eq 0 ]]; then
    record_failure "$test_name" "T40-11: 심볼릭 링크 상태에서 --uninstall --dry-run 이 exit 0(계획 경로가 사전조건을 건너뜀)"
    return 1
  fi

  # (안내 수행 — 거부 A) 링크만 지운다. 원본(attacker_uninstall.md)은 그대로 둔다.
  rm -f "$sandbox_t40_uninstall_symlink/.claude/rules/hub/dashboard-recording.md"

  # T40-11 재실행(UL2 계약 — 거부 A 쪽): 안내대로 링크만 지우면 재실행은 반드시 통과하고
  # 원본은 그대로 남는다.
  local uninstall_symlink_retry_exit_t40=0
  HOME="$sandbox_t40_uninstall_symlink" "$hub_install_file_t40" --uninstall > /dev/null 2>&1 \
    || uninstall_symlink_retry_exit_t40=$?
  if [[ "$uninstall_symlink_retry_exit_t40" -ne 0 ]]; then
    record_failure "$test_name" "T40-11: 링크만 지우고 재실행했는데 --uninstall 이 exit ${uninstall_symlink_retry_exit_t40}(안내 이행 후 영구 거부)"
    return 1
  fi
  if [[ ! -f "$sandbox_t40_uninstall_symlink/attacker_uninstall.md" ]]; then
    record_failure "$test_name" "T40-11: 링크만 지운 뒤 재실행했더니 원본 파일(attacker_uninstall.md)까지 사라짐"
    return 1
  fi

  # T40-12(신설, 검수 3회차 N7·N8 — docs/prps/hub-uninstall-symlink-precondition.md
  # UL1~UL4): 제거 사전조건이 「배포 자리가 심링크」이거나 「부모가 심링크이고 그 너머에
  # 규칙 파일이 실제로 있음」일 때만 거부하고(UL1), 안내대로 한 뒤 재실행하면 반드시
  # 통과하며(UL2), 규칙 제거는 통과한 뒤에도 링크 너머를 rm·rmdir 하지 않는다(UL3 —
  # 재판정 방어선 포함, UL4)는 세 계약의 회귀 가드다. 한계(비망라) — 태우는 링크 형태는
  # 부모 링크(12a~c)·디렉터리 링크(12d) 둘이다. 파일 링크(거부 A)의 안내 문구·안내 후
  # 재실행 계약·dry-run exit 코드는 T40-11 이 맡되, dry-run **계획 줄 문구**는 보지
  # 않는다(그건 12b 가 부모 링크 시나리오에서 본다). 끊긴 링크·$HOME/.claude 자신의 링크·
  # 링크가 겹친 형태는 태우지 않는다. 전수 증명이 아니다.
  local sandbox_t40_parent_link
  sandbox_t40_parent_link=$(mktemp -d)
  register_cleanup_path "$sandbox_t40_parent_link"
  mkdir -p "$sandbox_t40_parent_link/.claude/hub/bin"
  mkdir -p "$sandbox_t40_parent_link/dotfiles_rules/hub"
  cp "$hub_rule_source_file_t40" "$sandbox_t40_parent_link/dotfiles_rules/hub/"
  ln -s "$sandbox_t40_parent_link/dotfiles_rules" "$sandbox_t40_parent_link/.claude/rules"

  # T40-12a: $HOME/.claude/rules 가 심링크이고 그 너머(hub/)에 배포 규칙 파일이 실제로
  # 있으면 --uninstall 은 아무것도 바꾸지 않고 실패한다(거부 B, UL1 ②).
  local uninstall_parent_link_output_t40 uninstall_parent_link_exit_t40=0
  uninstall_parent_link_output_t40=$(HOME="$sandbox_t40_parent_link" "$hub_install_file_t40" --uninstall 2>&1) || uninstall_parent_link_exit_t40=$?
  if [[ "$uninstall_parent_link_exit_t40" -eq 0 ]]; then
    record_failure "$test_name" "T40-12a: 부모 링크 너머에 규칙 파일이 있는데 --uninstall 이 exit 0(가장 나쁜 잔존 상태 회귀)"
    return 1
  fi
  if [[ ! -d "$sandbox_t40_parent_link/.claude/hub/bin" ]]; then
    record_failure "$test_name" "T40-12a: --uninstall 실패에도 bin/ 이 지워짐(부분 제거 회귀)"
    return 1
  fi
  if [[ ! -f "$sandbox_t40_parent_link/dotfiles_rules/hub/dashboard-recording.md" ]]; then
    record_failure "$test_name" "T40-12a: --uninstall 실패에도 링크 너머의 규칙 파일이 지워짐(링크 관통)"
    return 1
  fi
  if [[ "$uninstall_parent_link_output_t40" != *"링크 너머에 허브 규칙 파일이 남아 있습니다"* ]]; then
    record_failure "$test_name" "T40-12a: --uninstall 실패 출력에 '링크 너머에 허브 규칙 파일이 남아 있습니다' 문구가 없음"
    return 1
  fi
  if [[ "$uninstall_parent_link_output_t40" != *"그 파일만 지운 뒤 다시 실행하십시오 — 링크는 지우지 마십시오"* ]]; then
    record_failure "$test_name" "T40-12a: --uninstall 실패 출력에 거부 B 안내(그 파일만 지우고 링크는 두라)가 없음"
    return 1
  fi

  # (안내 수행) 하드코딩된 경로가 아니라 출력의 "남아 있습니다: " 뒤에 실제로 적힌 경로를
  # 읽어 지운다(검수 2회차 P1 — 안내 문구 자체가 엉뚱한 경로를 가리켜도 이 스크립트가
  # 옳은 경로를 대신 알아내 지우면 그 결함이 가려진다). 추출한 경로가 샌드박스 밖이면
  # 지우지 않고 실패로 멈춘다.
  local guided_removal_path_t40
  guided_removal_path_t40=$(sed -n 's/.*남아 있습니다: //p' <<< "$uninstall_parent_link_output_t40" | head -n 1)
  if [[ "$guided_removal_path_t40" != "$sandbox_t40_parent_link"/* ]]; then
    record_failure "$test_name" "T40-12a: 안내 문구에서 읽은 경로가 샌드박스 밖이거나 비어 있음(${guided_removal_path_t40:-빈 문자열})"
    return 1
  fi
  rm -f "$guided_removal_path_t40"

  # T40-12b: 안내대로 링크 너머의 규칙 파일만 지우고 재실행하면 반드시 통과한다(UL2 계약).
  local uninstall_parent_link_retry_output_t40 uninstall_parent_link_retry_exit_t40=0
  uninstall_parent_link_retry_output_t40=$(HOME="$sandbox_t40_parent_link" "$hub_install_file_t40" --uninstall 2>&1) || uninstall_parent_link_retry_exit_t40=$?
  if [[ "$uninstall_parent_link_retry_exit_t40" -ne 0 ]]; then
    record_failure "$test_name" "T40-12b: 안내대로 링크 너머의 규칙 파일을 지우고 다시 실행했는데 --uninstall 이 exit ${uninstall_parent_link_retry_exit_t40}(영구 거부 회귀)"
    return 1
  fi
  if [[ -d "$sandbox_t40_parent_link/.claude/hub/bin" ]]; then
    record_failure "$test_name" "T40-12b: 안내대로 재실행했는데 bin/ 이 지워지지 않음(제거 미완료)"
    return 1
  fi

  # T40-12b dry-run(검수 2회차 E8③ — log_uninstall_plan 의 통과-링크 너머 분기가 뒤집혀도
  # 실제 실행 경로만 보는 위 두 단언은 잡지 못한다). 실제 재실행이 통과를 확인한 뒤에
  # 같은 통과-링크 너머 상태에서 dry-run 도 같은 분기로 통과하는지 별도로 본다 — 재실행
  # 앞에 두면 check_uninstall_preconditions 자체가 깨지는 다른 변조(T40-12b 원장 행)가
  # 실제 재실행보다 이 dry-run 단언에 먼저 걸려 원장 토큰을 가려 버린다(T37-15 로 실측).
  # dry-run 은 무변경이라 이 위치에서도 뒤 단계(T40-12c)에 영향이 없다.
  local uninstall_parent_link_dryrun_output_t40 uninstall_parent_link_dryrun_exit_t40=0
  uninstall_parent_link_dryrun_output_t40=$(HOME="$sandbox_t40_parent_link" "$hub_install_file_t40" --uninstall --dry-run 2>&1) || uninstall_parent_link_dryrun_exit_t40=$?
  if [[ "$uninstall_parent_link_dryrun_exit_t40" -ne 0 ]]; then
    record_failure "$test_name" "T40-12b: 재실행 통과 뒤 --uninstall --dry-run 이 exit ${uninstall_parent_link_dryrun_exit_t40}(0 이어야 함 — dry-run 분기 회귀)"
    return 1
  fi
  if [[ "$uninstall_parent_link_dryrun_output_t40" != *"규칙 파일 제거 건너뜀"* ]]; then
    record_failure "$test_name" "T40-12b: --uninstall --dry-run 계획에 '규칙 파일 제거 건너뜀' 줄이 없음(dry-run 분기 회귀)"
    return 1
  fi

  # T40-12c: 통과-링크 너머 경로는 부모 링크 너머의 빈 hub/ 를 rmdir 하지 않는다(UL3 —
  # 링크 관통 0, 빈 디렉터리라도 사용자 트리 쪽은 예외 없이 그대로 둔다). T40-12b 가
  # 실행한 결과를 그대로 검사한다(재실행하지 않음).
  if [[ ! -d "$sandbox_t40_parent_link/dotfiles_rules/hub" ]]; then
    record_failure "$test_name" "T40-12c: --uninstall 이 부모 링크 너머의 빈 hub/ 디렉터리를 rmdir 함(링크 관통)"
    return 1
  fi
  if [[ ! -L "$sandbox_t40_parent_link/.claude/rules" ]]; then
    record_failure "$test_name" "T40-12c: --uninstall 뒤 .claude/rules 링크 자체가 사라짐(예상 밖 변경)"
    return 1
  fi

  # T40-12d: 사전조건 통과 뒤(하위 명령 실행 중) 링크 너머에 규칙 파일이 생기면, 규칙
  # 제거의 재판정 방어선(UL4)이 이를 잡아 bin/ 삭제 전에 멈춘다 — 방어선이 없거나
  # 무조건 통과하면 검수 2회차 N4 의 최악 상태가 되살아난다(N8). hub.py 스텁은 마지막
  # 하위 명령(uninstall-statusline) 응답 시점에 디렉터리 링크 너머로 규칙 파일을 하나
  # 만들어, 방어선을 정상 흐름에서 태운다.
  local sandbox_t40_dir_link
  sandbox_t40_dir_link=$(mktemp -d)
  register_cleanup_path "$sandbox_t40_dir_link"
  mkdir -p "$sandbox_t40_dir_link/.claude/rules"
  mkdir -p "$sandbox_t40_dir_link/dotfiles_hub"
  ln -s "$sandbox_t40_dir_link/dotfiles_hub" "$sandbox_t40_dir_link/.claude/rules/hub"
  mkdir -p "$sandbox_t40_dir_link/.claude/hub/bin"
  cat > "$sandbox_t40_dir_link/.claude/hub/bin/hub.py" << 'PYEOF'
#!/usr/bin/env python3
import os
import sys
subcommand = sys.argv[1] if len(sys.argv) > 1 else ""
if subcommand == "uninstall-statusline":
    late_rule_path = os.path.expanduser("~/.claude/rules/hub/dashboard-recording.md")
    with open(late_rule_path, "w") as late_rule_file:
        late_rule_file.write("late\n")
    print('{"ok":true,"late_rule":"created"}')
else:
    print('{"ok":true}')
PYEOF
  local uninstall_dir_link_output_t40 uninstall_dir_link_exit_t40=0
  uninstall_dir_link_output_t40=$(HOME="$sandbox_t40_dir_link" "$hub_install_file_t40" --uninstall 2>&1) || uninstall_dir_link_exit_t40=$?
  if [[ "$uninstall_dir_link_output_t40" != *'"late_rule":"created"'* ]]; then
    record_failure "$test_name" "T40-12d: 시나리오 전제가 깨졌다 — 스텁이 late_rule 을 만들지 않음"
    return 1
  fi
  if [[ "$uninstall_dir_link_exit_t40" -eq 0 ]]; then
    record_failure "$test_name" "T40-12d: 사전조건 뒤 링크 너머에 규칙 파일이 생겼는데 --uninstall 이 exit 0(방어선 회귀)"
    return 1
  fi
  if [[ ! -d "$sandbox_t40_dir_link/.claude/hub/bin" ]]; then
    record_failure "$test_name" "T40-12d: 방어선이 거부했는데도 bin/ 이 지워짐(부분 제거 회귀)"
    return 1
  fi
  if [[ ! -f "$sandbox_t40_dir_link/dotfiles_hub/dashboard-recording.md" ]]; then
    record_failure "$test_name" "T40-12d: 방어선이 거부했는데도 링크 너머에 생긴 규칙 파일이 사라짐(링크 관통)"
    return 1
  fi

  # T40-7: /harness-update Phase 4b 의 "이미 최신" 사전 비교에 hub/rules 비교 줄이 있고, 그
  # 줄이 server-stop --json 호출보다 앞선다(HD11 — bin/ 만 같아도 규칙이 바뀌면 재설치가
  # 돌아야 한다. T25-228 이 첫 비교 줄의 리터럴과 순서를 이미 물고 있어 그 줄 자체는
  # 손대지 않는다). 순서 사실(T40-7a)과 "bin/ 은 그대로, 규칙만 변경" 분기 존재(T40-7b,
  # 검수 1회차 F10 — 9f23534 「이미 최신이면 서버를 안 끈다」의 연장)는 각각 다른 결함을
  # 겨눠 원장 행도 따로 둔다(T22-170a/b 등과 같은 문자 접미 관례 — 같은 T40-7 화제 아래
  # 묶이는 독립 서브체크). 순서 서브체크(T40-7a)는 검수 1회차 이전부터 코드에 있었지만
  # (사실 정정, 검수 2회차 N6) K5 위반은 아니었다 — 그때는 두 검사가 같은 리터럴 ID
  # "T40-7:" 을 썼고 그 ID 자체는 원장 행이 있어 K5(원장 완비)는 성립했다. 빠져 있던
  # 것은 순서 서브체크 전용 변조행(그 서브체크만 겨눈 뮤테이션 검증)이었다 — 원래
  # T40-7 행의 변조는 비교 줄 부재만 겨눴고 순서 위반은 아무도 재현하지 않았다. 이번에
  # F10 작업 중 발견해 T40-7a 로 분리·등록한다.
  local hub_rules_diff_line_t40 server_stop_json_line_t40
  hub_rules_diff_line_t40=$(grep -nF 'diff -rq "$repo_path/hub/rules" "$HOME/.claude/rules/hub"' "$harness_update_file_t40" | head -1 | cut -d: -f1)
  server_stop_json_line_t40=$(grep -nF 'server-stop --json' "$harness_update_file_t40" | head -1 | cut -d: -f1)
  if [[ -z "$hub_rules_diff_line_t40" ]]; then
    record_failure "$test_name" "T40-7: commands/harness-update.md 에 hub/rules 사전 비교 명령이 없음"
    return 1
  fi
  if [[ -z "$server_stop_json_line_t40" || "$hub_rules_diff_line_t40" -ge "$server_stop_json_line_t40" ]]; then
    record_failure "$test_name" "T40-7a: hub/rules 사전 비교가 server-stop --json 호출보다 앞에 있지 않음(불필요한 서버 정지 회귀)"
    return 1
  fi
  if ! grep -qF 'Hub rules changed but bin/ did not' "$harness_update_file_t40"; then
    record_failure "$test_name" "T40-7b: commands/harness-update.md 에 'bin/ 은 그대로, 규칙만 변경' 분기(서버 미개입 재설치)가 없음"
    return 1
  fi

  # T40-8(역방향 2종): coding-harness 가 배포하는 rules/ 안 어디에도 hub_dashboard_log.py 를
  # 언급하지 않고(§17-2 안 A — role-separation.md 에 포인터조차 남기지 않는다는 승인의
  # 회귀 가드), 레포 commands/ 에 옛 dashboard* 파일이 남아 있지 않다(HD1).
  local rules_dashboard_log_hits_t40
  rules_dashboard_log_hits_t40=$(grep -rl 'hub_dashboard_log.py' "$REPO_ROOT/rules" 2> /dev/null | wc -l | tr -d ' ')
  if [[ "$rules_dashboard_log_hits_t40" -ne 0 ]]; then
    record_failure "$test_name" "T40-8: rules/ 안에 hub_dashboard_log.py 언급이 ${rules_dashboard_log_hits_t40}건 있음(안 A 위반 — coding-harness 배포 규칙이 허브 내부 구현을 알면 안 된다)"
    return 1
  fi
  local repo_dashboard_leftover_count_t40
  repo_dashboard_leftover_count_t40=$(find "$REPO_ROOT/commands" -maxdepth 1 -name 'dashboard*' | wc -l | tr -d ' ')
  if [[ "$repo_dashboard_leftover_count_t40" -ne 0 ]]; then
    record_failure "$test_name" "T40-8: 레포 commands/ 에 dashboard* 파일이 ${repo_dashboard_leftover_count_t40}건 남아 있음(HD1 위반)"
    return 1
  fi

  finish_group "$test_name"
}

# T41 픽스처 — VERSION 을 마음대로 바꿔 끼울 수 있는 레포 사본(rules agents commands install.sh
# removals.txt)을 만든다. 사본에는 .git 이 없어 install.sh 의 installed_from_commit 은 unknown 이 된다.
make_version_fixture_repo() {
  local fixture_dir="$1"
  cp -R "$REPO_ROOT/rules" "$REPO_ROOT/agents" "$REPO_ROOT/commands" \
    "$REPO_ROOT/install.sh" "$REPO_ROOT/removals.txt" "$fixture_dir/"
}

# T41(신설, docs/prps/harness-versioning.md HV1~HV10): 버전 체계 — 루트 VERSION 이 SemVer 한 줄이고,
# install.sh 가 그 값을 설치 기록(harness_version)과 설치 출력 첫 줄에 싣고, 스키마 번호(version 3)에
# 간섭하지 않고, VERSION 이 없거나 틀리면 unknown + WARN 으로 설치를 계속하고, 로컬 태그가 VERSION 과
# 같고, 문서 3종이 규칙을 가리키는지 본다.
#
# 모든 설치는 샌드박스(mktemp -d, 진입부의 HOME 치환)에서만 돈다.
#
# 한계(비망라, HV9) — "평소 커밋에서 VERSION 을 바꾸지 마라"는 이 그룹이 보지 않는다(릴리스 커밋과 평소 커밋을
# 기계가 가를 수 없다, CLAUDE.md 1줄이 대신한다). T41-6 은 로컬 태그만 보므로 태그 푸시 누락도 못 잡는다.
# 전수 증명이 아니다.
test_harness_versioning() {
  group_failures=()   # 앞 그룹이 조기 return 했을 때의 잔여물 제거
  local test_name="T41"
  local test_desc="버전 체계 — VERSION 정본·설치 기록·폴백·태그 일치·문서 토큰 (T41-1~T41-9)"
  log_test_name "$test_name" "$test_desc"

  local version_file_t41="$REPO_ROOT/VERSION"
  # 숫자 부분 1~9자리 — install.sh HARNESS_VERSION_PATTERN·허브 hub_release.py 와 같은 경계(HV1).
  local semver_pattern_t41='^(0|[1-9][0-9]{0,8})\.(0|[1-9][0-9]{0,8})\.(0|[1-9][0-9]{0,8})$'
  local repo_version_t41=""

  # T41-1: VERSION 은 SemVer X.Y.Z 한 줄 + 끝 개행 1개다(바이트 수가 첫 줄 길이 + 1 이면 앞뒤 공백·
  # 둘째 줄·개행 없음이 모두 걸린다).
  if [[ ! -f "$version_file_t41" ]]; then
    note_failure "T41-1: 루트 VERSION 파일이 없음(HV1 정본)"
  else
    repo_version_t41=$(head -n 1 "$version_file_t41")
    local version_bytes_t41
    version_bytes_t41=$(wc -c < "$version_file_t41" | tr -d ' ')
    if [[ "$version_bytes_t41" -ne $((${#repo_version_t41} + 1)) || ! "$repo_version_t41" =~ $semver_pattern_t41 ]]; then
      note_failure "T41-1: VERSION 이 SemVer 한 줄(끝 개행 1개)이 아님 — 첫 줄 '${repo_version_t41}', 바이트 ${version_bytes_t41}"
    fi
  fi

  # T41-2·T41-8: 실제 레포로 --scope project 설치 → 설치 기록에 "harness_version": "<VERSION 값>" 이
  # 정확히 1줄, 설치 출력 첫 줄과 dry-run 계획 줄에 버전이 찍힌다(HV6·HV8).
  local project_sandbox_t41 install_output_t41 install_exit_t41=0 manifest_file_t41
  project_sandbox_t41=$(mktemp -d)
  register_cleanup_path "$project_sandbox_t41"
  install_output_t41=$(cd "$project_sandbox_t41" && "$INSTALL_SCRIPT" --scope project 2>&1) || install_exit_t41=$?
  manifest_file_t41="$project_sandbox_t41/.claude/.coding-harness.json"
  if [[ "$install_exit_t41" -ne 0 ]]; then
    note_failure "T41-2: 실제 레포 --scope project 설치가 exit ${install_exit_t41} 로 실패함"
  else
    local recorded_line_count_t41
    recorded_line_count_t41=$(grep -cF "\"harness_version\": \"${repo_version_t41}\"" "$manifest_file_t41" || true)
    if [[ "$recorded_line_count_t41" -ne 1 ]]; then
      note_failure "T41-2: 설치 기록의 harness_version 줄이 정확히 1개가 아님(VERSION '${repo_version_t41}', 실제 ${recorded_line_count_t41}줄)"
    fi
  fi
  if ! grep -qF "[INFO] coding-harness ${repo_version_t41} 설치 (scope: project)" <<< "$install_output_t41"; then
    note_failure "T41-8: 설치 출력에 '[INFO] coding-harness <VERSION> 설치' 줄이 없음(HV8)"
  fi
  local dry_run_output_t41
  dry_run_output_t41=$(cd "$project_sandbox_t41" && "$INSTALL_SCRIPT" --scope project --dry-run 2>&1) || true
  if ! grep -qF "[INFO] coding-harness ${repo_version_t41} 설치 계획 (scope: project, DRY-RUN)" <<< "$dry_run_output_t41"; then
    note_failure "T41-8b: dry-run 출력에 '[INFO] coding-harness <VERSION> 설치 계획' 줄이 없음(HV8)"
  fi

  # T41-3: 스키마 무간섭(행동). 새 install.sh 가 만든 user scope 설치 기록(harness_version 이 든 v3)을
  # 둔 채, 대장에 없는 ~/.claude/CLAUDE.md(레거시 센티널 2종을 가진 파일)를 두고 재설치한다 — 은퇴 규칙 4
  # (read_manifest_version >= 3 → skip)가 새 필드가 든 기록에서도 그대로 발동하면 파일은 무접촉이고
  # [보호]·은퇴 로그가 없다. 규칙 4 가 안 서면 규칙 7 이 파일을 개명한다.
  local user_home_t41 user_output_t41 user_claude_md_t41 claude_md_before_t41 user_exit_t41=0
  user_home_t41=$(mktemp -d)
  register_cleanup_path "$user_home_t41"
  user_claude_md_t41="$user_home_t41/.claude/CLAUDE.md"
  HOME="$user_home_t41" "$INSTALL_SCRIPT" --scope user > /dev/null 2>&1 || true
  {
    echo '# 전역 개발 지침 (~/.claude/CLAUDE.md)'
    echo ''
    echo '### 서브에이전트 위임은 사용자가 상시 요청한 것이다'
  } > "$user_claude_md_t41"
  claude_md_before_t41=$(cat "$user_claude_md_t41")
  user_output_t41=$(HOME="$user_home_t41" "$INSTALL_SCRIPT" --scope user 2>&1) || user_exit_t41=$?
  if [[ "$user_exit_t41" -ne 0 ]] || [[ ! -f "$user_claude_md_t41" ]] \
    || [[ "$(cat "$user_claude_md_t41" 2> /dev/null)" != "$claude_md_before_t41" ]] \
    || grep -qE '\[보호\]|은퇴' <<< "$user_output_t41"; then
    note_failure "T41-3: harness_version 이 든 v3 설치 기록에서 은퇴 규칙 4(스키마 번호 3 이상 → 무접촉)가 발동하지 않음(exit ${user_exit_t41})"
  fi

  # T41-4: 폴백(HV7). VERSION 이 없거나·형식이 틀리거나·여러 줄인 사본에서도 설치는 exit 0 이고,
  # 설치 기록은 "unknown", stderr 에 VERSION 을 가리키는 WARN 이 정확히 1줄이다.
  local fallback_case_t41 fixture_dir_t41 target_dir_t41 stderr_file_t41 fallback_exit_t41 warn_count_t41
  for fallback_case_t41 in missing malformed multiline toolong unreadable; do
    fixture_dir_t41=$(mktemp -d)
    target_dir_t41=$(mktemp -d)
    register_cleanup_path "$fixture_dir_t41" "$target_dir_t41"
    make_version_fixture_repo "$fixture_dir_t41"
    case "$fallback_case_t41" in
      malformed) printf '1.0\n' > "$fixture_dir_t41/VERSION" ;;
      multiline) printf '1.0.0\n1.0.1\n' > "$fixture_dir_t41/VERSION" ;;
      toolong) printf '1.0.1234567890\n' > "$fixture_dir_t41/VERSION" ;;
      unreadable) printf '1.0.0\n' > "$fixture_dir_t41/VERSION"; chmod 000 "$fixture_dir_t41/VERSION" ;;
    esac
    if [[ "$fallback_case_t41" == "unreadable" && -r "$fixture_dir_t41/VERSION" ]]; then
      continue   # root 등 권한 검사를 받지 않는 실행 환경 — 읽기 실패를 재현할 수 없다
    fi
    stderr_file_t41="$target_dir_t41.stderr"
    register_cleanup_path "$stderr_file_t41"
    fallback_exit_t41=0
    (cd "$target_dir_t41" && "$fixture_dir_t41/install.sh" --scope project > /dev/null 2> "$stderr_file_t41") || fallback_exit_t41=$?
    if [[ "$fallback_exit_t41" -ne 0 ]]; then
      note_failure "T41-4: VERSION 폴백(${fallback_case_t41}) 설치가 exit 0 이 아님(exit ${fallback_exit_t41}) — 버전은 메타데이터라 설치를 막으면 안 된다"
      continue
    fi
    if ! grep -qF '"harness_version": "unknown"' "$target_dir_t41/.claude/.coding-harness.json"; then
      note_failure "T41-4: VERSION 폴백(${fallback_case_t41}) 설치 기록이 harness_version unknown 이 아님"
    fi
    warn_count_t41=$(grep -E '\[WARN\].*VERSION' "$stderr_file_t41" | wc -l | tr -d ' ')
    if [[ "$warn_count_t41" -ne 1 ]]; then
      note_failure "T41-4: VERSION 폴백(${fallback_case_t41}) 의 VERSION WARN 이 stderr 에 정확히 1줄이 아님(실제 ${warn_count_t41}줄)"
    fi
    if grep -qF 'Permission denied' "$stderr_file_t41"; then
      note_failure "T41-4b: VERSION 폴백(${fallback_case_t41}) 의 읽기 오류(cat)가 stderr 로 새어 나옴"
    fi
  done

  # T41-5: 멱등·갱신. 같은 VERSION 재설치는 manifest 변경 없음, VERSION 만 바뀌면 설치 기록이 다시 쓰인다.
  fixture_dir_t41=$(mktemp -d)
  target_dir_t41=$(mktemp -d)
  register_cleanup_path "$fixture_dir_t41" "$target_dir_t41"
  make_version_fixture_repo "$fixture_dir_t41"
  printf '1.2.3\n' > "$fixture_dir_t41/VERSION"
  (cd "$target_dir_t41" && "$fixture_dir_t41/install.sh" --scope project > /dev/null 2>&1) || true
  local same_version_output_t41 changed_version_output_t41
  same_version_output_t41=$(cd "$target_dir_t41" && "$fixture_dir_t41/install.sh" --scope project 2>&1) || true
  if ! grep -qF 'manifest → 변경 없음' <<< "$same_version_output_t41"; then
    note_failure "T41-5: 같은 VERSION 재설치에서 'manifest → 변경 없음' 이 안 나옴(멱등 위반)"
  fi
  printf '1.2.4\n' > "$fixture_dir_t41/VERSION"
  changed_version_output_t41=$(cd "$target_dir_t41" && "$fixture_dir_t41/install.sh" --scope project 2>&1) || true
  if grep -qF 'manifest → 변경 없음' <<< "$changed_version_output_t41" \
    || ! grep -qF '"harness_version": "1.2.4"' "$target_dir_t41/.claude/.coding-harness.json"; then
    note_failure "T41-5: VERSION 만 바꾼 재설치에서 설치 기록이 갱신되지 않음(변경 없음으로 오판)"
  fi

  # T41-6: 로컬 태그 일치(HV2). 레포의 v* 태그는 주석 태그이고 vX.Y.Z 형식이며, 그 커밋의 VERSION 이
  # 태그 숫자와 같다. git 이 없거나 .git 이 없는 사본(미러 포함)에서는 건너뛴다(실패 아님).
  if ! command -v git > /dev/null 2>&1 || ! git -C "$REPO_ROOT" rev-parse --git-dir > /dev/null 2>&1; then
    log_info "T41-6 건너뜀: git 또는 레포 .git 이 없음"
  else
    local tag_name_t41 tag_version_t41 tag_object_type_t41 tagged_version_t41
    while IFS= read -r tag_name_t41; do
      tag_version_t41="${tag_name_t41#v}"
      tag_object_type_t41=$(git -C "$REPO_ROOT" cat-file -t "refs/tags/$tag_name_t41" 2> /dev/null || true)
      tagged_version_t41=$(git -C "$REPO_ROOT" show "refs/tags/$tag_name_t41:VERSION" 2> /dev/null | head -n 1 || true)
      if [[ ! "$tag_version_t41" =~ $semver_pattern_t41 || "$tag_object_type_t41" != "tag" \
        || "$tagged_version_t41" != "$tag_version_t41" ]]; then
        note_failure "T41-6: 태그 ${tag_name_t41} 가 vX.Y.Z 주석 태그가 아니거나 그 커밋의 VERSION('${tagged_version_t41}')과 다름"
      fi
    done < <(git -C "$REPO_ROOT" tag -l 'v*')
  fi

  # T41-9: 자릿수 경계 일치(HV1). 저장소가 받는 VERSION 형식(install.sh 의 숫자 자릿수 {0,N})과 허브가 읽는
  # 태그 형식(hub_release.py MAX_VERSION_NUMBER_DIGITS)이 같은 경계여야 한다 — 어긋나면 한쪽이 받은 값을 다른
  # 쪽이 다르게 읽는다(자릿수 무제한은 허브의 int() 변환 한도에서 사이클을 죽였다, 2회차 검수 Major).
  local pattern_bounds_t41 pattern_bound_count_t41 pattern_bound_t41 hub_digit_limit_t41
  pattern_bounds_t41=$(grep -E '^readonly HARNESS_VERSION_PATTERN=' "$INSTALL_SCRIPT" | grep -oE '\{0,[0-9]+\}' || true)
  pattern_bound_count_t41=$(grep -c . <<< "$pattern_bounds_t41" || true)
  pattern_bound_t41=$(sort -u <<< "$pattern_bounds_t41" | tr -d '{}' | cut -d, -f2)
  hub_digit_limit_t41=$(sed -nE 's/^MAX_VERSION_NUMBER_DIGITS = ([0-9]+)$/\1/p' "$REPO_ROOT/hub/bin/hub_release.py" | head -1)
  if [[ "$pattern_bound_count_t41" -ne 3 || -z "$pattern_bound_t41" || "$pattern_bound_t41" == *$'\n'* \
    || -z "$hub_digit_limit_t41" || "$((pattern_bound_t41 + 1))" -ne "$hub_digit_limit_t41" ]]; then
    note_failure "T41-9: VERSION 숫자 자릿수 경계가 install.sh({0,${pattern_bound_t41}} ${pattern_bound_count_t41}곳)와 허브 MAX_VERSION_NUMBER_DIGITS(${hub_digit_limit_t41})에서 어긋남 — 저장소와 허브가 받는 형식이 달라진다"
  fi

  # T41-7a·b·c: 문서 토큰 — 규칙이 문서에서 사라지는 것을 막는다.
  if ! grep -qF 'harness_version' "$REPO_ROOT/commands/harness-update.md"; then
    note_failure "T41-7a: commands/harness-update.md 에 harness_version 토큰이 없음(HV8 — 업데이트 보고에 버전이 흐르지 않는다)"
  fi
  if ! grep -qE '^## 버전$' "$REPO_ROOT/README.md" || ! grep -qF 'VERSION' "$REPO_ROOT/README.md"; then
    note_failure "T41-7b: README.md 에 '## 버전' 절 또는 VERSION 언급이 없음(릴리스 절차의 정본 자리)"
  fi
  if ! grep -qF 'VERSION' "$REPO_ROOT/CLAUDE.md"; then
    note_failure "T41-7c: CLAUDE.md 에 VERSION 포인터가 없음(HV10 — 커밋마다 번호를 올리는 실패의 방어선)"
  fi

  finish_group "$test_name"
}

# 그룹 레지스트리(항목1, tests-hardening PRP §4.2·§6-2). "<그룹ID>:<함수명>" 쌍의 배열로
# total_tests 를 리터럴이 아니라 여기서 산출한다. 실행 순서는 기존 register_and_run_tests
# 호출 순서를 그대로 보존한다(T35 자신의 주석이 순서 의존을 언급하므로 재정렬하지 않는다).
# T30 이 T27 보다 먼저 실행되는 등 그룹 ID 순서와 실행 순서가 어긋나는 지점이 있는데,
# 이는 기존 코드 그대로다(신규 그룹이 처음 추가될 때의 히스토리 — T11 은 결번).
readonly TEST_GROUPS=(
  "T1:test_scope_project_new_install"
  "T2:test_scope_user_new_install"
  "T3:test_idempotency"
  "T4:test_partial_damage_recovery"
  "T5:test_scope_project_ignores_existing_claude_md"
  "T6:test_retire_ledger_match"
  "T7:test_retire_protection_branches"
  "T8:test_dry_run_no_side_effect"
  "T9:test_missing_scope"
  "T10:test_no_write_permission"
  "T12:test_paths_frontmatter_preserved"
  "T13:test_relative_path_references_work"
  "T14:test_symlink_target_warning"
  "T15:test_diff_detection_requires_force"
  "T16:test_unmanaged_files_preserved"
  "T17:test_commands_installed"
  "T18:test_global_command_overlap_report"
  "T19:test_global_report_skipped_for_user_scope"
  "T20:test_manifest_created_after_install"
  "T21:test_manifest_fields_complete"
  "T22:test_dashboard_template_integrity"
  "T23:test_dashboard_option_docs"
  "T24:test_hub_unit_tests"
  "T25:test_hub_docs_and_constants"
  "T26:test_always_on_context_budget"
  "T30:test_rules_and_agents_file_count_parity"
  "T27:test_manifest_ledger_and_removals"
  "T28:test_rules_vendor_patch_guards"
  "T29:test_rules_agent_denylist_guard"
  "T31:test_rules_workflow_guardrails"
  "T32:test_license_and_notice_guardrails"
  "T33:test_dashboard_bash_gate_regression"
  "T34:test_dashboard_helper_table_dispatch_parity"
  "T35:test_pycache_excluded_from_deployment"
  "T36:test_suite_exit_guard_regression"
  "T37:test_mutation_ledger_harness"
  "T39:test_prose_number_citation_hygiene"
  "T38:test_vendor_patch_contract_tokens"
  "T40:test_hub_dashboard_channel"
  "T41:test_harness_versioning"
)

# TEST_GROUPS 의 각 항목이 §6-2 불변식(그룹 ID 유일 · 함수가 실제로 정의됨 · 함수 내부
# local test_name 값과 그룹 ID 일치)을 지키는지 검사한다(항목2). 레지스트리가 조용히
# 어긋나는 것을 실행 전에 잡는다 — 위반이 있으면 어떤 그룹도 실행하지 않고 exit 1.
# bash 3.2 는 선언됐지만 빈 배열이어도 "${arr[@]}" 순회 자체가 set -u 에서 unbound 이므로
# (실측 확인) 원소가 있을 때만 순회한다(seen_ids).
#
# 한계(비망라, tests-hardening PRP §4.6 — 원장 T99-3 등록에 따라 T37-13 이 이 표기를
# 강제한다) — 이 검사는 배열에 등록된 항목만 본다. 정의돼 있는데 배열에 등록되지 않은 그룹
# 함수(그래서 아예 실행되지 않는 그룹)는 여기서 드러나지 않는다. test_name 추출도
# `declare -f` 텍스트의 첫 `local test_name=` 한 줄에만 의존한다 — 아래가 그 대가이고,
# 세 형태 모두 불일치로 보고되지만 원인은 지목되지 않는다(실측):
#  - `local` 없는 대입(`test_name="T41"`)은 그 줄이 grep 패턴에 걸리지 않아 빈 값으로 읽힌다.
#  - 작은따옴표 값(`local test_name='T42'`)은 sed 의 치환이 성립하지 않아 줄 전체가 그대로
#    읽힌다.
#  - 변수를 경유한 대입(`local test_name="$MUTATION_HARNESS_GROUP"`)은 변수 참조 문자열이
#    그대로 뽑힌다 — 그래서 MUTATION_HARNESS_GROUP 상수화에서 이 한 줄만 리터럴로 남겼다
#    (그 상수 주석 참고).
# 반대로 조건 분기 안의 대입(`if true; then local test_name="T40"; fi`)은 정상 추출되므로
# 불일치로 보고되지 않는다. 전수 증명이 아니다.
verify_group_registry_parity() {
  local seen_ids=()
  local mismatches=0
  local entry group_id function_name declared_name seen_id is_duplicate

  for entry in "${TEST_GROUPS[@]}"; do
    group_id="${entry%%:*}"
    function_name="${entry#*:}"

    is_duplicate=0
    if ((${#seen_ids[@]} > 0)); then
      for seen_id in "${seen_ids[@]}"; do
        if [[ "$seen_id" == "$group_id" ]]; then
          is_duplicate=1
          break
        fi
      done
    fi
    if ((is_duplicate == 1)); then
      log_error "레지스트리 오류: 그룹 ID \"$group_id\" 가 TEST_GROUPS 에 중복 등록됨"
      ((mismatches++)) || true
      continue
    fi
    seen_ids+=("$group_id")

    if ! declare -F "$function_name" > /dev/null 2>&1; then
      log_error "레지스트리 오류: $group_id 가 가리키는 함수 \"$function_name\" 가 정의되지 않음"
      ((mismatches++)) || true
      continue
    fi

    declared_name="$(declare -f "$function_name" | grep -m1 'local test_name=' | sed -E 's/.*test_name="([^"]*)".*/\1/')" || true
    if [[ "$declared_name" != "$group_id" ]]; then
      log_error "레지스트리 파리티 불일치: $function_name 는 배열에 \"$group_id\" 로 등록됐지만 함수 내부 test_name 은 \"$declared_name\""
      ((mismatches++)) || true
    fi
  done

  if ((mismatches > 0)); then
    log_error "레지스트리 파리티 검사 실패 — 위 ${mismatches}건을 먼저 고쳐야 스위트를 실행할 수 있음"
    exit 1
  fi
  PRECHECK_REGISTRY_PARITY_DONE=1  # 통과 표시(PRP §20-8 신규 3)
}

# 이 파일의 `trap … <시그널>` 설치 개수를 두 전처리 순서로 각각 세어 **큰 값**을 낸다
# (PRP tests-hardening §17 이관 3). 두 순서는 서로 다른 형태를 놓친다:
#  - 주석 제거 → 줄 이어짐 합침: `\` 로 끝난 주석 줄 바로 다음의 진짜 trap 문을 정확히
#    세지만(bash 의 주석은 `\` 로 이어지지 않으므로 그 trap 은 실제로 설치된다 — 옛 순서가
#    실제 발화 1곳을 0곳으로 셌던 재현이 이 자리다), 진짜 trap 문의 연속줄이 앞줄에서 아직
#    안 닫힌 따옴표 안에서 우연히 `#` 로 시작하면 그 줄을 문자열 내부인 줄 모르고 지워
#    계수를 놓친다(재현 확인).
#  - 줄 이어짐 합침 → 주석 제거: 뒤 형태는 잡지만 앞 형태를 놓친다(대칭).
# 큰 값을 취하면 두 누락이 함께 닫힌다 — S2 검수자가 네 시나리오에서 max 가 실제 발화
# 개수와 일치함을 검증했다. 착지 시점 실측은 두 순서가 같은 값이다(EXIT 1곳 · RETURN 0곳).
#
# 한계(비망라) — 이것은 두 정적 텍스트 관점의 합집합이지 bash 파서가 아니다. 어느 순서로도
# 줄 시작에 리터럴 `trap` 이 나타나지 않는 형태는 여전히 세지 못한다(그 목록은 아래
# verify_trap_hygiene 주석에 있다). 반대 방향으로 max 는 과다계수 쪽으로 기운다 — 여러 줄
# 문자열 안의 한 줄이 `trap … EXIT` 로 시작하면 실제 설치가 없어도 세어진다(현재 이 파일에는
# 그런 자리가 없다). perl 이 없으면 두 값이 함께 0 이 되어 fail-close 가 걸린다 —
# verify_trap_hygiene 가 이 함수를 부르기 전에 perl 유무를 먼저 확인해, 그 경우를 계수
# 0 과 다른 메시지로 분리한다(PRP §17 이관 8). 전수 증명이 아니다.
count_trap_installs_max() {
  local source_path="$1" signal="$2"
  local comments_first joins_first
  comments_first=$(grep -v '^[[:space:]]*#' "$source_path" \
    | perl -0777 -pe 's/\\\n\s*//g' | grep -c "^[[:space:]]*trap .*${signal}") || true
  joins_first=$(perl -0777 -pe 's/\\\n\s*//g' "$source_path" \
    | grep -v '^[[:space:]]*#' | grep -c "^[[:space:]]*trap .*${signal}") || true
  if ((joins_first > comments_first)); then
    echo "$joins_first"
  else
    echo "$comments_first"
  fi
}

# 트랩 위생 검사(K3, tests-hardening PRP §4.3). S2 가 세운 불변식 — 통상적인 방식으로
# 다시 걸지 않는 한 이 파일 안 trap EXIT 설치는 위 전역 suite_exit_guard 한 곳, trap
# RETURN 설치는 0곳이어야 한다 — 을 실행마다 다시 확인한다.
#
# 기제: 이 파일 텍스트에서 주석을 제거하고 줄 이어짐(\)으로 쪼개진 문장을 논리 줄 하나로
# 합친 뒤, 줄 시작이 `trap` 인 논리 줄만 센다. 그 두 전처리의 **순서를 하나로 고르지
# 않는다** — 두 순서가 서로 다른 형태를 놓치므로 둘 다 계산해 큰 값을 취한다(PRP §17 이관
# 3 — 근거·한계는 위 count_trap_installs_max 주석). 앵커
# (맨 앞부터 `trap`)를 쓰는 이유는 trap 을 문자열로 인용하는 awk 범위 패턴(아래 T36
# 자신의 검증부, 예: `awk '/.../,/^trap suite_exit_guard EXIT$/'`)이 줄 시작은 "awk"라
# 이 앵커에 애초에 걸리지 않기 때문이다.
#
# 이 기제에서 따라오는 한계 — 정적 텍스트 스캔이지 bash 파서가 아니므로, 아래는 실제로
# 발화하는 trap 을 이 검사가 놓치는 형태의 비망라 예시다:
#  - 같은 줄에서 trap 앞에 다른 명령이 먼저 오는 경우: `if true; then trap "…" EXIT; fi`,
#    `cd /tmp && trap "…" EXIT` — 앵커가 줄 시작만 보므로 걸리지 않는다.
#  - 변수·eval 을 경유한 간접 설치: `t=trap; $t "…" EXIT`, `eval 'trap "…" EXIT'` — 리터럴
#    "trap" 이 줄 시작에 없다.
# 위 형태는 모두 통상적인 작성으로는 나오지 않고 의도적 우회에 가까워야 나온다 — 그런
# 우회의 존재 여부까지 기계가 담당하지는 않는다(tests-hardening PRP §4.1 이 그은 경계:
# 기계는 「존재」와 「무는 힘」을, 「정직함」과 「의미」는 검수가 담당한다). 전수 증명이 아니다.
# 한때 세 번째 형태였던 「진짜 trap 문의 연속줄이 우연히 `#` 로 시작하는 경우」는 두 순서를
# 합산하는 위 count_trap_installs_max 로 옮겨가 닫혔다(§17 이관 3) — 한쪽 순서가 놓치는
# 자리를 다른 순서가 센다. 합산이 새로 만드는 한계는 그 함수 주석에 적는다.
verify_trap_hygiene() {
  local exit_trap_installs return_trap_installs
  # perl 부재를 계수 0 과 다른 메시지로 분리한다(PRP §17 이관 8) — count_trap_installs_max
  # 의 두 파이프라인 모두 perl 을 거치므로, perl 이 PATH 에 없으면 두 값이 함께 0 이 되어
  # 아래 첫 번째 판정(EXIT 트랩 개수 위반)과 동일한 문구가 찍혔다. fail-close(exit 1)
  # 자체는 이 분리 이전에도 참이었다(perl 없는 PATH 에서 재현 — exit 1, 그룹 0개 실행) —
  # 여기서 바뀌는 것은 원인 진단의 정밀도다.
  #
  # 한계(비망라) — 이 확인은 perl 이 PATH 에 "존재하는지"만 보고 "정상 실행되는지"는 보지
  # 않는다: 실행 권한이 없는 동명 파일이나 손상된 바이너리도 command -v 는 찾은 것으로
  # 보고한다(실측 확인 — 권한 000 인 가짜 perl, 유효하지 않은 헤더를 가진 가짜 perl 모두
  # command -v 성공). 그런 perl 을 count_trap_installs_max 가 실제로 호출하면 그 안의
  # 파이프라인이 조용히 실패해(|| true 로 삼켜짐) 두 값이 함께 0 이 되므로, 위 fail-close
  # 는 유지되지만(exit 1) perl 부재가 아니라 개수 0 으로 잘못 진단한다 — 이 분리 이전부터
  # 있던 정밀도 한계와 같은 종류다. 전수 증명이 아니다.
  #
  # 메모(이 회차 자기 검증, ledger-anchor-column PRP 이후 갱신) — 예전에는 이 함수·형제
  # 함수의 실패 메시지 문구를 새 주석에 그대로 옮기면 안 됐다: 그 문구가 원장 T99-1 행의
  # expect_token 앵커라 tests/run.sh 전체에서 1건일 것을 요구했고(옛 5열 규약), 그대로
  # 인용하면 2건이 되어 앵커 유일성이 깨졌다 — 그때 초안에서 실제로 그렇게 됐다가(grep -cF
  # 로 사전 확인) 되돌린 적이 있다. 지금은 앵커가 8열 anchor_function(이 함수 자신)으로
  # 분리됐고 5열 유일성도 보고 호출 줄로만 재조준돼 주석은 그 대조에서 애초에 제외된다 —
  # 그래서 이 문구를 주석에 그대로 옮겨 적어도 앵커도 5열 유일성도 깨지지 않는다.
  if ! command -v perl > /dev/null 2>&1; then
    log_error "트랩 위생 검사를 셀 수 없음: perl 이 PATH 에 없음(count_trap_installs_max 의 두 파이프라인 모두 perl 을 요구한다) — 계수 0 과 실제 위반을 구분할 수 없어 fail-close 로 exit 1"
    exit 1
  fi
  exit_trap_installs=$(count_trap_installs_max "$REPO_ROOT/tests/run.sh" "EXIT")
  return_trap_installs=$(count_trap_installs_max "$REPO_ROOT/tests/run.sh" "RETURN")

  if [[ "$exit_trap_installs" -ne 1 ]]; then
    log_error "트랩 위생 검사 실패: EXIT 트랩 설치 ${exit_trap_installs}곳(기대 1곳 — 전역 suite_exit_guard 뿐, 함수 안에서 다시 걸면 안 된다)"
    exit 1
  fi
  if [[ "$return_trap_installs" -ne 0 ]]; then
    log_error "트랩 위생 검사 실패: RETURN 트랩 설치 ${return_trap_installs}곳(기대 0곳 — register_cleanup_path + finish_group 의 명시 호출로 대체됐다)"
    exit 1
  fi
  PRECHECK_TRAP_HYGIENE_DONE=1  # 통과 표시(PRP §20-8 신규 3 — register_and_run_tests 참고)
}

# 원장 데이터 행 중 **면제행**(mutation_sed == "-")에서 지정 열이 지정 접두로 시작하는 행
# 수를 센다 — 헤더 산문이 인용한 두 바구니 계수의 실측이다. 열 번호는 원장 헤더의 8열 규약
# 그대로다(1 = guard_id · 7 = exempt_reason — ledger-anchor-column PRP 가 7열을 8열로
# 늘렸지만 이 두 열의 번호 자체는 바뀌지 않았다). 파서(parse_mutation_ledger)를 쓰지 않고
# 원본을 직접 세는 이유: 이것은 main 의 사전 점검이라 파서보다 먼저 돌고, 세는 대상이 열
# 값 하나뿐이어서 불변식 검증이 필요하지 않다.
count_ledger_exempt_rows_with_prefix() {
  local ledger_path="$1" column_index="$2" prefix="$3"
  awk -F'\t' -v column_index="$column_index" -v prefix="$prefix" \
    '/^#/ {next} NF < 8 {next} $3 == "-" && index($column_index, prefix) == 1 {n++} END {print n+0}' \
    "$ledger_path"
}

# 원장 헤더가 인용한 숫자 하나를 상수·실측치와 대조한다(§19-5 최우선 항목). citation_regex
# 는 캡처 그룹 하나로 그 숫자를 잡는 ERE 여야 하고, `grep -oE | wc -l` 의 유일성 계수와
# bash 의 =~ 캡처가 같은 정규식을 공유한다(두 리터럴이 따로 표류하는 것을 막는다).
#
# 매칭 건수를 값 대조보다 **먼저** 단언하는 이유(T26-2 가 정확히 같은 함정을 닫았다): 인용이
# 지워지거나 여러 곳으로 갈라졌을 때 첫 매치만 읽으면, 남은 하나를 읽어 조용히 통과하거나
# 어느 것을 읽는지가 불확정해진다. 0건·2건 이상은 값 대조로 넘어가지 않고 그 자체를 실패로
# 보고한다.
#
# 한계(아래는 비망라 예시다) — 이것은 헤더 산문의 **숫자**만 본다. 그 숫자에 붙은 서술(이력
# 화살표, 무엇을 세는지에 대한 설명)이 참인지는 검사하지 않는다. 그리고 이 함수는 호출자가
# 넘긴 정규식 하나만 보므로, 호출자가 넘기지 않은 헤더 인용은 이 함수의 사정거리 밖이다 —
# 그 목록이 무엇을 빼놓는지는 verify_ledger_header_citations 의 한계 절에 적는다. 인용을
# 새 문장으로 옮겨 쓰면 이 정규식이 0건으로 읽어 fail-loud 로 걸리지만, 그것이 "인용이
# 사라졌다"인지 "형식만 바뀌었다"인지는 구분하지 못한다. 전수 증명이 아니다.
assert_ledger_header_citation() {
  local header_text="$1" citation_regex="$2" expected_value="$3" citation_label="$4"
  local citation_hits matched cited_value=""
  # grep -c 가 아니라 grep -oE | wc -l 인 이유(실측으로 잡은 구멍): -c 는 **줄** 수를 세므로
  # 같은 줄에 인용이 두 번 나오면 1건으로 읽고 통과한다 — 한 줄에 두 인용을 넣은 변조가
  # rc 0 으로 새는 것을 확인했다. T26-2 가 같은 자리에서 같은 관용구(-oE | wc -l)를 쓴다.
  citation_hits=$(grep -oE "$citation_regex" <<< "$header_text" | wc -l | tr -d ' ') || true
  if [[ "$citation_hits" != "1" ]]; then
    log_error "원장 헤더 인용 대조 실패: ${citation_label} — 매칭 ${citation_hits}건(기대 1건 — 인용이 지워졌거나 여러 곳으로 갈라졌다)"
    return 1
  fi
  matched=$(grep -oE "$citation_regex" <<< "$header_text" | head -1)
  if [[ "$matched" =~ $citation_regex ]]; then
    cited_value="${BASH_REMATCH[1]}"
  fi
  if [[ "$cited_value" != "$expected_value" ]]; then
    log_error "원장 헤더 인용 대조 실패: ${citation_label} — 헤더 인용 ${cited_value:-<추출 실패>} vs 실측·상수 ${expected_value}"
    return 1
  fi
  return 0
}

# 원장 헤더(tests/mutations.tsv 의 주석 블록)가 인용한 상수 4종과 면제 바구니 계수 2종을
# 상수·실측과 대조하는 사전 점검(PRP tests-hardening §19-5 최우선 항목). 세 회차 연속으로
# 차단 판정을 낸 계열이 「숫자를 인용한 산문이 그 숫자를 바꾼 수정에 전파되지 않는다」였고 —
# 검수 1회차에 래칫 3종 인용, 2회차에 PRP §19-3 수치 6종, 3회차에 면제 바구니 계수 — 기계가
# 그 숫자를 읽지 않아 매번 검수만이 잡았다. 헤더 인용의 그 두 갈래를 여기서 기계에
# 넘긴다
# (무엇이 남는지는 아래 한계 절).
#
# 이 자리(main 의 사전 점검, verify_trap_hygiene·verify_group_registry_parity 옆)를 고른
# 이유가 둘이다:
#  (i) 계약 파일의 정적 불변식이라 그 둘과 같은 계열이고, 위반이면 그룹을 하나도 실행하지
#      않고 멈추는 것이 맞다.
#  (ii) T37 안에 두면 이 가드를 무는 변조행의 expect_group 이 T37 이 되고, 그러면 미러가
#       --only T37 을 돌려 무한 재귀가 된다(GOTCHA 7) — 파서가 그 행을 거부하므로 면제행밖에
#       만들 수 없다. 사전 점검 자리면 아무 그룹(install.sh 를 안 불러 빠른 T29)을 매개체로
#       실제 변조행을 등록할 수 있다.
#
# 대조 대상은 두 갈래다 — 상수 인용 4종(상수명 뒤 괄호 안 첫 숫자. 그 뒤에 붙는 이력 화살표는
# 읽지 않는다)과 면제 바구니 계수 2종(원장 데이터 행의 실측과 대조한다).
#
# 한계(아래는 비망라 예시다) — 헤더에는 숫자로 인용되지 않은 단정도 많고(면제 사유의 진위,
# 미등록 가드 목록, 「세 번째 사유를 한 행에 썼다」처럼 숫자를 한글로 적은 자리) 그것들은 이
# 검사의 시야 밖이다. **숫자로 인용됐는데도 시야 밖인 자리도 있다** — 위 대조 대상 두 갈래에
# 들지 않는 헤더 산문의 숫자(collect_guard_ids 가 놓치는 접두의 건수, 레지스트리 그룹 수의
# 분해, 상수 인용 괄호 안 첫 숫자 뒤에 붙는 이력 화살표)는 읽지 않는다. 대조 대상 목록이
# 아래 하드코딩 배열이라는 것도 같은 성질의 한계다 — 헤더에 다섯 번째 상수 인용이 생겨도 그
# 배열에 손대지 않으면 조용히 시야 밖이다. 원장 **데이터 행**의 defect_description 이
# 인용하는 숫자(T36-0 행이 자기 sed 의 사정거리를 적는다)도 보지 않는다 — 헤더만 본다.
# 위 (i) 의 「그룹을 하나도 실행하지 않고 멈춘다」는 한때 기계로 고정돼 있지 않았다 — 이
# 호출을 register_and_run_tests 뒤로 옮긴 사본에서도 이 가드는 그 자리에서 계속 물어
# 어떤 검사도 순서 이동을 보지 않았다(재현 확인: 옮긴 사본의 --only T37 이 rc 0). 형제 두
# 사전 점검(verify_trap_hygiene · verify_group_registry_parity)도 같은 구멍을 공유했다 —
# register_and_run_tests 자신이 시작 지점에서 세 완료 플래그를 확인하는
# verify_prechecks_completed_before_group_run(PRP §20-8 신규 3)이 지금은 그 구멍을 막는다:
# main 의 호출 순서가 아니라 이 함수 자신의 전제 조건이 되므로 나열을 옮겨도 우회할 수
# 없다. 반대 방향으로 이 검사는 헤더 산문의 형식에 결합돼 있어, 정당한 리라이트가 인용
# 형식을 바꾸면 0건으로 읽고 멈춘다(fail-loud 이지 조용한 통과가 아니다). 전수 증명이 아니다.
verify_ledger_header_citations() {
  local ledger_path="$REPO_ROOT/tests/mutations.tsv"
  local header_text mismatches=0
  header_text=$(grep '^#' "$ledger_path") || true
  if [[ -z "$header_text" ]]; then
    log_error "원장 헤더 인용 대조 실패: tests/mutations.tsv 의 주석 헤더를 읽지 못함(파일 부재 또는 헤더 삭제 — 대조의 분모가 공허하다)"
    exit 1
  fi

  local citation_spec constant_name expected_value
  for citation_spec in \
      "LEDGER_EXEMPT_ROW_RATCHET $LEDGER_EXEMPT_ROW_RATCHET" \
      "LEDGER_MUTATION_ROW_FLOOR $LEDGER_MUTATION_ROW_FLOOR" \
      "SOURCE_GUARD_ID_FLOOR $SOURCE_GUARD_ID_FLOOR" \
      "NOTE_FAILURE_ID_LESS_RATCHET $NOTE_FAILURE_ID_LESS_RATCHET"; do
    constant_name="${citation_spec%% *}"
    expected_value="${citation_spec##* }"
    if ! assert_ledger_header_citation "$header_text" "${constant_name}\(([0-9]+)" \
        "$expected_value" "상수 ${constant_name} 인용"; then
      ((mismatches++)) || true
    fi
  done

  # 면제 바구니 두 계수. 헤더는 「아래 <n>개는 … 공통 사유를 공유한다」와
  # 「T37-0~T37-<k>(<n>개)는 … 다른 사유를 쓴다」로 인용하고, 세 번째 사유 한 행은 숫자가
  # 아니라 한글로 적혀 있어(「한 행」) 읽을 숫자가 없다 — 그 항은 대조 대상이 아니다.
  local common_exempt_reason_prefix='S3 이전에 존재한 가드'
  local common_reason_rows harness_exempt_rows
  common_reason_rows=$(count_ledger_exempt_rows_with_prefix \
    "$ledger_path" 7 "$common_exempt_reason_prefix") || true
  harness_exempt_rows=$(count_ledger_exempt_rows_with_prefix \
    "$ledger_path" 1 "${MUTATION_HARNESS_GROUP}-") || true
  if ! assert_ledger_header_citation "$header_text" '아래 ([0-9]+)개는' \
      "$common_reason_rows" "공통 면제 사유 바구니 계수 인용"; then
    ((mismatches++)) || true
  fi
  if ! assert_ledger_header_citation "$header_text" \
      "${MUTATION_HARNESS_GROUP}-0~${MUTATION_HARNESS_GROUP}-[0-9]+\(([0-9]+)개\)" \
      "$harness_exempt_rows" "하네스 자신의 면제행 바구니 계수 인용"; then
    ((mismatches++)) || true
  fi

  if ((mismatches > 0)); then
    log_error "원장 헤더 인용 대조 검사 실패 — 위 ${mismatches}건을 먼저 고쳐야 스위트를 실행할 수 있음"
    exit 1
  fi
  PRECHECK_LEDGER_HEADER_DONE=1  # 통과 표시(PRP §20-8 신규 3)
}

# main 의 인자를 파싱해 SELECTED_GROUPS 를 채운다(항목5). 지원 형식은 인자 없음(전체) ·
# --only <id1,id2,...>(콤마 구분, §16 확정) · --list(그룹 ID 열거 후 exit 0) 뿐이고, 그 외
# 인자·값 없는 --only·미등록 그룹 ID 는 전부 exit 2 다(기존에 미지 인자를 조용히 무시하던
# 결함 수정, §0-8 실측).
parse_suite_arguments() {
  SELECTED_GROUPS=("${TEST_GROUPS[@]}")

  if [[ $# -eq 0 ]]; then
    return 0
  fi

  if [[ "$1" == "--list" && $# -eq 1 ]]; then
    local entry
    for entry in "${TEST_GROUPS[@]}"; do
      echo "${entry%%:*}"
    done
    exit 0
  fi

  if [[ "$1" == "--only" && $# -eq 2 && -n "$2" ]]; then
    local requested_ids=() unmatched=()
    IFS=',' read -r -a requested_ids <<< "$2"
    if ((${#requested_ids[@]} == 0)); then
      log_error "잘못된 인자: --only 뒤에 그룹 ID 가 없습니다"
      exit 2
    fi

    SELECTED_GROUPS=()
    local requested_id entry entry_id matched
    for requested_id in "${requested_ids[@]}"; do
      matched=0
      for entry in "${TEST_GROUPS[@]}"; do
        entry_id="${entry%%:*}"
        if [[ "$entry_id" == "$requested_id" ]]; then
          SELECTED_GROUPS+=("$entry")
          matched=1
          break
        fi
      done
      if ((matched == 0)); then
        unmatched+=("$requested_id")
      fi
    done

    if ((${#unmatched[@]} > 0)); then
      log_error "잘못된 인자: --only 에 알 수 없는 그룹 ID (${unmatched[*]})"
      exit 2
    fi
    return 0
  fi

  log_error "잘못된 인자: $* (지원: 인자 없음 · --only <id1,id2,...> · --list)"
  exit 2
}

# 사전 점검 3종(verify_group_registry_parity · verify_trap_hygiene ·
# verify_ledger_header_citations)이 이 함수 호출 전에 전부 끝났는지 확인한다(PRP §20-8
# 신규 3). 기존에는 이 순서가 main 의 호출문 나열 순서에만 의존했다 — 그 세 호출을
# register_and_run_tests 뒤로 옮긴 사본에서도 전체 스위트가 그대로 통과했다(검수 실측,
# 위 verify_ledger_header_citations 한계 절이 그 재현을 남겼다). 기제: 세 사전 점검
# 각각이 자기 검사를 통과하고 반환하는 마지막 줄에서 전용 플래그를 세우고(위
# CLEANUP_PATHS 근처 선언 참고), 이 함수가 그 세 플래그를 자기 시작 지점에서 직접
# 확인한다 — main 의 호출 순서가 아니라 이 함수 자신의 전제 조건이므로 나열 순서를
# 바꾸거나 호출을 통째로 빠뜨려도 우회할 수 없다.
#
# 한계(비망라) — 이 가드는 플래그가 섰는지만 보고, 세 함수의 본문이 실제로 유의미한
# 검사를 수행했는지는 보지 않는다: 어떤 수정이 verify_trap_hygiene 의 검사 로직을 전부
# 지우면서 마지막의 플래그 대입 한 줄만 남기면, 이 가드는 통과하고 트랩 위생 검사만
# 조용히 무력화된다. 세 사전 점검 서로 간의 상대 순서(예: 트랩 위생 검사가 파리티
# 검사보다 먼저 도는지)는 다루지 않는다 — 그 순서는 결과에 영향이 없어 애초에 요구
# 사항이 아니다. 같은 이유로, 플래그 중 하나를 그 검사 함수를 거치지 않고 다른 자리에서
# 직접 대입해도(예: verify_trap_hygiene 호출 줄을 PRECHECK_TRAP_HYGIENE_DONE=1 대입으로
# 바꾼다) 이 가드는 통과한다 — 플래그는 평범한 전역 변수라 대입 주체를 검증하지 않는다
# (재현 확인: 그 치환만으로 --only T29 가 rc 0·무신호). 그 치환 형태 하나는 인자 없는
# 전체 실행에서도 걸렸으나(검수 2회차 실측) 그것은 그 치환이 원장 T99-7 의 sed 대상 줄을
# 함께 지워 사전조건 실패를 낸 결과다 — 호출 줄을 남긴 채 플래그를 따로 세우는 형태는
# 확인하지 않았다. 이 함수 자신의 호출이
# register_and_run_tests 에서 삭제되는 경우도 이 가드 자체는 다루지 않는다 — 세 플래그를
# 아무도 읽지 않으므로 --only T29 는 마찬가지로 rc 0·무신호다(재현 확인). 인자 없는 기본
# 실행에서는 그 삭제가 공용 부분(러너) 변경이라 K6 가 전체 재확인으로 돌고(증분 도입 뒤에도
# 같다), 이 하네스(T37) 자신이 원장 행 T99-7 의 판정 쌍을 수행하다 그 판정이 조용히
# 뒤집히는 것을 T37-15 가 "가드 무력화"로 간접 보고하지만(재현 확인) 원인(호출 누락)을
# 지목하지는 않는다 — suite_exit_guard 헤더 주석이 cleanup_registered_paths 함수 소실에
# 대해 이미 적은 것과 같은 형태이고, 수용 근거도 같다: project CLAUDE.md §4 의 정본
# 검증 명령은 인자 없는 실행이라 공식 커밋 게이트는 이 시나리오를 놓치지 않는다.
# 전수 증명이 아니다.
verify_prechecks_completed_before_group_run() {
  local missing=()
  ((PRECHECK_REGISTRY_PARITY_DONE == 1)) || missing+=("verify_group_registry_parity")
  ((PRECHECK_TRAP_HYGIENE_DONE == 1)) || missing+=("verify_trap_hygiene")
  ((PRECHECK_LEDGER_HEADER_DONE == 1)) || missing+=("verify_ledger_header_citations")
  if ((${#missing[@]} > 0)); then
    log_error "사전 점검 완료 확인 실패: ${missing[*]} 가 그룹 실행 전에 끝나지 않음(순서가 바뀌었거나 호출이 누락됐다)"
    exit 1
  fi
}

# SELECTED_GROUPS 를 순회하며 각 그룹 함수를 실행한다. 그룹 호출 전후로 passed_tests+
# failed_tests 합이 늘지 않았는지(0 증가인지)만 확인하고, 늘지 않았으면(그룹 함수가 집계
# 이전에 return 했거나 이미 집계된 상태에서 재차 반환한 경우) 그 그룹 ID 를
# untallied_groups 에 남긴다 — print_test_summary 의 총합 대조(항목3)가 이 배열로 어느
# 그룹이 빠졌는지 보고한다(B3·K2). +1 을 넘는 증가(예: 한 그룹이 finish_group 을 두 번 불러
# +2)는 이 그룹 단위 검사만으로는 잡지 못하고 그 총합 대조에 기댄다 — "정확히 +1"까지
# 확인하도록 강화하는 것은 S2 의 몫이다.
register_and_run_tests() {
  verify_prechecks_completed_before_group_run
  local entry group_id function_name before_tally after_tally
  for entry in "${SELECTED_GROUPS[@]}"; do
    group_id="${entry%%:*}"
    function_name="${entry#*:}"
    before_tally=$((passed_tests + failed_tests))
    "$function_name" || true
    after_tally=$((passed_tests + failed_tests))
    if ((after_tally == before_tally)); then
      untallied_groups+=("$group_id")
    fi
  done
}

# 테스트 결과 요약 출력. passed+failed != total_tests 면(항목3, B3·K2) 실패로 종결하고
# register_and_run_tests 가 채운 untallied_groups(집계 미도달 그룹 ID)를 함께 보고한다.
# 여기까지 도달하면(통과/실패 무관) SUMMARY_PRINTED 를 세운다(항목4 — suite_exit_guard 가
# 참조).
#
# 한계(비망라, tests-hardening PRP §4.6·T37-13이 원장 등록 시 강제) — 과소 집계(그룹이
# 집계 전에 return, untallied_groups 로 그룹 ID 까지 지목됨)와 달리 과대 집계(한 그룹이
# finish_group 을 두 번 불러 +2 인 경우, register_and_run_tests 주석 참고)는 이 총합
# 불일치만 보고할 뿐 원인 그룹을 지목하지 못한다.
print_test_summary() {
  echo ""
  echo "=========================================="
  echo "테스트 결과"
  echo "=========================================="
  echo "총 테스트: $total_tests"
  echo -e "통과: ${GREEN}$passed_tests${NC}"
  echo -e "실패: ${RED}$failed_tests${NC}"
  # K6 가 증분이었는지 전체였는지를 로그 꼬리만 봐도 알게 한다(T37 이 돌지 않은 실행에서는 빈 값).
  if [[ -n "$K6_SUMMARY_LINE" ]]; then
    echo "$K6_SUMMARY_LINE"
  fi

  local suite_ok=1
  if ((passed_tests + failed_tests != total_tests)); then
    suite_ok=0
    echo ""
    log_error "총합 불일치: 통과($passed_tests) + 실패($failed_tests) != 총 테스트($total_tests)"
    if ((${#untallied_groups[@]} > 0)); then
      log_error "집계에 도달하지 못한 그룹: ${untallied_groups[*]}"
    fi
  fi

  if [[ $failed_tests -gt 0 ]]; then
    suite_ok=0
    echo ""
    echo "실패한 테스트:"
    for failure in "${failed_list[@]}"; do
      echo "  - $failure"
    done
    echo ""
  fi

  SUMMARY_PRINTED=1

  if ((suite_ok == 0)); then
    return 1
  fi

  echo ""
  log_ok "모든 테스트 통과"
  return 0
}

# ============================================================================
# 메인 러너
# ============================================================================

main() {
  # --list/--only 파싱을 배너보다 먼저 한다 — --list 는 기계(§10-2 의 향후 원장 완비
  # 검사)가 소비할 열거이므로 배너 없이 바로 출력하고 끝난다(항목5).
  parse_suite_arguments "$@"

  echo ""
  echo "=========================================="
  echo "coding-harness install.sh 테스트 스위트"
  echo "=========================================="
  echo ""

  # install.sh 존재 확인
  if [[ ! -f "$INSTALL_SCRIPT" ]]; then
    log_error "install.sh 미존재: $INSTALL_SCRIPT"
    exit 1
  fi

  # 레지스트리 파리티 사전 점검(항목2) — 위반 시 exit 1, 그룹을 하나도 실행하지 않는다.
  verify_group_registry_parity

  # 트랩 위생 사전 점검(K3, S2) — 위반 시 exit 1, 그룹을 하나도 실행하지 않는다. install.sh
  # 존재 확인·레지스트리 파리티와 같은 자리(그룹 실행 전 정적 불변식)에 둔다.
  verify_trap_hygiene

  # 원장 헤더 인용 대조 사전 점검(PRP §19-5 최우선 항목) — 위 두 사전 점검과 같은 자리·같은
  # 처방(위반 시 exit 1, 그룹을 하나도 실행하지 않는다). 그 함수 주석이 이 자리를 고른
  # 이유(GOTCHA 7 회피 포함)와, 그 자리가 기계로 고정돼 있지 않다는 한계를 함께 적는다.
  verify_ledger_header_citations

  log_info "레포 루트: $REPO_ROOT"
  log_info "install.sh: $INSTALL_SCRIPT"
  echo ""

  # 전체 테스트 개수 — 리터럴 34 제거(항목1). SELECTED_GROUPS 는 parse_suite_arguments 가
  # 채운다(기본: TEST_GROUPS 전체, --only 지정 시 부분집합) — 선택 실행에서도 총합 계약이
  # 유지되도록 선택된 개수로 산출한다(항목5).
  total_tests=${#SELECTED_GROUPS[@]}

  # 각 테스트 실행
  TEST_EXECUTION_STARTED=1
  register_and_run_tests

  # 결과 출력
  print_test_summary
}

# 파싱이 파일 끝까지 도달했음을 표시한다(위 SCRIPT_FULLY_PARSED 문단). main 호출 **직전**
# 이어야 한다 — 뒤에 두면 정상적인 테스트 실패마다 트랩이 "파싱이 완주하지 못함"으로
# 오진한다: main 안의 사전 점검들은 직접 exit 1 을 부르고, 테스트가 하나라도 실패하면
# print_test_summary 가 1 을 반환해 set -e 가 `main "$@"` 에서 스크립트를 끊으므로 그
# 뒤의 줄에 도달하지 못한다. 정상 종료 경로는 그렇지 않다 — main 은 exit 를 부르지 않고
# return 하므로 `main "$@"` 뒤의 줄에 실제로 도달한다(사본 끝에 표식 출력을 붙여 두
# 경로를 각각 재현했다: 통과 실행은 표식이 찍히고, 주입한 실패 1건이 있는 실행은 rc 1 로
# 끊겨 표식이 찍히지 않았다).
SCRIPT_FULLY_PARSED=1

main "$@"
